window.__TCM_DATA__ = {"site":{"site":{"mark":"岐黃","name":"岐黄翰墨","subtitle":"中华医药传统知识库","description":"汇集中医基础理论、{classics}部传世典籍、{herbs}味常用中药、{formulas}首经典方剂、针灸经络、食疗养生、{solar}节气与{constitution}种体质辨识，以及{diseases}个常见病种的辨证论治与调护方案。","author":"岐黄翰墨编辑组","keywords":["中医药","中医基础理论","中医经典","中药功效","方剂","针灸经络","食疗养生","二十四节气","体质辨识"],"repo":"","startYear":2026},"nav":[{"key":"home","title":"首页","href":"index.html","icon":"fa fa-home"},{"key":"theory","title":"理论基础","href":"theory.html","icon":"fa fa-book"},{"key":"classics","title":"经典医籍","href":"classics.html","icon":"fa fa-scroll"},{"key":"herbs","title":"本草图鉴","href":"herbs.html","icon":"fa fa-leaf"},{"key":"formulas","title":"方剂大成","href":"formulas.html","icon":"fa fa-flask"},{"key":"acupuncture","title":"针灸经络","href":"acupuncture.html","icon":"fa fa-mountain"},{"key":"diet","title":"养生食疗","href":"diet.html","icon":"fa fa-mortar-pestle"},{"key":"solar","title":"节气养生","href":"solar.html","icon":"fa fa-sun"},{"key":"constitution","title":"体质辨识","href":"constitution.html","icon":"fa fa-id-card"},{"key":"diseases","title":"疾病调理","href":"diseases.html","icon":"fa fa-heartbeat"},{"key":"about","title":"关于本站","href":"about.html","icon":"fa fa-info-circle"}],"sidebar":{"intro":"本站以《黄帝内经》《伤寒论》《本草纲目》等传世典籍为源，整理中医药基础理论、药物方剂、针灸经络与养生调护知识，供学习与查阅参考。","stat":[{"label":"典籍","value":"19","board":"classics"},{"label":"药材","value":"60","board":"herbs"},{"label":"方剂","value":"36","board":"formulas"},{"label":"病种","value":"28","board":"diseases"},{"label":"节气","value":"24","board":"solar"},{"label":"体质","value":"9","board":"constitution"}],"topics":[{"title":"基础与典籍","items":[{"title":"中医基础理论","href":"theory.html","count":"11 章","board":"theory"},{"title":"经典医籍","href":"classics.html","count":"19 部","board":"classics"},{"title":"针灸经络","href":"acupuncture.html","count":"8 章","board":"acupuncture"}]},{"title":"药物与方剂","items":[{"title":"本草图鉴","href":"herbs.html","count":"60 味","board":"herbs"},{"title":"方剂大成","href":"formulas.html","count":"36 首","board":"formulas"}]},{"title":"养生与临床","items":[{"title":"养生食疗","href":"diet.html","count":"36 道","board":"diet"},{"title":"二十四节气","href":"solar.html","count":"24 节","board":"solar"},{"title":"九种体质","href":"constitution.html","count":"9 种","board":"constitution"},{"title":"常见病调理","href":"diseases.html","count":"28 病","board":"diseases"}]}],"links":[{"title":"国家中医药管理局","href":"http://www.natcm.gov.cn/","external":true,"icon":"fa fa-link"},{"title":"中国哲学书电子化计划","href":"https://ctext.org/zh","external":true,"icon":"fa fa-link"},{"title":"中国知网","href":"https://www.cnki.net/","external":true,"icon":"fa fa-link"}]},"footer":{"note":"免责声明：本站内容整理自中医经典文献与公开教材资料，仅供传统医学知识学习与文化传承参考，不构成任何医疗诊断或治疗建议。药物剂量、针灸操作与食疗方案均须由执业医师结合个体情况辨证确定；身体不适请及时就医，切勿自行用药。","links":[{"title":"中医基础理论","href":"theory.html"},{"title":"经典医籍","href":"classics.html"},{"title":"本草图鉴","href":"herbs.html"},{"title":"方剂大成","href":"formulas.html"},{"title":"针灸经络","href":"acupuncture.html"},{"title":"养生食疗","href":"diet.html"},{"title":"节气养生","href":"solar.html"},{"title":"体质辨识","href":"constitution.html"},{"title":"疾病调理","href":"diseases.html"},{"title":"关于本站","href":"about.html"}]},"disclaimer":"本站内容仅供传统医学知识学习参考，不构成诊疗建议。","stats":{"theory":{"unit":"章"},"classics":{"unit":"部"},"herbs":{"unit":"味"},"formulas":{"unit":"首"},"acupuncture":{"unit":"章"},"diet":{"unit":"道"},"solar":{"unit":"节"},"constitution":{"unit":"种","count":9},"diseases":{"unit":"病"}},"modules":{"theory":"阴阳五行、藏象、气血津液、经络、病因病机与辨证论治","classics":"{count}部传世典籍：《黄帝内经》《伤寒论》《本草纲目》等","herbs":"{count}味常用中药的性味归经、功效主治、配伍与使用注意","formulas":"{count}首经典方剂的组成、方义、加减化裁与临床应用","acupuncture":"十二经脉、奇经八脉、腧穴主治与针刺灸法操作","diet":"药膳食谱、食材宜忌与按体质、按季节的调养方案","solar":"{count}节气气候物候、起居饮食、导引保健与易发疾病","constitution":"{count}种中医体质的形神特征、易病倾向与调养方案","diseases":"{count}个常见病种的辨证分型、方药、外治与调护"}},"theory":{"page":{"key":"theory","title":"中医基础理论","subtitle":"阴阳·五行·藏象·气血·经络·辨证·治则","description":"中医基础理论系统阐述阴阳五行、藏象经络、气血津液、病因病机、四诊八纲与治则治法，是研习中医药学的入门根基与临床枢机。","lead":"本门以《黄帝内经》《难经》为本，兼采后世诸家之说，系统介绍中医的哲学框架、脏腑经络、气血津液、病因病机、诊察方法与治疗原则。所述内容以经典原文为据，术语表述遵循现行教材规范，供学习参考，不能替代医师面诊。","type":"section","icon":"fa fa-book","sections":[{"id":"yinyang","title":"阴阳学说","subtitle":"对立制约 · 互根互用 · 消长平衡 · 相互转化","icon":"☯","summary":"阴阳是对事物对立双方属性的概括，是中医认识生命活动、把握病理变化的总纲，“阴平阳秘”则是判断机体是否健康的根本尺度。","badge":"核心","blocks":[{"type":"paragraph","text":"阴阳是中国古代哲学中最基本的一对范畴，也是中医理论体系的思想基础。《素问·阴阳应象大论》开篇即言：「阴阳者，天地之道也，万物之纲纪，变化之父母，生杀之本始，神明之府也。」中医学以阴阳之理统摄天地万物与人体生命，认为人体是阴阳双方相互对立、互根互用、消长转化并相对平衡的动态整体；一旦这种平衡被打破，便会产生疾病。因此《素问·生气通天论》提出「阴平阳秘，精神乃治；阴阳离决，精气乃绝」，把阴阳协调与否视为健康与疾病的总判据。"},{"type":"heading","level":3,"text":"一、阴阳的基本概念与属性划分"},{"type":"paragraph","text":"阴阳既是相互对立的两类事物或现象的概括，也可代表同一事物内部相互对立的两个方面。其属性划分具有普遍性、相对性与可分性三特点：凡运动、外向、上升、温热、兴奋、亢进、无形、功能占优势者属阳，凡静止、内守、下降、寒冷、抑制、衰退、有形、物质占优势者属阴。同一事物在不同条件下属性可变，如昼为阳、夜为阴，而上午与下午相比，前者阳气渐盛、后者阳气渐衰，故阴阳之中复有阴阳，可无限可分。临床上，以此为工具可以概括药物的寒热属性、脏腑的表里层次、脉象的浮沉迟数，构成整个辨证体系的语言基础。"},{"type":"table","caption":"阴阳属性划分对照表","head":["对比维度","阳的属性","阴的属性"],"rows":[["性质","温热、光明","寒冷、晦暗"],["运动趋势","上升、外向、躁动","下降、内守、静止"],["功能与物质","功能活跃、化气","物质凝聚、成形"],["时间","昼、春、夏","夜、秋、冬"],["空间部位","表、上、外、背","里、下、内、腹"],["药物属性","辛甘温热、升浮","酸苦咸寒凉、沉降"],["脉象","浮、数、洪、滑、动","沉、迟、细、涩、弱"]]},{"type":"heading","level":3,"text":"二、阴阳的四种基本关系"},{"type":"paragraph","text":"阴阳关系不是静止的、割裂的两个概念，而是相互渗透、动态联系的整体属性。具体表现为四个方面：其一是**对立制约**，阴阳双方相互限制、彼此制约，如寒能制热、燥能胜湿，同一脏腑中气主升、肺主降，一升一降方能完成水谷纳运；其二是**互根互用**，阴阳互为存在前提，“阴根于阳、阳根于阴”，气为血之帅、血为气之母，气虚可致血虚、血虚亦可致气脱；其三是**消长平衡**，阴阳随自然界四时与人体活动此消彼长，如春生夏长、秋收冬藏，若消长超过正常范围即为偏盛偏衰；其四是**相互转化**，阴阳在一定条件下可以向对立面转化，如寒极生热、热极生寒，重阴必阳、重阳必阴。"},{"type":"table","caption":"阴阳四种基本关系与临床意义","head":["基本关系","含义","临床意义"],"rows":[["对立制约","双方相互限制、削弱对方","寒者热之、热者寒之；实则泻之、虚则补之"],["互根互用","互为前提、互相资助","气虚补气以生血，血虚补血以生气；阴中求阳、阳中求阴"],["消长平衡","此消彼长、动态持平","春生夏长为正常消长；消长失衡即阴阳偏盛偏衰"],["相互转化","在一定条件下变为对方","寒极生热、热极生寒；重阴必阳、重阳必阴"]]},{"type":"cards","columns":2,"items":[{"icon":"⚖","title":"对立制约","text":"阴阳相互限制而保持动态平衡，是“以寒治热、以热治寒”的辨证基础。","bullets":["寒者热之，热者寒之","实则泻之，虚则补之","升降相因，出入相召"]},{"icon":"🔗","title":"互根互用","text":"阴阳互为存在前提，一方虚损必然累及另一方。","bullets":["气为血之帅，血为气之母","精气互生，阴阳互济","阴中求阳，阳中求阴"]},{"icon":"🌗","title":"消长平衡","text":"阴阳随时序此消彼长，消长适度则生理，失衡则病理。","bullets":["阳长阴消谓生长","阴长阳消谓收藏","消长失衡即偏盛偏衰"]},{"icon":"🔄","title":"相互转化","text":"阴阳在一定条件下向对立面转化，提示病情的转折。","bullets":["寒极生热，热极生寒","重阴必阳，重阳必阴","注意向愈与向恶的转折"]}]},{"type":"heading","level":3,"text":"三、阴阳失调：偏盛、偏衰与格拒"},{"type":"paragraph","text":"阴阳失调是疾病发生发展的内在根据，可归纳为偏盛与偏衰两大类。**偏盛**即阴或阳一方有余而另一方相对不足，属“邪气盛则实”：阳盛则热，阴盛则寒；阳盛则阴病，阴盛则阳病，《素问·阴阳应象大论》所谓“阳胜则热，阴胜则寒。重寒则热，重热则寒”。**偏衰**即一方虚损而另一方相对偏亢，属“精气夺则虚”：阳虚则寒，阴虚则热。阳虚不能制阴而见畏寒肢冷、便溏清稀；阴虚不能制阳而见午后潮热、颧红盗汗。二者常互相影响，因虚致实、实致虚，形成虚实夹杂。此外尚有阴阳格拒与阴阳亡失：格拒为邪盛格拒于外，出现真寒假热或真热假寒；亡失为阴液或阳气暴脱，属危候。"},{"type":"table","caption":"阴阳偏盛偏衰证候鉴别","head":["类型","病机","主要表现","治法要点"],"rows":[["阳盛","阳邪偏盛，阴液未亏","壮热、面赤、烦躁、口渴喜冷、脉数有力","寒凉清热，直折其有余"],["阴盛","阴寒内盛，阳气未衰","恶寒、肢冷、面白、蜷卧、脉迟有力","辛热散寒，祛其有余"],["阳虚","阳气不足，阴相对偏盛","畏寒喜暖、肢冷便溏、脉沉迟无力","温补阳气，扶阳抑阴"],["阴虚","阴液不足，阳相对偏亢","午后潮热、盗汗、颧红、舌红少苔、脉细数","滋阴增液，壮水制火"],["阴阳格拒","一方盛极而格拒于外","真寒假热（面红身热而欲覆被）或真热假寒","反治法，热因寒用、寒因热用"],["阴阳亡失","阴液或阳气暴脱","亡阳见冷汗肢厥，亡阴见汗热如油","急回阳救逆或救阴固脱"]]},{"type":"paragraph","text":"临床辨阴阳须注意几个要点：其一，先辨其真伪，勿被假象所惑；其二，辨阴阳当结合病因、病位、病性，不可仅凭单一症状；其三，阴阳是八纲的总纲，表里寒热虚实最终皆可归属阴阳，故有“阴病治阳、阳病治阴”以及“壮水之主，以制阳光；益火之源，以消阴翳”的具体治法。调理阴阳的根本目的在于“以平为期”，即恢复阴平阳秘的相对平衡，而非一味攻伐。"},{"type":"quote","text":"阴阳者，天地之道也，万物之纲纪，变化之父母，生杀之本始，神明之府也。治病必求于本。故积阳为天，积阴为地。阴静阳燥；阳生阴长；阳杀阴藏；阳化气，阴成形。","source":"《黄帝内经·素问·阴阳应象大论》"},{"type":"quote","text":"凡阴阳之要，阳密乃固，两者不和，若春无秋，若冬无夏。因而和之，是谓圣度。故阳强不能密，阴气乃绝。阴平阳秘，精神乃治；阴阳离决，精气乃绝。","source":"《黄帝内经·素问·生气通天论》"},{"type":"keypoints","title":"掌握要点","items":["阴阳是中医解释生命活动与病理变化的总纲，具有普遍性、相对性、可分性三大特点。","阴阳四大关系：对立制约、互根互用、消长平衡、相互转化，须结合临床综合运用。","阴阳失调分偏盛（阳盛、阴盛）与偏衰（阳虚、阴虚），并可见格拒、亡失等危候。","诊断以“阴平阳秘”为健康标准，治疗以“以平为期”为最终目的。"]},{"type":"paragraph","text":"阴阳学说与五行学说相互补充：阴阳揭示事物的普遍对立属性，五行则把这种对立进一步细分为五类具体的系统联系。二者合参，构成中医“阴阳五脏一体”的两大理论支柱，也是理解藏象、经络、气血乃至辨证论治的钥匙。"}]},{"id":"wuxing","title":"五行学说","subtitle":"五行特性 · 生克制化 · 乘侮 · 母子相及","icon":"❖","summary":"五行以木火土金水五类属性概括自然界与人体的一切联系，通过生克制化维持动态平衡，是脏腑分类与虚实补泻的重要依据。","badge":"核心","blocks":[{"type":"paragraph","text":"五行学说源于《尚书·洪范》“五行：一曰水，二曰火，三曰木，四曰金，五曰土”，是对自然界五类基本物质及其相互关系的朴素概括。中医学将自然界五类属性推演至人体，形成以五脏为中心的藏象体系，用以说明五脏之间的生克制化关系、五脏与体窍志液season的对应关系，以及病变的传变规律和治疗的补泻原则。《四圣心源·天人解·五行生克》指出：“五行之理，有生有克。木生火，火生土，土生金，金生水，水生木。木克土，土克水，水克火，火克金，金克木。”五行的生克既是自然的客观规律，也是中医认识脏腑关系、指导治疗的出发点。"},{"type":"heading","level":3,"text":"一、五行的基本特性"},{"type":"paragraph","text":"《尚书·洪范》与《左传》所述五行特性，后世归纳为十一个字，即木曰曲直、火曰炎上、土爰稼穑、金曰从革、水曰润下。**木曰曲直**：木性生长、升发、条达舒畅，对应肝之疏泄升发与筋之屈伸；**火曰炎上**：火性温热、升腾向上，对应心之阳气与血脉运行；**土爰稼穑**：土性承载、生化万物，为万物之母，对应脾之运化；**金曰从革**：金性清肃、收敛、变革，对应肺之宣降与大肠传导；**水曰润下**：水性润泽、向下流泻，对应肾之藏精、主水。五行特性既是分类的尺度，也直接对应五脏的生理功能特点。"},{"type":"table","caption":"五行特性与五脏功能对应","head":["五行","特性","对应脏","生理特点","主要病机"],"rows":[["木","曲直：生长升发、条达舒畅","肝","主疏泄、主藏血，体阴用阳","肝气郁结、肝阳上亢、肝风内动"],["火","炎上：温热升腾、化气","心","主血脉、藏神，为阳脏而主通明","心火亢盛、心血不足、心神不宁"],["土","稼穑：承载生化、滋养万物","脾","主运化、升清、统血，为后天之本","脾气虚、脾阳虚、脾不统血"],["金","从革：清肃收敛、条理变革","肺","主气司呼吸、朝百脉、通调水道","肺气虚、风寒犯肺、燥邪伤肺"],["水","润下：滋润濡养、向下流泻","肾","藏精、主水、纳气，为先天之本","肾精亏虚、肾阳虚衰、肾阴不足"]]},{"type":"heading","level":3,"text":"二、生克制化与乘侮母子相及"},{"type":"paragraph","text":"**相生**指五行之间依次滋助促进的次序为：木生火、火生土、土生金、金生水、水生木。相生关系传递的是脏腑间的滋养，如肾水涵木以养肝，脾土运化以充肺。**相克**指五行之间相互制约、抑制其太过，顺序为：木克土、土克水、水克火、火克金、金克木。相克保证各脏功能不过亢，如肝木疏泄脾土，脾土运化以防肾水泛滥，肺金肃降以制心火。五行生克同时存在且保持适度，才构成“生中有制、制中有生”的动态平衡。"},{"type":"paragraph","text":"当生克关系超出正常范围，即出现异常传变。**相乘**是克伐太过，与“顺”相反，如木气过旺乘土，见肝脾不和、胁胀纳呆、腹痛便泻；土虚木乘则见中焦虚弱而肝气横逆。**相侮**是反向克制，如“反侮”，木本克土而反被土侮，或火本克金而反侮金，多因一方虚弱无力制约对方所致。**母子相及**包括“母病及子”（如肾水亏虚不能涵木，致肝阴不足、肝阳上亢）与“子病犯母”（如肝火炽盛耗伤肾阴，致肝肾阴虚）。临床治疗即依此确立“虚则补其母、实则泻其子”的原则，如肝肾阴虚用滋水涵木法，肺肾阴虚用金水相生法。"},{"type":"table","caption":"五行异常传变类型","head":["类型","含义","形成原因","典型表现"],"rows":[["相乘","克伐太过，顺克关系被破坏","一方亢盛或另一方虚弱","木乘土：胁胀腹痛、肠鸣泄泻"],["相侮","反向克制，反克关系出现","受克一方虚弱无力","土侮木：脾虚肝郁；火侮金：心火灼肺"],["母病及子","母脏先病累及子脏","母脏虚损，子脏失养","肾阴亏虚致肝阴不足、眩晕耳鸣"],["子病犯母","子脏先病反过来伤母脏","子脏亢盛耗伤母脏","肝火炽盛耗伤肾阴，潮热盗汗"],["母子俱虚","母子两脏同时亏虚","久病失治或素体俱亏","脾肾阳虚，完谷不化、五更泄泻"]]},{"type":"cards","columns":3,"items":[{"icon":"🌱","title":"相生","text":"木生火、火生土、土生金、金生水、水生木，五脏之间互资互养。","bullets":["肾水涵木","脾土生肺金","肝木生心火"]},{"icon":"⚔","title":"相克","text":"木克土、土克水、水克火、火克金、金克木，制约太过以保平衡。","bullets":["肝木疏脾土","肺金制心火","脾土制肾水"]},{"icon":"⚠","title":"乘侮相及","text":"生克关系失调所致的异常传变，是解释复杂病势的关键。","bullets":["相乘：克伐太过","相侮：反向克制","母病及子与子病犯母"]}]},{"type":"heading","level":3,"text":"三、五脏、五色、五味、五季与虚实补泻"},{"type":"paragraph","text":"五行在人体内形成多层对应体系。《素问·阴阳应象大论》详述五方五脏对应：东方生风，风生木，木生酸，酸生肝；南方生热，热生火，火生苦，苦生心；中央生湿，湿生土，土生甘，甘生脾；西方生燥，燥生金，金生辛，辛生肺；北方生寒，寒生水，水生咸，咸生肾。并以五色（青赤黄白黑）、五音（角徵宫商羽）、五声（呼笑歌哭呻）、五志（怒喜思忧恐）、五体（筋脉肉皮骨）、五窍（目舌口鼻耳）、五液（泪汗涎涕唾）归属于五脏，形成完整的藏象体系。《素问·宣明五气》概括为“五味所入：酸入肝，辛入肺，苦入心，咸入肾，甘入脾”，说明五味与五脏的亲和性。"},{"type":"paragraph","text":"五行学说直接指导临床的**虚实补泻**。运用“虚则补其母、实则泻其子”的法则：肝肾阴虚者补肾水以滋肝木，称滋水涵木；肺肾阴虚者补肾水以润肺金；心肝血虚者补肝血以养心血。若肝火亢盛属实，则泻其子以清肝火，肝火得泻而心火自降；若脾虚湿盛，则健脾以实脾土，此谓“培土生金”。此外尚有“抑强扶弱”之法，即所胜之脏太过则抑制其所胜，脾虚肝旺者抑肝扶脾。所谓“见肝之病，知肝传脾，当先实脾”，正是五行相生传变思想在治疗中的直接体现。"},{"type":"table","caption":"五行与人体多要素对应总表","head":["五行","方位","五脏","五色","五味","五季","五志"],"rows":[["木","东","肝","青","酸","春","怒"],["火","南","心","赤","苦","夏","喜"],["土","中","脾","黄","甘","长夏","思"],["金","西","肺","白","辛","秋","忧"],["水","北","肾","黑","咸","冬","恐"]]},{"type":"table","caption":"五行生克对应的临床治疗法则","head":["治法","五行原理","适用证候","代表方药思路"],"rows":[["滋水涵木","水生木，补母治子虚","肝肾阴虚、肝阳上亢","六味地黄丸类，滋养肾阴以潜肝阳"],["金水相生","水生金，肺肾阴虚","肺肾阴虚、干咳少痰","百合固金汤类"],["培土生金","土生金，脾肺气虚","脾肺气虚、久咳食少","四君子汤合参苓白术散类"],["抑木扶土","木克土过旺乘脾","肝旺脾虚、痛泻要方证","抑肝健脾，痛泻要方类"],["培土制水","土克水，脾虚水肿","脾虚水湿泛滥","实脾饮类，温运脾阳以利水"],["泻南补北","水火不济、心肾不交","心肾不交、失眠健忘","交泰丸类，滋肾清心"]]},{"type":"quote","text":"五行之理，有生有克。木生火，火生土，土生金，金生水，水生木。木克土，土克水，水克火，火克金，金克木。其相生相克，皆以气而不以质也，成质则不能生克矣。","source":"《四圣心源·卷一·天人解·五行生克》"},{"type":"keypoints","title":"掌握要点","items":["五行特性：木曰曲直、火曰炎上、土爰稼穑、金曰从革、水曰润下。","相生为滋助，相克为制约，生中有制方能维持动态平衡。","五行异常传变包括相乘、相侮、母病及子、子病犯母四种。","治疗上运用“虚则补其母、实则泻其子”，并结合抑强扶弱之法。"]},{"type":"paragraph","text":"五行学说与阴阳学说一样，是中医认识生命与疾病的两大工具。五行偏重于说明事物之间的具体联系与传变路径，阴阳偏重于说明属性对立与消长转化。二者合参，才能既把握总体病性，又追踪病变走向，为“审证求因、治病求本”提供完整的理论支撑。"}]},{"id":"zangxiang","title":"藏象学说","subtitle":"五脏 · 六腑 · 奇恒之腑 · 脏腑表里","icon":"🫀","summary":"藏象学说以五脏为中心，把人体形态结构、生理功能与精神活动统摄为五大系统，“藏象”二字体现了以脏为体、以象为用的认识特点。","badge":"核心","blocks":[{"type":"paragraph","text":"藏象学说形成于《黄帝内经》，是对人体形态结构、生理功能、物质代谢与精神活动规律的概括。所谓“藏象”，“藏”指内在的精气脏腑，“象”指其外在表现与功能征象，即通过外在征象来认识内在脏腑。《素问·六节藏象论》以“心者，生之本，神之变也，其华在面，其充在血脉，为阳中之太阳，通于夏气”为范式，将每一脏的功能、精华所注、体表部位、阴阳属性与四时之气一并论定，形成以五脏为核心的藏象体系。"},{"type":"heading","level":3,"text":"一、五脏的主要生理功能"},{"type":"paragraph","text":"**心**为君主之官，主血脉而藏神。心主血脉指心气推动和调控血液在脉中运行，流注全身，发挥营养与滋润作用，是血液循环的动力；心藏神指心主宰人的精神、意识、思维活动，《灵枢·本神》所谓“所以任物者谓之心”。**肺**为相傅之官，主气司呼吸，朝百脉而通调水道：肺吸入清气与脾胃运化的水谷精气结合而成宗气，宗气助心行血；肺朝百脉，指全身血脉会聚于肺经，通过呼吸进行清浊之气的交换；肺主通调水道，指肺气的宣发肃降对体内水液输布运行与排泄起疏通调节作用。**脾**为仓廪之官，主运化、升清、统血：运化指将水谷化为精微并输布全身，升清指将水谷精微上输心肺、化生气血，统血指脾气的固摄统摄使血液循行脉中而不逸出。**肝**为将军之官，主疏泄而藏血：疏泄指调畅全身气机、促进脾胃升降与情志舒畅，藏血指贮藏血液、调节血量并防止出血。**肾**为先天之本，藏精、主水、纳气：藏精包括先天之精与后天之精，是人体生长生殖与脏腑功能的物质基础；主水指肾的气化作用对全身水液输布排泄起调节作用；纳气指肾摄纳肺所吸入的清气以维持呼吸深度。"},{"type":"table","caption":"五脏功能要点对照","head":["脏","主要功能","核心机制","主要生理表现","功能失常常见表现"],"rows":[["心","主血脉、藏神","心气推动血液运行，神明统摄精神活动","面有血色、意识清晰、脉搏有力","心悸怔忡、失眠多梦、面色淡白或红赤"],["肺","主气司呼吸、朝百脉、通调水道","肺气宣发肃降，呼吸与气体交换","呼吸均匀、声音洪亮、皮肤润泽","气短声低、咳嗽喘息、皮肤干燥"],["脾","主运化、升清、统血","脾气转输水谷精微并统摄血液","食欲旺盛、便形正常、肌肉充实","食少腹胀、便溏出血、形体消瘦或浮肿"],["肝","主疏泄、藏血","肝气升发疏泄，肝血贮藏调节","筋柔软有力、情志舒畅、两目灵活","胁胀易怒、筋挛肢麻、目视昏花"],["肾","藏精、主水、纳气","肾精充盈、肾气蒸化摄纳","齿坚发乌、听力灵敏、呼吸均匀","腰膝酸软、遗精、水肿、呼多吸少"]]},{"type":"cards","columns":2,"items":[{"icon":"❤️","title":"心：君主之官","text":"心主血脉藏神，为五脏之大主，精神情志活动总归其司。","bullets":["心气推动血行","心主神明，神藏于心","其华在面，其充在血脉"]},{"icon":"🫁","title":"肺：相傅之官","text":"肺主气司呼吸，朝百脉而通调水道，为百脉之朝会。","bullets":["宣发肃降调畅气机","呼吸吐故纳新","通调水道为水之上源"]},{"icon":"🍚","title":"脾：仓廪之官","text":"脾主运化升清而统血，为气血生化之源、后天之本。","bullets":["运化水谷化生气血","升清输精上达心肺","统血摄血循行脉中"]},{"icon":"🌿","title":"肝：将军之官","text":"肝主疏泄以调畅全身气机，藏血以贮藏和调节血量。","bullets":["疏泄气机助脾胃升降","藏血调节血量防出血","体阴用阳，喜条达而恶抑郁"]},{"icon":"💧","title":"肾：先天之本","text":"肾藏精、主水、纳气，为人体生殖发育与水液代谢的动力根本。","bullets":["藏先天之精与后天之精","主水液输布与排泄","纳气以维持呼吸深度"]}]},{"type":"heading","level":3,"text":"二、六腑与奇恒之腑"},{"type":"paragraph","text":"六腑即胆、胃、小肠、大肠、膀胱、三焦，功能特点为“传化物而不藏，实而不能满”。《素问·五藏别论》谓“夫胃、大肠、小肠、三焦、膀胱，此五者，天气之所生也，其气象天，故泻而不藏，此受五脏浊气，名曰传化之腑，此不能久留输泻者也”。胃主受纳腐熟水谷，为水谷之海；小肠主受盛化物、泌别清浊；大肠主传道糟粕；膀胱贮尿排尿；胆贮藏排泄胆汁以助消化并主决断；三焦为元气之别使，主司全身气机与水液通化。此外有奇恒之腑，即脑、髓、骨、脉、胆、女子胞，其形态中空似腑，功能似脏，能贮藏精气而不泻，故称奇恒之腑。"},{"type":"table","caption":"六腑功能与受盛传化特点","head":["腑","功能定位","生理特点","受邪或失常表现"],"rows":[["胆","贮藏排泄胆汁，主决断","贮而不泻，藏精气而不泻","胆怯易惊、失眠、口苦、胁痛"],["胃","受纳腐熟水谷，主通降","以降为和，喜润恶燥","胃脘胀痛、呕吐、嗳气、牙龈肿痛"],["小肠","受盛化物，泌别清浊","化物而不藏","小便异常、腹泻、脐腹胀痛"],["大肠","传化糟粕，主津","传导糟粕，吸收部分水液","便秘、泄泻、便血、肛门灼热"],["膀胱","贮尿与排尿","气化则能出","癃闭、遗尿、尿频、尿急、尿痛"],["三焦","通行元气与水液，总司全身气化","有名而无形，主司诸气、通调水道","水肿、脘腹胀满、耳鸣、疟疾"]]},{"type":"heading","level":3,"text":"三、脏腑之间的表里配合关系"},{"type":"paragraph","text":"脏与腑之间存在固定的表里配对：一脏一腑，阴阳相应，气的升降相因。《难经·论脏腑·三十五难》明示“小肠者，心之腑；大肠者，肺之腑；胆者，肝之腑；胃者，脾之腑；膀胱者，肾之腑”。《素问·血气形志》则从手足配属角度归纳“足太阳与少阴为表里，少阳与厥阴为表里，阳明与太阴为表里”。表里关系具有三方面意义：一是生理上相互资助，如脾气运化水谷以养心，肺气宣降以助大肠传导；二是病理上相互影响，如肝火犯胃致胃失和降，脾虚失运致大肠传导无力；三是治疗上可表里同治，如肺气壅滞兼大肠腑实者可用宣肺通腑之法。脏与腑的功能差异即“脏者藏精气而不泻，故满而不能实；六腑者，传化物而不藏，故实而不能满”，这一区别正是“藏象”与“腑象”分野的根据。"},{"type":"table","caption":"脏腑表里配对与病理联系","head":["脏","腑","表里经","生理协同","常见相互影响"],"rows":[["心","小肠","手少阴—手太阳","心血下行温养小肠，小肠泌别清浊上济于心","心火下移小肠致尿赤涩痛；小肠实热上扰心神致心烦失眠"],["肺","大肠","手太阴—手阳明","肺气肃降助大肠传导，大肠传导正常助肺气宣降","肺气壅滞致大肠腑实；大肠燥结致肺气不降而喘"],["脾","胃","足太阴—足阳明","脾升胃降相反相成，共同完成饮食物纳化","脾不运化致胃失和降；胃不受纳致脾气不运"],["肝","胆","足厥阴—足少阳","肝疏泄气机助胆汁排泄，胆汁助饮食消化","肝郁及胆致胁痛口苦；胆火上炎引动肝火"],["肾","膀胱","足少阴—足太阳","肾气蒸化助膀胱气化排尿，膀胱气化赖肾气温煦","肾气不固致遗尿；湿热下注致膀胱气化不利"]]},{"type":"quote","text":"心者，君主之官也，神明出焉。肺者，相傅之官，治节出焉。肝者，将军之官，谋虑出焉。胆者，中正之官，决断出焉。膻中者，臣使之官，喜乐出焉。脾胃者，仓廪之官，五味出焉。大肠者，传道之官，变化出焉。小肠者，受盛之官，化物出焉。肾者，作强之官，伎巧出焉。三焦者，决渎之官，水道出焉。膀胱者，州都之官，津液藏焉，气化则能出矣。","source":"《黄帝内经·素问·灵兰秘典论》"},{"type":"quote","text":"脑、髓、骨、脉、胆、女子胞，此六者，地气之所生也，皆脏于阴而象于地，故藏而不泻，名曰奇恒之腑。夫胃、大肠、小肠、三焦、膀胱，此五者，天气之所生也，其气象天，故泻而不藏，此受五脏浊气，名曰传化之腑。","source":"《黄帝内经·素问·五藏别论》"},{"type":"keypoints","title":"掌握要点","items":["五脏：心主血脉藏神，肺主气司呼吸朝百脉通调水道，脾主运化升清统血，肝主疏泄藏血，肾藏精主水纳气。","六腑功能特点为传化物而不藏、实而不能满；奇恒之腑形态似腑、功能似脏。","脏腑表里一一相配，生理上相互资助，病理上相互影响，治疗上可表里同治。","《灵兰秘典论》强调“主明则下安”，说明五脏协调是全身功能正常的前提。"]},{"type":"paragraph","text":"藏象学说与经络学说是同一理论体系的两翼：藏象论功能，经络论通道；藏象言脏腑之气如何运行，经络言其运行所循的线路。二者结合，才能既知“何脏何腑之气所病”，又明“病在何经何络”，为针灸、方药等治疗手段提供定位依据。"}]},{"id":"qixue","title":"气血津液","subtitle":"气 · 血 · 津液 · 三者关系","icon":"💧","summary":"气、血、津液是构成人体、维持生命活动的基本物质，皆由脾胃化生的水谷精微所化，彼此依存、相互为用。","badge":"核心","blocks":[{"type":"paragraph","text":"气、血、津液与精同属液态物质与能量范畴，是构成人体、维持生命活动的基本物质。《灵枢·决气》把这一系统分为精、气、津、液、血、脉六者，其中精为有形之精微物质，气为无形之功能活动，津液为流动性较大的水液，血为循行脉中的红色液体，脉为血运行的通道。六者同源异流：由脾胃化生的水谷精微是共同来源，由肾精化生、由脾胃运化的水谷精微是重要补充。"},{"type":"heading","level":3,"text":"一、气的生成、分类与功能"},{"type":"paragraph","text":"气的生成有三条来源：一是禀受于父母的先天之精气；二是从自然界吸入的清气；三是来源于饮食水谷、由脾胃化生的水谷精气。三者结合而成人体之气。按分布与功能，气的类别有四：**元气**根于肾，由先天之精化生并得后天水谷精气充养，通过三焦布散全身，是人体生命活动的原动力；**宗气**聚于胸中气海，由肺吸入的清气与脾胃化生的水谷精气结合而成，走息道以行呼吸，贯心脉以行气血；**营气**行于脉中，性质精纯柔和，由水谷精微中的精华部分所化，濡养脏腑并化生血液；**卫气**行于脉外，性质慓疾滑利，功能温养脏腑肌肤、护卫肌表、调控腠理开合与汗液排泄。"},{"type":"table","caption":"四气生成、分布与功能对照","head":["气的类别","生成来源","主要分布","主要功能"],"rows":[["元气","先天之精化生，后天水谷精气充养","根于肾，经三焦布散全身","推动和调控人体生长发育与脏腑功能，是生命活动原动力"],["宗气","肺吸入清气与脾胃化生水谷精气相结合","聚于胸中气海，贯心脉、走息道","行呼吸、助心行血、司全身气化"],["营气","水谷精微之精华部分","行于脉中，循脉上下，五十周而复始","化生血液、濡养脏腑、化生津液"],["卫气","水谷精微之慓悍滑利部分","行于脉外，昼行于阳、夜行于阴","温养脏腑肌肤、护卫肌表、调控腠理与汗液"]]},{"type":"cards","columns":2,"items":[{"icon":"🔆","title":"气的三大功能","text":"气的功能可概括为推动与调控、温煦与凉润、防御与固摄三方面。","bullets":["推动调控：促进生长、脏腑运动与血液运行","温煦凉润：维持体温恒定，濡润脏腑组织","防御固摄：护卫肌表，固摄血液津液不妄泄"]},{"icon":"🌀","title":"气的升降出入","text":"气的运动形式为升、降、出、入，贯穿脏腑经络与形体官窍。","bullets":["肺主宣降，肝主升发","脾升胃降，肾主纳气","气机失调即生升降出入失常之病"]}]},{"type":"heading","level":3,"text":"二、血的生成、运行与功能"},{"type":"paragraph","text":"血主要由营气与津液化生，《灵枢·营卫生会》说“中焦亦并胃中，出上焦之后，此所受气者，泌糟粕，蒸津液，化其精微，上注于肺脉，乃化而为血，以奉生身，莫贵于此”。血由心主、肺朝百脉、脾统摄、肝藏血共同完成生成与运行：心气推动血行，肺气助心行血并使血中清气与浊气分离，脾气统摄血循脉中，肝血贮藏并调节血量、防止出血。血的功能一是濡养滋润全身脏腑经络形体官窍；二是化神，《灵枢·本神》“血舍魂”，《灵枢·营卫生会》“血者，神气也”，说明血是神志活动的重要物质基础。"},{"type":"heading","level":3,"text":"三、津液代谢与气血津液的关系"},{"type":"paragraph","text":"津与液同属体液，区别在于性状、分布与功能：津性质清稀，流动性大，分布于皮肤、肌肉、孔窍，能渗注血脉，起滋润作用，并参与血液的组成；液性质较稠厚，流动性小，灌注于骨节、脏腑、脑、髓，起濡养作用。津液代谢依赖肺的宣降、脾的运化转输、肾的蒸腾气化与膀胱的贮尿排泄，同时三焦是津液运行的通道。津液不足则燥，津液停聚则成痰饮、水肿。"},{"type":"paragraph","text":"三者之间的关系密不可分。**气为血之帅**：气能生血、行血、摄血，气旺则血充、气虚则血少、气滞则血瘀、气虚亦可致气不摄血而出血；**血为气之母**：血能载气，气存于血中而运行不致散失，血虚则气无所依而气虚。**气与津液**：津液能载气，气能生津、行津、摄津，气虚则津液不固而多汗，气化不利则水湿停聚。**血与津液**：津液渗入脉中成为血液的组成成分，故大汗、吐泻时可因津液大量耗损而致血虚；血中津液渗出脉外则为汗，故血家不可再发汗。"},{"type":"table","caption":"气血津液关系与常见病理","head":["关系","生理作用","失常表现","治法提示"],"rows":[["气为血之帅","气能生血、行血、摄血","气虚血少、气滞血瘀、气不摄血而出血","补气以生血、行气以活血、益气以摄血"],["血为气之母","血能载气、养气","血虚气无所依而气虚，血脱气随","补血以养气，急救血脱则益气固脱"],["气与津液","气能生津、行津、摄津","气虚多汗、气化不利则水停","益气生津、化气行水"],["血与津液","津液化血，血渗为津","大汗吐泻后血燥生风","津血同源，兼以养阴增液"]]},{"type":"quote","text":"人受气于谷，谷入于胃，以传与肺，五脏六腑，皆以受气，其清者为营，浊者为卫，营在脉中，卫在脉外，营周不休，五十度而复大会，阴阳相贯，如环无端。","source":"《黄帝内经·灵枢·营卫生会》"},{"type":"quote","text":"营出于中焦，卫出于上焦。……中焦亦并胃中，出上焦之后，此所受气者，泌糟粕，蒸津液，化其精微，上注于肺脉，乃化而为血，以奉生身，莫贵于此，故独得行于经隧，命曰营气。……夫血之与气，异名同类。何谓也？岐伯答曰：营卫者，精气也。血者，神气也。故血之与气，异名同类焉。故夺血者无汗，夺汗者无血，故人生有两死而无两生。","source":"《黄帝内经·灵枢·营卫生会》"},{"type":"keypoints","title":"掌握要点","items":["气的生成：先天之精气 + 自然界清气 + 水谷精气；按功能分为元气、宗气、营气、卫气。","血由营气与津液化生，赖心主血脉、肺朝百脉、脾统血、肝藏血而运行正常。","津清稀而流动性大，液稠厚而灌注骨节脏腑，二者代谢依赖肺脾肾与三焦。","关系要点：气为血之帅、血为气之母；夺血者无汗，夺汗者无血。"]},{"type":"paragraph","text":"气血津液理论是理解临床多种病机的钥匙：气虚、气滞、气逆、气陷、气闭、气脱各有不同表现；血虚、血瘀、血热、血寒各成证候；津液不足则燥，津液停聚则为痰饮、水肿。治疗上“虚则补之、实则泻之”是总纲，而善用气血关系往往是提高疗效的关键，例如治血瘀常配补气之品以推动血行。"}]},{"id":"jingluo","title":"经络学说","subtitle":"十二经脉 · 奇经八脉 · 经络作用","icon":"🕸","summary":"经络是运行气血、联络脏腑的通路，十二经脉为主体、奇经八脉为补充，共同构成覆盖全身的调节网络。","badge":"核心","blocks":[{"type":"paragraph","text":"经络是经脉与络脉的总称。《灵枢·经脉》指出“经脉者，所以能决死生、处百病、调虚实，不可不通”。《难经·论经络·二十三难》进一步概括其功能为“经脉者，行血气，通阴阳，以荣于身者也”。经脉是运行气血的主要通道，多循行于深部；络脉是经脉的分支，多循行于浅部，沟通表里、联络脏腑。经络内属脏腑、外络肢节，把人体上下内外联成有机整体。"},{"type":"heading","level":3,"text":"一、十二经脉的走向、交接、分布与表里"},{"type":"paragraph","text":"十二经脉即手与足的阴经、阳经各六条，按“手太阴肺经—手阳明大肠经—足阳明胃经—足太阴脾经—手少阴心经—手太阳小肠经—足太阳膀胱经—足少阴肾经—手厥阴心包经—手少阳三焦经—足少阳胆经—足厥阴肝经”的次序流注，如环无端。其走向规律为：手三阴经从胸走手，手三阳经从手走头，足三阳经从头走足，足三阴经从足走腹胸。交接方式为：相表里的阴经与阳经在手足末端交接，同名的阳经与阴经在头面部交接，手足同名阳经在头面部交接，足三阴经与手三阴经在胸部交接。分布规律为：手足三阴经内侧为太阴、厥阴、少阴，阳经外侧为阳明、太阳、少阳；头面部分布亦有一定规律。"},{"type":"paragraph","text":"十二经脉内属脏腑，阴经属脏、阳经属腑，形成六对表里关系：《素问·血气形志》所谓“足太阳与少阴为表里，少阳与厥阴为表里，阳明与太阴为表里……手太阳与少阴为表里，少阳与心主为表里，阳明与太阴为表里”。《灵枢·经别》则记载十二经别循行深入体腔，加强了表里脏腑的联系。每条经脉还联络若干脏腑与官窍，形成固定的循行路线与主治范围，这正是“经脉所过，主治所及”的依据。"},{"type":"table","caption":"十二经脉循行与主治要点","head":["经脉","循行起止（概括）","所属脏腑","表里配合","主要主治提示"],"rows":[["手太阴肺经","起中焦，下络大肠，上膈属肺，从肺系出腋下至拇指","肺","与手阳明相表里","咳嗽、气喘、咯血、胸痛、咽喉肿痛"],["手阳明大肠经","起食指端，上行头面，下入缺盆属大肠","大肠","与手太阴相表里","齿痛、口疮、咽痛、腹泻、便秘"],["足阳明胃经","起鼻旁，下行至足，支脉起于胃下口","胃","与足太阴相表里","胃痛、呕吐、牙痛、口臭、狂躁"],["足太阴脾经","起足大趾，上行腹胸，支脉络胃注于心","脾","与足阳明相表里","腹胀、便溏、泄泻、纳呆、便血"],["手少阴心经","起心中，下膈络小肠，循手小指内侧","心","与手太阳相表里","心痛、心悸、失眠、咽干、腕臂痛"],["手太阳小肠经","起小指端，上行头项，络心属小肠","小肠","与手少阴相表里","肩背痛、耳鸣、目赤、小指麻木"],["足太阳膀胱经","起目内眦，上头顶项背，下行足后外侧","膀胱","与足少阴相表里","头痛项强、腰背痛、腘痛、感冒发热"],["足少阴肾经","起足小趾下，斜走足心，上行腹胸属肾络膀胱","肾","与足太阳相表里","腰膝酸软、遗精、水肿、喘息、耳鸣"],["手厥阴心包经","起胸中，出属心包络，下膈历络三焦","心包","与手少阳相表里","心痛、胸胁胀痛、癫狂、掌心热"],["手少阳三焦经","起无名指端，上行头项，遍身属三焦","三焦","与手厥阴相表里","耳鸣耳聋、咽喉肿痛、胁痛、肩臂痛"],["足少阳胆经","起目外眦，绕耳后下颈循胁下行足外侧","胆","与足厥阴相表里","偏头痛、耳聋、胁痛、瘰疬、半身不遂"],["足厥阴肝经","起大趾丛毛，循胫上股入腹，巅顶连目系","肝","与足少阳相表里","胁痛、目眩、目干、疝气、癫厥"]]},{"type":"cards","columns":3,"items":[{"icon":"🔄","title":"走向与交接","text":"手三阴胸走手，手三阳手走头，足三阳头走足，足三阴足走腹胸。","bullets":["阴经属脏，阳经属腑","末端交接表里经","同名阳经头部交接"]},{"icon":"📐","title":"体表分布","text":"内侧为阴经、外侧为阳经，四肢末端为阴阳经交替交接处。","bullets":["太阴、厥阴、少阴居内侧","阳明、太阳、少阳居外侧","头面部分布有别于四肢"]},{"icon":"🔗","title":"表里配合","text":"六对阴经阳经首尾相接，构成气血运行的完整环路。","bullets":["肺—大肠","心—小肠","脾—胃","肝—胆","肾—膀胱","心包—三焦"]}]},{"type":"heading","level":3,"text":"二、奇经八脉"},{"type":"paragraph","text":"奇经八脉指任、督、冲、带、阴跷、阳跷、阴维、阳维八条不与十二经直接相表里循行的经脉。《难经·论经络·二十七难》谓“凡此八脉者，皆不拘于经，故曰奇经八脉也”。其作用有三：一是沟通十二经脉、调节气血盛衰，如《奇经八脉考·奇经八脉总说》所言“奇经凡八脉，不拘制于十二正经，无表里配合，故谓之奇。盖正经犹夫沟渠，奇经犹夫湖泽，正经之脉隆盛，则溢于奇经”；二是补充十二经在头面、躯干的不足；三是加强脏腑之间的联系。督脉总督一身之阳经，任脉总任一身之阴经，冲脉为十二经脉之海、带脉约束纵行诸脉、跷脉主司下肢运动与眼睑开合、维脉维系一身阴阳。"},{"type":"table","caption":"奇经八脉循行与主治病证","head":["奇经","循行特点","功能定位","常见病证"],"rows":[["督脉","起于下极之俞，并于脊里，上至风府入属于脑","总督一身之阳经","脊强、角弓反张、阳痿、遗尿、疟疾"],["任脉","起于中极之下，循腹里，上至咽喉","总任一身之阴经，主胞胎","疝气、瘕聚、女子妊娠与经带胎产"],["冲脉","起于气冲，并足阳明经夹脐上行，至胸中而散","十二经脉之海，血海","气逆里急、月经不调、崩漏、癫狂"],["带脉","起于季胁，回身一周","约束纵行诸脉，主司腰腹","腰以下如坐水中、腹满、腰痛"],["阴跷脉","起于跟中，循内踝上行，至咽喉交贯冲脉","主一身左右之阴，司下肢运动与目开合","阳缓而阴急、嗜睡、癫狂、不寐"],["阳跷脉","起于跟中，循外踝上行，入风池","主一身左右之阳，司下肢运动与目开合","阴缓而阳急、失眠、癫痈"],["阴维脉","起于诸阴之交，发于足少阴筑宾穴","维络一身之阴","心痛、忧郁、癫狂"],["阳维脉","起于诸阳之会，由外踝而上行于卫分","维络一身之阳","寒热、头痛、胁痛、疟疾"]]},{"type":"heading","level":3,"text":"三、经络的临床作用"},{"type":"paragraph","text":"经络的临床作用可归纳为四点：其一，**沟通表里上下**，联系脏腑与体表、五脏与六腑，形成整体观；其二，**运行气血**，为气血津液运行的通道，决定气血运行的分布与盛衰；其三，**感应传导**，是针灸、推拿、按摩得气与信息传递的通路，也是“内病外治”的理论依据；其四，**调节虚实**，通过针刺、灸法、推拿等刺激经络腧穴，疏通气血、调和脏腑、补虚泻实，使失衡的机体恢复平衡。《灵枢·九针十二原》“凡用针者，虚则实之，满则泄之，宛陈则除之，邪胜则虚之”，正是经络调节虚实功能的具体操作原则。此外，经络学说还用于解释疾病的传变规律、确定腧穴主治、指导药物归经与方剂配伍。"},{"type":"quote","text":"经脉者，所以能决死生、处百病、调虚实，不可不通。……雷公曰：何以知经脉之与络脉异也？黄帝曰：经脉者，常不可见也，其虚实也，以气口知之。脉之见者，皆络脉也。","source":"《黄帝内经·灵枢·经脉》"},{"type":"quote","text":"经脉十二，络脉十五，何始何穷也？然：经脉者，行血气，通阴阳，以荣于身者也。其始从中焦，注手太阴、阳明……别络十五，皆因其原，如环无端，转相灌溉，朝于寸口、人迎，以处百病，而决死生也。","source":"《难经·论经络·二十三难》"},{"type":"keypoints","title":"掌握要点","items":["十二经脉走向：手三阴胸走手，手三阳手走头，足三阳头走足，足三阴足走腹胸。","阴经属脏、阳经属腑，六对表里配合；循行路线固定，主治范围可循经取穴。","奇经八脉不与十二经表里配合，如“沟渠”与“湖泽”之比，调节气血盛衰。","经络四大作用：沟通表里、运行气血、感应传导、调节虚实。"]},{"type":"paragraph","text":"经络学说把藏象的“藏”与体表的“象”具体联系起来，使脏腑功能变化能够通过经络反映于体表，也使体表刺激可以反及脏腑。今天临床上应用的针灸、推拿、拔罐、刺络放血等手段，皆以此为直接理论基础；而方药中的“引经药”、经络辨证下的分经论治，同样源于经络理论。"}]},{"id":"bingyuan","title":"病因","subtitle":"六淫 · 七情 · 饮食劳倦 · 外伤 · 病理产物","icon":"🦠","summary":"病因学说将致病因素分为外感、内伤与其它三类，并强调痰饮瘀血等病理产物既是疾病的结果，又可成为新的致病因素。","blocks":[{"type":"paragraph","text":"病因是疾病发生的原因与条件。中医病因学说的特色在于以脏腑经络的生理病理为基础推求病因，即“审证求因”。《素问·阴阳应象大论》把病因分为“外因”与“内因”两大层次，又有“外伤”与“其他病因”的补充。明代《医学源流论·卷上·病·内伤外感论》总结得更为明确：“七情所病，谓之内伤；六淫所侵，谓之外感。”《金匮要略·卷上·藏府经络先后病脉证第一》则概括为“千般疢难，不越三条：一者，经络受邪，入藏府，为内所因也；二者，四肢九窍，血脉相传，壅塞不通，为外皮肤所中也；三者，房室、金刃、虫兽所伤”，至今仍是把握病因范围的经典依据。"},{"type":"heading","level":3,"text":"一、六淫：风寒暑湿燥火"},{"type":"paragraph","text":"六淫即风、寒、暑、湿、燥、火六种外感邪气。「淫」意为过度、浸淫。六淫致病具有共同特点：一是多从肌表而入或从口鼻而入，故又称外感六淫；二是多与季节气候、环境居处有关；三是有明显的从表入里、由浅入深的传变过程；四是常相兼致病。风为阳邪，其性开泄、善行数变、主动，为百病之始，故《素问·生气通天论》说“故风者，百病之始也”；寒为阴邪，易伤阳气，凝滞收引，主痛；暑为阳邪，其性炎热、升散耗气伤津，多夹湿；湿为阴邪，重浊黏滞、趋下，阻遏气机、损伤阳气；燥为阳邪，其性干涩，易伤津液、耗伤肺气；火（热）为阳邪，其性炎上，易扰心神、迫血妄行、易致疮痈。"},{"type":"table","caption":"六淫性质与致病特点","head":["六淫","阴阳属性","主要性质","致病特点","常见证候"],"rows":[["风","阳邪","开泄、善行数变、主动","病位游走不定，发病急，变化快，兼夹诸邪","恶风、头痛、皮肤瘙痒、游走性关节痛"],["寒","阴邪","凝滞、收引、伤阳","疼痛剧烈、拘挛、气机收敛、恶寒无汗","恶寒发热、无汗、肢体疼痛、脘腹冷痛"],["暑","阳邪","炎热、升散、耗气伤津","多见汗出气短、口渴乏力，常夹湿邪","身热汗多、口渴心烦、头昏、胸闷恶心"],["湿","阴邪","重浊、黏滞、趋下、易阻气机","症状黏滞缠绵、沉重困重，病程迁延","头身困重、脘痞纳呆、便溏不爽、带下量多"],["燥","阳邪","干涩、易伤津液","口鼻咽干、皮肤干裂、大便干结，秋季多见","干咳少痰、鼻咽干燥、皮肤瘙痒、便干"],["火（热）","阳邪","炎上、易扰心神、迫血妄行","热象明显，易致疮痈、出血、神昏谵语","壮热烦渴、面赤、便血、斑疹、谵语"]]},{"type":"cards","columns":3,"items":[{"icon":"🍃","title":"风邪","text":"风为阳邪，百病之始，善行数变而主动。","bullets":["多为外感病初起","症状部位游走不定","兼夹寒热燥湿，变化迅速"]},{"icon":"❄","title":"寒邪","text":"寒为阴邪易伤阳气，凝滞收引而主痛。","bullets":["恶寒、无汗、疼痛拘急","易直中脏腑形成寒邪直中","寒与湿相合易成寒湿"]},{"icon":"☀","title":"暑邪","text":"暑为阳邪，炎热升散而耗气伤津。","bullets":["有明显季节性","多见汗出气短乏力","长夏多夹湿邪为患"]},{"icon":"💦","title":"湿邪","text":"湿为阴邪，重浊黏滞、趋下而阻气机。","bullets":["头身困重、分泌物秽浊","症状黏滞、缠绵难愈","易困阻脾阳、损伤阳气"]},{"icon":"🏜","title":"燥邪","text":"燥为阳邪，干涩伤津，最易伤肺。","bullets":["口鼻咽干、皮肤干裂","秋季多见，初起类似风温","燥与湿相反，治宜滋润"]},{"icon":"🔥","title":"火（热）邪","text":"火为阳邪，炎上扰心，易致出血与疮痈。","bullets":["热象显著、伤津耗气","迫血妄行而见出血","易扰心神而见谵语"]}]},{"type":"heading","level":3,"text":"二、七情内伤、饮食劳倦与外伤"},{"type":"paragraph","text":"**七情内伤**指喜、怒、忧、思、悲、恐、惊七种情志变化超过正常限度而致病。《素问·阴阳应象大论》分述“怒伤肝、喜伤心、思伤脾、忧伤肺、恐伤肾”，《素问·宣明五气》补充“脾藏意，肾藏志”，《灵枢·本神》则从神志活动与五脏的对应关系作了系统阐发。情志致病有三条路径：一为直接伤及本脏，如怒则气上、伤肝动血；二为影响他脏，如思虑过度则脾气郁结、纳呆便溏；三为耗伤心神，如惊则气乱、恐惧则气下。此外情志致病还影响病情演变与预后，故《素问·汤液醪醴论》强调“精神不进，志意不治，故病不可愈”。"},{"type":"paragraph","text":"**饮食失宜**包括过饥、过饱、饮食不洁与饮食偏嗜。过饥则气机内伤、化源不足；过饱则食积中焦、损伤脾胃，《灵枢·五乱》即有“谷气大满，贼邪内伤”之论；饮食不洁易致胃肠疾病或疫疠；偏嗜则可致偏胜偏衰，《素问·生气通天论》说“味过于酸，肝气以津，脾气乃绝；味过于咸，大骨气劳，短肌，心气抑；味过于甘，心气喘满，色黑，肾气不衡；味过于苦，脾气不濡，胃气乃厚；味过于辛，筋脉沮弛，精神乃央”。**劳逸失度**中，劳力过度则耗气，劳神过度则伤心脾，房劳过度则伤肾精，久卧少动则气机不畅；**外伤**包括跌仆损伤、金刃创伤、烧烫伤、虫兽咬伤等。此外还有先天因素、劳逸、外伤、痰饮瘀血等病理产物以及某些其他因素。"},{"type":"table","caption":"内伤病因与致病机制","head":["病因","所伤","病机","常见表现"],"rows":[["怒","肝","气逆上冲，肝气上亢，血随气逆","面红目赤、头胀头痛、呕血，甚则昏厥"],["喜","心","心气涣散，神不守舍","心神不宁、失眠健忘、语无伦次"],["思虑","脾","脾气郁结，运化失职","食欲不振、脘腹胀满、便溏、失眠健忘"],["悲忧","肺","肺气消泄，气机不利","善悲欲哭、气短、咳声低微"],["惊","心、肾","心无所倚、神气不宁、肾气不固","惊悸、失眠、遗精、惊厥"],["恐","肾","肾气不固，恐则气下","恐惧不安、二便失禁、遗精、滑精"],["饮食不节","脾胃","食积、伤胃、吐泻","脘腹胀痛、嗳腐吞酸、泄泻"],["劳倦内伤","脾、肾","中气不足、肾精亏损","神疲乏力、气短懒言、腰膝酸软"]]},{"type":"heading","level":3,"text":"三、痰饮、瘀血等病理产物"},{"type":"paragraph","text":"痰饮、瘀血、结石等病理产物，是脏腑功能失调、水液代谢与血行异常所形成的病理产物，一旦形成又可反过来成为新的致病因素，故有“痰随气升降，无处不到”“瘀血为百病之胎”之说。**痰饮**由水液代谢失常、津液凝聚而成，分为痰与饮：痰较稠浊而流动较小，多阻滞气机、蒙蔽清窍、阻碍血行；饮较清稀而流动较大，多停聚于肺、胃、胸胁、肠腔。**瘀血**为血液运行不畅或停滞所形成的病理产物，可形成于气虚、气滞、血寒、血热、外伤等原因，瘀血停于何处即何处疼痛，固定不移而夜间加重，可见面色黧黑、肌肤甲错、舌质紫暗或有瘀点瘀斑。**结石**多因湿热煎熬、胆气不利、气机郁滞而成。"},{"type":"quote","text":"夫邪气之客于身也，以胜相加，至其所生而愈，至其所不胜而甚，至于所生而持，自得其位而起。必先定五脏之脉，乃可言间甚之时，死生之期也。","source":"《黄帝内经·素问·藏气法时论》"},{"type":"quote","text":"七情所病，谓之内伤；六淫所侵，谓之外感。自《内经》、《难经》以及唐宋诸书，无不言之深切着明矣。二者之病，有病形同而病因异者；亦有病因同而病形异者；又有全乎外感，全乎内伤者，理会有内伤兼外感，外感兼内伤者，则因与病，又互相出入，参错杂乱，治法迥殊。","source":"《医学源流论·卷上·病·内伤外感论》"},{"type":"keypoints","title":"掌握要点","items":["六淫为风寒暑湿燥火，各有阴阳属性与致病特点，且多相兼为病、由表入里。","内伤包括七情、饮食、劳逸；七情直接伤本脏，亦可影响他脏并耗伤心神。","外感与内伤的鉴别关键在于发病途径与症状特点，《医学源流论》有专篇辨析。","痰饮瘀血等病理产物既是结果又是新的致病因素，形成恶性循环。"]},{"type":"paragraph","text":"认识病因是辨证论治的第一步。临床上常需综合四诊把病因与病位、病性、病势结合起来，做到“审证求因，论治病求本”。同时应看到病因与体质、环境、情志、生活方式密切相关，治疗中去除诱因、调理体质往往比单纯用药更为根本。"}]},{"id":"bingji","title":"发病与病机","subtitle":"邪正盛衰 · 阴阳失调 · 内生五邪 · 疾病传变","icon":"⚖","summary":"发病原理在于邪正相争，病机则概括疾病发展过程中阴阳、气血、津液与脏腑功能的变化规律，是辨证的核心依据。","badge":"核心","blocks":[{"type":"paragraph","text":"发病是指疾病的发生过程，病机是指疾病发展变化及其规律的机理。两者既有区别又相互联系：发病回答“病为什么起”，病机回答“病怎么变”。《素问·通评虚实论》以“邪气盛则实，精气夺则虚”概括发病基本原理；《素问·调经论》指出“五脏之道，皆出于经隧，以行血气，血气不和，百病乃变化而生，是故守经隧焉”，说明脏腑经络功能失调是疾病发生的内在基础，而邪气侵袭是重要条件。体质因素在发病中具有决定性影响，《素问·评热病论》提出“邪之所凑，其气必虚”，正气不足是发病的内在根据。"},{"type":"heading","level":3,"text":"一、邪正盛衰与发病"},{"type":"paragraph","text":"邪正盛衰是决定发病与否、病势轻重与预后转归的根本。**邪气**指各种致病因素，**正气**指人体精气津液与脏腑经络功能的总称。正气不足是疾病发生的内在根据，邪气是发病的重要条件，二者相互影响。发病类型有三条：一是正胜邪则病退、正邪相争则病发、正不胜邪则病进；二是邪气盛则实证、精气夺则虚证，两者并见则为虚实夹杂；三是体质差异决定发病倾向，阳盛质易患热证，阴盛质易患寒证，痰湿质易患痰饮湿病。"},{"type":"table","caption":"邪正盛衰与虚实病机","head":["情形","病机","表现","治疗原则"],"rows":[["正胜邪退","正气渐复，邪气渐衰","症状由重转轻，热退身凉，脉渐和缓","继续扶正，祛余邪"],["邪胜正衰","邪气亢盛，正气被伤","症状由轻转重，或见厥脱、昏迷","急祛邪以扶正，或回阳救逆"],["邪正相持","正邪相争，病程迁延","症状时轻时重，反复不愈","扶正祛邪并用"],["正虚邪恋","正气亏虚，余邪未尽","低热、乏力、纳差，病程迁延日久","扶正为主兼清余邪"],["邪盛正实","邪气亢盛而正气未衰","高热、烦躁、脉数有力、苔厚腻","攻邪为主（泻法）"],["精气夺虚","正气亏虚而邪气不盛","神疲乏力、气短、脉弱、舌淡","补益为主（补法）"]]},{"type":"heading","level":3,"text":"二、阴阳失调、气血津液失常与内生五邪"},{"type":"paragraph","text":"**阴阳失调**是疾病病机的总纲，包括阴阳偏盛、偏衰、互损、格拒、亡失等。**气血失常**表现为气的生成不足与运行失常（气虚、气滞、气逆、气陷、气闭、气脱），血的生成不足与运行失常（血虚、血瘀、血热、血寒），以及气血关系失调（气滞血瘀、气虚血瘀、气血两虚、气随血脱）。**津液代谢失常**则表现为津液不足（燥证）与津液停聚（痰饮、水肿）。**内生五邪**指在疾病过程中，由于脏腑功能失调而产生的病理状态，其性质类似外感六淫而有别于六淫致病，称为“内风”“内寒”“内湿”“内燥”“内火”，又称“内生五邪”。"},{"type":"table","caption":"内生五邪的成因与表现","head":["内生五邪","又称","主要成因","主要表现"],"rows":[["风气内动","内风、肝风内动","肝阳化风、热极生风、阴虚风动、血虚生风","眩晕欲仆、肢麻震颤、抽搐、舌强不语"],["寒从中生","内寒","阳气虚衰，温煦气化失职","畏寒肢冷、脘腹冷痛、吐泻清稀、痰饮内停"],["湿浊困阻","内湿","脾失健运、水湿不化；肾阳不足、气化失司","身重困倦、脘痞纳呆、便溏不爽、带下、痰饮"],["津伤化燥","内燥","津液亏少、脏腑失润","口鼻咽干、干咳少痰、皮肤干裂、大便干结"],["火热内生","内火（内热）","阳气过盛化火；阴虚火旺；气郁化火；邪郁化火","五心烦热、口燥咽干、面赤、便秘、尿赤"]]},{"type":"cards","columns":2,"items":[{"icon":"🌬","title":"风气内动","text":"多由肝的疏泄失常引起，以动摇不定为共同特征。","bullets":["肝阳化风：眩晕、肢麻、震颤","热极生风：抽搐、颈项强直","阴虚风动、血虚生风：手足蠕动"]},{"icon":"🥶","title":"寒从中生","text":"内寒多因脾肾阳虚，温煦与气化功能衰退所致。","bullets":["阳虚则寒，畏寒肢冷","气化失司则水湿不化","内寒常与内湿互见"]},{"icon":"💦","title":"湿浊困阻","text":"内湿以重浊黏滞、缠绵难愈为特点。","bullets":["脾虚不运为关键","湿性趋下，易袭下部","易阻气机、损伤阳气"]},{"icon":"🔥","title":"火热内生与津伤化燥","text":"内火多与情志、饮食、瘀血、痰湿郁滞有关；内燥多由津液耗伤。","bullets":["实火多见高热烦渴","虚火多见五心烦热","津亏失润则见干燥诸症"]}]},{"type":"heading","level":3,"text":"三、疾病传变"},{"type":"paragraph","text":"疾病传变指病位与病性的变化。**表里出入**指病邪由表入里或由里出表，影响病之进退；**寒热转化**与**虚实转化**反映病性的转折，如《素问·阴阳应象大论》说“重寒则热，重热则寒”，阳气恢复则阴证转阳属由阴转阳，正气渐衰则阳证转阴属由阳转阴。**病位传变**包括《素问·标本病传论》所论的脏腑传变，如“心病先心痛，一日先欬，三日胁支痛，五日闭塞不通，身痛体重”，并指出“诸病以次是相传如是者，皆有死期”，同时《素问·热论》详述了伤寒由太阳、阳明、少阳、太阴、少阴、厥阴逐日相传的六经传变规律。此外尚有经络传变与病势出入顺逆的区别。"},{"type":"table","caption":"疾病传变形式","head":["传变形式","含义","临床意义"],"rows":[["表里出入","病邪由肌表入里，或由脏腑出表","判断病位深浅与预后，表解为顺、入脏为逆"],["寒热转化","寒证转热或热证转寒","提示病性转折，须重新辨证论治"],["虚实转化","实证转虚或虚证转实","由实转虚多提示正气渐亏，病程迁延"],["脏腑传变","按五行生克与经络循行传变","《标本病传论》系统论述，提示危重程度"],["六经传变","伤寒按太阳至厥阴顺序传变","《素问·热论》详述，见证则治，治其脏脉"],["病势出入","疾病向愈或加重的趋势","判断预后顺逆的关键"]]},{"type":"quote","text":"邪气盛则实，精气夺则虚。……帝曰：经络俱实何如？何以治之？岐伯曰：经络皆实，是寸脉急而尺缓也，皆当治之。故曰：“滑则从，涩则逆也。”","source":"《黄帝内经·素问·通评虚实论》"},{"type":"quote","text":"五脏之道，皆出于经隧，以行血气，血气不和，百病乃变化而生，是故守经隧焉。","source":"《黄帝内经·素问·调经论》"},{"type":"keypoints","title":"掌握要点","items":["发病内在根据是正气不足，外在条件是邪气侵袭，体质因素决定发病倾向。","邪正盛衰决定虚实：邪气盛则实，精气夺则虚，两者并见为虚实夹杂。","内生五邪为内风、内寒、内湿、内燥、内火，多由脏腑功能失调产生。","传变形式包括表里出入、寒热转化、虚实转化与脏腑（六经）传变，标志病势进退。"]},{"type":"paragraph","text":"病机学说把疾病的整体规律与局部变化统一起来：横向看有脏腑、经络、气血津液、阴阳的交叉定位，纵向看有邪正消长与传变顺逆的动态演变。临床辨证实际上就是在还原病机，只有病机明确，才能做到理、法、方、药的层次贯通。"}]},{"id":"sizhen","title":"四诊","subtitle":"望闻问切 · 四诊合参","icon":"🔍","summary":"望闻问切四诊是收集病情资料的基本方法，四诊合参、不可偏执，方能避免以偏概全，并据此判断病位、病性与邪正盛衰。","badge":"核心","blocks":[{"type":"paragraph","text":"四诊即望、闻、问、切，是中医诊察疾病的主要手段。《难经·论脉·一难》提出“十二经皆有动脉，独取寸口，以决五脏六腑死生吉凶之法”，明确了切诊在四诊中的核心地位；《素问·阴阳应象大论》则概括了四诊的基本内容：“善诊者，察色按脉，先别阴阳，审清浊而知部分；视喘息，听音声，而知所苦；观权衡规矩，而知病所主；按尺寸，观浮沉滑濇，而知病所生。以治无过，以诊则不失矣。”四诊不可偏废，须相互印证、反复参详。"},{"type":"heading","level":3,"text":"一、望诊：神色形态"},{"type":"paragraph","text":"望诊重在观察神、色、形态与排泌物，其中以**望神**为首要。《灵枢·本神》指出“神者，水谷之精气也”，故得神者目有光彩、反应灵敏、神志清楚；失神者目光晦暗、表情淡漠、反应迟钝；少神与假神则多见于久病、重病与垂危阶段。**望色**以五色主病为主，《素问·五色》说“青黑为痛，黄赤为热，白为寒”，并以面部部位分部对应脏腑：左颊属肝、右颊属肺、颔属心、颧属肾、鼻属脾。色泽以明润含蓄为有神，晦暗枯槁为无神。**望形态**观察形体强弱胖瘦、动静姿态、皮肤毛发与四肢关节；望舌是望诊的重要内容，舌质候气血、舌苔候邪正。此外尚需观察痰涎、呕吐物、痰色、二便与分泌物。"},{"type":"heading","level":3,"text":"二、闻诊与问诊"},{"type":"paragraph","text":"**闻诊**包括听声音与嗅气味。听声音主要辨语言、呼吸、咳嗽、呕吐、嗳气、呃逆、喷嚏、肠鸣等，声音高亢有力多属实证，低沉无力多属虚证；咳嗽声重浊有痰多属实证，干咳无痰或痰少而黏多属虚燥。嗅气味包括汗臭、痰臭、口气、呕吐物气味、粪尿气味与病室气味，腐臭秽浊多属实热，腥臭多见于出血或疮疡。**问诊**内容最为广泛，经典归纳为“十问歌”：一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变。问诊要点包括既往史、现在史、生活习惯与情志等，尤须重视《医学源流论·卷上·经络脏腑·躯壳经络脏腑论》所说“今人不问何病，廖举一经以借口”的弊端。"},{"type":"table","caption":"四诊内容与常见征候","head":["诊法","观察内容","常见征候","提示病机"],"rows":[["望神","目光、表情、反应、意识","得神目光明亮、反应灵敏；失神目光晦暗、反应迟钝","正气盛衰、预后吉凶"],["望色","面色、肤色、爪甲","面赤潮红属热；面白属虚寒；青紫属瘀血","寒热虚实、气血瘀滞"],["望舌","舌质、舌苔、舌形舌态","舌红苔黄燥属热；舌淡胖有齿痕属气虚湿盛；舌紫有瘀点属瘀","气血津液状态与邪正关系"],["闻声","语言、咳嗽、喘息、嗳呃","声高气粗属实证；声低气怯属虚证","邪正盛衰、气机升降"],["嗅气味","汗、痰、口气、呕吐物、二便","臭秽浓重属实热；清稀无味属虚寒","湿热、食积、瘀血、腐败"],["问寒热","恶寒、发热、潮热、畏寒","恶寒发热属表；寒热往来属少阳；午后潮热属阴虚","表里寒热与邪正进退"],["问汗","自汗、盗汗、绝汗、战汗","自汗多属气虚；盗汗属阴虚；绝汗为亡阳亡阴危候","阳气固摄与津液存亡"],["切脉","寸关尺三部脉象","浮沉迟数辨表里寒热虚实，脉有力无力定邪正","气血盛衰与病邪性质"]]},{"type":"cards","columns":2,"items":[{"icon":"👁","title":"望诊要点","text":"望神为先，察色为要，舌诊为重点。","bullets":["得神少神失神辨预后","五色主病结合面部分部","舌质候气血、舌苔候邪正"]},{"icon":"👂","title":"闻诊要点","text":"以声高气粗为实、声低气怯为虚的总纲辨别。","bullets":["辨语言、呼吸、咳嗽、呃逆","辨汗、痰、二便与呕吐物气味","结合嗅诊判断寒热与腐败"]},{"icon":"🗣","title":"问诊要点","text":"十问歌为纲，兼问既往、现在与生活情志。","bullets":["问寒热汗以明寒热表里","问饮食二便以察脾胃与肾","问旧病情志以明诱因"]},{"icon":"🫱","title":"切诊要点","text":"脉诊为主，按诊为辅，合参方能定病位病性。","bullets":["寸关尺候脏腑，三部合参","浮沉迟数辨表里寒热","有力无力、有神无神定虚实"]}]},{"type":"heading","level":3,"text":"三、切诊：脉诊与按诊"},{"type":"paragraph","text":"**脉诊**以寸口腕部为诊察部位。《濒湖脉学·四言举要》概括其原理：“脉乃血脉，气血之先，血之隧道，气息应焉。……十二经中，皆有动脉，惟手太阴，寸口取决，此经属肺，上系吭嗌，脉之大会，息之出入。”《难经·论脉·一难》进一步说明：“人一呼脉行三寸，一吸脉行三寸，呼吸定息，脉行六寸。……寸口者，五脏六腑之所终始，故法取于寸口也。”寸口分寸、关、尺三部，左右分候心肝脾（左手）与肺胃肾（右手）。脉诊须注意脉位、脉数、脉形、脉势、脉律、脉神六个方面，常见二十七脉，以浮、沉、迟、数、虚、实、细、滑、涩、弦、紧等为基本脉象。"},{"type":"paragraph","text":"**按诊**包括按肌肤、按手足、按胸腹、按腧穴。通过肌肤的寒热、润燥、肿块与疼痛，了解寒热真假与痰饮、瘀血、积聚；按手足手足温凉与手足心热感，辨亡阳与阴虚内热；按胸腹辨别痞、满、痛、癥瘕；按腧穴如合谷、委中、阳陵泉等的压痛与异常反应，可协助定位病位。此外尚有体温计测温等辅助方法。切诊与望闻问相互配合，方能全面。"},{"type":"heading","level":3,"text":"四、四诊合参：舍症从脉与舍脉从症"},{"type":"paragraph","text":"四诊合参是诊断的基本原则，即把望闻问切四方面资料互相参证、互相对照，避免以一诊定全局。当四诊资料出现矛盾时，就须有所取舍，这就是**舍症从脉**与**舍脉从症**。舍症从脉指在症与脉不一致时，以脉象为准，多见于病邪深重、真气已衰而症象不足以反映本质的情况，如脉沉细而症见面赤身热；舍脉从症指以症状表现为主，多见于邪气有余、真气未衰而脉象受一时因素干扰的情况，如热证而脉一时沉伏。取舍的原则是“审证求因”，抓住疾病的本质病机，不可执着于四诊中的任何一诊而轻弃其余三诊。"},{"type":"table","caption":"四诊合参与取舍原则","head":["情形","取舍方向","适用情形","举例"],"rows":[["症脉一致","四诊同参，无须取舍","病机明确、证据统一","面赤、脉数有力、苔黄燥，同属里热实"],["症脉相背","舍症从脉","邪盛正衰，症象失真，脉象反映本质","身热面赤而脉沉细无力，属真寒假热"],["症脉相背","舍脉从症","邪气有余而脉受干扰，症象可信","热证而脉偶伏，症见壮热口渴便秘"],["脉证相反","结合病史与病程判断","需追溯病因、时相与治疗经过","久病脉反有力当细辨真虚假实"],["症脉均疑","重做检查、动态观察","资料不足或病情演变中","结合前后变化与治疗反应校正诊断"]]},{"type":"quote","text":"善诊者，察色按脉，先别阴阳，审清浊而知部分；视喘息，听音声，而知所苦；观权衡规矩，而知病所主；按尺寸，观浮沉滑濇，而知病所生。以治无过，以诊则不失矣。","source":"《黄帝内经·素问·阴阳应象大论》"},{"type":"quote","text":"曰：经言脉有是动，有所生病。一脉（辄）变为二病者，何也？然：经言是动者，气也；所生病者，血也。邪在气，气为是动；邪在血，血为所生病。气主呴之，血主濡之。气留而不行者，为气先病也；血壅而不濡者，为血后病也。故先为是动，后所生（病）也。","source":"《难经·论脉·二十二难》"},{"type":"keypoints","title":"掌握要点","items":["四诊为望闻问切，望神、闻声、问寒热汗、切脉为四大要点。","脉诊取寸口三部，正常人每息脉四至（相当一息四至或五六至），徐和匀。","四诊必须合参，症脉矛盾时须辨明是舍症从脉还是舍脉从症。","取舍的最终标准是审证求因，抓住疾病本质病机。"]},{"type":"paragraph","text":"四诊是中医认识疾病的窗口，也是辨证论治的第一环节。临床工作中应做到四诊合参、动态观察，既重视局部症状，更注重整体与体质；既采集当下的静态信息，也追问病程的动态变化。同时必须明确，舌脉等诊察结果具有主观性，不同医者理解可能有差异，因此需要以规范的操作标准尽量减少误判。"}]},{"id":"bagen","title":"八纲辨证","subtitle":"表里寒热虚实阴阳 · 相兼错杂 · 真假","icon":"🎯","summary":"八纲是辨证的总纲，其中阴阳为总纲，表里定病位、寒热定病性、虚实定邪正盛衰，三者相互联系而不可分割。","badge":"核心","blocks":[{"type":"paragraph","text":"八纲即表、里、寒、热、虚、实、阴、阳，是从八个角度对病证进行概括分析的最基本方法。《医学源流论·卷上·病·寒热虚实真假论》指出“病之大端，不外乎寒热虚实”，说明八纲是从大量临床证候中归纳提炼的纲领性认识。《素问·阴阳应象大论》“善诊者，察色按脉，先别阴阳”则确立了阴阳在八纲中的主导地位。八纲中表里辨病位深浅，寒热辨病性，虚实辨邪正盛衰，阴阳则统摄前六纲，是辨证的总纲与纲中之纲。"},{"type":"heading","level":3,"text":"一、八纲的基本证候"},{"type":"paragraph","text":"**表证**指邪气侵袭肌表所表现的证候，常见恶寒发热、头身疼痛、脉浮，治宜解表；**里证**指病变在脏腑，范围广、表现复杂，可由表证内传入里或由内伤直接产生，治宜清里、温里、攻下等法。**寒证**属阴，常见畏寒喜暖、口淡不渴、小便清长、舌淡苔白、脉迟；**热证**属阳，常见发热喜凉、口渴喜冷、便秘尿赤、舌红苔黄、脉数。**虚证**为正气不足，常见神疲乏力、气短懒言、痛处喜按、舌淡嫩、脉虚无力；**实证**为邪气亢盛，常见壮热烦躁、声高气粗、痛处拒按、舌苔厚腻、脉实有力。"},{"type":"table","caption":"八纲辨证基本要点","head":["八纲","所属","主要依据","典型表现","常用治法"],"rows":[["表证","阳","恶寒发热、头身痛、脉浮","发热恶寒并见，无汗或汗出不畅","解表（辛温解表／辛凉解表）"],["里证","阴","脏腑功能失常表现，脉沉","但寒不热、但热不寒，或脏腑功能紊乱","清里、温里、通下等"],["寒证","阴","畏寒、口淡、舌淡苔白、脉迟","肢冷、清稀、无汗、痛喜温","散寒、温里（热者寒治）"],["热证","阳","发热、口渴、舌红苔黄、脉数","壮热、烦渴、便秘尿赤、痛拒按","清热、泻火（寒者热治）"],["虚证","阴","正气不足，脉弱无力","神疲气短、声低息微、痛喜按","补虚（益气养血滋阴温阳）"],["实证","阳","邪气亢盛，脉实有力","壮热烦躁、声高气粗、痛拒按","泻实（发汗攻下清解消导）"]]},{"type":"cards","columns":3,"items":[{"icon":"📍","title":"表里辨病位","text":"表证病在肌表，里证病在脏腑。","bullets":["表证以恶寒发热为主","里证以脏腑功能失调为主","表证入里则由表转里"]},{"icon":"🌡","title":"寒热辨病性","text":"寒热反映病变性质，与阴阳总纲相属。","bullets":["寒证属阴，热证属阳","热者寒之，寒者热之","真寒假热、真热假寒须辨"]},{"icon":"⚖","title":"虚实辨邪正","text":"虚实反映邪正盛衰，是决定攻补的依据。","bullets":["邪气盛则实，精气夺则虚","虚实夹杂须分主次","虚实真假须仔细鉴别"]},{"icon":"🌗","title":"阴阳为总纲","text":"表里寒热虚实六纲最终皆可归属阴阳。","bullets":["阳证：表热实证","阴证：里寒虚证","阴病治阳，阳病治阴"]},{"icon":"🧩","title":"相兼与错杂","text":"八纲可同时出现，常见表里相兼、寒热错杂、虚实夹杂。","bullets":["相兼：八纲并存","错杂：寒热虚实互见","转化：随病机演进而变"]},{"icon":"🎭","title":"真假辨析","text":"病重时可见与本质相反的假象，须去伪存真。","bullets":["真寒假热：阴盛格阳","真热假寒：阳盛格阴","大实有羸状，至虚有盛候"]}]},{"type":"heading","level":3,"text":"二、证候的相兼、错杂与真假"},{"type":"paragraph","text":"八纲在临床中极少单独出现，多以相兼、错杂与转化的形式呈现。**相兼**指八纲中两个或多个同时存在，如表寒、里热、虚实夹杂等，是最常见的情形。**错杂**指寒与热、虚与实同时出现而主次不一，如上热下寒、上实下虚、虚中夹实，处理时须分清主次，或寒热并用、或攻补兼施。《素问·标本病传论》提出的“间者并行，甚者独行”即为此意。**转化**指证候随病程在表里、寒热、虚实之间发生性质变化，如表证入里、由实转虚、由阴转阳（向愈）或由阳转阴（恶化）。**真假**则指本质与现象不一致，出现假寒、假热、假实、假虚，需依据“假象”出现的部位、程度与脉舌等综合判断。"},{"type":"table","caption":"八纲相兼、错杂与真假鉴别","head":["类型","具体表现","辨识要点","治疗原则"],"rows":[["表里相兼","表证未罢而里证已见，如恶寒发热兼口渴便秘","表证里证并见，以何者为主定治法先后","先表后里或表里双解"],["寒热错杂","上热下寒、上寒下热","辨别上下部位与真假之别","寒热并用，按主次调整"],["虚实夹杂","正虚与邪实并存，如气虚兼痰湿","察邪正主次，辨虚实多少","攻补兼施，或扶正祛邪并用"],["寒热转化","寒证转热、热证转寒","结合病程、季节与转归判断","重新辨证，随证立法"],["虚实转化","实证转虚、虚证转实","观察正气耗伤程度与新邪是否起","由攻转补或补中寓攻"],["真寒假热","身热反欲盖衣、面红如妆、口渴喜热饮或饮不多","内寒极盛格阳于外，脉沉而有力","热因寒用，急回阳"],["真热假寒","四肢厥冷而胸腹灼热、脉沉而有力","内热炽盛阳郁不达四末","寒因热用，急清热"],["真实假虚","大实有羸状，如腹胀满而脉弱","形瘦声低而内有实积，脉虽弱而有力","攻下逐实"],["真虚假实","至虚有盛候，如腹胀而时减、按之不痛","食少便溏、脉弱，重按无力","补虚扶正"]]},{"type":"heading","level":3,"text":"三、八纲与病因病机的层次关系"},{"type":"paragraph","text":"八纲并非孤立的标签，而是有层次结构的判断体系。**第一层是病位**，即表与里，决定治疗的大方向是解表还是治里；**第二层是病性**，即寒与热，决定治法性质是温还是清；**第三层是邪正盛衰**，即虚与实，决定治疗手段是补还是泻；**第四层是阴阳归属**，将前三层六纲归纳为阴证与阳证两大类，以统摄全局。这与病因病机层次是相对应的：病因（六淫、七情、饮食劳倦）回答“因何而病”，病机（邪正盛衰、阴阳失调、气血津液失常、内生五邪）回答“病在何处、为何如此”，八纲则把病机认识归纳为可操作的辨证结论。而脏腑辨证、气血津液辨证、卫气营血辨证、三焦辨证等具体辨证方法，都是在八纲统摄下的进一步细分。"},{"type":"table","caption":"八纲与病因病机的层次对应","head":["层次","八纲内容","对应病机","对应病因","治疗取向"],"rows":[["第一层·病位","表 / 里","邪在肌表 或 病及脏腑","六淫外袭、情志内伤、饮食劳倦","解表 或 治里（清温攻补随证）"],["第二层·病性","寒 / 热","阴阳偏盛偏衰","寒邪、热邪、阳虚、阴虚","寒者热之、热者寒之"],["第三层·邪正","虚 / 实","邪气盛则实、精气夺则虚","邪气亢盛 或 正气不足","实则泻之、虚则补之"],["第四层·总纲","阴 / 阳","阴阳失调总括","阴阳偏盛偏衰、阴阳格拒亡失","阴病治阳、阳病治阴，以平为期"]]},{"type":"quote","text":"病之大端，不外乎寒热虚实，然必辨其真假，而后治之无误。假寒者，寒在外而热在内也，虽大寒而恶热饮；假热者，热在外而寒在内也，虽大热而恶寒饮，此其大较也。假实者，形实而神衰，其脉浮、洪、芤、散也；假虚者，形衰而神全，其脉静、小、坚、实。","source":"《医学源流论·卷上·病·寒热虚实真假论》"},{"type":"quote","text":"凡脉大、浮、数、动、滑，此名阳也；脉沉、涩、弱、弦、微，此名阴也，凡阴病见阳脉者生，阳病见阴脉者死。","source":"《伤寒论·辩脉法》"},{"type":"keypoints","title":"掌握要点","items":["八纲为表里寒热虚实阴阳，阴阳统摄其余六纲，是辨证总纲。","表里定病位，寒热定病性，虚实定邪正盛衰，三者合参方能定治法。","证候存在相兼、错杂、转化与真假四种情形，须分清主次、去伪存真。","八纲与病因病机形成层次对应：病因言其因，病机言其变，八纲言其辨证结论。"]},{"type":"paragraph","text":"八纲辨证是所有具体辨证方法的共同基础。熟练掌握八纲之后，方能进入脏腑辨证、气血津液辨证、卫气营血辨证与三焦辨证等更细的层面，也才能理解“同病异治、异病同治”何以成立——因八纲组合不同、从而立法不同，而不同病证若八纲一致亦可异病同治。"}]},{"id":"zhize","title":"治则治法","subtitle":"治本治标 · 扶正祛邪 · 三因制宜 · 治病八法","icon":"⚕","summary":"治则是立法遣方的总纲，治法是治则在具体病证中的落实，核心目标是调整阴阳、恢复脏腑功能与气血协调。","badge":"核心","blocks":[{"type":"paragraph","text":"治则治法是针对疾病病机所确立的治疗原则与具体方法。《素问·阴阳应象大论》开篇即言“治病必求于本”，奠定了辨证求因、治病求本的总原则；《素问·至真要大论》提出“谨察阴阳所在而调之，以平为期，正者正治，反者反治”，指明治疗的总目标是“以平为期”。治则解决方向性问题，治法解决具体方法问题：治则如“扶正祛邪”“调整阴阳”，治法则如“滋阴潜阳”“息风止痉”“活血化瘀”。二者一纲一目，共同指导方药与针灸的选择。"},{"type":"heading","level":3,"text":"一、治标与治本，标本缓急"},{"type":"paragraph","text":"**标本**是矛盾的双方，一般认为病因是本、 symptoms 是标，脏腑病变是本、外在症状是标，先病是本、后病是标。《素问·标本病传论》系统论述了标本治则：“知标本者，万举万当，不知标本，是谓妄行。”其要点为：急则治标，当病势急重、危及生命时先治其标，如大出血先止血、水肿先利水；缓则治本，在病情缓和、病势迁延时着重治其病因病机以求根治；标本兼治则攻补兼施、扶正祛邪并进。《素问·汤液醪醴论》指出“病为本，工为标，标本不得，邪气不服”，强调医者须辨明标本，方能使邪气得解。"},{"type":"paragraph","text":"《金匮要略·卷上·藏府经络先后病脉证第一》举“见肝之病，知肝传脾，当先实脾”为范例，说明既病防变的治则依据——在治疗本脏的同时，预先顾护可能受累的脏腑。书中进一步指出“上工治未病，何也？师曰：夫治未病者，见肝之病，知肝传脾，当先实脾，四季脾旺不受邪，即勿补之”，体现了治未病与既病防变的思想。"},{"type":"table","caption":"标本缓急与治法取舍","head":["原则","适用情形","具体做法","经典依据"],"rows":[["急则治标","标病急重危及生命","大出血先止血、喘脱先救脱、痉证先止痉","《素问·标本病传论》"],["缓则治本","病情缓和、病势迁延","针对病因与病机根本施治，如虚劳补肾","《素问·标本病传论》"],["标本兼治","标本并重或单一法难以奏效","扶正祛邪兼施，如气血同补、寒热并调","《素问·标本病传论》"],["先标后本","标症消除后转治本","解表后调理脏腑、止血后益气摄血","《素问·标本病传论》"],["先本后标","本虚而标实不甚","先补虚以扶正，兼以祛邪","《金匮要略》肝脾同治例"]]},{"type":"heading","level":3,"text":"二、扶正祛邪、调整阴阳与调理脏腑"},{"type":"paragraph","text":"**扶正祛邪**是针对邪正盛衰的基本治则。扶正即扶助正气，适用于虚证或真虚假实，包括益气、养血、滋阴、温阳等法；祛邪即攻逐邪气，适用于实证或真实假虚，包括发汗、攻下、清热、温寒、消导、涌吐、祛湿等法。运用时须辨清主次：正虚为主者以扶正为主兼以祛邪，邪实为主者以祛邪为主兼以扶正，虚实夹杂者攻补兼施或攻补交替，且要注意“先补后攻”“先攻后补”“攻补兼施”“攻补交替”四种不同策略。**调整阴阳**则针对阴阳偏盛偏衰：阳盛则热者寒凉清热，阴盛则寒者辛热散寒，阳虚则补阳以制阴，阴虚则滋阴以制阳，即“壮水之主，以制阳光；益火之源，以消阴翳”。**调理脏腑**则针对脏腑功能失调，分别采用调理脏腑、脏腑相治（如肝脾同治、心肾相交、肺胃同调）与脏腑局部治疗（针对某一脏腑的具体病机立法）三类方法。"},{"type":"cards","columns":2,"items":[{"icon":"🛡","title":"扶正祛邪","text":"针对邪正盛衰，虚者补之、实者泻之。","bullets":["扶正：益气、养血、滋阴、温阳","祛邪：发汗、攻下、清热、消导、涌吐","虚实夹杂则攻补兼施或交替"]},{"icon":"⚖","title":"调整阴阳","text":"以平为期，恢复阴平阳秘。","bullets":["阳盛者寒凉清热","阴盛者辛热散寒","阳虚补阳、阴虚滋阴"]},{"icon":"🫀","title":"调理脏腑","text":"针对脏腑功能失调与脏腑间关系失衡立法。","bullets":["单独调理某一脏腑","脏腑同治，如肝脾、心肾同调","依据五行生克补母泻子"]},{"icon":"🌏","title":"三因制宜","text":"因时、因地、因人制宜，体现整体与个体差异。","bullets":["因时：顺应四时气候与运气","因地：考虑地域水土与物产","因人：年龄、性别、体质、病史"]}]},{"type":"heading","level":3,"text":"三、三因制宜与个体化调整"},{"type":"paragraph","text":"**因时制宜**指顺应四时气候变化施治，《素问·四气调神大论》详述了“春三月，此为发陈……夏三月，此为蕃秀……秋三月，此谓容平……冬三月，此为闭藏”的起居与摄生原则，并指出“圣人春夏养阳，秋冬养阴，以从其根”；临床亦须考虑运气太过不及对疾病的影响，《素问·五常政大论》即强调“不失岁气，无伐天和”。**因地制宜**指依据地域环境、气候与物产特点立法，《素问·异法方宜论》系统论述“东方之域……其治宜砭石；西方者……其治宜毒药；北方者……其治宜灸焫；南方者……其治宜微针；中央者……其治宜导引按蹻”，并总结“故圣人杂合以治，各得其所宜”。**因人制宜**指依据患者年龄、性别、体质、既往病史与生活习惯调整方药与剂量，《灵枢·五味》与《素问·至真要大论》均强调“必先岁气，无伐天和，无盛盛，无虚虚”。"},{"type":"heading","level":3,"text":"四、治病八法与常用治法"},{"type":"paragraph","text":"**八法**是《伤寒论》确立、后世完善的基本治法，即汗、吐、下、和、温、清、消、补。汗法开泄腠理、发汗解表，用于表证；吐法涌吐痰涎宿食，用于痰涎壅盛、宿食内停；下法荡涤肠胃、攻下里实，用于里实证；和解法和解少阳、调和肝脾，用于半表半里或脏腑不和；温法温里祛寒、回阳救逆，用于里寒证；清法清热泻火、凉血解毒，用于里热证；消法消食化积、行气活血、化痰利水，用于食积、痰饮、瘀血等积滞证；补法补益气血阴阳，用于各种虚证。《素问·阴阳应象大论》对治法层次有精辟概括：“其高者，因而越之；其下者，引而竭之；中满者，泻之于内；有邪者，渍形以为汗；其在皮者，汗而发之……审其阴阳，以别柔刚。阳病治阴，阴病治阳，定其血气，各守其乡。”"},{"type":"paragraph","text":"**常用治法**是在八法基础上针对具体病机形成的专法，如用于虚阳上浮的滋阴潜阳、用于肝阳化风的平肝息风、用于热极生风的息风止痉、用于瘀血内阻的活血化瘀、用于痰饮内停的燥湿化痰与温化寒痰、用于湿热壅盛的清热利湿、用于食积内停的消食导滞、用于虫积的驱虫、用于疮疡肿毒的消肿排脓等。使用这些治法时须严格把握适应证与禁忌证，如滋阴潜阳用于阴虚阳亢之虚热，不用于实热；活血化瘀用于瘀血，孕妇慎用；峻下逐水与涌吐吐法体虚者慎用。"},{"type":"table","caption":"治病八法对照","head":["治法","作用","适应证","代表方举例","使用注意"],"rows":[["汗法","开泄腠理、发汗解表","表证","麻黄汤、桂枝汤、银翘散","表虚自汗、阴虚盗汗忌用"],["吐法","涌吐痰涎宿食","痰涎壅盛、宿食内停","瓜蒂散","体虚、孕妇慎用"],["下法","荡涤肠胃、攻下里实","里实证","大承气汤、小承气汤、麻子仁丸","表证未解、孕妇、脾虚者忌用"],["和法","和解少阳、调和肝脾","半表半里证、肝脾不和","小柴胡汤、四逆散","不宜用于邪实正虚之证"],["温法","温里祛寒、回阳救逆","里寒证、亡阳证","理中汤、四逆汤","阴虚火旺者忌用"],["清法","清热泻火、凉血解毒","里热证","白虎汤、黄连解毒汤","脾胃虚寒者慎用"],["消法","消食化积、化痰利水、行气活血","积滞痰饮瘀血","保和丸、二陈汤、血府逐瘀汤","虚证慎用"],["补法","补益气血阴阳","各种虚证","四君子汤、四物汤、六味地黄丸","实证未清者忌用"]]},{"type":"table","caption":"常用治法与适应证","head":["治法","针对病机","主治病证","常用配伍思路"],"rows":[["滋阴潜阳","阴虚不能制阳、虚阳上浮","阴虚阳亢之眩晕耳鸣、烘热盗汗","滋阴药配潜阳药，如六味地黄丸加龙骨牡蛎"],["平肝息风","肝阳上亢、肝风内动","眩晕头痛、手足震颤、抽搐","平肝潜阳药配息风止痉药，如天麻钩藤饮"],["息风止痉","热极生风、邪热炽盛引动肝风","高热、抽搐、神昏","凉肝息风药，如羚角钩藤汤"],["活血化瘀","血行不畅、瘀血内阻","痛有定处、癥瘕积聚、痛经","活血药配行气药，如血府逐瘀汤"],["燥湿化痰","湿聚成痰、痰湿阻滞","咳嗽痰多、脘痞纳呆","燥湿化痰配理气健脾，如二陈汤"],["清热利湿","湿热壅滞、熏蒸肝胆","黄疸、胁痛、淋证、带下","清热燥湿配利湿药，如茵陈蒿汤"],["消食导滞","食积内停、脘腹胀满","嗳腐吞酸、纳呆、便臭","消导药配行气药，如保和丸"],["驱虫杀虫","虫积肠道","脐腹作痛、嗜食异物","安蛔、驱虫药，如乌梅丸"]]},{"type":"quote","text":"谨察阴阳所在而调之，以平为期，正者正治，反者反治。……夫气之胜也，微者随之，甚者制之。气之复也，和者平之，暴者夺之，皆随胜气，安其屈伏，无问其数，以平为期，此其道也。","source":"《黄帝内经·素问·至真要大论》"},{"type":"quote","text":"夫病之始生也，极微极精，必先入结于皮肤。今良工皆称曰病成，名曰逆，则针石不能治，良药不能及也。……病为本，工为标，标本不得，邪气不服，此之谓也。","source":"《黄帝内经·素问·汤液醪醴论》"},{"type":"keypoints","title":"掌握要点","items":["治则总纲为“治病求本”与“以平为期”，治标治本依病情缓急取舍。","三大治则：扶正祛邪（虚补实泻）、调整阴阳（阴病治阳、阳病治阴）、调理脏腑。","三因制宜：因时顺四时运气，因地察水土物产，因人辨体质与病史。","治病八法为汗、吐、下、和、温、清、消、补，用时须严守适应证与禁忌。"]},{"type":"paragraph","text":"从理法方药的整体链条看：辨证是认识阶段，治则是从认识走向治疗的转折点，治法是治则的具体化，方药与针灸是治法的落地形式，疗效又反过来检验辨证与治则是否正确。因此“理法方药”的贯通，其枢纽正在于治则治法这一层。"}]},{"id":"prevent","title":"治未病与养生","subtitle":"未病先防 · 既病防变 · 瘥后防复","icon":"🌿","summary":"治未病是中医的最高追求，涵盖未病先防、既病防变与瘥后防复三个层次，是养生与临床防病的统一原则。","badge":"加分","blocks":[{"type":"paragraph","text":"治未病是中医防治思想的最高境界。《素问·四气调神大论》提出：“是故圣人不治已病，治未病；不治已乱，治未乱，此之谓也。夫病已成而后药之，乱已成而后治之，譬犹渴而穿井，斗而铸锥，不亦晚乎！”《素问·热论》亦说“视其虚实，调其逆从，可使必已矣”，强调在疾病初起、病邪尚浅时就及时干预。这一思想包含三个层次：未病先防、既病防变、瘥后防复，与现代医学强调的预防医学、防止并发症与防止复发的思路高度契合。"},{"type":"heading","level":3,"text":"一、未病先防：养生固护正气"},{"type":"paragraph","text":"未病先防包含两个层面：一是**养生固护正气**，增强体质以抗邪；二是**防止病邪侵害**，避其邪气。《素问·上古天真论》系统阐述养生的根本原则：“上古之人，其知道者，法于阴阳，和于术数，食饮有节，起居有常，不妄作劳，故能形与神俱，而尽终其天年，度百岁乃去。”与之相对的是失养之害：“今时之人不然也，以酒为浆，以妄为常，醉以入房，以欲竭其精，以耗散其真，不知持满，不时御神，务快其心，逆于生乐，起居无节，故半百而衰也。”《素问·生气通天论》补充“阴平阳秘，精神乃治”的总目标，并强调“谨和五味，骨正筋柔，气血以流，腠理以密”。"},{"type":"paragraph","text":"养生的具体方法包括：顺应四时（春生夏长秋收冬藏的起居原则）、调畅情志（“澹泊虚无，真气从之”）、饮食有节（“食饮有节”“食不厌精，脍不厌细”）、劳逸适度（“不妄作劳”）、节欲保精、动静相兼、导引按跷（如八段锦、五禽戏）、以及针灸、药物等辅助调养。《灵枢·本神》提出养生的具体要求：“智者之养生也，必顺四时而适寒暑，和喜怒而安居处，节阴阳而调刚柔。如是，则僻邪不至，长生久视。”同时强调“正气存内，邪不可干”，《素问·刺法论》更提出“避其毒气”的主动防护观念。"},{"type":"cards","columns":3,"items":[{"icon":"🌱","title":"未病先防","text":"在未病状态下调养正气、避邪防病。","bullets":["顺应四时，起居有常","调畅情志，恬淡虚无","饮食有节，劳逸适度","导引按跷，动静相兼"]},{"icon":"🛡","title":"既病防变","text":"疾病初起即及时治疗，防止传变与恶化。","bullets":["早诊早治，截断扭转","顾护未受邪之脏","早期即用汗法解表防内传"]},{"icon":"🔄","title":"瘥后防复","text":"病后调理，防范余邪与复发。","bullets":["《素问·热论》：热甚而强食之故有所遗","病后调养脾胃，防食复","起居避风寒，节饮食慎情志"]}]},{"type":"heading","level":3,"text":"二、既病防变：早期干预与顾护未病之脏"},{"type":"paragraph","text":"既病防变指疾病已发生之后，医者与患者共同采取措施，防止病邪进一步传变、病情加重或转为危重。其理论依据有三：一是**早期治疗防止病邪深入**，《素问·阴阳应象大论》指出“故善治者治皮毛，其次治肌肤，其次治筋脉，其次治六腑，其次治五脏。治五脏者，半死半生也”，强调在皮毛、肌肤阶段即干预；二是**脏腑传变的前瞻性防治**，《金匮要略·卷上·藏府经络先后病脉证第一》说“见肝之病，知肝传脾，当先实脾”，即治疗肝的同时预先顾护脾；三是**顾护正气、避免误治**，《素问·至真要大论》提出“无盛盛，无虚虚”，强调不可因病情而妄用峻剂。《素问·标本病传论》还按“心病先心痛，一日先欬……”的规律列出传变次序与死生之期，为既病防变提供了时间维度的参考。"},{"type":"heading","level":3,"text":"三、瘥后防复：病后调理与康复"},{"type":"paragraph","text":"瘥后防复指疾病初愈或缓解后，防止余邪未尽、劳复、食复而再度发病。《素问·热论》明确指出：“热病已愈，时有所遗者，何也？岐伯曰：诸遗者，热甚而强食之，故有所遗也。若此者，皆病已衰而热有所藏，因其谷气相薄，两热相合，故有所遗也。”并给出治法“视其虚实，调其逆从，可使必已矣”，以及禁忌“病热少愈，食肉则复，多食则遗，此其禁也”。《伤寒论》专列“辨阴阳易差后劳复病证并治”篇，对病后劳复、阴阳易等作了系统论述。病后调护的要点包括：慎起居、节饮食、适寒温、畅情志、慎用峻补，并视余邪性质酌以清化。"},{"type":"table","caption":"治未病三个层次的操作要点","head":["层次","时机","核心措施","经典依据"],"rows":[["未病先防","未病、亚健康状态","养生固护正气、避其毒气、顺应四时、节饮食慎起居","《素问·上古天真论》《四气调神大论》"],["既病防变","疾病初起、病邪尚浅","早诊早治、截断扭转、顾护未受邪脏腑、不可妄攻","《素问·阴阳应象大论》《金匮要略》"],["瘥后防复","病后邪衰正未复","清余邪、节饮食、慎劳倦、适寒温、畅情志","《素问·热论》《伤寒论》"]]},{"type":"table","caption":"四时摄生要点","head":["季节","气候特点","养生原则","起居调摄","情志调摄"],"rows":[["春","阳气始生、万物发陈","养肝气、疏泄条达","夜卧早起，广步于庭，被发缓形","使志生，勿怒、勿杀生"],["夏","阳气盛长、万物蕃秀","养心气、养阴清热","夜卧早起，无厌于日，使气得泄","使志无怒，志达喜畅"],["长夏","湿气当令","健脾化湿","避暑湿、忌生冷黏腻","思虑勿过，防困脾"],["秋","秋高气爽、阳气渐收","养肺气、润燥","早卧早起，与鸡俱兴，收敛神气","使志安宁，勿外其志"],["冬","阴盛阳伏、万物闭藏","养肾气、藏精固元","早卧晚起，必待日光，去寒就温","使志若伏若匿，勿扰乎阳"]]},{"type":"quote","text":"是故圣人不治已病，治未病；不治已乱，治未乱，此之谓也。夫病已成而后药之，乱已成而后治之，譬犹渴而穿井，斗而铸锥，不亦晚乎！","source":"《黄帝内经·素问·四气调神大论》"},{"type":"quote","text":"夫治未病者，见肝之病，知肝传脾，当先实脾，四季脾旺不受邪，即勿补之。中工不晓相传，见肝之病，不解实脾，惟治肝也。","source":"《金匮要略·卷上·藏府经络先后病脉证第一》"},{"type":"quote","text":"热病已愈，时有所遗者，何也？岐伯曰：诸遗者，热甚而强食之，故有所遗也。若此者，皆病已衰而热有所藏，因其谷气相薄，两热相合，故有所遗也。……病热当何禁之？岐伯曰：病热少愈，食肉则复，多食则遗，此其禁也。","source":"《黄帝内经·素问·热论》"},{"type":"callout","variant":"info","title":"温馨提示","text":"本页所述养生与治未病内容属传统医学知识介绍，不能替代临床诊疗。个体化调养方案（如具体食疗、药膳、导引功法与剂量）须由执业医师结合体质与病情面诊后确定；慢性病与老年人群尤应遵医嘱，切勿自行用药。"},{"type":"keypoints","title":"掌握要点","items":["治未病三层次：未病先防、既病防变、瘥后防复，核心是“防患于未然”。","养生的根本在于法于阴阳、和于术数、食饮有节、起居有常、不妄作劳。","既病防变重在早期干预与前瞻性顾护未受邪之脏，如“见肝之病，知肝传脾，当先实脾”。","病后防复的关键是清余邪、节饮食、慎劳倦、适寒温、畅情志。"]},{"type":"paragraph","text":"治未病的思想使中医在健康促进、疾病预防与康复医学三个环节上贯通无阻，也与《素问·上古天真论》所描述的“上古圣人，春秋皆度百岁”的理想形成呼应。现代人将其落实为规律作息、均衡饮食、适度运动、调畅情志与定期体检，正是这一古老智慧的现实转化。"}]}]}},"classics":{"page":{"key":"classics","title":"经典医籍","subtitle":"十九部中医古典文献","description":"收录《黄帝内经》《难经》《伤寒论》《金匮要略》《神农本草经》《本草纲目》等十九部中医古典医籍，附原文摘录、要点解析与文献地位介绍。","lead":"中医典籍是历代医家智慧的结晶，也是当代临床与研究的根基。本页收录知识库中十九部古典医籍，逐部介绍其成书年代、作者、卷数、文献地位与内容贡献，并摘录原典要句以见其风貌。所述均为公有领域文献，供学习研究参考，不能替代医师面诊与处方。","type":"collection","icon":"fa fa-scroll","items":[{"id":"huangdi-neijing","title":"《黄帝内经》","subtitle":"成书于战国至秦汉·黄帝岐伯问答·今分《素问》《灵枢》二书","category":"基础理论","tags":["四大经典","阴阳五行","藏象经络","治未病"],"meta":[{"label":"成书年代","value":"约战国至秦汉之际，非一时一人之作"},{"label":"作者","value":"托名黄帝与岐伯问答，实为历代医家累积编纂"},{"label":"卷章节数","value":"现存《素问》八十一篇、《灵枢》八十一篇，共一百六十二篇"},{"label":"文献地位","value":"现存最早的中医医学典籍，中医四大经典之一，奠定了中医学理论体系的根本框架"}],"image":"","imageHint":"内经","summary":"《黄帝内经》是中国现存最早的中医理论巨著，以黄帝与岐伯问答的形式，系统总结了战国以前及秦汉之际的医学成就。全书以阴阳五行学说为总纲，奠定藏象、经络、气血津液、病因病机、四诊、治则等中医基本理论；提出「阴平阳秘」「上工治未病」等经典命题，确立「整体观」与「辨证论治」的思路。其论运气则推演五运六气，论养生则贯通四时起居，皆为后世所宗。它不仅是中国医学的理论源头，也是世界医学史上最早的系统性医学文献之一，影响远及日本、朝鲜与欧美学界，至今仍是研习中医者必读的根本经典。","blocks":[{"type":"paragraph","text":"《黄帝内经》成书于战国至秦汉之际，由历代医家长期累积编纂而成，托名黄帝与岐伯问答。全书分《素问》与《灵枢》两部，各八十一篇。《素问》偏重于理论，论阴阳五行、藏象经络、病因病机、诊法与治则；《灵枢》偏重于临床与操作，详论经脉腧穴、针刺刺法、脏腑病形与诊断方法。它并非一家之言，而是先秦医学知识的总汇，因此被后世尊为「医家之宗」，是中医四大经典中最早的一部。"},{"type":"paragraph","text":"在理论建构上，《内经》以阴阳为纲，以五行为目，建立了完整的藏象学说：心主血脉而藏神、肺主气司呼吸而朝百脉、脾主运化升清而统血、肝主疏泄而藏血、肾藏精主水而纳气；又以十二经脉与奇经八脉构建运行气血、联络脏腑的通路。病因学上提出六淫与七情内伤，发病机制上以「邪气盛则实，精气夺则虚」概括正邪相争；诊断上强调四诊合参，辨证上确立八纲雏形；治则上提出「治病必求于本」「以平为期」，并首创「治未病」思想。可以说，中医所有的理论分支都能在《内经》中找到源头。"},{"type":"cards","columns":3,"items":[{"icon":"☯","title":"阴阳五行的总纲","text":"以阴阳之理统摄天地万物，是中医哲学思想的根基。","bullets":["阴阳者，天地之道也","阴平阳秘，精神乃治","四时五行，以生长收藏"]},{"icon":"🫀","title":"藏象经络体系","text":"五脏六腑的功能系统与十二经脉的运行通路。","bullets":["心者，君主之官","经脉者，所以能决死生、处百病、调虚实","奇经八脉为十二经之补充"]},{"icon":"🔎","title":"诊法与治则","text":"望闻问切四诊合参，八纲辨证与治病求本。","bullets":["善诊者，察色按脉，先别阴阳","谨察阴阳所在而调之，以平为期","有其在标而求之于标，有其在本而求之于本"]}]},{"type":"table","caption":"《内经》两大部类的内容分布","head":["部类","篇数","理论重心","代表篇章"],"rows":[["《素问》","八十一篇","医学基本理论、藏象经络、病因病机、诊法治则、运气学说","阴阳应象大论、上古天真论、灵兰秘典论、至真要大论、四气调神大论"],["《灵枢》","八十一篇","经脉腧穴、针刺刺法、脏腑病形、诊断与病机","经脉、经别、九针十二原、本神、决气、营卫生会、五色"]]},{"type":"quote","text":"阴阳者，天地之道也，万物之纲纪，变化之父母，生杀之本始，神明之府也。治病必求于本。","source":"《黄帝内经·素问·阴阳应象大论》"},{"type":"paragraph","text":"《内经》的另一项重大贡献是确立了整体医学的思维模式。它把人体置于天地万物之中考察，提出「天人相应」「五运六气」的周期性医学理论；强调脏腑经络相互关联，形成「藏象—经络—气血」一体的功能模型；主张「形神合一」，将情志活动纳入病理与养生范畴。这些思想使中医不是头痛医头、脚痛医脚，而是从整体联系中把握病机，至今仍指导着临床辨证与养生实践。"},{"type":"table","caption":"《内经》主要学说对后世的影响","head":["学说","《内经》原文","后世传承"],"rows":[["治未病","圣人不治已病，治未病；不治已乱，治未乱","形成未病先防、既病防变、瘥后防复的完整养生观"],["整体观","五脏相通，移皆有次","脏腑辨证与经络辨证的理论基础"],["四诊合参","察色按脉，先别阴阳；视喘息，听音声","望闻问切四诊合参的诊断原则"],["标本治则","知标本者，万举万当，不知标本，是谓妄行","急则治标、缓则治本、标本兼治的取舍依据"],["情志致病","怒伤肝、喜伤心、思伤脾、忧伤肺、恐伤肾","七情内伤学说与情志调摄养生法"],["养生摄生","法于阴阳，和于术数，食饮有节，起居有常","顺应四时、调畅情志、节欲保精的养生原则"]]},{"type":"quote","text":"上古之人，其知道者，法于阴阳，和于术数，食饮有节，起居有常，不妄作劳，故能形与神俱，而尽终其天年，度百岁乃去。","source":"《黄帝内经·素问·上古天真论》"},{"type":"paragraph","text":"历代对《内经》的注释与研究文献极多，隋唐有杨上善《太素》、王冰次注《素问》，宋以后林亿等奉敕校定《素问》《难经》，明清则有张介宾《类经》、吴昆《素问吴注》、王士雄《温热经纬》等。理解《内经》，既需借助注家释义以明字词训诂，又须把握其整体精神而不拘泥字句；其理论至今仍为中医教育与临床的基本出发点。"}]},{"id":"nanjing","title":"《难经》","subtitle":"战国·秦越人（扁鹊）·原名《黄帝八十一难经》","category":"基础理论","tags":["四大经典","脉学","经络腧穴","问答释难"],"meta":[{"label":"成书年代","value":"约成书于战国至东汉间，托名扁鹊问答"},{"label":"作者","value":"旧题战国秦越人（扁鹊）撰，历代学者多认为系后儒补缀《内经》之作"},{"label":"卷章节数","value":"三卷八十一难，内容分论脉、脏腑、经络、疾病、穴道、针法六类"},{"label":"文献地位","value":"与《内经》并称中医四大经典，在脉学与经络学说上补《内经》之未备"}],"image":"","imageHint":"难经","summary":"《难经》全称《黄帝八十一难经》，以八十一个问答解释《内经》疑难，故名难经。相传为战国名医秦越人（扁鹊）所撰，实际约成书于东汉。书中首创独取寸口以诊全身脏腑的寸口诊脉法，系统阐明脏腑、经脉、奇经八脉、腧穴与针法，并提出「命门」「三焦有名而无形」「原气之别焉」等新说，弥补了《内经》在脉诊精度与脏腑定位上的不足。八十一难条条精要，甫一问即有一答，义理贯通，被后世奉为与《内经》比肩的经典，对脉诊、命门学说与经络腧穴临床影响深远，历代注家迭出，研习者至今不绝。","blocks":[{"type":"paragraph","text":"《难经》全称《黄帝八十一难经》，共八十一难，以黄帝与扁鹊（或曰岐伯）问答的形式写成。它的成书与《内经》有密切关系，历代医家多认为系后人据《内经》文义撰为问答以释疑解难，故书名中有「黄帝」而托名扁鹊。全书体裁简洁，条文精要，甫一问而辄有一答，义理贯通，在中医经典中别具一格。"},{"type":"paragraph","text":"《难经》的理论贡献主要有三方面。其一是**脉学**：《难经·论脉·一难》提出「十二经皆有动脉，独取寸口，以决五脏六腑死生吉凶之法」，确立以腕部寸口为诊脉要位的寸口诊脉法，并规定寸、关、尺三部与脏腑配属，成为后世脉诊的准绳；其四是脏腑定位，提出「肾两者，非皆肾也。其左者为肾，右者为命门」，开命门学说之先河，又论三焦「有名而无形」「主持诸气」，为后世命门、三焦理论提供依据；其三是**经络腧穴**，详论奇经八脉的循行、主病与八会穴，补充了《内经》之未备；此外还提出「泻南方，补北方」等治则，被后世丹溪学派奉为圭臬。"},{"type":"table","caption":"《难经》八十一难的内容分类","head":["类别","难数范围","核心内容","代表论述"],"rows":[["论脉","第一难至第二十二难","寸口诊脉、三部九候、脉的阴阳属性与脏腑分野","独取寸口以决死生吉凶；尺寸之脉一息四至五至"],["论经络","第二十三难至第二十九难","经脉度数、奇经八脉循行与病候、十五络","奇经八脉不拘于十二经；八会穴的提出"],["论脏腑","第三十难至第四十七难","三焦、营卫、五脏七神、命门、脏腑表里","三焦者，水谷之道路，气之所终始也"],["论病","第四十八难至第六十一难","疾病传变、脏腑病候、脉证死生、五邪","诊之有病者，脉沉滑者病在藏；脉浮滑者病在腑"],["论穴道","第六十二难至第六十八难","腧穴主治、五脏六腑原穴","五脏有疾，当取之十二原"],["论针法","第六十九难至第八十一难","迎随补泻、针刺深浅与得气、泻南补北","泻南方，补北方"]]},{"type":"cards","columns":3,"items":[{"icon":"🫀","title":"独取寸口","text":"确立腕部寸口为全身脏腑脉诊之要位。","bullets":["一呼脉行三寸，一吸脉行三寸","关前为阳、关后为阴","寸口者，脉之大会"]},{"icon":"🔗","title":"奇经八脉","text":"系统论述八奇经的起止、循行与病候。","bullets":["八脉皆不拘于经","阳维维于阳，阴维维于阴","冲脉为十二经脉之海"]},{"icon":"🕳","title":"命门与三焦","text":"首倡右肾为命门、三焦有名而无形之说。","bullets":["男子以藏精，女子以系胞","三焦主持诸气，有名而无形","原气之所系也"]}]},{"type":"quote","text":"十二经皆有动脉，独取寸口，以决五脏六腑死生吉凶之法，何谓也？然：寸口者，脉之大会，手太阴之脉动也。……寸口者，五脏六腑之所终始，故法取于寸口也。","source":"《难经·论脉·一难》"},{"type":"paragraph","text":"《难经》的临床价值历久不衰。宋代王惟一奉敕校定《难经本义》，滑寿作《难经本义阐注》，近代又有多种注本与研究专著。今天中医诊断学教材中关于寸口分诊脏腑、脉证死生、奇经八脉病候的内容，基本都以《难经》为依据。学习《难经》，既要注意它与《内经》的继承关系，也要看到它在脉诊精确化、命门学说与经络补全上的独创贡献——正是这种既承又创的特点，使它与《内经》并列为中医四大经典。"},{"type":"table","caption":"《难经》重要命题及其后世影响","head":["命题","原文","后世意义"],"rows":[["寸口诊脉","十二经皆有动脉，独取寸口，以决五脏六腑死生吉凶","成为寸口脉诊法的经典依据，延续至今"],["命门","其左者为肾，右者为命门。命门者，诸神精之所舍，原气之所系也","命门学说之滥觞，明清温补派赖以立论"],["三焦","三焦者，水谷之道路，气之所终始也；有原气之别焉，主持诸气，有名而无形","三焦概念由部位描述转向功能定位"],["奇经八脉","有阳维、阴维、阳跷、阴跷、冲、督、任、带之脉，凡此八脉者，皆不拘于经","奇经八脉学说定型，指导针灸与方药归经"],["原气三焦","五脏六腑之本，十二经脉之根，呼吸之门，三焦之原","强调下焦与元气的关系，为温补肾命门张目"],["泻南补北","泻南方，补北方","成为后世滋阴降火法的理论依据"]]},{"type":"quote","text":"经言是动者，气也；所生病者，血也。邪在气，气为是动；邪在血，血为所生病。气主呴之，血主濡之。气留而不行者，为气先病也；血壅而不濡者，为血后病也。","source":"《难经·论脉·二十二难》"},{"type":"paragraph","text":"从文献学角度看，《难经》篇幅虽小而信息密度极高，八十一难几乎条条都是临床与理论的枢纽。它对经脉长度的具体计算（总计一十六丈二尺）、对五脏六腑原穴的明确规定、对营卫运行「五十而复大会」的量化描述，都把《内经》的原则性论述落到了可操作的层面。读《难经》宜与《内经》对读：先明《内经》之理，再看《难经》如何补其未备、密其未精，方能体会中医理论层层递进的构建过程。"}]},{"id":"shanghan-lun","title":"《伤寒论》","subtitle":"东汉·张仲景撰·十卷·外感热病辨证论治专书","category":"临床方书","tags":["四大经典","辨证论治","六经辨证","方剂之祖"],"meta":[{"label":"成书年代","value":"东汉末年，约公元200年前后"},{"label":"作者","value":"张机（字仲景），南阳人，后世尊为医圣"},{"label":"卷章节数","value":"十卷，计《辨脉法》《平脉法》《伤寒例》及六经辨治诸篇，另附《辨不可发汗病脉证并治》等八篇"},{"label":"文献地位","value":","}],"image":"","imageHint":"伤寒论","summary":"《伤寒论》由东汉张仲景撰述，是我国第一部系统阐述外感热病辨证论治的专书。全书以六经辨证为纲，将外感病过程中由表入里、由浅入深的病机演变，与汗、吐、下、和、温、清等治法方药严密对应，提出「辨证论治」的完整思路，开后世「同病异治、异病同治」之先河。其方剂配伍严谨、剂量规范，被后世尊为「方书之祖」，其中仅载方剂即达一百一十二首，并详载煎服、禁忌与病后护理之法。仲景之方至今仍被广泛使用，宋以后奉为太医之圣、医门之宗，历代医家奉为圭臬，其所确立的辨证思路影响远超中医一域。","blocks":[{"type":"paragraph","text":"《伤寒论》原名《伤寒杂病论》，东汉末年张仲景（名机，字仲景，南阳人）所撰。原书经西晋王叔和整理，隋唐以后分列为两部：《伤寒论》专论外感热病，《金匮要略》专论杂病。经历代医家增补（如宋代林亿校正、赵开美复刻），现行本为宋本《伤寒论》十卷。《伤寒论》以六经辨证为总体框架：太阳主表、阳明主里、少阳主半表半里、太阴主脾胃虚寒、少阴主心肾虚衰、厥阴主寒热错杂，配以八纲辨证为具体内容，形成六经与八纲互相配合的辨证体系。"},{"type":"paragraph","text":"《伤寒论》的核心贡献是**辨证论治**的创立。它把同一病因所致疾病在不同个体、不同阶段的差异，用六经证候加以区分，形成「同病异治」的思路；又指出不同病因可导致相同证候，须「异病同治」。在具体内容上，全书以条文加方剂的形式载方一百一十二首，用药精简、配伍严谨，如桂枝汤、麻黄汤、葛根汤、小柴胡汤、四逆汤、真武汤、炙甘草汤、白虎汤、大承气汤等，至今仍为临床常用。此外还首载煎服法、禁忌与病后调理，对后世方剂学、药物学影响极为深远。"},{"type":"cards","columns":3,"items":[{"icon":"🧭","title":"六经辨证","text":"以六经概括外感病由表入里的六个阶段与病性。","bullets":["太阳为表，阳明为里","少阳为半表半里","太阴少阴厥阴属里与半里"]},{"icon":"⚖","title":"八纲辨证","text":"在六经纲领下以表里寒热虚实阴阳细析证候。","bullets":["阴阳为总纲","表里定病位，寒热定病性","虚实定邪正盛衰"]},{"icon":"💊","title":"经方群","text":"载方一百一十二首，被尊为「方书之祖」。","bullets":["六经各方随证加减","剂量与煎服法规范","附方后禁忌与护理"]}]},{"type":"table","caption":"《伤寒论》六经辨证提纲","head":["六经","病位与病性","主要脉证","治法代表方"],"rows":[["太阳病","风寒束表，营卫失和","恶寒发热、头项强痛、无汗或自汗、脉浮紧或浮缓","麻黄汤、桂枝汤、葛根汤、大青龙汤"],["阳明病","里热炽盛或胃肠燥实","身热、汗自出、不恶寒反恶热、脉洪大或沉实","白虎汤、大承气汤、小承气汤、麻子仁丸"],["少阳病","邪在半表半里","往来寒热、胸胁苦满、默默不欲饮食、心烦喜呕","小柴胡汤、蒿芩清胆汤"],["太阴病","脾胃虚寒，中阳不振","腹满而吐、食不下、自利不渴、时腹自痛","理中汤、小建中汤"],["少阴病","心肾虚衰，阳气内衰或阴虚火旺","脉微细、但欲寐、四肢逆冷或心烦不得卧","四逆汤、真武汤、黄连阿胶汤"],["厥阴病","寒热错杂，阴阳格拒","消渴、气上撞心、心中疼热、饥不欲食、蛔厥","乌梅丸、当归四逆汤"]]},{"type":"quote","text":"少阴之为病，脉微细，但欲寐也。","source":"《伤寒论·辨少阴病脉证并治》"},{"type":"paragraph","text":"《伤寒论》的方药运用体现出高度的整体与平衡观念。如桂枝汤以桂枝、芍药一散一收，调和营卫；四逆汤以生附子、干姜、炙甘草回阳救逆；小柴胡汤以柴胡、黄芩和解少阳、升降相因。其用药主张顾护胃气，具体规定服药后啜热粥、温覆取微汗等护理方法，并强调病在胸膈以上者先食后药、病在心腹以下者先药后食的服药次第。这些经验至今仍是提高疗效与避免误治的重要参考。"},{"type":"table","caption":"《伤寒论》主要方剂举例","head":["方名","组成要点","主治","配伍意义"],"rows":[["桂枝汤","桂枝、芍药、生姜、大枣、炙甘草","太阳中风，营卫不和之自汗恶风","桂枝辛温助卫解肌，芍药酸敛养营，一散一收调和营卫"],["麻黄汤","麻黄、桂枝、杏仁、炙甘草","太阳伤寒，风寒束表之无汗恶寒","麻黄开腠发汗，桂枝助解肌，杏仁降气，甘草和中"],["小柴胡汤","柴胡、黄芩、半夏、生姜、人参、大枣、甘草","少阳证，往来寒热、胸胁苦满","柴胡疏解少阳之邪，黄芩清少阳之热，半夏、生姜和胃降逆"],["白虎汤","石膏、知母、粳米、甘草","阳明气分热盛，大热、大汗、大渴、脉洪大","石膏辛寒清热，知母苦润滋阴，粳米甘草护胃"],["四逆汤","生附子、干姜、炙甘草","少阴病阳衰阴盛，四肢逆冷、脉微欲绝","附子温壮元阳，干姜温中复阳，甘草缓和姜附之烈"],["炙甘草汤","炙甘草、生姜、人参、生地黄、桂枝、阿胶、麦冬、麻仁、大枣","伤寒脉结代、心动悸、虚羸少气","气血阴阳并补，以炙甘草益气养心，配伍滋阴养血之品"]]},{"type":"quote","text":"凡脉大、浮、数、动、滑，此名阳也；脉沉、涩、弱、弦、微，此名阴也，凡阴病见阳脉者生，阳病见阴脉者死。","source":"《伤寒论·辩脉法》"},{"type":"paragraph","text":"《伤寒论》的版本源流值得留意：宋本《伤寒论》与桂林古本、康平本等在条文与方药数量上存在差异，日本传入的《康平本》更接近原貌。国内现行教材多采宋本。因原书文字简约古奥，学习时须借助于成无己《伤寒论明理论》、柯琴《伤寒来苏集》、尤怡《伤寒金匮要略心典》、刘渡舟《伤寒论校注》等注家之书，方能读通字义、把握方证相应的关系。"}]},{"id":"jingui-yaolue","title":"《金匮要略》","subtitle":"东汉·张仲景《伤寒杂病论》杂病部分·三卷二十五篇","category":"临床方书","tags":["四大经典","方书之祖","杂病辨治","治未病"],"meta":[{"label":"成书年代","value":"东汉末年，与《伤寒论》同源，原书名《伤寒杂病论》"},{"label":"作者","value":"张机（张仲景），后经王叔和整理、宋代林亿校订"},{"label":"卷章节数","value":"三卷二十五篇，载病六十余种、方剂二百六十二首、附方若干"},{"label":"文献地位","value":"现存的杂病专书，被誉为「方书之祖」，与《伤寒论》合称「金匮伤寒」"}],"image":"","imageHint":"金匮","summary":"《金匮要略》是东汉张仲景《伤寒杂病论》中杂病部分，经王叔和整理、宋代林亿校订而成的现存杂病专书。全书三卷二十五篇，按病分篇，载病六十余种、方二百六十二首，涉及内外妇儿、痰饮、水气、黄疸、疟疾、虚劳、妇人病等。它首倡「治未病」与「辨证论治」，所载方剂配伍精当、剂量考究，被誉为「方书之祖」，其中如栝蒌薤白白酒汤、枳实薤白桂枝汤、桂枝芍药知母汤、肾气丸、大黄䗪虫丸等至今常用。","blocks":[{"type":"paragraph","text":"《金匮要略》原是张仲景《伤寒杂病论》的后半部分，专论杂病。成书后长期散佚，经西晋王叔和整理始得流传，宋代林亿奉敕校正、编入《金匮玉函要略方》，金代成无己、朱肱等校订，明代赵以德《金匮方论》始将「金匮要略」之名用于书名，遂定型为今日通行本。全书三卷二十五篇，每篇以病为纲，先论病机脉证而后出方治，与《伤寒论》的六经辨证体例相区别。"},{"type":"paragraph","text":"《金匮要略》的学术价值突出表现在三个方面。第一是**首创治未病**：《藏府经络先后病脉证第一》提出「上工治未病，何也？师曰：夫治未病者，见肝之病，知肝传脾，当先实脾」，确立了既病防变的整体观，并列出「千般疢难，不越三条」的病因归类。第二是**建立杂病辨证体系**：如痰饮病以「当以温药和之」为总则，水气病分风水、皮水、石水、里水，妇人病设妊娠、产后、杂病三篇，皆成体系。第三是**方药精纯**：《金匮》载方二百六十二首，用药多在十味以内，剂量比例明晰，煎服法与服后护理详备，如服桂枝汤后啜热稀粥、温覆取微汗，被视为中药剂型与服法的经典范例。"},{"type":"cards","columns":3,"items":[{"icon":"🛡","title":"治未病先声","text":"首篇即论治未病与病因三分，为中医预防思想奠基。","bullets":["见肝之病，知肝传脾，当先实脾","千般疢难，不越三条","痼疾加以卒病，当先治其卒病"]},{"icon":"💧","title":"杂病分科","text":"痰饮、水气、黄疸、疟病、虚劳等各成专篇。","bullets":["痰饮：当以温药和之","水气：分风水皮水石水里水","妇人：妊娠产后杂病三分"]},{"icon":"💊","title":"方书之祖","text":"载方二百六十二首，配伍严谨、剂量考究。","bullets":["经方用量精确到分两","重视顾护胃气与服药护理","后世众多方剂以此为基础化裁"]}]},{"type":"table","caption":"《金匮要略》二十五篇病类分布","head":["卷次","篇名（部分）","主要病类"],"rows":[["卷上","藏府经络先后病、痉湿暍、百合狐惑阴阳毒、疟病、血痹虚劳、中风历节、奔豚、胸痹心痛短气、肺痿肺痈咳嗽上气","病机总论与内科杂病"],["卷中","痰饮咳嗽、水气、黄疸、消渴小便不利淋病、五藏风寒积聚、惊悸吐血下血胸满瘀血、腹满寒疝宿食、呕吐哕下利","水液代谢病与消化系统病"],["卷下","妇人妊娠、妇人产后、妇人杂病、疮痈肠痈浸淫、趺蹶手指臂肿转筋阴狐疝蛔虫、杂疗方、果实菜谷禁忌","妇科、外科、杂病与食疗禁忌"]]},{"type":"quote","text":"问曰：上工治未病，何也？师曰：夫治未病者，见肝之病，知肝传脾，当先实脾，四季脾旺不受邪，即勿补之。中工不晓相传，见肝之病，不解实脾，惟治肝也。","source":"《金匮要略·卷上·藏府经络先后病脉证第一》"},{"type":"paragraph","text":"《金匮要略》的方药运用以「和」为贵：病邪在表则微汗、在里则通下、在上则吐、在半表半里则和解；痰饮则温化、水气则通阳化气、虚劳则建中缓中、瘀血则祛瘀生新、黄疸则分清泄浊、妇人病则养血调经。这种因势利导、不伤正气的用药风格，与《伤寒论》的峻汗峻下形成互补。书末专列「果实菜谷禁忌并治」「禽兽鱼虫禁忌并治」两篇，把食疗与饮食禁忌纳入方书体系，是研究唐代以前饮食卫生与食物中毒的重要史料。"},{"type":"table","caption":"《金匮要略》代表方剂与主治","head":["方名","组成要点","主治病证","辨证要点"],"rows":[["栝蒌薤白白酒汤","栝蒌实、薤白、白酒","胸痹，喘息咳唾、胸背痛、短气","胸阳不振、痰浊痹阻，脉沉迟、关上小紧数"],["枳实薤白桂枝汤","枳实、厚朴、薤白、桂枝、栝蒌实","胸痹，心中痞留、气结在胸","胸阳不振兼气滞痞满，胁下逆抢心"],["桂枝芍药知母汤","桂枝、芍药、知母、防风、附子、白术、甘草、生姜","风湿历节，身体疼烦、肿痛、关节屈伸不利","风湿痹阻兼化热，方中桂芍附子与知母并用"],["肾气丸","干地黄、山药、山茱萸、泽泻、茯苓、牡丹皮、桂枝、附子","虚劳腰痛，小便不利，肢体酸痛","肾阳不足、水湿内停，益火之源以消阴翳"],["苓桂术甘汤","茯苓、桂枝、白术、甘草","心下有痰饮，胸胁支满、目眩","中阳不足、饮邪上冲，温药和之之代表"],["大黄䗪虫丸","大黄、黄芩、甘草、桃仁、杏仁、芍药、干地黄、干漆、虻虫、水蛭、蛴螬、土鳖虫","五劳虚极羸瘦，腹满不能饮食","瘀血内停、虚劳夹杂，取缓中补虚、攻瘀生新之义"]]},{"type":"quote","text":"师曰：病人脉浮者在前，其病在表；浮者在后，其病在里，腰痛背强不能行，必短气而极也。","source":"《金匮要略·卷上·藏府经络先后病脉证第一》"},{"type":"paragraph","text":"研读《金匮要略》，宜与《伤寒论》对读：《伤寒论》重在阐明外感病传变与治法，《金匮要略》重在杂病的脉证方治与病机。二者同出一源而各擅胜场，后世合称「金匮伤寒」，构成中医临床的经典处方库。历代注家众多，如宋代成无己《金匮要略方》、宋代赵以德《金匮方论》、清代尤怡《金匮要略心典》、徐彬《金匮要略论注》、陈修园《金匮要略浅注》，以及日本汤本求真《金匮要略方论》等，理解其方证相应的关键，正在于把条文与病机、与方药三者合起来读。"}]},{"id":"shennong-bencao-jing","title":"《神农本草经》","subtitle":"东汉集结成书·托名神农·载药三百六十五种","category":"本草药物","tags":["四大经典","本草学","三品分类","七情和合"],"meta":[{"label":"成书年代","value":"约成书于东汉，托名神农，经历代医家增益"},{"label":"作者","value":"非一人一时之作，托名「神农」以示其古，后世多认为系秦汉药物知识累积编成"},{"label":"卷章节数","value":"全书三卷，按玉石、草、虫、木、果、谷、米等分部，载药三百六十五种"},{"label":"文献地位","value":"现存最早的本草学专著，中医四大经典之一，开创三品分类与七情和合之法"}],"image":"","imageHint":"神农","summary":"《神农本草经》是我国现存最早的本草学专著，托名神农著，成书于东汉。书中载药三百六十五种，创立上、中、下三品分类法，以「主治病」与「永年益寿」为标准区分层次，并明确提出药物配伍的「七情」——单行、相须、相使、相畏、相恶、相反、相杀，以及「有毒无毒」的用药安全观念。其体例「录本草，载药名，标产地，述气味、主治、别名校注」，奠定了历代本草书的编写范式。书中所载药物的性味主治多经长期临床检验而沿用至今，如麻黄、大黄、附子、半夏、柴胡、黄连等，其功效认识与后世基本一致。","blocks":[{"type":"paragraph","text":"《神农本草经》简称《本经》，是最早的一部本草专著，载药三百六十五种，恰合周天三百六十五度之说。全书三卷，按药物自然属性分为玉石、草、虫、木、果、谷、米等七类，每药先记气味主治，次及产地、别名与校注，记述简练而内容可靠，为后世本草学所沿用。书中首创上、中、下三品分类法，把药物的用途与毒性一并规定，又首提单行、相须、相使、相畏、相恶、相反、相杀的「七情」配伍原则与「有毒无毒」的安全观念，历代医家不断增益修订，至梁代陶弘景《本草经集注》增入《名医别录》内容，才形成今本体系。"},{"type":"paragraph","text":"《本经》的三大理论贡献是：**三品分类**——上品「主养命以应天，无毒，多服久服不伤人」，中品「主养性以应人，有毒无毒，斟酌其宜」，下品「主治病以应地，多毒，不可久服」，把药物的用途与毒副作用一并规定，这是世界药学史上最早的药物分级思想之一；**七情和合**——《千金要方》引述其配伍原则为「有单行者，有相须者，有相使者，有相畏者，有相恶者，有相反者，有相杀者」，指出「当用相须、相使者良，勿用相恶、相反者」，明确反对某些不合配伍；**药性记述**——每药标注性味与主治，如丹沙「味甘、微寒，主身体五藏百病，养精神，安魂魄，益气，明目」，成为后世「性味归经」理论的源头。此外书中还提出药物产地与采收时节的重要性，并注意到同名异物与形态变异问题。"},{"type":"cards","columns":3,"items":[{"icon":"🥇","title":"三品分类","text":"按功效与毒性分上中下三品，兼论久服之宜忌。","bullets":["上品养命，多服久服不伤人","中品养性，有毒无毒斟酌其宜","下品治病，多毒不可久服"]},{"icon":"⚗","title":"七情和合","text":"首提药物配伍七种关系，确立合和用药原则。","bullets":["单行、相须、相使","相畏、相杀、相恶、相反","当用相须相使，勿用相恶相反"]},{"icon":"📖","title":"体例奠基","text":"药名、气味、主治、产地、别名五项俱全的记载格式。","bullets":["一药一条，文字简约","标注明产地与采收时节","注意形态变异与同名异物"]}]},{"type":"table","caption":"《神农本草经》三品分类内容","head":["品级","功效定位","毒性规定","代表药物举例","用法则度"],"rows":[["上品","主养命以应天","无毒，多服久服不伤人","人参、甘草、地黄、人参、茯苓、丹沙、麦门冬","可久服，轻身益气不老延年"],["中品","主养性以应人","有毒无毒，斟酌其宜","当归、白芍、黄芩、枸杞、菊花、白术","视体质病情酌用，不宜久服"],["下品","主治病以应地","多毒，不可久服","巴豆、附子、乌头、芫花、甘遂、大戟、砒霜","用于治病，中病即止"]]},{"type":"quote","text":"丹沙，味甘、微寒。主身体五藏百病，养精神，安魂魄，益气，明目，杀精魅邪恶鬼。久服，通神明不老。能化为汞，生山谷。","source":"《神农本草经·上品·玉石部·丹沙》"},{"type":"paragraph","text":"《本经》的药物记载虽简，却保存了大量汉代以前药物学的真实成就。如载有麻黄（治风寒头痛、温疟）、大黄（通大便、破癥瘕积聚）、附子（回阳救逆、止痛）、半夏（咳逆气上、咽喉肿痛）、柴胡（心腹肠胃中结气）、黄连（目痛眦伤、肠澼腹痛）等，其功效认识与后世基本一致，经长期临床检验至今有效。《本经》中关于「四时采造」「阴干暴干」的炮制要求，以及「产地决定药效」的产地观念，也是后世道地药材理论之源。"},{"type":"table","caption":"《本经》各部类代表药物","head":["部类","药物举例","主要功效取向"],"rows":[["玉石部","丹沙、玉泉、云母、朴消、矾石、磁石、禹余粮","重镇安神、软坚散结、化石通淋"],["草部","人参、黄芪、白术、茯苓、甘草、当归、川芎、菊花、麦门冬、天麻","补虚扶正、理气活血、解表清热"],["木部","桂枝、厚朴、枳实、橘皮、杜仲、柏子仁、干姜、吴茱萸","温里散寒、理气宽中、强筋健骨"],["果部","桃仁、杏仁、枇杷叶、茱萸、山茱萸、橘核","活血化瘀、降气止咳、收敛固涩"],["米谷部","粳米、黍米、麦、稻米、粟米、豉","益气养胃、和中除烦、解表除烦"]]},{"type":"quote","text":"上药一百二十种，为君，主养命以应天。无毒，多服、久服不伤人。欲轻身益气，不老延中药一百二十种，为臣，主养性以应人。有毒无毒，斟酌其宜。欲遏病，补虚羸者，本中经。下药一百二十五种，为佐使，主治病以应地，多毒，不可久服。欲除寒热邪气，破积聚、愈疾者，本下经。三品合三百六十五种，法三百六十五度，每一度应一日，以成一岁。","source":"《千金要方·诸论·论用药第六》（引《神农本草经》药例）"},{"type":"paragraph","text":"《神农本草经》在中国药学史上的地位，如同《内经》在中医理论史上的地位。它首创的「药有个性与主治」「药有君臣佐使」「药有毒无毒」等观念，至今仍是中药学的基本原理；它与《伤寒论》相配合，形成「理法方药」的完整体系，孙思邈所谓「夫经方之难精，由来尚矣」正说明经方必须以《本经》药性为基础。今天学习中药，仍应从《本经》的性味主治入手，再结合后世各家本草的补充与修正，方能全面把握药物的运用。"}]},{"id":"bencao-gangmu","title":"《本草纲目》","subtitle":"明·李时珍撰·五十二卷·一五九〇年刊","category":"本草药物","tags":["本草学","药物分类","考据训诂","医方集成"],"meta":[{"label":"成书年代","value":"明万历六年（1578）成书，万历十八年（1590）金陵刊行"},{"label":"作者","value":"李时珍（字东璧，号濒湖），蘄州人，出身世医之家"},{"label":"卷章节数","value":"五十二卷，载药一千八百九十二种、收集医方一万一千零九十六首、绘图一千一百六十幅"},{"label":"文献地位","value":"中国古代药物学的集大成之作，达尔文称之为「中国古代的百科全书」，今译名世界影响广泛"}],"image":"","imageHint":"纲目","summary":"《本草纲目》是明代李时珍历时二十七年编成的药物学巨著，五十二卷，载药一千八百九十二种、医方一万一千余首、插图一千一百六十幅。全书按「析族区类，振纲分目」的方法分为十六部六十类，纠正了《神农本草经》以来药物分类混乱、重复与错置的弊病；每药依次列释名、集解、气味、主治、方论等项，兼收医药学、植物学、动物学、矿物学、民俗学与历史文献学内容，其百科性质为世所公认。","blocks":[{"type":"paragraph","text":"《本草纲目》由李时珍编撰，父子两代历时二十余年，李时珍本人曾行医采药、遍访山野、访求四方士人，亲自检视药材实物，故书中所载药名、形态与产地多有亲历实证。成书后几经修改，至万历十八年金陵胡承龙刻本刊行，即今日通行本。全书五十二卷，卷一至卷二为序例、历代诸家本草与图谱，卷三至卷四十二为正文，载药一千八百九十二种，附药一千余种，另收医方一万一千余首、插图一千一百六十幅。"},{"type":"paragraph","text":"《本草纲目》的核心创新在分类体系。它以「部」为纲、「类」为目，建立十六部六十类的自然分类系统：水部、火部、土部、金石部、虫部、鳞部、介部、禽部、兽部、人部、草部、谷部、菜部、果部、木部、器服部。这一体系在当时是世界上最进步的药物分类法，使《本经》以来混乱的品类得以理顺，纠正了同类药物重复、异类药物错置的弊病。此外李时珍于每药之下依次列释名、集解、气味、主治、方论等项，并以「发明」一项表达作者个人的考据与临床心得，是本草编撰的重大革新。"},{"type":"cards","columns":3,"items":[{"icon":"🗂","title":"析族区类","text":"十六部六十类的自然分类体系，纲举目张。","bullets":["水火土金石、虫鳞介禽兽人","草谷菜果木器服","同类归部、异类分目，纠正旧误"]},{"icon":"📑","title":"八项著录","text":"释名、集解、辨疑、气味、主治、发明、方论、附药。","bullets":["集解广引诸家之说","辨疑正前人之误","发明载个人心得与考据"]},{"icon":"🌍","title":"博物学价值","text":"兼收动物、植物、矿物、民俗与历史知识。","bullets":["考姓氏与名物之沿革","参物理与形状之实见","附方言俗名与民间疗法"]}]},{"type":"table","caption":"《本草纲目》十六部分类概览","head":["部名","涵盖内容","部名","涵盖内容"],"rows":[["水部","井泉、雨水、露水、霜雪、冰等","虫部","蝉、蜈蚣、斑蝥、蜣螂、蜜蜂等"],["火部","艾火、炭火、灯火、熨火等","鳞部","龙、蛇、鲤、鲫、鳝、鳖等"],["土部","黄土、伏龙肝、灶心土、蚯蚓泥等","介部","龟甲、鳖甲、牡蛎、蛤蚧、蚌等"],["金石部","金、银、铜、铁、石、丹砂、雄黄等","禽部","鸡、鸭、鹅、雀、鹰、鹤等"],["草部","人参、黄芪、甘草、当归、地黄等千余种","兽部","虎、狼、鹿、羊、猪、狗等"],["谷部","粳米、黍、麦、粟、菽、芝麻等","人部","人尿、人乳、童便、人指甲等"],["菜部","韭、葱、姜、蒜、葵、蕨等","果部","梅、杏、桃、梨、橘、枣、葡萄等"],["木部","桑、桂、柏、榆、槐、柚、沉香等","器服部","金银器、镜鉴、剪刀、灯盏等"]]},{"type":"quote","text":"释名：亦名黄参、血参、人衔、鬼盖、神草、土精、地精、海腴、皱面还丹。气味：(根)甘、微寒、无毒。","source":"《本草纲目·草部·人参》"},{"type":"paragraph","text":"《本草纲目》的另一重要贡献是对前人记载的严谨考辨。李时珍在「辨疑」与「发明」中，订正了大量误传：指出《本经》上品丹砂「久服通神明不老」实为方士之言而不可信；辨明「古方二术通用，后人始有苍、白之分」，厘清白术与苍术之别；考证地黄有生地、熟地之异；并对陶弘景《本草经集注》、陈藏器《本草拾遗》、李珣《海药本草》、朱震亨《本草衍义补遗》等前代本草的得失一一评骘。这一广征博引、订正前误的编纂方针，使全书具备了很高的文献可靠性。"},{"type":"table","caption":"《本草纲目》对前代本草的辨正举例","head":["药物","旧说","李时珍辨正"],"rows":[["术","古方二术通用","术有白术、苍术两种，一般用「术」字则指白术；苍术为后来分出"],["丹沙","《本经》称久服通神明不老","案《说文》《列仙传》《抱朴子》，指出古人有服之致死者，今人和肉食服之转以成疾，不可疑古书之虚证"],["云母","云母有五种，各有时服之宜","引《抱朴子·仙药》说明五色云母与四时服法，考其名物出于《说文》"],["玉泉","临死服五斤，死三年色不变","引郑玄、周礼、玉篇诸说辨正，谓当得璞玉乃可用，已成之器伤人"]]},{"type":"quote","text":"今人和肉食服之，遂多相反，转以成疾，不可疑古书之虚证。","source":"《神农本草经·上品·玉石部·丹沙》"},{"type":"paragraph","text":"《本草纲目》的世界影响极为深远。十七世纪即有英、法、德等多种译本与选本传入欧洲，达尔文在其著作中多次引用《本草纲目》关于中国药物的记载，李约瑟亦盛誉其为「辉煌的成就」。今天所用的《中华人民共和国药典》与中药学教材，其药物分类与著录格式仍多承其绪余。李时珍遍访山野、亲验药材的治学态度，以及他以近三十年之功编成此书的坚韧精神，至今仍是医者的榜样。"}]},{"id":"binhu-maixue","title":"《濒湖脉学》","subtitle":"明·李时珍·二十七脉·以歌括体例阐释脉象","category":"临床方书","tags":["脉学","诊法","歌诀体","四诊合参"],"meta":[{"label":"成书年代","value":"明嘉靖年间，约1530年前后"},{"label":"作者","value":"李时珍（号濒湖），晚年据其《脉要精微论》阙疑与《奇经八脉考》而作"},{"label":"卷章节数","value":"一卷，载二十七脉（附二十八脉之说），各脉系以体状诗、相类诗、主病诗，末附《四言举要》"},{"label":"文献地位","value":"明代流传最广、影响最大的脉学专著，为后世脉学教本与临床必读之书"}],"image":"","imageHint":"脉学","summary":"《濒湖脉学》是明代李时珍所著的脉学专著，李时珍号濒湖，故名。全书一卷，以歌诀体例系统阐述二十七种脉象，每脉分「体状诗」（描述脉形）、「相类诗」（辨析与相近脉的区别）、「主病诗」（列举所主病证）三部分，末附《四言举要》综述诊脉原理与部位。文字简练押韵，便于记诵，成为明清以来脉学教学与临床的通行读本。其中「相类诗」的辨析功夫尤足称道，如以「浮脉惟从肉上行，如循榆荚似毛轻」写浮脉轻清在上之象，而临床脉象常相兼出现，非此辨析不能准确把握主病。李时珍又反复强调四诊合参，不可凭一脉定病。","blocks":[{"type":"paragraph","text":"《濒湖脉学》约成书于明嘉靖年间，是李时珍晚年的作品，为其脉学专论。全书体例极为精炼：先以《四言举要》综述脉的原理、部位、诊法与脏腑分部，然后分述二十七脉。每脉下设三首诗——体状诗描述脉象的具体形态与指下感觉，相类诗辨别本脉与形似脉的区别，主病诗列举该脉所主的病证，末附《气口九道脉》以别异经。这种以韵文入医的写法，便于习诵记忆，被后世奉为脉学入门与临床实用的经典，明清以来脉学教本多本于其说。"},{"type":"paragraph","text":"在内容上，《濒湖脉学》既有对《内经》《难经》脉学理论的继承与整理，也有李时珍的独立心得。其二十七脉为浮、沉、迟、数、虚、实、细、洪、滑、涩、弦、紧、促、结、代的常见脉象，另附伏、动、革、牢、革、濡、弱、微、散、芤、伏、动、促、结、代、疾等二十八脉之说，主要采自《脉经》而有所取舍，尤以「相类诗」最能体现其辨析功夫：如以「浮脉惟从肉上行，如循榆荚似毛轻」写浮脉的轻清在上之象，以「水行润下脉来沉，筋骨之间软滑匀」写沉脉的重按而得，与《内经》「脉者，血之府也」的认识相贯通。李时珍又特别强调「四诊合参」，反对仅凭脉象定病。"},{"type":"cards","columns":3,"items":[{"icon":"🎼","title":"二十七脉","text":"浮沉迟数虚实等二十七种基本脉象，各具三诗。","bullets":["体状诗：写脉形与指下感觉","相类诗：辨形似之脉","主病诗：列所主病证"]},{"icon":"📏","title":"诊脉部位","text":"寸关尺三部与脏腑配属，为脉诊之基础。","bullets":["关前为阳，关后为阴","心肝居左，肺脾居右，肾居两尺","寸候胸上，关候膈下，尺候脐下"]},{"icon":"🔗","title":"四诊合参","text":"强调脉象须与望闻问互相参证。","bullets":["脉有七诊，曰浮中沉","脉之浮沉及人迎与寸口气小大等者，病难已","气如橐钥，血如波澜"]}]},{"type":"table","caption":"《濒湖脉学》部分脉象提要","head":["脉象","体状（指下特征）","相类脉辨别","主病"],"rows":[["浮","举之有余，按之不足，如循榆荚似毛轻","浮大中空是芤，拍拍而浮是洪，浮而无力为芤","主表证；浮而有力多风热，无力而浮是血虚"],["沉","重手按至筋骨乃得，如绵里砂内刚外柔","沉细如绵真弱脉，弦长实大是牢形","主里证；沉而有力里实，无力里虚"],["迟","一息不足四至，来去徐缓","与缓脉、涩脉相别","主寒证；迟而有力属实寒，无力属虚寒"],["数","一息六至，脉流薄疾","与疾脉、促脉相别","主热证；数而有力属实热，细数属阴虚"],["滑","往来流利，应指圆滑，如盘走珠","与涩脉相反，与痰脉相关","主痰湿、食积、实热，亦见妇人妊娠"],["弦","端直以长，如按琴弦","与紧脉、革脉相别","主肝胆病、痛证、痰饮、疟疾"]]},{"type":"quote","text":"脉乃血脉，气血之先，血之隧道，气息应焉。其象法地，血之府也，心之合也，皮之部也。资始于肾，资生于胃，阳中之阴，本乎营卫，营者阴血，卫者阳气，营行脉中，卫行脉外，脉不自行，随气而至，气动脉应，阴阳之义。","source":"《濒湖脉学·四言举要》"},{"type":"paragraph","text":"《濒湖脉学》的教学价值与临床实用价值同样突出。历代中医基础教材的脉诊部分，几乎全本于《濒湖脉学》的描述与歌诀，如「浮脉惟从肉上行」「沉脉重手按至筋骨」「滑脉如珠替替然，往来流利却还前」「弦脉端直以长」等表述今日仍被直接使用。其「相类诗」的辨析思路尤其重要——临床上脉象常相兼出现，如沉迟、弦滑、细数，只有通过相类辨别才能准确把握主病。李时珍在《四言举要》中还提出「脉有七诊，曰浮中沉，上下左右，消息求寻」，为脉诊的手法与体位确立了规范。"},{"type":"table","caption":"《四言举要》诊脉部位与脏腑配属","head":["部位","左手","右手","主候范围"],"rows":[["寸部","心（膻中）","肺（胸中）","寸候胸上：心肺、膻中、胸喉"],["关部","肝胆","脾胃","关候膈下：肝胆、脾胃"],["尺部","肾（阴）","肾（阳）","尺候脐下至跟：肾、膀胱、胞宫、大腹"]]},{"type":"quote","text":"浮脉惟从肉上行，如循榆荚似毛轻。三秋得令知无恙，久病逢之却可惊。……沉潜水畜阴经病，数热迟寒滑有痰，无力而沉虚与气，沉而有力积并寒。","source":"《濒湖脉学·浮（阳）》《濒湖脉学·沉（阴）》"},{"type":"paragraph","text":"需要说明的是，脉诊是四诊之一而非全部。《濒湖脉学》本身即以歌诀反复强调脉象须与神色、形体、声音、二便、病史合参，李时珍在《四言举要》中明确指出「脉之浮沉及人迎与寸口气小大等者，病难已」，又在主病诗中说明同一脉象可主多种病、同一疾病又可见多种脉象。因此临床必须坚持四诊合参，不可凭一脉定病、不可凭寸口脉象机械推断全身气血。这是学习本书时最应把握的尺度。"}]},{"id":"qijing-bamai-kao","title":"《奇经八脉考》","subtitle":"明·李时珍·专论任督冲带与四维四跷","category":"基础理论","tags":["经络学说","奇经八脉","任督二脉","针灸推拿"],"meta":[{"label":"成书年代","value":"明嘉靖三十四年（1555）成书，刊于《本草纲目》后"},{"label":"作者","value":"李时珍（号濒湖）"},{"label":"卷章节数","value":"一卷，分八脉各论、总说、维脉为病、二跷为病、气口九道脉、释音等篇"},{"label":"文献地位","value":"现存系统专论奇经八脉的著作，补《内经》《难经》之未详，为针灸与方药归经的重要依据"}],"image":"","imageHint":"八脉","summary":"《奇经八脉考》是明代李时珍所著的经络学专著，一卷。书中专论任脉、督脉、冲脉、带脉、阴跷、阳跷、阴维、阳维八条奇经的循行路线、腧穴位置、主治病候，并引《内经》《难经》《脉经》《千金方》诸家之说与张洁古、李东垣等医家论述互证。书中以「正经犹夫沟渠，奇经犹夫湖泽」比喻奇经调节十二经气血盛衰的作用，并讨论奇经与养生、丹道的关系，是研究奇经八脉的权威文献。此书直接推动了针灸临床中对八脉交会穴（公孙、内关、后溪、申脉、足临泣、外关、阳交、阴交）的重视，也影响了明清以来的方剂归经理论。","blocks":[{"type":"paragraph","text":"《奇经八脉考》成书于明嘉靖三十四年，是李时珍在《濒湖脉学》之后、刊行《本草纲目》之前的经络学专论。全书一卷，体例是先列八脉各自的循行与腧穴，再分述各脉为病之证候，末附《气口九道脉》与《释音》。李时珍自谓「参考诸说，萃集于左，以备学仙、医者，筌蹄之用云」，意在把散见于《内经》《难经》《脉经》《千金方》及后世诸家中的奇经资料集中考订，兼资医道与养生之用。全书以乾坤、东西、南北、六合分属八脉功能，汇诸家方药治验，是研究奇经八脉的权威文献。"},{"type":"paragraph","text":"全书的核心命题是奇经八脉与十二经的关系。李时珍指出「奇经八脉者∶阴维也、阳维也、阴跷也、阳跷也、冲也、任也、督也、带也」，并以乾坤、东西、南北、六合分属其功能：阳维主一身之表、阴维主一身之里，阳跷主一身左右之阳、阴跷主一身左右之阴，督主身后之阳、任冲主身前之阴，带脉横束诸脉。他继承《难经》之喻，指出「正经之脉隆盛，则溢于奇经」，故奇经有调节十二经气血盛衰、蓄溢调节的作用，并说「医不知此，罔探病机」。在临床应用上，书中广泛收录张洁古、李东垣、丹溪等家治疗奇经病证的方药经验，使此书兼具理论与实用价值。"},{"type":"cards","columns":3,"items":[{"icon":"🕸","title":"八脉归属","text":"以乾坤、东西、南北、六合分论八脉功能。","bullets":["阳维主表、阴维主里","阳跷主左之阳、阴跷主左之阴","督主身后、任冲主身前、带束诸脉"]},{"icon":"💧","title":"溢蓄调节","text":"正经隆盛则溢于奇经，奇经以调平十二经。","bullets":["正经犹沟渠，奇经犹湖泽","流溢之气转相灌溉","内温脏腑，外濡腠理"]},{"icon":"🩺","title":"临床采方","text":"汇集诸家治奇经病证的方药与刺灸法。","bullets":["张洁古论阳维阴维证治","李东垣论冲脉逆气","列出各脉腧穴与主治"]}]},{"type":"table","caption":"《奇经八脉考》八脉功能与主病","head":["奇经","循行要点","功能归属","主要病候"],"rows":[["督脉","起于会阴，循背而行于身之后，入属于脑","阳脉之总督，阳脉之海","脊强而厥、腰痛、阳痿、疟疾"],["任脉","起于会阴，循腹而行于身之前，至咽喉","阴脉之承任，阴脉之海，主胞胎","男子七疝、女子瘕聚、妇人病、妊娠病"],["冲脉","起于气冲，并足阳明经夹脐上行，至胸中而散","十二经脉之海、血海","逆气而里急、气上冲心、少腹痛、崩漏"],["带脉","起于季胁，回身一周","横束诸脉，总约诸经","腹满、腰溶溶若坐水中、妇人带下"],["阴跷脉","起于跟中，循内踝上行，至咽喉交贯冲脉","主一身左右之阴，司机关跷捷","阳缓而阴急、嗜睡、不寐、癫狂"],["阳跷脉","起于跟中，循外踝上行，入风池","主一身左右之阳，司机关跷捷","阴缓而阳急、失眠、癫痈"],["阴维脉","起于诸阴之交，发于足少阴筑宾穴","维络一身之阴，维系诸阴经","心痛、悒然失志、癫狂"],["阳维脉","起于诸阳之会，由外踝而上行于卫分","维络一身之阳，维系诸阳经","寒热、头痛、胁痛、疟疾"]]},{"type":"quote","text":"奇经八脉者∶阴维也、阳维也、阴跷也、阳跷也、冲也、任也、督也、带也。……是故阳维主一身之表，阴维主一身之里，以乾坤言也。阳跷主一身左右之阳，阴跷主一身左右之阴，以东西言也。督主身后之阳，任、冲主身前之阴，以南北言也。带脉横束诸脉，以六合言也。是故医而知乎八脉，则十二经、十五络之大旨得矣。","source":"《奇经八脉考·八脉》"},{"type":"paragraph","text":"《奇经八脉考》在经络学说史上的地位十分重要。此前奇经八脉的记载散见于《内经》《难经》《脉经》《针灸甲乙经》等书，李时珍首次为之专立一书，系统整理其循行、腧穴与病候，使奇经从零散条文变为完整体系。这一整理直接推动了针灸临床中对八脉交会穴（公孙、内关、后溪、申脉、足临泣、外关、阳交、阴交）的重视，也影响了明清以来的方剂归经理论——如四逆汤治少阴病而通阳维、建中汤治阴维之痛等用药思路，皆与奇经学说相关。"},{"type":"table","caption":"《奇经八脉考》辑录的诸家论述","head":["来源","所论内容","要点"],"rows":[["《难经》","奇经为病","阳维维于阳、阴维维于阴，阴阳不能自相维则怅然失志；阳维病苦寒热，阴维病苦心痛"],["《灵枢》","冲脉为病","气逆上，刺膺中陷下者，与下胸动脉；腹痛，刺脐左右动脉"],["张洁古","阳维阴维证治","卫为阳主表，故阳维受邪为病在表；营为阴主里，故阴维受邪为病在里"],["李东垣","冲脉逆气证治","秋冬胃脉四道为冲脉所逆，气上冲、咽不得息而喘息有音，宜调中益气汤加吴茱萸"],["孙思邈","气冲证治","咳唾手足厥逆，气从小腹上冲胸咽，宜茯苓五味子汤"],["李濒湖","冲脉与痿厥","冲脉为经脉之海，主渗灌溪谷，与阳明合于宗筋，会于气街"]]},{"type":"quote","text":"奇经凡八脉，不拘制于十二正经，无表里配合，故谓之奇。盖正经犹夫沟渠，奇经犹夫湖泽，正经之脉隆盛，则溢于奇经。故秦越人比之∶天雨降下，沟渠溢满，霈妄行，流于湖泽，此发灵、素未发之秘旨也。八脉散在群书者，略而不悉。医不知此，罔探病机；仙不知此，难安炉鼎。","source":"《奇经八脉考·奇经八脉总说》"},{"type":"paragraph","text":"《奇经八脉考》还有一个常被忽略的特点，是它对养生与内丹的记载。书中引张紫阳《八脉经》说八脉「俱属阴神，闭而不开，惟神仙以阳气冲开，故能得道」，强调阴跷为一身关键，「此脉才动，诸脉皆通」，并描述「真气聚散，皆从此关窍」的养生体验。李时珍对此持审慎态度，指出丹书之说「稍与医家之说不同」，同时又肯定「内景隧道，惟返观者能照察之」。这一以医理参证养生的取向，使本书兼具文献与思想史价值。"}]},{"id":"qianjin-yaofang","title":"《千金要方》","subtitle":"唐·孙思邈·三十卷·六百五十二年成书","category":"临床方书","tags":["临床百科全书","医德","食疗养生","妇科儿科"],"meta":[{"label":"成书年代","value":"唐永徽三年（652）成书，永淳二年（683）尚未完成"},{"label":"作者","value":"孙思邈（号真人、隐士，享年逾百），京兆华原人"},{"label":"卷章节数","value":"三十卷，五十三万字，载方五千余首，论诊、治、妇人、少小婴孺、养性、食疗、针灸等"},{"label":"文献地位","value":"中国现存最早的医学临床百科全书，兼收唐代以前各家诊治经验，被后世尊为「千金方」"}],"image":"","imageHint":"千金","summary":"《千金要方》是唐代孙思邈所撰的医学巨著，三十卷，五十三万字，载方五千余首，被誉为中国最早的临床医学百科全书。全书以「大医精诚」与「大医习业」两篇开篇，强调医德规范与医者学养；内容涵盖诸科诊疗、针灸、养生、食疗、禁咒等，尤以妇人、少小婴孺两卷最具开创性。孙思邈主张「食疗不愈，然后命药」，并首载脚气病专卷，开创了内科专科之先河。其价值不仅在于集唐以前医学之大成，更在于确立了中医医德的规范与专科分科的雏形，至今仍是医学伦理教育与临床参考的重要读本。","blocks":[{"type":"paragraph","text":"《千金要方》又称《备急千金要方》，唐代孙思邈撰于永徽三年（652），至永淳二年（683）尚未全部完成，后由其学生整理传世。全书三十卷，五十三万字，卷一为序例，含《论大医习业》《论大医精诚》《论治病略例》《论诊候》《议处方》《论用药》《论合和》《论服饵》等篇，从学医、医德、诊法、方药、服法到养生均有系统论述；卷二至卷二十三为诸科疾病（首列风毒脚气、诸风、痈疽、备急、食忌、养性等）；卷二十四至卷二十八为妇人、少小婴孺两科；卷二十九为针灸；卷三十为养性、导引与食疗。"},{"type":"paragraph","text":"《千金要方》的价值首先体现在**医德规范**上。《论大医精诚》提出「凡大医治病，必当安神定志，无欲无求，先发大慈恻隐之心，誓愿普救含灵之苦」，要求医者「普同一等，皆如至亲之想」，并从仪表、言语、行为、着装、乃至不得炫耀声名訾毁同行等细节规范医德，此篇被誉为中医医德的奠基之作，被后世尊为「大医精诚篇」。其次体现在**专科化**上：脚气病专列一卷并详述其证候与治法，开创了内科专科先河；妇人、少小婴孺各成体系，是最早的妇产科与儿科分科记载。其三是**食疗与养生**：《食治方》《养性》诸篇强调「食疗不愈，然后命药」，主张「食不厌精，脍不厌细」，并记录了大量食疗方、服食禁忌与导引法。"},{"type":"cards","columns":3,"items":[{"icon":"🕯","title":"大医精诚","text":"中医医德的奠基之作，规范医者的学养与操守。","bullets":["安神定志，无欲无求","普同一等，皆如至亲之想","不得自逞俊快、邀射名誉"]},{"icon":"👣","title":"脚气专卷","text":"首列风毒脚气专卷，开内科专科之先河。","bullets":["详述脚气证候分型","创用谷米、外敷诸法","反对服金石强药之弊"]},{"icon":"🍲","title":"食疗养生","text":"食疗不愈，然后命药；系统整理食治与养性。","bullets":["食治方载食疗方数百首","养性篇论服食与导引","强调食不厌精、脍不厌细"]}]},{"type":"table","caption":"《千金要方》卷次内容大要","head":["卷次","内容","价值"],"rows":[["卷一","序例：习业、精诚、治病略例、诊候、处方、用药、合和、服饵、药藏","确立医德、诊疗程序与方药规范，为全书总纲"],["卷二至卷四","风毒脚气、诸风、痈疽发背、备急用方、食忌调养","脚气专科与急救、食忌之早期专论"],["卷五至卷十七","伤寒、脏腑、消渴、疔肿、痈疽、备急等诸科","汇集前代与当代经验方五千余首"],["卷十八至卷二十三","养性、辟谷、退居、补益、脏腑、筋骨、养性调补","养生与补益方剂之集成"],["卷二十四至二十八","妇人上中下三卷、少小婴孺上中下三卷","最早的妇产科与儿科分科体系"],["卷二十九至卷三十","针灸、按摩、导引、食治、养性","针灸与食疗养生之专门论述"]]},{"type":"quote","text":"凡大医治病，必当安神定志，无欲无求，先发大慈恻隐之心，誓愿普救含灵之苦。若有疾厄来求救者，不得问其贵贱贫富，长幼妍媸，怨亲善友，华夷愚智，普同一等，皆如至亲之想。","source":"《千金要方·诸论·论大医精诚第二》"},{"type":"paragraph","text":"在方药学上，《千金要方》提出「凡药有君臣佐使，以相宣摄，合和者，宜用一君、二臣、三佐、五使」，并完整保存了《神农本草经》的药物配伍七情与「三品」分类，明确「当用相须、相使者良，勿用相恶、相反者」。服药法上规定「凡服汤欲得稍热服之，即易消下不吐」，并详述服药时间与病位的关系——「病在胸膈以上者，先食而后服药；病在心腹以下者，先服药而后食；病在四肢血脉者，宜空腹而在旦；病在骨髓者，宜饱满而在夜」，还提醒服药期间「皆断生冷酢滑，猪犬鸡鱼，油面蒜及果实等」，这些经验至今仍有临床参考价值。"},{"type":"table","caption":"《千金要方》药性分类与配伍原则","head":["项目","内容","临床意义"],"rows":[["药物分品","上药一百二十种主养命，中药一百二十种主养性，下药一百二十五种主治病","确立药有个性与毒性分级"],["七情和合","单行、相须、相使、相畏、相恶、相反、相杀","规范药物配伍的宜忌"],["君臣佐使","宜用一君、二臣、三佐、五使","方剂组成原则的经典表述"],["煎服法","汤药宜稍热服；病位与服药时间相应","提高疗效、减少药后不适"],["服药禁忌","忌生冷、滑腻、腥膻及特定食物配伍","防止药食相碍与不良反应"]]},{"type":"quote","text":"仲景曰∶人体平和，唯须好将养，勿妄服药。药势偏有所助，令人脏气不平，易受外患。……夫为医者，当须先洞晓病源，知其所犯，以食治之。食疗不愈，然后命药。药性刚烈，犹若御兵。兵之猛暴，岂容妄发，发用乖宜，损伤处众。","source":"《千金要方·食治方·序论第一》"},{"type":"paragraph","text":"孙思邈还是中国医学史上少见的「百科型」医家，除医学著述外，其《大医习业》要求学者「必须谙《素问》《甲乙》《黄帝针经》、明堂流注、十二经脉、三部九候、五脏六腑、表里孔穴、本草药对」，兼通五经三史诸子与天文五行，形成了他「博极医源、精勤不倦」的治学风格。今人讨论其学术特点，亦常举《千金要方》中脏腑理论结合经络腧穴、以脏腑辨证指导针灸取穴的内容为例。总之，《千金要方》既是一部临床百科全书，也是一部医德教科书与养生手册，其「大医精诚」一篇，至今仍是医学伦理教育的重要读本。"}]},{"id":"shiliao-bencao","title":"《食疗本草》","subtitle":"唐·孟诜撰、张鼎增补·三卷·载二百六十余种食疗品","category":"养生食疗","tags":["食疗","药食同源","本草学","唐代饮食"],"meta":[{"label":"成书年代","value":"唐开元年间（约713—741年）成书，张鼎于天宝年间增补"},{"label":"作者","value":"孟诜（邈），陈州人，张鼎（道士）增补"},{"label":"卷章节数","value":"三卷，二百二十七条，载食疗品二百六十余种"},{"label":"文献地位","value":"现存最早的食疗专书，是《千金要方·食治》与《外台秘要》食疗部分的主要来源"}],"image":"","imageHint":"食疗","summary":"《食疗本草》是唐代孟诜所撰、张鼎增补的食疗专著，全书三卷，载食疗品二百六十余种，是我国现存最早的食疗专书。书中记载各类食物的性味、功效、主治、禁忌与单验方，强调「药食同源」，主张有病先以食疗，食疗不愈再行用药；并广泛搜集民间食疗经验与西域药物知识，对后世食疗、药膳与养生文献影响深远，宋代《太平圣惠方》《本草纲目》均大量采录其内容。书中对食物的炮制、服食季节与体质禁忌均很重视，如黄精须「九蒸九曝」以去其刺激性、鸡子「动风气，不可多食」，这类记载既保存古代经验，也提示食物与药物同样需要辨证使用。","blocks":[{"type":"paragraph","text":"《食疗本草》由唐代孟诜（邈）撰于开元年间，其后由道士张鼎增补，故《旧唐书·艺文志》著录为《食疗本草》三卷，张鼎增补后仍称《食疗本草》，全书三卷、二百二十七条，载食物二百六十余种。内容按食物分类编排，先记性味、主治与功效，再列单方、验方与禁忌，每条以「〔证〕」「〔嘉〕」等标记注明文献出处，是研究唐代食疗与本草源流的重要文献。其所载多为盐、姜、地黄、菊花、黄精、薏苡仁、胡麻、赤小豆、鸡、羊、牛乳等日常之物，却均按本草体例考其功效主治，充分体现了「药食同源」的思想，与孙思邈「食疗不愈，然后命药」的主张互为表里。"},{"type":"paragraph","text":"《食疗本草》的学术贡献有三。其一是**确立药食同源观念**：书中所载多为日常食物如盐、姜、地黄、菊花、黄精、薏苡仁、胡麻、赤小豆、鸡、羊、牛乳等，却均按本草体例标明性味、主治与宜忌，说明食物亦可入药疗疾，这与孙思邈「食疗不愈，然后命药」的主张互为表里。其二是**保存大量唐代以前经验**：许多条目引《肘后方》《广济方》《食疗本草》等前代文献，如「地黄」条下以少蜜煎或浸食、主齿痛唾血折伤，「薏苡仁」条下「去干湿香港脚，大验」，皆为古代食疗的原始记录。其三是**补充西域与民族药物知识**：如胡麻、葡萄、柰子等条目，反映了丝绸之路沿线食材与药物的传入情况，是研究唐代中西医药交流的实物文本。"},{"type":"cards","columns":3,"items":[{"icon":"🍚","title":"药食同源","text":"食物亦按本草体例标注性味、主治与禁忌。","bullets":["每条列性味与功效","附单方、验方与服法","注明禁忌与不食之例"]},{"icon":"📜","title":"文献标记","text":"以〔证〕〔嘉〕等标记注明资料来源。","bullets":["〔证〕本经／证类所出","〔嘉〕张鼎（嘉遁）所增","便于后世考订源流"]},{"icon":"🌏","title":"胡地新风","text":"记录西域传入的食材与药物，兼含民族医药经验。","bullets":["胡麻、麻子、白油麻","赤小豆、青小豆","补充外来物种知识"]}]},{"type":"table","caption":"《食疗本草》收录的食疗品举例","head":["食物","性味","功效主治","条目要旨"],"rows":[["地黄","微寒（生者寒）","生则寒，主齿痛、唾血、折伤","以少蜜煎，或浸食之，或煎汤，或入酒饮，并妙；叶可以羹"],["黄精","甘平","补虚劳、益气力，能老不饥","根叶花实皆可食，九蒸九曝；相对者为正，不对者名偏精"],["甘菊","平","主头风目眩、泪出，去烦热，利五脏","叶正月采、茎五月五日采、花九月九日采；野生苦菊不堪用"],["薏苡仁","平","去干湿香港脚","条下仅一句而效验显著，为后世薏苡仁食疗之滥觞"],["饴糖（饧糖）","甘温","补虚，止渴，健脾胃气，去留血，补中","白者以蔓菁汁煮顿服；凝强者为良，主打损瘀血"],["乌雌鸡","温，味酸，无毒","除风寒湿痹，治反胃、安胎及腹痛、折骨疼、乳痈","月蚀疮绕耳根以胆汁敷之；产后血不止以鸡子醋酒煎服"]]},{"type":"quote","text":"（一）饵黄精，能老不饥。其法∶可取瓮子去底，釜上安置令得，所盛黄精令满。密盖，蒸之。令气溜，即曝之。第二遍蒸之亦如此。九蒸九曝。凡生时有一硕，熟有三、四斗。蒸之若生，则刺人咽喉。曝使干，不尔朽坏。","source":"《食疗本草·卷上·黄精》"},{"type":"paragraph","text":"《食疗本草》的读用价值在于它把「养生」落实在可操作的日常饮食上。书中对食物的炮制、服食季节与体质禁忌均很重视，如黄精须「九蒸九曝」以去其刺激性、生者「刺人咽喉」，地黄生寒熟温须分别使用，鸡子「动风气，不可多食」，先患骨热者不可食鸡等。这类记载既保留了古代食疗的经验，也提示了食物与药物同样需要辨证使用，不可过量与不辨体质。它与《千金要方·食治方》《外台秘要》《太平圣惠方·食治类》共同构成了唐宋食疗文献的主体。"},{"type":"table","caption":"《食疗本草》的文献价值与后世流传","head":["价值维度","具体表现","后世承传"],"rows":[["早期食疗专书","现存最早以食疗为专题的药物学著作","为《千金要方·食治》《外台秘要》食疗部分的主要来源"],["药食同源实践","以本草体例记录二百六十余种食物性味功效","后世药膳、食物本草与营养食疗学的源头"],["民间经验汇集","广泛收录民间单验方与不食之例","后世《本草纲目·果部》《菜部》多采其说"],["唐代中西交流","记录胡麻、赤小豆等外来食材","研究唐代丝绸之路医药交流的原始材料"],["文献标记体例","以〔证〕〔嘉〕注明出处","被后世本草学沿用为考订药物来源的方法"]]},{"type":"quote","text":"以少蜜煎，或浸食之，或煎汤，或入酒饮，并妙。生则寒，主齿痛，唾血，折伤。叶可以羹。","source":"《食疗本草·卷上·地黄》"},{"type":"paragraph","text":"需要提醒的是，《食疗本草》所载食疗方法多属古代经验，其中部分含有时代局限（如食矿物、服石粉类），今日若要应用应取其性味功效之理，而由医师与营养师结合现代营养学知识评估安全性与适配性。书中反复强调的「不可食之」「不可多食」「先患骨热者不可食之」等禁忌，正是古人经验中最为可靠的部分，值得重视。相关食疗内容仅供传统医学知识学习参考，不能替代临床诊疗与个体化营养指导。"}]},{"id":"yaoxing-gekuo-sibaibei","title":"《药性歌括四百味》","subtitle":"明·龚廷贤撰·四卷·四百余味药性歌括","category":"本草药物","tags":["药性歌括","韵语启蒙","四百味","通俗实用"],"meta":[{"label":"成书年代","value":"明正德年间（约1515年前后）成书"},{"label":"作者","value":"龚廷贤（字瑞芝，号云林），江西金溪人"},{"label":"卷章节数","value":"四卷，收录药物四百四十余味，每味以七言或四言歌诀一首概述性味功效"},{"label":"文献地位","value":"明清以来流传最广的药性启蒙读物与临床备用药诀"}],"image":"","imageHint":"四百味","summary":"《药性歌括四百味》是明代龚廷贤编撰的药性歌诀，四卷收药四百四十余味，每味以七言或四言韵语一首概括其性味、功效与主治，如「人参味甘，大补元气，止渴生津，调营养卫」。全书文约义丰、朗朗上口，把繁复的药物知识化为便于记诵的韵文，是明清药学初学者的入门读本与临床医师的随身药诀，流传极广，影响至今。全书依药物功效分部次第编排，便于按需检索，历代《本草纲目》类方书与近现代中药学教材的「药物功效分类」思路，皆与本书一脉相承。","blocks":[{"type":"paragraph","text":"《药性歌括四百味》又名《药性歌括》，明正德年间龚廷贤所撰，收入其《万病回春》《寿世保元》等书系列之中。全书四卷，按《本草》分部次第编排，收录常用药物四百四十余味，每药列「别名」与歌诀两栏：别名栏简述异名与炮制要点，歌诀栏以七言（部分四言）韵语概括该药的性味、功效与主治，如人参「味甘，大补元气，止渴生津，调营养卫」，白术「甘温，健脾强胃，止泻除湿，兼祛痰痞」。卷首四句总纲「诸药之性，各有其功，温凉寒热，补泻宜通。君臣佐使，运用于衷，相反畏恶，立见吉凶」概括全书宗旨，又对有毒药与妊娠禁忌多有标注，韵语易记而切于实用。"},{"type":"paragraph","text":"本书的价值在于**化繁为简、便于实用**。中药学本有数百万言之众，而临床与教学实际所需者不过数百味常用药。龚廷贤以韵文方式提炼出各药最核心的性味功效要点，使初学者能迅速建立药物印象，临床医师亦能随时翻检印证。卷首总论更以「诸药之性，各有其功，温凉寒热，补泻宜通。君臣佐使，运用于衷，相反畏恶，立见吉凶」四句总括全书宗旨，又于各卷之前分述「用药剂量」「炮制须知」等基本原则。书中对有毒药物明确标出「大毒」「有毒」，并注明「孕妇忌用」「不宜久服」等警语，体现了作者对用药安全的重视。"},{"type":"cards","columns":3,"items":[{"icon":"🎵","title":"韵文体例","text":"每味药以七言或四言歌诀一首，朗朗上口。","bullets":["性味、功效、主治一歌概括","别名栏附异名与炮制","便于记诵与临床速查"]},{"icon":"📗","title":"四百余味","text":"撷取临床常用之药，构成药物学核心。","bullets":["按本草分部次第编排","补气养血清热泻火温里各类俱备","补气健脾之品最为详备"]},{"icon":"⚠","title":"安全提示","text":"对有毒药与禁忌多有明确标注。","bullets":["附子、半夏等明标有大毒","注明孕妇忌用与不宜久服","强调相反畏恶之害"]}]},{"type":"table","caption":"《药性歌括四百味》代表药性歌诀","head":["药物","歌诀原文","要点归纳"],"rows":[["人参","人参味甘，大补元气，止渴生津，调营养卫","补气第一要药，兼生津养血"],["黄芪","黄芪性温，收汗固表，托疮生肌，气虚莫少","补气升阳、固表止汗、托毒生肌"],["白术","白术甘温，健脾强胃，止泻除湿，兼祛痰痞","健脾燥湿，兼化痰理气"],["甘草","甘草甘温，调和诸药，炙则温中，生则泻火","调和诸药之总，炙生异用"],["当归","当归甘温，生血补心，扶虚益损，逐瘀生新","补血活血，调经止痛，兼润肠"],["茯苓","茯苓味淡，渗湿利窍，白化痰涎，赤通水道","健脾渗湿，白茯苓偏健脾，赤茯苓偏利水"],["白芍","白芍酸寒，能收能补，泻痢腹痛，虚寒勿与","养血敛阴柔肝止痛，酸寒之性虚寒者慎"],["附子","附子辛热，有大毒，破积逐寒，回阳救逆","回阳救逆、散寒止痛，须先煎久煎"]]},{"type":"quote","text":"诸药之性，各有其功，温凉寒热，补泻宜通。君臣佐使，运用于衷，相反畏恶，立见吉凶。","source":"《药性歌括四百味·卷一》"},{"type":"paragraph","text":"《药性歌括四百味》的另一个特色是**分类实用**。全书依药物功效分列，便于按需检索：如补气类有人参、黄芪、白术、甘草、茯苓、山药、大枣等；补血类有当归、熟地、白芍、阿胶等；清热类有黄连、黄芩、黄柏、栀子、石膏、知母等；温里类有附子、干姜、肉桂、吴茱萸等。这种编排使它不仅是记忆工具，也是初学者认识中药功效分类体系的范本。历代《本草纲目》类方书与近现代中药学教材所采用的药物功效分类，与本书的思路一脉相承。"},{"type":"table","caption":"《药性歌括四百味》的编排与体例特点","head":["体例要素","具体内容","实用价值"],"rows":[["卷首总论","诸药之性各有其功，温凉寒热补泻宜通；君臣佐使，相反畏恶","以二十四字概括药学总纲，便于记诵"],["别名栏","每药先列异名，部分附炮制方法","便于识别同名异物与规范炮制"],["歌诀栏","七言或四言韵语，一药一首","性味功效主治一目了然"],["按分部次第","依《本草》分部编排药物","保留本草学分类框架，便于对照查检"],["毒性与禁忌标注","大毒、有毒、孕妇忌用、不宜久服","提示用药安全边界"]]},{"type":"quote","text":"人参味甘，大补元气，止渴生津，调营养卫。……附子辛热，性走不守，四肢厥冷，回阳功有。……白芍酸寒，能收能补，泻痢腹痛，虚寒勿与。","source":"《药性歌括四百味·卷一》"},{"type":"paragraph","text":"需要说明的是，歌诀体便于记诵，但字简意略，同一药物的具体功效、主治病证、配伍宜忌与剂量，仍须查证《神农本草经》《本草纲目》《本经逢原》等专著并结合临床判断。同时本书所载药物与剂量已属前人经验，任何用药均须由执业医师辨证决定，尤其对有毒药物与妊娠期用药，须严格遵医嘱。本书仅供传统药学知识学习参考。"}]},{"id":"sisheng-xinyuan","title":"《四圣心源》","subtitle":"清·黄元御撰·十卷·乾隆十八年（1753）成书","category":"基础理论","tags":["天人合一","六气学说","中气升降","经典解要"],"meta":[{"label":"成书年代","value":"清乾隆十八年（1753）成书，另有乾隆十九年刊本"},{"label":"作者","value":"黄元御（字元御，一字研农，号昴亭子、扶舆老人），山东昌邑人"},{"label":"卷章节数","value":"十卷，含天人解、六气解、脉法解、劳伤解、杂病解、七窍解、疮疡解、妇人解等"},{"label":"文献地位","value":"清代「综合派」代表作，以气化说贯通《内》《难》《伤寒》《金匮》，是理解中医气机理论的重要著作"}],"image":"","imageHint":"四圣","summary":"《四圣心源》是清代黄元御所著，十卷。作者自序称「医有黄帝、岐伯、越人、仲景，四圣之书，争光日月」，故名。全书以「一气流行」为总纲，以中气为枢轴，阐发阴阳、五行、脏腑、气血、脉法、六气、劳伤、杂病、七窍、疮疡、妇人诸理，力主「阳气」与「中气」，主张治病以扶阳抑阴、调和中气为纲。书风峻峭简练，论理自出机杼，与清代主流学派多有异趣，对近代医家影响不小。书中以六气分属五脏，创制桂枝苓胶汤、黄连丹皮汤、柴胡芍药汤、术甘苓泽汤、百合五味汤、苓甘姜附汤六方，为后世所重；其学风峻峭，与清代温病学主张颇有异趣。","blocks":[{"type":"paragraph","text":"《四圣心源》由黄元御撰于乾隆十八年（1753），历时十余年而成，全书十卷，卷首为自序与《天人解》《六气解》《脉法解》《劳伤解》《杂病解》《七窍解》《疮疡解》《妇人解》等。黄元御自谓「玉楸子悯后世作者不达其意，既解《伤寒》《金匮》，乃于己巳二月，作《四圣心源》，解内外百病，原始要终，以继先圣之业」，明确以续承《内经》《难经》《伤寒论》《金匮要略》四大经典为立书宗旨，故名「四圣心源」。其论学不依傍陈规，多发前人未发之论，在清代医林中别树一帜，为「综合派」气化说的代表作。"},{"type":"paragraph","text":"《四圣心源》的理论核心是**一气流行与中气枢轴**。作者认为「阴阳未判，一气混茫。气含阴阳，则有清浊，清则浮升，浊则沉降，自然之性也。升则为阳，降则为阴，阴阳异位，两仪分焉。清浊之间，是谓中气，中气者，阴阳升降之枢轴，所谓土也」，即以脾胃中气为阴阳升降的枢纽，中气健运则木火升、金水降而病不生，中气败则「己土不升而清阳下陷，戊土不降而浊气上逆」，遂成阴虚阳虚诸证。全书以这一气机模型贯串脏腑、脉象、方药，形成严整而自洽的体系。他还以六气（厥阴风木、少阴君火、少阳相火、太阴湿土、阳明燥金、太阳寒水）配五脏，创制「桂枝苓胶汤」「黄连丹皮汤」「柴胡芍药汤」「术甘苓泽汤」「百合五味汤」「苓甘姜附汤」六方，为后世所重。"},{"type":"cards","columns":3,"items":[{"icon":"🌀","title":"一气流行","text":"以阴阳未判之一气为始，由清浊升降而分阴阳。","bullets":["清则浮升为阳","浊则沉降为阴","四象即阴阳之升降"]},{"icon":"🏛","title":"中气枢轴","text":"脾胃中气为阴阳升降之枢纽，治法以调和中气为纲。","bullets":["戊己升降全凭中气","中气一败，清阳下陷、浊气上逆","阴虚阳虚由此而来"]},{"icon":"🌬","title":"六气配脏","text":"厥阴风木、少阴君火等六气分属五脏，各立专方。","bullets":["桂枝苓胶汤治厥阴风木","黄连丹皮汤治少阴君火","术甘苓泽汤治太阴湿土"]}]},{"type":"table","caption":"《四圣心源》十卷内容与要旨","head":["卷次","篇目","核心观点"],"rows":[["卷一","天人解：五行生克、阴阳变化、脏腑生成、气血原本、五官开窍、精神化生、五气分主、五味根原、经脉起止、营气运行、卫气出入、奇经部次","以一气流行立天人相应之理"],["卷二","六气解：六气名目、偏见、风寒暑湿燥火治法","六气分脏，各立专方"],["卷三","脉法解：脉法解、寸口脉法、三部九候、寸口人迎、真藏脉义、四时脉体、浮沉大小、脏腑脉象、二十四脉","以气化之理释脉象部位"],["卷四","劳伤解：劳伤解、阴阳、阳虚、阴虚、中气、阳脱、阴脱、精神、神惊、血瘀","以中气升降论虚劳病机"],["卷五至卷十","杂病解、七窍解、疮疡解、妇人解","分科论治，附方论与方剂"]]},{"type":"quote","text":"阴阳未判，一气混茫。气含阴阳，则有清浊，清则浮升，浊则沉降，自然之性也。升则为阳，降则为阴，阴阳异位，两仪分焉。清浊之间，是谓中气，中气者，阴阳升降之枢轴，所谓土也。","source":"《四圣心源·卷一·天人解·阴阳变化》"},{"type":"paragraph","text":"《四圣心源》的另一特色是对**脏腑生成与经络**的推衍。作者以五行生克解释五脏何以生成，以「血之与气异名同类」解释营卫运行，谓「营出于中焦，卫出于上焦」，并从水火寒热立论，认为阳气之根在肾中水火之气，「无火而能令百体皆温，无水而能令五脏皆润」。在脉法方面，他主张以寸口为脉之大会，明确「心与小肠，候于左寸，肺与大肠，候于右寸。肝胆候于左关，脾胃候于右关。肾与膀胱候于两尺」，并直斥近人候大小肠于两尺为「乖谬极矣」，在清代脉学中自成一家之言。"},{"type":"table","caption":"《四圣心源》六气治法专方","head":["六气","所属脏腑","治法方名","药物组成","适应证要点"],"rows":[["厥阴风木","肝","桂枝苓胶汤","甘草、桂枝、白芍、茯苓、当归、阿胶、生姜、大枣","上热加黄芩，寒加干姜、附子；治风木内生之证"],["少阴君火","心","黄连丹皮汤","黄连、白芍、生地、丹皮","少阴病水胜火负最易生寒，若有下寒当用椒、附"],["少阳相火","三焦","柴胡芍药汤","柴胡、黄芩、甘草、半夏、人参、生姜、大枣、白芍","和解少阳，调理相火之郁"],["太阴湿土","脾","术甘苓泽汤","甘草、茯苓、白术、泽泻","健脾渗湿，治太阴湿土之证"],["阳明燥金","肺","百合五味汤","百合、石膏、麦冬、五味","润燥养阴，治阳明燥金失润"],["太阳寒水","膀胱","苓甘姜附汤","甘草、茯苓、干姜、附子","太阳病易化生湿热，若有湿热当用栀、膏之类"]]},{"type":"quote","text":"戊己升降，全凭中气，中气一败，则己土不升而清阳下陷，戊土不降而浊气上逆，此阴虚、阳虚所由来也。","source":"《四圣心源·卷四·劳伤解·阴阳》"},{"type":"paragraph","text":"研读《四圣心源》，宜注意两点。其一是**学理特色与适用边界**：黄氏论治强调阳气与中气，力主「贵阴贱阳」之反面而重阳，但书中亦详辨阴虚阳虚之证，读者须分辨其语境，不可仅取一句而概括全书；其二是**文风与体例**：全书用古奥简洁的文言写成，术语如「戊己」「太阴湿土」「厥阴风木」等须结合《内经》篇章理解，学派上属清代气化派，与当时盛行的温病学主张有相当差异，正可与《温病条辨》对照阅读，以见清代学术之两途。"}]},{"id":"zhenjiu-dacheng","title":"《针灸大成》","subtitle":"明·杨继洲撰·十卷·一六〇一年刊","category":"针灸推拿","tags":["针灸学","腧穴定位","针刺手法","医案汇编"],"meta":[{"label":"成书年代","value":"明万历二十九年（1601）刊行"},{"label":"作者","value":"杨继洲（字济时），浙江衢州人，承家传医学"},{"label":"卷章节数","value":"十卷，载腧穴三百五十九穴、针刺手法、针灸治疗各科疾病与医案三百余则"},{"label":"文献地位","value":"明代针灸学的总结性集大成之作，被后世尊为针灸学第一部综合性巨著"}],"image":"","imageHint":"大成","summary":"《针灸大成》由明代杨继洲编著，十卷，刊于万历二十九年（1601）。全书汇集《内经》《难经》《针灸甲乙经》《铜人腧穴针灸图经》《针灸资生经》等针灸文献，结合家传经验与临床体会，系统论述经络腧穴、针刺灸法、治疗各科病证与近代医案。卷一先列《针道源流》溯源针道，卷二三为《针灸直指》与《难经》辑要，卷四为《针灸聚英》诸家论述，卷末附《杂病歌括》与百证针灸歌诀，是明代针灸学的集大成之作。卷末所附《杂病歌括》《百证赋》与二百余则医案，更使其成为可直接指导临床的针灸手册，也是研究针灸临床史的重要史料。","blocks":[{"type":"paragraph","text":"《针灸大成》凡十卷，为明代浙江衢州医家杨继洲所编。卷一《针道源流》先叙针道源流，自《素问》《难经》而下，历引《甲乙经》《太素》《铜人针灸图》《存真图》《膏肓灸法》《千金方》《千金翼方》《外台秘要》《金兰循经》《济生拔萃》《针经指南》《资生经》《十四经发挥》《神应经》《针灸节要》《聚英》《针灸捷要》《玄机秘要》《小儿按摩经》《古今医统》等书，勾勒针灸学术的传承谱系，并附各家评点；卷二《针灸直指》辑录《内经》诸篇，卷三《难经》辑要，卷四《针灸聚英》汇集诸家；卷五《长洲徐氏针灸全书》载手法；卷六《针灸直指》后附杂病歌括；卷七为《急症总要》《杂病门》；卷八为《历代避忌针灸图说》；卷九《难经》《周身经穴赋》与《百证赋》；卷十为《针灸聚英》《杂病歌括》等及《小儿灸法》与《医案》二百余则。"},{"type":"paragraph","text":"《针灸大成》的学术贡献可概括为三方面：其一**汇聚古今**，把散佚于数十种医籍中的针灸理论、腧穴主治、手法操作与临床经验系统整理，如《四卷·经络论》以《内经》原文阐明经络色诊，《针灸直指·针灸方宜始论》完整保存《素问·异法方宜论》关于砭石、毒药、灸焫、微针、导引按蹻五方治法的论述；其二**规范操作**，详述进针、出针、捻转、留气、候气、得气与补泻手法，强调「神在秋毫」「气至而去之」，并提出「一退三进」的操作规范，为针刺手法教学提供范本；其三**临床实用**，卷九《百证赋》以一百零五个证候的针灸取穴歌诀、《杂病门》分列内外科病症治法、《针灸避忌》说明时间与部位禁忌，使本书成为可直接指导临床的针灸手册，并保留了大量明以前针灸医案，是研究针灸临床史的重要史料。"},{"type":"cards","columns":3,"items":[{"icon":"📚","title":"汇聚古今","text":"汇集《内经》《难经》《甲乙经》等数十家之说。","bullets":["卷一《针道源流》叙学术谱系","卷二《针灸直指》辑《内经》","卷三辑《难经》要旨"]},{"icon":"🖐","title":"手法规范","text":"详述进针、候气、得气与补泻操作。","bullets":["一退三进、慢提紧按","必先诊脉，视气之剧易","气至而有效，效之信若风之吹云"]},{"icon":"📋","title":"临床实用","text":"百证赋、杂病门与医案可直接指导临床。","bullets":["《百证赋》一百零五证取穴","《杂病门》分科列治法","附明以前针灸医案二百余则"]}]},{"type":"table","caption":"《针灸大成》卷次内容","head":["卷次","主要篇目","内容性质"],"rows":[["卷一","针道源流","叙针灸学术源流，评历代针灸文献与诸家"],["卷二","针灸直指（附针灸方宜始论）","辑《内经》针灸理论，载五方治宜之论"],["卷三","难经","辑《难经》针灸相关论述"],["卷四","针灸聚英","汇集元明诸家针灸学说与歌赋"],["卷五","长洲徐氏针灸全书","载徐凤针灸歌赋与手法操作"],["卷六","针灸直指·杂病歌括","以歌括分列诸病证治"],["卷七","急症总要·杂病门","急症与内外科病症的针灸治法"],["卷八","针灸避忌","针灸的时间、部位与人群禁忌"],["卷九","难经·周身经穴赋·百证赋","经络腧穴定位与一百零五证取穴"],["卷十","杂病歌括·小儿灸法·医案","临床歌括、儿科灸法与医案二百余则"]]},{"type":"quote","text":"故圣人杂合以治，各得其所宜。故治所以异而病皆愈者，得病之情，知治之大体也。","source":"《针灸大成·卷一·针灸直指·针灸方宜始论》"},{"type":"paragraph","text":"《针灸大成》保存了大量现已散佚的早期针灸文献，其中《针道源流》所载诸家评点，诸如对《内经》朱墨混淆、玉石相乱之评，以及对《难经》各家注本「醇疵或相乱」「滑伯仁取长弃短，折衷以己意」的分析，本身就是针灸文献考订的重要材料。同时，《针灸大成》对腧穴定位与主治的整理，承前启后地影响了清代《针灸学》（李学川）、《针灸逢源》（李学源）乃至日本针灸著述，是针灸学从《内经》时代走向明清临床手册的枢纽。"},{"type":"table","caption":"《针灸大成》针刺手法要点","head":["操作环节","《大成》要点","对应经典依据"],"rows":[["持针","正指直刺，无针左右；神在秋毫，属意病者","《内经·针解》「神在秋毫，属意病者」"],["候气","必先诊脉，视气之剧易，乃可以治","《内经·九针十二原》「凡将用针，必先诊脉」"],["候气之守","刺之微，在速迟；气之来不可逢，其往不可追","《灵枢·九针十二原》论迎随补泻"],["得气","刺之而气不至，无问其数；刺之而气至，乃去之，勿复针","《灵枢·九针十二原》"],["补泻","徐而疾则实，疾而徐则虚；随之意，若行若按，如蚊虻止","《内经·针解》《难经》补泻义"],["留针","病在筋骨者深留之，病在肌肉者浅刺之","《内经·官针》分部深浅之宜"]]},{"type":"quote","text":"《灵枢》云：凡将用针，必先诊脉，视气之剧易，乃可以治也。……刺之而气不至，无问其数，刺之而气至，乃去之，勿复针。针各有所宜，各不同形，各任其所，为刺之要。气至而有效，效之信，若风之吹云明乎若见苍天，刺之道毕矣。","source":"《针灸大成·卷一·针道源流》《针灸大成·卷四·内经补泻》"},{"type":"paragraph","text":"《针灸大成》的临床价值至今仍被广泛使用。所载腧穴主治与《百证赋》取穴，如头痛取列缺、合谷，腰痛取委中、昆仑，痰饮取丰隆、膻中诸条，多与今日针灸教材所出相近；其《杂病门》所列病症涵盖内外妇儿与急症，为针灸临床辨证取穴提供历史参照。需要说明的是，书中亦保存有少量明以前时代局限的论述与操作方法（如某些放血、禁忌、祝由内容），今日应用须取其合规合度者，并由具备资质的医师依据现行规范操作，针刺深度与手法强度须以安全为前提。"}]},{"id":"bianque-xinshu","title":"《扁鹊心书》","subtitle":"宋·窦材撰·三卷·绍兴十六年（1146）撰·托名扁鹊","category":"针灸推拿","tags":["扶阳灸法","重灸轻针","经络学说","托名古医"],"meta":[{"label":"成书年代","value":"南宋绍兴十六年（1146），清道光年间曾有重刊"},{"label":"作者","value":"窦材（窦杰），武翼郎，河北真定人，自称得扁鹊心法"},{"label":"卷章节数","value":"三卷，上卷述扶阳、灸法理论与黄帝扁鹊灸法，中卷列伤寒诸证见证，下卷载「扁鹊神方」九十四方"},{"label":"文献地位","value":"宋代针灸学派中独树一帜的扶阳派代表著作，与《黄帝内经》《难经》并称其所自出"}],"image":"","imageHint":"扁鹊","summary":"《扁鹊心书》为南宋窦材所撰，托名扁鹊，全书三卷。作者继承扁鹊「治以针灸，重在扶阳」之旨，力主「学医不知经络，开口动手便错」，强调经络为识病之源、灸法为治病之本，全书以灸法为中心，卷上详述须识扶阳、大病宜灸、禁戒寒凉、五等虚实等理论，卷中列伤寒四经见证，卷下收录「扁鹊神方」九十四方。是研究宋元以来灸法流派与扶阳学派的重要原典。其「重经络、崇灸法、戒寒凉」三大主张，与《内经》《难经》一脉相承而更为峻切，学脉后经明清张介宾、龚廷贤及近现代扶阳学派传承，近代以来又成为研究宋元针灸流派的重要原典。","blocks":[{"type":"paragraph","text":"《扁鹊心书》题宋·窦材撰，卷首有《奏玉帝青辞》《进医书表》两篇，叙其母病不效、痛心疾首，遂精究《内经》「经历十年方得灵验」，又「苦志五十余年」的学医经历。窦材自述为扁鹊传人，书中多称「扁鹊」并载《三世扁鹊》一篇，谓黄帝时扁鹊、战国秦越人、大宋窦材为「三世扁鹊」，以自重其学。全书三卷：卷上论针灸源流与扶阳、灸法理论、禁忌与虚实分等，附《黄帝灸法》《扁鹊灸法》；卷中列《太阳见证》《阳明见证》《伤寒四经见证》《太阴见证》等，附《窦材灸法》；卷下为《扁鹊神方》九十四方与《伤寒补遗》。"},{"type":"paragraph","text":"《扁鹊心书》的核心学术主张有三。其一是**重经络**：「谚云∶“学医不知经络，开口动手便错。”盖经络不明，无以识病证之根源，究阴阳之传变。如伤寒三阴三阳，皆有部署，百病十二经脉可定死生。既讲明其经络，然后用药径达其处，方能奏效」，这是全书医理的出发点。其二是**重扶阳、崇灸法**：作者认为「为医者，要知保扶阳气为本」，「人有一息气在则不死，气者阳所生也，故阳气尽必死」，主张大病宜灸、常灸关元气海命关中脘，并明确「凡大病宜灸脐下五百壮」，同时批评滥用承气汤等攻下之害。其三是**禁戒寒凉**：认为「夫四百八病，大约热者居多，寒者最少」，批评时医偏执滋阴苦寒而致「凉药冰败」之害。这三点使该书成为宋代以来灸法派与扶阳学说的源头文本，其学脉后经明清张景岳、龚廷贤及近现代扶阳学派（如卢崇汉、扶阳书院一系）传承。"},{"type":"cards","columns":3,"items":[{"icon":"🕸","title":"重经络","text":"经络为识病之源，用药取穴皆不离经。","bullets":["百病十二经脉可定死生","先明经络，再论方药","认为望诊与识病皆本于经络"]},{"icon":"🔥","title":"崇灸扶阳","text":"以灸法温补阳气，主张常灸脐下以固本。","bullets":["凡大病宜灸脐下五百壮","人至三十可三年一灸脐下三百壮","保命之法：灼艾第一，丹药第二，附子第三"]},{"icon":"⛔","title":"戒寒凉","text":"批评偏执滋阴苦寒而损伤脾胃元气。","bullets":["认为热病多而寒病少","批评凉药冰败元气之害","主张先辨阴阳再议攻补"]}]},{"type":"table","caption":"《扁鹊心书》卷次内容","head":["卷次","篇目","主要内容"],"rows":[["卷上","须识扶阳、大病宜灸、住世之法、当明经络、三世扁鹊、禁戒寒凉、时医三错、忌用转下、五等虚实、要知缓急、黄帝灸法、扁鹊灸法","针灸源流、扶阳学说、灸法操作、虚实分等与禁忌"],["卷中","太阳见证、阳明见证、伤寒四经见证、伤寒、太阴见证等，附窦材灸法","以经络见证辨六经病变，载灸法图穴"],["卷下","扁鹊神方、伤寒补遗","载方九十四首，补录伤寒证治方药"]]},{"type":"quote","text":"谚云∶“学医不知经络，开口动手便错。”盖经络不明，无以识病证之根源，究阴阳之传变。如伤寒三阴三阳，皆有部署，百病十二经脉可定死生。既讲明其经络，然后用药径达其处，方能奏效。","source":"《扁鹊心书·卷上·当明经络》"},{"type":"paragraph","text":"《扁鹊心书》的灸法论述颇具操作性。卷上《黄帝灸法》《扁鹊灸法》所载灸法多以部位与壮数标定，如「男妇虚劳，灸脐下三百壮」「男妇水肿，灸脐下五百壮」之类，并载《住世之法》中以关元、气海、命关、中脘为常灸要穴的方法，谓「一年辛苦唯三百，灸取关元功力多，健体轻身无病患」。卷下《扁鹊神方》九十四方多取温补之力，如消积丸、痰气丸、偏风丸等，多用附子、干姜、硫黄等温阳化痰之品，并自述方多「以便贫家」或为久病重证而设。这些内容是研究宋代灸法临床的珍贵一手资料。"},{"type":"table","caption":"《扁鹊心书》主要学术主张","head":["主张","原文依据","临床意义","今日辨析"],"rows":[["经络为先","学医不知经络，开口动手便错","先明经络病位，方药针灸方能径达其处","经络辨证思路至今有效"],["扶阳为本","要知保扶阳气为本；人有一息气在则不死","重视阳气与生命力的关系","与温补学派一脉相承"],["大病宜灸","凡大病宜灸脐下五百壮，补接真气","确立灸法在大病虚证中的地位","现代临床仍用于虚寒与虚劳"],["戒用寒凉","凉药不知害了多少人；元气稍虚者无不被凉药冰败而死","纠偏时医偏执滋阴之弊","属特定历史语境下的偏重，不宜绝对化"],["常灸保健","人至三十，可三年一灸脐下三百壮，令人长生不老","提出周期性灸法保健观","与灸法养生传统相承接"]]},{"type":"quote","text":"道家以消尽阴翳，炼就纯阳，方得转凡成圣，霞举飞升。……故为医者，要知保扶阳气为本。人至晚年阳气衰，故手足不暖，下元虚惫，动作艰难。盖人有一息气在则不死，气者阳所生也，故阳气尽必死。","source":"《扁鹊心书·卷上·须识扶阳》"},{"type":"paragraph","text":"阅读《扁鹊心书》需持审慎态度。一方面，它所载灸法壮数、丹药与峻烈之品，须结合现代临床规范与患者体质评估，不可径行仿效；另一方面，作者「禁戒寒凉」的偏激之论与其所处时代风尚有关，读者应理解其针对时弊的语境，不宜简单套用于一切阴虚火旺之证。《扁鹊心书》仍是理解宋元医学思想转折、灸法源流与扶阳学派源头的必读文献，其对经络与生命观的强调，至今仍具启发。"}]},{"id":"wenbing-tiaobian","title":"《温病条辨》","subtitle":"清·吴瑭撰·六卷·一七九八年成书","category":"临床方书","tags":["温病学","三焦辨证","卫气营血","养阴保液"],"meta":[{"label":"成书年代","value":"清乾隆四十三年（1778）草稿，嘉庆三年（1798）定稿刊行"},{"label":"作者","value":"吴瑭（字鞠通，号温病），江苏淮阴人"},{"label":"卷章节数","value":"六卷：上焦篇、中焦篇、下焦篇、杂说，载方约二百首，条文自编号次"},{"label":"文献地位","value":"创立三焦辨证体系，与叶天士卫气营血辨证并立，标志温病学说的独立与成熟"}],"image":"","imageHint":"温病","summary":"《温病条辨》是清代吴瑭所著，六卷，是温病学两大辨证体系之一的奠基之作。作者在叶天士卫气营血辨证的基础上创立三焦辨证，将温病分为上焦（手太阴肺）、中焦（阳明与太阴）、下焦（肝肾）三个阶段，提出「凡病温者，始于上焦，在手太阴」的传变规律，主张温病忌汗、最喜解肌，倡养阴保液，忌用辛温峻汗与苦寒攻下。书中载方约二百首，多为自创方，后世称其为「温病学之祖」。王叔和曾将温病混于《伤寒例》，张志聪、尤怡虽驳其非而未另立法；叶天士《温热论》创卫气营血辨证而语焉不详；吴瑭则以三焦辨证立其纲、定其法、选其方，使温病终有完整的理法方药体系。","blocks":[{"type":"paragraph","text":"《温病条辨》凡六卷，清乾隆四十三年（1778）吴瑭因家乡温疫大行、亲历临床而草创，历二十年修订，于嘉庆三年（1798）由汪瑟庵促其定稿刊行。全书结构为：卷一、二为上焦篇、中焦篇，卷三为下焦篇，卷四为杂说（汗论、六气论等），卷五、六为「此赵（绍基）氏原稿」及附方。按上焦、中焦、下焦三篇分论各类温病，条文自「一」「二」依次编号，条下附自注，详述病机、治法与方药。全书另列温病九种：风温、温热、温疫、温毒、暑温、湿温、秋燥、冬温、温疟，各自区别。"},{"type":"paragraph","text":"《温病条辨》的理论贡献有三。其一**创立三焦辨证**：《卷一》明确「凡病温者，始于上焦，在手太阴」，上焦为肺之逆传与心包，中焦为阳明与太阴，下焦为肝肾，从而建立温病由上而下、逐层深入的三焦传变框架；其二**辨温病与伤寒之异**：《卷一》指出「伤寒由毛窍而入，自下而上，始足太阳。……温病由口鼻而入，自上而下，鼻通于肺，始手太阴。」，并提出「伤寒伤人身之阳，故喜辛温甘温苦热，以救其阳；温病伤人身之阴，故喜辛凉甘寒甘咸，以救其阴」，以阴阳立论厘清两大学派的分野；其三**养阴保液的治法原则**：反复强调温病「最喜解肌」「忌汗」，并主张顾护津液，其《原病篇》直斥时医「不识本病之名而伪造者，因而乱治」，于名实之辨尤为留意；在白虎汤、承气汤使用上亦反复申明「脉浮者不可下」「承气非可轻尝之品」的审慎态度。"},{"type":"cards","columns":3,"items":[{"icon":"🔺","title":"三焦辨证","text":"上焦肺与心包、中焦脾胃、下焦肝肾，逐层深入。","bullets":["始于上焦，在手太阴","上焦不治则传中焦","终上焦，始下焦"]},{"icon":"🌬","title":"温病九名","text":"风温、温热、温疫、温毒、暑温、湿温、秋燥、冬温、温疟。","bullets":["各有病因病性差异","初起治法各不相同","暑温湿温温疟不在桂枝汤例"]},{"icon":"💧","title":"养阴保液","text":"温病伤阴，治宜辛凉甘寒甘咸以救其阴。","bullets":["忌汗，最喜解肌","顾护津液，慎用苦寒攻下","热病救阴犹易，通阳最难"]}]},{"type":"table","caption":"《温病条辨》三焦辨证提纲","head":["三焦","所属脏腑","主要证候","治法要点","代表方"],"rows":[["上焦","手太阴肺（兼心包）","恶风寒、头痛、微恶风寒、脉不缓不紧而动数、尺肤热、午后热甚","辛凉解表、清泄肺热、宣肺化痰；忌辛温发汗","银翘散、桑菊饮、麻杏石甘汤、清营汤"],["中焦","阳明胃与太阴脾","面目俱赤、语声重浊、呼吸俱粗、大便闭、小便涩、舌苔老黄甚则黑有芒刺、日晡益甚","清泄胃热、通腑泄热、淡渗利湿；辨脉浮沉以定白虎或承气","白虎汤、大承气汤、小承气汤、葛根芩连汤"],["下焦","足少阴肾与足厥阴肝","身热面赤、手足心热甚于手足背、口干舌燥、脉细数或虚大、舌绛少苔","滋阴增液、育阴潜阳、酸甘化阴；忌辛温劫阴","加减复脉汤、大定风珠、救阴通脉汤"]]},{"type":"quote","text":"凡病温者，始于上焦，在手太阴。伤寒由毛窍而入，自下而上，始足太阳。……温病由口鼻而入，自上而下，鼻通于肺，始手太阴。……盖伤寒伤人身之阳，故喜辛温甘温苦热，以救其阳；温病伤人身之阴，故喜辛凉甘寒甘咸，以救其阴。彼此对勘，自可了然于心目中矣。","source":"《温病条辨·卷一·上焦篇·风温、温热、温疫、温毒、冬温》"},{"type":"paragraph","text":"《温病条辨》的方药特色鲜明，多为吴氏自创且后世广泛沿用。上焦篇创**银翘散**（辛凉平剂）与**桑菊饮**（辛凉轻剂），中焦篇有**白虎汤**与**大承气汤**的温病新解，下焦篇有**加减复脉汤**、**大定风珠**等填补肾阴、息风潜阳之剂。此外吴瑭自创**化斑汤**、**清营汤**、**普济消毒饮**等，并提出银翘散煎法「香气大出，即取服，勿过煎。肺药取轻清，过煎则味浓而入中焦矣」的具体要求，对后世方剂煎服法影响深远。书中「三消饮」「加减木防己汤」等方，更开后世祛湿化浊法先河。"},{"type":"table","caption":"《温病条辨》代表方剂","head":["方名","出处","组成要点","主治","方义要点"],"rows":[["银翘散","上焦篇第四条","连翘、银花、苦桔梗、薄荷、竹叶、生甘草、芥穗、淡豆豉、牛蒡子","太阴风温、温热初起但热不恶寒而渴者","辛凉透表、清热解毒；轻清宣透，不宜过煎"],["桑菊饮","上焦篇","桑叶、菊花、杏仁、连翘、薄荷、桔梗、甘草、苇根","风温初起咳嗽为主者","辛凉解表、宣肺止咳，较银翘散更轻"],["清营汤","上焦篇","犀角、生地、玄参、竹叶心、麦冬、丹参、黄连、银花、连翘","热入营分、舌绛而干、脉数","清营解毒、透热转气；禁用咸寒滋腻"],["白虎汤","中焦篇第一条","石膏、知母、生甘草、白粳米","阳明温病脉浮洪躁甚者","辛寒清热护津；脉浮者不可下"],["加减复脉汤","下焦篇","炙甘草、干地黄、生白芍、麦冬、阿胶、麻仁","温病后期脉虚大、舌绛少苔之真阴耗竭","甘咸酸寒，滋阴复脉"],["大定风珠","下焦篇","生白芍、阿胶、生龟板、干地黄、麻仁、五味子、生牡蛎、麦冬、炙甘草、鸡子黄、鳖甲","温病后期神倦瘛疭、脉气虚弱","滋阴息风，填补真阴以潜阳"]]},{"type":"quote","text":"盖温病忌汗，最喜解肌，桂枝本为解肌，且桂枝芳香化浊，芍药收阴敛液，甘草败毒和中、姜、枣调和营卫，温病初起，原可用之。此处却变易前法，恶风寒者主以桂枝，不恶风寒主以辛凉者，非敢擅违古训也。","source":"《温病条辨·卷一·上焦篇·风温、温热、温疫、温毒、冬温》"},{"type":"paragraph","text":"《温病条辨》的学术史意义在于它完成了温病学从《伤寒论》附翼到独立学科的转变。王叔和将温病混于《伤寒例》，张志聪、尤怡等虽驳其非而未另立法；叶天士《温热论》创卫气营血辨证而语焉不详；吴瑭则在此基础上以三焦辨证立其纲、定其法、选其方，使温病有了完整的理法方药体系，故后世称之为「温病学之祖」。今日学习温病学，卫气营血辨证与三焦辨证并用，前者明病位浅深与营血卫气之别，后者明上中下三焦之传变，二者相辅相成。《温病条辨》的条文加自注体例，也极大便利了教学与临床检索。"}]},{"id":"zhouhou-beijifang","title":"《肘后备急方》","subtitle":"晋·葛洪撰·八卷七十篇·后经陶弘景增补为《百一方》","category":"其他专科","tags":["急救方书","单验方","简便验廉","灸法急救"],"meta":[{"label":"成书年代","value":"东晋末年葛洪撰，南朝陶弘景增补，时约四至六世纪"},{"label":"作者","value":"葛洪（字稚川，号抱朴子），丹阳句容人，东晋著名道医"},{"label":"卷章节数","value":"原书三卷（又称《肘后救卒方》），经陶弘景增补为八卷，载方约千首，另有《附广肘后方》"},{"label":"文献地位","value":"中国最早的临床急救手册，开创简便验廉的急救方书传统"}],"image":"","imageHint":"肘后","summary":"《肘后备急方》又名《肘后卒救方》，晋代葛洪撰，原三卷，南朝陶弘景补阙为《肘后百一方》，今存八卷七十篇，是我国最早的临床急救专著。全书针对中恶、卒死、尸厥、霍乱、疟、狂犬、蛇蝎、蜈蚣、烧烫、妇人产难、疮疡等急症，载方多取易得之药与简捷灸法，并附《救卒病卒方》。其方「率多易得之药」「皆贱价，草石所在皆有」，专为人手边急难而设，开创了「简、便、廉、验」的方书风格。其确立的急救三原则——先救急后治病、重视简便可及、灸法与方药并重——在今天仍有启发，与急救普及教育和基层卫生建设的思路相通。","blocks":[{"type":"paragraph","text":"《肘后备急方》为晋代葛洪所撰。葛洪自序说：「余既穷览坟索，以着述余暇，兼综术数，省仲景元化刘戴秘要金匮绿秩黄素方，近将千卷。患其混杂烦重，有求难得，故周流华夏九州岛岛岛岛之中，收拾奇异，捃拾遗逸，选而集之，便种类殊，分缓急易简，凡为百卷，名曰玉函。然非有力不能尽写，又见周甘唐阮诸家，各作备急，既不能穷诸病状，兼多珍贵之药，岂贫家野居所能立办？」遂采其要约以为《肘后救卒》三卷，「率多易得之药」，专供仓卒急难之际取用。后经南朝陶弘景整理补充为《补阙肘后百一方》，并增《附广肘后方》三十七首，隋唐以后又陆续有增补，明清方书多有采录。"},{"type":"paragraph","text":"《肘后备急方》的编写宗旨极为明确：针对**急症**与**贫病者**。全书分上卷治内病、中卷治外发、下卷治为物所苦（伤害），所载内容涵盖卒中急死、霍乱吐泻、疟疾、水肿、癃闭、痉病、狂病、癫痫、痈疽、疥癣、蛇蝎虫兽咬伤、金疮、烧烫、妇人产难与乳疾、小儿惊啼疳积等。其用方特点有三：一是**单方验方**为主，如葱白、艾叶、生姜、豆豉、甘草等常见之品随手可取；二是**灸法与简捷外治**并重，如「灸其唇下宛宛中，承浆穴，十壮，大效矣」，并说「灸但言其分寸，不名孔穴」，便于推广；三是**操作描述极其具体**，如救卒死用葱黄心刺鼻中、吹耳条中，割雄鸡颈取血涂面、干复涂并以灰营死人一周等，虽属古代急救方法，其中一些（如保持呼吸道通畅、以温热刺激促进复苏）在今日仍有一定参考价值。"},{"type":"cards","columns":3,"items":[{"icon":"🚑","title":"急救专书","text":"中国最早的临床急救手册，专主急症。","bullets":["中恶、卒死、尸厥、霍乱等","金疮、烧烫、蛇蝎虫兽咬伤","妇人产难与小儿急症"]},{"icon":"🧺","title":"简便验廉","text":"专取易得贱价之药，为贫家野居而设。","bullets":["葱、姜、艾、豆豉等常用之品","单方、验方为主，便于取用","灸法只言分寸，不名孔穴"]},{"icon":"📖","title":"分类清楚","text":"按内病、外发、物伤三类分卷，便于寻检。","bullets":["上卷三十五首治内病","中卷三十五首治外发病","下卷三十一首治为物所苦"]}]},{"type":"table","caption":"《肘后备急方》主要内容分类","head":["卷次","篇数","主治范围","代表条目"],"rows":[["上卷（内病）","三十五首","脏腑气血躯壳内病与急症","救卒中恶死方、霍乱、疟、水肿、癃闭、痉、狂、痫、痈疽"],["中卷（外发）","三十五首","体表外部病证与传染性疾病","伤寒时病、疟疾、天行疫病、发斑、疮疡、丹毒、癣疥"],["下卷（物伤）","三十一首","为外物所伤之病","金疮、烧烫、毒物、蛇蝎、蜈蚣、蜂螫、狂犬、蛊毒"]]},{"type":"quote","text":"余今采其要约以为《肘后救卒》三卷，率多易得之药，其不获已须买之者，亦皆贱价，草石所在皆有，兼之以灸，灸但言其分寸，不名孔穴。凡人览之，可了其所用，或不出乎垣篱之内，顾眄可具。","source":"《肘后备急方·序·序二》"},{"type":"paragraph","text":"《肘后备急方》的文献价值尤应重视其**急救思想的奠基性**。它确立了中医急症救治的三个原则：一是**先救急后治病**，如对卒死先以通气、醒神、保温为务；二是**重视简便可及**，强调方药「不出乎垣篱之内」，把可及性作为选方标准；三是**灸法与方药并重**，开创了简便灸法用于急症的先例。书中「又使人用针，自非究习医方，素识明堂流注者，则身中荣卫尚不知其所在，安能用针以治之哉」的反思，也提出了针刺的适用边界问题——非专业者不宜擅用针刺，这一认识颇具前瞻性。"},{"type":"table","caption":"《肘后备急方》急救方法举例","head":["急症","原文方法","要点分析"],"rows":[["卒死（尸厥）","取葱黄心刺其鼻，男左女右，入七八寸；若使目中血出，佳","以辛温芳香通窍，取血出为邪气得泄之候"],["卒死","灸其唇下宛宛中，承浆穴，十壮，大效矣","以灸温通，取便于定位取穴"],["卒死","以小便灌其面，数回即能语","《扁鹊法》，以秽物冲开闭窍"],["霍乱吐泻","以醋煎汤灌服，及橘皮、生姜煎汤","后世霍乱方多祖述其意"],["金疮","以蜡为丸，煎以消石，裹伤处","止血止痛并以药蜡封护创口"],["狂犬咬伤","以泉水洗伤口，敷以雄黄、蜂蜡","外洗外敷并配合观察，取后世狂犬病防治之先声"]]},{"type":"quote","text":"医有方古也。古以来着方书者，无虑数十百家，其方殆未可以数计，篇帙浩瀚，苟无良医师，安所适从？况穷乡远地，有病无医，有方无药，其不罹夭折者几希。丹阳葛稚川，夷考古今医家之说，验其方简要易得，针灸分寸易晓，必可以救人于死者，为《肘后备急方》。使有病者得之，虽无韩伯休，家自有药；虽无封君达，人可为医，其以备急固宜。","source":"《肘后备急方·序·序一》"},{"type":"paragraph","text":"《肘后备急方》的现代意义在于其**可及性理念**。面对突发情况，一本只靠常见之物即可操作的手册，其价值远超理论深奥的巨著，这与今天的急救普及教育、分级诊疗与基层卫生的思路相通。需要提醒的是，书中所载如割鸡取血、灰营死人、刺鼻放血等古代方法，出于特定历史条件，在现代急救中已由心肺复苏、电除颤、气管插管等规范化手段取代；本书仅供传统医学文献与急救史研究参考，实际急救必须遵循现代急救规范并立即呼叫专业急救。"}]},{"id":"yixue-yuanliulun","title":"《医学源流论》","subtitle":"清·徐大椿撰·九十九篇·乾隆年间成书","category":"其他专科","tags":["医论","源流考证","针砭时弊","元气学说"],"meta":[{"label":"成书年代","value":"清乾隆年间（约1757年前后）成书"},{"label":"作者","value":"徐大椿（又名大业，字灵胎，晚号洄溪老人），江苏吴县人"},{"label":"卷章节数","value":"一卷，凡九十九篇，分经络脏腑、脉、病、方药、治法、书论等类"},{"label":"文献地位","value":"清代医论名篇专辑，纵横捭阖、针砭时弊，是研究乾嘉医学思想与临床主张的重要文献"}],"image":"","imageHint":"源流","summary":"《医学源流论》为清代徐大椿所撰，一卷九十九篇，为中医医论专辑。全书从经络脏腑、脉诊、病机、方药、治法、书论六个层面展开，考辨《内经》《伤寒》以来的学术源流，如辨经络脏腑之不可不治、论元气之存亡决死生、揭寒热虚实真假、辨内伤外感、论病有气色与神气、批评时医不辨经络、不审寒热虚实之弊。文字峻切，论理透辟，是清代医论中最具锋芒者之一。徐大椿论病处方多出己意而不拾古人牙慧，其不拘成说、敢辨异同的治学勇气，对今日临床思维方式的养成尤有教益。","blocks":[{"type":"paragraph","text":"《医学源流论》凡一卷，九十九篇，为清代吴县医家徐大椿所著。徐大椿，字灵胎，晚号洄溪老人，兼通经史百家与医学，虽未执壶常诊，而论病处方多出己意，不拾古人牙慧。本书体裁为短论集，每篇独立成篇而又有内在体系：卷上先论经络脏腑、脉与病，中论方药与治法，末论书论与学风。全书取名「源流」，意在考辨医学各科的源出正变，辨其是非，指陈利弊。其论《元气存亡》《寒热虚实真假》《内伤外感》诸篇最为精辟，为清代医论中最具锋芒者之一。"},{"type":"paragraph","text":"《医学源流论》的学术价值集中在三方面。其一**元气存亡论**：《元气存亡论》提出「故诊病决死生者，不视病之轻重，而视元气之存亡，则百不失一矣」，把正气存亡作为决死生的根本依据，继承并发展了《内经》邪正盛衰之论；其二**辨寒热虚实真假**：《寒热虚实真假论》指出「病之大端，不外乎寒热虚实，然必辨其真假，而后治之无误」，并分别列举假寒、假热、假实、假虚之候，是八纲辨证中「真假」一纲最系统的论述；其三**针砭时弊**：作者对当时医界不辨经络、滥用温凉、拘执成方等习气直言不讳，如《内伤外感论》说「如此死者，医杀之耳」，语气峻厉而切中时弊。其论治则主张「治病必分经络脏腑」，而《治病不必分经络脏腑论》则从反面补充，说明个别情况下的灵活，主张既不可一味分经脏腑而胶柱，亦不可全然不分。"},{"type":"cards","columns":3,"items":[{"icon":"🔥","title":"元气存亡","text":"以正气存亡作为决死生的根本标准。","bullets":["元气视之不见而附于气血之内","先伤元气者不可治","预防在上工，不使其势已横"]},{"icon":"🎭","title":"寒热虚实真假","text":"系统辨析八纲中的真假一纲。","bullets":["假寒：寒在外而热在内","假热：热在外而寒在内","假实形实而神衰，假虚形衰而神全"]},{"icon":"✍","title":"针砭时弊","text":"直斥不辨经络、不审虚实之临床流弊。","bullets":["批评杂药乱投、无法纪","批评守古方而不知变通","主张分经脏腑与灵活用药并行"]}]},{"type":"table","caption":"《医学源流论》篇目分类","head":["类别","代表篇目","核心论点"],"rows":[["经络脏腑","元气存亡论、躯壳经络脏腑论、表里上下论、阴阳升降论、治病必分经络脏腑论、治病不必分经络脏腑论、君火相火论、肾藏精论","以经络脏腑为识病之基，以元气存亡决死生，兼论治法之通变"],["脉","诊脉决死生论、脉症与病相反论、症脉轻重论","脉须与症合参，不可偏执；轻重缓急各有定法"],["病","中风论、寒热虚实真假论、内伤外感论、臌膈论、病情传变论、病同人异论、病同因别论、病症不同论、病有不愈不死虽愈必死论、卒死论、亡阴亡阳论、病有鬼神论","辨病之同异、传变与预后，强调审因求本"],["方药","方药离合论、方药优劣论、治病必以血气为主论、汤药论、药物论、用药论、药性论","强调方药须辨气血与病之标本"],["治法","表里论、上下论、阴阳论、寒热论、虚实论、攻补论、治病法","系统阐述八纲与治法之对应"],["书论","医非人人可学论、习医学古论、医源论、考《难经》、脉论、用药论等","论学医次第与源流，兼评历代医籍"]]},{"type":"quote","text":"故诊病决死生者，不视病之轻重，而视元气之存亡，则百不失一矣。……五脏有五脏之真精，此元气之分体者也。而其根本所在，即《道经》所谓丹田，《难经》所谓命门，《内经》所谓节节之旁中有小心，阴阳合辟存乎此，呼吸出入系乎此。无火而能令百体皆温，无水而能令五脏皆润。此中一线未绝，则生气一线未亡，皆赖此也。","source":"《医学源流论·卷上·经络脏腑·元气存亡论》"},{"type":"paragraph","text":"《医学源流论》的另一特色是**论治与论学并重**。在治法层面，《表里论》《上下论》《寒热论》《虚实论》《攻补论》诸篇，把八纲辨证系统转化为治法纲领，并处处体现「治病必分经络脏腑」与灵活变通并重的思想；《攻补论》讨论先后攻补、攻补兼施、攻补交替的策略，与《素问·标本病传论》「间者并行，甚者独行」遥相呼应。在书论层面，《医非人人可学论》《习医学古论》《医源论》等篇讨论学医次第、经典研习与医德医风，其中「医非人人可学论」提出学医须具三品之识、终身之功，是清代医德教育与人才观的重要文献。"},{"type":"table","caption":"《医学源流论》重要论断","head":["篇目","论断要点","现实意义"],"rows":[["元气存亡论","诊病决死生不视病之轻重，而视元气之存亡","把正气与预后置于首位，与危重症救治思路相通"],["躯壳经络脏腑论","当直指其病在何脏何腑、何筋何骨、何经何络，或传或不传","强调定位精确，反对笼统施治"],["阴阳升降论","元阳藏于肾中而四布，发汗太甚动其元阳即有亡阳之患","警示发汗、升散之法的度与禁忌"],["寒热虚实真假论","必辨真假而后治之无误","八纲「真假」一纲的系统论述"],["内伤外感论","内伤由于神志，外感起于经络；二者治法迥殊","内伤外感鉴别之专论"],["病情传变论","论病之传变与预后顺逆","重视动态观察而非一次定论"]]},{"type":"quote","text":"病之大端，不外乎寒热虚实，然必辨其真假，而后治之无误。假寒者，寒在外而热在内也，虽大寒而恶热饮；假热者，热在外而寒在内也，虽大热而恶寒饮，此其大较也。假实者，形实而神衰，其脉浮、洪、芤、散也；假虚者，形衰而神全，其脉静、小、坚、实。","source":"《医学源流论·卷上·病·寒热虚实真假论》"},{"type":"paragraph","text":"阅读《医学源流论》，一方面可体会清代乾嘉医家那股不拘成说、敢辨异同的学术勇气，其《元气存亡论》中「故诊病决死生者，不视病之轻重，而视元气之存亡，则百不失一矣」等主张，至今对临床思维方式的养成仍有教益；另一方面也须看到其某些论断带有强烈的个人色彩与时代局限，如《病有鬼神论》所述鬼神致病之说，以及部分篇目对某些医家医籍的峻评，均须以历史的、批判的眼光阅读。本书最值得反复揣摩的，是《躯壳经络脏腑论》《脉症与病相反论》《寒热虚实真假论》诸篇所体现的诊断学方法论。"}]},{"id":"yinshan-zhengyao","title":"《饮膳正要》","subtitle":"元·忽思慧撰·三卷·天历三年（1330）进呈","category":"养生食疗","tags":["营养食疗","宫廷膳食","食物禁忌","养生禁忌"],"meta":[{"label":"成书年代","value":"元天历三年（1330）成书并进呈，皇庆元年（1312）以后陆续编纂"},{"label":"作者","value":"忽思慧，任元代饮膳太医，兼通营养、烹调与医药"},{"label":"卷章节数","value":"三卷，含养生避忌、妊娠食忌、乳母食忌、聚珍异馔、诸般汤煎、饮酒避忌、食物中毒、服药食忌、五味偏走、四时所宜、食物相反等篇"},{"label":"文献地位","value":"现存较早且较完整的营养食疗专著，反映元代宫廷饮食与卫生保健状况"}],"image":"","imageHint":"饮膳","summary":"《饮膳正要》是元代太医忽思慧所撰，三卷，1330年进呈元英宗。全书以宫廷膳食经验为基础，系统论述养生避忌、聚珍异馔、诸般汤煎、饮酒避忌、食疗诸病、五味偏走、四时所宜、食物中毒、服药食忌与食物相反等内容，保存了大量元代宫廷菜谱、饮品与食物药用知识。书中强调「食饮有节，起居有常」，并明确「先饥而食、食勿令饱」，主张「五味调和」与「食疗为先」，是中国饮食养生学的重要典籍。其「聚珍异馔」「诸般汤煎」所载菜名与制法，使许多元代名点在今日得以复原，亦为研究元代宫廷膳食与民族饮食交融的第一手材料。","blocks":[{"type":"paragraph","text":"《饮膳正要》由元代饮膳太医忽思慧所撰。据虞集序与忽思慧自序，忽思慧于延祐年间（1314—1320）充任饮膳之职，遂与赵国公臣普兰奚「将累朝亲侍进用奇珍异馔，汤膏煎造，及诸家本草，名医方术，并日所必用谷肉果菜，取其性味补益者，集成一书」，于天历三年（1330）成书进呈，元英宗「嘉是书而用之，以资摄养之助」，后由中书省臣拜住刻梓广传。全书三卷，卷一列养生避忌、妊娠食忌、乳母食忌、三皇圣纪、聚珍异馔、饮酒避忌；卷二载神仙服食、食疗诸病、五味偏走、四时所宜、食物中毒、服药食忌、食物相反、诸般汤煎；卷三为各类食谱与食疗方，是研究元代宫廷饮食与卫生保健的第一手史料。"},{"type":"paragraph","text":"《饮膳正要》的内容特色有三。其一是**宫廷食谱的集中保存**：《聚珍异馔》载天厨御膳、秃秃麻食、蒸奶茶、螃蟹、贴饼等元代宫廷名馔，《诸般汤煎》《食疗诸病》《神仙服食》保存了大量以药入馔的方子，是研究元代饮食文化与宫廷膳食的第一手材料。其二是**食忌与相克之详尽论述**：卷一《养生避忌》提出「夫安乐之道，在乎保养，保养之道，莫若守中，守中则无过与不及之病」，并列出「薄滋味、省思虑、节嗜欲、戒喜怒、惜元气、简言语、轻得失、破忧阻、除妄想、远好恶、收视听、勤内固、不劳神、不劳形」十四条养生准则；卷二《食物相反》《服药食忌》《食物中毒》《五味偏走》专论食物之间的相克、与药物的禁忌及中毒解救。其三是**依时调养**：《四时所宜》按春夏秋冬分述起居、饮食宜忌，强调「春气温，宜食麦，以凉之，不可一于温也」等原则。"},{"type":"cards","columns":3,"items":[{"icon":"🍲","title":"宫廷食谱","text":"保存元代宫廷菜点、汤煎与饮品名目。","bullets":["聚珍异馔载天厨御膳","诸般汤煎记饮品制法","神仙服食载药膳方"]},{"icon":"🚫","title":"食忌相克","text":"详论食物相反、服药食忌与中毒解救。","bullets":["五味偏走：辛走气、咸走血等","食物相反列相克之例","中毒者以苦参汁、犀角汁等解救"]},{"icon":"🌤","title":"四时养生","text":"依四时气候定起居与饮食宜忌。","bullets":["春宜食麦，夏宜食菽","秋宜食麻以润其燥","冬宜食黍以热性治其寒"]}]},{"type":"table","caption":"《饮膳正要》篇章与内容","head":["卷","篇目","主要内容"],"rows":[["卷一","序、三皇圣纪、养生避忌、妊娠食忌、乳母食忌、聚珍异馔、饮酒避忌","养生总则、妇幼食忌、宫廷名馔、饮酒宜忌"],["卷二","神仙服食、食疗诸病、五味偏走、四时所宜、食物中毒、服药食忌、食物相反、诸般汤煎","药膳、食疗、五味归经、四时调养、食毒与汤饮"],["卷三","各类食谱（粉汤、秃秃麻食、蒸奶茶、醍醐、驼子、鹿唇、附子等条）","元代宫廷与市井饮食的具体制作方法"]]},{"type":"quote","text":"天之所生，地之所养，天地合气，人以禀天地气生，并而为三才。三才者，天地人。人而有生，所重乎者心也。心为一身之主宰，万事之根本，故身安则心能应万变，主宰万事，非保养何以能安其身。保养之法，莫若守中，守中则无过与不及之病。调顺四时，节慎饮食，起居不妄，使以五味调和五脏。五脏和平则血气资荣，精神健爽，心志安定，诸邪自不能入，寒暑不能袭，人乃怡安。","source":"《饮膳正要·卷一·序》"},{"type":"paragraph","text":"《饮膳正要》在食疗理论上承《内经》五味所入之说而又有发展。《五味偏走》一篇即引《千金》之说，申述「酸走筋，筋病勿多食酸；苦走骨，骨病勿多食苦；甘走肉，肉病勿多食甘；辛走气，气病勿多食辛；咸走血，血病勿多食咸」，并进一步指出多食某味所致之病，如「多食酸，肝气以津，脾气乃绝，则肉胝而唇揭」「多食咸，骨气劳短，肥气折，则脉凝泣而变色」，由偏嗜而致病的机制阐述得相当细致。书中还提出五脏病变的食疗原则：「肝病禁食辛，宜食粳米、牛肉、葵菜之类；心病禁食咸，宜食小豆、犬肉、李、韭之类」等，与《素问·藏气法时论》五脏所宜完全一致，可见其理论承袭清晰。"},{"type":"table","caption":"《饮膳正要》五味偏走与五脏食忌","head":["五味","所走","过食之害","相关脏病食宜"],"rows":[["酸","走筋","多食则肝气以津、脾气乃绝，肉胝而唇揭","肝病禁辛，宜粳米、牛肉、葵菜"],["苦","走骨","多食则脾气不濡、胃气乃厚，皮槁而毛拔","脾病宜粳米、牛肉、枣、葵"],["甘","走肉","多食则心气喘满、色黑、肾气不平，骨痛而发落","肾病禁甘，宜黄黍、鸡肉、桃、葱"],["辛","走气","多食则筋脉沮弛、精神乃央，筋急而爪枯","肺病禁苦，宜小麦、羊肉、杏、薤"],["咸","走血","多食则骨气劳短，脉凝泣而变色","心病禁咸，宜小豆、犬肉、李、韭"]]},{"type":"quote","text":"善摄生者，薄滋味，省思虑，节嗜欲，戒喜怒，惜元气，简言语，轻得失，破忧阻，除妄想，远好恶，收视听，勤内固，不劳神，不劳形，神形既安，病患何由而致也。故善养性者，先饥而食，食勿令饱，先渴而饮，饮勿令过。食欲数而少，不欲顿而多。盖饱中饥，饥中饱，饱则伤肺，饥则伤气。","source":"《饮膳正要·卷一·养生避忌》"},{"type":"paragraph","text":"《饮膳正要》的史料价值不可低估。它是研究元代宫廷饮食、汉族与蒙古族等民族饮食交融、宫廷膳食结构与元代卫生保健观念的重要原始文献；《聚珍异馔》《诸般汤煎》所载菜名与制法，使许多元代名点在今日得以复原，如「蒸奶茶」「秃秃麻食」「马思板肠」等；其对孕期、哺乳期饮食禁忌的专篇论述，也反映了对妇幼保健的重视。需要说明的是，书中部分食忌（如食物相反之说）带有经验色彩，今日应结合营养学与食品安全知识评估；具体食疗方案与剂量须由医师或营养师依据体质与病情制定。"}]},{"id":"xiyuan-jilu","title":"《洗冤集录》","subtitle":"南宋·宋慈撰·四卷五十三项·淳祐七年（1247）刊","category":"其他专科","tags":["法医学","验尸检骨","司法检验","世界法医名著"],"meta":[{"label":"成书年代","value":"南宋淳祐七年（1247）刊于湖南宪治"},{"label":"作者","value":"宋慈（字惠父），福建建阳人，南宋著名法医学家、理学家"},{"label":"卷章节数","value":"四卷五十三项，载检验规则、验尸、验伤、检骨及各类命案现场勘验方法"},{"label":"文献地位","value":"中国较早且较完整的法医学专书，被译介到英、法、德等国，被视为世界法医学的奠基之作"}],"image":"","imageHint":"洗冤","summary":"《洗冤集录》是南宋宋慈所著，四卷五十三项，是我国较早且较完整的法医学专著。全书针对司法验尸的实际需要，系统规定检验程序、验尸方法、验伤与检骨技术，详述自杀、他杀、溺死、缢死、勒死、压死、冻死、中毒、交通事故等各类死亡现象的检验要点，并附现场勘验、检验格目与尸检格目等文书程式。宋慈自序「狱事莫重于大辟」，其严谨务实的态度使此书成为古代司法检验的规范依据，也是世界法医学史上的重要里程碑。","blocks":[{"type":"paragraph","text":"《洗冤集录》为南宋淳祐七年（1247）宋慈所撰。宋慈，字惠父，福建建阳人，理学名臣朱熹的门生，历任江西提点刑狱、湖南提刑。他四任臬寄，「独于狱案，审之又审，不敢萌一毫慢易心」，遂「博采近世所传诸书，自《内恕录》以下凡数家，会而粹之，厘而正之，增以己见，总为一编，名曰《洗冤集录》，刊于湖南宪治」，供同僚「参验互考」。全书四卷五十三项，系统汇集了自唐宋以来各家法医检验经验并加以厘正。"},{"type":"paragraph","text":"《洗冤集录》的内容体系相当完备。卷一为**总则与检验规程**，包括《条令》《检验总说》《疑难杂说》，规定「诸尸应验而不验」「或不定要害致死之因」等违制情形与罚则，以及初检、覆检的分工与「同检验官」「同验官」回避制度，保存了完整的尸检格目文书格式。卷二为**各类尸体检验**，含《初检》《验尸》《覆检》《妇人》《小儿尸并胞胎》《四时变动》《洗罨》《验未埋瘗尸首》《验坟内及屋下攒殡尸》等。卷三为**具体死伤与骨伤检验**，含《论沿身骨脉及要害去处》《验骨》《自缢》《溺死》《验他物及手足伤死》《疑难杂说》等。卷四为**急救与验毒**，含《急救方》《复用急救方》《中毒急救》《酒醋毒物及饮食中毒》等，并附《验状程式》。其中《验骨》一章对人体骨骼结构、性别差异与骨伤特征作了细致描述，具有很高的法医鉴定价值。"},{"type":"cards","columns":3,"items":[{"icon":"⚖","title":"检验程序","text":"详定初检、覆检、回避与文书格式。","bullets":["诸尸应验而不验者以违制论","初覆检官相约同验","尸检格目以千字文为号"]},{"icon":"🦴","title":"验骨与尸检","text":"系统描述骨骼结构与各类死亡征象。","bullets":["男子骨白、妇人骨黑","颅骨片数、牙齿数与肋骨数有别","各种缢溺勒压死的中外征候"]},{"icon":"🩹","title":"急救验毒","text":"附中毒急救与检验方法，切合实用。","bullets":["服毒、中毒、饮食毒物之辨验","急救方与复用急救方","验状程式规范文书"]}]},{"type":"table","caption":"《洗冤集录》卷次内容","head":["卷","项目","主要内容"],"rows":[["卷一","条令、检验总说（上下）、疑难杂说（上）","检验的法令依据、程序规范、仵作吏胥责任与违制处罚"],["卷二","初检、验尸、覆检、妇人、小儿尸并胞胎、四时变动、洗罨、验未埋瘗尸首、验坟内及屋下攒殡尸","各类尸体检验方法与复检规则"],["卷三","论沿身骨脉及要害去处、验骨、自缢、溺死、验他物及手足伤死、疑难杂说（下）","要害部位、骨伤鉴定与各类外伤检验"],["卷四","急救方、复用急救方、中毒急救、验状程式","现场急救、中毒辨识与检验文书格式"]]},{"type":"quote","text":"狱事莫重于大辟，大辟莫重于初情，初情莫重于检验。盖死生出入之权舆，幽枉屈伸之机括，于是乎决。……慈四叨臬寄，他无寸长，独于狱案，审之又审，不敢萌一毫慢易心；若灼然知其为欺，则亟与驳下，或疑信未决，必反下覆深思，惟恐率然而行，死者虚被涝漉。","source":"《洗冤集录·序·序》"},{"type":"paragraph","text":"《洗冤集录》的科学成就集中体现在**验骨**与**死亡征象辨识**两方面。《验骨》章对全身骨骼数目与形态作了系统描述：髑髅骨男子八片（蔡州人有九片）、妇人六片；牙有二十四至三十六之别；肋骨男子各十二条、妇人各十四条；并指出「男子骨白，妇人骨黑」（妇人产子出血故骨黑），此说虽有部分依据但过于绝对。这些描述虽受时代所限，却代表了当时对身体骨骼系统的细致观察。各种死亡的检验要点尤为实用，如《自缢》一章区分活套头、死套头、单系十字、缠绕系四种缢法，指出「脚虚则喉下勒深，实则浅；人肥则勒深，瘦则浅」，并说明如何据索痕走向判断是自缢还是他杀，推理严密。今天法医学中的机械性窒息征象与之有相当渊源。"},{"type":"table","caption":"《洗冤集录》各类死亡检验要点举例","head":["死亡类型","检验要点","判断依据"],"rows":[["自缢","两眼合、唇口黑、皮开露齿；两手握拳、两脚尖直垂下；喉下痕紫赤或黑淤色","勒痕深浅与胖瘦、悬吊位置相关；单系十字须悬空方死；辨活套死套与自他杀"],["溺死","口鼻青赤、耳鼻有沫、头发散乱、身体膨胀","结合现场水域、尸身浮沉与外伤检验综合判断"],["中毒","须详察面色、唇色、牙龈与尸斑，结合服药饮食情形","《卷四》列中毒急救方与验毒法，参照毒物性质辨别"],["骨伤","按全身三百六十五节逐节验视，核计骨片数与折痕","《验骨》详述男女骨骼差异与骨伤特征"],["压死","验其肋骨折损与胸背伤痕并结合压物重量","结合现场物件与伤痕形态综合判断"]]},{"type":"quote","text":"人有三百六十五节，按一年三百六十五日。男子骨白，妇人骨黑。……髑髅骨∶男子自顶及耳并脑后共八片，(蔡州人有九片)脑后横一缝，当正直下至发际别有一直缝。妇人只六片，脑后横一缝，当正直下无缝。……左右肋骨∶男子各十二条，八条长、四条短。妇人各十四条。","source":"《洗冤集录·卷三·验骨》"},{"type":"paragraph","text":"《洗冤集录》的另一重要贡献是**司法程序的规范化**。卷一《条令》对验尸的时限（报到后两时不请官即属违制）、差遣回避、初覆检配合、检验文书填写与上报流程均有明文规定，并规定违规的笞杖刑罚；《序》中宋慈强调「参验互考」「医师讨论古法，脉络表里先已洞澈，一旦按此以施针砭，发无不中，则其洗冤泽物，当与起死回生同一功用矣」，把法医检验与医道相贯通，这一思路在世界法医学史上是相当早的。宋慈在《序》末尾仍虚心征求「贤士大夫或有得于见闻及亲所历涉出于此集之外者，切望片纸录赐，以广未备」，体现其求真务实的学风。"}]}]}},"herbs":{"page":{"key":"herbs","title":"本草图鉴","subtitle":"六十味常用中药 · 性味归经 · 功效主治 · 配伍宜忌","description":"岐黄翰墨本草图鉴收录六十味临床常用中药，逐一列明拉丁学名、性味归经、功效主治、用法用量、配伍宜忌与使用注意，并附《神农本草经》《本草纲目》原文，便于按类检索与临床速查。","lead":"本页按解表、清热、泻下、祛风湿、化湿、利水渗湿、温里、理气、消食、驱虫、止血、活血化瘀十二类，收录六十味临床常用中药。每味药均给出性味归经、功效主治、现代用法用量、配伍宜忌与注意事项，并附古籍原文及掌握要点，便于背诵、查阅与临床参考。","type":"collection","icon":"fa fa-leaf","items":[{"id":"ma-huang","title":"麻黄","subtitle":"Ephedra sinica Stapf ｜ 麻黄、净麻黄、蜜麻黄","category":"解表药","tags":["发汗解表","宣肺平喘","利水消肿"],"meta":[{"label":"性味归经","value":"辛、微苦，温；归肺、膀胱经"},{"label":"功效","value":"发汗解表，宣肺平喘，利水消肿"},{"label":"主治","value":"风寒感冒无汗、胸闷喘咳、风水水肿"},{"label":"用法用量","value":"煎服 2–10 g；发汗宜生用，止咳平喘多蜜炙用"},{"label":"使用注意","value":"表虚自汗、阴虚盗汗及肾不纳气之虚喘忌用；高血压、失眠者慎用"}],"image":"","imageHint":"麻黄","summary":"麻黄为麻黄科植物 Ephedra sinica Stapf 的干燥草质茎，是《神农本草经》列为上品的常用中药，主产于内蒙古、山西、甘肃等北方草原地带。商品分净麻黄、节麻黄与蜜麻黄三种，净者发汗力强，节者止咳平喘力胜，蜜炙者偏于润肺止咳。其性温味辛，主入肺、膀胱经，善发汗解表、宣肺平喘、利水消肿，为治风寒表实无汗与肺气壅遏喘咳的第一要药。风寒闭表、肺气不宣者用之最宜，风热表证、阴虚盗汗及高血压患者则当慎用。","blocks":[{"type":"paragraph","text":"麻黄为麻黄科植物麻黄 Ephedra sinica Stapf 的干燥草质茎，秋末至次春采收，除去地上部分及木质茎，晒干或阴干后切成小段。现代商品分净麻黄（去节）、节麻黄（保留节）、蜜麻黄（蜜炙）三类：净麻黄发汗作用最强，节麻黄止咳平喘作用较胜，蜜麻黄辛散之性缓和而润肺止咳之功见长；另有麻黄绒，取净麻黄除去木质茎的绒毛，作用更缓，适合老人、虚人及小儿使用。商品以色青、干燥、断面黄白、中心红棕、气微味苦涩者为佳。"},{"type":"paragraph","text":"麻黄辛温而气轻浮，主入肺经，宣开肺气而外达皮毛，故能发汗解表，为风寒表实无汗之要药；肺主气而司呼吸，麻黄宣肺开闭、降气平喘，能治风寒束肺或痰饮壅肺之咳喘；麻黄又能宣通肺气、通调水道而下输膀胱，故有利水消肿之功，用于风水水肿、小便不利。蜜炙之后辛散之性减弱而润肺止咳之功增强，因此临床止咳平喘多用蜜麻黄，发汗解表则用生麻黄。"},{"type":"paragraph","text":"现代药理研究表明，麻黄主含麻黄碱、伪麻黄碱与挥发油等成分，麻黄碱能兴奋交感神经、收缩血管、升高血压，同时可松弛支气管平滑肌，故其平喘作用确切，而这亦是引起心悸、失眠、血压升高的不良反应根源。配伍方面，麻黄配桂枝可增强发汗解表之力，配杏仁一宣一降以止咳平喘，配石膏则清宣肺热，配白术、防风益气固表而用于气虚自汗，配附子温阳散寒以治阳虚外感；其与甘草同用可缓和发汗、益气和中。"},{"type":"table","caption":"麻黄常见配伍与要点","head":["配伍","作用","要点"],"rows":[["麻黄配桂枝","发汗解表力增","用于风寒表实无汗、恶寒发热"],["麻黄配杏仁","一宣一降，止咳平喘","用于咳嗽痰多、气喘"],["麻黄配石膏","清宣肺热","用于肺热壅盛之喘咳"],["麻黄配白术、防风","益气固表、调和营卫","用于表虚自汗、易感风邪"]]},{"type":"quote","text":"麻黄乃肺经之药，主宣发阳气，开腠理以散风邪。","source":"《本草纲目·草部·麻黄》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"麻黄发汗作用较强，表虚自汗、阴虚盗汗及肾不纳气之虚喘者忌用；高血压、心脏病、失眠及甲状腺功能亢进患者应慎用，运动员及需避免兴奋者禁用或严格控量。麻黄碱可致心悸、血压升高、震颤、失眠，用量过大可引起心律失常甚至抽搐；不宜久煎（有效成分易挥发，久煎则效减），也不宜长期连续服用，儿童及孕妇须在医师指导下使用。"},{"type":"keypoints","title":"掌握要点","items":["发汗解表要药，专治风寒表实无汗","蜜炙偏于止咳平喘，生品偏于发汗解表","麻黄碱兴奋交感神经，高血压、失眠者慎用","宣肺开闭、通调水道，故兼能利水消肿"]}]},{"id":"gui-zhi","title":"桂枝","subtitle":"Cinnamomi Ramulus ｜ 桂枝、嫩桂枝、柳桂","category":"解表药","tags":["发汗解肌","温通经脉","助阳化气","平冲降逆"],"meta":[{"label":"性味归经","value":"辛、甘，温；归心、肺、膀胱经"},{"label":"功效","value":"发汗解肌，温通经脉，助阳化气，平冲降逆"},{"label":"主治","value":"风寒感冒、脘腹冷痛、血寒经闭、关节痹痛、痰饮眩悸、水肿、心悸、奔豚"},{"label":"用法用量","value":"煎服 3–10 g；与白芍等量同用为桂枝汤"},{"label":"使用注意","value":"外感热病、里热盛者忌用；阴虚火旺、血热妄行者不宜；孕妇慎用"}],"image":"","imageHint":"桂枝","summary":"桂枝为樟科植物肉桂 Cinnamomum cassia (L.) J. Presl 的干燥嫩枝，春末夏初采收、除去木质部后干燥而成，商品以嫩枝细、色红棕、香气浓、味甘辛者为佳。其性温味辛甘，主入心、肺、膀胱经，既能发汗解肌、调和营卫，又能温通经脉、助阳化气、平冲降逆，为外感风寒营卫不和之要药，并广泛用于寒凝经脉的脘腹冷痛、血寒经闭、痹痛以及痰饮、水肿、奔豚等病证。外感热病、阴虚火旺者当忌用。","blocks":[{"type":"paragraph","text":"桂枝为樟科植物肉桂 Cinnamomum cassia (L.) J. Presl 的干燥嫩枝，春末夏初采收嫩枝，除去木质部，晒干或阴干而得。商品以枝细而嫩、色红棕、香气浓郁、味甘辛者为佳，历史上习称\"柳桂\"。炮制多生用，少数地区炒用或蜜炙；取桂枝与白芍等量相配，即为经典配伍桂枝汤，用于太阳中风、营卫不和之恶风汗出、脉缓。"},{"type":"paragraph","text":"桂枝辛甘而温润，主入心、肺经，外达皮毛而解肌发表，内温通阳而温经通脉。辛能散寒解肌，甘能补中益气，温能通脉行血，故对风寒在表、营卫不和之恶风汗出、脉浮缓者疗效良好；其温通之性可温运阳气、推动血行，故用于血寒经闭、寒凝经脉所致脘腹冷痛与关节痹痛；又能助阳化气、通阳利水，故治痰饮、蓄水、水肿；并能平冲降逆，用于心悸、奔豚。"},{"type":"paragraph","text":"现代研究显示桂枝含桂皮醛等挥发油及桂皮多糖，具有解热、镇痛、抗炎、抗菌、扩张血管等作用，挥发油含量随产地与采收期变化明显，故质量控制以桂皮醛含量为指标。配伍上，桂枝配白芍调和营卫，配麻黄增强发汗解表，配白术、茯苓温阳化气行水，配干姜、附子温通经脉以治寒凝血瘀之痛经闭经，配龙骨、牡蛎平冲降逆治心悸烦满。"},{"type":"table","caption":"桂枝常见配伍与要点","head":["配伍","作用","要点"],"rows":[["桂枝配白芍","调和营卫、解肌发表","等量相配为桂枝汤"],["桂枝配麻黄","发汗解表","用于风寒表实无汗"],["桂枝配白术、茯苓","温阳化气、通阳利水","用于痰饮、水肿"],["桂枝配附子、干姜","温通经脉、散寒止痛","用于寒凝经脉之痹痛、痛经"]]},{"type":"quote","text":"桂枝，辛甘而温，气味俱薄，浮而升，阳之桂也。","source":"《本草纲目·木部·桂》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"桂枝辛温走散，外感热病、里热炽盛、阴虚火旺、血热妄行者均应忌用；孕妇及月经过多者慎用。本品含桂皮醛，浓煎或过量服用可致口咽干燥、烦躁、失眠、鼻衄；入汤剂宜后下，久煎则挥发油散失而药力明显减弱；与含鞣质的药物同用亦可影响吸收。"},{"type":"keypoints","title":"掌握要点","items":["解肌发表，调和营卫，治风寒表虚有汗","温通经脉，为治寒凝血瘀之要药","助阳化气，可治痰饮、水肿与奔豚","含挥发油，入汤宜后下，久煎则效减"]}]},{"id":"jing-jie","title":"荆芥","subtitle":"Schizonepeta tenuifolia Briq. ｜ 荆芥、荆芥穗、假苏","category":"解表药","tags":["祛风解表","透疹消疮","炒炭止血"],"meta":[{"label":"性味归经","value":"辛，微温；归肺、肝经"},{"label":"功效","value":"祛风解表，透疹消疮；炒炭长于止血"},{"label":"主治","value":"感冒头痛、麻疹不透、风疹瘙痒、疮疡初起；便血、崩漏（荆芥炭）"},{"label":"用法用量","value":"煎服 4.5–9 g；止血宜炒炭用"},{"label":"使用注意","value":"表虚自汗、阴虚头痛者不宜；服药期间忌食鱼蟹"}],"image":"","imageHint":"荆芥","summary":"荆芥为唇形科植物荆芥 Schizonepeta tenuifolia Briq. 的干燥地上部分，秋季花穗盛开时采割晒干。商品分全草与花穗两种，荆芥穗芳香性较强、祛风解表之力较胜，荆芥全草长于解表透疹；炒炭后称荆芥炭，用于各类出血证。其性味辛而微温，主入肺、肝经，辛散可祛风，微温可散寒，既能祛风解表、透疹消疮，又能炒炭止血，为风热、风寒外感以及出血证的常用药，性质较和缓，为\"辛温解表\"中之佳品。","blocks":[{"type":"paragraph","text":"荆芥为唇形科植物荆芥 Schizonepeta tenuifolia Briq. 的干燥地上部分，秋季花穗盛开时采割，晒干或阴干。商品分\"荆芥全草\"与\"荆芥穗\"（花穗）两类：荆芥穗因含挥发油较多而芳香，祛风解表之力较胜，荆芥全草则解表透疹较为常用；将荆芥炒至表面焦黑、内部焦黄者称\"荆芥炭\"，炒炭后辛散之性转为收涩而入血分止血。商品以穗多、色绿褐、气芳香者为佳。"},{"type":"paragraph","text":"荆芥辛而微温，主入肺、肝经。辛能散风，微温可散寒，故祛风解表而治外感风邪之头痛身热；风性轻扬向上向外，荆芥善散风透邪，故能透疹消疮，用于麻疹初起、疹出不畅、风疹瘙痒及疮疡初起；荆芥炒炭之后，辛散之性受制而收涩之性显现，入血分而能止血，用于便血、吐血、崩漏等出血证，故有\"炒炭止血\"之用法。"},{"type":"paragraph","text":"现代研究表明，荆芥挥发油主要含薄荷酮、荆芥内酯等成分，具有解热、镇痛、抗炎、抗过敏及止血等作用；研究还提示荆芥炒炭后其凝血时间较生品缩短，而久煎则止血作用反见减弱，故强调\"炒炭存性\"。配伍上，荆芥配防风以祛风解表，配金银花、连翘治风热疮疡与痄腮，配生地黄、槐花治血热出血，配白芷、羌活治外感风寒之头身疼痛，配僵蚕治风痰阻络之口眼歪斜。"},{"type":"table","caption":"荆芥常见配伍与要点","head":["配伍","作用","要点"],"rows":[["荆芥配防风","祛风解表力增","用于风寒感冒、头痛"],["荆芥配金银花、连翘","疏风清热解毒","用于风热疮疡、痄腮"],["荆芥炭配槐花、地榆","凉血止血","用于便血、痔血、崩漏"],["荆芥配僵蚕","祛风化痰通络","用于风痰阻络之口眼歪斜"]]},{"type":"quote","text":"祛风解表，透疹消疮。用于感冒，头痛，麻疹不透，风疹瘙痒，疮疡初起。荆芥炭止血，用于便血，崩漏。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"荆芥辛散走窜，表虚自汗、阴虚头痛者及久病体弱者不宜单用；服药期间忌食鱼蟹及辛辣发物。本品辛温而性质较和缓，然用于热证时须注意其温散之性对血热、实热的影响；荆芥穗提取物有一定光敏反应，肝功能不全者及光敏体质者应慎用，孕妇亦当慎用。"},{"type":"keypoints","title":"掌握要点","items":["祛风解表、透疹消疮，并能炒炭止血","荆芥穗祛风力胜，荆芥全草解表透疹为宜","炒炭须存性，久煎止血作用反而减弱","解表药中性质较和缓，兼治风疹瘙痒"]}]},{"id":"fang-feng","title":"防风","subtitle":"Saposhnikovia divaricata (Turcz.) Schischk. ｜ 防风、关防风、北防风","category":"解表药","tags":["祛风解表","胜湿止痛","止痉"],"meta":[{"label":"性味归经","value":"辛、甘，微温；归膀胱、肝、脾经"},{"label":"功效","value":"祛风解表，胜湿止痛，止痉"},{"label":"主治","value":"感冒头痛、风湿痹痛、风疹瘙痒、破伤风、项强拘挛"},{"label":"用法用量","value":"煎服 5–10 g"},{"label":"使用注意","value":"阴血亏虚、热病动风者不宜；剂量过大可致胃脘不适"}],"image":"","imageHint":"防风","summary":"防风为伞形科植物防风 Saposhnikovia divaricata (Turcz.) Schischk. 的干燥根，春末夏初采挖、除去泥沙、洗净晒干，商品以根皮色浅黄、断面黄白、气味特异者为佳，关防风为其地道品种。因其质轻虚、性润而不燥，素有\"风药中之润剂\"之称。其味辛甘而微温，归膀胱、肝、脾经，善祛风解表、胜湿止痛，并能息风止痉，为外感风邪、风湿痹痛与破伤风的常用药。","blocks":[{"type":"paragraph","text":"防风为伞形科植物防风 Saposhnikovia divaricata (Turcz.) Schischk. 的干燥根，春末夏初采挖，除去泥沙、杂质，洗净后晒干。商品以根皮色浅黄、断面黄白、质松软、气味特异者为佳，产于辽宁、吉林、河北、山西等地者称\"关防风\"，为地道品种，品质尤佳；山西产者称\"北防风\"，条细身轻而质佳。其质轻虚而性润不燥，故古今医家称其为\"风药中之润剂\"。"},{"type":"paragraph","text":"防风辛甘微温，归膀胱经而善走外，祛风解表以治外感表证，无论风寒、风热均可随证配伍；入肝脾经而善胜湿止痛，为治风湿痹痛、筋骨拘挛的常用要药；其性升散，又能息风止痉，用于破伤风、项强拘挛、抽搐等；此外散风之功亦可用于风疹瘙痒、疮疡初起以及头痛项强、牙痛。"},{"type":"paragraph","text":"现代研究显示防风含色原酮类（如升麻素苷）、香豆素类与多糖等成分，色原酮类具有抗炎、镇痛、抗过敏作用，临床用于风湿性关节炎、荨麻疹、过敏性鼻炎等有一定疗效；其所含挥发油则与其\"风药\"特性相关。配伍上，防风配荆芥治外感风邪头痛，配羌活、秦艽治风湿痹痛，配黄芩清热祛风止痒，配天麻、钩藤息风止痉，配党参、白术益气固表祛风，配龙骨、牡蛎治肠风泄泻。"},{"type":"table","caption":"防风常见配伍与要点","head":["配伍","作用","要点"],"rows":[["防风配荆芥","祛风解表","用于外感风寒、头痛鼻塞"],["防风配羌活、秦艽","胜湿止痛","用于风湿痹痛、筋脉拘挛"],["防风配黄芩","疏风清热止痒","用于风疹、皮肤瘙痒"],["防风配党参、白术","益气固表、祛风和营","用于表虚自汗、易感风邪"]]},{"type":"quote","text":"主大风头眩痛，恶风风邪，目盲无所见，风行周身，骨节疼痹，烦满，拘挛。","source":"《神农本草经·草部·防风》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"防风辛甘温燥，阴血亏虚、久病体弱、热病动风者不宜使用；服药期间不宜食用辛辣刺激及鱼蟹类食物。本品含香豆素类成分，与抗凝血药同用时须注意出血倾向；大剂量或长期服用可出现胃脘不适、恶心、口干、倦怠等不良反应，出现时应减量或停用并咨询医师。"},{"type":"keypoints","title":"掌握要点","items":["祛风解表，兼能胜湿止痛、止痉","风药中之润剂，外感与痹痛皆宜","含色原酮与香豆素，注意与抗凝药同用","阴血亏虚、热病动风者不宜"]}]},{"id":"xi-xin","title":"细辛","subtitle":"Asari Radix et Rhizoma ｜ 细辛、辽细辛、北细辛","category":"解表药","tags":["解表散寒","祛风止痛","通窍","温肺化饮"],"meta":[{"label":"性味归经","value":"辛，温；归心、肺、肾经"},{"label":"功效","value":"解表散寒，祛风止痛，通窍，温肺化饮"},{"label":"主治","value":"风寒感冒、头痛、牙痛、鼻塞流涕、鼻鼽、鼻渊、风湿痹痛、痰饮咳喘"},{"label":"用法用量","value":"煎服 1–3 g；散剂每次服 0.5–1 g"},{"label":"使用注意","value":"十八反，与藜芦相反不可同用；气虚多汗、阴虚阳亢头痛者及肺燥伤阴干咳者忌用；孕妇慎用"}],"image":"","imageHint":"细辛","summary":"细辛为马兜铃科植物北细辛 Asarum heterotropoides var. mandshuricum、汉城细辛 Asarum sieboldii 或华细辛的干燥根和根茎，前期采挖者根细长称\"辽细辛\"，夏季采挖者称\"西细辛\"。其味辛而性温，主入心、肺、肾经，气味俱厚而能升能降，善走窜而不峻猛，能解表散寒、祛风止痛、通窍开闭、温肺化饮，为治头痛、牙痛、鼻渊、寒饮咳喘之要药。然其含黄樟醚，毒性明确，剂量必须严格控制。","blocks":[{"type":"paragraph","text":"细辛为马兜铃科植物北细辛 Asarum heterotropoides Fr. Schmidt var. mandshuricum (Maxim.) Kitag.、汉城细辛 Asarum sieboldii Miq. 或华细辛 Asarum sieboldii Miq. var. seoulense Nakai 的干燥根和根茎。夏季果熟期或初秋采挖，除去泥沙、杂质与残留茎叶，阴干；前期采挖者根细长、充实者称\"辽细辛\"（北细辛），夏季采挖者称\"西细辛\"或\"荷叶细辛\"，均以根细、色灰绿、叶片完整、香气浓者为佳。商品多已洗净切段，注意其与北沙参、辽细辛外形相似，购销与调剂时须严加区分。"},{"type":"paragraph","text":"细辛辛温，气味俱厚而能升能降，主入心、肺、肾经。辛能散寒，温能通脉，故能解表散寒，治风寒感冒、痰饮咳喘；其走窜力强，善于上达巅顶而深入鼻窍，可祛风止痛、通窍开闭，为治头痛、牙痛、鼻塞、鼻鼽、鼻渊之要药；又能温肺化饮，治寒饮伏肺之咳喘痰多量稀；其散寒止痛之功亦可用于风湿痹痛与脘腹冷痛。"},{"type":"paragraph","text":"现代研究证实细辛含挥发油，主要成分为甲基丁香酚（黄樟醚）、细辛酮等，小剂量有镇静、镇痛、局麻及抗炎作用，大剂量则对中枢神经系统产生强烈兴奋乃至抑制作用，毒性明显。古人有\"细辛不过钱\"之说，与现代剂量认识基本吻合。配伍上，细辛配川芎治风寒头痛，配白芷、辛夷治鼻渊鼻塞，配干姜、茯苓治寒饮咳喘，配附子治少阴寒化证，配石膏治胃火牙痛，配龙骨、牡蛎治心悸失眠。"},{"type":"table","caption":"细辛常见配伍与要点","head":["配伍","作用","要点"],"rows":[["细辛配川芎","祛风止痛、通窍","用于风寒头痛"],["细辛配白芷、辛夷","通窍止痛、宣肺","用于鼻渊、鼻塞流涕"],["细辛配干姜、茯苓","温肺化饮","用于寒饮咳喘痰稀"],["细辛配附子","温阳散寒通脉","用于少阴寒化证"]]},{"type":"quote","text":"主咳逆上气，头痛，风眩，腋下肿，肠鸣，痹，消痹。久服轻身长年。","source":"《神农本草经·草部·细辛》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"细辛含黄樟醚，具明确毒性，十八反中\"诸参辛芍叛藜芦\"，细辛反藜芦，绝不可与藜芦同用；气虚多汗、阴虚阳亢头痛、肺燥伤阴干咳者忌用，孕妇慎用。必须严格控制剂量，散剂每次不超过 1 g，入汤剂用量宜小且不宜久煎；过量可出现头痛、呕吐、气促、烦躁、颈项强直、抽搐甚至昏迷，应立即停用并就医。"},{"type":"keypoints","title":"掌握要点","items":["走窜力强，通行周身、达巅顶通鼻窍","治头痛、牙痛、鼻渊与寒饮咳喘的要药","含黄樟醚，毒性明确，剂量须严格控制","十八反：反藜芦；孕妇慎用"]}]},{"id":"shi-gao","title":"石膏","subtitle":"Gypsum Fibrosum ｜ 石膏、生石膏、煅石膏","category":"清热药","tags":["清热泻火","除烦止渴","收湿敛疮"],"meta":[{"label":"性味归经","value":"辛、甘，大寒；归肺、胃经"},{"label":"功效","value":"清热泻火，除烦止渴；煅用收湿敛疮、生肌止血"},{"label":"主治","value":"外感热病高热烦渴、肺热喘咳、胃火亢盛之牙痛头痛；溃疡不敛、湿疹、水火烫伤"},{"label":"用法用量","value":"煎服 15–60 g，宜先煎；煅石膏外用适量"},{"label":"使用注意","value":"脾胃虚寒及阴虚内热者忌用；煅石膏不宜入煎剂"}],"image":"","imageHint":"石膏","summary":"石膏为硫酸盐类矿物石膏 Fibrosum 的加工品，生用清热泻火，煅用收湿敛疮。其味辛甘而性大寒，质重气浮，主入肺、胃经，善清阳明气分之热，为清泻肺胃实热之要药。临床常用于外感热病气分实热所致壮热、大汗、大渴、脉洪大，肺热壅盛之咳喘，以及胃火上炎之牙痛头痛；煅石膏外用可治溃疡不敛、湿疹与水火烫伤。因其大寒伤胃，脾胃虚寒及阴虚内热者当忌用，入汤剂须先煎。","blocks":[{"type":"paragraph","text":"石膏为纤维石膏 Gypsum Fibrosum 的加工品。将生石膏打碎，置煅炉或火锅内煅至红透，失去结晶水，研细即为煅石膏；生石膏多内服清热，煅石膏多外用收湿。商品以色白、质酥、断面有光泽、无杂石者为佳，煅后应呈白色或灰白色，质地酥松者可作外用敷料。生石膏块状者需打碎先煎，使有效成分易于煎出。"},{"type":"paragraph","text":"石膏辛甘大寒，质重而气浮，入肺胃经而生清肃之性，善清阳明气分之热，为清泻肺胃实热之要药。用于外感热病邪在气分，症见壮热、大汗、大渴、脉洪大；又用于肺热壅盛之咳喘鼻翼煽动；胃火上炎之牙痛头痛、牙龈红肿溃烂；煅石膏外用能收湿敛疮、生肌止血，用于溃疡不敛、湿疹、水火烫伤等。"},{"type":"paragraph","text":"现代研究证实石膏煎剂有明显解热作用，其解热机制与抑制体温中枢及所含微量钙盐、硫酸钙对内毒素发热的拮抗有关，钙离子还可抑制神经肌肉兴奋性，故对神经性、牙源性疼痛亦有效。配伍方面，石膏配知母清热泻火，用于气分实热；配黄芩、桑白皮清肺平喘；配生地黄、玄参清营凉血治热入营血；配苍术清热燥湿治湿温；煅石膏配黄柏、青黛外敷治湿疹与疮疡。"},{"type":"table","caption":"石膏常见配伍与要点","head":["配伍","作用","要点"],"rows":[["石膏配知母","清热泻火、除烦止渴","用于气分实热、壮热烦渴"],["石膏配黄芩、桑白皮","清肺平喘","用于肺热壅盛之咳喘"],["石膏配生地黄、玄参","清热凉血养阴","用于热入营血、斑疹"],["煅石膏外用","收湿敛疮、生肌止血","用于溃疡、湿疹、水火烫伤"]]},{"type":"quote","text":"石膏，敷用治疮疡，煎服清里热。","source":"《本草纲目·石部·石膏》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"石膏大寒，脾胃虚寒、阴虚内热、便溏者忌用；孕妇慎用。生石膏入汤剂须先煎，且用量宜大（15–60 g）；煅石膏只供外用，不宜内服。外用于大面积创面时应注意其收涩之性可能影响渗出与分泌物引流，避免大面积长时间使用；服药期间忌食辛辣炙煿及生冷之品，过用可致胃脘不适、腹泻、畏寒。"},{"type":"keypoints","title":"掌握要点","items":["清泻肺胃气分实热之要药","生用清热，煅用收湿敛疮、生肌止血","入汤须先煎，用量宜大（15–60 g）","大寒伤胃，脾胃虚寒与阴虚内热者忌用"]}]},{"id":"huang-qin","title":"黄芩","subtitle":"Scutellariae Radix ｜ 黄芩、条芩、子芩、枯芩","category":"清热药","tags":["清热燥湿","泻火解毒","止血","安胎"],"meta":[{"label":"性味归经","value":"苦，寒；归肺、胆、脾、大肠、小肠经"},{"label":"功效","value":"清热燥湿，泻火解毒，止血，安胎"},{"label":"主治","value":"湿温暑湿、湿热痞满、泻痢、黄疸、肺热咳嗽、高热烦渴、血热吐衄、痈肿疮毒、胎动不安"},{"label":"用法用量","value":"煎服 3–10 g"},{"label":"使用注意","value":"脾胃虚寒者不宜；苦寒败胃，不宜久服过量"}],"image":"","imageHint":"黄芩","summary":"黄芩为唇形科植物黄芩 Scutellaria baicalensis Georgi 的干燥根，春季或秋季采挖，除去须根，撞去粗皮，蒸透或沸水略烫后晒干；根条上部色黄而充实者称\"子芩\"，中空者称\"枯芩\"，今多统称黄芩。其味苦而性寒，主入肺、胆、脾、大肠、小肠经，善清上焦肺热与少阳胆热，兼清大肠湿热，为湿温、黄疸、泻痢、肺热咳嗽之要药；又能凉血止血、泻火解毒，古称\"安胎之圣药\"。","blocks":[{"type":"paragraph","text":"黄芩为唇形科植物黄芩 Scutellaria baicalensis Georgi 的干燥根。春、秋二季采挖，除去须根与泥沙，撞去粗皮，蒸透或沸水略烫后晒干。商品以条粗、色黄、质坚实、味苦者为佳。古代因采收部位、产地与加工不同而分\"条芩\"（河北、山西产，条粗色黄而坚实）、\"子芩\"（根条上部细嫩、色黄而充实）、\"枯芩\"（老根、中空而色褐）之名，现代多以黄芩统用入药，处方名亦可分列。"},{"type":"paragraph","text":"黄芩苦寒，主入肺、胆、脾、大肠、小肠经。苦能燥湿、寒能清热，故善清上焦肺热与少阳胆热，并清大肠湿热，为治湿温暑湿、湿热痞满、黄疸、泻痢之要药；黄芩尤善清肺火，治肺热咳嗽；清热泻火故治热病烦渴、高热；入血分能凉血止血，治血热吐衄、崩漏；清热解毒治痈肿疮毒、咽喉肿痛；古人有\"黄芩乃安胎之圣药\"之说，用于胎热不安、胎动不安。"},{"type":"paragraph","text":"现代研究显示黄芩主含黄芩苷、汉黄芩素、黄芩素等黄酮类成分，具有抗菌、抗病毒、抗炎、解热、保肝利胆、降压、镇静及免疫调节等作用，临床用于上呼吸道感染、急性肝炎、肠炎、胆囊炎等有一定效果。配伍上，黄芩配黄连、黄柏清热燥湿泻火力宏（合称三黄），配柴胡和解少阳，配桑白皮、杏仁清肺止咳，配白术、白芍清热安胎，配大黄治热结便秘兼湿热，配生地黄凉血止血。"},{"type":"table","caption":"黄芩常见配伍与要点","head":["配伍","作用","要点"],"rows":[["黄芩配黄连、黄柏","清热燥湿泻火（三黄）","用于湿热痞满、泻痢、黄疸"],["黄芩配柴胡","和解少阳","用于少阳证寒热往来"],["黄芩配桑白皮、杏仁","清肺止咳","用于肺热咳嗽"],["黄芩配白术、白芍","清热安胎","用于胎热不安"]]},{"type":"quote","text":"主诸热黄疸，肠澼，泄痢，逐水，下血闭，恶疮疽蚀火疡。","source":"《神农本草经·草部·黄芩》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"黄芩苦寒败胃，脾胃虚寒、食少便溏者不宜长期或大量使用；若无胎热之证，孕妇亦当慎用。服用期间如出现胃部不适、食欲减退、便溏、头晕，应减量或停用并咨询医师；本品含黄芩苷等黄酮类成分，与部分西药存在代谢与吸收层面的相互作用，合并用药时须告知医师。"},{"type":"keypoints","title":"掌握要点","items":["清热燥湿，尤善清肺热与少阳胆热","兼能凉血止血，为治血热吐衄之要药","古称安胎圣药，用于胎热不安","苦寒败胃，脾胃虚寒者不宜久服"]}]},{"id":"huang-lian","title":"黄连","subtitle":"Coptidis Rhizoma ｜ 黄连、味连、雅连、云连","category":"清热药","tags":["清热燥湿","泻火解毒","清心除烦"],"meta":[{"label":"性味归经","value":"苦，寒；归心、脾、胃、肝、胆、大肠经"},{"label":"功效","value":"清热燥湿，泻火解毒"},{"label":"主治","value":"湿热痞满、呕吐吞酸、泻痢、黄疸、高热神昏、心火亢盛、心烦不寐、血热吐衄、目赤牙痛、消渴、痈肿疔疮"},{"label":"用法用量","value":"煎服 2–5 g；外用适量"},{"label":"使用注意","value":"脾胃虚寒者忌用；不宜过量久服；含小檗碱，与含鞣质药物同服可降低疗效"}],"image":"","imageHint":"黄连","summary":"黄连为毛茛科植物黄连 Coptis chinensis Franch.、三角叶黄连 Coptis deltoidea 或云连 Coptis teeta 的干燥根茎，秋季采挖，除去须根、泥沙，晒干后撞去茎枝并除去节须；商品分味连（云连）、雅连、蜀连等，以根茎粗壮、色黄、味极苦者为佳。其苦寒之性极强，主入心、脾、胃、肝、胆、大肠经，能上清心火、中清脾胃、下泻大肠湿热，为三焦湿热俱盛之要药，主治湿热痞满、泻痢、呕吐吞酸、高热神昏、心烦不寐、消渴与痈肿疔疮。","blocks":[{"type":"paragraph","text":"黄连为毛茛科植物黄连 Coptis chinensis Franch.、三角叶黄连 Coptis deltoidea C.Y.Cheng et Hsiao 或云连 Coptis teeta Wall. 的干燥根茎。秋季采挖，除去须根与泥沙，晒干后撞去茎枝，除去残留茎节及须根。商品以根茎粗壮、色黄、质坚硬、味极苦者为佳，产于四川者称\"味连\"，产于云南者称\"云连\"，产于江浙者称\"雅连\"，以味连品质最佳。因其味极苦，服用时常与姜汁或紫苏汁同用以缓和苦寒之性并增强和胃止呕之效。"},{"type":"paragraph","text":"黄连苦寒之性极强，主入心、脾、胃、肝、胆、大肠经，能上清心火、中清脾胃实热、下泻大肠湿热，为三焦湿热俱盛之要药。治湿热痞满、脘腹胀痛、呕吐吞酸、泻痢痢疾、湿热黄疸；善清心火，治高热神昏、心烦不寐、口舌生疮、目赤肿痛；清胃火治牙痛、消渴；清热解毒治痈肿疔疮、内外疮疡；入血分凉血止血治血热吐衄。"},{"type":"paragraph","text":"现代研究证明黄连含小檗碱（黄连素）、黄连碱、巴马汀、掌叶防己碱等生物碱，具有广谱抗菌、抗病毒、抗炎、降血糖、抗溃疡、镇静等作用，临床用于细菌性痢疾、肠炎、消化性溃疡等疗效确切，小檗碱为的物质基础；因其在肠道内容易与鞣质结合而沉淀，故服用前后不宜与浓茶及含鞣质中药同服。配伍上，黄连配黄芩、黄柏为三黄，配木香治湿热泻痢里急后重，配黄芩、栀子治热毒炽盛，配朱砂、栀子清心除烦，配石膏治胃火牙痛。"},{"type":"table","caption":"黄连常见配伍与要点","head":["配伍","作用","要点"],"rows":[["黄连配黄芩、黄柏","清热燥湿泻火（三黄）","用于三焦湿热、火毒炽盛"],["黄连配木香","清热燥湿、行气止痛","用于泻痢里急后重"],["黄连配栀子、竹叶","清心除烦","用于心火亢盛之失眠"],["黄连配石膏、知母","清胃泻火","用于胃火牙痛、消渴"]]},{"type":"quote","text":"主热气目痛，眦伤泣出，明目，肠澼，腹痛下痢，妇人阴中肿痛。","source":"《神农本草经·草部·黄连》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"黄连大苦大寒，脾胃虚寒、阴虚津亏者忌用，孕妇慎用；过量或久服易致恶心呕吐、腹泻、食欲不振，并可出现口苦、心烦、头晕等苦味药过量表现。含小檗碱，不宜与含鞣质的浓茶、诃子、石榴皮、五倍子同服；与地高辛、华法林等药物同用时应告知医师并监测相关指标。"},{"type":"keypoints","title":"掌握要点","items":["三焦湿热俱盛之要药，泻火力强","善清心火，治心烦不寐、口舌生疮","含小檗碱，抗菌作用确切","大苦大寒，脾胃虚寒者忌用、不可久服"]}]},{"id":"jin-yin-hua","title":"金银花","subtitle":"Lonicerae Japonicae Flos ｜ 金银花、银花、双花、二花","category":"清热药","tags":["清热解毒","疏散风热","清利咽喉"],"meta":[{"label":"性味归经","value":"甘，寒；归肺、心、胃经"},{"label":"功效","value":"清热解毒，疏散风热"},{"label":"主治","value":"痈肿疔疮、喉痹、丹毒、热毒血痢、风热感冒、温病发热"},{"label":"用法用量","value":"煎服 6–15 g"},{"label":"使用注意","value":"脾胃虚寒及气虚疮疡脓清者忌用；不宜久服"}],"image":"","imageHint":"银花","summary":"金银花为忍冬科植物忍冬 Lonicera japonica Thunb. 的干燥花蕾或带初开的花，夏初花开放前采收、干燥，商品以花蕾多、色黄白、气清香者为佳；初开为白、盛开转黄，故名金银花。其藤茎另作\"忍冬藤\"入药，功能清热利湿、通经活络。金银花甘寒而芳香，既能清热解毒，又能疏散风热，为治热毒证与风热感冒的常用要药，广泛用于痈肿疔疮、咽喉肿痛、丹毒、热毒血痢与温病发热，因其性寒易伤脾胃，脾胃虚寒者不宜久服。","blocks":[{"type":"paragraph","text":"金银花为忍冬科植物忍冬 Lonicera japonica Thunb. 的干燥花蕾或带初开的花。夏初花开放前采收，干燥；有\"黄白花\"之别，初开色白，盛开转黄，商品以花蕾多、色黄白、气清香者为佳。花蕾与初开花均可入药，习称\"金银花\"；其带叶藤茎则另作\"忍冬藤\"入药，长于清热利湿、通经活络，用于风湿热痹、筋骨疼痛。与山银花分开经营，临床疗效相近而品种有别。"},{"type":"paragraph","text":"金银花甘寒，气味芳香，既能清解气分与血分热毒，又能疏散风热，为治热毒证与风热感冒之要药。用于痈肿疔疮、内外疮疡、咽喉肿痛（喉痹）、丹毒、热毒血痢；用于风热感冒、温病初起之发热恶寒、咽痛咳嗽。其芳香轻扬之性还可透邪外出，使热毒从表而解；因兼能通络，故亦用于风湿热痹与咽喉肿痛。"},{"type":"paragraph","text":"现代研究显示金银花含绿原酸、木犀草苷、挥发油、鞣质及多糖等成分，具有广谱抗菌、抗病毒、抗炎、解热、增强免疫等作用，临床广泛用于上呼吸道感染、扁桃体炎、流行性感冒及多种感染性疾病，绿原酸与木犀草苷为其主要抗菌有效成分。配伍上，金银花配连翘清热解毒、疏散风热（银翘散），配黄芩清肺泄热，配蒲公英、紫花地丁治疮疡肿毒，配荆芥、防风治风热感冒，配当归治热毒血痢兼血虚。"},{"type":"table","caption":"金银花常见配伍与要点","head":["配伍","作用","要点"],"rows":[["金银花配连翘","清热解毒、疏散风热","用于温病初起与热毒疮疡"],["金银花配蒲公英、紫花地丁","清热解毒消痈","用于乳痈、疔疮"],["金银花配荆芥、防风","疏风解表透邪","用于风热感冒"],["金银花配黄芩、桑白皮","清肺泄热","用于肺热咳嗽"]]},{"type":"quote","text":"忍冬，治一切风湿气及诸肿毒、痈疽疥癣、杨梅诸恶疮，散热解毒。","source":"《本草纲目·草部·忍冬》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"金银花甘寒，脾胃虚寒、气虚疮疡脓清者忌用或慎用；久服、大量服用易损伤脾胃阳气，出现腹泻、胃纳减少、肠鸣。含鞣质与绿原酸，与铁剂、酶类制剂、浓茶及含鞣质中药同服可降低吸收或影响疗效；孕妇、哺乳期妇女及脾胃虚寒者应在医师指导下使用。"},{"type":"keypoints","title":"掌握要点","items":["清热解毒、疏散风热，治温病与疮疡要药","花蕾入药为金银花，藤茎另作忍冬藤","芳香轻扬，可透邪外出","性寒伤中，脾胃虚寒者不宜久服"]}]},{"id":"sheng-di-huang","title":"生地黄","subtitle":"Rehmanniae Radix ｜ 生地黄、干地黄、鲜地黄","category":"清热药","tags":["清热凉血","养阴生津","生津止渴"],"meta":[{"label":"性味归经","value":"甘、苦，寒；归心、肝、肾经"},{"label":"功效","value":"清热凉血，养阴生津"},{"label":"主治","value":"热入营血、温毒发斑、吐血衄血、热病伤阴、舌绛烦渴、津伤便秘、阴虚发热、骨蒸劳热、内热消渴"},{"label":"用法用量","value":"煎服 10–15 g；鲜品用量加倍或捣汁饮"},{"label":"使用注意","value":"脾虚湿滞、腹满便溏者不宜；性寒滋腻碍胃"}],"image":"","imageHint":"生地","summary":"生地黄为玄参科植物地黄 Rehmannia glutinosa (Gaertn.) DC. 的新鲜或干燥块根，秋季采挖、除去须根、洗净，鲜者称\"鲜地黄\"，干燥者称\"生地黄\"，经酒炖或蒸制则为\"熟地黄\"，功用由凉血养阴转为补血滋阴、益精填髓。生地黄甘苦寒凉，主入心、肝、肾经，质润能清热凉血、养阴生津，为热入营血与阴虚内热证之要药，主治斑疹吐衄、热病伤阴、津亏便秘与骨蒸劳热。因其寒凉滋腻，脾虚湿滞、腹满便溏者不宜。","blocks":[{"type":"paragraph","text":"生地黄为玄参科植物地黄 Rehmannia glutinosa (Gaertn.) DC. 的新鲜或干燥块根。秋季采挖，除去须根与泥沙，洗净。鲜者称\"鲜地黄\"，干燥者称\"生地黄\"，商品以块大、体重、断面黄褐、味甜微苦者为佳；经酒炖或反复蒸晒后成为\"熟地黄\"，其性由寒转温，功由凉血养阴转为补血滋阴、益精填髓，临床应用当有区别。生地黄块形不规则，须与玄参、块根类药材仔细鉴别。"},{"type":"paragraph","text":"生地黄甘苦寒凉，主入心、肝、肾经。质润而能清热凉血，入于血分，治温热病热入营血所致身热夜甚、心烦谵语、舌绛、斑疹，以及血热妄行之吐血、衄血、便血；又能养阴生津，治热病后期伤阴之舌绛烦渴、口干咽燥、内热消渴；其滋阴之力可退虚热，治阴虚发热、骨蒸劳热；并能滋阴润燥通便，治津亏便秘。"},{"type":"paragraph","text":"现代研究证明生地黄含梓醇、地黄苷、多糖及多种氨基酸，具有强心、利尿、降血糖、抗凝血、增强免疫与调节内分泌等作用，临床用于心悸、糖尿病、出血性疾病、阴虚内热及干燥综合征等有一定效果，梓醇与生地黄多糖为其主要物质基础。配伍上，生地黄配水牛角、赤芍、丹皮清营凉血治热入营血，配玄参、麦冬养阴生津，配知母滋阴降火，配牡蛎、龟板滋阴潜阳，配桃仁、红花养血活血用于产后血虚。"},{"type":"table","caption":"生地黄常见配伍与要点","head":["配伍","作用","要点"],"rows":[["生地黄配水牛角、赤芍","清营凉血","用于热入营血、斑疹吐衄"],["生地黄配玄参、麦冬","养阴生津、增液润燥","用于热病伤阴、津亏便秘"],["生地黄配知母、黄柏","滋阴降火","用于阴虚火旺、骨蒸潮热"],["生地黄配玄参、牡蛎","滋阴潜阳","用于阴虚阳亢之头痛眩晕"]]},{"type":"quote","text":"主折跌绝筋，伤中，逐血痹，填骨髓，长肌肉。","source":"《神农本草经·草部·干地黄》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"生地黄甘寒滋腻，脾虚湿滞、腹满便溏、痰湿壅盛者不宜，脾胃虚弱者久服易致纳呆、腹泻；服药期间忌食萝卜、浓茶及寒凉生冷之品。鲜品汁液黏腻，剂量过大易致恶心、脘腹不适；配伍时宜稍佐枳壳、厚朴等行气药以防滋腻碍胃；孕妇、哺乳期妇女及急性肠炎患者应慎用。"},{"type":"keypoints","title":"掌握要点","items":["清热凉血养阴，为热入营血之要药","生地偏于凉血养阴，熟地偏于补血填精","滋腻碍胃，脾虚便溏者不宜久服","鲜品凉血之功较强，干品生津更佳"]}]},{"id":"chai-hu","title":"柴胡","subtitle":"Bupleurum chinense DC. ｜ 柴胡、醋柴胡、北柴胡","category":"解表药","tags":["解表退热","疏肝解郁","升举阳气"],"meta":[{"label":"性味归经","value":"辛、苦，微寒；归肝、胆、肺经"},{"label":"功效","value":"解表退热，疏肝解郁，升举阳气"},{"label":"主治","value":"表证发热、少阳证寒热往来、肝郁气滞之胁肋胀痛与月经不调、气虚下陷之久泻脱肛与脏器下垂"},{"label":"用法用量","value":"煎服 3–10 g；疏肝宜醋炙，升提宜酒炙"},{"label":"使用注意","value":"真阴亏损、肝阳上升者忌用；大剂量可致头晕、呕逆"}],"image":"","imageHint":"柴胡","summary":"柴胡为伞形科植物柴胡 Bupleurum chinense DC. 或同属近缘植物的干燥根，春秋二季采挖，除去茎叶及泥沙晒干，北方产者称北柴胡，南方产者称南柴胡，商品以北柴胡为优，另有醋柴胡、酒柴胡等炮制品。其味辛苦而性微寒，主入肝、胆、肺经，既能解表退热、透邪外出，又能疏肝解郁条达肝气，并可升举清阳，为治少阳证寒热往来、肝郁气滞之胁痛月经不调以及中气下陷之久泻脱肛、脏器下垂的常用要药。","blocks":[{"type":"paragraph","text":"柴胡为伞形科植物柴胡 Bupleurum chinense DC. 或同属近缘种类的干燥根，春秋二季采挖，拣去茎叶及泥沙，晒干。北方产者根条粗壮、色黄褐，习称北柴胡；南方产者根细、色红褐，习称南柴胡，商品以北柴胡为优。炮制品有柴胡片、醋柴胡与酒柴胡：生柴胡解表退热之力较胜，醋柴胡善入肝经而长于疏肝止痛，酒柴胡升提阳气之力较强，各随证选用。"},{"type":"paragraph","text":"柴胡苦辛微寒，主入肝、胆、肺经。辛能散、苦能泄，微寒可清，故能解表退热、透邪外出，为邪在少阳、寒热往来之要药；其性轻灵升散，善于条达肝气、疏解肝郁，用于肝郁气滞之胸胁胀痛、脘腹胀满、嗳气以及月经不调、痛经；又能升举清阳、举陷止脱，用于中气下陷之久泻脱肛、子宫脱垂、胃下垂等脏器下垂。此外与养血药同用可疏肝补脾而调经，与解表药同用可增强退热之效。"},{"type":"paragraph","text":"现代药理研究显示，柴胡含柴胡皂苷、挥发油、β-谷甾醇等成分，具有解热、镇静、镇痛、抗炎、保肝降酶、抗病毒、调节免疫及抗抑郁等作用，临床用于感冒发热、肝胆疾病、病毒性肝炎、乳腺增生等有较好疗效。配伍上，柴胡配黄芩和解少阳，配葛根解肌退热，配白芍、枳壳疏肝理脾，配升麻、党参升阳举陷，配牡蛎、桂枝平冲降逆，配香附、当归养血疏肝调经。"},{"type":"table","caption":"柴胡常见配伍与要点","head":["配伍","作用","要点"],"rows":[["柴胡配黄芩","和解少阳、退热","用于少阳证寒热往来"],["柴胡配葛根","解肌发表、透邪退热","用于表证发热、项背强痛"],["柴胡配白芍、枳壳","疏肝理脾、行气消胀","用于肝郁气滞之胁痛"],["柴胡配升麻、党参","升阳举陷、益气退热","用于中气下陷之久泻脱肛"]]},{"type":"quote","text":"主心腹肠胃中结气，饮食积聚，寒热邪气，推陈致新。久服轻身明目益精。","source":"《神农本草经·草部·柴胡》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"柴胡苦辛升散，易耗气伤阴，真阴亏损、肝阳上升、阴虚火旺及肝阳化风者忌用或慎用；无肝郁气滞、无表证发热者不宜多服。服用期间若出现头晕、恶心、呕吐、腹胀、食欲减退或心烦易怒，应减量或停用并咨询医师。肝功能严重异常者应在医师监测下使用；本品与某些可能影响肝酶的西药同用时尤须谨慎。"},{"type":"keypoints","title":"掌握要点","items":["解表退热、疏肝解郁、升举阳气三用皆长","少阳寒热往来与中气下陷为其两大主治","醋炙偏于疏肝止痛，酒炙偏于升提","真阴亏损、肝阳上升者忌用"]}]},{"id":"pu-gong-ying","title":"蒲公英","subtitle":"Taraxacum mongolicum Hand.-Mazz. ｜ 蒲公英、婆婆丁、奶浆草","category":"清热药","tags":["清热解毒","消肿散结","利湿通淋"],"meta":[{"label":"性味归经","value":"苦、甘，寒；归肝、胃经"},{"label":"功效","value":"清热解毒，消肿散结，利湿通淋"},{"label":"主治","value":"疔疮肿毒、乳痈、瘰疬、目赤、咽痛、肺痈、肠痈、湿热黄疸、热淋涩痛"},{"label":"用法用量","value":"煎服 10–15 g；外用适量"},{"label":"使用注意","value":"用量过大可致缓泻；阳虚外寒、脾胃虚寒者忌用"}],"image":"","imageHint":"蒲公","summary":"蒲公英为菊科植物蒲公英 Taraxacum mongolicum Hand.-Mazz.、药用蒲公英 T. officinale Weber 等的干燥全草，春至初秋采挖，除去泥沙，晒干，商品以叶多、色灰绿、根完整者为佳。其味苦甘而性寒，主入肝、胃经，善清热解毒、消肿散结，为治疔疮肿毒与乳痈之要药，民间亦广泛用于清肝明目、治热淋；因其性寒滑利，脾胃虚寒与阳虚外寒者不宜多食久服。临床亦常配伍紫花地丁、野菊花同用，以增强清热解毒、消痈散结之效。","blocks":[{"type":"paragraph","text":"蒲公英为菊科植物蒲公英 Taraxacum mongolicum Hand.-Mazz.、药用蒲公英 Taraxacum officinale Weber 等的干燥全草，春至初秋采挖，除去泥沙，晒干。商品以叶多、色灰绿、根完整、无杂质者为佳；鲜用者随时可采，民间常作食疗。另有同科植物不同种入药，形态相近而成分有别，采收时须依药典规定辨认真伪，不可用园地野生之品随意代替。"},{"type":"paragraph","text":"蒲公英苦甘寒凉，主入肝、胃经。苦寒能清热解毒，且能消肿散结，尤善消乳痈、疔疮肿毒，为治热毒证之要药，临床用于乳痈、疔疮、痈肿疮毒、咽喉肿痛；入肝经能清肝明目，治目赤肿痛；其甘淡渗利之性又能利湿通淋，治热淋涩痛、湿热黄疸；兼能清肝和胃，故对肝火目赤、胃热呕吐亦可选用。"},{"type":"paragraph","text":"现代研究表明，蒲公英含蒲公英甾醇、蒲公英素、菊糖、胆碱等成分，具有广谱抗菌、抗炎、利胆保肝、利尿、增强免疫及抗肿瘤等作用，临床用于急性乳腺炎、泌尿系感染、胆囊炎、肝炎等有较好效果。配伍上，蒲公英配金银花、连翘清热解毒治疮疡，配紫花地丁、野菊花治疔毒，配乳香、没药治乳痈初起，配茵陈治湿热黄疸，配车前子、滑石治热淋，配大黄治热毒内结之便秘。"},{"type":"table","caption":"蒲公英常见配伍与要点","head":["配伍","作用","要点"],"rows":[["蒲公英配金银花、连翘","清热解毒、消肿散结","用于热毒疮疡、咽喉肿痛"],["蒲公英配乳香、没药","活血消肿止痛","用于乳痈初起红肿热痛"],["蒲公英配紫花地丁","清热解毒、消痈散结","用于疔疮肿毒"],["蒲公英配茵陈、车前子","利湿退黄、通淋","用于湿热黄疸、热淋涩痛"]]},{"type":"quote","text":"解食毒，散滞气，消热毒、恶肿、疔疮、乳痈之肿痛。","source":"《本草纲目·草部·蒲公英》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"蒲公英苦寒滑利，脾胃虚寒、阳虚外寒、大便溏泄者忌用或慎用；用量过大易致缓泻，腹泻、脘腹不适时应减量。孕妇、哺乳期妇女及儿童用量宜偏小；其寒凉之性于虚寒证中尤须留意。对菊科植物过敏者使用时应谨慎，出现皮疹、瘙痒等应立即停用。"},{"type":"keypoints","title":"掌握要点","items":["清热解毒、消肿散结，为治乳痈之要药","全草入药，鲜品亦可，兼能清肝明目","苦寒滑利，脾胃虚寒者不宜多服","过量可致缓泻，腹泻者慎用"]}]},{"id":"da-huang","title":"大黄","subtitle":"Rhei Radix et Rhizoma ｜ 大黄、将军、川军、锦纹","category":"泻下药","tags":["泻下攻积","清热泻火","凉血解毒","逐瘀通经"],"meta":[{"label":"性味归经","value":"苦，寒；归脾、胃、大肠、肝、心包经"},{"label":"功效","value":"泻下攻积，清热泻火，凉血解毒，逐瘀通经，利湿退黄"},{"label":"主治","value":"实热积滞便秘、血热吐衄、目赤咽肿、痈肿疔疮、瘀血经闭、跌打损伤、湿热痢疾、黄疸尿赤、烫伤"},{"label":"用法用量","value":"煎服 3–15 g；用于泻下不宜久煎，外用适量"},{"label":"使用注意","value":"久病体虚、脾胃虚弱者及妇女月经期、哺乳期、孕期忌用；久服可致结肠黑变病"}],"image":"","imageHint":"大黄","summary":"大黄为蓼科植物掌叶大黄 Rheum palmatum L.、唐古特大黄 R. tanguticum 或药用大黄 R. officinale 的干燥根和根茎，秋末茎叶枯萎时采挖，除去细根，刮去外皮，切瓣或段，绳穿成串干燥或直接干燥后撞去外皮，商品以色棕黄、纹理清晰、质坚实者为佳。其味苦而性寒，沉降下行，主入脾、胃、大肠、肝、心包经，既能泻下攻积、荡涤肠胃，又能清热泻火、凉血解毒、逐瘀通经，为\"将军\"之称的热病与积滞要药。","blocks":[{"type":"paragraph","text":"大黄为蓼科植物掌叶大黄 Rheum palmatum L.、唐古特大黄 Rheum tanguticum Maxim. ex Balf. 或药用大黄 Rheum officinale Baill. 的干燥根和根茎，秋末茎叶枯萎时采挖，除去细根，刮去外皮，切瓣或段，绳穿成串干燥或直接干燥后撞去外皮。商品以色棕黄、纹理清晰、质坚实、气味特异者为佳，产于甘肃、青海、陕西、山西者为地道，习称\"西大黄\"或\"川军\"。炮制品有生大黄、酒大黄、熟大黄、大黄炭、复方大黄的不同取向：生用泻下力强，酒制后善清上焦血分，熟用泻下力缓而能润肠，制炭则长于止血。"},{"type":"paragraph","text":"大黄苦寒沉降，主入脾、胃、大肠、肝、心包经。苦能泄下、寒能清热，沉降下行而不伤上焦，故能泻下攻积、荡涤肠胃，推陈致新，为治实热积滞、燥屎内结之便秘的要药；其苦寒之性又能清热泻火，治气分实热壮热烦躁、阳明腑实证及血分热毒之吐衄、目赤咽肿、痈肿疔疮；入血分能凉血逐瘀，治瘀血经闭、跌打损伤、瘀滞腹痛；还能利湿退黄，治湿热黄疸与热淋，外用可治水火烫伤。"},{"type":"paragraph","text":"现代研究显示大黄含蒽醌苷（番泻苷、大黄素、大黄酸）、鞣质、没食子酸等成分，泻下作用以结合型蒽醌苷为主，且须经肠道菌群转化为游离型才起作用，故泻下作用常在服药后六至八小时出现，临床用于急腹症与功能性便秘均有确切疗效；其所含鞣质能收敛止血，故大黄炭用于出血。配伍上，大黄配芒硝攻下力峻，配枳实、厚朴即大承气汤治阳明腑实，配黄连、黄芩、栀子泻火解毒，配桃仁、红花逐瘀通经，配茵陈、栀子利湿退黄，配牡丹皮凉血消痈。"},{"type":"table","caption":"大黄常见配伍与要点","head":["配伍","作用","要点"],"rows":[["大黄配芒硝","软坚攻下、峻下热结","为治阳明腑实之要药"],["大黄配枳实、厚朴","行气消积、通腑泄热","用于痞满燥实俱全之腑实证"],["大黄配黄连、黄芩、栀子","泻火解毒","用于火热毒盛诸证"],["大黄炭配白及、三七","凉血止血、收敛生肌","用于血热出血与创面渗出"]]},{"type":"quote","text":"主下瘀血，血闭，寒热，破癥瘕积聚，留饮宿食，荡涤肠胃，推陈致新，通利水谷，调中化食，安和五脏。","source":"《神农本草经·草部·大黄》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"大黄苦寒沉降，易伤脾胃、耗气伤阴，久病体虚、脾胃虚弱者忌用；妇女月经期、哺乳期及孕期忌用；肠梗阻、严重脱水者禁用。本品所含蒽醌苷可刺激肠黏膜，长期服用可致结肠黑变病与继发性便秘，须间断使用并配合健脾之品；腹泻、恶心、腹痛为常见反应，孕妇尤应慎用；与大黄同类的番泻叶、芦荟等亦不宜叠加使用。"},{"type":"keypoints","title":"掌握要点","items":["泻下攻积，为实热积滞便秘之要药","生用泻下力强，酒制清上焦血分，制炭止血","含蒽醌苷，长期服用可致结肠黑变病","脾胃虚弱者、孕期及月经期忌用"]}]},{"id":"mang-xiao","title":"芒硝","subtitle":"Natrii Sulfas ｜ 芒硝、朴硝、玄明粉","category":"泻下药","tags":["泻下通便","润燥软坚","清火消肿"],"meta":[{"label":"性味归经","value":"咸、苦，寒；归胃、大肠经"},{"label":"功效","value":"泻下通便，润燥软坚，清火消肿"},{"label":"主治","value":"实热积滞、腹满胀痛、大便燥结、肠痈肿痛；外治乳痈、痔疮、痈肿、目赤、咽痛"},{"label":"用法用量","value":"6–12 g，一般不入煎剂，待汤剂煎得后溶入汤液服用；外用适量"},{"label":"使用注意","value":"脾胃虚寒者忌用；孕妇慎用；含硫酸钠，不宜久服"}],"image":"","imageHint":"芒硝","summary":"芒硝为硫酸钠 Na2SO4·10H2O 的结晶，主含硫酸钠，习称朴硝、玄明粉，商品以无色透明、质脆、色白、条块分明者为佳。其味咸苦而性寒，主入胃、大肠经，咸能软坚润下，苦能泄热，故能泻下通便、润燥软坚，为治实热积滞、燥屎坚结之要药，常与大黄相须为用；外用又能清火消肿，用于乳痈、痔疮、痈肿与咽喉肿痛。脾胃虚寒者忌用，孕妇慎用。","blocks":[{"type":"paragraph","text":"芒硝为硫酸盐类矿物芒硝 Nitrii Sulfas 所含结晶，或用芒硝与朴硝的加工品，主要成分为含水硫酸钠，习称朴硝、玄明粉。商品以无色透明、质脆易碎、色白、条块分明、无杂质者为佳，产于河南、河北、山东、山西、江苏等地者多由芒硝加工而得。风化后所得粉末称为\"风化硝\"，质地更纯。传统入汤剂时不与群药同煎，待其他药物煎得后，取汤液冲入搅匀溶解服用，可避免结晶析出。"},{"type":"paragraph","text":"芒硝咸苦寒降，主入胃、大肠经。咸能软坚润下，苦寒能泄热，故能泻下通便、润燥软坚，为治实热积滞、燥屎坚结不通、腹满胀痛之要药，常与大黄相须为用而增强攻下之力；其咸寒之性又能清火消肿，外用可治乳痈初起红肿热痛、痔疮肿痛、痈肿疮毒以及咽喉肿痛、目赤肿痛；内服还可清热通淋，治热淋涩痛。"},{"type":"paragraph","text":"现代研究证实芒硝主含硫酸钠，口服后不易被吸收，在肠内形成高渗，保留水分而刺激肠蠕动，产生缓和的泻下作用，故用于实热积滞与外用消肿均有确切疗效；外用可借其高渗与吸热作用消散局部炎症。配伍上，芒硝配大黄治阳明腑实证，配枳实、厚朴治痞满燥实，配桃仁、红花治产后瘀滞腹痛，外用配硼砂、冰片治咽喉肿痛，配黄柏、蒲公英外敷治疮疡肿毒。"},{"type":"table","caption":"芒硝常见配伍与要点","head":["配伍","作用","要点"],"rows":[["芒硝配大黄","软坚攻下、峻下热结","为治阳明腑实之要药"],["芒硝配枳实、厚朴","行气通腑、消痞除满","用于痞满燥实之腑实证"],["芒硝配桃仁、红花","逐瘀通下","用于产后瘀滞腹痛"],["芒硝外用配硼砂、冰片","清热消肿止痛","用于咽喉肿痛、目赤"]]},{"type":"quote","text":"主百病，除寒热邪气，逐六腑积聚，结固留癖。","source":"《神农本草经·土部·朴硝》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"芒硝咸苦大寒，脾胃虚寒、便溏者忌用；孕妇慎用；水肿、高血压、心衰者因钠盐负荷应慎用。本品主含硫酸钠，过量或久服可致水样腹泻、脱水、电解质紊乱，故须按剂量使用并注意补液；外用亦可致局部皮肤刺激，出现皮疹、瘙痒应停用。本品不宜与硫黄同用，亦不与含钙、含铝的药物同时服用。"},{"type":"keypoints","title":"掌握要点","items":["咸能软坚，苦能泄热，润燥通便之要药","与大黄相须为用，治阳明腑实证","一般不入煎剂，待汤成后溶入","脾胃虚寒者忌用，久服可致水样腹泻"]}]},{"id":"huo-ma-ren","title":"火麻仁","subtitle":"Cannabis Fructus ｜ 火麻仁、大麻仁、麻子仁","category":"泻下药","tags":["润肠通便","润燥","治肠燥便秘"],"meta":[{"label":"性味归经","value":"甘，平；归脾、胃、大肠经"},{"label":"功效","value":"润肠通便"},{"label":"主治","value":"血虚津枯肠燥便秘、津伤口渴"},{"label":"用法用量","value":"煎服 9–15 g，打碎入煎；或入丸、散"},{"label":"使用注意","value":"肠滑者慎用；孕妇慎用；过量可致恶心、呕吐、腹痛"}],"image":"","imageHint":"麻仁","summary":"火麻仁为桑科植物大麻 Cannabis sativa L. 的干燥成熟果实，秋至冬间果实成熟时采割，除去杂质，晒干，商品以粒大、饱满、色灰褐、仁白者为佳。其味甘而性平，主入脾、胃、大肠经，甘润多脂，能润肠通便、润燥通结，为治年老体弱、久病产后、津血亏虚所致肠燥便秘之要药，兼可润燥止渴。其性润滑平和，孕妇及脾虚便溏者当慎用。","blocks":[{"type":"paragraph","text":"火麻仁为桑科植物大麻 Cannabis sativa L. 的干燥成熟果实，秋至冬间果实成熟时采割，除去杂质，晒干。商品以粒大、饱满、完整、色灰褐、仁白、油润者为佳，产于东北、华北、西北各省区。火麻仁含脂肪油约三成，入汤剂宜打碎捣烂以利有效成分煎出；亦可炒用或与陈皮、杏仁、松子仁等配伍入丸剂。另有\"麻子仁\"\"火麻子\"等别名，均指同一药材。"},{"type":"paragraph","text":"火麻仁甘平而质润多脂，主入脾、胃、大肠经。甘能润、油能滑，故能润肠通便、润燥通结，缓和下泄而不伤正，为治津血亏虚之肠燥便秘的要药，尤宜于年老体弱、久病产后、产后血虚、大便燥结难下者；对肠燥便秘兼有津伤口渴者，服之尤宜。因其质润滑利，故常与杏仁、郁李仁、桃仁等养血润燥药配伍以加强润下之功。"},{"type":"paragraph","text":"现代研究显示火麻仁所含脂肪油主要是亚油酸与α-亚麻酸等多不饱和脂肪酸，在肠内形成油膜并润滑肠壁，缓和刺激肠蠕动而引起排便，属容积性与润滑性泻药，作用温和，适用于习惯性便秘与老年便秘；其提取物亦有降血脂、抗衰老作用。配伍上，火麻仁配杏仁、桃仁、郁李仁润肠通便，配生地黄、当归养血润燥，配陈皮、枳实理气宽中以防滋腻碍中，配白芍养阴和营治老人血虚便秘。"},{"type":"table","caption":"火麻仁常见配伍与要点","head":["配伍","作用","要点"],"rows":[["火麻仁配杏仁、桃仁","润肠通便","用于津血亏虚之肠燥便秘"],["火麻仁配生地黄、当归","养血滋阴、润燥通便","用于产后血虚便秘"],["火麻仁配陈皮、枳实","润下与行气并用","用于气滞便秘、脘腹胀满"],["火麻仁配白芍、甘草","养阴和营、缓急止痛","用于老人虚秘"]]},{"type":"quote","text":"主五脏，益精明气，长肌肉，润肠燥。","source":"《神农本草经·谷部·麻子》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"火麻仁甘润滑利，脾虚便溏、肠滑湿盛者慎用；孕妇慎用，因其润下之力可助胎下动。大剂量或过量服用可出现恶心、呕吐、腹痛、腹泻等反应，应立即减量；所含油脂较多，服后如感脘腹胀满可配陈皮、枳实以行气除满。大麻为我国管制类经济植物，种植与采收须严格遵守有关规定，工业用麻子不得作药用。"},{"type":"keypoints","title":"掌握要点","items":["润肠通便，为肠燥便秘之要药","甘平质润，缓下不伤正，老人虚秘尤宜","入汤剂宜打碎，以利有效成分煎出","肠滑便溏者慎用，孕妇慎用"]}]},{"id":"fan-xie-ye","title":"番泻叶","subtitle":"Sennae Folium ｜ 番泻叶、旃那叶、异名番泻叶","category":"泻下药","tags":["泻下通便","导滞","消食"],"meta":[{"label":"性味归经","value":"甘、苦，寒；归大肠经"},{"label":"功效","value":"泻下通便"},{"label":"主治","value":"热结便秘；亦可用于习惯性便秘及老年便秘"},{"label":"用法用量","value":"煎服 5–10 g，宜后下；或开水泡服 1.5–3 g"},{"label":"使用注意","value":"哺乳期、月经期及孕妇忌用；肠梗阻患者禁用；久服可致依赖与肠黑变病"}],"image":"","imageHint":"番泻","summary":"番泻叶为豆科植物狭叶番泻 Cassia angustifolia 或尖叶番泻 C. acutifolia 的干燥叶，主产于印度、埃及及我国海南、云南等地，为近年从国外引种的药材，商品以叶片完整、色绿黄、纸质、味苦而带黏液者为佳。其味甘苦而性寒，专归大肠经，所含蒽醌苷刺激肠黏膜而奏泻下通便之功，为治热结便秘之常用药；因其作用温和而确切，故习惯性便秘与老年便秘亦多选之，惟哺乳期、月经期及孕妇禁用。","blocks":[{"type":"paragraph","text":"番泻叶为豆科植物狭叶番泻 Cassia angustifolia Vahl. 或尖叶番泻 Cassia acutifolia Delile 的干燥叶。狭叶番泻主产于印度、埃及、阿拉伯诸国，我国自1950年代起引种于海南、广东、云南、广西等地，尖叶番泻主产于埃及与印度。商品以叶片完整、色绿黄、纸质、无霉变、味苦而带黏液者为佳；采收后多除去杂质，干燥后压平包装。生用或炒用皆可，炒制后泻下作用略缓而腹痛轻减。"},{"type":"paragraph","text":"番泻叶味甘苦而性寒，专归大肠经。所含蒽醌类成分能刺激肠黏膜，使大肠蠕动增强，同时抑制水分吸收，从而奏泻下通便之功，其作用较峻缓而确实，主要用于热结便秘，亦可用于习惯性便秘及老年便秘。因其性寒走泄，故对实证便秘最为适宜；若属气血亏虚、津枯肠燥之虚秘，则不宜久用单用，须配伍养血润燥之品以固其本。"},{"type":"paragraph","text":"现代研究表明，番泻叶含番泻苷、橙花苷、异番泻苷等蒽醌苷类，番泻苷A与番泻苷B为主要有效成分，在结肠内经菌群代谢为苷元后作用于肠黏膜引起排空增加，故其泻下作用具有起效较缓、作用温和而持久的特点，且能双向调节肠道功能，部分研究提示对习惯性便秘有较好远期疗效。配伍上，番泻叶配大黄、芒硝治热结便秘，配枳实、厚朴治气滞便秘，配火麻仁、当归治老年血虚便秘，配山楂、神曲消食导滞用于食积便秘。"},{"type":"table","caption":"番泻叶常见配伍与要点","head":["配伍","作用","要点"],"rows":[["番泻叶配大黄、芒硝","峻下热结、软坚通便","用于实热便秘、腹满胀痛"],["番泻叶配枳实、厚朴","行气导滞","用于气滞便秘、脘腹胀满"],["番泻叶配火麻仁、当归","攻润相合","用于老年或产后血虚便秘"],["番泻叶单用泡服","缓下通便","用于习惯性便秘及老年便秘"]]},{"type":"quote","text":"泻下通便。用于热结便秘，亦可用于习惯性便秘及老年便秘。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"番泻叶性寒走泄，哺乳期、月经期及孕妇忌用；肠梗阻、严重脱水、急性肠炎者禁用；出血倾向者及血虚体弱者慎用。服用过量可出现腹痛、恶心、呕吐、腹泻、电解质紊乱，长期服用可致结肠黑变病与药物依赖，一旦停用易出现排便困难，故不宜久服、连续服用，临床应用宜短期间歇并注意辨证虚实。"},{"type":"keypoints","title":"掌握要点","items":["专归大肠经，以泻下通便为唯一主要功效","作用温和确切，习惯性便秘亦可选用","哺乳期、月经期及孕妇禁用","久服可致依赖与肠黑变病，不宜连续使用"]}]},{"id":"gan-sui","title":"甘遂","subtitle":"Kansui Radix ｜ 甘遂、醋甘遂、濛芦","category":"泻下药","tags":["泻水逐饮","消肿散结","峻下逐水"],"meta":[{"label":"性味归经","value":"苦，寒；有毒。归肺、肾、大肠经"},{"label":"功效","value":"泻水逐饮，消肿散结"},{"label":"主治","value":"水肿胀满、二便不利、痰饮积聚、气逆咳喘；外治痈肿疮毒"},{"label":"用法用量","value":"炮制后多入丸散用，内服 0.5–1.5 g；外用适量"},{"label":"使用注意","value":"十八反，与甘草相反不可同用；有毒，孕妇禁用，体虚者忌用"}],"image":"","imageHint":"甘遂","summary":"甘遂为戟科植物甘遂 Euphorbia kansui Turr. 的干燥块根，秋末至次春采挖，除去须根与杂质，晒干，商品以块根肥大、表面黄白色、质坚脆、粉性足者为佳；入药多醋制以减毒。其味苦而性寒，有毒，归肺、肾、大肠经，泻水逐饮之力峻猛，为治水肿胀满、痰饮积聚、二便不利之峻下逐水药，兼能消肿散结外治疮毒。因其毒烈，十八反中与甘草相反，孕妇及体虚者禁用。","blocks":[{"type":"paragraph","text":"甘遂为戟科植物甘遂 Euphorbia kansui Turr. 的干燥块根，秋末至次春采挖，除去须根与杂质，晒干。商品以块根肥大、表面黄白色、质坚脆、断面粉性足、断面黄白者为佳，产于陕西、甘肃、河南、山西等地者多以家种者为道，习称\"陕甘遂\"。入药多经醋制，醋制后毒性降低、泻下作用缓和，故处方多写\"醋甘遂\"；生品多供外用或入丸散。因其有效成分不耐煎煮，故多入丸散而不入煎剂。"},{"type":"paragraph","text":"甘遂味苦性寒而有毒，主入肺、肾、大肠经。苦寒沉降，能泻水逐饮、通利二便，其泻下作用远峻于大黄、芒硝，故为治水肿胀满、腹水鼓胀、二便不利之峻药；又能峻逐痰饮，治痰饮积聚、气逆咳喘；其消肿散结之力可用于风痰癫痫、疮痈肿毒，外敷可治疮疡痈肿。临床上多与京大戟、芫花同用，方如十枣汤、舟车丸，以增强逐水之功而兼顾正气。"},{"type":"paragraph","text":"现代研究显示甘遂含大戟酮醇、甘遂萜酯等三萜类成分，这些成分对肠黏膜有强烈刺激，可致峻泻与电解质紊乱，并可引起心肌与呼吸肌的毒副反应，故临床必须严格控制剂量与疗程。配伍上，甘遂配京大戟、芫花、牵牛子峻下逐水治重症水饮，配大黄、芒硝攻下热结，配枳实、厚朴行气除满，配人参、大枣扶正以制其毒，取\"扶正祛邪\"之意。"},{"type":"table","caption":"甘遂常见配伍与要点","head":["配伍","作用","要点"],"rows":[["甘遂配京大戟、芫花","峻下逐水","用于重症水饮、悬饮"],["甘遂配牵牛子","泻水通便力增","用于水饮壅盛、二便不利"],["甘遂配大黄、芒硝","攻逐水饮、通腑","用于水饮与腑实互结"],["甘遂配人参、大枣","扶正逐水、缓和毒烈","用于体虚水停之证"]]},{"type":"quote","text":"主留饮宿食，癥瘕积聚，大小不利，破癥积，利水谷。","source":"《神农本草经·草部·甘遂》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"甘遂有毒，为峻下逐水之品，十八反中与甘草相反，绝不可同用；不宜与藜芦同用。内服剂量须严格控制在 0.5–1.5 g，且多入丸散，不宜入煎剂，不宜连续久服；孕妇禁用，哺乳期妇女与体虚、脾胃虚弱者忌用。中毒表现为剧烈腹痛、水样腹泻、呕吐、脱水、电解质紊乱、血压下降，严重者可出现呼吸困难与肝肾功能损害，出现异常应立即停用并就医。"},{"type":"keypoints","title":"掌握要点","items":["峻下逐水，为治重症水饮之猛药","十八反：与甘草相反，不可同用","醋制减毒，多入丸散，不宜入煎剂","孕妇禁用，体虚者忌用，剂量须严控"]}]},{"id":"wei-ling-xian","title":"威灵仙","subtitle":"Clematidis Radix et Rhizoma ｜ 威灵仙、灵仙、铁脚威灵仙","category":"祛风湿药","tags":["祛风湿","通络止痛","消骨鲠"],"meta":[{"label":"性味归经","value":"辛、咸，温；归膀胱经"},{"label":"功效","value":"祛风湿，通络止痛，消骨鲠"},{"label":"主治","value":"风湿痹痛、肢体麻木、筋脉拘挛、屈伸不利；骨鲠咽喉"},{"label":"用法用量","value":"煎服 6–9 g"},{"label":"使用注意","value":"气血亏虚者慎服；孕妇慎用；本品走窜力强，不宜过量久服"}],"image":"","imageHint":"灵仙","summary":"威灵仙为毛茛科植物威灵仙 Clematis chinensis Osbeck、棉团铁线莲 C. hexapetala 或毛铁线莲 C. lasiantha 的干燥根和根茎，秋季采挖，除去泥沙，晒干，商品以根粗大、色灰黄、质坚硬者为佳。其味辛咸而性温，归膀胱经，善于通行十二经、祛风湿通络止痛，为治风湿痹痛、肢体麻木、筋脉拘挛之要药，尤善治顽痹；又能消骨鲠，为治鱼骨等鲠咽咽喉之常用药。惟其走窜力强，气血亏虚者不宜过量久服。","blocks":[{"type":"paragraph","text":"威灵仙为毛茛科植物威灵仙 Clematis chinensis Osbeck、棉团铁线莲 Clematis hexapetala Pall. 或毛铁线莲 Clematis lasiantha Maxim. 的干燥根和根茎，秋季采挖，除去泥沙、杂质，晒干。商品以根粗大、条长、色灰黄、质坚硬而断面黄白者为佳，产于山东、辽宁、吉林、黑龙江等省者习称\"东北威灵仙\"，质优；产于浙江、江苏、安徽、江西等地者称\"江南威灵仙\"，根细而质稍次。切须注意与形似的钩吻、威灵仙伪品相区分，钩吻全株有毒而威灵仙无毒，误服可致命。"},{"type":"paragraph","text":"威灵仙味辛咸而性温，归膀胱经。辛能行散、温能通利，咸能软坚，其性猛而善走，能通行十二经，祛风湿、通经络、止痹痛，为治风湿痹痛之要药，尤善治顽痹、痛痹、麻木拘挛、屈伸不利之证；因其软坚之力，又能消骨鲠，为治鱼骨等鲠咽咽喉之常用要药，临床亦用于诸骨鲠咽，取其软化之意；外用还可治鱼鳞痣、久治不愈之皮肤瘙痒。"},{"type":"paragraph","text":"现代研究显示威灵仙含三萜皂苷、原白头翁素等成分，其皂苷类成分能促进炎症吸收、镇痛并使已僵化的关节与肌肉恢复活动，原白头翁素则为引起皮肤瘙痒的主要刺激成分，临床用于风湿性关节炎、腰腿痛、颈椎病、骨质增生等有较好疗效；其能使骨鲠 softening 而有软化骨鲠之用。配伍上，威灵仙配川芎、当归治气血痹痛，配苍术、羌活治寒湿痹痛，配鸡血藤、络石藤治顽痹久痛，配半夏、南星治痰瘀阻络之中风后遗症。"},{"type":"table","caption":"威灵仙常见配伍与要点","head":["配伍","作用","要点"],"rows":[["威灵仙配川芎、当归","行气活血通络止痛","用于气血不畅之痹痛麻木"],["威灵仙配苍术、羌活","祛风散寒除湿","用于寒湿痹痛、肢体沉重"],["威灵仙配半夏、南星","化痰通络","用于痰瘀阻络之中风后遗"],["威灵仙配黄芪、党参","益气祛风通络","用于久痹气血两虚"]]},{"type":"quote","text":"祛风湿，通络止痛，消骨鲠。用于风湿痹痛，肢体麻木，筋脉拘挛，屈伸不利；骨鲠咽喉。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"威灵仙走窜力强，气血亏虚、阴虚火旺者慎服，孕妇慎用；本品不宜过量或久服，以免耗气伤阴、损伤脾胃而致气短乏力、食欲减退。鲜品捣汁外用可刺激皮肤，出现红肿、灼痛、起疱者应立即清洗并停用。服用期间忌饮浓茶；与钩吻等外形相似品须严格鉴别，误服钩吻可致呼吸麻痹而死亡，切不可混淆。"},{"type":"keypoints","title":"掌握要点","items":["善通行十二经，为治顽痹要药","兼能消骨鲠，为治鲠咽常用药","性猛走窜，气血亏虚者不宜过量久服","外用捣汁可刺激皮肤，须注意鉴别钩吻"]}]},{"id":"qin-jiao","title":"秦艽","subtitle":"Gentianae Macrophyllae Radix ｜ 秦艽、西秦艽、秦纠","category":"祛风湿药","tags":["祛风湿","通络止痛","退虚热","清湿热"],"meta":[{"label":"性味归经","value":"辛、苦，平；归胃、肝、胆经"},{"label":"功效","value":"祛风湿，通络止痛，退虚热，清湿热"},{"label":"主治","value":"风湿痹痛、中风不遂、筋脉拘挛、骨节酸痛；湿热黄疸、骨蒸潮热、小儿疳积发热"},{"label":"用法用量","value":"煎服 3–9 g"},{"label":"使用注意","value":"久病体虚、尿多便溏者慎用；所含秦艽碱有溶血作用"}],"image":"","imageHint":"秦艽","summary":"秦艽为龙胆科植物大叶秦艽 Gentiana macrophylla Pall.、麻花艽 G. straminea Turr.、小叶秦艽 G. crassicaulis Turr. 或粗茎秦艽 G. robusta Turr. 的干燥根，春秋二季采挖，除去茎叶及泥沙，晒干，商品以根粗大、色棕黄、质坚实者为佳，产于甘肃、青海、陕西、内蒙古者称西秦艽，质优。其味辛苦而性平，归胃、肝、胆经，祛风湿通络止痛而不燥不腻，为风药中之润剂，兼能退虚热、清湿热。因其质润不燥，寒热痹痛皆可随证配伍使用。","blocks":[{"type":"paragraph","text":"秦艽为龙胆科植物大叶秦艽 Gentiana macrophyllae Pall.、麻花艽 Gentiana straminea Turr.、小叶秦艽 Gentiana crassicaulis Turr. 或粗茎秦艽 Gentiana robusta Turr. 的干燥根，春秋二季采挖，除去茎叶、须根及泥沙，晒干。商品以根粗大、色棕黄、质坚实者为佳，产于甘肃、青海、陕西、内蒙古、山西、河北等地者称\"西秦艽\"，根粗、质优，为道地品；产于东北、华北者称\"北秦艽\"，根细而略瘦；云南、四川所产称\"小秦艽\"。药材需注意与同科近缘种及伪品相区别。"},{"type":"paragraph","text":"秦艽味辛苦而性平，主入胃、肝、胆经。辛能散风、苦能燥湿、性平而无燥烈之弊，故祛风湿、通络止痛而质润不燥，为\"风药中之润剂\"，尤宜于风湿痹痛兼有阴血不足、虚热内生者；又因入肝胆经而善清湿热、退虚热，可治湿热黄疸、胁痛口苦，以及阴虚骨蒸、潮热盗汗、小儿疳积发热。其通络之功又能治中风不遂、筋脉拘挛、口眼歪斜。"},{"type":"paragraph","text":"现代研究显示秦艽含秦艽碱、麻花艽苷、苦参苷等成分，秦艽碱具有镇痛、镇静、抗炎、解热、抑菌及促进胃肠运动等作用，临床用于风湿性关节炎、类风湿关节炎、半身不遂、小儿疳积发热等疗效确切；其抗炎作用与抑制中枢前列腺素合成有关。配伍上，秦艽配羌活、防风治风寒湿痹，配当归、川芎治血虚风痹，配鳖甲、地骨皮治阴虚潮热，配茵陈、栀子治湿热黄疸，配黄芪、党参治久痹气血两虚。"},{"type":"table","caption":"秦艽常见配伍与要点","head":["配伍","作用","要点"],"rows":[["秦艽配羌活、防风","祛风散寒除湿","用于风寒湿痹、关节酸痛"],["秦艽配当归、川芎","养血活血通络","用于血虚风痹、肢体麻木"],["秦艽配鳖甲、地骨皮","退虚热、除骨蒸","用于阴虚潮热、盗汗"],["秦艽配茵陈、栀子","清利湿热退黄","用于湿热黄疸"]]},{"type":"quote","text":"祛风湿，通络止痛，退虚热，清湿热。用于风湿痹痛，中风不遂，筋脉拘挛，骨节酸痛；湿热黄疸，骨蒸潮热，小儿疳积发热。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"秦艽性平而润，但久病体虚、尿多便溏者慎用；其所含秦艽碱有轻微溶血作用，溶血性贫血及严重心血管疾病患者应慎用，临床不作长期大剂量使用。服用过量可出现恶心、呕吐、腹痛、腹泻等胃肠道反应；本品与富含铁剂的药物同用时可能影响吸收，服药期间宜与铁剂、钙剂间隔服用，具体剂量须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["祛风湿通络止痛而不燥，风药中之润剂","兼退虚热、清湿热，为痹兼阴虚者所宜","西秦艽为道地品质最佳","久病体虚、便溏者慎用，含秦艽碱有溶血作用"]}]},{"id":"fang-ji","title":"防己","subtitle":"Stephaniae Tetrandrae Radix ｜ 防己、汉防己、粉防己","category":"祛风湿药","tags":["利水消肿","祛风止痛","治脚气水肿"],"meta":[{"label":"性味归经","value":"苦，寒；归肺、膀胱经"},{"label":"功效","value":"利水消肿，祛风止痛"},{"label":"主治","value":"风湿痹痛、水肿脚气、小便不利、湿疹疮毒"},{"label":"用法用量","value":"煎服 4.5–9 g"},{"label":"使用注意","value":"苦寒伤胃，胃弱者慎用；含马兜铃酸的关木通、青木香已作废，严禁混用"}],"image":"","imageHint":"防己","summary":"防己为防己科植物粉防己 Stephania tetrandra S. Moore 的干燥根，秋季采挖，除去须根，刮去粗皮，切厚片或段，晒干，商品以切片厚、色黄白、质坚硬者为佳。其味苦而性寒，归肺、膀胱经，苦寒降泄，能利水消肿、祛风止痛，为治风水水肿、脚气、小便不利与风湿痹痛之常用药。因其苦寒易伤胃，胃弱者慎用；历史上汉防己、木防己混淆，现行药典已明确仅以粉防己为正品。","blocks":[{"type":"paragraph","text":"防己为防己科植物粉防己 Stephania tetrandra S. Moore 的干燥根，秋季采挖，除去须根，刮去粗皮，切厚片或段，晒干。商品以切片厚、色黄白、质坚硬、断面具粉性者为佳，产于浙江、湖北、江西、安徽、湖南等地者称\"粉防己\"或\"杭防己\"，为现行药典正品；历史上北方所产防己科植物汉防己常作防己入药，南方马兜铃科植物广防己、木防己亦曾混作防己使用，其中广防己含马兜铃酸，具肾毒性，现已明令废除。凡处方写\"防己\"，必须核对为粉防己。"},{"type":"paragraph","text":"防己味苦而性寒，主入肺、膀胱经。苦寒降泄，能利水消肿、通利水道，为治风水水肿、脚气、小便不利之常用药，尤宜于湿热壅盛、下肢肿痛者；其祛风止痛之功可用于风湿痹痛、关节不利，因质不燥不腻，故对热痹与寒痹均可随证配伍使用；外用还可治湿疹疮毒、皮肤瘙痒。临床常与茯苓、泽泻等同用以增强利水之效，与黄芪相配则可治气虚水肿、肢体沉重。"},{"type":"paragraph","text":"现代研究显示粉防己含汉防己甲素、汉防己乙素、千金藤碱等生物碱与粉防己碱，具有镇痛、抗炎、抗肿瘤、免疫抑制及抗心律失常等作用，其汉防己甲素可阻滞钙通道、扩张血管、降低血压，临床用于风湿性关节炎、神经痛、心律失常等有一定疗效；所含生物碱对肾脏有一定刺激，须避免长期大剂量使用。配伍上，防己配茯苓、泽泻利水消肿，配黄芪益气利水，配威灵仙、秦艽祛风止痛，配石膏治热痹，配白术健脾利水治痰饮水肿。"},{"type":"table","caption":"防己常见配伍与要点","head":["配伍","作用","要点"],"rows":[["防己配茯苓、泽泻","淡渗利水消肿","用于水肿、小便不利"],["防己配黄芪","益气利水","用于气虚水肿、肢体沉重"],["防己配威灵仙、秦艽","祛风通络止痛","用于风湿痹痛"],["防己配石膏、知母","清热通痹","用于热痹关节红肿热痛"]]},{"type":"quote","text":"利水消肿，祛风止痛。用于风湿痹痛，水肿脚气，小便不利，湿疹疮毒。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"防己苦寒，易伤脾胃阳气，脾胃虚弱、胃纳不佳、便溏者慎用；阴虚津亏而无湿热者不宜。服用过量或长期使用可出现胃肠道不适、乏力、水电解质紊乱，生物碱对肾脏有刺激作用，肾功能不全者应慎用或避免长期使用。极重要提示：含马兜铃酸的关木通、青木香、广防己已作废禁用，绝不可与防己混用；处方与调剂时必须核对品种，误用可致急性肾损伤。"},{"type":"keypoints","title":"掌握要点","items":["利水消肿兼祛风止痛，治风水与湿热肿痛","现行药典正品为防己科粉防己","含马兜铃酸的关木通、青木香严禁混用","苦寒伤胃，胃弱者慎用"]}]},{"id":"lei-gong-teng","title":"雷公藤","subtitle":"Tripterygii Wilfordii Radix ｜ 雷公藤、黄藤根、昆明雷公藤","category":"祛风湿药","tags":["祛风除湿","活血通络","消肿止痛","杀虫解毒"],"meta":[{"label":"性味归经","value":"苦、辛，寒；有大毒。归肝、肾经"},{"label":"功效","value":"祛风除湿，活血通络，消肿止痛，杀虫解毒"},{"label":"主治","value":"风湿顽痹、麻木瘫痪、跌打损伤、痈肿疮毒；现代用于类风湿关节炎、红斑狼疮、肾小球肾炎等免疫性疾病"},{"label":"用法用量","value":"煎服 10–25 g，文火煎 1–2 h；外用适量"},{"label":"使用注意","value":"有大毒，孕妇、哺乳期妇女及儿童禁用；肝肾功能不全者禁用；须严格控制剂量与疗程"}],"image":"","imageHint":"雷公","summary":"雷公藤为卫矛科植物雷公藤 Tripterygium wilfordii Hook. f. 的干燥根或根皮，秋至冬采挖，剥取根皮，除去杂质，晒干；药典规定入药部位为去皮的根或根皮，商品以断面黄白、质坚、气微者为佳。其味苦辛而性寒，有大毒，归肝、肾经，能祛风除湿、活血通络、消肿止痛，现代多用于类风湿关节炎、红斑狼疮、IgA 肾病等免疫相关疾病，效果虽好而毒副反应明显，孕妇、哺乳期妇女、儿童及肝肾功能不全者一律禁用。","blocks":[{"type":"paragraph","text":"雷公藤为卫矛科植物雷公藤 Tripterygium wilfordii Hook. f. 的干燥根或根皮，秋至冬季采挖，剥取根皮，除去杂质，晒干。药典明确规定入药部位为去皮的根或根皮，以断面黄白、质坚、气微者为佳，主产于福建、浙江、湖南、湖北、云南、四川等地。因其毒性显著，采收加工时须注意防护，避免皮肤与汁液直接接触。临床用量须依医嘱严格掌握，多以文火久煎以降低毒性；外用多制成酊剂、软膏或煎剂局部使用。"},{"type":"paragraph","text":"雷公藤味苦辛而性寒，有大毒，归肝、肾经。苦寒能祛风除湿、辛散能活血通络，故对风湿顽痹、麻木瘫痪、关节肿痛屈伸不利有较强作用，且见效较速；其活血消肿止痛之功可用于跌打损伤、瘀血肿痛；杀虫解毒则可外治疮疡疥癣。现代临床还将其用于类风湿关节炎、系统性红斑狼疮、IgA 肾病、紫癜性肾炎、银屑病等免疫性疾病，因其具有明确的免疫抑制作用；但毒副作用亦与其同出一源，必须权衡利弊、短期足量而不可长期滥用。"},{"type":"paragraph","text":"现代研究显示雷公藤含雷公藤甲素、雷公藤乙素、雷公藤内酯等二萜类与倍半萜类成分，雷公藤甲素为免疫抑制与抗炎的主要活性物质，能抑制T淋巴细胞增殖与多种炎症介质释放，临床用于上述免疫性疾病疗效确切，但同时可致消化、血液、泌尿、肝胆及生殖多个系统损害。配伍上，雷公藤多与黄芪、当归、白芍等同用以补气血、护肝肾、减轻毒副作用；与伸筋草、桑枝、威灵仙配伍以增强祛风通络之力；外用可与黄柏、蒲公英同敷治疮毒。"},{"type":"table","caption":"雷公藤常见配伍与要点","head":["配伍","作用","要点"],"rows":[["雷公藤配黄芪、当归","益气养血、减轻毒性","用于久痹体虚、气血不足"],["雷公藤配伸筋草、桑枝","祛风通络、舒筋利节","用于顽痹拘挛、屈伸不利"],["雷公藤配黄柏、蒲公英","清热解毒、消肿止痛","外治疮疡肿毒"],["雷公藤配白芍、甘草","缓急止痛、护肝肾","用于关节疼痛与肝肾防护"]]},{"type":"quote","text":"祛风除湿，活血通络，消肿止痛，杀虫解毒。用于风湿顽痹，麻木瘫痪，跌打损伤，痈肿疮毒。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"雷公藤有大毒，为本方中最需严加控制之品。本品不属十八反十九畏之列，然其毒性远甚于一般草木药，用药安全完全取决于剂量控制与规范监测。孕妇禁用，哺乳期妇女与儿童禁用，肝肾功能不全者、有出血倾向者及严重心脑血管疾病者禁用。内服剂量须严格控制在 10–25 g 并文火久煎，疗程宜短而不宜久服，服药期间应定期复查血常规、肝肾功能与尿常规；常见不良反应为胃肠道不适、食欲下降、腹泻、恶心、白细胞与血小板下降、肝酶升高、肾损害及月经失调甚至生殖毒性，出现异常须立即停药并就医。用药方案必须由专科医师制定与监测。"},{"type":"keypoints","title":"掌握要点","items":["有大毒，祛风除湿、活血通络而见效较速","现代用于类风湿关节炎与多种免疫性疾病","孕妇、哺乳期妇女、儿童及肝肾功能不全者禁用","须短期足量、定期查血象与肝肾功能"]}]},{"id":"huo-xiang","title":"藿香","subtitle":"Pogostemon Cablin (Blanco) Benth. ｜ 藿香、广藿香、土藿香","category":"化湿药","tags":["芳香化湿","和中止呕","发表解暑"],"meta":[{"label":"性味归经","value":"辛，微温；归脾、胃、肺经"},{"label":"功效","value":"芳香化湿，和中止呕，发表解暑"},{"label":"主治","value":"湿浊中阻、脘痞呕吐、暑湿倦怠、寒湿闭暑、腹胀、大肠虚滑泄泻；湿温初起"},{"label":"用法用量","value":"煎服 3–10 g；后下"},{"label":"使用注意","value":"阴虚火旺、胃有实热者忌用"}],"image":"","imageHint":"藿香","summary":"藿香为唇形科植物广藿香 Pogostemon cablin (Blanco) Benth. 的干燥地上部分，南方地区习用土藿香，原植物为同属 Pogostemon chinensis (Maxim.) Briq.，夏季花序初现时割取，晒干或阴干，商品以枝叶完整、色黄绿、香气浓郁者为佳。其味辛而微温，归脾、胃、肺经，芳香而善化湿浊、和中止呕、发表解暑，为治湿阻中焦与暑湿证之要药，尤善治湿浊内阻之恶心呕吐。阴虚火旺、胃有实热者忌用。","blocks":[{"type":"paragraph","text":"藿香为唇形科植物广藿香 Pogostemon cablin (Blanco) Benth. 的干燥地上部分，一年生草本，茎直立，四棱形，茎叶揉之有特殊香气。南方地区另以同属植物土藿香 Pogostemon chinensis (Maxim.) Briq. 入药，习称\"土藿香\"。多于夏秋季花序初现时割取地上部分，晒干或阴干。商品以枝叶完整、色黄绿、气芳香者为佳，产于广东、广西、海南者习称\"广藿香\"，质量最优；北方所产多为土藿香，效用相近而香气略淡。生用或用鲜品，鲜品芳香力更足。"},{"type":"paragraph","text":"藿香味辛而性微温，主归脾、胃、肺经。辛能行散、微温能化，其气芳香，故善化湿浊、醒脾和中，为治湿阻中焦之要药，用于脘腹痞满、纳呆呕恶、口中黏腻；其芳香之气又能和中止呕，尤善治湿浊内阻、胃气上逆之呕吐，为治呕吐之要药；兼能发表解暑、化湿和中，故为治暑湿证、外感风寒兼湿之常用药，用于暑湿倦怠、恶寒发热、胸闷腹胀、泄泻；此外又可治鼻渊、湿疹、手足癣等。"},{"type":"paragraph","text":"现代研究显示藿香含广藿香醇、广藿香酮、藿香醛等挥发油成分，广藿香醇具有抗真菌、抗病原微生物、抗炎及调节胃肠运动等作用，临床用于急慢性胃肠炎、胃肠型感冒、消化不良等有较好疗效；其所含挥发油能促进胃液分泌、抑制胃肠过度蠕动，故止呕作用确切。配伍上，藿香配佩兰增强化湿醒脾之力，配半夏、厚朴治湿阻中焦之痞满呕吐，配香附、半夏治妊娠恶阻，配白术、茯苓治脾虚湿盛，配滑石、甘草治暑湿泄泻。"},{"type":"table","caption":"藿香常见配伍与要点","head":["配伍","作用","要点"],"rows":[["藿香配佩兰","芳香化湿、醒脾和中","用于湿阻中焦、脘痞纳呆"],["藿香配半夏、厚朴","化湿和胃、降逆止呕","用于湿浊呕吐、痞满"],["藿香配香附、半夏","和胃安胎、降逆止呕","用于妊娠恶阻、胎动不安"],["藿香配滑石、甘草","解暑化湿、止泻","用于暑湿泄泻"]]},{"type":"quote","text":"芳香化湿，和中止呕，发表解暑。用于湿浊中阻，脘痞呕吐，暑湿倦怠，寒湿闭暑，大肠虚滑泄泻。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"藿香辛温芳香，阴虚火旺、胃有实热者忌用；无湿滞、气滞之证者不宜久服，服用过多可致口干、咽痛、目赤、烦躁等\"香燥\"之弊。含挥发油，入汤剂宜后下，久煎则芳香有效成分挥发而药力大减；亦不宜久煎代茶久饮。孕妇如无湿阻之证当慎用；服药期间不宜与含鞣质、含金属离子的药物同服，以免影响吸收。"},{"type":"keypoints","title":"掌握要点","items":["芳香化湿与和中止呕并用，治湿阻中焦之要药","兼能发表解暑，为治暑湿证常用药","含挥发油，入汤宜后下","阴虚火旺、胃有实热者忌用"]}]},{"id":"pei-lan","title":"佩兰","subtitle":"Eupatorium Fortunei Turcz. ｜ 佩兰、佩兰叶、醒头草","category":"化湿药","tags":["芳香化湿","醒脾开胃","发表解暑"],"meta":[{"label":"性味归经","value":"辛，平；归脾、胃、肺经"},{"label":"功效","value":"芳香化湿，醒脾开胃，发表解暑"},{"label":"主治","value":"湿阻中焦、脘痞呕恶、口中甜腻、多涎、脾瘅、口臭"},{"label":"用法用量","value":"煎服 3–10 g"},{"label":"使用注意","value":"阴虚血燥、气虚者不宜；含挥发油，入汤宜后下"}],"image":"","imageHint":"佩兰","summary":"佩兰为菊科植物佩兰 Eupatorium fortunei Turcz. 的干燥地上部分，夏秋季采割，晒干，商品以叶多、色绿、气芳香者为佳，产于江苏、浙江、河北、陕西、甘肃等地者多为家种。其味辛而性平，归脾、胃、肺经，芳香而长于化湿醒脾、开胃除臭，为治湿阻中焦、口中甜腻多涎、口臭之良药，兼能发表解暑。与藿香相比，佩兰化湿和中之力较缓而除臭醒脾之功较著。","blocks":[{"type":"paragraph","text":"佩兰为菊科植物佩兰 Eupatorium fortunei Turcz. 的干燥地上部分，一年生草本，茎直立，绿色或略带紫色，节间长，叶对生，边缘有锯齿，揉之有特殊香气。夏秋季采割，除去杂质，晒干。商品以叶多、色绿、气芳香者为佳，产于江苏、浙江、安徽、河北、陕西、甘肃等地者多为栽培品。临床上多以生用为主，亦可鲜用；其与藿香同科不同属而功效相近，近代常二者同用以为\"芳香化浊\"之对药。"},{"type":"paragraph","text":"佩兰味辛而性平，主归脾、胃、肺经。辛平芳香，善于化湿醒脾、开胃进食，为治湿阻中焦之常用药，用于脘腹痞满、纳呆呕恶、身重困倦；其芳香气味尤能化除口中秽浊之气，故对\"脾瘅\"所致口中甜腻多涎、口臭、齿垢有良好效果，《内经》所谓\"脾瘅\"即由此而来；又能发表解暑，与藿香相须为用治暑湿困脾、胸闷泛恶、腹泻；外用还可治湿疹、疥癣。"},{"type":"paragraph","text":"现代研究显示佩兰含挥发油，主要为香叶醇、乙酸香叶酯、香茅醇等，另含少量鞣质及黄酮类成分，其挥发油具有芳香化浊、调节胃肠运动、抑菌等作用，临床用于消化不良、口腔异味、功能性胃肠病等有较好效果，长期服用未见明显毒性。配伍上，佩兰配藿香芳香化浊、醒脾和中，配半夏、厚朴治湿阻痞满恶心，配藿香、滑石、甘草治暑湿泄泻，配白豆蔻增强化湿行气之功，配石菖蒲化湿开窍治湿阻清窍之神情昏蒙。"},{"type":"table","caption":"佩兰常见配伍与要点","head":["配伍","作用","要点"],"rows":[["佩兰配藿香","芳香化浊、醒脾和中","用于湿阻中焦、暑湿困脾"],["佩兰配半夏、厚朴","化湿和胃、降逆止呕","用于脘痞呕恶、纳呆"],["佩兰配石菖蒲","化湿开窍、宁神益志","用于湿阻清窍、健忘失眠"],["佩兰配白豆蔻","增强化湿行气","用于湿温初起、脘闷苔腻"]]},{"type":"quote","text":"芳香化湿，醒脾开胃，发表解暑。用于湿阻中焦，脘痞呕恶，口中甜腻，多涎，脾瘅，口臭。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"佩兰性平而芳香，气虚、阴虚血燥者不宜，脾虚无湿浊者亦当慎用；孕妇如无湿阻之象应慎用。本品含挥发油，入汤剂宜后下，久煎则芳香成分挥发而化湿醒脾之力大减；其气味芳香，服后如感口干、咽干可少少饮温水，不宜与含鞣质的浓茶同服。"},{"type":"keypoints","title":"掌握要点","items":["芳香化湿、醒脾开胃，兼能发表解暑","善治脾瘅之口中甜腻、口臭、多涎","常与藿香相须为用，芳香化浊","含挥发油，入汤宜后下"]}]},{"id":"cang-zhu","title":"苍术","subtitle":"Atractylodis Rhizoma ｜ 苍术、茅苍术、炒苍术","category":"化湿药","tags":["燥湿健脾","祛风散寒","明目"],"meta":[{"label":"性味归经","value":"辛、苦，温；归脾、胃、肝经"},{"label":"功效","value":"燥湿健脾，祛风散寒，明目"},{"label":"主治","value":"湿阻中焦、脘腹胀满、泄泻、水肿；风湿痹痛、风寒挟湿表证；夜盲、眼目昏涩"},{"label":"用法用量","value":"煎服 3–9 g"},{"label":"使用注意","value":"阴虚内热、津液亏耗者慎用；气虚者不宜多服"}],"image":"","imageHint":"苍术","summary":"苍术为菊科植物苍术 Atractylodes lancea (Thunb.) DC. 的干燥根茎，春秋二季采挖，除去泥沙，晒干，商品以质坚实、断面黄白、切片有朱砂点、油室者为佳，产于江苏、浙江、安徽、江西、河北、山西者习称\"茅苍术\"，质量最佳。其味辛苦而性温，归脾、胃、肝经，燥湿健脾之力雄健，为治湿阻中焦、脾失健运之要药，兼能祛风散寒、明目，麸炒后燥性缓和而健脾和胃之功独专。","blocks":[{"type":"paragraph","text":"苍术为菊科植物苍术 Atractylodes lancea (Thunb.) DC. 的干燥根茎，菊科植物白术 Atractylodes macrocephala Koidz. 的根茎习称\"白术\"，二者须严加区分。春秋二季采挖，除去泥沙、须根，晒干，去粗皮者称\"茅苍术\"，不去皮者称\"苍术\"。商品以质坚实、断面黄白、散有朱砂点与油室者为佳，产于江苏、浙江、安徽、江西等江浙一带者习称\"茅苍术\"，因断面有朱砂点、油室明显而质量最佳；北方所产称\"北苍术\"，体轻质松而次之。炮制品有麸炒苍术与生苍术之分。"},{"type":"paragraph","text":"苍术味辛苦而性温，主归脾、胃、肝经。苦温燥湿、辛香健脾，燥湿健脾之力雄健，为治湿阻中焦之要药，用于脘腹胀满、纳呆呕恶、舌苔白腻、泄泻下痢、水肿；其辛温之性又能祛风散寒、燥湿止痛，为治风寒湿邪留滞经络所致风湿痹痛、肢体酸重疼痛之常用药，并可用于风寒挟湿之表证；入肝经而能明目，治夜盲、眼目昏涩，常与猪肝、羊肝同用。麸炒后燥性缓和，长于健脾和胃。"},{"type":"paragraph","text":"现代研究显示苍术含苍术酮、苍术内酯、白术内酯等倍半萜类与苍术多糖等成分，具有调节胃肠运动、利尿、保肝、抗炎、抗菌及增强免疫等作用，临床用于消化不良、慢性胃炎、溃疡病、风湿性关节炎等疗效确切；苍术酮对调节胃肠运动与利尿作用较为突出。配伍上，苍术配厚朴、陈皮为平胃散，燥湿运脾治湿阻中焦，配茯苓、泽泻治脾虚水肿，配黄芪、防风为玉屏风散而固表止汗，配白术为二术丸治脾虚湿盛，配独活、桑寄生治风湿痹痛。"},{"type":"table","caption":"苍术常见配伍与要点","head":["配伍","作用","要点"],"rows":[["苍术配厚朴、陈皮","燥湿运脾、行气和胃（平胃散）","用于湿阻中焦、脘痞苔腻"],["苍术配黄芪、防风","益气固表、祛风止汗","用于表虚自汗、易感风邪"],["苍术配茯苓、泽泻","健脾利水消肿","用于脾虚湿盛之水肿"],["苍术配独活、桑寄生","祛风除湿、补肝肾","用于风湿痹痛、久痹肾虚"]]},{"type":"quote","text":"燥湿健脾，祛风散寒，明目。用于湿阻中焦，脘腹胀满，泄泻，水肿；风湿痹痛，风寒挟湿表证；夜盲，眼目昏涩。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"苍术苦温燥烈，阴虚内热、津液亏耗者慎用，常见表现为口干咽燥、潮热盗汗、目赤、口舌生疮；气虚下陷、脾虚易出汗者亦不宜多服，久服可致口干、胃纳减退、便秘等燥烈伤阴之弊。服药期间忌食生冷、油腻、辛辣及甜食；与含糖类、含铁剂同服时宜间隔，以免影响吸收。孕妇若无湿阻之证应慎用。具体剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["燥湿健脾力雄，为湿阻中焦之要药","生用偏于祛风燥湿，麸炒偏于健脾和胃","为玉屏风散、平胃散之要药","阴虚内热、津液亏耗者慎用"]}]},{"id":"hou-po","title":"厚朴","subtitle":"Magnoliae Officinalis Cortex ｜ 厚朴、川朴、紫油朴","category":"化湿药","tags":["燥湿消痰","下气除满","行气消胀"],"meta":[{"label":"性味归经","value":"苦、辛，温；归脾、胃、肺、大肠经"},{"label":"功效","value":"燥湿消痰，下气除满"},{"label":"主治","value":"湿滞伤中、脘痞吐泻、食积气滞、腹胀便秘、痰饮喘咳"},{"label":"用法用量","value":"煎服 3–10 g"},{"label":"使用注意","value":"孕妇慎用；气虚津亏者忌服；含厚朴酚与和厚朴酚，不宜久服"}],"image":"","imageHint":"厚朴","summary":"厚朴为木兰科植物厚朴 Magnolia officinalis Rehd. et Wils.、凹叶厚朴 M. officinalis subsp. biloba 或大叶厚朴 M. officinalis subsp. velutina 的干燥干皮、枝皮或根皮，4–6月剥取，卷筒或双卷筒状，商品以皮厚、肉细、油性足、内表面紫褐者为佳，习称「川朴」。其味苦辛而性温，归脾、胃、肺、大肠经，燥湿消痰、下气除满，为治湿滞伤中与气滞腹胀之要药。孕妇慎用，气虚津亏者忌服。与枳实相配，一行一降，为治痰气互结痞满之常用药对。","blocks":[{"type":"paragraph","text":"厚朴为木兰科植物厚朴 Magnolia officinalis Rehd. et Wils.、凹叶厚朴 Magnolia officinalis subsp. biloba (Chun et C. H. Tsoong) Y. W. Law 或大叶厚朴 Magnolia officinalis subsp. velutina (Y. W. Law) Hu 的干燥干皮、枝皮或根皮。4–6月剥取，根皮、干皮与枝皮分别加工，卷筒或双卷筒状，置阴凉干燥处。商品以皮厚、肉细、油性足、内表面紫褐色、断面颗粒状者为佳，产于四川、湖北、陕西者习称\"川朴\"，质量最佳，习称\"紫油朴\"；产于浙江、福建、江西者习称\"浙朴\"。用时刮去粗皮，切丝或卷筒，干燥后入药。"},{"type":"paragraph","text":"厚朴味苦辛而性温，主归脾、胃、肺、大肠经。苦能燥湿降泄，辛能行气散结，温能通行，故善燥湿消痰、下气除满，为治湿滞伤中、气滞腹胀之要药，用于脘腹痞满胀痛、嗳气呕吐、泄泻下痢；其辛散苦降之性善于行气消胀，故食积气滞、便秘腹胀者用之尤宜；又能燥湿化痰、降气平喘，用于痰湿阻肺之咳喘痰多、气逆喘急。与枳实相配，一行一降，气行则痰消，是为经典配伍。"},{"type":"paragraph","text":"现代研究显示厚朴含厚朴酚、和厚朴酚及厚朴碱等成分，厚朴酚与和厚朴酚具有抗菌、抗炎、镇痛、抗肿瘤、影响胃肠运动及抗抑郁等作用，临床用于慢性胃炎、消化性溃疡、功能性消化不良等有较好疗效；其所含挥发油对胃肠运动呈双向调节，可使紧张状态下胃肠运动得以缓和。配伍上，厚朴配苍术、陈皮为平胃散治湿阻气滞，配枳实、大黄治阳明腑实痞满，配半夏、茯苓治痰湿咳嗽，配桂枝、白芍治腹满腹痛，配黄连治泻痢后重。"},{"type":"table","caption":"厚朴常见配伍与要点","head":["配伍","作用","要点"],"rows":[["厚朴配苍术、陈皮","燥湿运脾、行气和胃","用于湿阻气滞之脘腹胀满"],["厚朴配枳实、大黄","行气消积、通腑泄热","用于阳明腑实之痞满燥实"],["厚朴配半夏、茯苓","燥湿化痰、降气平喘","用于痰湿咳喘、痰多气逆"],["厚朴配黄连、木香","行气止痛、治泻痢后重","用于湿热泻痢"]]},{"type":"quote","text":"主中风伤寒，头痛寒热，惊悸气，血痹死肌，去三虫。","source":"《神农本草经·草部·厚朴》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"厚朴苦辛温燥，气虚津亏、阴虚火旺者忌服，孕妇慎用。含有厚朴酚与和厚朴酚等成分，长期或大剂量服用存在肝损伤风险，故不宜久服、过量服用，服药期间宜定期监测肝功能；用药后如出现乏力、食欲减退、恶心、尿黄等应停药并就医。不宜与含金属离子的药物及强心苷类同用，孕妇使用须严格评估获益与风险。"},{"type":"keypoints","title":"掌握要点","items":["燥湿消痰、下气除满，为湿阻气滞之要药","与枳实相配，一行一降治痞满","含厚朴酚与和厚朴酚，不宜久服","孕妇慎用，气虚津亏者忌服"]}]},{"id":"sha-ren","title":"砂仁","subtitle":"Amomi Fructus ｜ 砂仁、缩砂密、春砂仁、白砂仁","category":"化湿药","tags":["化湿开胃","温脾止泻","理气安胎"],"meta":[{"label":"性味归经","value":"辛，温；归脾、胃、肾经"},{"label":"功效","value":"化湿开胃，温脾止泻，理气安胎"},{"label":"主治","value":"湿浊中阻、脘痞不饥、脾胃虚寒、呕吐泄泻、妊娠恶阻、胎动不安"},{"label":"用法用量","value":"煎服 3–6 g，后下"},{"label":"使用注意","value":"阴虚血燥、火热内炽者忌服；大便燥结者慎用"}],"image":"","imageHint":"砂仁","summary":"砂仁为姜科植物阳春砂 Amomum villosum Lour.、海南砂 A. longiligulare T. L. Wu 或绿壳砂 A. villosum var. xanthioides T. L. Wu et B. L. Yang 的干燥成熟果实，夏季果实成熟时采收，除去杂质，晒干，商品以个大饱满、色紫褐、质坚、辛香浓者为佳。其味辛而性温，归脾、胃、肾经，芳香而善化湿开胃、温脾止泻、理气安胎，为治湿阻中焦与脾胃虚寒之要药，并善安胎。入汤剂宜后下。又因砂仁壳力缓而温，常用于脾虚气滞之脘腹胀痛。","blocks":[{"type":"paragraph","text":"砂仁为姜科植物阳春砂 Amomum villosum Lour.、海南砂 Amomum longiligulare T. L. Wu 或绿壳砂 Amomum villosum var. xanthioides T. L. Wu et B. L. Yang 的干燥成熟果实。夏季果实成熟时采收，除去杂质，晒干。商品以个大饱满、质坚、色紫褐、辛香浓者为佳，产于广东、广西的阳春砂习称\"春砂\"，品质最优；产于海南的称\"海南砂\"；广西所产绿壳砂习称\"绿壳砂\"，壳薄而仁厚。另有一味\"砂仁壳\"，为砂仁果实的干燥果壳，作用较缓，多用于脘腹胀痛而气虚者。砂仁含挥发油，入汤剂须后下，捣碎入药更易出味。"},{"type":"paragraph","text":"砂仁味辛而性温，主归脾、胃、肾经。辛香温通，能化湿开胃、温中止呕、醒脾进食，为治湿阻中焦及脾胃虚寒之要药，用于脘腹痞闷、不思饮食、胃寒呕吐；其温中之性又能温脾止泻，用于脾胃虚寒之泄泻腹痛；入肾经而能温肾化气，与茯苓、党参同用可治肾虚寒湿之尿频、遗尿；其理气之功又能行气安胎，用于妊娠恶阻、胎动不安，为安胎之要药。"},{"type":"paragraph","text":"现代研究显示砂仁含挥发油，主要为蒎烯、樟烯、桉叶素等，另含黄酮类与皂苷，其挥发油能促进胃肠消化液分泌、改善胃肠运动、抗溃疡、镇痛，临床用于消化不良、胃肠炎、妊娠恶阻等疗效确切。配伍上，砂仁配厚朴、陈皮化湿行气治湿阻，配党参、白术温脾止泻，配苏梗、白术行气安胎，配木香治气滞腹痛，配补骨脂、益智仁治脾肾虚寒之泄泻。"},{"type":"table","caption":"砂仁常见配伍与要点","head":["配伍","作用","要点"],"rows":[["砂仁配厚朴、陈皮","化湿行气、和中止呕","用于湿阻中焦、脘痞纳呆"],["砂仁配党参、白术","温脾止泻、益气和中","用于脾胃虚寒之泄泻"],["砂仁配苏梗、白术","理气安胎、健脾和中","用于妊娠恶阻、胎动不安"],["砂仁配木香、茯苓","行气止痛、温肾化气","用于气滞腹痛、肾虚寒湿"]]},{"type":"quote","text":"化湿开胃，温脾止泻，理气安胎。用于湿浊中阻，脘痞不饥，脾胃虚寒，呕吐泄泻，妊娠恶阻，胎动不安。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"砂仁辛温香燥，阴虚血燥、火热内炽者忌服，大便燥结者慎用；孕妇若无气滞及妊娠恶阻之证亦不宜多服。本品含挥发油，入汤剂宜后下，久煎则芳香有效成分挥发而温脾理气之力大减；剂量过大可致口干、咽痛、便秘、上火等燥热之象。阴虚有热者若需使用，应配伍养阴之品以制其燥。"},{"type":"keypoints","title":"掌握要点","items":["化湿开胃、温脾止泻、理气安胎三用俱长","为治妊娠恶阻与胎动不安之要药","含挥发油，入汤宜后下、捣碎入药","阴虚血燥、火热内炽者忌服"]}]},{"id":"sang-zhi","title":"桑枝","subtitle":"Mori Ramulus ｜ 桑枝、桑条、桑木枝","category":"祛风湿药","tags":["祛风湿","利关节","清热"],"meta":[{"label":"性味归经","value":"甘，平；归肝经"},{"label":"功效","value":"祛风湿，利关节"},{"label":"主治","value":"肩臂、关节酸痛麻木"},{"label":"用法用量","value":"煎服 9–15 g"},{"label":"使用注意","value":"寒痹者慎用；无风湿者不宜"}],"image":"","imageHint":"桑枝","summary":"桑枝为桑科植物桑 Morus alba L. 的干燥枝条，春至初秋采割，晒干，商品以枝条细长、色黄褐、质坚韧者为佳。其味甘而性平，归肝经，能祛风湿、利关节，为治风湿痹痛、尤其上肢痹痛之要药，因其性平不燥寒热皆可使用，故有\"四肢拘挛，痹痛者\"良药之称。临床常与桂枝、姜黄同用治肩臂痛，与防己、薏苡仁配伍治湿热痹痛。","blocks":[{"type":"paragraph","text":"桑枝为桑科植物桑 Morus alba L. 的干燥枝条。春至初秋采割，晒干。商品以枝条细长、色黄褐、质坚韧、断面纤维性强者为佳。其来源与桑叶、桑白皮、桑果同出一体，均取自桑树，惟部位与采收时令不同：桑枝取春夏秋三季之嫩枝条，以质坚韧者为优，古有\"桑枝无童枝，取之不效\"之说，强调其须有充分木质化程度方能通络。"},{"type":"paragraph","text":"桑枝味甘而性平，主归肝经。甘能缓急，平而无寒热偏胜之弊，故善祛风湿、通经络、利关节，为治风湿痹痛之常用药，尤善治上肢痹痛、肩臂酸沉、关节麻木，因其性平不燥而寒痹、热痹均可随证配伍使用；又入肝经而能养肝血、柔筋脉，故对肝血不足、筋脉失养之肢体麻木、转筋挛急亦有效。作为桑白皮上行之辅药，临床常配伍桑白皮、桂枝、姜黄等治疗上肢痹痛。"},{"type":"paragraph","text":"现代研究显示桑枝含桑素、桑色素、黄酮类、鞣质及多种糖类等成分，其黄酮类物质与多酚类具有抗炎、镇痛、降血糖、降血脂及抗氧化作用，临床用于风湿性关节炎、关节痛、高脂血症与糖尿病等有一定疗效；因其能改善微循环，故对糖尿病周围神经病变所致肢体麻木亦有助益。配伍上，桑枝配桂枝、姜黄、黄芪治肩臂痛风上肢麻木，配防己、薏苡仁、蚕沙治湿热痹痛，配牛膝、木瓜治下肢痿软，配白芍、甘草治肝血不足之筋脉拘挛。"},{"type":"table","caption":"桑枝常见配伍与要点","head":["配伍","作用","要点"],"rows":[["桑枝配桂枝、姜黄","祛风通络、通利上肢","用于肩臂酸痛、风湿上肢痹痛"],["桑枝配防己、薏苡仁","祛风湿、清湿热","用于湿热痹痛、肢体麻木"],["桑枝配白芍、甘草","养肝柔筋、缓急止痛","用于筋脉拘挛、转筋"],["桑枝配黄芪、当归","益气养血、通络","用于血虚风痹、麻木不仁"]]},{"type":"quote","text":"祛风湿，利关节。用于肩臂、关节酸痛麻木。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"桑枝甘平质润，作用缓和，故用量宜偏大，一般 9–15 g，必要时可用至 30 g；但无风湿痹痛之证者不宜滥用。寒痹者若单用桑枝力不足，应配伍温经散寒之品（如桂枝、细辛）以增强温通之力；热痹者则宜配伍清热祛湿之品（如防己、薏苡仁）。本品药性平和，一般不良反应少见，孕妇使用仍宜适度。"},{"type":"keypoints","title":"掌握要点","items":["性平不燥，寒痹热痹皆可使用","善治上肢痹痛、肩臂酸沉麻木","为桑白皮之上行辅药","作用缓和，用量宜偏大"]}]},{"id":"fu-ling","title":"茯苓","subtitle":"Poria ｜ 茯苓、白茯苓、云苓、松苓","category":"利水渗湿药","tags":["利水渗湿","健脾","宁心"],"meta":[{"label":"性味归经","value":"甘、淡，平；归心、肺、脾、肾经"},{"label":"功效","value":"利水渗湿，健脾，宁心"},{"label":"主治","value":"水肿尿少、痰饮眩悸、脾虚食少、便溏泄泻、心神不安、惊悸失眠"},{"label":"用法用量","value":"煎服 10–15 g"},{"label":"使用注意","value":"虚寒精滑、气虚下陷者慎用；可与五灵脂同用"}],"image":"","imageHint":"茯苓","summary":"茯苓为多孔菌科真菌茯苓 Poria cocos (Schw.) Wolf 的干燥菌核，多于夏秋季采挖，堆放\"发汗\"后干燥，商品以个大、质实、色白、体重者为佳，产于云南、安徽、河南、湖北、山西等地者习称\"云苓\"。其味甘淡而性平，归心、肺、脾、肾经，利水渗湿而无峻烈之弊，为治水湿内停诸证之要药；又善健脾宁心，故为脾虚食少与心神不安之常用药，虚实寒热皆可随证配伍。","blocks":[{"type":"paragraph","text":"茯苓为多孔菌科真菌茯苓 Poria cocos (Schw.) Wolf 的干燥菌核，多于夏秋季采挖，堆置\"发汗\"后摊开晾至表面干燥，反复数次至现皱纹、内部水分大部散失后阴干或晒干，习称\"茯苓个\"；再切去皮、切片或碾碎，习称\"茯苓皮\"与\"茯神\"。商品以个大、体重、质实、色白、无霉变者为佳，产于云南者习称\"云苓\"，质优。茯苓皮长于利水消肿而作用较缓，茯神（抱松根者）长于宁心安神。"},{"type":"paragraph","text":"茯苓味甘淡而性平，主归心、肺、脾、肾经。甘能补脾，淡能渗利、性平不燥，故能利水渗湿而补而不峻，为治水湿内停诸证之要药，用于水肿、小便不利、痰饮眩悸；其健脾之力可治脾虚食少、便溏泄泻、脘腹胀满；入心经而能宁心安神，用于心神不宁、惊悸失眠、多梦健忘。因其性平和、可利可补、可健可宁，寒热虚实皆可配伍，故有\"四时神药\"之誉。"},{"type":"paragraph","text":"现代研究证实茯苓含茯苓多糖、三萜类（茯苓酸、茯苓醇）、茯苓聚糖等成分，具有利尿、增强免疫、抗肿瘤、镇静、保肝、抗炎、降血糖等作用，临床用于慢性肾炎水肿、心源性水肿、神经衰弱、消化不良等疗效确切；所含茯苓多糖为免疫调节与抗肿瘤的物质基础。配伍上，茯苓配猪苓、泽泻利水渗湿，配白术、苍术健脾燥湿，配桂枝、白术温阳化气利水，配陈皮理气化痰（补中益气汤、二陈汤），配远志、龙骨宁心安神，配人参、白术补气健脾。"},{"type":"table","caption":"茯苓常见配伍与要点","head":["配伍","作用","要点"],"rows":[["茯苓配猪苓、泽泻","淡渗利水","为治水湿内停之基本方剂组合"],["茯苓配白术、苍术","健脾燥湿","用于脾虚食少、便溏泄泻"],["茯苓配桂枝、白术","温阳化气、通阳利水","用于痰饮、蓄水证"],["茯苓配远志、龙骨","宁心安神","用于惊悸失眠、多梦健忘"]]},{"type":"quote","text":"主胸胁逆气，忧恚惊邪恐悸，心下结痛，寒热烦满咳逆，口焦舌干，利小便。久服安魂养神。","source":"《神农本草经·草部·茯苓》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"茯苓甘淡渗利，虚寒精滑、气虚下陷、阴虚而无湿热者慎用，尿多者不宜多服；服用期间宜多饮温水以利排尿，勿过食生冷油腻。传统有\"茯苓恶白敛\"、\"畏牡蒙、地榆、秦艽、鳖甲\"之说，另古人认为\"服茯苓忌饮茶\"，服药期间宜淡饮食、勿饮浓茶。本品药性平和，一般不良反应少见，但大剂量长期服用可致口干、脘腹不适，孕妇及儿童用量宜酌减。"},{"type":"keypoints","title":"掌握要点","items":["利水健脾宁心三用俱长，性平无弊","治水湿内停诸证之要药","茯苓皮长于利水，茯神长于宁心","虚寒精滑、气虚下陷者慎用"]}]},{"id":"yi-yi-ren","title":"薏苡仁","subtitle":"Coicis Semen ｜ 薏苡仁、薏米、苡仁、六谷子","category":"利水渗湿药","tags":["利水渗湿","健脾止泻","除痹","排脓"],"meta":[{"label":"性味归经","value":"甘、淡，凉；归脾、胃、肺经"},{"label":"功效","value":"利水渗湿，健脾止泻，除痹，排脓，解毒散结"},{"label":"主治","value":"水肿、脚气、小便不利、脾虚泄泻、湿痹拘挛、肺痈、肠痈、赘疣"},{"label":"用法用量","value":"煎服 9–30 g；健脾宜炒用"},{"label":"使用注意","value":"津液不足者慎用；孕妇慎用；性偏凉，脾胃虚寒者宜炒制"}],"image":"","imageHint":"薏仁","summary":"薏苡仁为禾本科植物薏苡 Coix lacryma-jobi L. 的干燥成熟种子，秋季果实成熟时采收，除去杂质，晒干，商品以粒大、饱满、色白、杂质少者为佳。其味甘淡而性凉，归脾、胃、肺经，利水渗湿而不伤阴，兼能健脾止泻、除痹排脓，为治湿热痹痛与肺痈肠痈之要药，又为食疗佳品。因其性偏凉，脾胃虚寒者宜炒用，孕妇慎用。《本经》列为上品，兼可作药膳调养。","blocks":[{"type":"paragraph","text":"薏苡仁为禾本科植物薏苡 Coix lacryma-jobi L. 的干燥成熟种子，秋季果实成熟时采收，除去杂质，晒干。商品以粒大、饱满、色白、杂质少者为佳，产于福建、河北、辽宁及长江流域各省者品质较佳。炮制品有生薏苡仁与炒薏苡仁（清炒或麸炒）之别：生品偏于利水渗湿、清热排脓，炒后偏于健脾止泻、缓和寒性。薏苡仁亦为药食两用之品，民间多煮粥、煲汤食用。"},{"type":"paragraph","text":"薏苡仁味甘淡而性凉，主归脾、胃、肺经。甘淡渗利能利水渗湿而不伤正，为治湿热下注之水肿、脚气、小便不利与湿痹拘挛之要药；其甘能健脾、淡能渗湿，故能健脾止泻，用于脾虚泄泻；入肺经而能排脓解毒、消痈排脓，用于肺痈、肠痈；外用可治赘疣、湿疹。此外本品能除痹止痛，尤善治湿热痹痛与着痹拘挛。"},{"type":"paragraph","text":"现代研究显示薏苡仁含薏苡仁酯、薏苡多糖、脂肪酸及多种氨基酸，其薏苡仁酯有抗炎、镇痛、抑菌、抗肿瘤及增强免疫等作用，薏苡多糖具有调节血脂、血糖与免疫功能之效，临床用于风湿性关节炎、慢性结肠炎、肺炎及多种肿瘤的辅助治疗有较好效果。配伍上，薏苡仁配防己、蚕沙治湿热痹痛，配茯苓、猪苓、泽泻利水消肿，配白术、苍术健脾止泻，配苇茎、桃仁治肺痈，配败酱草、红藤治肠痈，配白术、桂枝治寒湿痹痛。"},{"type":"table","caption":"薏苡仁常见配伍与要点","head":["配伍","作用","要点"],"rows":[["薏苡仁配防己、蚕沙","祛湿清热、通痹止痛","用于湿热痹痛、拘挛"],["薏苡仁配茯苓、泽泻","淡渗利水消肿","用于水肿、小便不利"],["薏苡仁配苇茎、桃仁","清肺排脓、活血消痈","用于肺痈咳吐脓血"],["薏苡仁配白术、苍术","健脾渗湿止泻","用于脾虚湿盛之泄泻"]]},{"type":"quote","text":"主筋急拘挛不可屈伸，风湿痹，下气。久服轻身益气。其根下三虫。","source":"《神农本草经·草部·薏苡仁》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"薏苡仁甘淡性凉，津液不足、阴虚而无湿热者慎用；脾胃虚寒者宜炒用，并配伍温中之品，否则易致脘腹不适与便溏。孕妇慎用，因其有兴奋子宫平滑肌、促进排空之虞，孕期不宜大量食用。服用期间不宜过量，过量可致便秘、腹胀与食欲减退；作为食疗长期食用亦当注意体质辨证，寒湿与湿热并存者当随证调整用量。"},{"type":"keypoints","title":"掌握要点","items":["利水渗湿兼健脾，湿盛脾虚者尤宜","为治湿热痹痛与肺痈肠痈之要药","生用偏渗湿排脓，炒用偏健脾止泻","性偏凉，孕妇与脾胃虚寒者慎用"]}]},{"id":"che-qian-zi","title":"车前子","subtitle":"Plantaginis Semen ｜ 车前子、车前草、车前实","category":"利水渗湿药","tags":["清热利尿通淋","渗湿止泻","明目","祛痰"],"meta":[{"label":"性味归经","value":"甘，寒；归肝、肾、肺、小肠经"},{"label":"功效","value":"清热利尿通淋，渗湿止泻，明目，祛痰"},{"label":"主治","value":"热淋涩痛、水肿胀满、暑湿泄泻、目赤肿痛、痰热咳嗽"},{"label":"用法用量","value":"煎服 9–15 g，包煎"},{"label":"使用注意","value":"肾虚精滑者慎用；含胶质，须包煎"}],"image":"","imageHint":"车前","summary":"车前子为车前科植物车前 Plantago asiatica L. 或平车前 P. depressa Willd. 的干燥成熟种子，秋季采收，晒干，商品以粒大、色黑褐、饱满者为佳。其味甘而性寒，归肝、肾、肺、小肠经，能清热利尿通淋、渗湿止泻、明目祛痰，为治热淋涩痛与暑湿泄泻之要药；其全草即车前草，另长于清热解毒与凉血止血，临床亦常并用。因其含大量胶质，入汤剂须包煎。","blocks":[{"type":"paragraph","text":"车前子为车前科植物车前 Plantago asiatica L. 或平车前 Plantago depressa Willd. 的干燥成熟种子，夏秋季种子成熟时采收，除去泥沙，晒干。商品以粒大、饱满、色黑褐者为佳，产于江西、河北、辽宁、山西等地者习称\"大粒车前\"，产于江苏、浙江者为\"小粒车前\"。炮制多炒用或盐炒用：炒车前子可缓和寒性、利于煎出，盐炒则引药下行入肾。车前全草另作\"车前草\"入药，长于清热解毒、利尿通淋、凉血止血。种子含大量黏液质，故入汤剂须用纱布包裹。"},{"type":"paragraph","text":"车前子味甘而性寒，主归肝、肾、肺、小肠经。甘寒能清热利尿通淋，为治热淋涩痛、水肿尿少之要药，尤善治下焦湿热之小便淋沥涩痛；其渗湿之功能分利水湿而止泄泻，用于暑湿或湿盛泄泻，取其“利小便以实大便”之义；入肝经而能清肝明目，治目赤肿痛、目昏；入肺经而能清肺化痰，治痰热咳嗽。故凡水肿、淋证、泄泻、目赤、痰饮诸证，皆可用之。"},{"type":"paragraph","text":"现代研究表明车前子含车前子酸、黏液质、钾盐、多种多糖及黄酮类，车前子酸有明显的镇咳、祛痰、平喘与利尿作用，黏液质则能润滑肠道、缓和刺激，故临床用于上呼吸道感染、急慢性支气管炎、泌尿系感染及急性腹泻等有确切疗效；所含钾盐有利尿降压之效，高血压患者亦常选用。配伍上，车前子配木通、滑石治热淋涩痛，配茯苓、泽泻治水肿，配黄连、黄芩治湿热泄泻，配菊花、决明子治目赤肿痛，配黄芩、桑白皮治痰热咳嗽。"},{"type":"table","caption":"车前子常见配伍与要点","head":["配伍","作用","要点"],"rows":[["车前子配木通、滑石","清热利尿通淋","用于热淋、血淋涩痛"],["车前子配茯苓、泽泻","利水消肿","用于水肿、小便不利"],["车前子配黄连、黄芩","清热渗湿止泻","用于湿热泄泻"],["车前子配菊花、决明子","清肝明目","用于目赤肿痛、目昏多泪"]]},{"type":"quote","text":"主气癃，止痛，利水道小便，除湿痹。","source":"《神农本草经·草部·车前子》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"车前子甘寒滑利，肾虚精滑、遗尿者慎用，孕妇慎用；本品含大量黏液质，入汤剂须包煎，否则易使药液黏稠、过滤困难，亦可影响其他药物煎出。若与滋腻补药同用，宜后下或分煎，以免黏液碍胃。服用过量可致腹泻、尿频与胃部不适；以其利尿之功，肾功能不全者须遵医嘱控制用量，并注意电解质平衡。"},{"type":"keypoints","title":"掌握要点","items":["清热利尿通淋兼渗湿止泻、祛痰明目","取利小便以实大便，治湿盛泄泻","含黏液质，入汤剂必须包煎","肾虚精滑者慎用"]}]},{"id":"yin-chen","title":"茵陈","subtitle":"Artemisiae Scopariae Herba ｜ 茵陈、茵陈蒿、绵茵陈、白蒿","category":"利水渗湿药","tags":["清利湿热","利胆退黄","治湿热黄疸"],"meta":[{"label":"性味归经","value":"苦、辛，微寒；归脾、胃、肝、胆经"},{"label":"功效","value":"清利湿热，利胆退黄"},{"label":"主治","value":"黄疸尿少、湿温暑湿、湿热黄疸、胆胀胁痛"},{"label":"用法用量","value":"煎服 6–15 g；治黄疸宜单用或作主药"},{"label":"使用注意","value":"脾胃虚寒者慎用；蓄血发黄者不宜；非黄疸病勿用"}],"image":"","imageHint":"茵陈","summary":"茵陈为菊科植物茵陈 Artemisia scoparia Waldst. et Kitag. 或绵茵陈 Artemisia capillaris Thunb. 的干燥地上部分，春季幼苗全被白绒毛时采收，除去杂质，晒干，商品以绵茵芽质量为佳，习称「绵茵陈」，其质轻绵软、灰绿色者为正品。其味苦辛而性微寒，归脾、胃、肝、胆经，专清利湿热、利胆退黄，为治黄疸之要药，湿热黄疸与寒湿黄疸皆可随证配伍使用。古称「茵陈蒿」，《本经》称其能治热结黄疸。","blocks":[{"type":"paragraph","text":"茵陈为菊科植物茵陈 Artemisia scoparia Waldst. et Kitag. 或绵茵陈 Artemisia capillaris Thunb. 的干燥地上部分。春季幼苗全被白绒毛时采收，除去杂质及老茎，晒干。商品有茵陈与绵茵陈之分：绵茵陈质轻绵软、灰绿色、叶片细长如羽、香气特异，质量为佳；茵陈（花茵陈）茎叶稍长、色绿褐、气味较淡。绵茵陈于春季采收，茵陈多在秋季花期采收，二者功效相近，临床处方多写\"绵茵陈\"。"},{"type":"paragraph","text":"茵陈味苦辛而性微寒，主归脾、胃、肝、胆经。苦泄下降、微寒清热，善清利脾胃肝胆湿热，为治黄疸之要药，素有\"治黄疸要药\"之称，用于湿热黄疸、面目俱黄、小便短赤；其辛散之性又能疏畅肝胆、芳香化浊，故对湿温暑湿之脘腹胀满、恶心呕吐亦可选用；并可治胆胀胁痛、石淋血淋。治疗黄疸时多作主药使用，或配伍栀子、大黄（茵陈蒿汤）治湿热阳黄，或配伍附子、干姜、术附汤治寒湿阴黄。"},{"type":"paragraph","text":"现代研究显示茵陈含绿原酸、蒿色原、茵陈酮、β-蒎烯等成分，其茵陈酮蒿色原有显著利胆、保肝、抗炎及抑菌作用，能促进胆汁分泌、减轻肝细胞损伤，临床用于急性黄疸型肝炎、胆囊炎、胆石症、新生儿黄疸等有确切疗效；临床还用于预防流行性肝炎。配伍上，茵陈配栀子、大黄清利湿热退阳黄，配附子、干姜温化寒湿退阴黄，配金钱草、郁金利胆排石，配白术、茯苓健脾利湿，配黄连、黄芩清中焦湿热。"},{"type":"table","caption":"茵陈常见配伍与要点","head":["配伍","作用","要点"],"rows":[["茵陈配栀子、大黄","清利湿热、通腑退黄","为治湿热阳黄之要方"],["茵陈配附子、干姜","温化寒湿、退黄","用于寒湿阴黄"],["茵陈配金钱草、郁金","利胆排石、行气止痛","用于胆石症、胆胀胁痛"],["茵陈配白术、茯苓","健脾利湿退黄","用于脾虚湿盛之黄疸"]]},{"type":"quote","text":"主风湿寒热邪气，热结黄疸。久服轻身益气耐老。","source":"《神农本草经·草部·茵陈蒿》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"茵陈苦辛微寒，脾胃虚寒、纳呆便溏者慎用；蓄血发黄者不宜使用，因其苦泄走散，反增出血之虞；非黄疸之病亦不宜滥用，久服易伤脾胃阳气。服药期间如出现恶心、纳呆、腹泻、头晕等应减量或停用。孕妇如无湿热黄疸之证当慎用；本品含绿原酸等成分，与某些抑菌药同用时宜错开服用时间，具体用量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["清利湿热、利胆退黄，为治黄疸之要药","阳黄配栀子大黄，阴黄配附子干姜","绵茵陈质优，春季采收为佳","脾胃虚寒者慎用，蓄血发黄者不宜"]}]},{"id":"jin-qian-cao","title":"金钱草","subtitle":"Lysimachiae Herba ｜ 金钱草、过路黄、铜钱草","category":"利水渗湿药","tags":["利湿退黄","利尿通淋","解毒消肿"],"meta":[{"label":"性味归经","value":"甘、咸，微寒；归肝、胆、肾经"},{"label":"功效","value":"利湿退黄，利尿通淋，解毒消肿"},{"label":"主治","value":"湿热黄疸、胆胀胁痛、石淋、砂淋、小便涩痛；热毒消肿、疔疮肿毒、蛇虫咬伤"},{"label":"用法用量","value":"煎服 15–30 g；外用适量"},{"label":"使用注意","value":"脾胃虚寒者慎用；忌与钩吻同用"}],"image":"","imageHint":"金钱","summary":"金钱草为报春花科植物过路黄 Lysimachia christinae Hance 的干燥全草，夏秋二季采收，除去泥沙，晒干，商品以茎长、叶多、色绿者为佳。其味甘咸而性微寒，归肝、胆、肾经，能利湿退黄、利尿通淋，为治湿热黄疸与肝胆结石之要药；又能解毒消肿，可治热毒疮疡、蛇虫咬伤。其性微寒，脾胃虚寒者慎用，且不可与钩吻混用。其叶金钱草亦可入药，功似而力缓。","blocks":[{"type":"paragraph","text":"金钱草为报春花科植物过路黄 Lysimachia christinae Hance 的干燥全草，夏秋二季采收，除去泥沙、杂质，晒干。商品以茎长、色绿、叶多而完整者为佳，产于湖南、湖北、四川、江西、浙江、陕西、云南等地者均可入药。药材名称历代各地多有混称，江南称\"过路黄\"，广西称\"真金鸡草\"，湖北称\"金钱草\"；南方尚有另一味豆科植物广金钱草 Guangdong 金钱草，与本品来源不同，功效相近而形态有别，须依药典严格区分。"},{"type":"paragraph","text":"金钱草味甘咸而性微寒，主归肝、胆、肾经。甘淡渗利、咸能软坚、微寒清热，故能利湿退黄，为治湿热黄疸之要药，尤善治肝胆结石所致胁痛与黄疸；其利尿通淋之功可用于石淋、砂淋、小便涩痛，取其咸能软石之义；又能清热解毒、消肿止痛，用于疔疮肿毒、咽喉肿痛、毒蛇咬伤，热毒消肿可内服外敷并用。"},{"type":"paragraph","text":"现代研究显示金钱草含槲皮素、山柰酚、熊果酸、挥发油及多酚类成分，具有利胆排石、利尿、抗炎、抑菌、镇痛及抗氧化等作用，所含黄酮与多酚类对泌尿系结石有抑制成石与促排作用，临床用于急性胆囊炎、胆石症、泌尿系结石、黄疸型肝炎等有较好疗效。配伍上，金钱草配茵陈、栀子清利湿热退黄，配鸡内金、郁金、海金沙利胆排石，配石韦、滑石通淋排石，配蒲公英、紫花地丁解毒消肿，配大黄治热毒内结之便秘。"},{"type":"table","caption":"金钱草常见配伍与要点","head":["配伍","作用","要点"],"rows":[["金钱草配茵陈、栀子","清利湿热、退黄","用于湿热黄疸、面目俱黄"],["金钱草配鸡内金、郁金","利胆排石、行气止痛","用于肝胆结石、胁痛"],["金钱草配海金沙、石韦","通淋排石","用于石淋、砂淋"],["金钱草配蒲公英、紫花地丁","清热解毒、消肿止痛","用于疔疮肿毒、蛇虫咬伤"]]},{"type":"quote","text":"利湿退黄，利尿通淋，解毒消肿。用于湿热黄疸，胆胀胁痛，石淋，砂淋，小便涩痛；热毒消肿，疔疮肿毒，蛇虫咬伤。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"金钱草性微寒，脾胃虚寒、久病体虚者慎用；服用期间如出现脘腹不适、纳呆、便溏应减量或停用。孕妇慎用。本品品种来源复杂，南方广金钱草与本品外观相似而基原不同，调配时须依药典标准严格鉴别；尤其须严防与形似的钩吻相混，钩吻全株有大毒，误服可致呼吸麻痹甚至死亡。此外本品与部分利尿药同用时须注意电解质与肾功能变化，具体剂量应遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["利湿退黄、利尿通淋，为肝胆结石要药","咸能软坚，故能治石淋、砂淋","兼能解毒消肿，可治疮毒与蛇咬","须与钩吻等有毒异物严格鉴别"]}]},{"id":"fu-zi","title":"附子","subtitle":"Aconiti Lateralis Radix Praeparata ｜ 附子、附片、黑顺片、白附片","category":"温里药","tags":["回阳救逆","补火助阳","散寒止痛"],"meta":[{"label":"性味归经","value":"辛、甘，大热；有毒。归心、肾、脾经"},{"label":"功效","value":"回阳救逆，补火助阳，散寒止痛"},{"label":"主治","value":"亡阳虚脱、肢冷脉微、心阳不足、胸痹心痛、虚寒吐泻、脘腹冷痛、肾阳虚衰、阳痿宫冷、阴寒水肿、阳虚外感、寒湿痹痛"},{"label":"用法用量","value":"煎服 3–15 g，先煎、久煎 0.5–1 h"},{"label":"使用注意","value":"十八反，与半夏、瓜蒌、贝母、白蔹、白及相反；有毒，孕妇禁用；先煎久煎"}],"image":"","imageHint":"附子","summary":"附子为毛茛科植物乌头 Aconitum carmichaelii Debeaux 的子根加工品，冬至后采挖，除去须根与泥沙，蒸煮或火烘至无麻舌感，商品有黑顺片与白附片之分。其味辛甘而性大热，有毒，归心、肾、脾经，能回阳救逆于须臾之间，为治亡阳虚脱之第一要药；又能补火助阳、散寒止痛，用于肾阳虚衰、命门火衰、心阳虚衰诸证。因其毒性强烈，十八反中与半夏、瓜蒌、贝母、白蔹、白及相反，孕妇禁用，须先煎久煎。","blocks":[{"type":"paragraph","text":"附子为毛茛科植物乌头 Aconitum carmichaelii Debeaux 的干燥子根的加工品，一般于冬至后采挖，除去须根与泥沙，洗净，晒干后蒸煮或火烘至无麻舌感。商品分黑顺片与白附片：黑顺片为不去皮、切片、蒸至无麻舌感后干燥者；白附片为去皮、切片、蒸至无麻舌感后干燥者。另有淡附片、炮附片等炮制品。商品以个大、质坚实、色灰褐、表面有环节者为佳，主产于四川江油者习称\"江附子\"，为地道之品，陕西汉中等地产者亦佳。生附子毒性剧烈，临床皆用炮制品。"},{"type":"paragraph","text":"附子味辛甘而性大热，有毒，主归心、肾、脾经。辛能散寒、甘能缓急、大热能回阳，故能回阳救逆，为治亡阳虚脱、肢冷脉微之第一要药，常与人参、干姜同用（参附汤、四逆汤）；其温补肾阳、命门火衰之功，用于肾阳不足、阳痿宫冷、宫寒不孕、腰膝冷痛；入心经能温通心阳，治心阳不足之胸痹心痛、心悸；温脾阳而散寒止痛，治虚寒吐泻、脘腹冷痛、阴寒水肿；并能温经散寒，治寒湿痹痛与阳虚外感。"},{"type":"paragraph","text":"现代研究显示附子含乌头碱、次乌头碱、中乌头碱等双酯型生物碱，及单酰型、寡酰型等毒性较低成分，其强心、升压、抗休克、抗炎、镇痛作用确切，临床用于休克、心力衰竭、慢阻肺、类风湿关节炎等疗效显著；双酯型生物碱则为毒性来源，经久煎水解为毒性大减的寡酰型生物碱，故先煎久煎是安全用药的关键。配伍上，附子配干姜、炙甘草回阳救逆（四逆汤），配人参益气回阳（参附汤），配干姜、桂枝温阳通脉，配白术、茯苓温阳利水，配麻黄、细辛温经散寒。"},{"type":"table","caption":"附子常见配伍与要点","head":["配伍","作用","要点"],"rows":[["附子配干姜、炙甘草","回阳救逆（四逆汤）","用于亡阳虚脱、肢冷脉微"],["附子配人参","益气回阳固脱（参附汤）","用于阳气暴脱之休克"],["附子配白术、茯苓","温阳化气行水","用于阳虚水肿、痰饮"],["附子配干姜、桂枝","温经散寒、通脉止痛","用于寒湿痹痛与虚寒腹痛"]]},{"type":"quote","text":"主风寒咳逆邪气，温中，金创，破癥瘕积聚寒湿踒躄，拘挛膝痛不能行步。","source":"《神农本草经·草部·附子》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"附子有大毒，十八反中\"诸参辛芍叛藜芦\"，附子反半夏、瓜蒌、贝母、白蔹、白及，临床严禁与之同用。孕妇禁用；阴虚火旺、真热假寒者忌用；儿童、哺乳期妇女及心功能不全者慎用。用法上必须先煎、久煎 0.5–1 小时以上，至口尝无麻舌感方可服用，且不宜久服、连续服用；服药期间忌饮酒（乙醇可促进乌头碱吸收）。中毒表现为口舌及四肢麻木、恶心呕吐、心悸心律失常、血压下降、呼吸抑制，一旦出现应立即停药并急诊处理。"},{"type":"keypoints","title":"掌握要点","items":["回阳救逆第一要药，用于亡阳虚脱","有毒，必须先煎久煎至无麻舌感","十八反：反半夏、瓜蒌、贝母、白蔹、白及","孕妇禁用，服药期间忌酒"]}]},{"id":"gan-jiang","title":"干姜","subtitle":"Zingiberis Rhizoma ｜ 干姜、干生姜","category":"温里药","tags":["温中散寒","回阳通脉","温肺化饮"],"meta":[{"label":"性味归经","value":"辛，热；归脾、胃、肾、心、肺经"},{"label":"功效","value":"温中散寒，回阳通脉，温肺化饮"},{"label":"主治","value":"脘腹冷痛、呕吐泄泻、肢冷脉微、寒饮喘咳；吐血、便血、崩漏（炮姜）"},{"label":"用法用量","value":"煎服 3–10 g"},{"label":"使用注意","value":"阴虚内热、血热妄行者忌用；孕妇慎用"}],"image":"","imageHint":"干姜","summary":"干姜为姜科植物姜 Zingiber officinale Roscoe 的干燥根茎，冬季采挖，除去须根与泥沙，晒干或低温烘干，商品以块大、肥厚、色黄白、辣味强者为佳。其味辛而性热，归脾、胃、肾、心、肺经，温中散寒之力宏大而持久，为治脾胃寒证之要药；又能回阳通脉、温肺化饮，用于亡阳肢冷与寒饮咳喘。其与生姜同出一物而用有偏重，古有干姜守而不走、生姜走而不走之说。","blocks":[{"type":"paragraph","text":"干姜为姜科植物姜 Zingiber officinale Roscoe 的干燥根茎，多于冬季茎叶枯萎时采挖，除去须根与泥沙，洗净，晒干或低温烘干。商品以块大、肥厚、色黄白、表面有环节、断面黄白、辣味浓者为佳，主产于四川、贵州、山东、河南等省。炮制品有干姜、炮姜与姜炭之别：干姜切片生用，温中回阳之力较强；炮姜以砂炒或麸炒至鼓起，表面棕褐色，性偏温而守，善于温经止血、固脱止遗；姜炭则止血力更强。生姜与干姜同出一物而生用、干用有别，古有\"生姜走而不守，干姜守而不走\"之说。"},{"type":"paragraph","text":"干姜味辛而性热，主归脾、胃、肾、心、肺经。辛热走窜而能温中散寒，为治脾胃寒证之要药，用于脘腹冷痛、呕吐泄泻、食少吐泻、胃寒疼痛；其大热之性又能回阳通脉，用于亡阳虚脱、肢冷脉微，常与附子相须为用；入肺经能温肺化饮，治寒饮犯肺之咳喘痰多清稀、胸闷；炮姜则长于温经止血，用于虚寒性吐血、便血、崩漏、脾胃虚寒之出血。"},{"type":"paragraph","text":"现代研究显示干姜含姜辣素、姜烯酚、6-姜辣素及挥发油，其姜辣素能促进消化液分泌、增强胃肠运动、止吐止泻，姜烯酚有抗炎、镇痛、抗血小板聚集与保肝作用，临床用于急慢性胃肠炎、消化性溃疡、风湿性关节炎等有一定疗效；其所含挥发油对中枢神经系统有兴奋作用，可促进产热。配伍上，干姜配附子回阳救逆，配党参、白术温中健脾止泻，配半夏、茯苓温肺化饮，配黄连为辛开苦降之对药治寒热错杂之痞满，配桂枝温经散寒，炮姜配黄芪、艾叶治虚寒出血。"},{"type":"table","caption":"干姜常见配伍与要点","head":["配伍","作用","要点"],"rows":[["干姜配附子","回阳救逆、温中散寒","为治亡阳虚脱之要药"],["干姜配党参、白术","温中健脾、益气止泻","用于脾胃虚寒之泄泻"],["干姜配半夏、茯苓","温肺化饮、降逆化痰","用于寒饮咳喘、痰多清稀"],["炮姜配黄芪、艾叶","温经止血、固摄冲任","用于虚寒性崩漏、便血"]]},{"type":"quote","text":"主胸满咳逆上气，温中止血，出汗，逐风湿痹，肠澼下痢。","source":"《神农本草经·草部·干姜》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"干姜辛热，阴虚内热、血热妄行者忌用；孕妇慎用；湿热内蕴、脾胃湿重者亦当慎用。服用过量可致口干咽燥、烦躁上火、失眠、鼻衄等\"姜辣素\"过量反应，故不宜大量久服。本品含挥发油，入汤剂宜后下或久煎以析出有效成分；与附子同用时须确保附子已先煎久煎至无麻舌感。阴虚火旺者若需使用当配伍养阴之品以制其燥。"},{"type":"keypoints","title":"掌握要点","items":["温中散寒为治脾胃寒证之要药","回阳通脉，常与附子相须为用","温肺化饮，治寒饮咳喘痰稀","炮姜偏于温经止血，干姜偏于回阳"]}]},{"id":"rou-gui","title":"肉桂","subtitle":"Cinnamomi Cortex ｜ 肉桂、桂心、官桂","category":"温里药","tags":["补火助阳","引火归元","散寒止痛","温通经脉"],"meta":[{"label":"性味归经","value":"辛、甘，大热；归肾、脾、心、肝经"},{"label":"功效","value":"补火助阳，引火归元，散寒止痛，温通经脉"},{"label":"主治","value":"阳痿宫冷、腰膝冷痛、肾虚作喘、虚阳上浮、眩晕目赤、心腹冷痛、虚寒吐泻、寒疝腹痛、痛经经闭"},{"label":"用法用量","value":"煎服 1–5 g，宜后下；研末冲服 1–2 g"},{"label":"使用注意","value":"阴虚火旺、里有实热、血热妄行者忌用；孕妇忌用；畏赤石脂"}],"image":"","imageHint":"肉桂","summary":"肉桂为樟科植物肉桂 Cinnamomum cassia (L.) J. Presl 的干燥树皮，多于秋季剥取，刮去栓皮，阴干，商品以皮细肉厚、断面紫红、油性大、香气浓、味甜辣者为佳，尤以\"油桂\"为上品。其味辛甘而性大热，归肾、脾、心、肝经，能补火助阳、引火归元，为治命门火衰之要药；又能散寒止痛、温通经脉，为治寒凝诸痛之常用药。其与桂枝同出一物而用有偏重：肉桂偏于温里补火，桂枝偏于解表通阳。","blocks":[{"type":"paragraph","text":"肉桂为樟科植物肉桂 Cinnamomum cassia (L.) J. Presl 的干燥树皮，多于秋季剥取，剥去边栓与栓皮，刮去粗皮，阴干。商品以皮细、肉厚、断面紫红、油性大、香气浓、味甜而辛者为佳，习称\"油桂\"，为上品；广西所产\"桂通\"次之。商品有进口与国产之别，越南产的\"北桂\"亦佳。炮制多刮去粗皮用净皮，或用\"桂通\"、\"桂心\"、\"官桂\"等名。肉桂有效成分易挥发，且含鞣质遇铁可变色，故入煎剂宜后下，用量亦较桂枝为小。"},{"type":"paragraph","text":"肉桂味辛甘而性大热，主归肾、脾、心、肝经。辛甘大热、能补火助阳，且引火下归命门，为治命门火衰、肾阳不足之要药，用于阳痿宫冷、腰膝冷痛、畏寒肢冷、肾虚作喘、痰饮眩悸；其\"引火归元\"之能尤善治虚阳上浮、真寒假热之眩晕目赤、咽痛、唇舌生疮而下部畏寒者；辛热散寒止痛，能温中散寒治脘腹冷痛、寒疝腹痛、虚寒吐泻；又能温通经脉、活血通经，治寒凝血瘀之痛经、经闭、产后腹痛，兼可引火归元以治虚火牙痛。"},{"type":"paragraph","text":"现代研究显示肉桂含挥发油（桂皮醛为主，另含桂皮醇、乙酸桂皮酯）及肉桂多糖、鞣质、槲皮素等，桂皮醛有明显扩张血管、加速微循环、抗炎、镇痛、抑菌及降血糖作用，其对寒凝血瘀型痛经与心源性疾病的改善作用确切，临床用于痛经、雷诺现象、心律失常、糖尿病周围神经病变等；肉桂多醣则有抗肿瘤与免疫调节作用。配伍上，肉桂配附子温补命火，配当归、艾叶温经养血治宫冷痛经，配黄连为辛开苦降之对药治上热下寒，配麻黄、附子温阳散寒治寒凝经脉。"},{"type":"table","caption":"肉桂常见配伍与要点","head":["配伍","作用","要点"],"rows":[["肉桂配附子","温补命门、助火归元","用于肾阳不足、畏寒肢冷"],["肉桂配当归、艾叶","温经养血、调经止痛","用于宫冷痛经、经闭"],["肉桂配黄连","辛开苦降、寒热并用","用于上热下寒之口疮咽痛"],["肉桂配黄芪、党参","温阳益气、固表","用于阳虚自汗、畏寒乏力"]]},{"type":"quote","text":"主百病，温中，利九窍，通关节，补中益气。","source":"《神农本草经·草部·菌桂》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"肉桂辛甘大热，阴虚火旺、里有实热、血热妄行者忌用，孕妇忌用；无虚寒之证者不宜多用。十九畏中\"官桂畏赤石脂\"，故不宜与赤石脂同用。服用过量可致口干、咽痛、鼻衄、烦躁失眠、血压升高，故高血压、阴虚火旺者尤应慎用。入汤剂宜后下，久煎则挥发性有效成分散失而力减；含鞣质，遇铁剂易生黑色沉淀，勿与含铁制剂同煎，孕妇使用须严格评估获益与风险。"},{"type":"keypoints","title":"掌握要点","items":["补火助阳、引火归元，为命门火衰要药","善治虚阳上浮、真寒假热之证","入汤宜后下，用量小于桂枝","孕妇忌用，畏赤石脂，阴虚火旺者忌用"]}]},{"id":"wu-zhu-yu","title":"吴茱萸","subtitle":"Tutae Fructus ｜ 吴茱萸、萸肉、淡吴萸、疏吴萸","category":"温里药","tags":["散寒止痛","降逆止呕","助阳止泻"],"meta":[{"label":"性味归经","value":"辛、苦，热；有小毒。归肝、脾、胃、肾经"},{"label":"功效","value":"散寒止痛，降逆止呕，助阳止泻"},{"label":"主治","value":"厥阴头痛、寒疝腹痛、寒湿脚气、经行腹痛、脘腹胀痛、呕吐吞酸、五更泄泻"},{"label":"用法用量","value":"煎服 2–4.5 g；外用适量"},{"label":"使用注意","value":"阴虚火旺者忌用；不宜多服久服；孕妇慎用"}],"image":"","imageHint":"吴茱","summary":"吴茱萸为芸香科植物吴茱萸 Euodia rutaecarpa (Juss.) Benth. 的干燥近成熟果实，秋季果实由绿转绿褐时采收，除去杂质，晒干或低温烘干，商品以粒大、色棕褐、萸肉饱满者为佳，其气强烈而味辛苦。其味辛苦而性热，有小毒，归肝、脾、胃、肾经，散寒止痛之力强，为治厥阴头痛、寒疝腹痛之要药；又能降逆止呕、助阳止泻，用于呕吐吞酸与五更泄泻。阴虚火旺者忌用。","blocks":[{"type":"paragraph","text":"吴茱萸为芸香科植物吴茱萸 Euodia rutaecarpa (Juss.) Benth.、疏叶吴茱萸 E. rutaecarpa subsp. australis 或吴茱萸的变种的干燥近成熟果实。秋末冬初果实由绿色转绿褐色时采收，除去杂质、梗，晒干或低温烘干。商品以粒大、色棕褐、萸肉饱满、无杂质者为佳，主产于浙江、江西、湖南、四川、贵州等地，产于浙江衢州者习称\"衢吴萸\"，质量最佳。因其气味强烈，采收加工时宜戴手套、口罩以免刺激。炮制多盐制或姜制，以缓和辛烈之性并增强疗效。"},{"type":"paragraph","text":"吴茱萸味辛苦而性热，有小毒，主归肝、脾、胃、肾经。辛散苦降、性热走窜，故能散寒止痛，善治寒邪凝滞之痛证，尤善治厥阴头痛（头痛连齿、呕吐涎沫）与寒疝腹痛、经行腹痛、脘腹胀痛；入胃能降逆止呕，治胃寒呕吐、呕吐吞酸、肝胃不和之嗳气；入肾能助阳止泻，用于脾肾阳虚之五更泄泻、下痢；外用还能杀虫止痒，治湿疹、阴痒。"},{"type":"paragraph","text":"现代研究显示吴茱萸含吴茱萸碱、吴茱萸次碱、柠檬苦素及挥发油，吴茱萸碱有镇痛、抗炎、降压、扩张血管及抗溃疡作用，其对消化性溃疡与高血压有明显疗效，临床用于胃炎、溃疡病、偏头痛、痛经、肠易激综合征等；柠檬苦素则有抗肿瘤与免疫调节作用。配伍上，吴茱萸配川芎治厥阴头痛（吴茱萸汤），配干姜、木香治寒疝腹痛，配黄连治肝胃不和之呕吐吞酸（左金丸），配补骨脂、肉豆蔻治五更泄泻（四神丸），配桃仁、川芎治寒凝血瘀之痛经。"},{"type":"table","caption":"吴茱萸常见配伍与要点","head":["配伍","作用","要点"],"rows":[["吴茱萸配川芎、当归","温经散寒、降逆止痛","为治厥阴头痛之要方"],["吴茱萸配黄连","辛开苦降、清肝和胃","用于肝胃不和之呕吐吞酸"],["吴茱萸配干姜、木香","散寒止痛、理气和中","用于寒疝腹痛、寒凝胃痛"],["吴茱萸配补骨脂、肉豆蔻","温肾暖脾、固肠止泻","用于五更泄泻、脾肾阳虚"]]},{"type":"quote","text":"主温中下气，止痛，咳逆寒热，头痛汗出，逐风痹，五脏虚不足，寒湿五痹。","source":"《神农本草经·果部·吴茱萸》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"吴茱萸有小毒，阴虚火旺、肝阳上亢、胃热呕吐者忌用；无寒证者不宜服用。孕妇慎用，因其有较强的子宫兴奋作用，可能诱发宫缩。本品辛烈，不宜多服久服，剂量过大可引起口干、咽痛、目赤、烦躁、胃部不适甚至视力障碍；服用期间忌与生冷、油腻同食。若用于止呕，宜少量频服，若用于止痛，可用吴茱萸粉加醋调敷涌泉穴引火下行。"},{"type":"keypoints","title":"掌握要点","items":["散寒止痛，为厥阴头痛与寒疝腹痛要药","降逆止呕，治呕吐吞酸","助阳止泻，治五更泄泻","有小毒，阴虚火旺者忌用，孕妇慎用"]}]},{"id":"ding-xiang","title":"丁香","subtitle":"Caryophylli Flos ｜ 丁香、雄丁香、公丁香、番丁香","category":"温里药","tags":["温中降逆","补肾助阳","散寒止痛"],"meta":[{"label":"性味归经","value":"辛，温；归脾、胃、肾经"},{"label":"功效","value":"温中降逆，补肾助阳"},{"label":"主治","value":"胃寒呕吐、呃逆、胃寒胀痛、肾虚阳痿"},{"label":"用法用量","value":"煎服 1–3 g；研末服 0.5–1 g"},{"label":"使用注意","value":"阴虚内热、胃热呕吐者忌用；孕妇及儿童慎用；畏郁金"}],"image":"","imageHint":"丁香","summary":"丁香为桃金娘科植物丁香 Eugenia caryophyllata (L.) Merr. et Perry 的干燥花蕾，冬季至初春花蕾将开时采收，除去杂质，晒干，商品以花蕾饱满、个大、色棕褐、芳香浓烈者为佳，主产于海南、广东、广西、云南等地，习称\"海南丁香\"。其味辛而性温，归脾、胃、肾经，温中降逆之力强，为治胃寒呕吐、呃逆之要药，兼能补肾助阳、温经止痛。气味芳香，入煎剂宜后下，阴虚内热者忌用。","blocks":[{"type":"paragraph","text":"丁香为桃金娘科植物丁香 Eugenia caryophyllata (L.) Merr. et Perry 的干燥花蕾，冬季至初春花蕾将开而尚未开放时采收，除去杂质，晒干。商品以花蕾饱满、个大、色棕褐、芳香浓烈者为佳，主产于海南、广东、广西、云南、缅甸、印尼等地，产于海南者习称\"海南丁香\"，质量最佳。丁香有公丁香（花蕾）、母丁香（近开花的花蕾）与洋丁香之分，临床多用公丁香。因其芳香成分易挥发，入汤剂宜后下，研末冲服效果亦佳。"},{"type":"paragraph","text":"丁香味辛而性温，主归脾、胃、肾经。辛温芳香，能温中散寒、降逆止呕，为治胃寒呕吐、呃逆之要药，用于胃寒脘腹冷痛、呕吐、呃逆、干呕；其温通之力又能温经散寒止痛，治寒凝气滞之脘腹胀痛、痛经；入肾经可补肾助阳，用于肾虚阳痿、宫冷不孕。与砂仁、白豆蔻相比，丁香温散之力较强，尤宜于胃寒重证。"},{"type":"paragraph","text":"现代研究显示丁香含丁香酚、丁香酚乙酯、β-石竹烯等挥发油成分，丁香酚有明显抗菌、抗炎、镇痛、麻醉、抗氧化及促进药物透皮吸收的作用，临床用于消化不良、胃炎、牙痛、口腔溃疡等有较好疗效；其所含挥发油可促进胃液分泌、抑制胃肠痉挛，故止呕、止痛作用确切。配伍上，丁香配柿蒂、党参降逆止呃，配干姜、党参温中降逆止呕，配白芍、甘草治寒凝气滞之脘腹痛，配细辛、鹿角胶治肾阳虚寒之阳痿宫冷，配当归、川芎治寒凝血瘀之痛经。"},{"type":"table","caption":"丁香常见配伍与要点","head":["配伍","作用","要点"],"rows":[["丁香配干姜、党参","温中降逆、益气止呕","用于胃寒呕吐、呃逆"],["丁香配柿蒂","降逆止呃、温中降气","用于胃寒呃逆"],["丁香配细辛、鹿角胶","温肾助阳、散寒通脉","用于肾阳虚寒之阳痿宫冷"],["丁香配当归、川芎","温经散寒、活血止痛","用于寒凝血瘀之痛经"]]},{"type":"quote","text":"温中降逆，补肾助阳。用于胃寒呕吐，呃逆，胃寒胀痛，肾虚阳痿。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"丁香辛温香燥，阴虚内热、胃热呕吐者忌用；热证兼有郁热者不宜。孕妇慎用，儿童用量宜小，婴幼儿尤应慎用。本品气味芳香、入药量不宜过大，过量可致口干、咽痛、目赤、鼻衄、烦躁甚或神志不清；十九畏中\"丁香莫与郁金见\"，故不宜与郁金同用。含挥发油，入煎剂宜后下；阴虚火旺者若需使用宜配伍养阴之品，服药期间忌食生冷、油腻及过食辛辣。"},{"type":"keypoints","title":"掌握要点","items":["温中降逆，为胃寒呕吐、呃逆之要药","兼能补肾助阳，治肾虚阳痿宫冷","含挥发油，入汤宜后下","畏郁金，阴虚内热者忌用"]}]},{"id":"chen-pi","title":"陈皮","subtitle":"Citri Reticulatae Pericarpium ｜ 陈皮、橘皮、广陈皮、橘红","category":"理气药","tags":["理气健脾","燥湿化痰","调中"],"meta":[{"label":"性味归经","value":"辛、苦，温；归脾、肺经"},{"label":"功效","value":"理气健脾，燥湿化痰"},{"label":"主治","value":"脘腹胀满、食少吐泻、咳嗽痰多；兼治胸闷气滞、呕吐呃逆"},{"label":"用法用量","value":"煎服 3–10 g"},{"label":"使用注意","value":"气虚、阴虚燥咳、吐血者慎用；含挥发油，久煎则效减"}],"image":"","imageHint":"陈皮","summary":"陈皮为芸香科植物橘 Citrus reticulata Blanco 及其栽培变种的干燥成熟果皮，冬季果实成熟后剥取，晒干或低温干燥，商品以皮厚、瓤少、色红褐、油性足、香气浓者为佳，产于广东新会者习称\"新会皮\"，为地道之品，习称\"广陈皮\"。其味辛苦而性温，归脾、肺经，理气健脾、燥湿化痰，为治脾胃气滞与湿痰咳嗽之要药，素有\"陈皮理气燥湿之功，千年不变\"之誉。","blocks":[{"type":"paragraph","text":"陈皮为芸香科植物橘 Citrus reticulata Blanco 及其栽培变种的干燥成熟果皮。栽培变种有茶枝柑、大红袍等，多于冬季果实成熟后剥取，晒干或低温干燥；亦有于5月采收者习称\"青皮\"。商品以皮厚、瓤少、色红褐、油性足、香气浓、味微苦者为佳，产于广东新会、江门一带者习称\"新会皮\"或\"广陈皮\"，质优；产于四川者为\"川陈皮\"，亦良。炮制多刷去杂质与内瓤，切丝或整张入药，陈久者习称\"陈皮\"，以陈者为佳。"},{"type":"paragraph","text":"陈皮味辛苦而性温，主归脾、肺经。辛能行散、苦能燥湿、温能和中，故善理气健脾，为治脾胃气滞之要药，用于脘腹胀满、纳呆食少、大便溏泄、恶心呕吐；其辛散之性又能行气解郁，用于胸闷气滞、脘腹胀痛；入肺经则能燥湿化痰，为治湿痰咳嗽之要药，用于咳嗽痰多、色白易咯、胸闷气促；并能理气止呕、开胃进食，故常作为调和诸药之使药。"},{"type":"paragraph","text":"现代研究显示陈皮含挥发油（柠檬烯、柠檬醛等）、橙皮苷、新橙皮苷、川陈皮素等黄酮类成分，具有促进消化液分泌、排除肠管积气、健胃消食、祛痰平喘、抗炎及抗氧化等作用，临床用于消化不良、慢性胃炎、支气管炎等有确切疗效；橙皮苷能升高血压、减慢心率，与川陈皮素的降脂作用共同构成其\"药食同源\"的价值。配伍上，陈皮配苍术、厚朴为平胃散治湿阻气滞，配党参、白术为异功散治脾虚，配半夏、茯苓为二陈汤治湿痰，配枳实为橘皮枳实汤理气消痞，配乌药、荔枝核治寒疝腹痛。"},{"type":"table","caption":"陈皮常见配伍与要点","head":["配伍","作用","要点"],"rows":[["陈皮配苍术、厚朴","燥湿运脾、行气和胃","用于湿阻中焦之脘腹胀满"],["陈皮配党参、白术","益气健脾、理气助运","用于脾虚食少、便溏"],["陈皮配半夏、茯苓","燥湿化痰、理气和中","为治湿痰咳嗽之要方"],["陈皮配枳实","理气消痞、升降相因","用于痰气互结之痞满"]]},{"type":"quote","text":"主胸中痰热，咳逆，下气，善唾涎沫。","source":"《神农本草经·果部·橘皮》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"陈皮辛温香燥，气虚证、阴虚燥咳、吐血及内有实热者慎用；本品耗气伤阴，不宜久服过量，尤忌用于阴虚火旺之咳嗽。含挥发油，入汤剂宜后下，久煎则芳香有效成分挥发而理气之功大减；用于健脾时多与补气药同用，以防其辛散耗气。孕妇若无气滞之证亦不宜多用，服药期间如出现口干、咽痛、烦躁等上火表现应减量。"},{"type":"keypoints","title":"掌握要点","items":["理气健脾与燥湿化痰并用，治气滞湿痰","广陈皮（广东新会产者最佳）品质最佳，陈久者更良","含挥发油，入汤宜后下","气虚、阴虚燥咳者慎用"]}]},{"id":"qing-pi","title":"青皮","subtitle":"Citri Reticulatae Green Pericarpium ｜ 青皮、青橘皮、个青皮","category":"理气药","tags":["疏肝破气","消积化滞","疏肝解郁"],"meta":[{"label":"性味归经","value":"苦、辛，温；归肝、胆、胃经"},{"label":"功效","value":"疏肝破气，消积化滞"},{"label":"主治","value":"胸胁胀痛、疝气疼痛、乳癖、饮食积滞、癥瘕积聚、脏器下垂"},{"label":"用法用量","value":"煎服 3–10 g"},{"label":"使用注意","value":"气虚者慎用；有实热、阴虚者忌用；孕妇慎用"}],"image":"","imageHint":"青皮","summary":"青皮为芸香科植物橘 Citrus reticulata Blanco 及其栽培变种的干燥幼果，5–6月采收，拣去杂质，蒸或沸水略烫后晒干，商品以皮厚、瓤小、色青褐、油性足者为佳，多产于福建、浙江、四川等地。其味苦辛而性温，归肝、胆、胃经，疏肝破气、消积化滞之力较强，为治肝郁气滞之胁痛与食积气滞之脘腹胀痛之要药；陈皮理气力缓而偏于化痰，青皮破气力猛而偏于疏肝，二者常相须为用。","blocks":[{"type":"paragraph","text":"青皮为芸香科植物橘 Citrus reticulata Blanco 及其栽培变种的干燥幼果。多于5—6月采摘未成熟的果实，拣去杂质，蒸或沸水略烫后晒干，习称\"青皮\"或\"个青皮\"；亦有采收近成熟果实者，除去内外果皮干燥，习称\"青橘皮\"。商品以皮厚、瓤小、色青褐、断面有香气者为佳，主产于福建、浙江、四川、广东等地。其采收时节与陈皮（冬季成熟果皮）不同，故二者功效侧重有别，古有\"陈皮治气，青皮破气\"之说。"},{"type":"paragraph","text":"青皮味苦辛而性温，主归肝、胆、胃经。苦能泄降、辛能散结、温能通行，其气沉降而力峻，故善疏肝破气，为治肝郁气滞之要药，用于胸胁胀痛、脘腹胀痛、疝气疼痛、乳房结块胀痛；其消积化滞之功又可治饮食积滞之脘腹胀痛、嗳腐吞酸、大便秘结；并可用于癥瘕积聚、脏器下垂等属气滞血瘀或气陷之证。因其破气力强，故气虚者慎用，孕妇亦当慎用。"},{"type":"paragraph","text":"现代研究显示青皮含挥发油（柠檬烯、柠檬醛）、橙皮苷、川陈皮素等成分，其挥发油能促进消化液分泌、解除肠痉挛，青皮陈皮挥发油可使胃肠运动节律化，临床用于消化不良、胆囊炎、乳腺增生及肝郁气滞型功能性子官出血等有较好疗效；川陈皮素具有明确的抗炎与降脂作用。配伍上，青皮配柴胡、香附疏肝理气解郁，配白芍柔肝缓急止胁痛，配山楂、神曲消食导滞，配枳实破气消积，配黄芪、升麻治气滞下陷之脏器下垂，配鳖甲、莪术治癥瘕积聚。"},{"type":"table","caption":"青皮常见配伍与要点","head":["配伍","作用","要点"],"rows":[["青皮配柴胡、香附","疏肝理气、解郁止痛","用于肝郁气滞之胁痛"],["青皮配白芍","疏肝柔肝、缓急止痛","用于肝脾不和之脘腹胀痛"],["青皮配山楂、神曲","消食导滞、消积化滞","用于食积气滞之脘腹胀痛"],["青皮配黄芪、升麻","升提下陷、行气消胀","用于气滞下陷之脏器下垂"]]},{"type":"quote","text":"疏肝破气，消积化滞。用于胸胁胀痛，疝气疼痛，乳癖，饮食积滞，癥瘕积聚，脏器下垂。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"青皮破气力强，气虚证、脾胃虚弱而无积滞者慎用；阴虚火旺、有实热者忌用；孕妇慎用，因其行气破滞之力较强，可动胎气。服用过量可致胃肠道不适、恶心、腹痛、气短乏力，故临床用量宜从小量起，中病即止，不宜久服久用。若与补气药同用，须注意顾护正气；服药期间如出现明显疲乏、气短、纳减，应停用并咨询医师。"},{"type":"keypoints","title":"掌握要点","items":["疏肝破气，治肝郁胁痛与疝气疼痛","消积化滞，治食积气滞之脘腹胀痛","破气力较陈皮为峻，气虚者慎用","与陈皮相须为用，一破一和"]}]},{"id":"zhi-shi","title":"枳实","subtitle":"Citri Reticulatae Fructus ｜ 枳实、枳壳、炒枳实","category":"理气药","tags":["破气消积","化痰散痞","行气消痞"],"meta":[{"label":"性味归经","value":"苦、辛、酸，微寒；归脾、胃经"},{"label":"功效","value":"破气消积，化痰散痞"},{"label":"主治","value":"积滞内停、痞满胀痛、泻痢后重、大便不通；痰滞气阻、脏器下垂"},{"label":"用法用量","value":"煎服 3–10 g；枳壳 3–10 g"},{"label":"使用注意","value":"孕妇慎用；脾胃虚弱者慎用；破气力强，不宜过量久服"}],"image":"","imageHint":"枳实","summary":"枳实为芸香科植物酸橙 Citrus aurantium L.、栽培变种或干燥近成熟果实，7—8月果实近成熟时采摘，除去杂质，蒸或沸水略烫后晒干，商品以皮厚、瓤小、质坚、色褐褐者为佳。其味苦辛酸而性微寒，归脾、胃经，破气消积、化痰散痞之力较强，为治积滞内停、痞满胀痛之要药；枳壳为其半成熟果实，性较缓而偏于行气宽中，治气滞胸腹胀满。孕妇慎用。","blocks":[{"type":"paragraph","text":"枳实为芸香科植物酸橙 Citrus aurantium L.、栽培变种或干燥近成熟果实。多于7—8月果实近成熟时采摘，除去杂质，蒸或沸水略烫后晒干，习称\"枳实\"；将果实横切两瓣晒干或整果干燥者习称\"枳壳\"（或\"枳壳\"为5—6月采收的半成熟果实）。商品以皮厚、瓤小、质坚硬、色褐褐、气味浓者为佳，主产于四川、江西、湖南、湖北、广东等地，习称\"江枳实\"。枳实破气力强，枳壳力缓，故古有\"枳实破气，枳壳宽中\"之别。"},{"type":"paragraph","text":"枳实味苦辛酸而性微寒，主归脾、胃经。苦能泄下、辛能散结、酸能收敛，微寒清热，故善破气消积，为治积滞内停、痞满胀痛、大便不通之要药，用于食积气滞之脘腹胀痛、便秘；其化痰散痞之功可治痰气互结之胸痹、结胸、痞满；并因气行则血行，故可治气滞血瘀之胸胁疼痛、产后腹痛；枳壳则偏于行气宽中除胀，用于胸胁气滞、胀满食少，并可用于脏器下垂之久泻脱肛。"},{"type":"paragraph","text":"现代研究显示枳实含挥发油（柠檬烯）、橙皮苷、辛弗林、诺香酮等黄酮类成分，其挥发油能调节胃肠运动、使节律加快，辛弗林可升高血压、改善微循环，诺香酮有明显抑菌作用，临床用于消化不良、胃肠痉挛、功能性便秘及胃下垂等有较好疗效；枳壳则用于慢性支气管炎、胃下垂等。配伍上，枳实配厚朴、木香行气消积治痞满（枳实厚朴汤），配大黄、芒硝攻积导滞治腑实（大承气汤），配黄连清热燥湿治泻痢后重（枳壳导滞丸），配白术、茯苓健脾消痞，配瓜蒌、薤白通阳散结治胸痹。"},{"type":"table","caption":"枳实常见配伍与要点","head":["配伍","作用","要点"],"rows":[["枳实配厚朴、木香","行气消积、除满散痞","用于气滞痞满、腹胀便秘"],["枳实配大黄、芒硝","攻积导滞、峻下热结","为治阳明腑实之要药"],["枳实配黄连、白芍","清热燥湿、调气止痛","用于泻痢后重、大肠气滞"],["枳壳配黄芪、升麻","行气宽中、升提下陷","用于气虚下陷之脏器下垂"]]},{"type":"quote","text":"主大风在皮肤中如麻豆苦痒，除寒热结，止痢，长肌肉，利五脏，益气轻身。","source":"《神农本草经·果部·枳实》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"枳实破气力强，脾胃虚弱而无积滞者慎用，孕妇慎用；气虚下陷之脏器下垂宜选枳壳而不宜重用枳实。本品可促进胃肠蠕动，用量过大易出现胃部不适、腹痛、腹泻、肠鸣，老年及体弱者尤须从小量起；与补益药同用时须注意顾护胃气。煎服时以微炒或麸炒者为佳，可缓和其峻烈之性；服药期间如出现明显腹痛、频泻、头晕、心悸，应减量或停用并咨询医师。"},{"type":"keypoints","title":"掌握要点","items":["破气消积，为积滞内停、痞满胀痛要药","枳实力峻，枳壳力缓而偏于行气宽中","配大黄、芒硝为治阳明腑实之要药","孕妇慎用，脾胃虚弱者不宜重用"]}]},{"id":"mu-xiang","title":"木香","subtitle":"Aucklandiae Radix ｜ 木香、广木香、云木香","category":"理气药","tags":["行气止痛","健脾消食","行气解郁"],"meta":[{"label":"性味归经","value":"辛、苦，温；归脾、胃、大肠、胆、三焦经"},{"label":"功效","value":"行气止痛，健脾消食"},{"label":"主治","value":"胸膈气滞、脘腹胀痛、泻痢后重、食积不消、不思饮食"},{"label":"用法用量","value":"煎服 3–6 g，后下"},{"label":"使用注意","value":"阴虚津液不足者慎服；含挥发油，入汤宜后下；孕妇慎用"}],"image":"","imageHint":"木香","summary":"木香为伞形科植物木香 Aucklandia lappa Decne. 的干燥根，冬季采挖，除去泥沙、须根与地上茎，洗净，烘干，商品以根条粗壮、色黄褐、质坚、香气浓郁者为佳，产于云南 者习称\"云木香\"，主产于印度、缅甸、越南，国内以云南质量为上。其味辛苦而性温，归脾、胃、大肠、胆、三焦经，行气止痛之力强而不燥烈，为治脾胃气滞、脘腹胀痛之要药，兼能健脾消食、止泻痢后重。","blocks":[{"type":"paragraph","text":"木香为伞形科植物木香 Aucklandia lappa Decne. 的干燥根。秋末冬初采挖，除去泥沙、须根与地上茎，洗净，烘干；亦有用面裹煨制者习称\"煨木香\"，以增其止泻之功。商品以根条粗壮、色黄褐、质坚、香气浓郁、味辛苦者为佳，主产于印度、缅甸、越南、泰国，我国云南、广东、广西等地栽培成功，产于云南者习称\"云木香\"，质量最佳。其含挥发油，气味芳香，入汤剂宜后下，久煎则芳香散失而效减。"},{"type":"paragraph","text":"木香味辛苦而性温，主归脾、胃、大肠、胆、三焦经。辛行苦降、温通香燥，故善行气止痛，为治脾胃气滞、脘腹胀痛之要药，用于胸膈气滞、脘腹胀痛、嗳气纳呆；行气又能止痛，故止痛作用确切而广用于脘腹、胁肋、疝气诸痛；入大肠能行气化滞以解后重，用于泻痢里急后重；其芳香健脾之功又能醒脾开胃、增进食欲，治食欲不振、脘腹胀满。"},{"type":"paragraph","text":"现代研究显示木香含挥发油（去氢木香内酯、木香内酯）、菊糖、甾体等成分，其挥发油能调节胃肠运动、促进胆汁分泌、解除肠痉挛、去氢木香内酯有明显镇痛抗炎作用，临床用于消化性溃疡、胃肠炎、胆囊炎、痢疾及胆道蛔虫症疗效确切。配伍上，木香配枳实、厚朴行气消痞治气滞腹胀，配黄连治湿热泻痢里急后重，配乌药、川楝子治寒疝腹痛，配砂仁、豆蔻治湿阻中焦，配当归、川芎治血瘀气滞之痛经，配党参、白术健脾益气以防行气伤正。"},{"type":"table","caption":"木香常见配伍与要点","head":["配伍","作用","要点"],"rows":[["木香配枳实、厚朴","行气消痞、宽中止痛","用于气滞痞满、腹胀"],["木香配黄连","行气化滞、清热燥湿","用于泻痢里急后重"],["木香配黄连、黄芩","清热燥湿、行气止痛","用于湿热泻痢腹痛"],["木香配砂仁、豆蔻","芳香醒脾、化湿行气","用于湿阻中焦、脘腹胀痛"]]},{"type":"quote","text":"行气止痛，健脾消食。用于胸膈气滞，脘腹胀痛，泻痢后重，食积不消，不思饮食。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"木香辛温香燥，易耗气伤阴，阴虚津液不足者慎服，孕妇慎用。含挥发油，入汤剂宜后下，久煎则香气散失、止痛与行气作用减弱；剂量过大可致口干、咽干、烦躁、纳减，个别报道有胸闷、皮肤过敏等反应。用本品行气时宜配伍补气养血之品以顾护正气；服药期间如出现胃部灼热、口干舌燥、头晕，应减量或停用并咨询医师。"},{"type":"keypoints","title":"掌握要点","items":["行气止痛，为脾胃气滞脘腹胀痛之要药","行气化滞以解泻痢里急后重","含挥发油，入汤宜后下","阴虚津亏者慎服，孕妇慎用"]}]},{"id":"xiang-fu","title":"香附","subtitle":"Cyperi Rhizoma ｜ 香附、香附子、莎草根、雀头香","category":"理气药","tags":["疏肝解郁","理气宽中","调经止痛"],"meta":[{"label":"性味归经","value":"辛、微苦、微甘，平；归肝、脾、三焦经"},{"label":"功效","value":"疏肝解郁，理气宽中，调经止痛"},{"label":"主治","value":"肝郁气滞、胸胁胀痛、脘腹痞满、乳房胀痛、疝气疼痛、月经不调、痛经"},{"label":"用法用量","value":"煎服 4.5–10 g"},{"label":"使用注意","value":"阴虚血热者慎用；气虚无滞者不宜；孕妇慎用"}],"image":"","imageHint":"香附","summary":"香附为莎草科植物莎草 Cyperus rotundus L. 的干燥根茎，秋季采挖，除去须根与泥沙，蒸或煮至透心，晒干或烘干，商品以根茎大、质坚、香气浓者为佳，主产于浙江、山东、江苏、福建等地，习称\"浙香附\"。其味辛苦微甘而性平，归肝、脾、三焦经，为疏肝理气之要药，\"气病之总司，女科之主帅\"，善治肝郁气滞之胸胁疼痛、月经不调、痛经与脘腹痞满。因其性平不燥，寒热虚实皆可配伍。","blocks":[{"type":"paragraph","text":"香附为莎草科植物莎草 Cyperus rotundus L. 的干燥根茎。秋季采挖，除去须根与泥沙，蒸或煮至透心，晒干或烘干，商品以根茎大、色紫褐、质坚、香气浓郁者为佳，主产于浙江、山东、江苏、福建、湖北等地，产于浙江者习称\"浙香附\"，质优。炮制品有生香附、醋香附与酒香附之别：生品长于疏肝理气，醋制后专入肝经而长于调经止痛、消积化滞，酒制则偏于行气通络。香附为妇科调经要药，古有\"气病之总司，女科之主帅\"之誉。"},{"type":"paragraph","text":"香附味辛、微苦、微甘而性平，主归肝、脾、三焦经。辛能疏达、苦能泄降、甘能和中、性平不燥，故善疏肝解郁、行气止痛，为治肝郁气滞之要药，用于肝气郁结之胸胁胀痛、脘腹痞满、乳房胀痛、疝气疼痛；其调经止痛之功用于月经不调、痛经、闭经、经行乳房胀痛；又能理气宽中、消胀除满，治脘腹胀满、食少纳呆。因性平不燥而作用温和，故寒、热、虚、实各证均可随证配伍使用，为妇科与气病之常用良药。"},{"type":"paragraph","text":"现代研究显示香附含挥发油（香附酮、香附醇、α-香附酮）、黄酮类与三萜类成分，其挥发油有明显镇痛、抗炎、抑制子宫收缩与调节内分泌作用，临床用于月经不调、痛经、乳腺增生、抑郁症、胃肠功能紊乱等有较好疗效；α-香附酮对中枢神经系统有镇静作用。配伍上，香附配川芎治气滞血瘀之痛经，配当归补血和血、调经止痛，配柴胡、枳壳疏肝理气解郁，配青皮、川楝子治疝气疼痛，配苍术、厚朴治气滞湿阻之脘腹胀满，配栀子、川连治肝郁化火之胁痛。"},{"type":"table","caption":"香附常见配伍与要点","head":["配伍","作用","要点"],"rows":[["香附配川芎","行气活血、调经止痛","用于气滞血瘀之痛经、月经不调"],["香附配当归","疏肝养血、调经止痛","为治妇科月经病之常用对药"],["香附配柴胡、枳壳","疏肝理气、解郁除胀","用于肝郁气滞之胸胁胀痛"],["香附配苍术、厚朴","行气除满、燥湿健脾","用于气滞湿阻之脘腹胀满"]]},{"type":"quote","text":"香附乃气病之总司，女科之主帅。","source":"《本草纲目·草部·香附》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"香附性平而辛散，气虚无滞、阴虚血热者慎用，孕妇慎用。含挥发油，入汤剂宜稍后下，久煎则香气散失；剂量过大或久服可致口干、头晕、恶心、纳减，个别报道有月经量增多之情形。其性虽平，然有耗气之弊，配伍时宜与补血养气之品同用以顾护正气；月经过多者及有出血倾向者应先辨明虚实再决定用量，具体剂量须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["疏肝解郁、调经止痛，气病总司、妇科主帅","性平不燥，寒热虚实皆可随证配伍","醋制后长于调经止痛、消积化滞","气虚无滞、阴虚血热者慎用"]}]},{"id":"shan-zha","title":"山楂","subtitle":"Crataegi Fructus ｜ 山楂、山里红、焦山楂、北山楂","category":"消食药","tags":["消食化积","行气散瘀","化浊降脂"],"meta":[{"label":"性味归经","value":"酸、甘，微温；归脾、胃、肝经"},{"label":"功效","value":"消食健胃，行气散瘀，化浊降脂"},{"label":"主治","value":"肉食积滞、胃脘胀满、泻痢腹痛、瘀血经闭、痛经、疝气疼痛、胸痹心痛、高脂血症"},{"label":"用法用量","value":"煎服 9–12 g；焦山楂长于止泻止痢"},{"label":"使用注意","value":"脾胃虚弱无积滞者慎用；胃酸过多者不宜；孕妇慎用"}],"image":"","imageHint":"山楂","summary":"山楂为蔷薇科植物山楂 Crataegus pinnatifida Bge. var. major N.E.Br. 或山楂 C. pinnatifida 的干燥成熟果实，秋季果实成熟时采收，晒干或低温干燥，商品以个大、色红褐、肉厚、核小者为佳，产于山东、河北、辽宁、陕西、山西等地者习称\"北山楂\"。其味酸甘而性微温，归脾、胃、肝经，善消肉食油腻之积而不伤正，兼能行气散瘀、化浊降脂，为治肉食积滞与瘀滞腹痛之常用药。","blocks":[{"type":"paragraph","text":"山楂为蔷薇科植物山楂 Crataegus pinnatifida Bge. var. major N. E. Br. 或山楂 Crataegus pinnatifida Bge. 的干燥成熟果实。秋末冬初果实成熟时采收，除去杂质及脱落的核，晒干或低温干燥；产于山东、河北、辽宁、陕西、山西等地者习称\"北山楂\"，果大肉厚，质佳。炮制品有生山楂、炒山楂、焦山楂与山楂炭之别：生品长于活血化瘀，炒焦后消食化积之力增强而缓和刺激，焦山楂长于止泻止痢，山楂炭则专于收涩止血。采收加工时须注意钩吻等有毒异物混入之防范。"},{"type":"paragraph","text":"山楂味酸甘而性微温，主归脾、胃、肝经。酸能收敛、甘能缓急、微温通行，故善消食化积，尤善消肉食油腻之积，为治肉食积滞、脘腹胀满、嗳腐吞酸、泻痢腹痛之要药，临床常用于食积不化、泻痢腹痛；其入肝经而行气散瘀，治气滞血瘀之脘腹疼痛、痛经经闭、产后瘀阻腹痛、疝气疼痛；又能化浊降脂，用于高脂血症、动脉粥样硬化；焦山楂则长于止泻止痢，用于食积泄泻、痢疾。"},{"type":"paragraph","text":"现代研究显示山楂含黄酮类（牡荆素、槲皮素、金丝桃苷）、三萜类（熊果酸、山楂酸）、有机酸及核果苷，山楂黄酮能扩张冠脉、增加冠脉流量、降压、调节血脂，山楂酸与熊果酸有保肝、利胆、抗血小板聚集及抑菌作用，临床用于高脂血症、冠心病、消化不良、细菌性痢疾等疗效确切；核果苷具有明显的强心与抗心律失常作用。配伍上，山楂配神曲、麦芽消食导滞治食积，配青皮、木香行气消积治气滞腹胀，配桃仁、红花活血化瘀治瘀滞腹痛，配黄芪、丹参益气活血治胸痹心痛，配木香、槟榔治泻痢后重。"},{"type":"table","caption":"山楂常见配伍与要点","head":["配伍","作用","要点"],"rows":[["山楂配神曲、麦芽","消食化积、健脾和中","为治食积之常用组合"],["山楂配木香、青皮","行气消积、活血止痛","用于气滞血瘀之脘腹疼痛"],["山楂配桃仁、红花","活血祛瘀、通经止痛","用于痛经经闭、产后瘀阻"],["焦山楂配木香、槟榔","消食化积、止泻止痢","用于食积泄泻与痢疾"]]},{"type":"quote","text":"凡脾弱食物不克化，胸腹酸刺胀闷者，于每食后嚼二三枚，绝不疏也。","source":"《本草纲目·果部·山楂》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"山楂味酸，过食易伤脾胃，脾胃虚弱无积滞、胃酸过多及消化性溃疡活动期者不宜；孕妇慎用，因其能兴奋子宫平滑肌，有促流产之虞。空腹不宜食用；服用过量可致胃酸增多、纳减、恶心、腹胀、大便溏泄，牙敏者更易伤牙。与碱性药物如碳酸氢钠、铝碳酸镁同服可降低其疗效，与地高辛合用可增加其毒性反应，须注意；服药期间如出现明显胃部不适应减量并咨询医师。"},{"type":"keypoints","title":"掌握要点","items":["善消肉食油腻之积，为食积要药","行气散瘀，治痛经经闭与瘀滞腹痛","化浊降脂，用于高脂血症与冠心病","焦山楂长于止泻止痢，生品长于活血"]}]},{"id":"shen-qu","title":"神曲","subtitle":"Massae Fermentatae ｜ 六神曲、炒神曲、焦神曲、建曲","category":"消食药","tags":["消食和胃","解表","回乳"],"meta":[{"label":"性味归经","value":"甘、辛，温；归脾、胃经"},{"label":"功效","value":"消食和胃"},{"label":"主治","value":"食积不消、脘腹胀满、嗳腐吞酸、呕吐泄泻；外感发热兼食积"},{"label":"用法用量","value":"煎服 6–15 g；消食宜焦用"},{"label":"使用注意","value":"阴虚胃火盛者不宜；多服耗气"}],"image":"","imageHint":"神曲","summary":"神曲为面粉、赤小豆、苦杏仁、青蒿、苍耳草、辣蓼等六味药材混合发酵而成的干燥炮制品，商品以色黄褐、香气浓、表面光滑者为佳，习称\"六神曲\"。其味甘辛而性温，归脾、胃经，善于消食和胃，尤善消化面食积滞，为治食积不消之常用药；焦用则消食之力增强而止泻，临床常用于小儿食积、脘腹胀满与外感发热兼食滞之证。","blocks":[{"type":"paragraph","text":"神曲为面粉、赤小豆、苦杏仁、青蒿、苍耳草、辣蓼等六味药材混合粉碎，拌和成团、蒸制后发酵制成的干燥炮制品，习称\"六神曲\"；以陈久者为佳，故又称\"建神曲\"。商品以表面黄褐、内部灰白、香气浓郁者为佳，产于福建、江西、广东、河南等地者多供药用。炮制品有生神曲、炒神曲与焦神曲之别：生品长于消食和胃兼解表，炒焦后消食化积之力增强而兼能止泻，临床用于食积兼泻者多选焦神曲。"},{"type":"paragraph","text":"神曲味甘辛而性温，主归脾、胃经。甘能补脾、辛能行散，温能通行，故能消食和胃，尤善消金石药物难以消化之食积与面食积滞，为治食积不消、脘腹胀满、嗳腐吞酸之常用药；其辛散之性兼能解表，故外感发热兼见食滞者可用之；此外神曲又能回乳，用于小儿断乳积滞、乳房胀痛。其消食之力较山楂缓和而善化面食，故常与山楂、麦芽同用。"},{"type":"paragraph","text":"现代研究显示神曲含酵母菌、淀粉酶、蛋白酶、纤维素酶等消化酶类及麦芽糖、葡萄糖、挥发油等成分，其消化酶能促进淀粉、蛋白质、脂肪的分解，故能助消化、增进食欲，临床用于小儿消化不良、食积腹胀、消化不良性腹泻等疗效确切；所含酵母菌还能抑制肠道有害菌群。配伍上，神曲配山楂、麦芽消食化积治食积，配苍术、厚朴燥湿运脾治湿阻，配陈皮、枳实理气和胃治气滞腹胀，配苏梗、砂仁行气安胎治妊娠恶阻，配大黄、芒硝攻积导滞治食积便秘。"},{"type":"table","caption":"神曲常见配伍与要点","head":["配伍","作用","要点"],"rows":[["神曲配山楂、麦芽","消食化积、和胃和中","为消食导滞之常用组合"],["神曲配苍术、厚朴","消食兼燥湿运脾","用于食积兼湿阻之脘腹胀满"],["神曲配陈皮、枳实","理气和胃、消胀除满","用于食积气滞之嗳腐吞酸"],["焦神曲配炒山楂","消食止泻、化积","用于小儿食积兼泄泻"]]},{"type":"quote","text":"消食和胃。用于食积不消，脘腹胀满，嗳腐吞酸，呕吐泄泻。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"神曲甘辛温燥，阴虚胃火盛、口干舌燥而无食积者不宜；因其多服耗气，气虚者不宜久服，脾胃虚弱者当慎用。服用过量或久服可致胃部灼热、纳减、口干、便秘等不适；所含酵母菌对磺胺类药物代谢有影响，正在服用磺胺类药物者应咨询医师。配伍消导药时须注意顾护胃气，孕妇不宜过多消导之品。此外本品为发酵制品，须注意防霉变，发现霉变异味者不可药用。"},{"type":"keypoints","title":"掌握要点","items":["消食和胃，尤善消面食积滞","生品兼能解表，焦用长于消食止泻","为山楂、麦芽消食组合之常用药","阴虚胃火盛者不宜，多服耗气"]}]},{"id":"mai-ya","title":"麦芽","subtitle":"Hordei Fructus Germinatus ｜ 麦芽、大麦芽、炒麦芽","category":"消食药","tags":["行气消食","健脾开胃","回乳消胀"],"meta":[{"label":"性味归经","value":"甘，平；归脾、胃经"},{"label":"功效","value":"行气消食，健脾开胃，回乳消胀"},{"label":"主治","value":"米面薯芋食滞、脘腹胀痛、脾虚食少、乳汁郁积、乳房胀痛、妇女断乳、肝郁胁痛"},{"label":"用法用量","value":"煎服 10–15 g；回乳需大剂量 30–60 g"},{"label":"使用注意","value":"哺乳期妇女不宜服用；阴虚火旺者忌用"}],"image":"","imageHint":"麦芽","summary":"麦芽为禾本科植物大麦 Hordeum vulgare L. 的成熟果实经发芽干燥的炮制品，商品以芽大、饱满、色黄褐者为佳。其味甘而性平，归脾、胃经，善消米面薯芋等淀粉类食积，又能健脾开胃，故为治食滞脘腹胀痛与脾虚食少之要药；大剂量生用又能回乳消胀，为妇科断乳之常用药。因其有回乳作用，哺乳期妇女不宜服用，阴虚火旺者亦忌用。","blocks":[{"type":"paragraph","text":"麦芽为禾本科植物大麦 Hordeum vulgare L. 的成熟果实经发芽干燥的炮制品。取净大麦洗净，浸泡至含水量约 45% 时，摊开铺平，室温发芽至芽长约 5 mm，晒干或低温干燥，筛去灰屑。商品以芽大、饱满、色黄褐、干燥、无霉变为佳，主产于河南、山东、河北、山西等地。炮制品有生麦芽、炒麦芽与焦麦芽之别：生麦芽长于回乳消胀，炒麦芽偏于消食和胃，焦麦芽则消食化积之力较强而兼能止泻。"},{"type":"paragraph","text":"麦芽味甘而性平，主归脾、胃经。甘能补益平性而无寒热之偏，故能行气消食、健脾开胃，尤善消米面薯芋等淀粉类食积，为治食积脘腹胀痛、嗳腐吞酸、纳呆及脾虚食少之要药；其行气之功又能疏肝解郁，用于肝郁气滞之胁肋胀痛、脘腹胀满；大剂量生用又能回乳消胀，为妇女断乳之常用药，临床多取生麦芽 30–60 g 煎服，或炒用研末冲服。"},{"type":"paragraph","text":"现代研究显示麦芽含α、β-淀粉酶、转化糖酶、麦芽糖、麦芽素及生物碱类，淀粉酶能促进淀粉水解为麦芽糖，故助消化作用确切，且能促进胃酸分泌，临床用于消化不良、小儿食积、乳腺增生等有较好疗效；大剂量麦芽所含麦芽素有回乳作用，临床用于断乳回奶有效。配伍上，麦芽配山楂、神曲消食化积治食滞，配党参、白术健脾开胃治脾虚食少，配柴胡、香附疏肝理气治肝郁胁痛，配大剂量生麦芽配伍知母或大黄以回乳，配橘核、荔枝核疏肝散结治乳癖。"},{"type":"table","caption":"麦芽常见配伍与要点","head":["配伍","作用","要点"],"rows":[["麦芽配山楂、神曲","行气消食、化积和中","为治米面薯芋食滞之常用组合"],["麦芽配党参、白术","健脾开胃、益气助运","用于脾虚食少、纳呆乏力"],["麦芽配柴胡、香附","疏肝理气、消胀除满","用于肝郁气滞之胁肋胀痛"],["生麦芽大剂量单用或配大黄","回乳消胀","用于妇女断乳、乳房胀痛"]]},{"type":"quote","text":"行气消食，健脾开胃，回乳消胀。用于米面薯芋食滞，脘腹胀痛，脾虚食少，乳汁郁积，乳房胀痛，妇女断乳；肝郁胁痛，脘腹胀痛。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"麦芽有回乳作用，故哺乳期妇女不宜服用；阴虚火旺、肝阳上亢者忌用，脾胃虚寒而无积滞者亦当慎用。回乳时须用生麦芽且剂量宜大（30–60 g），若用量过小反而可能催乳，此点尤须留意。服药期间可出现胃部不适、纳减、肠鸣等消化反应；与乳酶生等酶类制剂同用时，因其所含淀粉酶遇酸失活而疗效下降，二者宜间隔服用。孕妇如无回乳需要不宜大剂量使用。"},{"type":"keypoints","title":"掌握要点","items":["善消米面薯芋食积，为淀粉类食积要药","健脾开胃，可与补气药同用","大剂量生用回乳，小剂量反或催乳","哺乳期妇女禁用，阴虚火旺者忌用"]}]},{"id":"lai-fu-zi","title":"莱菔子","subtitle":"Raphani Semen ｜ 莱菔子、萝卜子、炒莱菔子","category":"消食药","tags":["消食除胀","降气化痰","行气通便"],"meta":[{"label":"性味归经","value":"辛、甘，平；归脾、胃、肺经"},{"label":"功效","value":"消食除胀，降气化痰"},{"label":"主治","value":"饮食停滞、脘腹胀痛、大便秘结、积滞泻痢；痰壅气逆、喘咳"},{"label":"用法用量","value":"煎服 5–12 g，宜炒用"},{"label":"使用注意","value":"气虚者慎用；不与人参同用；生用吐风痰"}],"image":"","imageHint":"莱菔","summary":"莱菔子为十字花科植物萝卜 Raphanus sativus L. 的干燥成熟种子，夏季果实成熟时采割，晒干，打出种子，除去果壳及杂质，商品以粒大、饱满、色棕者为佳。其味辛甘而性平，归脾、胃、肺经，能消食除胀、降气化痰，为治饮食停滞、脘腹胀满之要药，尤善行气消胀；生用又能涌吐风痰。气虚者慎用，传统认为不与人参同用，其与山楂、神曲常相须为用。","blocks":[{"type":"paragraph","text":"莱菔子为十字花科植物萝卜 Raphanus sativus L. 的干燥成熟种子。夏季果实成熟时采割植株，晒干，打出种子，除去果壳及杂质。商品以粒大、饱满、色棕褐、质坚者为佳，各地产者皆可入药，以山东、陕西、河北产量较大。炮制品有生莱菔子与炒莱菔子之别：生品性较升散，能升能散、能吐能降，可用于涌吐风痰；炒后药性缓和，善于消食除胀、降气化痰，故临床消食多用炒品。"},{"type":"paragraph","text":"莱菔子味辛甘而性平，主归脾、胃、肺经。辛能行散、甘能和中，故能消食除胀，为治饮食停滞、脘腹胀满、嗳腐吞酸、大便秘结、积滞泻痢之要药，其消食兼能行气，故胀满得消甚于一般消食药；入肺经能降气化痰，用于痰壅气逆之咳嗽气喘、痰多；生用又能涌吐风痰，用于痰涎壅盛、咽喉不利者。"},{"type":"paragraph","text":"现代研究显示莱菔子含莱菔素、芥子碱、莱菔子素及脂肪油等成分，莱菔素能促进胃肠蠕动、抑制胃酸分泌，芥子碱有明显的镇咳、祛痰作用，临床用于消化不良、功能性腹胀、便秘、小儿食积及慢性支气管炎等有较好疗效。配伍上，莱菔子配山楂、神曲消食化积治食滞，配枳实、厚朴行气消胀治气滞，配半夏、陈皮降气化痰治痰湿咳嗽，配苏子、白芥子降气化痰定喘，配大黄、芒硝攻积导滞治便秘。"},{"type":"table","caption":"莱菔子常见配伍与要点","head":["配伍","作用","要点"],"rows":[["莱菔子配山楂、神曲","消食化积、行气和胃","用于饮食停滞、嗳腐吞酸"],["莱菔子配枳实、厚朴","行气除满、消胀导滞","用于气滞腹胀、大便秘结"],["莱菔子配半夏、陈皮","降气化痰、理气止咳","用于痰湿壅盛之咳嗽气喘"],["莱菔子配苏子、白芥子","降气化痰、宣肺平喘","用于痰壅气逆之喘咳"]]},{"type":"quote","text":"消食除胀，降气化痰。用于饮食停滞，脘腹胀痛，大便秘结，积滞泻痢；痰壅气逆，喘咳。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"莱菔子辛散耗气，气虚、脾虚而无积滞者慎用；服药过量可致恶心、呕吐、胃部不适与腹泻，胃溃疡者慎用。古有\"莱菔子气弱人忌之\"之说。传统认为莱菔子能削弱人参的补气作用，故人参不宜与莱菔子同用，二者服药时间应间隔；此外莱菔子不宜与人参类补益药同方配伍。生用涌吐风痰之力强，体虚者不宜，且吐后宜饮温粥以护胃。孕妇慎用。"},{"type":"keypoints","title":"掌握要点","items":["消食除胀兼降气化痰，胀满之证尤宜","炒用缓和而长于消食，生用能涌吐风痰","传统不与人参同用","气虚者慎用，过量可致恶心呕吐"]}]},{"id":"shi-guan-zhi","title":"使君子","subtitle":"Quisqualis Fructus ｜ 使君子、使君子仁、壳君子","category":"驱虫药","tags":["杀虫消积","健脾","驱蛔虫"],"meta":[{"label":"性味归经","value":"甘，温；归脾、胃经"},{"label":"功效","value":"杀虫消积"},{"label":"主治","value":"蛔虫病、蛲虫病、虫积腹痛、小儿疳积"},{"label":"用法用量","value":"煎服 6–9 g（使君子仁 6–9 g）；亦可炒熟嚼服，小儿按岁数给药"},{"label":"使用注意","value":"服药期间忌饮浓茶；用量过大可致呃逆、呕吐、眩晕；阴虚火旺者慎用"}],"image":"","imageHint":"使君","summary":"使君子为使君子科植物使君子 Quisqualis indica (L.) Vaub. 的干燥成熟果实，秋季果实成熟时采收，除去杂质，晒干，商品以个大、仁满、色灰褐、味甘者为佳，主产于四川、湖南、贵州、广东等地。其味甘而性温，归脾、胃经，能杀虫消积，尤善驱蛔虫，为治蛔虫病、小儿虫积腹痛与疳积之要药。因其甘温而不峻，故小儿亦常用；服药期间忌饮浓茶，以免引起呃逆。","blocks":[{"type":"paragraph","text":"使君子为使君子科植物使君子 Quisqualis indica (L.) Vaub. 的干燥成熟果实。秋季果实成熟时采收，除去杂质，晒干。商品以个大、粒仁饱满、色灰褐或棕褐、味甘者为佳，主产于四川、湖南、贵州、广东、广西、云南等地，旧时以四川产量大、品质佳而著名。药用有果实与仁两种，果实连壳称\"壳君子\"，去壳取仁称\"使君子仁\"，二者功效相近；使用时多炒至微黄以香而不燥，并可增强驱虫效果。其仁含大量脂肪油，嚼服时易腻膈，临床多以煎剂或丸剂使用。"},{"type":"paragraph","text":"使君子味甘而性温，主归脾、胃经。甘能缓急、温能通行，故能杀虫消积，尤善驱蛔虫，为治蛔虫病、蛲虫病之要药，用于虫积腹痛、脐腹胀痛、面部虫斑、嗜食异物；其甘温不燥之性又能健脾和中、改善小儿脾胃，故对小儿疳积、形体消瘦、纳呆腹胀尤为合宜，且小儿服用相对安全。此外亦可用于乳糜尿等。"},{"type":"paragraph","text":"现代研究显示使君子仁含使君子酸、脂肪油（棕榈酸、亚油酸等），使君子酸对蛔虫、蛲虫有麻痹作用，且对蟛蜞、绦虫亦有一定驱杀作用，故临床用于蛔虫病、蛲虫病、蛲虫性阑尾炎疗效确切。配伍上，使君子配苦楝皮、槟榔增强杀虫之力，配槟榔、大黄治虫积腹痛兼便秘，配神曲、麦芽健脾消积治小儿疳积，配党参、白术补气健脾以扶助正气，配海藻、昆布等可治丝虫病所致乳糜尿。"},{"type":"table","caption":"使君子常见配伍与要点","head":["配伍","作用","要点"],"rows":[["使君子配苦楝皮、槟榔","杀虫驱蛔、导滞下虫","用于蛔虫病、虫积腹痛"],["使君子配槟榔、大黄","杀虫攻下、荡涤虫积","用于虫积兼大便秘结"],["使君子配神曲、麦芽","杀虫健脾、消积和中","用于小儿疳积、纳呆消瘦"],["使君子配党参、白术","驱虫扶正、益气健脾","用于体弱小儿之虫积"]]},{"type":"quote","text":"杀虫消积。用于蛔虫病，蛲虫病，虫积腹痛，小儿疳积。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"使君子服药期间忌饮浓茶与热水，因茶中鞣质与使君子仁中脂肪油结合后可使药物失去驱虫效力；用量过大可致呃逆、呕吐、眩晕、头痛、腹泻等不良反应，儿童服用须按年龄与体重定量，成人亦不宜过量。阴虚火旺、脾胃虚寒者慎用；肝肾功能不全者应慎用。服药期间若出现剧烈腹痛、呕吐不止或意识异常，应立即停药并就医；驱虫药多宜空腹或清晨服，以利虫体排出。"},{"type":"keypoints","title":"掌握要点","items":["杀虫消积，尤善驱蛔虫","甘温不燥，兼能健脾，小儿疳积尤宜","服药期间忌饮浓茶","用量过大可致呃逆、呕吐、眩晕"]}]},{"id":"ku-lian-pi","title":"苦楝皮","subtitle":"Meliae Cortex ｜ 苦楝皮、川楝皮","category":"驱虫药","tags":["杀虫","疗癣","驱蛔杀虫"],"meta":[{"label":"性味归经","value":"苦，寒；有毒。归肝、脾、胃经"},{"label":"功效","value":"杀虫，疗癣"},{"label":"主治","value":"蛔虫病、蛲虫病、钩虫病；疥癣瘙痒、湿疹"},{"label":"用法用量","value":"煎服 4.5–9 g；外用适量"},{"label":"使用注意","value":"有毒，不宜过量或长期服用；肝肾功能不全者禁用；孕妇及哺乳期妇女忌用"}],"image":"","imageHint":"楝皮","summary":"苦楝皮为楝科植物川楝 Melia toosendan Sieb. et Zucc. 或楝 Melia azedarach L. 的干燥树皮或根皮，春夏二季剥取，晒干，商品以皮厚、断面纤维性者为佳。其味苦而性寒，有毒，归肝、脾、胃经，能杀虫疗癣，用于蛔虫、蛲虫、钩虫病，外用可治疥癣瘙痒、湿疹。因其有毒且能伤肝肾，剂量须严格控制，孕妇、哺乳期妇女及肝肾功能不全者禁用。其果实川楝子与本品同出一物，功效侧重不同。","blocks":[{"type":"paragraph","text":"苦楝皮为楝科植物川楝 Melia toosendan Sieb. et Zucc. 或楝 Melia azedarach L. 的干燥树皮或根皮。春夏季剥取，晒干。商品以皮厚、干燥、断面纤维性强者为佳，主产于四川、湖北、湖南、江苏、河南等地。川楝的果实另作\"川楝子\"入药，能疏肝泄热、行气止痛、杀虫，与苦楝皮功效不同而均能杀虫，用时须分辨。本品有毒，现代药典以川楝皮为正品来源，临床多在医师指导下短期使用。"},{"type":"paragraph","text":"苦楝皮味苦而性寒，有毒，主归肝、脾、胃经。苦能泄降、寒能清热，故能杀虫，用于蛔虫病、蛲虫病、钩虫病之虫积腹痛；其杀虫之力较使君子为峻，故对成虫较多、腹痛剧烈者较为适合；外用又能疗癣、祛风止痒，用于疔疮、疥癣、湿疹、皮肤瘙痒。因其有毒且苦寒败胃，故临床多与其他驱虫药配伍以减毒，且中病即止。"},{"type":"paragraph","text":"现代研究显示苦楝皮含川楝素（苦楝素）、苦楝萜内酯等活性成分，川楝素对蛔虫、蛲虫、钩虫有麻痹作用，与使君子所含使君子酸作用机制不同，二者合用可增强驱虫效果；所含苦楝萜内酯尚有抗肿瘤与抗炎作用，但毒理研究显示其对肝、肾、脾及生殖系统有可逆性损害，故临床用量须严格限制。配伍上，苦楝皮配使君子、槟榔增强杀虫除积之力，配大黄、芒硝攻下以利虫体排出，配槟榔治胆道蛔虫，配地肤子、白鲜皮外用治疥癣湿疹。"},{"type":"table","caption":"苦楝皮常见配伍与要点","head":["配伍","作用","要点"],"rows":[["苦楝皮配使君子","杀虫除积、互补增效","用于蛔虫病、蛲虫病"],["苦楝皮配槟榔","杀虫行气、导滞下虫","用于虫积腹痛、胆道蛔虫"],["苦楝皮配大黄、芒硝","攻下杀虫、荡涤虫积","用于虫积兼腑实便秘"],["苦楝皮配地肤子、白鲜皮","杀虫止痒、疗癣","外用治疥癣湿疹、瘙痒"]]},{"type":"quote","text":"杀虫，疗癣。用于蛔虫、蛲虫、钩虫病；外治疥癣瘙痒。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"苦楝皮有毒，本品不属十八反十九畏之列，但苦寒有毒且能伤肝肾，用药安全有赖于剂量控制与短期使用。须严格控制剂量，一般不宜超过 9 g，且不宜连续久服；肝肾功能不全者禁用，孕妇、哺乳期妇女及儿童慎用（婴幼儿尤应慎用）；脾胃虚弱者慎用，因苦寒败胃。中毒表现为恶心、呕吐、腹痛、腹泻、头晕、嗜睡、烦躁，甚则神志不清、肝肾损害，出现异常应立即停药并就医。本品苦寒且有小毒，须在医师指导下使用；外用亦可经皮吸收而致中毒，不可大面积长期外敷。"},{"type":"keypoints","title":"掌握要点","items":["杀虫疗癣，有毒之品","驱蛔之力较峻，宜配伍减毒","孕妇、哺乳期妇女与肝肾功能不全者禁用","中毒可见胃肠与神经系统症状，须严控剂量"]}]},{"id":"bing-liang","title":"槟榔","subtitle":"Arecae Semen ｜ 槟榔、槟榔子、大腹皮（果皮另用）","category":"驱虫药","tags":["杀虫消积","行气","利水","截疟"],"meta":[{"label":"性味归经","value":"苦、辛，温；归胃、大肠经"},{"label":"功效","value":"杀虫消积，行气，利水，截疟"},{"label":"主治","value":"绦虫病、蛔虫病、姜片虫病、虫积腹痛；食积气滞、脘腹胀痛、大便秘结；水肿、脚气；疟疾"},{"label":"用法用量","value":"煎服 3–10 g；驱绦虫、姜片虫常与南瓜子配伍"},{"label":"使用注意","value":"脾虚便溏或气虚下陷者忌用；孕妇慎用；过量可致头晕、恶心"}],"image":"","imageHint":"槟榔","summary":"槟榔为棕榈科植物槟榔 Areca catechu L. 的干燥成熟种子，冬季至次春采收，除去杂质，晒干或烘干，商品以个大、体重、质坚、表面色棕褐有斑纹者为佳，主产于海南、广西、云南、台湾等地。其味苦辛而性温，归胃、大肠经，杀虫消积而行气利水，为治绦虫、蛔虫、姜片虫及食积气滞之要药；又可截疟，为治疟疾之常用药。脾虚便溏者忌用，孕妇慎用。","blocks":[{"type":"paragraph","text":"槟榔为棕榈科植物槟榔 Areca catechu L. 的干燥成熟种子。冬季至次春果实成熟时采收，除去杂质，晒干或烘干。商品以个大、体重、质坚、表面色棕褐、具斑纹、断面黄白者为佳，主产于海南、广西、云南、台湾等地，习称\"海南槟榔\"。其果皮另作\"大腹皮\"入药，行气宽中、利水消肿，较槟榔力缓而无毒，常用于脘腹胀满、水肿之证；槟榔子则力峻。"},{"type":"paragraph","text":"槟榔味苦辛而性温，归胃、大肠经。苦能泄降、辛能行散、温能通行，故能杀虫消积，为治绦虫、蛔虫、姜片虫及虫积腹痛之要药，尤善驱绦虫，临床常与南瓜子配伍；其行气导滞之功又可治食积气滞、脘腹胀痛、大便秘结，为治腹胀便秘之常用药；因能行气利水，故可治水肿、脚气；又能截疟，为治疗疟疾的常用药，多与常山、草果、柴胡等同用。"},{"type":"paragraph","text":"现代研究显示槟榔含生物碱（槟榔碱、槟榔次碱）、鞣质、树脂等，槟榔碱能麻痹绦虫与姜片虫，使虫体失去攀附与吸附能力，并促进肠道蠕动而利于虫体排出，同时有拟胆碱样作用，可引起心率加快、血压升高与唾液分泌增加；其驱绦作用确切，临床用于绦虫病、姜片虫病、蛔虫病及疟疾疗效可靠。配伍上，槟榔配南瓜子增强绦虫麻痹作用，配使君子、苦楝皮增强杀虫除积，配木香、枳实行气消积治食积气滞，配商陆、牵牛子治水肿，配常山、草果截疟，配陈皮、枳实治胃脘胀痛。"},{"type":"table","caption":"槟榔常见配伍与要点","head":["配伍","作用","要点"],"rows":[["槟榔配南瓜子","麻痹虫体、协同驱绦","为治绦虫病之经典对药"],["槟榔配使君子、苦楝皮","杀虫消积、导滞下虫","用于蛔虫、蛲虫与虫积腹痛"],["槟榔配木香、枳实","行气消积、导滞通便","用于食积气滞、腹胀便秘"],["槟榔配常山、草果","截疟除痰、燥湿理气","用于疟疾寒热、痰湿中阻"]]},{"type":"quote","text":"主杀三虫，消宿食，治癥瘕，疗风疾。","source":"《神农本草经·果部·槟榔》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"槟榔苦辛温燥，脾虚便溏、脾胃虚弱或气虚下陷者忌用；孕妇慎用，因其能兴奋子宫平滑肌并有较强行气作用；高血压、心动过速、甲状腺功能亢进及精神病患者应慎用，因槟榔碱可致心率加快、血压升高与幻觉、烦躁。用量过大可致头晕、恶心、呕吐、腹痛、心悸、流涎等副反应，故须按剂量使用、不宜久服；槟榔为槟榔属管制之咀嚼用成品，具成瘾性，国际上已明确为致癌物，临床不宜长期嚼食。"},{"type":"keypoints","title":"掌握要点","items":["杀虫消积、行气利水、截疟，功效俱广","善驱绦虫，常与南瓜子配伍","脾虚便溏、气虚下陷者忌用，孕妇慎用","槟榔碱可致心率加快、血压升高"]}]},{"id":"nan-gua-zi","title":"南瓜子","subtitle":"Cucurbitae Semen ｜ 南瓜子、南瓜籽、炒南瓜子","category":"驱虫药","tags":["杀虫","驱绦虫","驱蛔虫"],"meta":[{"label":"性味归经","value":"甘，平；归胃、大肠经"},{"label":"功效","value":"杀虫"},{"label":"主治","value":"绦虫病、蛔虫病；与槟榔配伍可增强驱绦效果"},{"label":"用法用量","value":"研粉，60–120 g；或作丸剂，宜饭后服"},{"label":"使用注意","value":"服用期间不宜同时服用泻下药；用量过大可致脘腹不适；腹泻者慎用"}],"image":"","imageHint":"南瓜","summary":"南瓜子为葫芦科植物南瓜 Cucurbita moschata Duch. 的干燥成熟种子，秋季果实成熟时采割，洗净，晒干，剥取种子，商品以粒大、饱满、色黄白者为佳。其味甘而性平，归胃、大肠经，能杀虫，尤善驱绦虫，为治绦虫病之常用药，临床多与槟榔配伍以增强驱绦效果。因其药性平和、几无毒性，尤宜于体弱者与小儿，服用时通常研粉或制成丸剂。","blocks":[{"type":"paragraph","text":"南瓜子为葫芦科植物南瓜 Cucurbita moschata Duch. 的干燥成熟种子。秋季果实成熟时采割，除去瓜瓤，洗净，晒干，剥取种子，去除碎屑。商品以粒大、饱满、色黄白、质坚者为佳，全国各地皆产，以山东、山西、河北、湖南等地所产较多。临床多生用或炒用，研粉后冲服，或与槟榔配伍研末服用。其性平和、几无毒性，老人、儿童及体弱患者均可酌用，是其相较于槟榔、苦楝皮的重要优势。"},{"type":"paragraph","text":"南瓜子味甘而性平，归胃、大肠经。甘能补益、性平无毒，故能杀虫驱蛔，尤善驱绦虫，为治绦虫病之常用药；其作用特点在于使虫体麻痹、纤毛失去运动能力而便于排出，与槟榔配伍可明显增强驱绦效果，且能减轻槟榔之峻烈，故临床多二者同用。此外亦可与其他驱虫药配伍用于蛔虫、蛲虫等肠虫病；因其味甘可口，亦可作食疗之品长期小量食用以保健肠道。"},{"type":"paragraph","text":"现代研究显示南瓜子含南瓜子氨酸、脂肪酸、甾醇及维生素类，南瓜子氨酸能麻痹绦虫虫体，使虫体失去攀附肠壁的能力并促使其排出，故对绦虫有良好驱杀作用，临床用于绦虫病、蛔虫病与蛲虫病疗效确切；其不溶于水而作用于肠道，故宜研粉空腹或饭后服用，并可与槟榔配合。配伍上，南瓜子配槟榔为治绦虫之经典对药，配使君子、苦楝皮增强杀虫除积，配鹤草芽增强绦虫麻痹作用，配胡黄连、黄连治虫积兼有湿热者。"},{"type":"table","caption":"南瓜子常见配伍与要点","head":["配伍","作用","要点"],"rows":[["南瓜子配槟榔","协同麻痹虫体、导虫排出","为治绦虫病之经典对药"],["南瓜子配鹤草芽","增强杀虫除绦之力","用于绦虫病、虫积腹痛"],["南瓜子配使君子、苦楝皮","杀虫消积、驱除肠虫","用于蛔虫、蛲虫病"],["南瓜子单用研粉","驱绦杀虫、药性平和","宜饭后或空腹服用，体弱者宜"]]},{"type":"quote","text":"杀虫。用于绦虫病，蛔虫病。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"南瓜子药性平和，常规用量下不良反应少见，但用量过大可致脘腹胀满、恶心、纳减、腹泻，脾胃虚弱者及腹泻者应慎用并控制剂量。服用驱虫药期间不宜同时服用泻下药，以免肠道蠕动过快而影响虫体麻痹与排出；若与槟榔配伍，则宜先用南瓜子后用槟榔，驱虫效果更佳。孕妇虽非绝对禁忌，但不宜大量长期服用。本品须研粉或打碎入煎方能有效溶出有效成分，整粒吞服疗效不佳，且不易消化。"},{"type":"keypoints","title":"掌握要点","items":["杀虫驱绦，性平无毒，老幼体弱者宜","善驱绦虫，常与槟榔配伍增强疗效","宜研粉服用，整粒吞服效果不佳","用量过大可致腹胀、纳减、腹泻"]}]},{"id":"san-qi","title":"三七","subtitle":"Notoginseng Radix et Rhizoma ｜ 三七、田七、参三七、金不换","category":"止血药","tags":["化瘀止血","活血定痛","消肿生肌"],"meta":[{"label":"性味归经","value":"甘、微苦，温；归肝、胃经"},{"label":"功效","value":"散瘀止血，消肿定痛"},{"label":"主治","value":"咯血、吐血、衄血、便血、崩漏、外伤出血、胸腹刺痛、跌扑肿痛"},{"label":"用法用量","value":"研末服 3–9 g（每次 1–3 g）；外用适量"},{"label":"使用注意","value":"孕妇慎用；不宜与藜芦同用；服药期间忌食生冷、油腻及鱼类"}],"image":"","imageHint":"三七","summary":"三七为五加科植物三七 Panax notoginseng (Burkill) F. H. Chen 的干燥根和根茎，秋季采挖，除去须根，洗净，晒干，商品以个大、体重、质坚、表面黄褐色或灰绿色、有明显横纹者为佳，主产于云南、广西等地，习称\"田七\"。其味甘微苦而性温，归肝、胃经，能散瘀止血、消肿定痛，为化瘀止血之要药，既能止血又不留瘀，为治跌打损伤与瘀滞肿痛之良药。孕妇慎用。","blocks":[{"type":"paragraph","text":"三七为五加科植物三七 Panax notoginseng (Burkill) F. H. Chen 的干燥根和根茎。秋季采挖，除去须根与泥沙，洗净，分开主根、支根与根茎，晒干。商品以个大、体重、质坚实、表面黄褐色或灰绿色、断面灰白或黄绿、有明显横纹及放射状纹理者为佳，主产于云南文山、广南等地，习称\"云南三七\"或\"田七\"，广西所产者习称\"广西三七\"。药用有生三七与熟三七之别：生品长于散瘀止血、消肿定痛，蒸制后为熟三七，长于补血益气、化瘀止痛。"},{"type":"paragraph","text":"三七味甘微苦而性温，主归肝、胃经。甘能缓急、微苦能泄、温能通行，故能散瘀止血、消肿定痛，为化瘀止血之要药。其止血而不留瘀、行血而不伤正，为治咯血、吐血、衄血、便血、崩漏等血热或瘀阻所致出血之良药，尤宜于既有出血又有瘀滞者；又能活血化瘀、消肿定痛，为治跌打损伤、瘀滞肿痛、胸腹刺痛之要药，内服外敷皆宜；并能补虚强壮，用于虚损劳伤。"},{"type":"paragraph","text":"现代研究显示三七含三七皂苷（三七总皂苷）、三七素（三七氨酸）、挥发油及多糖，三七皂苷能促进凝血酶原活性、缩短凝血时间而止血，三七素则有活血、抗炎、镇痛作用，故其\"止血不留瘀、化瘀不伤正\"的特点有明确物质基础；临床用于各种出血症、跌打损伤、冠心病、脑血管病及外伤创面等疗效确切。配伍上，三七配茜草、蒲黄增强止血化瘀之力，配桃仁、红花增强活血止痛之功，配黄芪、白术益气摄血，配冰片、血竭外用治跌打瘀肿、外伤出血。"},{"type":"table","caption":"三七常见配伍与要点","head":["配伍","作用","要点"],"rows":[["三七配茜草、蒲黄","化瘀止血、止血而不留瘀","用于吐衄、崩漏等多种出血"],["三七配桃仁、红花","活血祛瘀、消肿定痛","用于跌打损伤、瘀滞肿痛"],["三七配黄芪、白术","益气摄血、化瘀止血","用于气虚出血、劳伤吐衄"],["三七配血竭、冰片","散瘀止痛、生肌止血","外用治外伤出血与创面肿痛"]]},{"type":"quote","text":"散瘀止血，消肿定痛。用于咯血，吐血，外伤出血，跌扑肿痛。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"三七有活血化瘀之力，孕妇慎用；十八反中藜芦反诸参，三七虽不在其列，但与藜芦同用亦应谨慎；服用期间忌食生冷、油腻及鱼类，以免影响药效；对本品过敏者禁用。服用过量或长期服用可致口干、舌麻、皮肤瘀点、牙龈出血等表现，亦有报道出现过敏性皮疹与肝肾功能异常，故用量不宜过大、疗程不宜过长，并须在医师指导下使用。出血倾向明显者若需服用，应与医师充分沟通并监测凝血指标。"},{"type":"keypoints","title":"掌握要点","items":["化瘀止血，止血而不留瘀","消肿定痛，为跌打损伤良药","生品长于活血，熟品长于补益","孕妇慎用，过量可致出血倾向"]}]},{"id":"di-yu","title":"地榆","subtitle":"Sanguisorbae Radix ｜ 地榆、地榆炭、榆根","category":"止血药","tags":["凉血止血","解毒敛疮","收敛止血"],"meta":[{"label":"性味归经","value":"苦、涩，凉；归肝、大肠经"},{"label":"功效","value":"凉血止血，解毒敛疮"},{"label":"主治","value":"血热出血证（便血、痔血、崩漏、吐血、衄血）；烫伤、湿疹、疮疡痈肿"},{"label":"用法用量","value":"煎服 9–15 g；外用适量"},{"label":"使用注意","value":"脾胃虚寒者忌用；对于大面积烧伤不宜大面积外涂，以防鞣质吸收引起中毒性肝炎"}],"image":"","imageHint":"地榆","summary":"地榆为蔷薇科植物地榆 Sanguisorba officinalis L. 或白花地榆 S. officinalis var. longifolia (Bge. Y ex et C. Y. Wu) C. Y. Wu 的干燥根，春秋二季采挖，除去须根，晒干，商品以根条粗壮、表面色棕黑、断面黄褐者为佳。其味苦涩而性凉，归肝、大肠经，善凉血止血，尤善治下焦血热之便血、痔血、崩漏，为治血热出血证之要药；又能解毒敛疮，为治烫伤与湿疹之良药。脾胃虚寒者忌用。地榆炭为临床止血之常用炮制品。","blocks":[{"type":"paragraph","text":"地榆为蔷薇科植物地榆 Sanguisorba officinalis L. 或白花地榆 Sanguisorba officinalis L. var. longifolia (Bge. Y. ex et C. Y. Wu) C. Y. Wu 的干燥根。春秋二季采挖，除去须根与泥沙，晒干。商品以根条粗壮、表面色棕黑或紫褐、断面黄褐、质坚硬者为佳，主产于辽宁、河北、内蒙古、山西、吉林等地。炮制品有生地榆与地榆炭之别：生品长于凉血解毒、清热利湿，地榆炭炒炭后收敛止血之力增强，多用于出血证；白花地榆形似而断面色浅白淡黄，商品称\"白地榆\"。"},{"type":"paragraph","text":"地榆味苦涩而性凉，主归肝、大肠经。苦能泄降、涩能收敛、凉能清热，故能凉血止血，为治血热出血证之要药，尤善治下焦出血，如便血、痔血、崩漏，兼治吐血、衄血、咳血；其清热解毒、凉血敛疮之功外用可治水火烫伤、湿热疮疡、湿疹、疖肿等，为临床处理烧伤创面的常用外用药。本品性凉而味苦涩，故血热者宜，虚寒者当忌。"},{"type":"paragraph","text":"现代研究显示地榆含鞣质（地榆鞣质）、三萜皂苷（地榆皂苷）及黄酮类，鞣质能收缩局部血管、降低毛细血管通透性而止血，地榆皂苷有抗菌、抗炎、收敛、促进创面愈合等作用，临床用于下消化道出血、痔疮出血、烧伤、湿疹等疗效确切；其鞣质成分对肝脏有潜在毒性，故大面积烧伤外涂须谨慎。配伍上，地榆配槐花、侧柏叶凉血止血治下焦出血，配黄连、黄芩清热解毒治血热痢疾，配赤芍、丹皮凉血消痈治疮疡肿痛，配苦参、白鲜皮祛湿止痒治湿疹。"},{"type":"table","caption":"地榆常见配伍与要点","head":["配伍","作用","要点"],"rows":[["地榆配槐花、侧柏叶","凉血止血、收敛固摄","为治下焦血热出血之常用组合"],["地榆炭配三七、茜草","化瘀止血、止血不留瘀","用于崩漏、便血等多种出血"],["地榆配黄连、黄芩","清热解毒、凉血止痢","用于血热痢疾、里急后重"],["地榆配苦参、白鲜皮","清热燥湿、收敛止痒","外用治湿疹、疥癣瘙痒"]]},{"type":"quote","text":"凉血止血，解毒敛疮。用于血热出血证；烫伤，湿疹，疮疡痈肿。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"地榆性凉而味苦涩，脾胃虚寒、便溏者忌用，阴虚而无血热者亦不宜；对鞣质过敏者禁用。因其所含鞣质经创面大量吸收可引起中毒性肝炎，严重者可致肝肾损害，故大面积烧伤、创面外涂时不宜大面积使用，且不宜长期连续外敷，应在医师指导下进行。长期大量内服可致恶心、呕吐、腹泻等胃肠反应，亦有便秘之虞；孕妇、哺乳期妇女及肝肾功能不全者应慎用。"},{"type":"keypoints","title":"掌握要点","items":["凉血止血，尤善治下焦血热出血","解毒敛疮，为烧伤、湿疹外用良药","炒炭后收敛止血力增强","脾胃虚寒者忌用，大面积创面外涂须防鞣质中毒"]}]},{"id":"bai-mao-gen","title":"白茅根","subtitle":"Imperatae Rhizoma ｜ 白茅根、茅根、茅草根","category":"止血药","tags":["凉血止血","清热利尿","清肺胃热"],"meta":[{"label":"性味归经","value":"甘，寒；归肺、胃、膀胱经"},{"label":"功效","value":"凉血止血，清热利尿，清肺胃热"},{"label":"主治","value":"血热出血证（鼻衄、咯血、吐血、尿血）；热淋、水肿、胃热呕吐、肺热咳嗽"},{"label":"用法用量","value":"煎服 15–30 g；鲜品用量加倍，或捣汁服"},{"label":"使用注意","value":"脾胃虚寒、溲多不渴者忌服；煎煮不宜过久"}],"image":"","imageHint":"茅根","summary":"白茅根为禾本科植物白茅 Imperata cylindrica (L.) Beauv. 的干燥根茎，冬季至次春采挖，除去须根，洗净，晒干，商品以条粗、色白、味甘者为佳，全国各地均产。其味甘而性寒，归肺、胃、膀胱经，能凉血止血、清热利尿，又善清肺胃之热，为治血热出血证与血淋、水肿之常用药。因其性寒且甘而不腻，止血而不留瘀、利尿而不伤阴，故寒热虚实均可随证配伍。","blocks":[{"type":"paragraph","text":"白茅根为禾本科植物白茅 Imperata cylindrica (L.) Beauv. 的干燥根茎。冬季至次春采挖，除去须根与泥沙，洗净，晒干或切段。商品以条粗、色白、味甘、质轻者为佳，全国各地均有野生，产于河南、河北、山东、山西、江苏等地者质量较佳。其质轻味甘，煎汤后汤色微黄而气清。另可采鲜品入药，鲜品清热凉血之力较胜，尤宜于热病烦渴与血热出血之急性证候。"},{"type":"paragraph","text":"白茅根味甘而性寒，主归肺、胃、膀胱经。甘能生津、寒能清热，故能凉血止血，为治血热出血证之常用药，用于鼻衄、咯血、吐血、尿血、崩漏；其清热利尿之功使血热从小便而出，故尤善治血热尿血、血淋；又能清肺胃之热，用于肺热咳嗽、痰黄黏稠与胃热呕吐、呃逆；并可治热淋涩痛、水肿、小便不利。因其甘寒而不腻、止血而不留瘀、利尿而不伤阴，故寒热虚实皆可配伍使用。"},{"type":"paragraph","text":"现代研究显示白茅根含茅根多糖、5-羟基铁亭酸（麦考酚酸）、甾体类及钾盐等，麦考酚酸对腺苷脱氨酶有抑制作用，茅根多糖能增强免疫与利尿，所含钾盐有明显的利尿作用，临床用于急性肾炎、血尿、上消化道出血、急性支气管炎、胃热呕吐等有较好疗效。配伍上，白茅根配侧柏叶、藕节凉血止血治血热出血，配车前子、滑石清热利尿治血淋热淋，配竹叶、麦冬清肺胃热治肺热咳嗽，配芦根清胃止呕治胃热呕哕，配益母草、泽兰利水消肿治水肿。"},{"type":"table","caption":"白茅根常见配伍与要点","head":["配伍","作用","要点"],"rows":[["白茅根配侧柏叶、藕节","凉血止血、收敛固摄","为治血热吐衄之常用组合"],["白茅根配车前子、滑石","清热利尿通淋","用于血淋、热淋涩痛"],["白茅根配竹叶、麦冬","清肺胃热、生津止渴","用于肺热咳嗽、胃热呕哕"],["白茅根配益母草、泽兰","利水消肿、行血活血","用于水肿、小便不利"]]},{"type":"quote","text":"主血热咳逆上气，茅瘿水肿，下血。","source":"《神农本草经·草部·茅根》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"白茅根甘寒，脾胃虚寒、脘腹冷痛、便溏者忌用；溲多不渴而无湿热者不宜，因其利尿之功可使小便更频而加重症状；孕妇慎用。本品所含钾盐较多，肾功能不全、心衰、高钾血症患者应慎用，避免加重水钠潴留与高钾。煎煮时间不宜过长，久煎则有效成分损失而疗效减弱；鲜品汁液黏腻，量大易致纳呆、恶心、腹胀，脾虚者尤须注意用量。"},{"type":"keypoints","title":"掌握要点","items":["凉血止血、清热利尿、清肺胃热","善治血热尿血与血淋","止血不留瘀、利尿不伤阴","脾胃虚寒、溲多不渴者忌用"]}]},{"id":"da-ji","title":"大蓟","subtitle":"Cirsii Japonici Herba ｜ 大蓟、大蓟根","category":"止血药","tags":["凉血止血","散瘀解毒消痈","止血不留瘀"],"meta":[{"label":"性味归经","value":"苦、甘，凉；归心、肝经"},{"label":"功效","value":"凉血止血，散瘀解毒消痈"},{"label":"主治","value":"血热出血证（吐血、咯血、衄血、崩漏、尿血、便血）；热毒痈肿"},{"label":"用法用量","value":"煎服 15–30 g；外用适量"},{"label":"使用注意","value":"脾胃虚寒而无瘀滞者忌服；孕妇慎用"}],"image":"","imageHint":"大蓟","summary":"大蓟为菊科植物大蓟 Cirsium japonicum Fisch. ex DC. 或刺儿菜 Cirsium setosum (Willd.) Bieb. 的干燥地上部分，夏季花蕾初现时采割，晒干，商品以茎粗、色绿褐、质硬、断面灰白者为佳。其味苦甘而性凉，归心、肝经，能凉血止血、散瘀解毒消痈，为治血热出血证之常用药，尤善治吐血、咯血、衄血与崩漏；又能清热解毒、消痈，用于热毒痈肿疮疡。脾胃虚寒而无瘀滞者忌服。","blocks":[{"type":"paragraph","text":"大蓟为菊科植物大蓟 Cirsium japonicum Fisch. ex DC. 或刺儿菜 Cirsium setosum (Willd.) Bieb. 的干燥地上部分。夏季花蕾初现时采割，晒干。商品以茎粗、色绿褐、质硬、断面灰白者为佳，全国各地均产，江苏、安徽、浙江、福建、广东等地所产较多。地上部分入药称\"大蓟草\"，其干燥根另作\"大蓟根\"入药，凉血止血之力更专。炮制品有生大蓟与大蓟炭之别：生品长于凉血解毒、消痈散瘀，炒炭后收涩止血力强，多用于出血证。"},{"type":"paragraph","text":"大蓟味苦甘而性凉，主归心、肝经。苦能泄降、甘能缓急、凉能清热，故能凉血止血，为治血热出血证之常用药，尤善治血热妄行之吐血、咯血、衄血、崩漏，兼治尿血、便血；其散瘀之功使其止血而不留瘀，故对出血兼有瘀滞者尤宜；又能清热解毒、消痈散结，用于热毒痈肿疮疡、咽喉肿痛；外用还可治跌打损伤、瘀肿疼痛。小蓟与大蓟功似，但小蓟兼能利尿通淋而更长于治尿血血淋，大蓟则更长于散瘀消痈。"},{"type":"paragraph","text":"现代研究显示大蓟含大蓟苷、柳叶苦苷、咖啡酸、绿原酸及挥发油等，大蓟苷、柳叶苦苷对金黄色葡萄球菌、链球菌等有较强抑菌作用，并有止血、抗炎、抑菌及抗肿瘤作用，临床用于上消化道出血、咯血、痔疮出血及疮痈肿毒等疗效确切。配伍上，大蓟配小蓟、侧柏叶凉血止血治多种血热出血，配白茅根、藕节增强止血而不留瘀之力，配黄连、蒲公英清热解毒消痈治疮痈肿毒，外用配赤小豆、冰片治跌打瘀肿。"},{"type":"table","caption":"大蓟常见配伍与要点","head":["配伍","作用","要点"],"rows":[["大蓟配小蓟、侧柏叶","凉血止血、化瘀生新","为治血热出血之常用组合"],["大蓟配白茅根、藕节","凉血止血而不留瘀","用于吐衄、咯血、崩漏"],["大蓟配黄连、蒲公英","清热解毒、消痈散结","用于热毒痈肿、疮疡"],["大蓟配赤小豆、冰片","活血消肿止痛","外用治跌打损伤、瘀肿"]]},{"type":"quote","text":"凉血止血，散瘀解毒消痈。用于吐血，衄血，尿血，便血，崩漏，外伤出血，痈肿疮毒。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"大蓟苦甘性凉，脾胃虚寒、食少便溏者忌用，无瘀滞者不宜久服；孕妇慎用，因其有活血散瘀之力。本品含苦苷类成分，剂量过大或长期服用可致苦味药过量反应，出现口苦、恶心、呕吐、腹泻、食欲减退及头晕，须及时停用；脾胃虚弱者尤易出现纳减。感冒发热期间不宜服用，糖尿病患者慎用。服用期间忌食辛辣油腻，若出现持续腹泻或明显胃部不适应停药并咨询医师。"},{"type":"keypoints","title":"掌握要点","items":["凉血止血、散瘀解毒消痈","止血而不留瘀，故出血兼瘀者尤宜","炒炭后收涩止血力增强","脾胃虚寒而无瘀滞者忌服"]}]},{"id":"xiao-ji","title":"小蓟","subtitle":"Cirsii Herba ｜ 小蓟、刺儿菜、猫儿刺","category":"止血药","tags":["凉血止血","散瘀解毒消痈","利尿通淋"],"meta":[{"label":"性味归经","value":"甘、苦，凉；归心、肝经"},{"label":"功效","value":"凉血止血，散瘀解毒消痈"},{"label":"主治","value":"血热出血证，尤善治尿血、血淋；热毒痈肿"},{"label":"用法用量","value":"煎服 15–30 g；外用适量"},{"label":"使用注意","value":"脾胃虚寒、便溏者忌服；与大蓟功似而更长于止血"}],"image":"","imageHint":"小蓟","summary":"小蓟为菊科植物刺儿菜 Cirsium setosum (Willd.) Bieb. 的干燥地上部分，夏季花蕾初现时采割，晒干，商品以茎细、色灰绿、质脆者为佳。其味甘苦而性凉，归心、肝经，能凉血止血、散瘀解毒消痈；与大蓟功似而更长于止血，尤善治尿血、血淋，为治血热下焦出血之要药。因其性凉，脾胃虚寒、便溏者忌服，孕妇亦当慎用。其根亦可入药，凉血止血之力更专。","blocks":[{"type":"paragraph","text":"小蓟为菊科植物刺儿菜 Cirsium setosum (Willd.) Bieb. 的干燥地上部分。夏季花蕾初现时采割，晒干。商品以茎细、色灰绿、断面纤维性、质脆者为佳，全国各地均产，以江苏、安徽、浙江、河北、广东等地所产较多。历史上小蓟与 大蓟 常相混用，现药典已分别收载：小蓟基原为刺儿菜，与大蓟之基原不同，二者功效相近而各有偏重，小蓟更长于止血而尤善治尿血。炮制品有生小蓟与小蓟炭之别，炒炭后止血力更强。"},{"type":"paragraph","text":"小蓟味甘苦而性凉，主归心、肝经。苦能泄降、甘能缓急、凉能清热，故能凉血止血，为治血热出血证之常用药，尤善治下焦之尿血、血淋，凡热结下焦、血络受损之小便出血皆可用之；兼治吐血、咯血、衄血、崩漏、便血；其散瘀之性使止血而不留瘀，故出血夹瘀者尤宜；又能清热解毒、消痈散结，用于热毒痈肿疮疡。外用可治疮疡、跌打瘀肿。"},{"type":"paragraph","text":"现代研究显示小蓟含刺儿菜苷、芦丁、咖啡酸、绿原酸、原儿茶酸及挥发油等，刺儿菜苷对血小板聚集有明显抑制作用，芦丁能增强毛细血管抵抗力、降低其脆性与通透性，咖啡酸与绿原酸有抑菌、抗炎作用，合而成为其凉血止血与消痈的物质基础；临床用于血尿、急性肾小球肾炎、功能性子宫出血、疮痈肿毒等疗效确切。配伍上，小蓟配大蓟、侧柏叶凉血止血治多种血热出血，配生地黄、蒲黄凉血养阴止血治尿血血淋，配白茅根、藕节增强止血而不留瘀之力，配蒲公英、紫花地丁清热解毒消痈治疮痈。"},{"type":"table","caption":"小蓟常见配伍与要点","head":["配伍","作用","要点"],"rows":[["小蓟配大蓟、侧柏叶","凉血止血、化瘀生新","为治血热出血之常用组合"],["小蓟配生地黄、蒲黄","凉血养阴、止血利尿","为治尿血、血淋之要方"],["小蓟配白茅根、藕节","凉血止血而不留瘀","用于崩漏、吐衄"],["小蓟配蒲公英、紫花地丁","清热解毒、消痈散结","用于热毒痈肿、疮疡"]]},{"type":"quote","text":"凉血止血，散瘀解毒消痈。用于吐血，衄血，尿血，便血，崩漏，外伤出血，痈肿疮毒。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"小蓟甘苦性凉，脾胃虚寒、纳呆便溏者忌用，无血热瘀滞者不宜；孕妇慎用。服用过量或久服可致口苦、恶心、腹泻、食欲减退、头晕等苦味药过量反应，体虚者尤明显；脾胃虚弱者宜配伍健脾之品以顾护中焦。感冒发热期间不宜服用，肾功能不全者应遵医嘱使用。若出现持续腹泻、血便加重或明显乏力，应停药并及时就医。"},{"type":"keypoints","title":"掌握要点","items":["凉血止血，尤善治尿血、血淋","与大蓟功似而更长于止血","止血而不留瘀，出血夹瘀者尤宜","脾胃虚寒、便溏者忌服"]}]},{"id":"yan-hu-suo","title":"延胡索","subtitle":"Corydalis Rhizoma ｜ 延胡索、玄胡索、元胡","category":"活血化瘀药","tags":["活血","行气","止痛"],"meta":[{"label":"性味归经","value":"辛、苦，温；归肝、脾经"},{"label":"功效","value":"活血，行气，止痛"},{"label":"主治","value":"胸胁脘腹痛、痛经、产后瘀阻腹痛、跌打损伤、风湿痹痛；气滞血瘀诸痛证"},{"label":"用法用量","value":"煎服 3–10 g；研末服 1–3 g；醋制可增强止痛作用"},{"label":"使用注意","value":"阴虚火旺及血虚无瘀者慎用；孕妇慎用；生用活血力强，易伤正"}],"image":"","imageHint":"延胡","summary":"延胡索为罂粟科植物延胡索 Corydalis yanhusuo S. Y. Hu、 bulbiferum 或亚洲延胡索等的干燥块茎，夏季茎叶枯萎时采挖，除去须根，洗净，置沸水中煮至无白心，晒干或烘干，商品以个大、饱满、色黄褐、质坚硬者为佳。其味辛苦而性温，归肝、脾经，善行气活血止痛，为治气滞血瘀诸痛证之要药，素有\"血中气药\"之称，止痛作用确切而持久，尤善治妇科、心腹与胁肋疼痛。孕妇慎用。","blocks":[{"type":"paragraph","text":"延胡索为罂粟科植物延胡索 Corydalis yanhusuo S. Y. Hu、延胡索 C. bulbifera 或亚洲延胡索 C. asiaticus 等的干燥块茎。夏季植株枯萎时采挖，除去须根，洗净，置沸水中煮至无白心，晒干或烘干。商品以个大、饱满、外皮色黄褐、质坚硬、断面角质样者为佳，主产于浙江东阳、磐安及江苏连云港等地，习称\"东元胡\"或\"浙元胡\"，产量大而品质佳。炮制品有生延胡索、醋延胡索与炒延胡索之别：生品行气活血力强，醋制后增强止痛作用，临床多用醋制品。"},{"type":"paragraph","text":"延胡索味辛苦而性温，主归肝、脾经。辛能行散、苦能降泄、温能通行，故能活血行气止痛，为治气滞血瘀诸痛证之要药，古称\"血中气药\"，其止痛作用强而持久，应用范围广，尤善治心腹腰膝胁肋诸痛、痛经、产后瘀阻腹痛、跌打损伤与风湿痹痛；因其破血力较强，故瘀血痛甚者配桃仁、红花，血虚者配当归、白芍，气滞者配柴胡、香附，川芎，寒凝者配桂枝、吴茱萸。"},{"type":"paragraph","text":"现代研究显示延胡索含延胡索乙素（ tetrahydropalmatine）、延胡索甲素、延胡索丙素等生物碱，延胡索乙素具有中枢镇痛、镇静、催眠及抗溃疡作用，其镇痛机制与抑制脑内多巴胺能系统及上行网状结构激活系统有关，且不具成瘾性，临床用于消化性溃疡、痛经、产后瘀阻、冠心病心绞痛、胆囊炎、神经性疼痛等疗效确切。配伍上，延胡索配川楝子为金铃子散治肝郁化火之胸胁脘腹疼痛，配川芎、当归治血瘀痛经，配桃仁、红花治跌打损伤，配桂枝、吴茱萸治寒凝气滞之痛，配柴胡、香附治气滞胁痛。"},{"type":"table","caption":"延胡索常见配伍与要点","head":["配伍","作用","要点"],"rows":[["延胡索配川楝子","疏肝泄热、行气止痛","为治肝郁化火诸痛之要方"],["延胡索配川芎、当归","活血养血、调经止痛","用于血瘀兼血虚之痛经"],["延胡索配桃仁、红花","活血祛瘀、消肿止痛","用于跌打损伤、瘀肿疼痛"],["延胡索配桂枝、吴茱萸","温经散寒、行气止痛","用于寒凝气滞之脘腹冷痛"]]},{"type":"quote","text":"活血，利气，止痛。用于胸胁、脘腹疼痛，痛经，经闭，产后瘀阻腹痛，跌打损伤，风湿痹痛。","source":"《本草纲目·草部·延胡索》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"延胡索辛温走窜、破血力强，阴虚火旺、血虚无瘀者慎用，孕妇慎用；生品活血力较强，体虚者当用醋制品并配伍补益之品以顾护正气。服用过量可出现头晕、嗜睡、口干、恶心、腹胀、心率增快等不良反应，须控制剂量，不宜长期连续服用。所含生物碱具中枢抑制作用，服用期间不宜饮酒，亦不宜与中枢抑制剂、镇静催眠药同用；服药期间若出现明显嗜睡、乏力、心悸应停用并咨询医师。手术前应告知医师正在服用本品。"},{"type":"keypoints","title":"掌握要点","items":["活血行气止痛，为诸痛证要药","古称“血中气药”，止痛作用强而持久","醋制后止痛力增强","阴虚火旺、血虚无瘀者慎用，孕妇慎用"]}]},{"id":"chuan-xiong","title":"川芎","subtitle":"Chuanxiong Rhizoma ｜ 川芎、芎䓖、抚芎、西芎","category":"活血化瘀药","tags":["活血行气","祛风止痛","开郁"],"meta":[{"label":"性味归经","value":"辛，温；归肝、胆、心包经"},{"label":"功效","value":"活血行气，祛风止痛"},{"label":"主治","value":"胸痹心痛、胸胁刺痛、跌打肿痛、月经不调、经闭痛经、头痛、风湿痹痛"},{"label":"用法用量","value":"煎服 3–10 g"},{"label":"使用注意","value":"阴虚火旺、月经过多及出血性疾病者慎用；孕妇慎用；含川芎嗪，与抗凝药同用需谨慎"}],"image":"","imageHint":"川芎","summary":"川芎为伞形科植物川芎 Ligusticum chuanxiong Hort. 的干燥根茎，夏季植株叶鞘未完全闭合时采挖，除去泥沙，晒干或烘干，商品以个大、质坚、表面黄褐色、断面黄白、油性大、香气浓者为佳，主产于四川都江堰、彭州、灌县等地，习称\"川芎\"，为地道之品。其味辛而性温，归肝、胆、心包经，善活血行气、祛风止痛，为治头痛之要药，气行血行，故为妇科调经与胸痹心痛之常用药。","blocks":[{"type":"paragraph","text":"川芎为伞形科植物川芎 Ligusticum chuanxiong Hort. 的干燥根茎。夏季植株叶鞘未完全闭合、花冠初开时采挖，除去泥沙，晒干或烘干。商品以个大、质坚实、表面黄褐色、断面黄白或灰黄、油性大、香气浓者为佳，主产于四川都江堰、彭州、灌县等地，习称\"川芎\"，为地道之品，产量居全国之首；此外浙江、江苏、湖北等地亦有栽培。饮片多切薄片或段入药，生用即可；古人认为\"川芎\"宜\"细嚼\"，其芳香走窜之气可直达头目。"},{"type":"paragraph","text":"川芎味辛而性温，主归肝、胆、心包经。辛能行散、温能通行，故能活血行气，治胸痹心痛、胸胁刺痛、癥瘕积聚、跌打肿痛；其上行头目、外达皮毛之性又能祛风止痛，为治头痛之要药，尤善治风寒头痛、风热头痛、血虚头痛、血瘀头痛；因其气行则血行，故为妇科调经要药，用于月经不调、经闭痛经、产后瘀阻腹痛、癥瘕痞块；此外还常用于\"头痛不离川芎\"之诸般头痛与风湿痹痛。"},{"type":"paragraph","text":"现代研究显示川芎含川芎嗪（tetramethylpyrazine）、藁本内酯、川芎内酯、阿魏酸及挥发油，川芎嗪能扩张血管、改善微循环、抑制血小板聚集，阿魏酸有抗血小板聚集与抗炎作用，藁本内酯有明显镇静、镇痛与解痉作用，故临床用于冠心病心绞痛、缺血性脑血管病、偏头痛、痛经、产后瘀阻及顽固性头痛等疗效确切。配伍上，川芎配白芷治风寒头痛，配菊花治风热头痛，配当归、白芍养血调经，配桃仁、红花增强活血祛瘀，配柴胡、香附疏肝行气，配黄芪补气行滞以治气虚头痛。"},{"type":"table","caption":"川芎常见配伍与要点","head":["配伍","作用","要点"],"rows":[["川芎配白芷、羌活","祛风止痛、通络","用于风寒头痛、项背强痛"],["川芎配菊花、僵蚕","疏风清热、息风止痛","用于风热头痛、头痛目赤"],["川芎配当归、白芍","养血活血、调经止痛","用于血虚血瘀之月经不调、痛经"],["川芎配桃仁、红花","活血祛瘀、通脉止痛","为治血瘀诸痛之常用组合"]]},{"type":"quote","text":"主中风入脑头痛，寒痹筋挛缓急，金创，妇人血闭无子。","source":"《神农本草经·草部·芎䓖》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"川芎辛温升散，阴虚火旺、肝阳上亢、头痛目赤者不宜；月经过多、有出血倾向或正在使用抗凝血药（如华法林、阿司匹林）者慎用，因川芎嗪与阿魏酸能抑制血小板聚集，可能增加出血风险；孕妇慎用。服用过量可致剧烈头痛、呕吐、心悸、烦躁失眠或出现月经量增多，故不宜大量久服。含挥发油，入汤剂宜后下；其所扩张血管作用明显，高血压患者用药期间应监测血压变化，若出现头晕、心慌应减量或停用并咨询医师。"},{"type":"keypoints","title":"掌握要点","items":["活血行气、祛风止痛，为治头痛之要药","上行头目，外达皮毛","为妇科调经要药，气行则血行","阴虚火旺与出血倾向者慎用，含挥发油宜后下"]}]},{"id":"dan-shen","title":"丹参","subtitle":"Salviae Miltiorrhizae Radix et Rhizoma ｜ 丹参、紫丹参、赤参","category":"活血化瘀药","tags":["活血祛瘀","通经止痛","清心除烦","凉血消痈"],"meta":[{"label":"性味归经","value":"苦，微寒；归心、肝经"},{"label":"功效","value":"活血祛瘀，通经止痛，清心除烦，凉血消痈"},{"label":"主治","value":"胸痹心痛、脘腹胁痛、癥瘕积聚、热痹疼痛、疮疡肿痛、心烦不眠、月经不调、经闭痛经"},{"label":"用法用量","value":"煎服 10–15 g"},{"label":"使用注意","value":"十八反，与藜芦相反不可同用；不宜与牛奶同服；与抗凝药同用需谨慎"}],"image":"","imageHint":"丹参","summary":"丹参为唇形科植物丹参 Salvia miltiorrhiza Bge. 的干燥根和根茎，春秋二季采挖，除去泥沙与须根，晒干，商品以根条粗壮、色紫红或棕红、油润、断面黄棕者为佳，主产于江苏、山东、河北、四川等地。其味苦而性微寒，归心、肝经，能活血祛瘀、通经止痛，为治血瘀诸痛之要药；又善清心除烦、凉血消痈，为胸痹心痛与心烦不眠之常用药。十八反中与藜芦相反，孕妇慎用。","blocks":[{"type":"paragraph","text":"丹参为唇形科植物丹参 Salvia miltiorrhiza Bge. 的干燥根和根茎。春秋二季采挖，除去泥沙与须根，晒干。商品以根条粗壮、色紫红或棕红、油润、断面黄棕、纤维性者为佳，主产于江苏、山东、河北、安徽、四川、山西等地，习称\"紫丹参\"；其形似人参而色红，故又名\"红参\"、\"赤参\"。炮制多生用或酒制，酒丹参能增强活血通经之力。其有效成分丹参酮类不耐热，久煎则析出沉淀，故入汤剂宜后下或久煎后另服。"},{"type":"paragraph","text":"丹参味苦而性微寒，主归心、肝经。苦能泄降、微寒清热，故能活血祛瘀、通经止痛，为治血瘀诸痛之要药，用于胸痹心痛、脘腹胁痛、癥瘕积聚、产后瘀阻腹痛、痛经经闭；其活血而不伤正，故久用而无妨，\"一味丹参功同四物\"之誉即由此而来；入心经又能清心除烦，用于热病烦躁神昏、心悸失眠；其凉血解毒、消痈之功用于热毒疮疡肿痛、咽喉肿痛。此外还能祛瘀生新、润燥通便。"},{"type":"paragraph","text":"现代研究显示丹参含丹参酮ⅡA、丹参素、丹酚酸B及原儿茶醛等，丹参酮ⅡA 与丹酚酸类能扩张冠脉、改善微循环、抑制血小板聚集与纤维化，临床用于冠心病心绞痛、缺血性脑卒中、动脉粥样硬化、肝纤维化及下肢深静脉血栓等疗效确切；丹参素有抗凝与改善血液流变学作用。配伍上，丹参配川芎、赤芍活血祛瘀治胸痹心痛，配黄连、栀子清心除烦治热病烦躁，配茵陈、栀子利湿退黄治湿热黄疸，配桃仁、红花治癥瘕积聚，配乳香、没药治跌打瘀痛，配三七、益母草治产后瘀阻。"},{"type":"table","caption":"丹参常见配伍与要点","head":["配伍","作用","要点"],"rows":[["丹参配川芎、赤芍","活血祛瘀、通脉止痛","为治胸痹心痛之常用组合"],["丹参配黄连、栀子","清心除烦、凉血解毒","用于热病烦躁、心悸失眠"],["丹参配桃仁、红花","活血化瘀、消癥散结","用于癥瘕积聚、瘀血疼痛"],["丹参配三七、益母草","活血祛瘀、通经止痛","用于产后瘀阻、痛经"]]},{"type":"quote","text":"主心腹邪气，肠鸣结热，癥瘕积聚，痹痛，益气。","source":"《神农本草经·草部·丹参》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"丹参与藜芦相反，十八反中\"诸参辛芍叛藜芦\"，临床严禁与藜芦同用；因其活血祛瘀，孕妇慎用，月经过多及有出血倾向者慎用；不宜与牛奶同服，因丹参酮类可与牛奶中的蛋白结合而影响吸收；与华法林、阿司匹林等抗凝血药同用时应告知医师并监测凝血指标，因丹参可增强其抗凝作用。长期服用有报道出现胃肠道不适、口干、乏力及个别肝酶升高，故应定期复查；出现皮疹、瘙痒等过敏表现应停用。"},{"type":"keypoints","title":"掌握要点","items":["活血祛瘀，为血瘀诸痛之要药","兼清心除烦、凉血消痈","活血而不伤正，可较久应用","十八反：反藜芦；不宜与牛奶同服"]}]},{"id":"hong-hua","title":"红花","subtitle":"Carthami Flos ｜ 红花、红蓝花、藏红花（西红花另属）","category":"活血化瘀药","tags":["活血通经","散瘀止痛","祛瘀生新"],"meta":[{"label":"性味归经","value":"辛，温；归心、肝经"},{"label":"功效","value":"活血通经，散瘀止痛"},{"label":"主治","value":"痛经、经闭、产后瘀阻、癥瘕痞块、胸痹心痛、瘀滞胁痛、跌打肿痛、疮疡肿痛"},{"label":"用法用量","value":"煎服 3–10 g"},{"label":"使用注意","value":"孕妇忌用；月经过多、有出血倾向者忌用；与抗凝血药同用需谨慎"}],"image":"","imageHint":"红花","summary":"红花为菊科植物红花 Carthamus tinctorius L. 的干燥花，夏季花序由黄变红时采收，除去杂质，晒干，商品以花色红鲜艳、质柔软、无杂质者为佳，主产于新疆、云南、河南、河北等地，产于新疆者习称\"新疆红花\"，油多色鲜质量最佳。其味辛而性温，归心、肝经，善活血通经、散瘀止痛，为治血瘀经闭痛经、胸痹心痛与跌打损伤之常用药，因其活血力强，孕妇忌用，月经过多者亦忌用。","blocks":[{"type":"paragraph","text":"红花为菊科植物红花 Carthamus tinctorius L. 的干燥花。夏季花序由黄变红时于清晨露水未干前采收，除去杂质，晒干。商品以花色红鲜艳、质柔软、无碎屑与杂质者为佳，主产于新疆、云南、河南、河北、山东、山西等地，产于新疆者习称\"新疆红花\"，因日照充足、含油量高而色泽鲜艳，为地道之品。药用部位为筒状花冠，采收时须除去苞片与杂质，入药多生用，研末吞服或入煎剂。"},{"type":"paragraph","text":"红花味辛而性温，主归心、肝经。辛能行散、温能通行，故能活血通经、散瘀止痛，为治血瘀经闭、痛经、产后瘀阻腹痛、癥瘕痞块之常用药；其活血通脉之功用于胸痹心痛、瘀滞胁痛；外用能消肿止痛，治跌打损伤、瘀肿疼痛与疮疡肿痛。因其活血化瘀之力较强，故对血瘀兼气滞者疗效尤佳，可与川芎、桃仁、当归等同用；惟孕妇忌用，月经过多及出血性疾病患者亦当忌用。"},{"type":"paragraph","text":"现代研究显示红花含红花黄色素、红花油、亚油酸、油酸及红花苷等，红花黄色素有扩张血管、降低血压、抑制血小板聚集与改善微循环作用，红花油可降低胆固醇、抗血栓，临床用于冠心病心绞痛、缺血性脑病、痛经、产后瘀阻、跌打损伤等疗效确切；其所含红花苷对子宫有兴奋作用，故孕妇禁用。配伍上，红花配桃仁、川芎活血祛瘀治瘀血疼痛，配当归、丹参养血活血治痛经，配柴胡、香附疏肝行气治胁痛，配黄芪、党参益气活血治气滞血瘀，配大黄、芒硝攻积导滞治瘀血内结。"},{"type":"table","caption":"红花常见配伍与要点","head":["配伍","作用","要点"],"rows":[["红花配桃仁、川芎","活血祛瘀、通经止痛","为治血瘀经闭痛经之常用组合"],["红花配当归、丹参","活血兼能养血、祛瘀生新","用于血虚血瘀之月经不调"],["红花配柴胡、香附","行气活血、疏肝止痛","用于气滞血瘀之胸胁疼痛"],["红花配黄芪、党参","益气活血、推陈致新","用于气虚血瘀、胸痹心痛"]]},{"type":"quote","text":"活血通经，散瘀止痛。用于经闭，痛经，产后瘀阻腹痛，胸痹心痛，瘀滞胁痛，跌打肿痛，疮疡肿痛。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"红花活血力强，孕妇忌用；月经过多、有出血倾向者及溃疡病出血期患者忌用；正在服用华法林、阿司匹林、氯吡格雷等抗血小板或抗凝血药者应避免合用，以防出血；本品可引起子宫收缩，哺乳期妇女亦应慎用。服用过量可致月经过多、出血、皮肤瘀点瘀斑、血压下降与头晕，故须严格控制剂量；体质虚弱者不宜大量应用。服药期间若出现明显出血倾向、剧烈头痛或视物模糊，应立即停用并就医。"},{"type":"keypoints","title":"掌握要点","items":["活血通经、散瘀止痛，治瘀血诸证","与川芎、桃仁为经典活血组合","孕妇忌用，月经过多者亦忌用","与抗凝血药同用需谨慎，出血倾向者禁用"]}]},{"id":"ma-qian-zi","title":"马钱子","subtitle":"Strychni Semen ｜ 马钱子、番木鳖、马前子","category":"活血化瘀药","tags":["散结消肿","通络止痛","祛风除湿"],"meta":[{"label":"性味归经","value":"苦，温；有大毒。归肝、脾经"},{"label":"功效","value":"散结消肿，通络止痛"},{"label":"主治","value":"风湿顽痹、麻木瘫痪、跌打损伤、痈疽肿痛、小儿麻痹后遗症、类风湿关节痛"},{"label":"用法用量","value":"炮制后入丸散，0.15–0.3 g；入汤剂宜先煎、久煎；外用适量"},{"label":"使用注意","value":"有大毒，不可过量或连续服用；孕妇禁用；肝肾功能不全者禁用；须严格控制剂量与疗程"}],"image":"","imageHint":"马钱","summary":"马钱子为马钱科植物马钱 Strychnos nux-vomica L. 的干燥成熟种子，冬季采收，除去果肉，洗净，晒干，商品以个大、饱满、灰绿色者为佳，主产于海南、广东、广西、云南等地，习称\"番木鳖\"。其味苦而性温，有大毒，归肝、脾经，能散结消肿、通络止痛，为治风湿顽痹、麻木瘫痪与跌打损伤之猛药，止痛作用强而确切。因含士的宁而有剧毒，孕妇、肝肾功能不全者禁用，剂量须严控。","blocks":[{"type":"paragraph","text":"马钱子为马钱科植物马钱 Strychnos nux-vomica L. 的干燥成熟种子，习称\"番木鳖\"。冬季果实成熟时采收，取出种子，除去果肉，洗净，晒干。商品以个大、饱满、灰绿色、质坚硬、无杂质的马钱为佳，主产于海南、广东、广西、云南、台湾等地，进口品称\"进口马钱\"。本品须经炮制后方可药用：生马钱子有大毒，砂烫或油炸炮制后毒性降低，临床多入丸散剂或煎剂，且必须严格控制剂量。"},{"type":"paragraph","text":"马钱子味苦而性温，有大毒，主归肝、脾经。苦能泄降、温能通行，其毒性成分能强烈兴奋中枢神经系统，故能散结消肿、通络止痛，为治风湿顽痹、麻木瘫痪、跌打损伤、痈疽肿痛之猛药，止痛作用强而迅速，尤宜于久痹入络、肢体麻木、屈伸不利之顽证；现代亦用于小儿麻痹后遗症、类风湿关节炎、坐骨神经痛等；外用可治痈疽肿毒、瘰疬。其散结消肿之力可用于痰核、瘰疬等。"},{"type":"paragraph","text":"现代研究显示马钱子含士的宁（番木鳖碱）、马钱子碱、α-、β-可待因等生物碱，士的宁能选择性兴奋脊髓延髓，能提高中枢神经反射兴奋性，故有明显镇痛、抗炎、兴奋神经与抗麻痹作用，临床用于风湿顽痹与小儿麻痹后遗症疗效确切；但治疗量与中毒量极为接近，故必须在严格控制下使用。配伍上，马钱子配川乌、草乌治风湿顽痹、跌打损伤，配乳香、没药治痈疽肿毒、跌打瘀痛，配黄芪、党参益气扶正以缓其毒，配延胡索增强止痛之力，制马钱子配甘草可减毒。"},{"type":"table","caption":"马钱子常见配伍与要点","head":["配伍","作用","要点"],"rows":[["马钱子配川乌、草乌","祛风除湿、通络止痛","用于风湿顽痹、麻木瘫痪"],["马钱子配乳香、没药","散结消肿、活血止痛","用于痈疽肿毒、跌打瘀痛"],["马钱子配黄芪、党参","益气扶正、缓和毒性","用于久痹体虚之证"],["制马钱子配甘草","减毒缓急","用于缓解本品之毒性反应"]]},{"type":"quote","text":"散结消肿，通络止痛。用于风湿顽痹，麻木瘫痪，跌打损伤，痈疽肿痛，小儿麻痹后遗症，类风湿关节痛。","source":"《中华人民共和国药典（2020 年版）一部》"},{"type":"callout","variant":"warning","title":"使用注意与不良反应","text":"马钱子有大毒，本品不属十八反十九畏之列，然所含士的宁毒性剧烈，治疗量与中毒量极为接近，用药安全全赖于严格剂量与规范监测。孕妇禁用；儿童、哺乳期妇女禁用；肝肾功能不全者、高血压、心脏病、癫痫、破伤风及精神病患者禁用；体虚、久病者慎用。内服须严格控制剂量，一般不超过 0.3 g，且须用炮制品，不宜连续服用超过数日；入汤剂须先煎、久煎以降低毒性。中毒表现为头晕、头痛、颈部强直、咽下困难、肌肉抽动、全身痉挛、角弓反张，严重者因呼吸肌痉挛而窒息死亡，一旦出现先兆须立即停药并急诊处理。本品必须由医师处方并在其监护下使用，切勿自行服用。"},{"type":"keypoints","title":"掌握要点","items":["散结消肿、通络止痛，为治顽痹之猛药","有大毒，治疗量与中毒量接近","孕妇、儿童、哺乳期妇女及肝肾功能不全者禁用","须用炮制品，剂量严控并先煎久煎"]}]}]}},"formulas":{"page":{"key":"formulas","title":"方剂大成","subtitle":"经方·时方·名方：组成、方义、临证化裁","description":"中医方剂学数据库：收录解表、清热、泻下、补益、和解、理气、化痰祛湿、理血、安神开窍、治风等各类经典方剂 36 首，详列组成剂量、配伍机理、加减化裁与禁忌。","lead":"方者，制也；剂者，调也。本辑收录历代经典方剂三十六首，从《伤寒论》经方到后世时方，每首均按出处、组成、用法、功用、主治、方义、配伍、加减、禁忌逐项拆解，便于按证索方、按药求义。临证运用仍当辨证而行，剂量轻重须遵医嘱。","type":"collection","icon":"fa fa-flask","items":[{"id":"mahuang-tang","title":"麻黄汤","subtitle":"《伤寒论》· 麻黄 桂枝 杏仁 炙甘草","category":"解表剂","tags":["辛温解表","宣肺平喘","风寒表实证"],"meta":[{"label":"出处","value":"《伤寒论》卷二·辨太阳病脉证并治"},{"label":"组成","value":"麻黄 9g（去节），桂枝 6g（去皮），杏仁 9g（去皮尖，炒），炙甘草 3g"},{"label":"用法","value":"水煎服，先煮麻黄去上沫，内诸药，温服，覆取微似汗"},{"label":"功用","value":"发汗解表，宣肺平喘"},{"label":"主治","value":"外感风寒表实证。恶寒发热，头身疼痛，无汗而喘，舌苔薄白，脉浮紧"}],"image":"","imageHint":"麻黄","summary":"麻黄汤为《伤寒论》辛温解表第一方，主治风寒束表、卫强营弱之表实证。方以麻黄为君，发汗解表兼宣肺平喘；桂枝为臣，解肌发表，助麻黄开腠发汗；杏仁为佐，降利肺气以止咳喘；炙甘草为使，调和诸药并缓麻桂峻烈。四药合用，发汗有力而不伤津液，宣肺定喘而不偏燥烈，故称发汗峻剂。临床以恶寒发热、无汗而喘、脉浮紧为使用眼目，多用于感冒、流感、急性支气管炎、支气管哮喘等属风寒束表、肺气失宣之证。","blocks":[{"type":"paragraph","text":"麻黄汤是后世辛温解表剂的鼻祖，《伤寒论》以其治太阳伤寒表实证，后世解表方多由此化裁，如麻黄杏仁甘草石膏汤、大青龙汤、麻黄附子细辛汤等，皆由此方加减而成。其证关键在于寒邪束表、腠理闭塞，卫阳被遏而营阴未泄，故见恶寒、发热、无汗、身疼；肺气失宣则喘；苔薄白、脉浮紧，一望便知。临床凡外感风寒而以「无汗而喘」为主症者，即可用之。"},{"type":"table","caption":"麻黄汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["麻黄（去节）","君：发汗解表，宣肺平喘，开腠理散风寒","9g"],["桂枝（去皮）","臣：解肌发表，温通卫阳，助麻黄发汗","6g"],["杏仁（去皮尖，炒）","佐：降利肺气，止咳平喘，兼润燥","9g"],["炙甘草","使：调和药性，缓麻桂峻烈之性，缓峻而不伤中","3g"]]},{"type":"paragraph","text":"本方配伍精妙，妙在「发汗」与「宣肺」并重。麻黄辛温，入肺与膀胱经，既开腠理、发汗散寒，又宣肺气以平喘，一药而两任君药之职；桂枝辛甘温润，善解肌发表、调和营卫，得麻黄则发汗力强，得甘草则辛温而不燥，二药相须为用，是为臣药。杏仁苦温降气，与麻黄一宣一降，恢复肺气宣降之节律，喘亦自平，是为佐药。炙甘草甘温，既补中益气以助汗源，又调和诸药，更能缓和麻黄、桂枝峻烈之性，使发汗有源而不伤正，是为使药。四药合用，麻黄得桂枝，发汗而不伤津；杏仁得麻黄，宣降相因而喘自止；甘草得甘缓之，发汗有度而不致过汗亡阳。全方发汗峻而中有制，故称「发汗峻剂」，其配伍层次分明，可为辛温解表法的范本。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"表寒较轻而喘甚者，加杏仁量或加石膏（麻黄杏仁甘草石膏汤）；表寒里热、无汗烦躁者加大青龙汤；体虚外感、汗出恶寒者不宜用麻黄汤，当改用桂枝汤或加减玉屏风散；兼夹湿邪、恶寒身重者，可合平胃散化裁。临床用于感冒、流行性感冒、急性支气管炎、支气管哮喘、流行性腮腺炎等属风寒束表、肺气不宣之证。用药要点：以汗出而不伤阳、不伤津为度，得汗即止，中病即减，不可令大汗淋漓。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"表虚自汗、外感风热、体虚外感、疮家、淋家、衄家、亡血家均忌用麻黄汤。表虚有汗者误投可致汗出亡阳；阴虚盗汗者误投则助火伤阴；心悸、失眠、高血压者用麻黄亦须谨慎。现代使用中，麻黄用量宜从小剂量起，体质虚弱者酌减，老人、儿童及心脏疾病患者尤宜慎之。若服药后汗出不止，宜立即停药并予益气敛汗之品。麻黄为发汗峻品，处方须由医师辨证把握，不可自行服用。"},{"type":"quote","text":"太阳病，头痛发热，身疼腰痛，骨节疼痛，恶风，无汗而喘者，麻黄汤主之。","source":"《伤寒论》卷二·辨太阳病脉证并治"},{"type":"keypoints","title":"掌握要点","items":["主治风寒表实证，核心指征是「无汗而喘、脉浮紧」，不可据汗出而投","麻黄为君，兼发汗与宣肺平喘；桂枝为臣，助其发汗而不燥津","杏仁一宣一降，炙甘草调和并缓和峻烈，全方发汗有度","得汗即止，中病即减；表虚自汗、风热、阴虚者严禁使用"]}]},{"id":"guizhi-tang","title":"桂枝汤","subtitle":"《伤寒论》· 桂枝 白芍 生姜 大枣 炙甘草","category":"解表剂","tags":["解肌发表","调和营卫","风寒表虚证"],"meta":[{"label":"出处","value":"《伤寒论》卷二·辨太阳病脉证并治"},{"label":"组成","value":"桂枝 9g，白芍 9g，生姜 9g，大枣 4 枚，炙甘草 6g"},{"label":"用法","value":"水煎服，服后啜热稀粥一碗，温覆令一时许，遍身漐漐微似有汗者益佳"},{"label":"功用","value":"解肌发表，调和营卫"},{"label":"主治","value":"外感风寒表虚证。头痛发热，汗出恶风，鼻鸣干呕，苔白不渴，脉浮缓或浮弱"}],"image":"","imageHint":"桂枝","summary":"桂枝汤为《伤寒论》解肌发表、调和营卫之代表方，主治风寒在表、卫强营弱之表虚证。桂枝辛温，解肌发表、调和营卫为君；白芍酸苦微寒，养血敛阴，桂芍等量相配，一散一收，使汗出而不伤阴，为臣；生姜、大枣益气和中、调和营卫，助桂枝解肌，为佐；炙甘草调和诸药，合桂枝辛甘化阳、合芍药酸甘化阴，为使。全方五味，缓中有峻，被称「群方之魁」。临床广泛用于感冒、流感、产后或病后低热、自汗、荨麻疹、多形红斑等属营卫不和者。","blocks":[{"type":"paragraph","text":"桂枝汤与麻黄汤同为辛温解表剂，然麻黄汤用于表实无汗，桂枝汤用于表虚有汗，二者一攻一补，分工井然。仲景以「荣卫不和」概括本方证病机：风寒客于肌表，卫阳浮盛而欲外泄，营阴不足而不能内守，营卫相搏，故见发热、汗出、恶风、脉浮缓。治疗当以辛温之品解肌祛邪，酸甘之味和营敛阴，调和营卫则汗自止而邪自解。"},{"type":"table","caption":"桂枝汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["桂枝","君：解肌发表，温通卫阳，调和营卫，为群方之魁","9g"],["白芍","臣：养血敛阴，缓急止痛，与桂枝一散一收调和营卫","9g"],["生姜","佐：助桂枝辛散表邪，兼和胃止呕","9g"],["大枣","佐：益气养血，助卫阳固表，合生姜调和脾胃","4 枚"],["炙甘草","使：调和诸药，合桂枝辛甘化阳、合芍药酸甘化阴","6g"]]},{"type":"paragraph","text":"桂枝汤配伍之妙，首在桂芍对用。桂枝辛甘温，走卫分而发汗解肌；白芍酸苦微寒，入营分而养血敛阴。桂芍等量，一散一收，散中有收，则发汗而不伤营阴；收中有散，则敛阴而不留邪。营卫和则腠理开合有度，故汗出而热退，恶风自除。次在姜枣与甘草相配。生姜辛温，助桂枝之力以散风寒，又和胃止呕；大枣甘温，益气养血以固表，合生姜调和营卫；炙甘草甘温益气，调和药性，既与桂枝相合辛甘化阳以助卫阳，又与芍药相合酸甘化阴以养营阴，一味而兼两用。全方五味，三味辛甘、两味酸甘，散中有收、温中有润，故发汗而不伤阳，养阴而不碍邪，服后遍身微汗，邪随汗解而营卫自和，充分体现「调和营卫」治法。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"表虚自汗明显者加黄芪（桂枝加黄芪汤）；久病营卫不和、时发热自汗者，去生姜大枣，加黄芪、白术、防风（桂枝加黄芪汤）；营卫不和兼血虚者合四物汤；喘者加厚朴、杏仁；漏下不止者合补中益气汤；胃脘虚寒而痛者合小建中汤。临床用于感冒、流行性感冒、自汗症、产后或病后低热、荨麻疹、多形红斑、冻疮、荨麻疹、神经性皮炎等属营卫不和者。服法讲究「啜热稀粥、温覆取微汗」，不可大汗淋漓。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"表实无汗、温病初起、里热炽盛、阴虚火旺、酒客湿热、疮家、淋家、衄家、亡血家均忌用。本方须以有汗、恶风、脉浮缓为使用依据，若见高热烦渴、咽痛口苦、舌红苔黄、脉数有力，属风热或里热，当改用辛凉解表或清里之剂，切不可误投。服药期间忌生冷黏滑酒酪臭恶等物。孕妇及病后体虚者用量宜轻，发热汗多者服后须注意补充水分与静养。"},{"type":"quote","text":"太阳病，头痛发热，汗出而恶风者，桂枝汤主之。","source":"《伤寒论》卷二·辨太阳病脉证并治"},{"type":"keypoints","title":"掌握要点","items":["主治营卫不和之表虚证，眼目在「汗出恶风、脉浮缓」","桂芍等量为君臣，散中有收，汗出而不伤营阴","姜枣甘草调脾胃、助卫阳，炙甘草兼辛甘化阳、酸甘化阴","服后啜热稀粥、温覆取微汗，不可令大汗；表实者不可用"]}]},{"id":"yinqiao-san","title":"银翘散","subtitle":"《温病条辨》· 金银花 连翘 桔梗 薄荷 竹叶 甘草 荆芥 淡豆豉 芦根","category":"解表剂","tags":["辛凉解表","清热解毒","风温初起"],"meta":[{"label":"出处","value":"《温病条辨》卷一·上焦篇"},{"label":"组成","value":"连翘 9g，金银花 9g，苦桔梗 6g，薄荷 6g，竹叶 4g，生甘草 5g，荆芥穗 5g，淡豆豉 5g，芦根 15g"},{"label":"用法","value":"上杵为散，每服 9g，鲜苇根汤煎，香气大出即取服，勿过煮"},{"label":"功用","value":"辛凉透表，清热解毒"},{"label":"主治","value":"温病初起。发热无汗或有汗不畅，微恶风寒，头痛口渴，咳嗽咽痛，舌尖红苔薄白或薄黄，脉浮数"}],"image":"","imageHint":"银翘","summary":"银翘散为《温病条辨》辛凉平剂，主治温病初起、风热在卫之证。方以金银花、连翘为君，辛凉透表、清热解毒；桔梗、防风、薄荷、竹叶、荆芥穗、淡豆豉为臣，疏散风热、宣肺利咽；芦根清热生津，桔梗宣肺，甘草清热解毒调和诸药为佐使。全方辛凉轻清，疏卫透邪而不伤津清热而不遏邪，被称「辛凉平剂」，为治温病初起的代表方。临床广泛用于流感、急性上呼吸道感染、急性扁桃体炎、流行性腮腺炎、麻疹初起等属风热表证者。","blocks":[{"type":"paragraph","text":"温病初起，邪在卫分，卫气郁闭，肺失宣肃，故发热、微恶风寒、咳嗽咽痛；温邪易化燥伤津，故口渴；舌尖红苔薄白或薄黄、脉浮数，为风热在表之征。治当辛凉透表，兼以清热解毒，切不可辛温发汗助热，更不可苦寒直折遏邪外出。银翘散全方气味轻清，宣散透达，取「治上焦如羽，非轻不举」之意。"},{"type":"table","caption":"银翘散君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["金银花","君：辛凉透表，清热解毒，轻清芳烈以透邪外出","9g"],["连翘","君：清热解毒，透散上焦风热，兼利咽","9g"],["薄荷、竹叶","臣：疏散风热，清上焦之热，兼清利头目","各 4～6g"],["荆芥穗、淡豆豉","臣：辛散透邪，助君药开皮毛而逐温邪","各 5g"],["桔梗","佐：宣肺利咽止咳，引药上达于咽喉","6g"],["芦根","佐：清热生津止渴，兼透邪外出","15g"],["生甘草","使：清热解毒，调和诸药","5g"]]},{"type":"paragraph","text":"银翘散以金银花、连翘为君，二者皆能清热解毒而气味轻清，金银花偏于清透，凉而不凝，连翘偏于疏散，苦而不泄，相须为用则清热解毒之力倍，而又无苦寒冰伏之弊。臣以薄荷、竹叶，轻扬宣散上焦风热；荆芥穗、淡豆豉辛而微温，助君药从皮毛疏散温邪，虽属辛温而不助热，此正是吴鞠通「辛温变辛凉」之意。桔梗宣肺利咽，引药上趋；芦根清热生津，照顾温病易伤津液之弊；生甘草清热解毒而调和诸药。综观全方，辛凉之中寓辛散，透邪而不伤津，清热而不遏邪，宣上焦而利气化，配伍 embodies 「轻清宣气」之法，故列于治温诸方之首。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"咽痛甚者加大青叶、玄参、板蓝根；咳嗽痰黄者加杏仁、浙贝母、黄芩；热甚口渴加天花粉、芦根用量；项肿咽痛加大青叶、僵蚕、玄参；麻疹初起透发不畅加蝉蜕、葛根、升麻；欲增强清热解毒之力，加黄芩、板蓝根（银翘解毒汤）。临床用于流行性感冒、急性上呼吸道感染、急性扁桃体炎、流行性腮腺炎、麻疹初起、急性支气管炎等属温病初起、邪在卫分者。煎煮与服用宜遵「香气大出即取，勿过煮」，久煎则药性轻散而失效。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方为辛凉轻剂，只适用于风热、温邪在表之证。若高热持续不退、汗出热不解、口渴引饮、舌红苔黄、脉洪数，为邪入气分，不得再用；恶寒无汗、舌淡苔白、脉浮紧之风寒表证，误服则寒上加凉，徒伤阳气。体虚、脾胃虚寒者慎用，因本方多芳香轻散，易动胃气，出现纳呆、便溏者当停药调理。服药期间忌食辛辣炙煿油腻之品，慎用酒类。"},{"type":"quote","text":"太阴风温、温热、温疫、冬温，初起但热不恶寒而渴者，辛凉平剂银翘散主之。","source":"《温病条辨》卷一·上焦篇"},{"type":"keypoints","title":"掌握要点","items":["辛凉平剂，主治温病初起邪在卫分，症见发热、微恶风寒、口渴咽痛","金银花、连翘为君，轻清透表清热，辛凉而不苦寒、不遏邪","荆芥、淡豆豉辛温助散皮毛之邪，芦根顾护津液","「香气大出即取，勿过煮」；气分热盛、表寒及脾胃虚寒者不可用"]}]},{"id":"sangju-yin","title":"桑菊饮","subtitle":"《温病条辨》· 桑叶 菊花 杏仁 连翘 薄荷 桔梗 甘草 苇根","category":"解表剂","tags":["辛凉解表","疏风清热","宣肺止咳"],"meta":[{"label":"出处","value":"《温病条辨》卷一·上焦篇"},{"label":"组成","value":"桑叶 8g，菊花 3g，杏仁 9g，连翘 6g，薄荷 3g，桔梗 6g，生甘草 3g，苇根 3g"},{"label":"用法","value":"水二杯煮取一杯，日二服；病重者日三服，夜一服"},{"label":"功用","value":"疏风清热，宣肺止咳"},{"label":"主治","value":"风温初起，表热轻证。但咳，身热不甚，口微渴，脉浮数，舌苔薄白"}],"image":"","imageHint":"桑菊","summary":"桑菊饮为《温病条辨》辛凉轻剂，主治风温初起、表热轻证而以咳嗽为主症者。方中桑叶、菊花为君，疏散风热、清利头目；杏仁、桔梗为臣，宣肺止咳；连翘、薄荷、竹叶、苇根、甘草为佐使，疏风清热、生津利咽。全方药味轻清，用量极小，宣散之力不及银翘散而肃肺之功过之，体现「辛凉轻剂」之制。临床用于急性上呼吸道感染、急性支气管炎、流行性感冒、麻疹初起等属风热犯肺、咳嗽为主者，尤其适合体虚、儿童及不愿苦寒者。","blocks":[{"type":"paragraph","text":"风温初起，邪在肺卫，肺失清肃，故但咳为主而身热不甚、口微渴；风热轻袭，故恶风不著，脉浮数。治当疏风清热、宣肺止咳，既不可因咳而用苦寒沉降，也不可因热而用辛温发汗。桑菊饮以轻清宣透之品，宣散肺经风热而不伤津，故称「辛凉轻剂」，与银翘散辛凉平剂相为呼应而功力稍缓。"},{"type":"table","caption":"桑菊饮君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["桑叶","君：疏散风热，清肺润燥，宣肺止咳，为治风温咳嗽之要药","8g"],["菊花","君：疏散风热，清利头目，助桑叶清肺","3g"],["杏仁","臣：宣降肺气，止咳平喘，苦降以泄肺热","9g"],["桔梗","臣：宣肺利咽，祛痰利气，载药上达","6g"],["连翘、薄荷","佐：疏散风热，清热解毒，透邪外出","各 3～6g"],["苇根","佐：清热生津，止渴清热","3g"],["生甘草","使：清热解毒，调和诸药，兼利咽喉","3g"]]},{"type":"paragraph","text":"本方配伍以「轻」为要。君用桑叶、菊花，二者甘苦微寒而气清轻上扬，桑叶偏于清肺、菊花偏于疏风清热并利头目，合用则疏解在表之风热而不伤肺阴。臣以杏仁、桔梗，一苦降、一宣升，杏仁降肺气以止咳，桔梗开肺气以宣肺，一降一升，使肺气宣降得宜而咳嗽自止；桔梗又能载药上行，使轻清之品直达病所。佐以连翘清热解毒、薄荷疏散余邪、苇根清热生津，照顾温邪易化燥伤津之患。使以甘草清热解毒、调和诸药，兼利咽喉。综观全方，药味平淡而量极小，桑叶、菊花、薄荷、苇根皆轻扬之品，正合「治上焦如羽，非轻不举」之旨；全方集疏风、清热、宣肺、止咳于一身而无苦寒沉降之弊，故为风温咳嗽之良方。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"咳甚者加浙贝母、枇杷叶、前胡；痰黄黏稠加黄芩、瓜蒌皮、浙贝母；咽痛明显加牛蒡子、玄参、射干；热重口渴加芦根、天花粉；目赤肿痛加大黄牡丹皮（肝火上炎者）；久咳肺虚加沙参、麦冬、川贝母（沙参麦冬汤意）。临床用于急性上呼吸道感染、急性支气管炎、流行性感冒、麻疹初起、小儿外感咳嗽等属风热犯肺而以咳为主者。因药性轻缓，小儿及病后体虚者尤为适宜。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方药轻力缓，只宜于风热轻证。若咳嗽痰黄稠、发热较重、口渴引饮、舌红苔黄、脉数有力，属肺热炽盛，须改用清肺化痰之剂；若咳嗽痰白清稀、畏寒无汗、舌淡苔白，属风寒束肺，则当改用辛温宣肺之品，不可泥于「咳嗽皆热」而误投。脾胃虚寒、大便溏泄者慎用，因本方多甘寒轻散，易碍脾运。哺乳期妇女及婴幼儿用药宜在医师指导下调整剂量。"},{"type":"quote","text":"太阴风温，但咳，身不甚热，微渴者，辛凉轻剂桑菊饮主之。","source":"《温病条辨》卷一·上焦篇"},{"type":"keypoints","title":"掌握要点","items":["辛凉轻剂，主治风温初起「但咳、身热不甚、微渴」","桑叶、菊花为君轻清疏散，杏仁、桔梗一降一升宣肺止咳","用量极小，药性平淡，不伤津、不苦寒，尤宜小儿与体虚者","咳嗽热重须转清肺，寒咳则当改辛温，不可一概而论"]}]},{"id":"baihu-tang","title":"白虎汤","subtitle":"《伤寒论》· 石膏 知母 粳米 炙甘草","category":"清热剂","tags":["清热生津","辛凉重剂","气分热盛"],"meta":[{"label":"出处","value":"《伤寒论》卷二、卷三·辨太阳阳明病脉证并治"},{"label":"组成","value":"生石膏 50g（打碎先煎），知母 18g，粳米 9g，炙甘草 6g"},{"label":"用法","value":"水煎服，米熟汤成，去滓温服，日三服"},{"label":"功用","value":"清热生津"},{"label":"主治","value":"阳明气分热盛证。壮热面赤，烦渴引饮，汗出恶热，脉洪大有力；或气虚发热，烦渴欲饮，脉洪大而虚"}],"image":"","imageHint":"白虎","summary":"白虎汤为《伤寒论》清阳明气分热盛之辛凉重剂。方以生石膏为君，辛甘大寒，清热泻火除烦；知母为臣，辛润苦寒，滋阴清热，助石膏清肺胃之热；粳米、炙甘草为佐使，益胃生津防大寒伤中。全方辛寒清热而不伤津，甘寒生津而不恋邪，「辛寒清气，甘寒生津」，配伍严谨，为治气分热盛之代表方，临床亦用于大叶性肺炎、流行性乙型脑炎、中暑、糖尿病、牙龈炎等属气分热盛者。","blocks":[{"type":"paragraph","text":"阳明气分热盛，蒸腾于外，故壮热面赤、汗出恶热；热盛伤津，故烦渴引饮、脉洪大；此为「四大症」——大热、大汗、大渴、脉洪大。若兼气虚而汗多、脉虽洪大而按之无力者，当加人参益气生津，名白虎加人参汤，仍以本方为基本结构。"},{"type":"table","caption":"白虎汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["生石膏（打碎先煎）","君：辛甘大寒，清热泻火，除烦止渴","50g"],["知母","臣：苦寒滋阴清热，助石膏清肺胃气分之热","18g"],["粳米","佐：益胃生津，防大寒药物伤中，兼助药力","9g"],["炙甘草","使：清热解毒、益气和中，调和诸药","6g"]]},{"type":"paragraph","text":"本方用石膏不用寒水石、犀角，取其辛甘大寒而质重气浮，直入阳明气分，荡涤无形之热。石膏辛能解肌，甘能缓中，大寒能清热泻火，故为君药，然其性大寒，单用则伤胃气。知母苦寒质润，为「水之questions」——上能清肺胃之热，下能滋肾阴之虚，且质润不燥，与石膏相须为用，一清一润，清解之力愈强，共为臣药。粳米甘平，益胃生津，且能制约石膏、知母之寒凉，使邪热去而胃气存；炙甘草甘温，益气和中，调和诸药，二药相合为佐使。综观全方，辛寒与甘寒相配：辛寒清热，甘寒生津；苦寒与甘平相伍：苦寒直折里热，甘平顾护中焦。故本方清热而不伤津、生津而不恋邪，恰合阳明气分热盛「外有假寒、内有真热」之机，为清气分热的典范配伍。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"气津两伤、汗多脉大而虚者，加人参（白虎加人参汤）；热盛动风、痉厥抽搐者加羚羊角、钩藤；热入营血、发斑出血者合犀角地黄汤；气阴两虚、久病后期加生地、麦冬、玄参；关节热痛、红肿者合宣痹汤；糖尿病口渴引饮、气分热盛者加天花粉、生地、葛粉。临床用于大叶性肺炎、流行性乙型脑炎、流行性出血热、中暑、产后高热、牙龈炎、糖尿病等属阳明气分热盛者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方大寒，若表证未解、无汗恶寒、脉浮而细或沉者不可用；血虚发热、脉洪不胜重按、舌绛而干、暮热早凉、脉数而细，属营血热或阴虚者，误投则苦寒伤阴，危重者可致厥脱；真寒假热、阴盛格阳之四肢厥冷、脉微欲绝者大忌。脾胃虚寒、脾阳不振之纳呆便溏者慎用。石膏须打碎先煎，且用量宜大（可用至 60g 以上）方能见效，但必须以气分热盛为使用前提。孕妇及体弱者当由医师审慎掌握。"},{"type":"quote","text":"伤寒脉浮滑，此以表有热，里有寒，白虎汤主之。","source":"《伤寒论》卷二·辨太阳阳明病脉证并治"},{"type":"keypoints","title":"掌握要点","items":["辛凉重剂，主治阳明气分热盛，四大症为大热、大汗、大渴、脉洪大","石膏为君清热泻火，知母为臣滋阴清热，辛寒配甘寒","粳米、甘草益胃护中，清热不伤津、生津不恋邪","表证未解、营血热、阴虚、真寒假热者禁用或慎用"]}]},{"id":"huanglian-jiedu-tang","title":"黄连解毒汤","subtitle":"《外台秘要》引崔氏方 · 黄连 黄芩 黄柏 栀子","category":"清热剂","tags":["泻火解毒","清热燥湿","三焦热毒"],"meta":[{"label":"出处","value":"《外台秘要》卷十五引崔氏方（后载于《医方集解》"},{"label":"组成","value":"黄连 9g，黄芩 6g，黄柏 6g，栀子 9g"},{"label":"用法","value":"水煎服，一日分二服"},{"label":"功用","value":"泻火解毒，清热燥湿"},{"label":"主治","value":"三焦火毒热盛证。大热烦躁，口燥咽干，错语不眠；或热病吐血衄血；或热甚发斑；或热毒下利；或湿热黄疸，舌红苔黄，脉数有力"}],"image":"","imageHint":"黄连","summary":"黄连解毒汤为治三焦火毒热盛之峻剂。方以黄连为君，泻心胃之火兼燥湿；黄芩、黄柏为臣，分别清上焦肺火与下焦湿热；栀子为使，泻三焦之火，导热下行并使二便。全方苦寒直折，苦能燥湿、寒能清热，四药上下分治而无重复，合为泻火解毒之峻剂。临床用于败血症、细菌性痢疾、肺炎、急性胆囊炎、流行性脑脊髓膜炎、钩端螺旋体病、急性肾盂肾炎等属火毒炽盛或湿热并重者。因苦寒极甚，非实火不可轻投。","blocks":[{"type":"paragraph","text":"本方证为三焦火毒炽盛，上、中、下三焦俱热。心火上炎则烦躁不眠、错语；肺热则咳喘、痰黄；胃火炽盛则口燥咽干、呕吐吞酸；下焦湿热则下利、黄疸、溺赤；热迫血行则吐血衄血、便血、发斑；热郁肌肤则疮疡肿毒。舌红苔黄或黄燥、脉数有力，为其主要辨证依据。"},{"type":"table","caption":"黄连解毒汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["黄连","君：泻心胃之火，燥湿解毒，为治火毒要药","9g"],["黄芩","臣：清上焦肺火及少阳胆热，燥湿","6g"],["黄柏","臣：泻下焦湿热，治疮疡带下","6g"],["栀子","使：泻三焦之火，导热下行，兼利二便使邪有出路","9g"]]},{"type":"paragraph","text":"本方四药皆苦寒，然各有所司，绝无重复之弊。黄连苦寒沉降，善泻心经之火、胃腑之热，兼能燥湿，为君，直折上、中二焦之火。黄芩清肺热、泻胆火，善清上焦；黄柏泻肾与膀胱之湿热，专清下焦。二药与黄连同为臣，三味合用，上、中、下三焦火毒尽在掌握之中，而又各有专长，分工明确，不使一药而三处用之，诚为立方之妙。栀子苦寒清降，泻火除烦，利湿凉血，其性滑利，能导热下行从小便而出，故为使。综观全方：君一、臣二、使一，配伍层次分明；苦寒直折而不用硝黄峻下，故热毒可解而腑气不伤；燥湿而不伤阴，养津而不碍邪。以三焦俱实、火毒炽盛为使用之唯一前提，非实火不可轻投，此正是本方配伍之要旨。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"火毒炽盛而发斑者加生地、玄参、丹皮、犀角（犀角地黄汤）；热毒蕴结咽喉加玄参、桔梗、板蓝根；湿热黄疸加茵陈、郁金、大黄；热毒下利里急后重加木香、白头翁；疮疡肿毒加蒲公英、紫花地丁；热盛动风加钩藤、羚羊角；血热妄行加白茅根、小蓟。临床用于败血症、细菌性痢疾、肺炎、流行性脑脊髓膜炎、急性胆囊炎、钩端螺旋体病、急性肾盂肾炎、急性盆腔炎等属火毒炽盛或三焦湿热者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方苦寒峻剂，非火毒炽盛、三焦俱实者不可轻投。脾胃虚寒、阳气衰微、食少便溏者用之则中阳更伤；阴虚火旺而无湿热、舌红少苔者误投则苦燥伤阴；孕妇、产后、气血虚亏者当慎。大便秘结而津液已伤者不可专任苦寒，应配伍增液行舟之法。服药期间忌食辛辣炙煿及酒酪之品。本方剂量偏大且苦寒败胃，疗程宜短，中病即减，不可久服。"},{"type":"quote","text":"黄连解毒柏连芩，栀子大黄甘草金，热狂三焦火热盛，烦躁谵语吐衄侵。","source":"《医方集解·黄连解毒汤》"},{"type":"keypoints","title":"掌握要点","items":["治三焦火毒热盛之峻剂，黄连为君、黄芩黄柏为臣、栀子为使","上中下三焦分治而不重复，导热下行从小便而出","辨证要点为大热烦躁、口燥咽干、舌红苔黄、脉数有力","苦寒峻剂，非实火不可轻投，脾胃虚寒、阴虚者禁服，中病即减"]}]},{"id":"daochi-san","title":"导赤散","subtitle":"《小儿药证直诀》· 生地黄 木通 生甘草梢 竹叶","category":"清热剂","tags":["清心利水","导热下行","心火上炎"],"meta":[{"label":"出处","value":"《小儿药证直诀》卷下·诸方（钱乙）"},{"label":"组成","value":"生地黄 6g，木通 6g，生甘草梢 6g，竹叶 6g（加灯心草同煎）"},{"label":"用法","value":"上为末，每服 3g，水一盏，入竹叶同煎至五分，食后温服"},{"label":"功用","value":"清心利水养阴"},{"label":"主治","value":"心经热盛证。心胸烦热，口渴面赤，意欲饮冷，口舌生疮；或心热移于小肠，小便赤涩刺痛，舌红，脉数"}],"image":"","imageHint":"导赤","summary":"导赤散为《小儿药证直诀》治心经热盛之剂。方以生地黄为君，清热凉血养阴；木通为臣，清心降火、利小便，使心火从小便而出；生甘草梢为佐清热解毒、兼降火利咽；竹叶清心除烦、通利小便为使。全方甘寒清热而不伤阴，利水导热而不伤津，「上清心火，下利小肠」，寓清热利水于导引之中。临床用于口腔溃疡、疱疹性口炎、急性泌尿道感染、小儿夜啼、神经性口炎等属心火上炎或心火移于小肠者。","blocks":[{"type":"paragraph","text":"心主神明、属火而通于舌，心火上炎则心胸烦热、口渴面赤、口舌生疮；心与小肠相表里，心火下移小肠则小便赤涩刺痛。此证之病机为心经热盛，治当清心火、利小肠，使热从下行而有出路，故名「导赤」。钱乙立此方于小儿，盖小儿心常有余、肝常有余而脾常不足，心火上炎者尤多。"},{"type":"table","caption":"导赤散君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["生地黄","君：清热凉血，养阴生津，制清热药之燥","6g"],["木通","臣：清心降火，利小便，使心火从小便而出","6g"],["生甘草梢","佐：清热解毒，降火利咽，兼调和诸药","6g"],["竹叶（加灯心草）","使：清心除烦，通利小便，引热下行","6g"]]},{"type":"paragraph","text":"本方配伍精义在「以水导火」四字。生地黄甘苦寒凉，质润而不腻，既清心火、凉血解毒，又养阴生津，与木通、竹叶等渗利之品同用，可制其利水伤阴之弊，故以为君，直折心经之热。木通苦寒，清心降火，利小便通导心火下泄，为臣；其与生地相配，一清血分之热，一导火从小便而出，使邪有出路而非壅郁于上。生甘草梢甘寒偏凉，清热解毒，降火利咽，并能缓木通、竹叶之峻利为佐。竹叶清心除烦、利尿通淋，为使，与木通相须，使心火从二便分消。综观全方：生地、木通，一清一利；竹叶、甘草梢，一淡一缓；清热而不苦燥，导热而不伤阴，利水而不伤津。全方仅四味而环环相扣，故能「上清心火，下利小肠」，为清心利水的经典方。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"口舌生疮甚者加黄连、连翘、板蓝根；小便赤涩刺痛加滑石、车前子、瞿麦；血尿加白茅根、小蓟；心烦不寐加黄连、栀子、莲子心；小儿夜啼加蝉蜕、钩藤；阴虚口疮、舌红少苔者加麦冬、知母、玄参。临床用于口腔溃疡、疱疹性口炎、急性口炎、急性泌尿道感染、泌尿系结石、小儿夜啼、神经性口炎、手足口病等属心火上炎或心火移于小肠者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方所治为「实火」，若口舌生疮而舌淡苔白、脉沉迟，属虚火上浮、脾胃虚寒者不可用，误投则寒凉伤胃、便溏不止；小便清长而频数、畏寒肢冷者禁用。木通品种较多，关木通含马兜铃酸，有肾毒性，临床必须使用川木通或以通草、车前子等安全之品替代，严禁使用关木通及含马兜铃酸的中药材。脾胃虚寒者慎用，剂量亦不宜过大，症状缓解后应即停。"},{"type":"quote","text":"治小儿心热，视其睡，口中气温，或合面睡及上窜切牙，皆心热也。","source":"《小儿药证直诀》卷下·诸方"},{"type":"keypoints","title":"掌握要点","items":["清心利水养阴，治心火上炎及心火移于小肠之证","生地为君清心养阴，木通为臣利尿导热下行，竹叶、甘草梢为佐使","配伍特点：清热不燥、导热不伤阴，利水不伤津","只治实火，虚火上浮与脾胃虚寒者禁用；木通须用川木通，忌关木通"]}]},{"id":"longdan-xiegan-tang","title":"龙胆泻肝汤","subtitle":"《医方集解》· 龙胆草 黄芩 栀子 泽泻 木通 车前子 当归 生地 柴胡 甘草","category":"清热剂","tags":["清泻肝胆实火","清利肝经湿热","带下阴痒"],"meta":[{"label":"出处","value":"《医方集解》卷四（源自李东垣方意，后世定型）"},{"label":"组成","value":"龙胆草 6g，黄芩 9g，栀子 9g，泽泻 12g，木通 6g，车前子 9g，当归 3g，生地黄 9g，柴胡 6g，生甘草 6g"},{"label":"用法","value":"水煎服，日二服"},{"label":"功用","value":"清泻肝胆实火，清利肝经湿热"},{"label":"主治","value":"肝胆实火上炎证：头痛目赤，胁痛口苦，耳聋耳肿；或肝经湿热下注：阴肿阴痒，筋痿溲浊，妇女带下黄臭，舌红苔黄腻，脉弦数有力"}],"image":"","imageHint":"龙胆","summary":"龙胆泻肝汤为清泻肝胆实火、清利肝经湿热之代表方。方以龙胆草为君，直泻肝胆之火，清下焦湿热；黄芩、栀子为臣，清热泻火燥湿；泽泻、木通、车前子为佐，清利湿热使邪从小便而去；生地、当归养血滋阴，防苦燥伤阴；柴胡引经，甘草调和为使。全方泻中有补，利中有养，祛邪而不伤正，为「泻肝火、导湿热」之良方。临床用于急性结膜炎、急性中耳炎、急性肝炎、胆囊炎、胰腺炎、泌尿系感染、前列腺炎、阴痒带下等属肝胆实火或肝经湿热者。","blocks":[{"type":"paragraph","text":"肝胆实火循经上炎，则头痛目赤、口苦胁痛、耳聋耳肿；肝经湿热循下焦下注，则阴肿阴痒、筋痿溲浊、妇女带下黄臭。二者虽上下不同，病机则一，皆肝胆之火挟湿热为患。治当清泻肝胆实火，清利肝经湿热，使湿热从小便分消，方中龙胆草苦寒大清肝胆之火并下泄湿热，为全方核心。"},{"type":"table","caption":"龙胆泻肝汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["龙胆草","君：泻肝胆实火，清下焦湿热","6g"],["黄芩、栀子","臣：清热泻火燥湿，助君药清上中二焦之热","各 9g"],["泽泻、木通、车前子","佐：清利湿热，使湿热从小便而出","12g／6g／9g"],["生地黄、当归","佐：养血滋阴，防苦燥伤阴耗血","9g／3g"],["柴胡","使：疏肝解郁，引诸药入肝胆经","6g"],["生甘草","使：清热解毒，调和诸药","6g"]]},{"type":"paragraph","text":"本方配伍之妙在「泻火与利湿并用，清利与滋养相兼」。龙胆草苦寒沉降，既上清肝胆实火，又下泻肝经湿热，一药而两擅其长，故为君药。黄芩清肺与胆之热，栀子泻三焦之火并燥湿，二药为臣，助君药加强清热泻火燥湿之力，共成上、中、下三焦并治之局。泽泻、木通、车前子淡渗利湿，使湿热从小便而去，所谓「使邪有出路」，此三药为佐。生地黄滋阴凉血，当归养血活血，二药虽为佐制，却极关紧要：本方苦寒走泄之品众多，得此二味则邪去而阴血不伤，泻火而不至于燥烈。柴胡疏肝解郁，并能引归、芍等药入肝经，为使；甘草清热解毒、调和诸药，亦为使。综观全方，泻中有补，利中有养，降中寓升，祛邪而不伤正，正合肝胆实火兼湿热者复杂之证。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"肝火上炎头痛目赤加菊花、决明子；耳聋耳肿加菖蒲、磁石；胁痛加川楝子、郁金；湿热带下加黄柏、椿根皮、土茯苓；阴肿阴痒加苦参、蛇床子；泌尿系感染加萹蓄、瞿麦；急性肝炎加茵陈、栀子、大黄；胆囊炎加郁金、姜黄、蒲公英。临床用于急性结膜炎、急性中耳炎、急性肝炎、胆囊炎、急性胰腺炎、泌尿系感染、前列腺炎、湿疹、外阴瘙痒、急性盆腔炎等属肝胆实火或肝经湿热者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方大苦大寒，脾胃虚寒、食少便溏者禁用；阴虚阳亢之头晕目眩、舌红少苔、脉细数者慎用，误投则伤阴助火；孕妇尤当慎用，因方中有活血之当归与峻下之品。肝胆湿热属实证方可用之，若仅有肝火而无湿热、亦无肝胆实火者，当以滋养肝阴之法，不可一概苦寒直折。木通须用川木通，忌用关木通；服药期间忌食辛辣酒酪厚味，疗程宜短，中病即止。"},{"type":"quote","text":"治胁痛口苦，耳聋耳肿，筋痿阴汗阴湿痒，妇人湿热带下，男子阴挺，湿热带下，疝痛，小便淋浊，妇女湿热带下等证。","source":"《医方集解》卷四·泻火之剂"},{"type":"keypoints","title":"掌握要点","items":["清泻肝胆实火兼利肝经湿热，龙胆草为君，直上清下导","黄芩栀子助泻火燥湿，泽泻木通车前子导湿热从小便出","生地当归养血滋阴，泻中有补，祛邪不伤阴血","柴胡引经、甘草调和；苦寒之剂，脾胃虚寒与孕妇慎用，忌久服"]}]},{"id":"qingwei-san","title":"清胃散","subtitle":"《脾胃论》· 生地黄 当归 牡丹皮 黄连 升麻","category":"清热剂","tags":["清胃凉血","清热解毒","胃火牙痛"],"meta":[{"label":"出处","value":"《脾胃论》卷三（李东垣）"},{"label":"组成","value":"生地黄 12g，当归 6g，牡丹皮 9g，黄连 6g，升麻 9g"},{"label":"用法","value":"水煎服，食后温服"},{"label":"功用","value":"清胃凉血"},{"label":"主治","value":"胃火牙痛。牙痛牵引头脑，面赤发热，牙龈红肿溃烂，或牙宣出血，口气热臭，舌红苔黄，脉滑数"}],"image":"","imageHint":"清胃","summary":"清胃散为《脾胃论》清胃凉血之方，主治胃火牙痛。方以黄连为君，清胃泻火；生地黄为臣，凉血滋阴；牡丹皮为佐，清热凉血，活血消肿；升麻为使，散火解毒，引经上行并能升清；配当归养血活血，防苦寒伤血且使气血和。全方苦寒清泻而兼辛散升提，「清胃火，凉血止血」，标本兼顾。临床用于牙髓炎、牙周炎、牙龈炎、三叉神经痛、口疮、咽炎等属胃火炽盛者。若风寒牙痛、肾虚牙痛则非所宜。","blocks":[{"type":"paragraph","text":"足阳明胃经入上齿，手阳明大肠经入下齿。胃火炽盛，循经上炎，火热上攻则牙痛牵引头脑、面赤发热；火热壅聚牙龈则红肿溃烂，或成牙宣出血；口气热臭、舌红苔黄、脉滑数，皆胃火之征。治当清泻胃火、凉血止痛，使火从内降而牙龈得安。"},{"type":"table","caption":"清胃散君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["黄连","君：清胃泻火，直折阳明之火","6g"],["生地黄","臣：凉血滋阴，助君清热并护阴","12g"],["牡丹皮","佐：清热凉血，活血消肿止痛","9g"],["当归","佐：养血活血，防苦寒耗血，使气血和","6g"],["升麻","使：散火解毒，引经上达于齿龈，并能升清","9g"]]},{"type":"paragraph","text":"本方立法精妙，取李东垣「升清降浊」之意。清胃火不用朴硝沉降，而用黄连苦寒直折，热去则痛自止，此为君药。生地黄甘苦寒凉，凉血滋阴，既协黄连清热，又防苦寒伤阴，为臣。牡丹皮苦辛微寒，清热凉血而兼活血消肿止痛；当归甘辛温润，养血活血，一则防苦寒耗伤阴血，二则使气血调和而痛可止，二药同为佐。升麻辛甘微寒，一则散火解毒，助清胃火之功，二则引诸药上达于齿龈，三则取其升散之性，使下陷之清阳得升，火降而牙龈肿痛自消，是为使。综观全方：苦寒与辛散相伍，苦寒降火、辛散透邪；凉血与养血同用，清火而不损血；清降之中寓升散，泻火而兼升清。故胃火得清、血热得凉、龈肿得消、牙痛得止，为治胃火牙痛之代表方。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"胃火炽盛、牙龈肿痛甚者加石膏、蒲公英、紫花地丁；牙痛牵引头痛者加川芎、白芷、细辛；牙龈出血加白茅根、藕节；便秘加大黄；口疮心烦加连翘、竹叶；风火牙痛加防风、羌活；肾阴不足而牙痛者去黄连加知母、黄柏（玉女煎意）。临床用于牙髓炎、牙周炎、牙龈炎、智齿冠周炎、三叉神经痛、复发性口腔溃疡、急性咽炎等属胃火炽盛者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方主治阳明胃火实证，若牙痛隐隐、喜温喜按、齿松不坚，属肾阴不足虚火上炎，或牙痛遇寒加重、得温则减、舌淡苔白，属风寒牙痛，均不可误用，误投则苦寒伤阳、虚火更炽。脾胃虚寒、食少便溏者慎用；孕妇慎用，因方中当归、牡丹皮有活血之能。服药期间忌食辛辣炙煿、酒酪及生冷坚硬之物，牙痛期间宜食软烂清淡之品。"},{"type":"quote","text":"治牙痛牵引头脑，面赤发热，牙龈红肿溃烂，或脉洪实而滑数，口气热臭。","source":"《脾胃论》卷三·清胃散"},{"type":"keypoints","title":"掌握要点","items":["清胃凉血，主治胃火牙痛：牙痛牵引头脑、牙龈红肿、口气热臭、舌红苔黄","黄连为君泻胃火，生地为臣凉血养阴，丹皮、当归凉血养血","升麻为使散火解毒、引经上达，并寓升清于降火之中","风寒牙痛、肾虚牙痛、脾胃虚寒者禁用或慎用"]}]},{"id":"dachengqi-tang","title":"大承气汤","subtitle":"《伤寒论》· 大黄 厚朴 枳实 芒硝","category":"泻下剂","tags":["峻下热结","通腑泄热","阳明腑实证"],"meta":[{"label":"出处","value":"《伤寒论》卷二·辨阳明病脉证并治"},{"label":"组成","value":"大黄 12g（后下），厚朴 24g，枳实 12g，芒硝 9g（冲服）"},{"label":"用法","value":"以水一斗，煮取二升，去滓，分温二服；初服汤当更衣，不尔者尽饮之；若更衣者勿服之"},{"label":"功用","value":"峻下热结"},{"label":"主治","value":"阳明腑实证。大便不通，频转矢气，脘腹痞满，腹痛拒按，按之硬，甚或潮热谵语，手足濈然汗出，舌苔黄燥起刺或焦黑燥裂，脉沉实；或热结旁流、下利清水臭秽"}],"image":"","imageHint":"大承","summary":"大承气汤为《伤寒论》峻下热结之代表方，主治阳明腑实证。方以大黄为君，泻热通便，荡涤胃肠积滞；芒硝为臣，软坚润燥，助大黄泻热；枳实、厚朴为佐，行气消满除痞，且厚朴降气以助硝黄推陈。全方泻下与行气并用，「痞、满、燥、实」四症俱备者方可用之，后世称其为「峻下热结第一方」。临床用于急性肠梗阻、急性阑尾炎、急性胰腺炎、便秘、菌痢等属阳明腑实、燥屎内结者。因药力峻猛，非急下存阴者不可轻投。","blocks":[{"type":"paragraph","text":"阳明腑实证为胃肠燥热内结、气机阻滞之候。燥屎内结则大便不通、矢气频转；气机壅滞则脘腹痞满、腹痛拒按；燥热内结则潮热谵语、手足濈然汗出；津液被灼则舌苔黄燥起刺甚则焦黑燥裂、脉沉实。四个主症痞（心下痞塞）、满（脘腹胀满）、燥（肠中燥屎）、实（腹痛拒按、便结）具备，方为峻下之适应证。若大便通畅而仅腹胀，或仅便秘而无所苦，皆不可用。"},{"type":"table","caption":"大承气汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["大黄（酒洗，后下）","君：泻热通便，荡涤胃肠积滞，推陈致新","12g"],["芒硝（冲服）","臣：咸寒软坚润燥，助大黄泻热燥结","9g"],["枳实","佐：行气消痞，助硝黄推荡积滞","12g"],["厚朴","佐：行气除满，降气平逆，助硝黄除满消痞","24g"]]},{"type":"paragraph","text":"本方配伍严密，得仲景「急下存阴」之意。硝黄并用为君臣：大黄苦寒沉降，泻热通便，荡涤积滞而力宏；芒硝咸寒，软坚润燥，泻热通便而能软化燥屎，二药相须为用，则泻下之力倍而燥结得解。枳实、厚朴为佐：枳实苦辛微寒，破气消积、化痰除痞；厚朴苦温，下气除满。二药行气消满，既助硝黄推陈，又因「气行则便行」而加强通下，共奏痞满俱除之效。四药相合，泻下与行气并用，软坚与攻下相须，构成「痞、满、燥、实」四治俱全的峻下格局。综观本方：治阳明腑实而不用枳朴理气之品则痞满不除，不用硝黄软坚则燥结不破，二者缺一则全方不立；方中厚朴用量独重，凸显行气除满之意，而大黄后下、芒硝冲服，则取其气锐力峻，寓「釜底抽薪」之法。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"痞满燥实而津伤不甚者用本方；痞满实而无燥屎者去芒硝，枳朴减量（小承气汤）；燥实而无痞满者去枳朴，加甘草（调胃承气汤）；津亏便秘而无痞满燥实者合增液汤（增液承气汤）；热结旁流下利清水者加大黄量并加金银花、黄连；气虚便秘者合补中益气汤；产后瘀血腹痛加大黄、桃仁。临床用于急性肠梗阻、急性阑尾炎、急性胰腺炎、急性胆囊炎、高热谵语、功能性便秘、细菌性痢疾等属阳明腑实者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方峻猛，为伤寒急下之剂，非阳明腑实、痞满燥实俱全者不可轻投。表证未解、里未成实者；年老体弱、孕妇、产后、气血虚亏者；脾胃虚寒者，均当禁用或慎用。得下即止，慎勿过剂，以免攻下太过而伤阴损气；服药后若大便通畅、腹中渐安者，即不宜再服。孕妇及哺乳期禁用，确需应用者须由医师权衡并采用小承气汤等缓和之法。中风、脱证、久病津亏者尤当谨慎。本方必须由中医师辨证使用，切勿自行服用。"},{"type":"quote","text":"阳明病，脉迟，虽汗出不恶寒者，其身必重，短气腹满而喘，有潮热者，此外欲解，可攻里也。手足濈然汗出者，此大便已硬也，大承气汤主之。","source":"《伤寒论》卷二·辨阳明病脉证并治"},{"type":"keypoints","title":"掌握要点","items":["峻下热结第一方，主治痞、满、燥、实四症俱备的阳明腑实证","大黄为君泻热通便，芒硝为臣软坚润燥，枳实厚朴行气除满","大黄后下、芒硝冲服，取其力峻；得下即止，勿过剂","表证未解、体虚、孕妇、产后、脾胃虚寒者禁用或慎用"]}]},{"id":"zengye-chengqi-tang","title":"增液承气汤","subtitle":"《温病条辨》· 玄参 麦冬 生地 大黄 芒硝","category":"泻下剂","tags":["增液通便","泻热救阴","津亏热结"],"meta":[{"label":"出处","value":"《温病条辨》卷三·中焦篇（吴鞠通）"},{"label":"组成","value":"玄参 30g，麦冬 24g，细生地 24g，大黄 9g，芒硝 9g"},{"label":"用法","value":"水煎，三杯煮取二杯，分三次服；得下，余勿服"},{"label":"功用","value":"增液通便，泻热救阴"},{"label":"主治","value":"阳明温病，热结阴伤证。身热，口干咽燥，渴喜冷饮，大便秘结，甚则谵语，舌红少津，脉细数或沉而无力"}],"image":"","imageHint":"增液","summary":"增液承气汤为《温病条辨》治温病热结阴伤、燥屎内结之方。方以玄参、麦冬、细生地为君，滋阴增液、壮水制火；大黄、芒硝为臣，泻热通便、软坚润燥。三者相合，「增水行舟」，使津液得复而燥屎自下。较诸大承气汤，本方泻下之力缓和而滋阴之功独优，适用于温病后期或素体阴亏而腑实者。临床用于习惯性便秘、老年便秘、产后便秘、干燥综合征、放射性肠炎等属津亏热结者。","blocks":[{"type":"paragraph","text":"温病后期，邪热久羁，灼伤津液，或素体阴亏，复感温邪，燥热内结胃肠。津亏则口干咽燥、渴喜冷饮、舌红少津、脉细数；燥屎内结则大便秘结，甚则谵语。此时若以大承气汤峻下，则苦寒伤阴而愈下愈结；若单纯滋阴，则邪结不去。故吴鞠通取增液汤合调胃承气汤而成增液承气汤，以「增水行舟」之法，寓攻补于一方。"},{"type":"table","caption":"增液承气汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["玄参","君：滋阴清热，壮水制火，软坚润燥","30g"],["麦冬、细生地","君：养阴生津，补充亏损之津液","各 24g"],["大黄","臣：泻热通便，荡涤燥屎","9g"],["芒硝","臣：软坚润燥，助大黄通下","9g"]]},{"type":"paragraph","text":"本方即《温病条辨》增液汤（大增液汤去人参与增液承气）之合方。玄参咸寒入肾，滋阴清热而能软坚；麦冬甘微苦寒，养阴生津、清心除烦；细生地甘苦寒，滋阴养血、清热凉血。三药相须，大增阴液，是为君药，正合「壮水之主，以制阳光」之旨。大黄苦寒泻热通便，芒硝咸寒软坚润燥，二者为臣，一攻一润，助君药以通下。合而观之：君药补水以增舟，臣药泻热以行舟；补而不滞，泻而不伤；阴液既复，则燥屎自润而下，燥屎既下，则热势自解而阴液可保。吴氏自谓「此法余常得心应手」，足见其配伍之善。较之大承气汤，本方泻下之力虽缓，却因有厚实之阴津滋养而不伤正气，最合温病后期与老人、产后津亏之体。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"津伤较甚、舌绛少苔者加大生地、玄参用量并加石斛、天花粉；便秘甚者加大黄、芒硝，或加火麻仁、郁李仁；气虚者加生黄芪、白术；血虚者加当归、何首乌；阴虚发热者合青蒿鳖甲汤。临床用于习惯性便秘、老年性便秘、产后便秘、产后大便不通、干燥综合征、放射性肠炎、顽固性便秘、肠神经官能症等属津亏热结者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方为「润下攻下」之剂，药性较和缓但仍属攻下之品。表邪未解、里实未成、气滞腹胀而无燥屎者不宜使用；脾胃虚寒、便溏滑泄者禁用；年老体衰、孕妇、产后气血两虚者当在医师指导下配伍使用，切忌自行攻下。若服后大便通畅即当停用，不可久服。玄参、麦冬、地黄性滋腻，脾虚纳呆、舌苔厚腻者服后易生呆滞，须配伍砂仁、陈皮等醒脾之品。"},{"type":"quote","text":"阳明温病，无上焦证，数日不大便，其人阴素虚，不可行承气者，增液汤主之；服增液汤已，周十二时观之，若大便不下者，合调胃承气汤微和之。","source":"《温病条辨》卷三·中焦篇"},{"type":"keypoints","title":"掌握要点","items":["治阳明温病热结阴伤、津亏便秘之证","玄参、麦冬、生地为君滋阴增液，大黄、芒硝为臣泻热通便","配伍核心是「增水行舟」，补泻兼施，泻而不伤阴","较承气汤缓和，但终属攻下；脾虚滑泄者禁用，得下即止"]}]},{"id":"sijunzi-tang","title":"四君子汤","subtitle":"《太平惠民和剂局方》· 人参 白术 茯苓 炙甘草","category":"补益剂","tags":["补气健脾","益气和中","脾胃气虚"],"meta":[{"label":"出处","value":"《太平惠民和剂局方》卷三"},{"label":"组成","value":"人参 9g，白术 9g，茯苓 9g，炙甘草 6g"},{"label":"用法","value":"上为细末，每服 6g，水一盏，同煎至七分，通口服，不拘时候；或作汤剂水煎服"},{"label":"功用","value":"益气健脾"},{"label":"主治","value":"脾胃气虚证。面色㿠白，语声低微，四肢乏力，食少便溏，舌淡苔白，脉虚弱"}],"image":"","imageHint":"四君","summary":"四君子汤为《太平惠民和剂局方》益气健脾之基础方，主治脾胃气虚证。人参为君，大补元气、健脾养胃；白术为臣，健脾燥湿，助人参益气健脾；茯苓为佐，健脾渗湿；炙甘草为使，益气和中、调和诸药。全方甘温平补，补而不滞、温而不燥，药性平和缓慢，如君子致和，故名「四君子」。为治脾胃气虚的基本方，后世加陈皮为异功散，加半夏为六君子汤，再加木香、砂仁为香砂六君子汤，成为补气健脾法的经典系列。","blocks":[{"type":"paragraph","text":"脾胃为后天之本，气血生化之源。脾胃气虚则纳运无力，故食少便溏；中气不足，故四肢乏力、语声低微；生化乏源，气血不能荣于面，故面色㿠白；舌淡苔白、脉虚弱，皆中气不足之象。治宜甘温益气与健脾渗湿并施，使气得补而湿得去，脾胃健运则气血自生。四君子汤药性平和，补中寓运，为补气健脾第一基础方。"},{"type":"table","caption":"四君子汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["人参","君：大补元气，健脾养胃，益气生津","9g"],["白术","臣：健脾燥湿，助人参益气健脾，为补气健脾要药","9g"],["茯苓","佐：健脾渗湿，益心宁神，助白术除湿","9g"],["炙甘草","使：益气和中，调和诸药，合参术益气健脾","6g"]]},{"type":"paragraph","text":"本方配伍平淡而周密。人参甘温，大补元气、健脾养胃，为君，直治脾胃气虚之本。白术苦甘温，健脾燥湿，益气助阳，既助人参补气健脾，又能燥湿而除中焦之滞，为臣。茯苓甘淡而平，健脾渗湿，益心宁神，与白术相合则健脾祛湿之功更著；人参得茯苓则补气而无壅滞之虞，茯苓得人参则祛湿而不伤正之虞，二药相得，为佐。炙甘草甘温，益气和中，调和诸药，既助参、术补气，又可缓和白术燥湿之性，使全方补而不滞、温而不燥，是为使。四药合用，益气与健脾并重，补气与渗湿同施，温而不燥、平而不寒，服之气血渐充，脾胃渐健，故名四君子汤，为补气健脾之典范。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"加陈皮为异功散，兼理气化滞；加半夏、陈皮为六君子汤，兼燥湿化痰；再加木香、砂仁为香砂六君子汤，兼行气化滞；加人参、白术、当归、炙甘草为八珍汤，气血双补；加黄芪、附子为六君子加味，兼温阳益气；食少腹胀加枳壳、厚朴；泄泻加茯苓、炒薏苡仁、莲子；呕吐加半夏、生姜；贫血加当归、熟地、阿胶。临床用于慢性胃炎、消化性溃疡、慢性腹泻、功能性消化不良、贫血、慢阻肺缓解期等属脾胃气虚者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方甘温壅补，若外感表证未解、里热炽盛、湿热内蕴者当先解表清热，误补则留邪恋疾；阴虚火旺、舌红少苔、脉细数者不宜使用；实热积滞、大便秘结者忌用。服本方期间忌食生冷油腻、坚硬不化之物，宜食清淡易消化之品；所谓「虚不受补」，若服后脘腹胀满、纳呆苔腻者，须配伍理气醒脾之品或调整方案。剂量与疗程须由医师把握，儿童及孕妇慎用。"},{"type":"quote","text":"治荣卫气虚，脏腑怯弱，心腹胀满，全不思食，肠鸣泄泻，呕哕吐逆，或因食劳气伤，或因病后调理不，或痰气作而饮食减少，或气虚成热，呕吐吞酸，或气不调而喘咳，或霍乱吐泻，或因气虚而吐血，或因噎膈而食不下，或因气弱而恶寒发热，或因虚弱而口舌生疮，或因胃气虚弱而呕吐清水，或因脾胃不健而大便不实等证。","source":"《太平惠民和剂局方》卷三·治一切气"},{"type":"keypoints","title":"掌握要点","items":["益气健脾第一基础方，主治脾胃气虚：食少便溏、四肢乏力、舌淡脉弱","人参为君、白术为臣、茯苓为佐、炙甘草为使，补气与渗湿并重","药性甘温平补，补而不滞、温而不燥，故名四君子","外感未解、里热、湿热、阴虚火旺者禁服；宜配伍化裁为六君、香砂六君等"]}]},{"id":"buzhong-yiqi-tang","title":"补中益气汤","subtitle":"《内外伤辨惑论》· 黄芪 白术 人参 当归 陈皮 升麻 柴胡 炙甘草","category":"补益剂","tags":["补中益气","升阳举陷","脾虚气陷"],"meta":[{"label":"出处","value":"《内外伤辨惑论》卷中·饮食劳倦论"},{"label":"组成","value":"黄芪 18g，白术 9g，人参 6g，当归 3g，陈皮 6g，升麻 6g，柴胡 6g，炙甘草 5g"},{"label":"用法","value":"上㕮咀，水二盏半，煎至一盏，去滓，早饭午饭之间服之"},{"label":"功用","value":"补中益气，升阳举陷"},{"label":"主治","value":"脾虚气陷证。饮食减少，体倦肢软，少气懒言，面色㿠白，大便稀溏，脉虚软；以及气虚发热证：身热自汗，渴喜热饮，气短乏力，舌淡苔白，脉虚大无力"}],"image":"","imageHint":"补中","summary":"补中益气汤为《内外伤辨惑论》补气升阳之代表方，主治脾胃气虚、气虚发热及气虚下陷之证。方以黄芪为君，补中益气、升阳固表；人参、白术、炙甘草甘温益气，健脾养胃为臣；陈皮理气和胃，使诸药补而不滞；当归养血和营为佐；升麻、柴胡升阳举陷，引清阳上达为使。全方甘温补中与升提并用，补而不滞、升而不陷，为「甘温除热」法的代表方。临床用于内脏下垂、重症肌无力、慢性腹泻、贫血、功能性子宫出血、慢性疲劳综合征等属中气不足者。","blocks":[{"type":"paragraph","text":"李东垣立此方，以脾胃为枢纽。饮食劳倦，脾胃气虚，运化无力，故饮食减少、大便稀溏；中气下陷，脏器失于升举，故久泻脱肛、子宫下垂；清阳不升、浊阴不降，阳气郁于肌表，故见身热自汗而渴喜热饮，此即「阴火」之假热。其与外感发热不同：外感则恶寒、脉浮紧，本证则恶寒自汗、脉虚大无力。治当补中益气、升阳举陷，甘温除热。"},{"type":"table","caption":"补中益气汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["黄芪（蜜炙）","君：补中益气，升阳固表，为补气升阳要药","18g"],["人参、白术、炙甘草","臣：益气健脾，资生气血之源，合黄芪增强补气之力","6g／9g／5g"],["当归","佐：养血和营，气血相生","3g"],["陈皮","佐：理气和胃，使补而不滞、升降相因","6g"],["升麻、柴胡","使：升阳举陷，引清阳上达，兼助黄芪固表","各 6g"]]},{"type":"paragraph","text":"本方配伍的核心在「补中与升阳同用、益气与养血相兼」。黄芪甘温而升，补中益气、升阳固表，既治脾气虚之本，又治清阳下陷之标，为君。人参大补元气，白术健脾燥湿，炙甘草益气和中，三药合用即四君子汤之法，共为臣，资补中焦、培其生化之源，使气旺则血生。陈皮辛温，理气和胃，既使诸药补而不滞，又与升麻、柴胡之升散相配，使升降相因、气机得调；当归养血和营，与参、芪相配则气血相生而不偏枯，同为佐。升麻、柴胡苦辛微温而升浮，取其升举清阳之能，既助黄芪以升提下陷之中气，又引诸药上行直达病所，是为使。综观全方：甘温补气而不滞气，升阳举陷而不伤正，补中寓升、升中寓补，标本兼顾，故能治体倦少气之虚证，又能除气虚发热之「阴火」。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"头痛加川芎、蔓荆子、柴胡；久泻加诃子、肉豆蔻、罂粟壳（须慎）；崩漏加艾叶、棕榈炭、地榆；遗尿加益智仁、桑螵蛸；脱肛加诃子、柴胡；顽固性头痛加天麻、钩藤；重症肌无力加附子、巴戟天、淫羊藿；慢性疲劳综合征加仙茅、淫羊藿。临床用于内脏下垂（胃下垂、子宫脱垂、脱肛）、重症肌无力、慢性腹泻、功能性子宫出血、贫血、慢性疲劳综合征、神经性衰弱等属中气不足、清阳下陷者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方甘温升散，阴虚火旺、肝阳上亢、实热证候者禁用，误服可致头晕目胀、烦躁失眠；外感表热、湿热内蕴、食积腹胀者不宜使用；高血压属肝阳上亢者尤当忌之。升麻、柴胡用量不宜过大，以免升散太过致肝阳上亢。服药期间忌食生冷油腻，宜静养少劳。孕妇须在医师指导下使用。用于内脏下垂时须配合针灸、康复锻炼，疗效方能稳固。"},{"type":"quote","text":"脾胃气虚，饮食劳倦，心火甚甚，乘其土位，其次肺气受邪，须用黄芪最多，人参、甘草次之。脾胃一虚，肺气先绝，故用黄芪以益皮毛而闭腠理，不令自汗。","source":"《内外伤辨惑论》卷中·饮食劳倦论"},{"type":"keypoints","title":"掌握要点","items":["补气升阳第一方，主治脾虚气陷、气虚发热（阴火）","黄芪为君补中升阳，参术草为臣健脾资源，升麻柴胡为使升举引经","当归养血，陈皮理气，故补而不滞、升而不陷","阴虚火旺、肝阳上亢、实热者禁用；真寒假热者需辨清方可使用"]}]},{"id":"shengmai-san","title":"生脉散","subtitle":"《医学启源》· 人参 麦冬 五味子","category":"补益剂","tags":["益气生津","敛阴止汗","气阴两伤"],"meta":[{"label":"出处","value":"《医学启源》卷下·人参（《内外伤辨惑论》亦有载）"},{"label":"组成","value":"人参 9g，麦冬 9g，五味子 6g"},{"label":"用法","value":"上三味，同水煎，或作散剂，每服 6g，一日三次"},{"label":"功用","value":"益气生津，敛阴止汗"},{"label":"主治","value":"气阴两伤证。汗多神疲，体倦乏力，气短懒言，咽干口渴，舌干红少苔，脉虚数；久咳肺虚，气阴两虚之咳嗽少痰、短气自汗"}],"image":"","imageHint":"生脉","summary":"生脉散为《医学启源》益气生津、敛阴止汗之代表方，主治气阴两伤证。人参为君，益气生津、补肺益智；麦冬为臣，养阴生津、清心除烦；五味子为佐，敛肺止汗、生津涩精。三药一补、一清、一敛，益气养阴、生津止渴、敛阴止汗，故名「生脉」。全方扶正而不恋邪、敛固而不留邪，为暑伤气阴、久病气阴两虚之要方。临床用于中暑、心源性休克、心律失常、冠心病、病毒性心肌炎、慢阻肺、肺结核、糖尿病等属气阴两虚者。","blocks":[{"type":"paragraph","text":"暑热耗气伤津，或久病、热病后期，气随津泄而两伤，故汗多神疲、体倦气短、咽干口渴、舌干红、脉虚数；肺气虚则咳嗽少痰、气短自汗。治当益气养阴、生津止渴，兼以敛汗固脱。生脉散仅三味药，却标本兼顾，气阴双补，是后世生津益气诸方之祖。"},{"type":"table","caption":"生脉散君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["人参","君：大补元气，益肺气、生津液、益智安神","9g"],["麦冬","臣：养阴生津，清心除烦，兼清肺润燥","9g"],["五味子","佐：敛肺止汗，生津止渴，涩精止泻","6g"]]},{"type":"paragraph","text":"生脉散配伍之妙，在于一补一润一敛，标本并治而互不碍。人参甘温，大补元气，兼益肺气、生津液、养神益智，为君，直治气虚之本。麦冬甘微苦寒，性润质柔，养阴生津、清心除烦，一方面助人参生津，另一方面制约人参温燥之性，使全方补而不燥，为臣。五味子酸温，敛肺止汗、生津止渴、涩精止泻，为佐：一则敛汗以防气随津脱，二则与麦冬相配，酸甘化阴而生津止渴，三则与参、麦相配，一敛一润一补，敛中寓补，涩不伤正。综观全方：人参之甘温与麦冬之甘寒相配，气阴双补；麦冬之润与五味子之敛相配，敛阴而不留邪；五味子之酸与参麦之甘相配，酸甘化阴。补而不壅、润而不腻、敛而不滞，故名「生脉」——补气以复脉，养阴以生津，敛汗以固脱。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"暑热伤气、元气大脱者加附子、干姜（生脉附子汤）；心阳暴脱者加附子、龙骨、牡蛎；心阴不足、心悸失眠加酸枣仁、柏子仁、龙眼肉；冠心病心绞痛加丹参、川芎、郁金；慢性心衰加附子、丹参、葶苈子；肺虚久咳加百合、枇杷叶、蜜紫菀；糖尿病气阴两虚加天花粉、生地、山药。临床用于中暑急性虚脱、心源性休克、心律失常、冠心病、病毒性心肌炎、阻塞性肺病、肺结核、糖尿病、神经衰弱等属气阴两虚者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方以补为主，外邪未解、暑热尚盛之实证、湿热壅盛、食积内停者禁用，恐恋邪留滞；阴虚阳亢、实热证、脘腹胀满、食少便溏者慎用五味子之酸涩。五味子有收敛之性，凡表邪未解、咳嗽初起、麻疹初出者不宜早用，以免恋邪。服药期间忌食生冷油腻及辛辣发散之品，慎用浓茶、咖啡等耗气伤津之物。血压偏高属肝阳上亢者当慎用，高热大汗而致脱者须配合急救措施。"},{"type":"quote","text":"人参、麦门冬、五味子，上三味同水煎，或生脉饮。","source":"《医学启源》卷下·人参"},{"type":"keypoints","title":"掌握要点","items":["益气生津、敛阴止汗，主治气阴两伤：汗多神疲、口渴、舌干红、脉虚数","人参为君补气生津，麦冬为臣养阴，五味子为佐敛肺止汗","一补一润一敛，补而不壅、敛不留邪，故名生脉","外邪未解、实热、湿热、麻疹初出者禁用或慎用"]}]},{"id":"siwu-tang","title":"四物汤","subtitle":"《太平惠民和剂局方》· 熟地黄 当归 白芍 川芎","category":"补益剂","tags":["补血调血","养血和营","营血虚滞"],"meta":[{"label":"出处","value":"《太平惠民和剂局方》卷九（源出《仙授理伤续断秘方》）"},{"label":"组成","value":"熟地黄 12g，当归 10g，白芍 12g，川芎 8g"},{"label":"用法","value":"上为粗末，每服 6g，水一盏半，煎至七分，去滓温服"},{"label":"功用","value":"补血调血"},{"label":"主治","value":"营血虚滞证。头晕目眩，心悸失眠，面色无华，妇人月经不调，量少或经闭不行，脐腹作痛，舌淡，脉细弦或细涩"}],"image":"","imageHint":"四物","summary":"四物汤为补血调血之代表方，主治营血虚滞证。熟地黄为君，滋阴补血填精；当归为臣，补血养肝、和血调经；白芍养血敛阴、柔肝止痛；川芎活血行气，使全方补而不滞。四药配伍，补中有行、滋而不腻，补血而不滞血，行血而不伤血，为妇科调经之基础方，后世加桃仁、红花为桃红四物汤，加人参、黄芪为圣愈汤，加人参、白术、茯苓、甘草为八珍汤。临床用于月经不调、痛经、贫血、荨麻疹、紫癜等属营血虚滞者。","blocks":[{"type":"paragraph","text":"营血亏虚则不能上荣，故头晕目眩、面色无华；血不养心则心悸失眠；血少则经水不调、量少或经闭；血虚脉络失充则脐腹作痛，舌淡、脉细弦或细涩。治当补血和血、调畅营血。四物汤为历代妇科调经的基础方，功在补血而不滞血，养血而不碍血，故后世称其为「血家百病之专方」。"},{"type":"table","caption":"四物汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["熟地黄","君：滋阴补血，填精益髓，为补血之要药","12g"],["当归","臣：补血养肝，调经止痛，和血润燥","10g"],["白芍","佐：养血敛阴，柔肝止痛，和营缓急","12g"],["川芎","使：活血行气，调畅气血，使全方补而不滞","8g"]]},{"type":"paragraph","text":"四物汤之配伍，妙在补血与行血相融、滋阴与养血相须。熟地黄甘温质润，滋阴补血、填精益髓，为补血之君；当归甘辛温润，补血养肝、调经止痛、润肠通便，为臣，二者相须则补血之力倍。白芍苦酸微寒，养血敛阴、柔肝止痛、缓急和中，为佐；其与当归相配，一养血柔肝而不滞，一敛阴缓急而不涩。川芎辛温升散，走而不守，活血行气、祛瘀止痛，为使；它一方面使全方补而不滞、行而不峻，另一方面引诸药上行头目、下行血海。综观全方：熟地、白芍静而不动，当归、川芎动而不躁；补中有行，行中有补，养血而不伤血，活血而不耗血。故月经不调、痛经、眩晕、心悸、面色萎黄等属营血虚滞者，皆可以此为基础随证加减。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"血虚有热加黄芩、牡丹皮；血虚有寒加肉桂、炮姜；血瘀加桃仁、红花（桃红四物汤）；血虚气弱加人参、黄芪（圣愈汤）；气血两虚合四君子汤（八珍汤）；血虚发热加黄芪、党参、炙甘草（当归补血汤）；月经过多加艾叶、棕榈炭、阿胶；痛经加香附、延胡索；闭经加桃仁、红花、牛膝；血虚生风加防风、荆芥；荨麻疹加蝉蜕、白鲜皮。临床用于月经不调、痛经、功能性子宫出血、贫血、荨麻疹、过敏性紫癜、产后调理等属营血虚滞者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方多甘温滋腻，脾胃虚弱、纳呆便溏、舌苔厚腻者慎用，服后若脘腹胀满、纳减苔腻，当加砂仁、陈皮、茯苓等醒脾运化之品或调整熟地用量。阴虚火旺、湿热内蕴、实热出血者不宜使用。川芎为行气活血之品，孕妇慎用，月经过多者亦须慎之；服本方期间忌食生冷油腻及蟹、柿、荔枝等发物。补血之剂贵在坚持，骤然大量进补反易碍胃，须循序渐进。"},{"type":"quote","text":"治荣血虚滞，妇人月水不调，脐腹作痛，崩中漏下，血瘕痞块，妊娠宿冷，将理失宜，胎动不安，血下不止，及产后乘虚，风寒内搏，瘀血停滞，烦闷腹痛等证。","source":"《太平惠民和剂局方》卷九·治妇人诸疾"},{"type":"keypoints","title":"掌握要点","items":["补血调血第一方，主治营血虚滞：头晕心悸、面黄、量少经闭、舌淡脉细","熟地补血为君，当归为臣，白芍佐之，川芎为使","配伍特点：补中有行、滋而不滞、养血不伤血","脾虚便溏者慎用；川芎活血，孕妇与月经过多者慎之"]}]},{"id":"guipi-tang","title":"归脾汤","subtitle":"《济生方》· 白术 茯神 黄芪 龙眼肉 酸枣仁 人参 木香 甘草 当归 远志","category":"补益剂","tags":["益气补血","健脾养心","心脾两虚"],"meta":[{"label":"出处","value":"《重订严氏济生方》卷二·心脾论（后世薛己增当归、远志）"},{"label":"组成","value":"白术 9g，茯神 9g，黄芪 12g，龙眼肉 12g，酸枣仁 12g，人参 6g，木香 5g，炙甘草 3g，当归 9g，远志 6g，生姜 3 片，大枣 4 枚"},{"label":"用法","value":"上作一服，水二盏，生姜三片，大枣四枚，煎至一盏，去滓温服，不拘时候"},{"label":"功用","value":"益气补血，健脾养心"},{"label":"主治","value":"心脾气血两虚证。心悸怔忡，健忘失眠，盗汗虚热，体倦食少，面色萎黄，舌淡苔薄白，脉细弱；以及脾不统血之便血、崩漏、紫癜、月经提前量多"}],"image":"","imageHint":"归脾","summary":"归脾汤为《济生方》益气补血、健脾养心之代表方，主治心脾两虚及脾不统血之证。黄芪、人参、白术、甘草甘温补气健脾，使脾气旺而血有所生；龙眼肉、当归养血补心；酸枣仁、茯神、远志宁心安神；木香少许行气，使补而不滞。气为血之帅，血为气之母，气血双补而以补气为主，心脾同治而重在健脾，故名「归脾」。临床用于神经衰弱、失眠、心律失常、贫血、血小板减少性紫癜、功能性子宫出血、消化性溃疡等属心脾两虚者。","blocks":[{"type":"paragraph","text":"思虑过度则脾气耗伤，饮食不节则生化乏源，脾气虚弱则血无所生，血不养心故心悸怔忡、失眠健忘；气不摄血则见便血、崩漏、月经过多；气血不足则体倦食少、面色萎黄、舌淡脉细弱。本证以脾虚为本、心血不足为标，故治当健脾益气为主，养血安神为辅，使脾气健运则血自生，血充则心神得养。"},{"type":"table","caption":"归脾汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["黄芪、人参、白术、炙甘草","君臣：益气健脾，资气血生化之源，使血有所生","12g／6g／9g／3g"],["龙眼肉、当归","臣：养血补心安神，与补气药相配气血双补","12g／9g"],["酸枣仁、茯神、远志","佐：养心安神定志，敛心气以止盗汗","12g／9g／6g"],["木香","佐：理气醒脾，使补而不滞，气血流通","5g"],["生姜、大枣","使：调和脾胃，益气和中，兼养血安神","3 片／4 枚"]]},{"type":"paragraph","text":"本方配伍体现了「心脾同治、气血双补」的大法。黄芪补气升阳固表，人参大补元气，白术健脾燥湿，炙甘草益气和中，四药合为四君子之法，共为君药，以健脾气、资生化之源，正合「气为血之帅」之旨。龙眼肉甘温补心脾、益气血，当归补血养肝，二药为臣，与君药相配，气血双补而以气为主。酸枣仁养心补肝、敛汗宁心，茯神宁心安神，远志交通心肾、安神益智，三药为佐，一则补心血以养心神，一则敛脾气以止盗汗。少量木香辛香行气，醒脾开胃，使大队补益之品不致壅滞，为佐；又与生姜、大枣相配调和脾胃、资生化源，为使。综观全方：补气药多而养血药辅，重在健脾以生血；养心安神而不碍运，摄血止血而不留瘀。脾气得健则血自生，血气得充则心神得养，故名归脾汤，为治心脾两虚、脾不统血之要方。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"崩漏加艾叶炭、棕榈炭、阿胶；便血加地榆炭、槐花；血小板减少性紫癜加仙鹤草、白及、花生衣；失眠重加夜交藤、合欢皮、珍珠母；心悸加苦参、龙齿、磁石；自汗盗汗加浮小麦、麻黄根、五味子；纳差加砂仁、麦芽、神曲；兼瘀血者加桃仁、红花。临床用于神经衰弱、失眠、贫血、血小板减少性紫癜、功能性子宫出血、神经性心律失常、消化性溃疡、神经性耳鸣等属心脾两虚者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方多为甘温补益，痰湿内盛、舌苔厚腻、脘腹胀闷、食少纳呆者不宜使用；阴虚火旺、口舌生疮、便秘者慎用；外感发热期间当停服。木香辛温走窜，阴虚火旺或血热妄行者当减量；当归、龙眼肉滋腻，脾虚便溏者须配伍健运之品。使用期间注意节制思虑、劳逸适度，方能收效。出血量大者应先行现代医学检查与处理，不可单凭中药汤剂延误。"},{"type":"quote","text":"治思虑过度，健忘怔忡，虚烦不眠，或自汗盗汗，或衄血吐血，或食少体倦，或崩中漏下，或小儿痘疮失血。","source":"《重订严氏济生方》卷二·心脾论"},{"type":"keypoints","title":"掌握要点","items":["益气补血、健脾养心，主治心脾气血两虚及脾不统血","四君子汤为基础补气健脾，配龙眼肉、当归养血，枣仁、茯神、远志安神","配伍特点：心脾同治、气血双补而重在补气，木香一味使补而不滞","痰湿壅盛、阴虚火旺者禁服；出血量大者须先就医"]}]},{"id":"liuwei-dihuang-wan","title":"六味地黄丸","subtitle":"《小儿药证直诀》· 熟地黄 山萸肉 山药 泽泻 牡丹皮 茯苓","category":"补益剂","tags":["滋补肝肾","填精益髓","肝肾阴虚"],"meta":[{"label":"出处","value":"《小儿药证直诀》卷下·诸方（钱乙创制地黄丸）"},{"label":"组成","value":"熟地黄 24g，山萸肉 12g，山药 12g，泽泻 9g，牡丹皮 9g，茯苓 9g"},{"label":"用法","value":"上为末，炼蜜为丸，如梧子大，空心温水化下三丸；亦可作汤剂水煎服"},{"label":"功用","value":"滋补肝肾"},{"label":"主治","value":"肝肾阴虚证。腰膝酸软，头晕目眩，耳鸣耳聋，盗汗遗精，骨蒸潮热，手足心热，口燥咽干，舌红少苔，脉沉细数"}],"image":"","imageHint":"六味","summary":"六味地黄丸为钱乙《小儿药证直诀》所创地黄丸之剂，主治肝肾阴虚之证。熟地黄为君，滋阴补肾、填精益髓；山萸肉补养肝肾、涩精，山药补脾益阴、固精，共为臣，三药相配即「三补」。泽泻利湿泄浊防熟地之滞，牡丹皮清泄相火制山萸之温，茯苓淡渗脾湿助山药之健，即「三泻」。三补三泻，补中有泻、寓泻于补，补而不腻，为滋阴补肾之基础方。临床用于慢性肾炎、高血压病、糖尿病、肺结核、神经衰弱、更年期综合征等属肝肾阴虚者。","blocks":[{"type":"paragraph","text":"肝肾同源，肾藏精、主骨生髓，肝藏血、主筋。肝肾阴精亏虚，髓海失充则腰膝酸软、头晕目眩、耳鸣耳聋；虚热内扰则骨蒸潮热、手足心热、口燥咽干、盗汗；封藏失职则遗精；舌红少苔、脉沉细数，为阴虚内热之征。治当滋补肝肾、填精益髓，兼清虚火、渗湿浊。六味地黄丸为滋阴补肾之基础方，后世知柏地黄丸、杞菊地黄丸、麦味地黄丸皆由本方化裁。"},{"type":"table","caption":"六味地黄丸君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["熟地黄","君：滋阴补肾，填精益髓，为滋阴补肾之要药","24g"],["山萸肉","臣：补养肝肾、涩精，微温而不燥","12g"],["山药","臣：补脾益阴、固精，为后天补先天之要药","12g"],["泽泻","佐：淡渗脾湿、泄肾浊，防熟地之滋腻","9g"],["牡丹皮","佐：清泄肝肾相火，制山萸肉之温","9g"],["茯苓","佐：淡渗脾湿，助山药健运","9g"]]},{"type":"paragraph","text":"本方配伍之妙在「三补三泻，补中有泻」。熟地黄甘温质润，滋阴补肾、填精益髓，为君，直治肝肾阴虚之本。山萸肉酸温而涩，补养肝肾并涩精封藏；山药甘平，补脾益阴而固精，二药为臣。熟地配山萸，一滋肾水、一涩精气；熟地配山药，一补肾阴、一补脾阴，三药共为「三补」，从肾、肝、脾三阴同治，肾水得补则髓海充、肝得养则筋和。妙在补而不腻，故用三味「三泻」制约：泽泻淡渗脾湿而泄肾浊，使熟地之滋腻不滞；牡丹皮清泄肝肾相火，制山萸肉之温而防助热；茯苓淡渗脾湿，助山药健运而使补力得行。泻药虽能泄浊，却不伤正，正所谓「寓泻于补」。综观全方：三补三泻，补多泻少，补中有泻、寓泻于补，滋而不腻、补而不滞，故为滋补肝肾、填精益髓之典范，成人小儿皆宜。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"虚火明显加知母、黄柏（知柏地黄丸）；目干涩痛加枸杞子、菊花（杞菊地黄丸）；肺肾阴虚、咳嗽咽干加麦冬、五味子（麦味地黄丸）；肝血虚加当归、白芍（归芍地黄丸）；耳鸣加磁石、柴胡；遗精加金樱子、芡实、莲须；骨质疏松加骨碎补、杜仲、淫羊藿；糖尿病加天花粉、葛粉、玉米须；高血压加钩藤、菊花。临床用于慢性肾炎、高血压病、糖尿病、肺结核、神经衰弱、更年期综合征、男子不育、女子不孕等属肝肾阴虚者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方甘寒滋腻，脾虚便溏、痰湿内盛、食少纳呆、舌苔厚腻者不宜服用，服后若脘腹胀满、纳减、便溏加重，须加陈皮、砂仁、茯苓、山楂等健运消导之品或改用加减法；阳虚畏寒、畏寒肢冷、便溏清稀者禁用。感冒发热期间停服。儿童脾胃虚弱者宜从小剂量开始，或改用汤剂。服药期间忌食生冷油腻、辛辣炙煿之品。用于慢性肾炎、糖尿病等疾病时须坚持规范治疗，不可自行替代西药。"},{"type":"quote","text":"地黄丸，治肾怯失音，囟开不合，神不足，目中白睛多，面色㿠白等虚证。","source":"《小儿药证直诀》卷下·诸方"},{"type":"keypoints","title":"掌握要点","items":["滋补肝肾第一基础方，主治肝肾阴虚：腰膝酸软、眩晕耳鸣、潮热盗汗、舌红少苔","三补（熟地、山萸、山药）配三泻（泽泻、丹皮、茯苓），补中有泻","补多泻少，滋而不腻，为知柏、杞菊、麦味地黄丸之母方","脾虚便溏、痰湿内盛、阳虚畏寒者禁服，感冒发热期间停用"]}]},{"id":"xiaochaihu-tang","title":"小柴胡汤","subtitle":"《伤寒论》· 柴胡 黄芩 人参 半夏 炙甘草 生姜 大枣","category":"和解剂","tags":["和解少阳","疏肝和胃","枢机不运"],"meta":[{"label":"出处","value":"《伤寒论》卷三·辨太阳阳明病脉证并治"},{"label":"组成","value":"柴胡 24g，黄芩 9g，人参 9g，半夏 9g，炙甘草 3g，生姜 9g，大枣 4 枚"},{"label":"用法","value":"上八味，以水一斗二升，煮取六升，去滓，温服一升，日三服"},{"label":"功用","value":"和解少阳"},{"label":"主治","value":"少阳证。往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕，口苦咽干目眩，舌苔薄白，脉弦；兼治热入血室之疟疾、黄疸等"}],"image":"","imageHint":"小柴","summary":"小柴胡汤为《伤寒论》和解少阳之代表方，主治少阳枢机不运之证。柴胡为君，透泄少阳半表之邪、疏泄气机之郁滞；黄芩为臣，清泄少阳半里之热，一散一清共解少阳之邪；半夏、生姜降逆和胃止呕，人参、大枣益气健脾扶正，炙甘草调和诸药为佐使。全方和解少阳、扶正祛邪、寒热并用、辛开苦降，被称「和法之代表」，为后世逍遥散、四逆散、柴胡桂枝汤之母方。临床用于感冒、流行性感冒、疟疾、胆囊炎、胰腺炎、肝炎、胸膜炎、乳腺增生、更年期综合征等属少阳证者。","blocks":[{"type":"paragraph","text":"邪传少阳，枢机不利，邪正相争则往来寒热（寒热交替，发无定时）；少阳经脉循胸胁，故胸胁苦满；胆胃不和故默默不欲饮食、心烦喜呕；少阳枢机不利、津液不布故口苦咽干目眩；脉弦为少阳之脉。治当和解少阳，透泄表邪、清泄里热，兼扶正气、和中降逆。所谓「但见一证便是，不必悉具」，即抓住往来寒热、胸胁苦满、脉弦等主症即可投用。"},{"type":"table","caption":"小柴胡汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["柴胡","君：透泄少阳半表之邪，疏泄气机郁滞","24g"],["黄芩","臣：清泄少阳半里之热，与柴胡散清并用","9g"],["半夏、生姜","佐：和胃降逆止呕，兼制柴胡之散","9g／9g"],["人参、大枣","佐：益气健脾，扶正以助祛邪","9g／4 枚"],["炙甘草","使：调和诸药，合参枣扶正","3g"]]},{"type":"paragraph","text":"本方配伍精妙，是「和法」之典范。柴胡苦平，入肝胆经，轻清升散，透泄少阳半表之邪，兼疏泄气机郁滞，为君。黄芩苦寒，清泄少阳半里之热，为臣。二药相合，一散一清，透表清里，柴芩合用乃和解少阳之核心。半夏辛温，生姜辛温，二者相须为用，降逆和胃止呕，并制约柴胡升散之性，使邪不外越而得从里解；人参、大枣甘温，益气健脾，扶正以助祛邪，正所谓「扶正祛邪」，同时可防邪内传；炙甘草甘温，调和诸药，合人参、大枣益气和中，又合柴芩之苦以缓肝胆之急，为使。综观全方：寒热并用，柴芩清透与姜夏辛温相伍以和解表里；补泻兼施，参枣甘草扶正与柴芩祛邪相配以和其阴阳；升降相因，柴胡升散与半夏、生姜降逆相配以调畅气机。八味看似平常，实则层次分明、环环相扣，故能「和」少阳之枢。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"胸中烦而不呕去半夏、人参，加瓜蒌实；渴去半夏，加天花粉；腹中痛去黄芩，加芍药；胁下痞硬去大枣，加牡蛎；心下悸小便不利去黄芩，加茯苓；咳去人参、大枣、生姜，加五味子、干姜；热入血室加刺血（血府逐瘀汤）、丹皮、赤芍；疟疾加常山、草果；胆囊炎加郁金、金钱草、蒲公英；乳腺增生加香附、郁金、橘核；更年期综合征加浮小麦、百合、甘草。临床用于感冒、流行性感冒、疟疾、急慢性胆囊炎、急性胰腺炎、各型肝炎、胸膜炎、肋间神经痛、乳腺增生、经期感冒、更年期综合征等属少阳证者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"阴虚血少、肝阳上亢者慎用，柴胡升散易耗伤阴血；肝阳上亢之头痛眩晕、烦躁易怒者不宜单用。阴虚有汗、阳虚自汗者当慎用。服药期间忌食生冷辛辣、酒酪及寒凉之品。柴胡用量宜遵古方比例（重用柴胡 24g），但体虚者当酌减且不可久服。肝硬化、肝功能严重异常者使用须在医师严密指导下。"},{"type":"quote","text":"伤寒五六日中风，往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞硬，或心下悸小便不利，或不渴身有微热，或咳者，小柴胡汤主之。","source":"《伤寒论》卷三·辨太阳阳明病脉证并治"},{"type":"keypoints","title":"掌握要点","items":["和解少阳第一方，主治往来寒热、胸胁苦满、默默不欲饮食、脉弦","柴胡君（透邪）、黄芩臣（清热），一散一清为和解核心","姜夏降逆和胃，参枣甘草扶正祛邪，寒热并用、补泻兼施","「但见一证便是，不必悉具」；阴虚血少、肝阳上亢者慎用"]}]},{"id":"xiaoyao-san","title":"逍遥散","subtitle":"《太平惠民和剂局方》· 柴胡 当归 白芍 白术 茯苓 炙甘草 煨姜 薄荷","category":"和解剂","tags":["疏肝解郁","养血健脾","肝郁血虚"],"meta":[{"label":"出处","value":"《太平惠民和剂局方》卷九·治妇人诸疾（源出《医方集解》）"},{"label":"组成","value":"柴胡 9g，当归 9g，白芍 9g，白术 9g，茯苓 9g，炙甘草 5g，煨姜 3 片，薄荷 3g"},{"label":"用法","value":"上为粗末，每服 6g，水一大盏，去滓热服，不拘时候"},{"label":"功用","value":"疏肝解郁，养血健脾"},{"label":"主治","value":"肝郁血虚脾弱证。两胁作痛，头痛目眩，口燥咽干，神疲食少，或往来寒热，或月经不调，乳房胀痛，舌淡红苔薄白，脉弦而虚"}],"image":"","imageHint":"逍遥","summary":"逍遥散为《太平惠民和剂局方》疏肝解郁、养血健脾之代表方，主治肝郁血虚脾弱之证。柴胡为君，疏肝解郁、条达肝气；当归、白芍养血柔肝、缓急止痛为臣；白术、茯苓、炙甘草健脾益气、渗湿止泻，煨姜温胃和中，薄荷少许助柴胡疏散郁遏之气、透达肝经郁热为佐使。全方肝脾同调、气血兼顾，疏肝而不耗血，健脾而不壅滞，为妇科调经之名方。临床用于月经不调、乳腺增生、抑郁症、焦虑症、慢性肝炎、乳腺纤维瘤、更年期综合征等属肝郁血虚脾弱者。","blocks":[{"type":"paragraph","text":"情志不遂则肝气郁结，横逆犯脾，故两胁胀痛、神疲食少；肝郁化火则头痛目眩、口燥咽干；肝血不足则月经不调、乳房胀痛；血虚则舌淡红、脉弦而虚。其病机特点为「肝郁为主，血虚为本，脾弱为标」。治当疏肝解郁以治标，养血健脾以治本。逍遥散气味平淡，疏肝而不伤肝，养血而不滞血，故能久服而有效，为调治妇科情志病与慢性病之良方。"},{"type":"table","caption":"逍遥散君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["柴胡","君：疏肝解郁，条达肝气，使郁热得以透达","9g"],["当归","臣：养血和血，柔肝止痛，且使肝体得养","9g"],["白芍","臣：养血敛阴、柔肝缓急，与当归共养肝血","9g"],["白术、茯苓、炙甘草","佐：健脾益气、渗湿止泻，培土以制木","9g／9g／5g"],["煨姜","佐：温胃和中，助白术、茯苓健脾","3 片"],["薄荷","使：少许助柴胡疏散郁遏之气，透达肝经郁热","3g"]]},{"type":"paragraph","text":"本方配伍深得「肝脾同治、气血兼顾」之旨。柴胡苦辛微寒，疏肝解郁、条达气机，使郁滞得散、郁热得透，为君。当归甘辛温润，养血和血、调经止痛；白芍酸苦微寒，养血敛阴、柔肝缓急；当归偏于行、白芍偏于敛，二药相合则养血柔肝而不滞不涩，共为臣，直接针对肝郁血虚之本。白术苦甘温，健脾燥湿；茯苓甘淡，健脾渗湿；炙甘草甘温，益气和中、缓肝急，三药即四君子汤去参而加草之义，健脾益气以培土，脾气健运则肝木得抑、气血得生，为佐。煨姜温胃和中，助白术、茯苓运脾，且制薄荷之凉；薄荷少许，助柴胡疏散郁遏之气、透达肝经郁热，又监制全方温补之滞，二药相伍为使。综观全方：柴胡疏肝而不伤阴，当归白芍养血而不碍气，白术茯苓健脾而不壅滞，薄荷少许而清郁热。疏肝与养血并行、健脾与理气相合，故能「肝脾一和，气血自调」，为和法之典范。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"肝郁化火加牡丹皮、栀子（丹栀逍遥散）；血虚生热加生地、牡丹皮；脾虚甚加人参、茯苓（加味逍遥散）；乳胀加橘核、橘皮、王不留行、路路通；痛经加香附、延胡索、川牛膝；闭经加桃仁、红花、益母草；失眠加酸枣仁、柏子仁、合欢皮；抑郁焦虑加合欢花、郁金、石菖蒲；慢性肝炎加郁金、丹参、板蓝根；乳腺增生加夏枯草、浙贝母、橘核。临床用于月经不调、乳腺增生、乳腺纤维瘤、抑郁症、焦虑症、神经衰弱、慢性肝炎、更年期综合征、肠易激综合征等属肝郁血虚脾弱者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方多甘温养血，湿热内蕴、舌苔黄厚腻、脘腹胀闷者不宜；阴虚阳亢、肝火上炎之头痛眩晕、烦躁易怒者慎用，因柴胡、薄荷升散升阳，可能助火。孕妇慎用。服药期间注意调畅情志、避免精神刺激，方能见效；单靠药物而郁怒不解者，须配合心理疏导。若服用后出现口干、咽痛等上火之象，多为郁热未清或剂量偏当，应请医师调整。"},{"type":"quote","text":"治血虚劳倦，五心烦热，肢体疼痛，头目昏重，心忪颊赤，口燥咽干，妇人月水不调，痨瘵骨蒸，痈疽疮毒，咳嗽痰血，肠风痔漏，饮食劳倦，水土不服等证。","source":"《太平惠民和剂局方》卷九·治妇人诸疾"},{"type":"keypoints","title":"掌握要点","items":["疏肝解郁、养血健脾，主治肝郁血虚脾弱：胁痛、眩晕、口燥、神疲食少、月经不调","柴胡为君疏肝，当归白芍为臣养血柔肝，术苓草姜健脾，薄荷少许透郁热","配伍核心是「肝脾同调、气血兼顾」，疏肝不耗血、健脾不壅滞","湿热、阴虚阳亢者慎用；须配合情志调摄"]}]},{"id":"banxia-xiexin-tang","title":"半夏泻心汤","subtitle":"《伤寒论》· 半夏 黄芩 干姜 人参 炙甘草 黄连 大枣","category":"和解剂","tags":["寒热平调","消痞散结","脾胃不和"],"meta":[{"label":"出处","value":"《伤寒论》卷三·辨太阳阳明病脉证并治"},{"label":"组成","value":"半夏 12g，黄芩 9g，干姜 9g，人参 9g，炙甘草 9g，黄连 3g，大枣 4 枚"},{"label":"用法","value":"上七味，以水一斗，煮取六升，去滓再煎，取三升，温服一升，日三服"},{"label":"功用","value":"寒热平调，消痞散结"},{"label":"主治","value":"寒热错杂之痞证。心下痞满而不痛，呕吐，肠鸣下利，舌苔腻而微黄，脉弦数或濡"}],"image":"","imageHint":"半夏","summary":"半夏泻心汤为《伤寒论》寒热平调、消痞散结之代表方，主治脾胃不和、寒热错杂之痞证。半夏为君，散结除痞、降逆止呕；黄芩、黄连苦寒清热，干姜辛热散寒，三药合用调其寒热为臣；人参、大枣、炙甘草补中益气、健脾和中为佐使。全方辛开苦降、寒热平调、补泻兼施，去其痞而复其升降，为和法中「寒热并用、苦辛通降」之典范。临床用于急慢性胃炎、消化性溃疡、慢性腹泻、幽门螺杆菌感染、肠易激综合征、口腔溃疡等属中气虚弱、寒热错杂者。","blocks":[{"type":"paragraph","text":"误下伤中，脾胃气虚，中焦失于升降，邪气乘虚内陷，与宿寒宿热互结于心下，气机阻滞故心下痞满而按之柔软不痛；胃气上逆故呕吐；脾失健运故肠鸣下利；寒热错杂、津液不布故苔腻而微黄、脉弦数而濡。此证非纯寒非纯热，故不可专事辛温或苦寒，必须寒热并用、苦辛通降、虚实兼顾。"},{"type":"table","caption":"半夏泻心汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["半夏","君：散结除痞，降逆止呕，为治痞要药","12g"],["黄芩、黄连","臣：苦寒清热，干泄中焦之热","9g／3g"],["干姜","臣：辛热散寒，温运中阳，制芩连之苦寒","9g"],["人参、大枣、炙甘草","佐使：补中益气、健脾和中，扶正以助升降","9g／4 枚／9g"]]},{"type":"paragraph","text":"本方配伍之精，全在「辛开苦降、寒热平调、补泻兼施」十字。半夏辛温滑散，开结散痞、降逆止呕，为君，直治痞满呕吐之标。黄芩苦寒、黄连苦寒，清泄中焦郁热，为臣；干姜辛热，散寒温中，既助半夏辛开，又制芩连苦寒之过，是为臣。三药相合，辛以通之、苦以降之、热以温之、寒以清之，使中焦寒热各归其位，气机升降自复。人参、大枣甘温，炙甘草甘温，补中益气、健脾和中，为佐使，扶脾胃之虚以助运化，且调和诸药。综观全方：半夏、干姜辛开，黄芩、黄连苦降，一升一降使胃气得降、脾气得升；参、枣、草甘温补虚，与辛开苦降并行不悖，使祛邪而不伤正。需特别体会者，全方用大枣、炙甘草、人参三味甘温之品看似助热，实则正因中气已虚，非此不能固本；又「去滓再煎」一味，取其水气尽而药性醇和，缓和辛开苦降之峻而寓和法之意。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"呕甚加生姜、竹茹；痞满甚加枳实、枳壳；下利甚加诃子、薏苡仁、炮姜；胃痛加白芍、甘草、延胡索；口苦苔黄甚加蒲公英、连翘；Hp 阳性加蒲公英、连翘、仙鹤草、白及；嗳气加旋覆花、代赭石；食积加焦三仙、莱菔子；胃阴虚去干姜，加石斛、麦冬。临床用于急慢性胃炎、消化性溃疡、幽门螺杆菌相关性胃炎、功能性消化不良、肠易激综合征、慢性腹泻、复发性口腔溃疡等属中气虚弱、寒热错杂者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方以中气虚、寒热错杂为使用前提，若纯属脾胃虚寒而呕吐下利、苔白不黄者，当用理中汤；若属实热痞满、大便秘结、苔黄厚者，应改用大黄牡丹汤或泻心汤类；若胃痛拒按、气滞明显者，须先理气。半夏有毒，须用炮制合规之品，生半夏、内服半夏须严格炮制，不可用生品。服药期间忌食生冷油腻、辛辣酒酪及豆类制品，胃病患者宜少量多餐、餐后即卧或反之择宜。"},{"type":"quote","text":"伤寒五六日，呕而发热者，柴胡汤证具，而以他药下之，柴胡证仍在者，复与柴胡汤。此已下之，柴胡证仍在者，呕不止者，可与半夏泻心汤。","source":"《伤寒论》卷三·辨太阳阳明病脉证并治"},{"type":"keypoints","title":"掌握要点","items":["寒热平调、消痞散结，主治心下痞满不痛、呕吐、肠鸣下利、苔腻微黄","半夏为君开结降逆，芩连苦寒清热，干姜辛热散寒","参枣草甘温补中，使祛邪不伤正；「去滓再煎」取其醇和","纯寒纯热、实热痞满者均不可用；半夏须用炮制合规之品"]}]},{"id":"yueju-wan","title":"越鞠丸","subtitle":"《丹溪心法》· 香附 川芎 苍术 栀子 神曲","category":"理气剂","tags":["行气解郁","疏肝理脾","六郁并治"],"meta":[{"label":"出处","value":"《丹溪心法》卷二·六郁（源出《素问·丹溪心法》）"},{"label":"组成","value":"香附 10g，川芎 10g，苍术 10g，栀子 10g，神曲 10g"},{"label":"用法","value":"上为末，水泛为丸，每服 6～9g"},{"label":"功用","value":"行气解郁"},{"label":"主治","value":"六郁证。胸膈痞闷，脘腹胀痛，嗳腐吞酸，恶心呕吐，饮食不消，舌苔腻，脉弦"}],"image":"","imageHint":"越鞠","summary":"越鞠丸为《丹溪心法》行气解郁之代表方，主治气、血、痰、火、湿、食六郁并见之证。香附开郁行气、疏肝解郁为君；川芎活血行气，治血郁；苍术燥湿运脾，治湿郁；栀子清热泻火，治火郁；神曲消食导滞，治食郁为佐使。丹溪谓「越鞠者，越发其郁也」，五味药升降浮沉各归其经，共奏行气解郁、上下分消之功，方虽小而义全，为「气郁为先」之代表方。临床用于功能性消化不良、胆囊炎、抑郁性消化不良、胃神经官能症、更年期综合征等属六郁者。","blocks":[{"type":"paragraph","text":"丹溪云「气血冲和，万病不生，一有怫郁，诸病生焉」。六郁之中，气郁为先，气郁则血行不畅而成血郁，津液不布而成痰郁，气郁化火而成火郁，脾失健运而成湿郁、食郁。故治郁当以行气为先，气行则血行、痰消、火降、湿化、食消。本方五味药各治一郁而以香附一味统领，正合「治郁先治气」之旨。"},{"type":"table","caption":"越鞠丸君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["香附","君：开郁行气，疏肝解郁，理气调中，为治气郁之要药","10g"],["川芎","臣：活血行气，祛风止痛，治血郁","10g"],["栀子","臣：清热泻火，治火郁","10g"],["苍术","臣：燥湿运脾，治湿郁","10g"],["神曲","使：消食导滞，治食郁","10g"]]},{"type":"paragraph","text":"本方配伍简而精妙，方虽仅五味，却暗合六郁之机。香附辛微苦微温，疏肝理气、解郁止痛，为治气郁之要药，为君；丹溪认为「气郁则血亦滞」，故川芎辛温走而不守，活血行气、祛风止痛以治血郁；苍术苦温燥烈，燥湿运脾、健脾除湿以治湿郁；栀子苦寒清降，清热泻火以治火郁，此四药各有所主，同为臣。神曲甘辛温，消食和胃、导滞化积，以治食郁，并可调和诸药之峻，为使。综观全方：五药分治气、血、湿、火、食五郁，香附一味主气郁而统领全方；川芎之升散与栀子之苦降相配，一升一降使气机通畅；苍术燥湿健运以助香附行气之力，神曲消导以助脾胃运化。故丹溪谓「越鞠丸统治六郁」，随证加减而效如神手。气郁得解则血郁自去、痰湿自消、食郁自化，实为「治郁先治气」的具体体现。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"气郁甚加柴胡、郁金、青皮；血郁甚加桃仁、红花、丹参；火郁甚加黄芩、黄连、青黛；湿郁甚加茯苓、薏苡仁、大腹皮；食郁甚加山楂、麦芽、莱菔子；痰郁加半夏、瓜蒌、贝母；胁痛加延胡索、川楝子；胃痛加白芍、甘草；心烦失眠加酸枣仁、合欢皮。临床用于功能性消化不良、胆囊炎、胃神经官能症、抑郁性消化不良、肠易激综合征、更年期综合征、痛经、乳房胀痛等属气郁为主而六郁并见者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方多辛香燥烈、耗气伤阴，气血虚弱、阴虚火旺者慎用；脾胃虚寒、畏寒便溏者当减苍术并加干姜、白术；孕妇慎用。服药期间忌食油腻、难以消化之品，宜饮食清淡、少量多餐，并注意保持心情舒畅。本方以丸剂为宜，若改汤剂则药力较峻，须由医师掌握剂量。"},{"type":"quote","text":"越鞠丸，治六郁：气郁、血郁、痰郁、火郁、湿郁、食郁。","source":"《丹溪心法》卷二·六郁"},{"type":"keypoints","title":"掌握要点","items":["行气解郁第一方，主治六郁并见，以气郁为先","香附为君治气郁，川芎治血郁、苍术治湿郁、栀子治火郁、神曲治食郁","配伍特点：五药各治一郁，一升一降、气行则诸郁自解","气血虚弱、阴虚火旺、脾胃虚寒者慎用，忌油腻难消之食"]}]},{"id":"gualou-xiebai-banxia-tang","title":"瓜蒌薤白半夏汤","subtitle":"《金匮要略》· 瓜蒌实 薤白 半夏 白酒","category":"理气剂","tags":["通阳散结","行气祛痰","胸痹心痛"],"meta":[{"label":"出处","value":"《金匮要略》卷五·胸痹心痛短气病脉证治"},{"label":"组成","value":"瓜蒌实 12g（捣），薤白 9g，半夏 12g（洗），白酒适量同煎"},{"label":"用法","value":"上三味，以水五升，煮取四升，温服一升，日三服"},{"label":"功用","value":"通阳散结，行气祛痰"},{"label":"主治","value":"胸痹心痛痰浊壅盛证。胸闷而痛，甚或心痛彻背，背痛彻心，胸满气短，咳痰白黏，舌苔白腻，脉沉弦或紧"}],"image":"","imageHint":"瓜蒌","summary":"瓜蒌薤白半夏汤为《金匮要略》通阳散结、行气祛痰之代表方，主治胸痹心痛之痰浊壅盛证。瓜蒌实为君，宽胸散结、化痰下气；薤白辛散苦降温通，为臣，通阳散结、行气止痛；半夏燥湿化痰、降逆散结为佐；白酒辛温通阳、行气活血，助薤白通脉为使。全方辛温通阳、化痰散结、行气活血并行，为治疗胸痹心痛痰浊壅盛之代表方。临床用于冠心病心绞痛、心肌梗死恢复期、心律失常、慢性支气管炎、肺气肿、肋间神经痛等属胸阳不振、痰浊壅盛者。","blocks":[{"type":"paragraph","text":"胸痹心痛之病机，为上焦阳虚、阴寒痰浊上乘。胸阳不振则阴霾蔽塞，故胸闷而痛；痰浊壅盛则咳痰白黏、胸满气短；阴寒痹阻、心脉不通则心痛彻背、背痛彻心；苔白腻、脉沉弦或紧，为寒痰内停之征。治当通阳散结、行气祛痰，宣通胸中阳气，使痰浊得化、胸脉得通。"},{"type":"table","caption":"瓜蒌薤白半夏汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["瓜蒌实（捣）","君：宽胸散结，化痰下气，利气开结","12g"],["薤白","臣：辛散苦降温通，通阳散结、行气止痛","9g"],["半夏（洗）","佐：燥湿化痰，降逆散结，助瓜蒌开结","12g"],["白酒","使：辛温通阳，行气活血，助薤白通脉止痛","适量"]]},{"type":"paragraph","text":"本方配伍以「通阳」为核心而兼化痰、行气、活血。瓜蒌实甘寒滑润，宽胸散结、化痰下气，为治胸痹要药，为君。薤白辛苦微温，辛散苦降而温通，最善通阳散结、行气止痛，为臣；它与瓜蒌实相合，一润一散，一化痰浊、一通阳气，相须为用，正合仲景「瓜蒌薤白白酒汤」之法而力专于祛痰。半夏辛温燥烈，燥湿化痰、降逆散结，为佐，助瓜蒌、薤白开结除痞、化痰降逆。白酒辛温，宣通血脉、行气祛寒，助薤白温通胸阳，并可引药上行达胸，为使。综观全方：瓜蒌主化痰，薤白主通阳，半夏主降逆燥湿，白酒主宣通血脉。四药合用，痰浊得化、胸阳得通、气机得畅、血脉得和，故能治「胸痹不得卧，心痛彻背」之重证。较之瓜蒌薤白白酒汤，本方增半夏一味，祛痰之力更峻，故用于痰浊壅盛而气短咳痰者。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"心痛甚加半夏量、附子、桂枝（近效失笑散意）；血瘀明显加丹参、川芎、赤芍、三七；气滞加枳实、枳壳、檀香；寒重加桂枝、附子、细辛；痰热加黄连、竹茹、胆南星；气短乏力加黄芪、党参；喘息加杏仁、紫苏子；失眠加酸枣仁、柏子仁。临床用于冠心病心绞痛、心肌梗死缓解期、心律失常、慢阻肺、肺气肿、慢性支气管炎、肋间神经痛等属胸阳不振、痰浊壅盛者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方辛温通阳、燥湿祛痰，阴虚火旺、痰热内蕴者不宜，误用可致口干咽燥、心烦失眠；孕妇慎用。服用期间忌食生冷、肥甘厚味及酒类（若用白酒煎者应遵医嘱用量）；胸痛剧烈、持续不解、伴大汗、面色苍白者，可能为急性心肌梗死，须立即急诊就医，不可仅依赖汤剂。心脏病患者使用须在专科医师指导下，配合抗凝、降脂等规范治疗。"},{"type":"quote","text":"胸痹不得卧，心痛彻背者，瓜蒌薤白半夏汤主之。","source":"《金匮要略》卷五·胸痹心痛短气病脉证治"},{"type":"keypoints","title":"掌握要点","items":["通阳散结、行气祛痰，主治胸痹心痛痰浊壅盛：胸闷痛、痛彻背、气短咳痰、苔白腻","瓜蒌为君宽胸化痰，薤白为臣通阳行气，半夏祛痰降逆，白酒通脉","较瓜蒌薤白白酒汤增半夏，祛痰力峻而通阳力稍减","阴虚火旺、痰热内蕴者忌用；胸痛剧烈伴大汗者须急诊"]}]},{"id":"xuanfu-daizhe-tang","title":"旋覆代赭汤","subtitle":"《伤寒论》· 旋覆花 代赭石 半夏 生姜 人参 甘草 大枣","category":"理气剂","tags":["降逆化痰","益气和胃","胃虚痰阻气逆"],"meta":[{"label":"出处","value":"《伤寒论》卷三·辨太阳阳明病脉证并治"},{"label":"组成","value":"旋覆花 9g（包煎），代赭石 9g（先煎），半夏 9g，生姜 15g，人参 3g，炙甘草 9g，大枣 4 枚"},{"label":"用法","value":"上七味，以水一斗，煮取三升，去滓，温服一升，日三服"},{"label":"功用","value":"降逆化痰，益气和胃"},{"label":"主治","value":"胃虚痰阻气逆证。心下痞硬，噫气不除，或反胃呕吐，吐涎沫，舌淡苔白滑，脉弦而虚"}],"image":"","imageHint":"旋覆","summary":"旋覆代赭汤为《伤寒论》降逆化痰、益气和胃之代表方，主治胃虚痰阻气逆证。旋覆花为君，咸温性降，下气消痰、行水止呕；代赭石为臣，苦寒重镇，降逆止呕、化痰软坚；半夏、生姜化痰散结、降逆止呕为佐；人参、甘草、大枣益气和中、扶正为佐使。全方标本兼治，补泻并施，重用生姜伍旋覆、代赭以降逆和胃，为治噫气、呃逆、呕吐之良方。临床用于胃神经官能症、幽门不全梗阻、神经性呕吐、膈肌痉挛、妊娠剧吐、顽固性呃逆等属胃虚痰阻者。","blocks":[{"type":"paragraph","text":"伤寒误吐误下，胃气大虚，痰浊内生，痰随气升，气逆不降，故心下痞硬而硬软不痛、噫气不除，或反胃呕吐、吐涎沫；舌淡苔白滑、脉弦而虚，为胃虚痰阻、气逆不降之征。治当降逆化痰以治标，益气和胃以治本。旋覆代赭汤重用生姜，既助半夏化痰，又协旋覆、代赭降逆，且制半夏之毒，散水气而不伤正，是本方配伍的一大特色。"},{"type":"table","caption":"旋覆代赭汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["旋覆花（包煎）","君：下气消痰，行水止呕，降逆","9g"],["代赭石（先煎）","臣：重镇降逆，化痰软坚，助旋覆降胃气","9g"],["半夏、生姜","佐：化痰散结、降逆止呕，重用生姜以散水气","9g／15g"],["人参、炙甘草、大枣","佐使：益气和中、扶正以助降逆","3g／9g／4 枚"]]},{"type":"paragraph","text":"本方配伍以「标本兼顾、补泻并施、降逆和胃」为法。旋覆花咸温而性降，既能下气消痰、行水止呕，又能降逆，是治痰阻气逆、噫气呕吐之要药，为君。代赭石苦寒质重，沉降下行，重镇降逆、化痰软坚，既助旋覆以降逆，又制其辛散之性，为臣。二药相须，一走一守、一温一寒，降逆之力相得益彰。半夏辛温，燥湿化痰、降逆止呕；生姜辛温，本方重用至 15g，一则助半夏、旋覆化痰散结，二则散水气以助止呕，三则制半夏之毒，四则防代赭石之寒，二药为佐。人参甘温，益气和中以扶胃气之虚；炙甘草甘温，益气缓急、调和诸药；大枣甘温，补脾益气、缓和姜夏之峻，三药为佐使，与姜夏相伍则益气和胃之力全。综观全方：旋覆、代赭、半夏、生姜四味重在降逆化痰以治标，参、草、枣三味重在益气和胃以治本；标本兼顾而以降逆为先，故对「心下痞硬、噫气不除」之证最为合拍。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"呃逆甚加丁香、柿蒂、沉香；呕吐加白术、茯苓、藿香；反流加海螵蛸、瓦楞子、浙贝母；痰多加陈皮、茯苓、瓜蒌；呕血加白及、三七；胆汁返流加郁金、金钱草；化疗后呕吐加竹茹、石斛、砂仁。临床用于胃神经官能症、幽门不全梗阻、功能性呕吐、神经性呕吐、顽固性呃逆、妊娠剧吐、化疗后胃肠反应、膈肌痉挛等属胃虚痰阻气逆者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"代赭石重镇苦寒，孕妇慎用；脾胃虚寒而无痰浊者不宜，恐更伤胃气；胃热呕吐、舌红苔黄者慎用，胃阴不足者亦当兼顾养阴。旋覆花有绒毛刺激咽喉，包煎为宜，不宜直接入煎。服药期间忌食生冷、油腻、辛辣及易产气之品，宜少量多餐。顽固性呕吐、呃逆日久不愈者，须查明器质性病因，不可一味降逆而延误诊治。"},{"type":"quote","text":"伤寒，吐而逆者，旋覆代赭汤主之。","source":"《伤寒论》卷三·辨太阳阳明病脉证并治"},{"type":"keypoints","title":"掌握要点","items":["降逆化痰、益气和胃，主治胃虚痰阻气逆：心下痞硬、噫气不除、反胃呕吐、苔白滑","旋覆为君降逆消痰，代赭为臣重镇降逆，半夏生姜化痰止呕","重用生姜 15g 既助化痰又制半夏毒、散水气，是本方特色","参草枣益气和胃以治本；孕妇及无痰浊者慎用，旋覆花宜包煎"]}]},{"id":"erchen-tang","title":"二陈汤","subtitle":"《太平惠民和剂局方》· 半夏 陈皮 茯苓 甘草 生姜 乌梅","category":"化痰祛湿剂","tags":["燥湿化痰","理气和中","湿痰证"],"meta":[{"label":"出处","value":"《太平惠民和剂局方》卷四·治一切气"},{"label":"组成","value":"半夏 15g（汤洗七次），陈皮 15g，茯苓 9g，炙甘草 5g，生姜 3 片，大枣 1 枚，乌梅 1 个"},{"label":"用法","value":"上为粗末，每服 6g，水一盏半，生姜三片，枣一个，同煎至七分，去滓温服，不拘时候"},{"label":"功用","value":"燥湿化痰，理气和中"},{"label":"主治","value":"湿痰证。咳嗽痰多色白易咯，胸膈痞闷，恶心呕吐，肢体困重，头眩心悸，舌苔白滑或腻，脉滑"}],"image":"","imageHint":"二陈","summary":"二陈汤为《太平惠民和剂局方》燥湿化痰、理气和中之代表方，主治湿痰证。半夏为君，燥湿化痰、降逆和胃；陈皮为臣，理气行滞、燥湿化痰，二者相合为「治痰先治气」之配；茯苓健脾渗湿为佐，湿去则痰无由生；生姜降逆化痰、解半夏毒，炙甘草健脾和中，乌梅少许收敛肺气、防辛燥太过，大枣益气和中为佐使。全方温燥适中、标本兼治，为祛痰之总方。临床用于慢性支气管炎、慢性胃炎、妊娠呕吐、梅尼埃病、神经性呕吐等属湿痰者。","blocks":[{"type":"paragraph","text":"脾为生痰之源，肺为贮痰之器。脾失健运则水湿停聚而成痰，痰湿上渍于肺则咳嗽痰多色白易咯；痰阻中焦、气机不畅则胸膈痞闷、恶心呕吐；湿困清阳则肢体困重、头眩；痰扰心神则心悸；苔白滑或腻、脉滑为湿痰之征。治当燥湿化痰、理气和中。二陈汤温燥而不烈，化痰而不伤正，为祛痰剂之基础方，后世化痰诸方多由此化裁。"},{"type":"table","caption":"二陈汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["半夏（汤洗）","君：燥湿化痰，降逆和胃，为治湿痰要药","15g"],["陈皮","臣：理气行滞，燥湿化痰，与半夏相配治痰先治气","15g"],["茯苓","佐：健脾渗湿，湿去则痰无由生","9g"],["生姜","佐：降逆化痰止呕，并制半夏之毒","3 片"],["炙甘草","佐：健脾和中，调和诸药","5g"],["乌梅、大枣","使：收敛肺气、益气和中，防辛燥太过并调和脾胃","1 个／1 枚"]]},{"type":"paragraph","text":"本方配伍之要，在于「治痰先治气」。半夏辛温而燥，燥湿化痰、降逆和旋，为治湿痰之要药，为君。陈皮苦辛温，理气行滞、燥湿化痰，二药相合，半夏得陈皮则气顺而痰行，陈皮得半夏则燥湿而化痰，一燥一润、一行一降，共为君臣，故称「二陈」。茯苓甘淡，健脾渗湿，为佐；脾健则湿无所生，湿去则痰无由生，治本之举不可少。生姜辛温，降逆化痰、止呕，且制半夏之毒，为佐。炙甘草健脾和中、调和诸药；乌梅少许收敛肺气，防辛燥太过而伤肺，并可与甘草相配酸甘化阴、化痰而不伤阴；大枣益气和中、调和脾胃，二者为佐使。综观全方：半夏、陈皮、茯苓三味为治痰主体，姜、草、枣、梅四味则为佐使调和之品。燥湿化痰而不伤阴、理气和中而不耗气，化痰与健脾并行，标本兼治，故为治痰之总方、治湿痰之代表。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"加白术、天麻为半夏白术天麻汤，治风痰眩晕；加胆南星、枳实为导痰汤，治顽痰胶结；加人参、白术为六君子汤，治气虚痰湿；加附子、细辛为附子半夏汤，治寒痰；加竹茹、枳实为温胆汤，治胆郁痰扰；加苍术为平胃散，治湿浊中阻；痰多加瓜蒌、贝母；眩晕加天麻、钩藤；呕吐加竹茹、代赭石；咳嗽甚加紫菀、款冬花。临床用于慢性支气管炎、支气管哮喘缓解期、慢性胃炎、妊娠呕吐、梅尼埃病、神经性呕吐、肥胖症等属湿痰者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方温燥，属辛温苦燥之品，阴虚燥咳、痰中带血、痰少而黏、舌红少津者禁用；咯血、肺痨、吐血者忌用；热痰、痰黄稠黏、苔黄腻、脉滑数者当改用清化痰热之剂。孕妇慎用。半夏须用炮制合规之品，生半夏不可内服。服药期间忌食生冷、肥甘厚味及酒类，以免助湿生痰。"},{"type":"quote","text":"治痰饮为患，或呕吐恶心，或头眩心悸，或中脘不快，或发为寒热，或因食生冷，脾胃不和。","source":"《太平惠民和剂局方》卷四·治一切气"},{"type":"keypoints","title":"掌握要点","items":["燥湿化痰、理气和中，为治痰总方，主治湿痰：痰多色白、胸闷、呕恶、苔白滑、脉滑","半夏为君、陈皮为臣，「治痰先治气」；茯苓健脾渗湿治本","姜制半夏之毒、乌梅收敛肺气、甘草大枣和中，调和诸药","阴虚燥咳、痰中带血、热痰者禁用；忌生冷肥甘酒类"]}]},{"id":"wendan-tang","title":"温胆汤","subtitle":"《三因极一病证方论》· 半夏 竹茹 枳实 陈皮 甘草 茯苓 生姜 大枣","category":"化痰祛湿剂","tags":["理气化痰","清胆和胃","胆郁痰扰"],"meta":[{"label":"出处","value":"《三因极一病证方论》卷九·惊悸怔忡（源自《备急千金要方》温胆汤）"},{"label":"组成","value":"半夏 6g，竹茹 6g，枳实 6g，陈皮 9g，炙甘草 3g，茯苓 5g，生姜 5 片，大枣 1 枚"},{"label":"用法","value":"上为㕮咀，每服 6g，水一盏半，生姜五片，枣一枚，煎至七分，去滓，食前温服"},{"label":"功用","value":"理气化痰，和胃利胆"},{"label":"主治","value":"胆郁痰扰证。胆怯易惊，虚烦不眠，虚烦不宁，呕吐呃逆，眩晕癫痫，苔白腻，脉弦滑"}],"image":"","imageHint":"温胆","summary":"温胆汤为《三因极一病证方论》理气化痰、和胃利胆之代表方，主治胆郁痰扰之证。半夏为君，燥湿化痰、和胃止呕；竹茹为臣，清热化痰、除烦止呕；枳实、陈皮理气行滞、消痰利膈为佐；茯苓健脾渗湿，宁心安神；生姜降逆止呕、化痰，大枣调和脾胃为佐使。全方理气化痰、清胆和胃，使胆气得以温和而不亢，故名「温胆」。临床用于神经症、精神分裂症、更年期综合征、神经性呕吐、梅尼埃病、失眠、癫痫等属胆郁痰扰者。","blocks":[{"type":"paragraph","text":"胆为中正之官，主决断，与心神相通。胆气郁而不升，疏泄失常，则气郁生痰；痰随胆气上扰心神，故胆怯易惊、虚烦不眠；痰热上扰则眩晕、呕逆、呃逆；甚则痰迷心窍而见癫痫。苔白腻、脉弦滑为痰气郁结之征。治当理气化痰、和胃利胆。方名「温胆」者，非用温药温胆，而是使胆气温和、恢复决断之功能，学者当会此意。"},{"type":"table","caption":"温胆汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["半夏","君：燥湿化痰，和胃止呕，治胆郁痰扰之标","6g"],["竹茹","臣：清热化痰，除烦止呕，制半夏之温燥","6g"],["枳实、陈皮","臣佐：理气行滞，化痰利膈，使气顺痰消","各 6g／9g"],["茯苓","佐：健脾渗湿，宁心安神","5g"],["生姜","佐：降逆化痰止呕，制半夏之毒","5 片"],["炙甘草、大枣","使：益气和中，调和诸药，兼制竹茹苦寒","3g／1 枚"]]},{"type":"paragraph","text":"本方系二陈汤去乌梅、减半夏用量，加竹茹、枳实、茯苓而成，立法由「燥湿化痰」变为「理气化痰、和胃利胆」。半夏辛温，燥湿化痰、和胃止呕，为君；竹茹甘微寒，清热化痰、除烦止呕，兼制半夏温燥之性，为臣，二者相合，一温一凉，痰热得化而胆胃气和。枳实苦辛微寒，破气消积、化痰散痞；陈皮辛苦温，理气行滞、燥湿化痰，二药为臣佐，与半夏、竹茹相配则理气化痰之力尤强，所谓「气顺则痰消」。茯苓健脾渗湿、宁心安神，为佐，兼治胆怯心悸失眠。生姜降逆化痰止呕、制约半夏之毒，大枣、炙甘草益气和中、调和诸药并制竹茹之寒，为佐使。综观全方：半夏、竹茹一温一凉，化痰而不偏；枳实、陈皮理气，气顺则痰消；茯苓健脾宁心，标本兼顾；姜枣草和胃调中而护胃气。全方清而不寒、温而不燥，化痰与清胆并行，故能使郁遏之胆气得以条达，恢复「胆主决断」之功能，故名温胆汤。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"热重加黄连、黄芩、栀子；痰热扰心加黄连、朱砂（黄连温胆汤）；惊悸加珍珠母、龙齿、磁石；失眠加酸枣仁、柏子仁、合欢皮；眩晕加天麻、钩藤、菊花；呕吐甚加生姜、藿香、佩兰；癫痫加胆南星、钩藤、僵蚕；抑郁加郁金、合欢花、百合；高血压加钩藤、石决明。临床用于神经症、失眠、焦虑症、精神分裂症、更年期综合征、神经性呕吐、梅尼埃病、癫痫、胃神经官能症等属胆郁痰扰者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"阴虚津亏、心火炽盛之失眠心悸不宜使用本方；脾胃虚寒者慎用，因枳实破气、半夏降逆之力较峻。孕妇慎用。服药期间忌食肥甘厚味、生冷及酒类，避免情志过度紧张与熬夜。若出现头晕、心慌、手抖等不适须停药就诊。精神症状明显者须配合心理治疗与精神科规范诊治，不可单靠中药。"},{"type":"quote","text":"治胆虚寒，眩悸呕恶，或吐酸水，或胸痞，或心烦不眠，或癫痫等证。","source":"《三因极一病证方论》卷九·惊悸怔忡"},{"type":"keypoints","title":"掌握要点","items":["理气化痰、和胃利胆，主治胆郁痰扰：胆怯易惊、虚烦不眠、呕逆眩晕、苔白腻、脉弦滑","半夏君、竹茹臣，一温一凉；枳实陈皮理气，茯苓健脾宁心","「温胆」非温药温胆，乃使胆气温和、恢复决断之职","阴虚津亏、心火炽盛者不宜；精神症状须配合规范诊治"]}]},{"id":"pingwei-san","title":"平胃散","subtitle":"《太平惠民和剂局方》· 苍术 厚朴 陈皮 甘草 生姜 大枣","category":"化痰祛湿剂","tags":["燥湿运脾","行气和胃","湿滞脾胃"],"meta":[{"label":"出处","value":"《太平惠民和剂局方》卷三·治一切气"},{"label":"组成","value":"苍术 12g，厚朴 9g，陈皮 9g，炙甘草 6g，生姜 2 片，大枣 2 枚"},{"label":"用法","value":"上为粗末，每服 6g，水一盏半，生姜二片，大枣二枚，同煎至七分，去滓温服"},{"label":"功用","value":"燥湿运脾，行气和胃"},{"label":"主治","value":"湿滞脾胃证。脘腹胀满，不思饮食，口淡无味，恶心呕吐，嗳气吞酸，肢体沉重，怠惰嗜卧，常多自利，舌苔白腻而厚，脉缓"}],"image":"","imageHint":"平胃","summary":"平胃散为《太平惠民和剂局方》燥湿运脾、行气和胃之代表方，主治湿滞脾胃证。苍术为君，燥湿运脾、健脾和胃；厚朴为臣，行气消积、燥湿除满；陈皮为佐，理气行滞、燥湿化痰；甘草为使，益脾和中、调和诸药；生姜、大枣助其和胃益气。全方苦辛温燥、行气燥湿并用，为「燥湿健脾」第一方，后世藿香正气散、不换金正气散、胃苓汤皆由此化裁。临床用于慢性胃炎、功能性消化不良、急慢性胃肠炎、传染性单核细胞增多症等属湿困脾胃者。","blocks":[{"type":"paragraph","text":"湿浊内阻，困遏脾土，运化失常，故脘腹胀满、不思饮食、口淡无味、恶心呕吐、嗳气吞酸；湿性重浊黏滞，故肢体沉重、怠惰嗜卧；水谷不化故常多自利；苔白厚腻、脉缓为湿盛之征。治当燥湿运脾，兼以行气和胃。平胃散重用苍术，取其燥湿运脾之力，湿去则脾运自健，气行则湿无所附。"},{"type":"table","caption":"平胃散君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["苍术","君：燥湿运脾，健脾和胃，为治湿浊之要药","12g"],["厚朴","臣：行气消积，燥湿除满","9g"],["陈皮","佐：理气行滞，燥湿化痰，助厚朴行气","9g"],["炙甘草","使：益脾和中，调和诸药，合苍术健脾","6g"],["生姜、大枣","使：和胃益气，调和营卫，助甘草和中","各 2 片／2 枚"]]},{"type":"paragraph","text":"本方配伍体现了「燥湿与行气并重、祛湿兼以健脾」之法。苍术苦温辛燥，燥湿运脾、健脾和胃，其燥湿之力远胜于白术，故重用为君，直治湿浊困脾之本。厚朴苦温，芳香燥湿，行气消积、除满，为臣；它一方面协助苍术燥湿，另一方面行气以治气滞痞满，其与苍术相伍，则「气行则湿化」而痞满自除。陈皮辛温，理气行滞、燥湿化痰，为佐；与厚朴相须为用，行气消滞之力愈强，并可防厚朴、苍术耗伤胃气。炙甘草甘温，益脾和中、调和诸药，既助苍术、健脾运湿，又使全方燥而不烈，为使。生姜温胃和中、醒脾开胃，大枣益气养血、调和脾胃，与甘草相合则调和营卫、扶助中气，均为佐使。综观全方：苍术燥湿为本，厚朴、陈皮行气为要，甘草、姜枣健脾和中以固护胃气；行气与燥湿相配，燥湿而不伤正、行气而不耗气，标本兼顾，故为燥湿运脾之基础方，仲景之后为「消导化积」与「化痰祛湿」诸方所取。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"表邪外感而湿滞脾胃者合藿香正气散；湿热并重加黄连、黄芩、茵陈（不换金正气散）；食积加神曲、山楂、麦芽；气滞加木香、砂仁、枳壳；痰多加半夏、茯苓；呕逆加藿香、半夏；寒湿加干姜、附子；菌痢加黄连、白头翁。临床用于慢性胃炎、功能性消化不良、急慢性胃肠炎、胃肠功能紊乱、传染性单核细胞增多症、口疮等属湿困脾胃者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方苦温燥烈，脾胃阴虚、舌红少苔、口干咽燥、大便干结者禁用；湿热并重、舌苔黄腻者不宜单用；孕妇慎用。服药期间忌食生冷、油腻、甜腻及不易消化之品，宜清淡饮食、少量多餐、细嚼慢咽。若服后出现口干、咽痛、便秘等津伤之象，当减苍术、厚朴用量或改为养阴之法。胃脘痛剧烈、伴消瘦、黑便者应先行胃镜检查排除器质性病变。"},{"type":"quote","text":"治脾胃不和，不思饮食，心腹胁肋胀满刺痛，口苦无味，呕哕噎气，或沉重倦怠，或食入即吐，大便不调，或发寒热，或因食生冷，或因饥饱失宜，或因酒食伤中，或因气不顺，或因气滞痰饮，或因脾胃不健，或因气逆嘈杂，脘腹胀痛等证。","source":"《太平惠民和剂局方》卷三·治一切气"},{"type":"keypoints","title":"掌握要点","items":["燥湿运脾第一方，主治湿滞脾胃：脘腹胀满、不思饮食、肢体沉重、苔白厚腻、脉缓","苍术为君燥湿运脾，厚朴行气除满，陈皮理气化痰，甘草姜枣和中","配伍核心：燥湿与行气并重，湿去则脾健、气行则湿化","脾胃阴虚、舌红少苔者禁用；忌生冷油腻甜腻"]}]},{"id":"huoxiang-zhengqi-san","title":"藿香正气散","subtitle":"《太平惠民和剂局方》· 大腹皮 白芷 紫苏 茯苓 半夏曲 白术 陈皮 厚朴 桔梗 藿香 甘草 生姜 大枣","category":"化痰祛湿剂","tags":["解表化湿","理气和中","外感风寒内伤湿滞"],"meta":[{"label":"出处","value":"《太平惠民和剂局方》卷二·治伤寒"},{"label":"组成","value":"藿香 9g，紫苏 6g，白芷 6g，大腹皮 6g，白术 6g，陈皮 6g，厚朴 6g，半夏曲 6g，桔梗 6g，茯苓 6g，炙甘草 6g，生姜 3 片，大枣 2 枚"},{"label":"用法","value":"上为细末，每服 6g，水一盏，姜枣煎取七分，去滓热服，不拘时候"},{"label":"功用","value":"解表化湿，理气和中"},{"label":"主治","value":"外感风寒、内伤湿滞证。恶寒发热，头痛，胸膈满闷，脘腹疼痛，恶心呕吐，肠鸣泄泻，舌苔白腻，脉浮或缓"}],"image":"","imageHint":"藿香","summary":"藿香正气散为《太平惠民和剂局方》解表化湿、理气和中之代表方，主治外感风寒、内伤湿滞之证。藿香为君，辛温芳香，化湿和中、辟秽止呕兼解表；紫苏、白芷助君解表散寒，兼化湿；大腹皮、厚朴、陈皮行气除满、燥湿和胃；半夏曲、白术、茯苓燥湿健脾、降逆止泻；桔梗宣肺利膈；甘草、生姜、大枣调和脾胃。十六味药合用，表里双解、气化湿行，为治夏月感寒伤湿、吐泻并作之良方。临床用于急性胃肠炎、胃肠型感冒、消化不良、中暑等属外感风寒内伤湿滞者。","blocks":[{"type":"paragraph","text":"夏月暑湿盛行，起居贪凉、饮食不节，则外感风寒、内伤湿滞。风寒束表、卫阳被遏，故恶寒发热、头痛；湿滞中焦、气机不畅，故胸膈满闷、脘腹疼痛；胃失和降故恶心呕吐；脾失健运、水谷不分故肠鸣泄泻；苔白腻、脉浮或缓，为寒湿内盛之征。治当外散风寒、内化湿浊，兼理气和中，使表解湿化而吐泻自止。"},{"type":"table","caption":"藿香正气散君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["藿香","君：化湿和中，辟秽止呕，兼解表散寒","9g"],["紫苏、白芷","臣：助君解表散寒，兼化湿和中","各 6g"],["厚朴、大腹皮、陈皮","臣佐：行气除满，燥湿和胃","各 6g"],["白术、茯苓、半夏曲","佐：健脾燥湿，降逆止呕止泻","各 6g"],["桔梗","佐：宣肺利膈，行气载药上行","6g"],["炙甘草、生姜、大枣","使：益气和中，调和脾胃与诸药","6g／3 片／2 枚"]]},{"type":"paragraph","text":"本方配伍庞杂而有法度，主治表里同病而以中焦为枢。藿香辛温芳香，既能疏散表邪，又能芳香化湿、辟秽和中、止呕，为治湿浊中阻之要药，为君；一味藿香而表里两治，正是本方之枢。紫苏辛温，散寒解表、行气和胃；白芷辛温芳香，解表散寒、化湿止痛，二药助君以解表化湿，为臣。厚朴苦温，行气消积、燥湿除满；大腹皮辛微温，行气宽中、利水消肿；陈皮辛苦温，理气行滞、燥湿化痰，三药为臣佐，与藿香相配则气行湿化，痞满吐泻自除。白术苦甘温，健脾燥湿；茯苓甘淡，健脾渗湿；半夏曲辛温，燥湿化痰、降逆止呕，三药为佐，健脾以绝生湿之源。桔梗苦辛平，宣肺利膈，既利气机又载药上行，使药力达于上焦，为佐。炙甘草甘温，益气和中、调和诸药；生姜温胃止呕、化湿；大枣益气养血、调和脾胃，与甘草相配而调和营卫、扶助中气，共为使。综观全方：藿香、苏芷解表散寒，朴腹陈皮行气除湿，术苓半夏健脾化痰，桔梗宣肺，甘草姜枣和中；表里同治、气化湿行、标本兼顾，故能治外感风寒、内伤湿滞之上下同病。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"表邪重加香薷、荆芥、防风；湿重加苍术、薏苡仁；食积加神曲、山楂、麦芽；呕重加生姜、竹茹；泻重加薏苡仁、车前子（合胃苓汤）；寒重加干姜、附子；暑湿加佩兰、滑石；呕泻交作加吴茱萸、黄连（左金丸意）。临床用于急性胃肠炎、胃肠型感冒、消化不良、中暑、溃疡病急性发作、肠易激综合征等属外感风寒内伤湿滞者。夏月预防性服用可祛暑化湿。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方多辛香温燥，湿热霍乱、暑热证见高热烦渴、舌红苔黄者禁用，误投则助热伤津；阴虚火旺、舌红少苔者慎用；孕妇慎用（半夏、厚朴等）。藿香正气水含酒精，孕妇、儿童及不宜饮酒者宜用散剂或颗粒剂。服药期间忌食生冷油腻、不易消化之品。急性胃肠炎伴严重脱水、频繁呕吐不能进水者，须及时补液并就医。"},{"type":"quote","text":"治伤寒头疼，憎寒壮热，上喘咳嗽，五劳七伤，八般风痰，痰涎壅盛，肢体倦怠，憎寒壮热，荣卫不和，憎寒壮热，或吐泻…常服除山岚瘴气。","source":"《太平惠民和剂局方》卷二·治伤寒"},{"type":"keypoints","title":"掌握要点","items":["解表化湿、理气和中，主治外感风寒内伤湿滞：恶寒发热、胸闷腹痛、吐泻、苔白腻","藿香为君表里两治，紫苏白芷助解表，朴腹陈皮行气除湿","术苓半夏健脾化湿，桔梗宣肺，甘草姜枣和胃调中","暑热、湿热霍乱、阴虚火旺者禁用；忌生冷油腻"]}]},{"id":"linggui-zhugan-tang","title":"苓桂术甘汤","subtitle":"《伤寒论》· 茯苓 桂枝 白术 炙甘草","category":"化痰祛湿剂","tags":["温阳化饮","健脾利水","痰饮心悸眩晕"],"meta":[{"label":"出处","value":"《伤寒论》卷二·辨太阳病脉证并治（亦见《金匮要略》痰饮病）"},{"label":"组成","value":"茯苓 12g，桂枝 9g，白术 6g，炙甘草 6g"},{"label":"用法","value":"上四味，以水三升，煮取二升，去滓，分温三服"},{"label":"功用","value":"温阳化饮，健脾利水"},{"label":"主治","value":"中阳不足之痰饮证。胸胁支满，目眩心悸，短气而咳，舌苔白滑，脉沉弦或紧；亦治膀胱气化不利之水肿、痰饮、眩晕"}],"image":"","imageHint":"苓桂","summary":"苓桂术甘汤为《伤寒论》温阳化饮、健脾利水之代表方，主治中阳不足、痰饮内停之证。茯苓为君，健脾渗湿；桂枝为臣，温阳化气、平冲降逆；白术健脾燥湿为佐；炙甘草益气和中、缓急为佐使，并制桂枝之辛燥。四药配伍，温阳与利水并用，健脾与降逆相合，辛甘化气以行水，为「温阳化气、治饮之祖方」。临床用于慢性支气管炎、支气管哮喘、心律失常、梅尼埃病、心源性水肿、慢性胃炎等属中阳不足、痰饮内停者。","blocks":[{"type":"paragraph","text":"脾阳不运则水饮停聚，上凌心肺则心悸、短气而咳，饮停胸胁则胸胁支满，清阳不升、浊阴不降则目眩头摇；苔白滑、脉沉弦或紧，为水饮内停之征。治当温运脾阳、化气行水，使饮邪从小便而去。本方为苓桂剂之祖，后世苓桂术甘汤、苓桂味甘汤、苓桂姜甘汤皆由本方化裁，为治痰饮之经典。"},{"type":"table","caption":"苓桂术甘汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["茯苓","君：健脾渗湿，利水化饮，导饮从小便而出","12g"],["桂枝","臣：温阳化气，助膀胱气化，兼平冲降逆","9g"],["白术","佐：健脾燥湿，助茯苓渗湿，助中阳运化","6g"],["炙甘草","佐使：益气和中，缓急止痛，合桂枝辛甘化阳","6g"]]},{"type":"paragraph","text":"本方配伍精妙，关键在于「温阳化气」而非单纯利水。茯苓甘淡平，健脾渗湿、利水化饮，以淡渗之性导饮从小便而出，为君。桂枝辛甘温，温通脾阳、化气行水，助膀胱气化以利小便，并平冲降逆以治眩悸，为臣。茯苓得桂枝则阳气化而饮能行；桂枝得茯苓则温而不燥、水有出路，二药相须，为本方配伍之核心。白术苦甘温，健脾燥湿，既助茯苓健脾渗湿，又助中阳运化，为佐。炙甘草甘温，益气和中、缓急止痛，更能合桂枝辛甘相化以助温阳化气之力，合白术、茯苓补脾益气以固本，又制桂枝辛散之性，使温而不燥，为佐使。综观全方：四药皆入脾经，以温补脾阳为本、淡渗利水为标；桂枝与甘草辛甘化阳，茯苓与白术健脾渗湿；温阳而不燥烈，化饮而不伤正。故仲景云「病痰饮者，当以温药和之」，本方当之无愧，为治中阳不足痰饮之代表方。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"眩晕甚加泽泻（泽泻汤意）、天麻；咳喘加半夏、陈皮；心悸甚加桂枝量，加龙骨、牡蛎；水肿加猪苓、泽泻；胃反加半夏、生姜；阳虚甚加附子、干姜（肾阳虚者改用真武汤）；痰饮郁久化热加黄连、竹茹。临床用于慢性支气管炎、支气管哮喘缓解期、心源性水肿、梅尼埃病、神经性呕吐、心律失常、慢性胃炎、神经性水肿等属中阳不足、痰饮内停者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方性温，适用于阳虚水饮，若痰热内蕴、阴虚火旺、舌红少津、口干咽燥者禁用；湿热下注之水肿、泌尿系感染见尿频尿急尿痛者不宜，误投则助热恋邪。孕妇慎用。服后若小便过多、脘腹不适或口干，剂量宜调整。心脏病患者使用须在医师指导下，注意利尿作用对电解质与血容量的影响。"},{"type":"quote","text":"夫心下有痰水，胸胁支满，目眩，苓桂术甘汤主之。","source":"《金匮要略》卷十二·痰饮咳嗽病脉证并治"},{"type":"keypoints","title":"掌握要点","items":["温阳化饮、健脾利水，主治中阳不足痰饮：胸胁支满、目眩心悸、短气咳、苔白滑","茯苓为君健脾渗湿，桂枝为臣温阳化气，白术健脾，炙甘草辛甘化阳","配伍核心是「温阳化气、行水有路」，温而不燥、化饮不伤正","痰热、阴虚、湿热者禁用；水肿者注意电解质与血容量"]}]},{"id":"taohe-chengqi-tang","title":"桃核承气汤","subtitle":"《伤寒论》· 桃仁 大黄 桂枝 炙甘草 芒硝","category":"理血剂","tags":["逐瘀泻热","通下破血","下焦蓄血"],"meta":[{"label":"出处","value":"《伤寒论》卷三·辨太阳阳明病脉证并治"},{"label":"组成","value":"桃仁 12g（去皮尖），大黄 12g，桂枝 6g，炙甘草 6g，芒硝 6g"},{"label":"用法","value":"上五味，以水四升，煮取二升半，去滓，分温三服"},{"label":"功用","value":"逐瘀泻热"},{"label":"主治","value":"下焦蓄血证。少腹急结，小便自利，甚则谵语烦躁，其人如狂，至夜发热；以及血瘀经闭、痛经、脉沉实而涩，舌质暗有瘀斑"}],"image":"","imageHint":"桃核","summary":"桃核承气汤为《伤寒论》逐瘀泻热之代表方，主治下焦蓄血证。桃仁破血润燥为君；大黄下瘀泄热，芒硝软坚润燥为臣；桂枝通行血脉、缓急止痛，炙甘草护胃气、缓峻急为佐使。全方破血与泻热并用，祛瘀而不伤正，通下而不留瘀，为仲景「蓄血」治法之示范。临床用于闭经、痛经、盆腔炎、急性阑尾炎、产后恶露不下、精神分裂症、头部外伤等属瘀热互结于下焦者。因属峻下逐瘀之剂，孕妇禁用，体虚者慎用。","blocks":[{"type":"paragraph","text":"太阳病不解，邪热随经入于血分，与瘀血结于下焦，蓄血不去则少腹急结、小便自利；血热上扰心神故谵语烦躁、其人如狂；瘀热互结则入暮发热。辨证要点有二：一是少腹急结而小便自利（与蓄水证之小便不利相反）；二是脉沉实而涩、舌质暗有瘀斑。治当逐瘀泻热，使瘀血从大便而出，故以桃仁承气命名。"},{"type":"table","caption":"桃核承气汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["桃仁（去皮尖）","君：破血行瘀，润燥滑肠，为治瘀血要药","12g"],["大黄","臣：下瘀泄热，荡涤瘀热，推陈致新","12g"],["芒硝","臣：软坚润燥，助大黄攻下瘀热","6g"],["桂枝","佐：通行血脉，温通经脉，助桃仁破血","6g"],["炙甘草","佐使：护胃气、缓峻急，调和诸药","6g"]]},{"type":"paragraph","text":"本方配伍的核心是「逐瘀与泄热同施、攻下与通脉相伍」。桃仁苦甘平，破血行瘀而润燥，为治瘀血之要药，为君；大黄苦寒，下瘀泄热、荡涤积滞，与桃仁相合则瘀血得去、郁热得泄，为臣；芒硝咸寒，软坚润燥，助大黄攻下，助桃仁润燥，三药相须，则蓄血可从大便而下。桂枝辛甘温，通行血脉、通阳化气，助桃仁破血消瘀，并防寒凉凝滞之弊，为佐；炙甘草甘温，护胃气、缓峻急，并调和硝、黄、桃、桂之峻烈，为使。综观全方：桃、桂相配则破血而不伤正，大黄、芒硝相配则泻热而不留瘀；一攻一补、一润一通，故能于「蓄血」急证中标本兼顾。仲景原方用桂枝而非肉桂，取其温通血脉而不燥热之妙；服后当微下，得下即止，不可过剂。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"痛经加当归、川芎、延胡索；闭经加红花、川芎、益母草；产后恶露不下加益母草、炒蒲黄；跌打损伤加乳香、没药、红花；急性阑尾炎加红藤、败酱草、大黄牡丹汤；精神病属瘀热者加生大黄后下、远志、石菖蒲；血尿加白茅根、小蓟、石韦。临床用于闭经、痛经、盆腔炎、急性阑尾炎、产后恶露不下、精神分裂症、脑外伤后遗、顽固性便秘等属瘀热互结者。服法宜「得下即止」，不可久服。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方峻下逐瘀，孕妇绝对禁用；月经过多、无排卵型功血、溃疡病出血期、产后恶露不止者均禁用。体虚、贫血、脾胃虚弱者当慎用；体虚者必须用时须先以补益之品扶正，或改用少量化裁（如桃红四物汤）。服药期间忌食生冷、忌酒；服药后如腹泻不止、头晕乏力，为攻下太过，应停药并酌情调理。服后大便色黑或带血，乃瘀血得下之象，然亦须结合症状判断，不可误认为出血加重而自行停药就医。"},{"type":"quote","text":"太阳病不解，热结膀胱，其人如狂，血自下，下者愈。其外不解者，尚未可攻，当先解其外；外解已，但少腹急结者，乃可攻之，宜桃核承气汤。","source":"《伤寒论》卷三·辨太阳阳明病脉证并治"},{"type":"keypoints","title":"掌握要点","items":["逐瘀泻热，主治下焦蓄血：少腹急结、小便自利、暮热、如狂","桃仁为君破血，大黄、芒硝为臣泻热软坚，桂枝通脉，炙甘草护胃","配伍特点：逐瘀与泄热同施，攻而不伤正，通下不留瘀","孕妇禁用，月经过多、体虚者慎用；得下即止，勿过剂"]}]},{"id":"xuefu-zhuyu-tang","title":"血府逐瘀汤","subtitle":"《医林改错》· 桃仁 红花 当归 生地 牛膝 赤芍 川芎 枳壳 柴胡 桔梗 甘草","category":"理血剂","tags":["活血祛瘀","行气止痛","胸中血瘀"],"meta":[{"label":"出处","value":"《医林改错》卷上"},{"label":"组成","value":"桃仁 12g，红花 9g，当归 9g，生地黄 9g，川芎 5g，赤芍 6g，牛膝 9g，桔梗 5g，柴胡 3g，枳壳 6g，炙甘草 3g"},{"label":"用法","value":"水煎服，日一剂，分早晚服"},{"label":"功用","value":"活血化瘀，行气止痛"},{"label":"主治","value":"胸中血瘀证。胸痛头痛日久不愈，痛如针刺而有定处，或呃逆日久不止，或内热瞀闷，心悸失眠，急躁易怒，入暮潮热，唇暗或两目暗黑，舌质暗红或有瘀斑，脉涩或弦紧"}],"image":"","imageHint":"血府","summary":"血府逐瘀汤为《医林改错》活血化瘀、行气止痛之代表方，主治胸中血瘀证。桃仁、红花活血祛瘀为君；赤芍、川芎助祛瘀止痛，当归、生地养血活血，祛瘀而不伤阴血为臣；牛膝活血通经、导瘀下行，桔梗、枳壳一升一降，宽胸行气，柴胡疏肝解郁、升达清阳为佐；甘草调和为使。全方气血同治、升降同调、祛瘀与养血兼顾，开胸逐瘀而不伤正，为治疗胸中血瘀诸证之要方。临床用于冠心病心绞痛、胸部挫伤、肋软骨炎、脑震荡后遗症、顽固性头痛、失眠等属血瘀者。","blocks":[{"type":"paragraph","text":"胸中为气之海、血之府。情志不遂、跌仆损伤或久病入络，皆可使瘀血停滞于胸胁，既阻气机又碍血行，故见胸痛头痛、痛如针刺而固定，呃逆日久不止；瘀久化热则内热瞀闷、入暮潮热，急躁易怒；血不养心则心悸失眠；血行不畅则唇暗、两目暗黑；舌质暗红或有瘀斑、脉涩或弦紧，皆为血瘀之征。治当活血祛瘀、行气止痛，兼以养血与清热。"},{"type":"table","caption":"血府逐瘀汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["桃仁、红花","君：活血祛瘀，行气止痛，为治血瘀之要药","12g／9g"],["赤芍、川芎","臣：活血祛瘀止痛，助桃红破血行瘀","6g／5g"],["当归、生地黄","臣：养血活血，凉血清热，祛瘀而不伤阴血","9g／9g"],["牛膝","佐：活血通经，祛瘀下行，引血下行助降胸中瘀血","9g"],["桔梗、枳壳","佐：宽胸行气，一升一降，调畅胸中气机","5g／6g"],["柴胡","佐：疏肝解郁，升达清阳，配枳壳调气机","3g"],["炙甘草","使：补中益气，调和诸药","3g"]]},{"type":"paragraph","text":"本方配伍之妙在于气血同治、升降相因、祛瘀养血兼顾。桃仁苦甘平、红花辛温，二者活血祛瘀、行气止痛，为治血瘀之要药，为君。赤芍苦微寒，活血祛瘀止痛；川芎辛温，活血行气、开郁止痛，二药助桃红以破血行瘀，为臣。当归甘辛温，养血活血、和血止痛；生地黄甘苦寒，凉血清热、养阴生津，二药一温一凉，既养血以固护阴血，又清血分之瘀热，与桃红相配则祛瘀而不伤正，为佐使。牛膝苦酸平，活血通经、补肝肾、强筋骨，且引血下行，导瘀血从下而出，为佐；桔梗苦辛平，宣肺利气、载药上行，枳壳苦辛微寒，理气宽胸、破气消积，二药一升一降，使胸中气机宣畅、瘀血得散，是本方配伍之关键；柴胡苦辛微寒，疏肝解郁、升达清阳，与枳壳相配则一升一降，调畅气机，并使药力直达胸中，为佐。炙甘草甘温，补中益气、调和诸药，且使桃红、芎归不伤正，为使。综观全方：祛瘀与养血并行、活血与行气相合、升清与降浊相因，故能活血而不伤血、行气而不耗气，瘀去而新生，为治胸中血瘀之典范。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"胸痛甚加瓜蒌、薤白、丹参、檀香；头痛加白芷、川芎量、藁本；失眠加酸枣仁、柏子仁、夜交藤；心悸加桂枝、龙骨、牡蛎；呃逆加旋覆花、代赭石、丁香；瘀久化热加丹皮、栀子、黄芩；气虚加黄芪、党参；血虚加鸡血藤、制首乌；胸胁痛加柴胡、郁金；久痛入络加全蝎、蜈蚣。临床用于冠心病心绞痛、胸部挫伤、肋软骨炎、脑震荡后遗、顽固性头痛、失眠、神经症、痛经、子宫内膜异位症等属血瘀者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方活血祛瘀力强，孕妇禁用；月经过多、功能性子宫出血、溃疡病出血、牙龈出血、产后恶露不止、血小板减少性紫癜等出血倾向者禁用或严格减量。体虚、贫血者慎用；年老体弱、血瘀而兼气血亏虚者宜先补后攻或攻补兼施。服药期间忌酒、忌食生冷，勿服华法林等抗凝药而自行加量；若出现皮下瘀斑、鼻衄、牙龈出血，应停药就医。"},{"type":"quote","text":"治胸中血府血瘀之症……胸痛、胸不任物、胸任重物、心里热、瞀闷、急躁、夜睡梦多、呃逆、饮水即呛、不眠、心跳心忙、夜不安、干呕、晚发一阵热等证。","source":"《医林改错》卷上·血府逐瘀汤所治症目"},{"type":"keypoints","title":"掌握要点","items":["活血化瘀、行气止痛，主治胸中血瘀：胸痛如刺有定处、呃逆、暮热、唇暗、脉涩","桃红为君，芎赤归地养血，桔梗枳壳一升一降、柴胡疏肝、牛膝导瘀下行","配伍特点：气血同治、升降相因、祛瘀与养血并施","孕妇禁用，有出血倾向者禁服；久服须监测凝血功能"]}]},{"id":"shenghua-tang","title":"生化汤","subtitle":"《傅青主女科》· 当归 川芎 桃仁 炮姜 炙甘草","category":"理血剂","tags":["养血祛瘀","温经止痛","产后血瘀"],"meta":[{"label":"出处","value":"《傅青主女科》卷上·产后"},{"label":"组成","value":"当归 24g，川芎 9g，桃仁 6g，炮姜 2g，炙甘草 2g"},{"label":"用法","value":"水煎，产前产后皆可服；产后黄酒、童便各半杯煎服更佳"},{"label":"功用","value":"养血祛瘀，温经止痛"},{"label":"主治","value":"产后血虚寒凝、瘀血阻滞之产后腹痛。恶露不行，小腹冷痛拒按，得温则减，或腰膝酸痛，舌淡暗苔白，脉沉弦涩"}],"image":"","imageHint":"生化","summary":"生化汤为《傅青主女科》产后名方，主治产后血虚寒凝、瘀血阻滞之腹痛。当归为君，补血活血、化瘀生新；川芎为臣，活血行气、止痛；桃仁为臣，破血逐瘀；炮姜温经散寒、止痛，为佐；炙甘草调和诸药为使，兼制川芎、桃仁之耗血。全方补血而不滞血、化瘀而不伤正、温经而不燥烈，寓补于攻之中，为「产后生新血、化瘀血」之代表方。临床用于产后腹痛、产后恶露不绝、产后发热、痛经、崩漏、产后身痛等属血虚夹瘀者。因药性平和，产前产后皆可调治。","blocks":[{"type":"paragraph","text":"产后多虚多瘀：分娩耗伤气血，血虚则胞宫失养；离经之血停于胞宫，成血瘀则腹痛拒按、恶露不下。产后不慎感寒，寒凝血瘀则痛处固定、得温则减、喜按喜暖；舌淡暗苔白、脉沉弦涩，为血虚寒凝之征。治当补血化瘀、温经止痛。傅青主谓「生新血、化瘀血」，正合产后病机，故立生化汤为产后调治之要方。"},{"type":"table","caption":"生化汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["当归","君：补血活血，化瘀生新，调和产后气血","24g"],["川芎","臣：活血行气，祛瘀止痛，为血中之气药","9g"],["桃仁","臣：破血逐瘀，润燥通便","6g"],["炮姜","佐：温经散寒，止痛止血，制川芎桃仁之寒","2g"],["炙甘草","佐使：益气和中，调和诸药，兼制桃仁之破","2g"]]},{"type":"paragraph","text":"本方配伍精妙在「补血化瘀并施、寒温相济」。当归甘辛温，质润，补血活血、化瘀生新，为君；产后多虚，补血不可不急，故重用为君。川芎辛温，升散活血行气，为血中之气药，能行血中之滞、开郁止痛；桃仁苦甘平，破血逐瘀、润燥，二药相须为臣，助当归化瘀止痛。炮姜辛热，温经散寒、止痛止血，既温通经脉以助血行，又制约川芎、桃仁之寒凉耗血，为佐。炙甘草甘温，益气和中、调和诸药，一则助当归补血，二则缓桃仁破血之力，使祛瘀而不伤正，三则调和全方，为佐使。综观全方：当归补血以充其虚，川芎、桃仁化瘀以行其滞，炮姜温通以散其寒，甘草和中以顾其胃。四药相配，补而不滞、化而不伤、温而不燥，故能于产后血虚夹瘀之证中标本兼顾。方中川芎、桃仁用量远小于当归，正体现「以补为主、以化为辅」之意，与一般活血方剂大不相同。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"恶露不下加益母草、炒蒲黄；恶露不绝加炒蒲黄、益母草、阿胶；腹痛甚加延胡索、白芍、乌药；发热加金银花、连翘、蒲公英；身痛加黄芪、鸡血藤、秦艽；乳少加通草、王不留行、路路通；乳胀加橘叶、青皮；恶露臭秽加金银花、败酱草、红藤；崩漏加艾叶炭、棕榈炭、乌贼骨。临床用于产后腹痛、产后恶露不绝、产后发热、产后身痛、产后抑郁、痛经、崩漏、子宫内膜异位症等属血虚夹瘀者。产后即服可预防恶露不绝。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方为产后调治之剂，非血虚夹瘀者不可泛用。产后恶露量多色鲜红、量多不止属血热者禁用，恐助热动血；孕妇慎用（须辨证明确后方可短期使用）；月经过多、崩漏出血期禁用。服药期间忌食生冷寒凉，注意保暖避风寒。若产后腹痛剧烈、发热持续、恶露恶臭，须警惕盆腔感染、胎盘残留等，应及时就医，不可仅用汤剂。乳汁分泌旺盛者当归用量不宜过大。"},{"type":"quote","text":"治产后血块未散，或作寒热，或作呕吐，或崩漏，或大便实，此方皆可用。","source":"《傅青主女科》卷上·产后"},{"type":"keypoints","title":"掌握要点","items":["养血祛瘀、温经止痛，主治产后血虚寒凝之腹痛与恶露不下","当归重用为君补血，川芎桃仁化瘀，炮姜温经，炙甘草和中","配伍特点：补而不滞、化而不伤、温而不燥，寓补于攻","产后血热恶露不止、崩漏出血期禁用；产褥感染须就医"]}]},{"id":"simiao-yongan-tang","title":"四妙勇安汤","subtitle":"《验方新编》· 金银花 玄参 当归 甘草","category":"理血剂","tags":["清热解毒","活血止痛","脱疽热毒"],"meta":[{"label":"出处","value":"《验方新编》卷上·脱疽"},{"label":"组成","value":"金银花 90g，玄参 90g，当归 60g，炙甘草 30g"},{"label":"用法","value":"水煎服，一连十剂；亦可作散剂，每服 9g，日二次"},{"label":"功用","value":"清热解毒，活血止痛"},{"label":"主治","value":"热毒炽盛之脱疽。患肢暗红微肿灼热，溃烂腐臭，疼痛剧烈，或见发热口渴，舌红脉数"}],"image":"","imageHint":"四妙","summary":"四妙勇安汤为《验方新编》清热解毒、活血止痛之代表方，主治热毒炽盛之脱疽。金银花为君，清热解毒、消散痈肿；玄参为臣，清热凉血、泻火解毒、软坚散结；当归为佐，养血活血、化瘀止痛；甘草为使，清热解毒、调和诸药。全方药简力专，重用金银花、玄参以清热解毒，当归和血通脉，甘草和中解毒，使热毒清、经脉通而痛自止，为下肢脱疽（血栓闭塞性脉管炎、糖尿病足）之经典方。临床用于血栓闭塞性脉管炎、糖尿病足、丹毒、蜂窝织炎、痛风性关节炎等属热毒炽盛者。","blocks":[{"type":"paragraph","text":"脱疽为肢体血脉闭阻之病，若患处暗红肿痛、溃烂腐臭而灼热疼痛，伴发热口渴、舌红脉数，属热毒炽盛、瘀阻经脉之证。热毒不除则肉腐成脓，瘀阻不解则痛不可忍。故治当清热解毒为主，兼以活血通脉，使毒清而脉通，通则痛止。本方不用大苦大寒之品攻下，亦不用虫类破血之品峻攻，而以甘寒清解与养血和血相配，缓缓化之，正合脱疽「本虚标实、久病宜缓」之特点。"},{"type":"table","caption":"四妙勇安汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["金银花","君：清热解毒，消散痈肿，为治热毒炽盛之要药","90g"],["玄参","臣：清热凉血，泻火解毒，软坚散结，助金银花解毒","90g"],["当归","佐：养血活血，化瘀生肌，通利血脉止痛","60g"],["炙甘草","使：清热解毒，补中益气，调和诸药","30g"]]},{"type":"paragraph","text":"本方配伍简朴而力道专专。金银花甘寒质轻，清热解毒、消散痈肿而不伤阴、不败胃，为治疮疡热毒之要药，重用为君，直折炽盛之热毒。玄参甘苦咸寒，清热凉血、泻火解毒，又能软坚散结、滋阴养液，与金银花相须为臣，二者相合则清热解毒之力倍，而滋阴之性又可制约金银花之寒凉。顾步龙先生治脱疽以此方为主，取其「清热解毒、活血止痛」之功。当归甘辛温润，补血活血、化瘀生肌，既助桃仁-style活血之功以通利血脉、解除瘀阻，又养血生肌以促疮口愈合，且可制金银花、玄参之寒凉，为佐。炙甘草甘温，清热解毒、缓急止痛、调和诸药，并可与当归相合益气养血，为使。综观全方：金银花、玄参清热解毒治其标，当归、甘草养血和营治其本；四药皆入血分，清中有养、散中有收，故能令热毒得清、瘀阻得通、疼痛得止、疮口得敛。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"热毒炽盛加蒲公英、紫花地丁、连翘、白花蛇舌草；血瘀明显加桃仁、红花、赤芍、丹参；疼痛剧烈加乳香、没药、延胡索、蜈蚣；气虚加黄芪、党参；血虚加鸡血藤、制首乌；溃烂不敛加黄柏、苦参、土茯苓、儿茶；糖尿病足合五味消毒饮并加黄连、丹参；痛风性关节炎加土茯苓、萆薢、威灵仙。临床用于血栓闭塞性脉管炎、糖尿病足、丹毒、蜂窝织炎、坏疽性脓皮病、痛风性关节炎等属热毒炽盛、瘀阻脉络者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方重用金银花、玄参等寒凉之品，脾胃虚寒、食少便溏者慎用；阴虚而火炽无实毒者不宜单用；孕妇慎用。服药期间忌食辛辣发物、烟酒，注意患肢保暖但不可过烫，亦须避免长时间挤压与赤足行走。血栓闭塞性脉管炎、糖尿病足属进行性疾患，须配合血管外科、内分泌科规范治疗与创面护理，中药只作辅助，切不可因服汤而延误手术时机。患肢出现溃烂、坏疽、剧痛或感染扩散者须立即就医。"},{"type":"quote","text":"四妙勇安治脱疽，银花玄参配当归，甘草四两煎代茶，疼痛自消效亦奇。","source":"《汤头歌诀·四妙勇安汤歌》"},{"type":"keypoints","title":"掌握要点","items":["清热解毒、活血止痛，主治热毒炽盛之脱疽：患肢暗红灼痛、溃烂腐臭、舌红脉数","金银花为君、玄参为臣，重用二药清热解毒凉血","当归养血活血通脉，炙甘草清热解毒调和，清中有养","脾胃虚寒者慎用；脱疽须配合血管外科规范治疗与创面护理"]}]},{"id":"tianwang-buxin-dan","title":"天王补心丹","subtitle":"《校注妇人良方》· 生地 人参 丹参 玄参 茯苓 五味子 远志 桔梗 当归 天冬 麦冬 柏子仁 酸枣仁","category":"安神开窍剂","tags":["滋阴养血","补心安神","心肾不交"],"meta":[{"label":"出处","value":"《校注妇人良方》卷下（源出《摄生总要》）"},{"label":"组成","value":"生地黄 120g，人参 15g，丹参 15g，玄参 15g，茯苓 15g，五味子 30g，远志 15g，桔梗 15g，当归 60g，天冬 60g，麦冬 60g，柏子仁 60g，酸枣仁 60g，炼蜜为丸"},{"label":"用法","value":"上为末，炼蜜为丸，梧桐子大，朱砂为衣，每服一丸，临卧水化下；亦可作汤剂水煎服"},{"label":"功用","value":"滋阴清热，养血补心安神"},{"label":"主治","value":"阴虚血少、神志不安证。心悸怔忡，虚烦失眠，神疲健忘，梦遗，手足心热，口舌生疮，大便干结，舌红少苔，脉细数"}],"image":"","imageHint":"天王","summary":"天王补心丹为《校注妇人良方》滋阴清热、养血补心安神之代表方，主治阴虚血少、神志不安之证。生地为君，滋阴养血、清热除烦；天冬、麦冬、玄参滋阴清热为臣；当归、丹参养血活血，柏子仁、酸枣仁、茯苓、远志养心安神，五味子收敛心气，人参、桔梗益气载药、宣肺使药下行，朱砂为衣镇心安神为佐使。全方滋而不腻、养血安神而兼清心火，为「心肾同治、水火既济」之剂。临床用于神经衰弱、失眠、心律失常、冠心病、围绝经期综合征、更年期综合征、贫血等属阴虚血少者。","blocks":[{"type":"paragraph","text":"心主神明，肾藏精。心肾不交、阴虚火旺，则心神失养而心悸怔忡、失眠健忘；虚火扰神则虚烦不寐、梦遗；阴虚内热则手足心热、口舌生疮；津液不足则大便干结；舌红少苔、脉细数为其主要指征。此类证候，纯用滋腻则碍胃，纯用清降则伤阴，纯用重镇则遏邪，故须滋阴为主、养血安神为辅，兼以清心降火。"},{"type":"table","caption":"天王补心丹君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["生地黄","君：滋阴养血，清热除烦，为滋阴养血之要药","120g"],["天冬、麦冬、玄参","臣：滋阴清热，养血润燥，助生地壮水制火","各 60g／60g／15g"],["当归、丹参","佐：养血活血，补血中之不足，使血润则神安","60g／15g"],["柏子仁、酸枣仁、茯苓、远志","佐：养心安神定志，共奏安神除烦之功","各 60g／60g／15g／15g"],["人参","佐：益气生津，助生地滋阴，兼补心气","15g"],["五味子","佐：敛心气、涩精气，与酸枣仁相配敛汗安神","30g"],["桔梗","使：宣肺气、载药上行，济水火而滋阴","15g"],["朱砂（为衣）","使：镇心安神，清心火以定惊悸","外用"]]},{"type":"paragraph","text":"本方配伍宏富而井然，为「滋阴养血安神」之大法。生地黄甘苦寒，滋阴养血、清热除烦，重用为君，直治阴虚血少之本。天冬甘苦微寒、麦冬甘微苦寒，二者养阴润肺、生津清心；玄参甘苦咸寒，滋阴降火、凉血解毒，三药为臣，与生地共成壮水制火之功，既滋水以济火，又清热以安神。当归甘辛温，补血活血；丹参苦微寒，活血祛瘀、清心安神，二药为佐，养血而不滞，使血充则神有所舍。柏子仁甘平、酸枣仁甘酸平，养心补肝、宁心安神；茯苓甘淡，健脾宁心；远志苦辛温，安神益智、交通心肾，四药为佐，专事安神定志。人参甘温微苦，益气生津，既助生地滋阴，又补心气以助神有所养。五味子酸温，敛心气、涩精气，与酸枣仁相配则敛中寓补、心神自安。桔梗苦辛平，宣肺气以济心肾、载药上浮而使药力下达，兼取「桔梗载药上行、舟楫之剂」之义，为使。朱砂甘微寒，为衣以镇心安神、清心火定惊悸，为使。综观全方：滋阴为本，养血为基，安神为用；三组药分司滋阴、养血、安神，而以生地、参、归、麦冬、五味子滋补心肾之阴，酸枣仁、柏子仁、茯神、远志养心安神，标本兼顾，为治阴虚血少失眠心悸之代表方。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"心悸加龙齿、磁石；失眠甚加夜交藤、合欢皮、龙齿；健忘加菖蒲、益智仁；梦遗加金樱子、芡实、莲须；口疮加黄连、竹叶、莲子心；便秘加火麻仁、郁李仁、玄参；自汗盗汗加浮小麦、麻黄根；焦虑加郁金、合欢花；冠心病加丹参、川芎、瓜蒌；围绝经期综合征加女贞子、旱莲草、浮小麦。临床用于神经衰弱、失眠症、心律失常、冠心病、围绝经期综合征、更年期综合征、贫血、神经症、更年期失眠等属阴虚血少者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方药多滋腻，脾胃虚弱、纳呆便溏、痰湿内盛者慎用，服后脘腹胀满者宜加陈皮、砂仁、茯苓或改用汤剂。含朱砂者不可久服、不可过量，肝肾功能不全者尤须避免，孕妇慎用。痰热内扰、湿热下注所致失眠心悸者不宜使用。服药期间忌食辛辣炙煿、浓茶咖啡，注意调摄情志、规律作息，避免熬夜与用脑过度。长期失眠伴严重焦虑或情绪低落者须及时就诊，必要时配合心理治疗。"},{"type":"quote","text":"天王补心丹柏仁，二冬归芍茯苓神，桔梗远志人参味，滋阴养血安心神。","source":"《汤头歌诀·天王补心丹歌》"},{"type":"keypoints","title":"掌握要点","items":["滋阴清热、养血补心安神，主治阴虚血少：心悸失眠、健忘、梦遗、手足心热、舌红少苔","生地为君，天冬麦冬玄参为臣，壮水制火；当归丹参养血，酸枣仁柏子仁茯苓远志安神","配伍特点：滋而不腻、养血安神兼清心火，心肾同治、水火既济","脾胃虚弱、痰湿内盛者慎用；含朱砂者不可久服"]}]},{"id":"suanzaoren-tang","title":"酸枣仁汤","subtitle":"《金匮要略》· 酸枣仁 甘草 知母 茯苓 川芎","category":"安神开窍剂","tags":["养血安神","清虚热","虚烦不眠"],"meta":[{"label":"出处","value":"《金匮要略》卷九·血痹虚劳病脉证并治"},{"label":"组成","value":"酸枣仁 15g（炒捣），甘草 3g，知母 6g，茯苓 6g，川芎 6g"},{"label":"用法","value":"上五味，以水八升，煮取三升，分温三服"},{"label":"功用","value":"养血安神，清虚热"},{"label":"主治","value":"肝血不足、虚热内扰之虚烦不眠证。虚烦失眠，心悸盗汗，头目眩晕，咽干口燥，舌红少苔，脉弦细"}],"image":"","imageHint":"酸枣","summary":"酸枣仁汤为《金匮要略》养血安神、清虚热之代表方，主治肝血不足、虚热内扰之虚烦不眠。酸枣仁为君，养肝血、敛肝气、安五脏之魂，为治虚烦不眠之要药，重用为君；茯苓宁心安神、健脾渗湿，知母滋阴润燥、清虚热，川芎调畅气血、疏达肝气为臣；甘草和中缓急、调和诸药为佐使。全方酸甘化阴、养血调肝、宁心安神，为后世养血安神诸方之祖。临床用于神经衰弱、失眠症、焦虑症、心悸、更年期综合征等属肝血不足、虚热内扰者。","blocks":[{"type":"paragraph","text":"《金匮要略》曰「虚劳虚烦不得眠」，正是本方所治。肝藏血、主魂，肝血不足则魂不守舍，故虚烦不眠、心悸；血虚不能上荣则头晕目眩；血虚津亏则咽干口燥；阴血不足则虚热内生而见盗汗、舌红少苔；脉弦细为血虚肝旺之象。治当养肝血、清虚热、安神魂。此类失眠非重镇可制、非温补可通，唯养血安神之法最为对证。"},{"type":"table","caption":"酸枣仁汤君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["酸枣仁（炒捣）","君：养肝血、敛肝气、宁心安魂，为治虚烦不眠之要药","15g"],["茯苓","臣：宁心安神，健脾渗湿，合参甘草补脾以生血","6g"],["知母","臣：滋阴润燥，清虚热，制酸枣仁之温","6g"],["川芎","佐：调畅气血、疏达肝气，使肝血得行而不滞","6g"],["甘草","佐使：补中益气，缓急和中，调和诸药","3g"]]},{"type":"paragraph","text":"本方配伍之妙在「酸甘化阴、养血调肝」。酸枣仁甘酸平，养肝血、敛肝气、宁心安魂，重用为君，直治虚烦不眠之本；酸枣仁生用捣碎取其仁，炒用则其气香而和，二者皆可入方。茯苓甘淡平，宁心安神、健脾渗湿，既安神魂，又与甘草相配成四君子之义以健脾生血，使血有化源，为臣。知母苦甘寒，滋阴润燥、清虚热，一方面补阴血之不足，一方面制约酸枣仁之温而免助热，为臣。川芎辛温，调畅气血、疏达肝气，使补而不滞、郁而得舒，为佐。甘草甘温，补中益气、缓急和中，调和诸药，为佐使。综观全方：君药养肝血安神魂，臣药一健脾生血、一滋阴清热，佐药疏肝理气，使补血而不壅滞、安神而不恋邪。酸枣仁与甘草相配酸甘化阴，茯苓与甘草相配补脾生血，知母与酸枣仁相配滋阴清热而制其温，故养血安神而不燥不腻，为治虚烦不眠之经典。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"虚热明显加黄连、竹叶、栀子；血虚甚加当归、白芍、熟地；心悸加龙齿、珍珠母、磁石；盗汗加浮小麦、五味子、煅牡蛎；眩晕加天麻、钩藤、菊花；失眠甚加夜交藤、合欢皮、柏子仁；焦虑加郁金、合欢花、龙眼肉；更年期综合征加女贞子、旱莲草、百合；神经衰弱加远志、石菖蒲。临床用于失眠症、神经衰弱、焦虑症、神经性心悸、围绝经期综合征、更年期综合征、病毒性心肌炎后期等属肝血不足、虚热内扰者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方酸甘滋腻，脾胃虚弱、纳呆便溏、痰湿内蕴者慎用；实热扰心之失眠（心烦、口苦、舌红苔黄、脉数有力）当改用黄连温胆汤、龙胆泻肝汤等，误用则酸敛留邪。川芎为辛散之品，阴虚火旺、头痛目赤者当减量。服药期间忌食辛辣炙煿、浓茶与咖啡，须规律作息、避免熬夜；长期失眠伴抑郁焦虑倾向者应及时就诊，配合心理与行为干预。"},{"type":"quote","text":"虚劳虚烦不得眠，酸枣仁汤主之。","source":"《金匮要略》卷九·血痹虚劳病脉证并治"},{"type":"keypoints","title":"掌握要点","items":["养血安神、清虚热，主治肝血不足虚烦不眠：失眠、心悸、盗汗、眩晕、舌红少苔、脉弦细","酸枣仁重用为君养肝血敛肝气安魂，茯苓宁心健脾，知母滋阴清虚热，川芎疏肝调气血","配伍核心：酸甘化阴、养血调肝，补而不滞、安神不恋邪","实热扰心之失眠不可误用；脾胃虚弱者慎之"]}]},{"id":"suhexiang-wan","title":"苏合香丸","subtitle":"《太平惠民和剂局方》· 苏合香 冰片 麝香 乳香 檀香 沉香 丁香 荜茇 白术 诃子 朱砂","category":"安神开窍剂","tags":["芳香开窍","行气止痛","寒闭神昏"],"meta":[{"label":"出处","value":"《太平惠民和剂局方》卷三·治一切气"},{"label":"组成","value":"苏合香、冰片、麝香、乳香、檀香、沉香、丁香、荜茇、白术、诃子、朱砂、水牛角浓缩粉，研末，炼蜜为丸"},{"label":"用法","value":"每服 1 丸，研化温开水调下；昏迷者嚼碎灌服"},{"label":"功用","value":"芳香开窍，行气止痛"},{"label":"主治","value":"寒闭证。昏迷不醒，牙关紧闭，无汗，身冷，苔白，脉迟；亦治心腹卒痛、心痛、癔病、时疫"}],"image":"","imageHint":"苏合","summary":"苏合香丸为《太平惠民和剂局方》芳香开窍、行气止痛之代表方，主治寒闭神昏之证。苏合香、冰片、麝香为君，芳香开窍、苏醒神志；乳香、檀香、沉香、丁香、荜茇行气止痛、温通辟秽为臣；白术、诃子健脾敛气，犀角（水牛角浓缩粉）清心镇惊，朱砂重镇定神为佐使。十六味药多辛香温燥，辛开苦降、温通辟秽，与安宫牛黄丸之寒凉开窍相对而用，为「温开」代表方。临床用于中风、昏迷、心绞痛、癔病、癫痫、冻伤、心绞痛等属寒闭者。因辛香耗气、孕妇慎用，不宜久服。","blocks":[{"type":"paragraph","text":"寒闭证为寒邪痰浊蒙蔽心窍所致，患者突然昏仆、不省人事、牙关紧闭，兼见无汗、身冷、面色苍白、苔白、脉迟，与热闭之高热、面赤、便秘、舌绛、脉数截然不同。治当辛温芳香、开窍醒神、辟秽通闭，使寒邪痰浊从口鼻而出。苏合香丸集辛香温通之品于一身，以其芳香走窜之力开通闭阻，故称「温开」之祖方，与凉开之安宫牛黄丸、紫雪丹、至宝丹并列为三大开窍方。"},{"type":"table","caption":"苏合香丸配伍分析表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["苏合香、冰片、麝香","君：芳香开窍，苏醒神志，为开窍醒神之要药","各等分"],["乳香、檀香、沉香","臣：行气活血、止痛温通，辟秽化浊","各等分"],["丁香、荜茇","臣：温中散寒、行气开郁，助辛香开结","各等分"],["白术、诃子","佐：健脾益气、敛气固脱，防辛香耗散","各等分"],["水牛角浓缩粉、朱砂","佐使：清心解毒、镇心安神定惊","各等分"]]},{"type":"paragraph","text":"本方配伍以「辛香开窍、温通辟秽」为法。苏合香辛温芳香，开窍醒神、辟秽止痛，为君；冰片苦辛微寒，芳香走窜、清热开窍，与苏合香相须而开闭之力更宏；麝香辛温走窜，开窍醒神、活血行滞，三味并为君药，统领全方。乳香辛苦温，活血止痛、追风散寒；檀香辛苦温，理气止痛、辟秽和中；沉香辛苦温，行气止痛、温中止呕；丁香辛温，温中散寒、降逆；荜茇辛热，温中散寒、行气止痛，此五味为臣，助君药温通辟秽、行气止痛。诃子苦酸涩平，敛气固脱、化痰止咳；白术苦甘温，健脾益气、燥湿化痰，二者虽为佐药，却可制约大队辛香耗气之品，使开窍而不耗气，为佐。水牛角浓缩粉苦寒，清心凉血解毒；朱砂甘微寒，镇心安神定惊，二者清镇与辛温并用，使热象不致内生而神气得安，为佐使。综观全方：辛香与清镇同施，温通而不助热；开窍与健脾相配，辟邪而不伤正，故为寒闭神昏之良方。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"临床多作丸剂或散剂急救使用；胸痛明显可配伍速效救心丸、瓜蒌薤白半夏汤；中风昏迷可配合安宫牛黄丸或醒脑静；寒凝心绞痛可合冠心苏合丸（含苏合香、冰片、乳香、檀香、土木香）；癔病、癫痫可用本方合甘麦大枣汤；冻疮、雷诺现象可用本方外用研末调敷。临床用于急性中风昏迷、急性心肌梗死、心绞痛、癔病、癫痫、惊厥、冻伤、雷诺病等属寒闭者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方辛香温燥，只适用于寒闭（无汗、身冷、苔白、脉迟），热闭神昏（高热、面赤、便秘、舌绛、脉数）绝对禁用，误用可致加重内热、昏厥。孕妇禁用；体虚、阴虚火旺者慎用；婴幼儿慎用。本方含朱砂，不宜长期或过量服用，肝肾功能不全者尤须避免；服用后若出现口中金属味、牙龈肿痛、口舌生疮等，应停药就医。昏迷为急症，须立即拨打急救电话并配合现代医学抢救，不可单靠本方延误时机。"},{"type":"quote","text":"苏合香丸用冰片，麝香乳香木香檀，荜拨沉香白豆蔻，辟秽开窍急救寒。","source":"《汤头歌诀·苏合香丸歌》"},{"type":"keypoints","title":"掌握要点","items":["芳香开窍、行气止痛，主治寒闭神昏：昏迷不醒、牙关紧闭、无汗身冷、苔白脉迟","苏合香、冰片、麝香为君开窍，乳香檀香沉香丁香荜茇温通辟秽","配伍特点：辛香开窍与清镇安神同施，温而不助热、开而不耗气","热闭者绝对禁用；孕妇禁用，含朱砂不宜久服；昏迷须立即急救"]}]},{"id":"chuanxiong-chatiao-san","title":"川芎茶调散","subtitle":"《太平惠民和剂局方》· 川芎 荆芥 白芷 羌活 甘草 细辛 防风 薄荷 清茶","category":"治风剂","tags":["疏风止痛","外散风邪","偏正头痛"],"meta":[{"label":"出处","value":"《太平惠民和剂局方》卷二·治伤寒"},{"label":"组成","value":"川芎 12g，荆芥 12g，白芷 6g，羌活 6g，甘草 6g，细辛 3g，防风 4.5g，薄荷 12g（后下），清茶调服"},{"label":"用法","value":"上为细末，每服 6g，食后茶清调下"},{"label":"功用","value":"疏风止痛"},{"label":"主治","value":"外感风邪头痛。偏正头痛，或巅顶作痛，恶寒发热，目眩鼻塞，舌苔薄白，脉浮"}],"image":"","imageHint":"川芎","summary":"川芎茶调散为《太平惠民和剂局方》疏风止痛之代表方，主治外感风邪头痛。川芎为君，祛风止痛、活血行气，为治头痛要药；荆芥、防风、羌活、白芷、细辛、薄荷疏散风邪、通络止痛为臣；清茶清利头目、兼制辛散，炙甘草调和诸药为佐使。全方以轻清疏散之品外散风邪、以川芎直达巅顶而止痛，为治外感头痛之良方。临床用于感冒头痛、偏头痛、血管神经性头痛、紧张性头痛、鼻窦炎、额窦炎等属外感风邪者。因辛散升扬，肝阳上亢、血虚头痛者不宜。","blocks":[{"type":"paragraph","text":"外感风邪，客于巅顶，阻遏经络，气血不利则头痛；风邪袭表则恶寒发热、目眩鼻塞；舌苔薄白、脉浮为风邪在表之征。此类头痛多呈胀痛、连及眉棱骨或巅顶，遇风加重。治当疏风散邪、通络止痛。若肝阳上亢所致眩晕头痛、肾虚髓空所致空痛不移，则非本方所宜，须辨证而施。"},{"type":"table","caption":"川芎茶调散君臣佐使配伍表","head":["药物","配伍地位与作用","常用剂量"],"rows":[["川芎","君：祛风止痛，活血行气，上行巅顶，为治头痛之要药","12g"],["荆芥、防风","臣：祛风散邪，助川芎外散风邪","12g／4.5g"],["羌活、白芷、细辛","臣：散太阳、阳明风邪，止痛通络","各 6g／6g／3g"],["薄荷","佐：疏散风热，清利头目，制约川芎之升散","12g"],["清茶","佐：清利头目，制约诸药之辛燥","少许调服"],["炙甘草","使：益气和中，调和诸药，缓辛散耗气之性","6g"]]},{"type":"paragraph","text":"本方配伍以「轻清外散、直达病所」为特点。川芎辛温香窜，走而不守，祛风止痛、活血行气，能上行巅顶、下行血海，为治头痛之要药，为君；单用川芎虽能止痛，但恐其辛散耗气、升散太过，故配伍大队轻清之品以散风邪。荆芥、防风辛散祛风，善散太阳之风；羌活善散太阳经风邪而止痛；白芷善散阳明经风邪而止痛；细辛止痛力强、通窍祛风；薄荷辛凉，疏散风热、清利头目，六药为臣，助川芎外散风邪、通络止痛，且各有经络专长。炙甘草益气和中、调和诸药，兼制辛散升扬、耗气伤正之弊；清茶苦甘微寒，清热利头目、兼制诸药之辛燥，并为使。综观全方：川芎直达巅顶止痛为君，荆防羌芷辛薄散风为臣，甘草茶清和中清利为使；散风与止痛并重、疏邪而不伤正，故为治外感风邪头痛之代表方。因川芎兼有活血行气之功，本方对风邪兼气滞、血瘀之头痛尤宜。"},{"type":"callout","variant":"info","title":"加减化裁与临床应用","text":"风寒重加苏叶、生姜、羌活量；风热重去羌活细辛，加菊花、僵蚕、桑叶；鼻塞流涕加辛夷、苍耳子；鼻窦炎加苍耳子、白芷、辛夷、桔梗；阳明头痛（前额痛）加葛根、白芷；少阳头痛（侧痛）加柴胡、黄芩；太阳头痛（后枕痛）加羌活、葛根、蔓荆子；巅顶痛加藁本、僵蚕；久痛加全蝎、蜈蚣、白附子（牵正散意）；血瘀头痛加桃仁、红花、赤芍。临床用于感冒头痛、偏头痛、血管神经性头痛、紧张性头痛、鼻窦炎、额窦炎、枕神经痛等属外感风邪者。"},{"type":"callout","variant":"warning","title":"禁忌与注意事项","text":"本方辛散升扬，气血虚弱、肝阳上亢、肝火上炎、阴虚阳亢所致头痛眩晕者不宜，误投可致头胀目赤、烦躁失眠甚至加重病情；高血压病属肝阳上亢者尤当忌之。孕妇慎用；体虚者当减量并加益气养血之品。服药期间忌食辛辣炙煿及酒类，注意休息、避免强光与噪声刺激。若头痛突然剧烈、伴呕吐、意识障碍、肢体麻木无力，须立即就医排除脑出血等急症。"},{"type":"quote","text":"川芎茶调散荆防，辛芷薄荷甘草尝，疏风止痛治头痛，偏正头疼悉能康。","source":"《汤头歌诀·川芎茶调散歌》"},{"type":"keypoints","title":"掌握要点","items":["疏风止痛，主治外感风邪头痛：偏正头痛、巅顶痛、恶寒发热、鼻塞、脉浮","川芎为君祛风止痛直达巅顶，荆防羌芷辛薄为臣散各经风邪","清茶清利头目、炙甘草调和，辛散而不耗气","肝阳上亢、气血虚弱之头痛禁用；剧烈头痛伴呕吐须急诊"]}]}]}},"acupuncture":{"page":{"key":"acupuncture","title":"针灸经络","subtitle":"经络腧穴·刺法灸法·配穴处方·临床主治","description":"针灸学专题：经络系统总论、十二经脉、奇经八脉、腧穴分类与特定穴、毫针刺法与灸法、配穴处方原则、常见病针灸主治及操作禁忌，全部依据现行教材与经典文献整理。","lead":"经络者，脉之通行也；腧穴者，针灸之门户也。本辑自《灵枢》《针灸甲乙经》而下，系统整理经络系统的组成与功能、十二经脉的循行与病候、奇经八脉的功能主治、腧穴的分类与特定穴主治规律，以及毫针刺法、灸法的操作要领与异常处理，并给出常见病的针灸配穴处方与临床注意事项。针刺深度、剂量与手法须由合格针灸医师依证把握，切勿自行操作。","type":"section","icon":"fa fa-mountain","sections":[{"id":"meridian-overview","title":"经络总论","subtitle":"经络系统的组成、生理功能与辨证意义","icon":"🕸","summary":"经络是联络脏腑、体表与官窍的运行气血通道，由经脉、络脉及其附属结构构成，具沟通上下、运行气血、感应传导、调节虚实之功。","badge":"基础","blocks":[{"type":"paragraph","text":"经络是人体气血运行的通道，也是脏腑功能活动在体表的反映。《灵枢·经脉》开篇即言「经脉者，所以能血气百脉之运行也」，指出十二经脉内属于脏腑，外络于肢节，是沟通上下内外、联系脏腑体表的网络系统。经络有经脉与络脉之分：经脉是气血运行的主要通道，多直行于深层；络脉是经脉的分支，多浅行于体表。二者相互衔接，纵横交错，把人体内外连成一个有机整体。"},{"type":"heading","level":3,"text":"一、经络系统的组成"},{"type":"paragraph","text":"经络系统由经脉、络脉及其附属成分（皮部、筋、结、腧穴等）共同构成。其主体包括十二经脉、奇经八脉、十二经别、十二经筋、十二皮部，并有十五别络、浮络、孙络、十二经别络、十五络脉等分支结构，另有腧穴三百六十五穴及经外奇穴。十二经脉是气血运行的主体，内属脏腑、外络肢节，五脏六腑、头面躯干四肢的病变皆可通过经络反映于体表；奇经八脉调节蓄溢十二经气血，与十二经密切配合。"},{"type":"list","ordered":false,"items":["十二经脉：手太阴肺经、手阳明大肠经、足阳明胃经、足太阴脾经、手少阴心经、手太阳小肠经、足太阳膀胱经、足少阴肾经、手厥阴心包经、手少阳三焦经、足少阳胆经、足厥阴肝经，是气血运行的主干，故称「正经」","奇经八脉：督脉、任脉、冲脉、带脉、阴跷脉、阳跷脉、阴维脉、阳维脉，不与脏腑直接相属而别络十二经，有调节气血、沟通阴维阳维的功能","十二经别：多从四肢肘膝以上正经别出，深入体腔，联系脏腑，再上行头项，多仍归属本经经脉，加强了内外上下脏腑与头面的联系","十二经筋：多结聚于四肢关节、骨骼，走向多起于四肢末端上行头项，起于躯干者多下行四肢，主司关节运动与筋的功能","十二皮部：经络在体表的分区，是十二经脉在体表的对应范围，与皮肤、肌肉、腠理相应，为经络系统最外层屏障","十五别络：十二经脉各一络脉，加任督各一络、脾之大络，共十五络；此外有浮络、孙络等更细小的分支"]},{"type":"heading","level":3,"text":"二、经络的生理功能"},{"type":"paragraph","text":"《灵枢·经别》指出「十二经脉者，人之所以生，血之所以通调也」。经络的生理功能可概括为以下四个方面，这四者互相关联，共同维持人体气血津液的正常运行与脏腑功能的协调平衡，也是针灸、推拿等外治法能够起效的理论基础。"},{"type":"cards","columns":2,"items":[{"icon":"🔗","title":"沟通表里上下","text":"经络内联脏腑、外达肢节，十二经别、络脉加强了表里经、上下部位的 联系，使脏腑之气可输布于体表，体表之邪亦可内传脏腑。","bullets":["十二经脉属脏腑络属，形成表里配合关系","经别、络脉沟通上下、内外、左右","是整体观念在经络学中的体现"]},{"icon":"🩸","title":"运行气血","text":"气血由脏腑化生，循行于经脉之中，内荣脏腑、外濡腠理，濡养五官九窍、四肢百骸。","bullets":["《灵枢·营卫生会》：「营行脉中，卫行脉外」","经脉为气血运行之道路","气滞血瘀则经络不通而痛"]},{"icon":"✋","title":"感应传导","text":"经络是针灸、推拿等刺激信息传导的通路，刺激体表腧穴可引发酸麻胀重并沿经传导，脏腑功能亦能通过经络反映于体表。","bullets":["得气感应可循经传导","病变远处可出现压痛、条索、结节等反应","为经络诊察与治疗提供依据"]},{"icon":"⚖️","title":"调节虚实","text":"通过针灸的补泻手法，可调节经络气血盛衰，使失调的脏腑功能恢复平衡，即「以通为用、泻有余补不足」。","bullets":["虚则补之、实则泻之","循经取穴与整体配穴并重","调畅气机、调和阴阳是治疗总纲"]}]},{"type":"heading","level":3,"text":"三、经络辨证的意义"},{"type":"paragraph","text":"经络辨证是中医辨证体系的重要组成部分，其核心在于以经络循行路线为依据，结合患者症状体征与体表反应，判断病变所在经、所在脏腑，从而确定治疗原则与选经取穴。《灵枢·经脉》详载十二经脉「是动则病」与「是主所生病」两类病候，历代医家据此建立了经络辨证的方法，至今仍指导临床。"},{"type":"table","caption":"经络辨证常用方法一览","head":["辨证方法","主要内容","临床应用"],"rows":[["循行部位辨证","按经脉循行所过部位出现的症状归属相应经脉","颈项强痛属太阳经，巅顶痛属厥阴经，肩痛属阳明经"],["经脉病候辨证","依《灵枢》「是动」「所生」病候对照","咳喘属肺经，胸胁胀痛属肝胆经，心悸胸痛属心经心包经"],["体表反应辨证","腧穴压痛、条索、结节、皮肤色泽与温度改变","肝俞、期门压痛多提示肝郁气滞；阿是穴常为病所所在"],["脉诊辨经","寸口脉位分部候脏腑，配合全身脉象","左寸候心，右关候脾胃，右尺候肾"],["经络病机辨证","经络空虚则风寒湿邪易乘虚入络，留滞而痹","痹证按痛处所在经辨内外邪与虚实"]]},{"type":"quote","text":"经脉十二者，人之所以生，血之所以通调也。","source":"《灵枢·经别》"},{"type":"callout","variant":"info","title":"学习与临床提示","text":"经络辨证须与脏腑辨证、八纲辨证、气血津液辨证相互参照，不可偏执一端。临床应用时通常先辨病位所在经络，再据「经络所过，主治所及」的原则选取本经及表里经腧穴，并配合辨证配穴。切记经络有别脏腑概念：手太阴肺经之「肺」既指肺脏，也指肺经循行与肺的功能系统，临证需结合症状综合判断。"},{"type":"keypoints","title":"掌握要点","items":["经络由经脉、络脉组成，主体含十二经、奇经八脉、经别、经筋、皮部","十二经脉内属脏腑、外络肢节，是气血运行主干","奇经八脉调节蓄溢十二经气血，不与脏腑直接相属","生理功能四要点：沟通表里上下、运行气血、感应传导、调节虚实","经络辨证以循行部位、病候、体表反应为主要依据"]}]},{"id":"twelve-meridians","title":"十二经脉","subtitle":"循行路线、所属脏腑、表里配属与常见病候","icon":"🌿","summary":"十二经脉首尾相贯、内外相合，分属十二脏腑、按手足阴阳分为六对表里经，是经络辨证与循经取穴的基本依据。","badge":"重点","blocks":[{"type":"paragraph","text":"十二经脉是经络系统的主体，按「手太阴肺经—手阳明大肠经—足阳明胃经—足太阴脾经—手少阴心经—手太阳小肠经—足太阳膀胱经—足少阴肾经—手厥阴心包经—手少阳三焦经—足少阳胆经—足厥阴肝经」的次序流注，始于手太阴肺经，终于足厥阴肝经，复注于手太阴肺经，如环无端。其在头面、躯干、四肢的分布有规律：在四肢部内侧为阴经、外侧为阳经，阴经在前、阳经在后（足厥阴在前、足少阴在中、足太阴在后）；在头面部，阳明经行于面部，太阳经行于面颊、头后，少阳经行于头侧；躯干部为手三阴经、手三阳经、足三阳经，足三阴经不行于体表而循行于腹。"},{"type":"heading","level":3,"text":"一、十二经脉循行与主治要点"},{"type":"cards","columns":3,"items":[{"icon":"☁️","title":"手太阴肺经","text":"起于中焦，下络大肠，还循胃口，上膈属肺；从肺系横出腋下，沿上臂内侧前缘下行，过肘窝、前臂内侧前缘，入寸口、上鱼际，循鱼际至拇指。","bullets":["循行方向：手（阴经）","所属脏腑：肺；联络脏腑：大肠","表里经：与手阳明大肠经相表里","体表部位：胸肩、上臂内侧前缘、前臂内侧前缘、拇指","主治要点：咳嗽、气喘、咯血、咽喉肿痛、胸痛、缺盆中痛、掌中热痛"]},{"icon":"🌉","title":"手阳明大肠经","text":"起于食指末端，沿前臂桡侧上行，经肘窝、上臂外侧前缘至肩，上出柱骨之会上，下入缺盆络肺、下膈属大肠；其支者从缺盆上颈贯颊入下齿，还出挟口交人中；另一支从缺盆至胸，上出四末之上。","bullets":["循行方向：手（阳经）","所属脏腑：大肠；联络脏腑：肺","表里经：与手太阴肺经相表里","体表部位：食指桡侧、前臂桡侧、上臂外侧前缘、肩部、颈部、面颊","主治要点：齿痛、口㾦、咽痛、颈肿、腹痛、肠鸣泄泻、便血、痔疾、肩背痛"]},{"icon":"🍚","title":"足阳明胃经","text":"起于鼻旁，下循鼻外，入上齿中，出夹口环唇，下交承浆，却循颐后下廉，出大迎，循颊车至下关，入上齿中；其支者循喉咙，入缺盆，下膈属胃络脾；直行者下乳内廉，下行至气街中而伏；另支起于胃口，下腹内，下至气街中而合下行。","bullets":["循行方向：足（阳经）","所属脏腑：胃；联络脏腑：脾","表里经：与足太阴脾经相表里","体表部位：面部（鼻、齿、颊）、颈、膺乳、腹、股前、胫前、足背","主治要点：胃痛、呕吐、呃逆、腹胀、肠鸣、便秘、癫狂、痹证、半身不遂"]},{"icon":"🌾","title":"足太阴脾经","text":"起于大趾丛毛之际，沿足内侧上行至内踝前，上行胫后缘，交出足厥阴经之前，上行膝、大腿内侧，入腹属脾络胃；其支者复从胃别，上膈，注于心中。","bullets":["循行方向：足（阴经）","所属脏腑：脾；联络脏腑：胃","表里经：与足阳明胃经相表里","体表部位：足大趾、足内侧、胫内侧、膝内侧、腹、胸部","主治要点：腹胀、腹泻、呕吐、便秘、便血、纳呆、倦怠乏力、月经不调、带下、脏躁"]},{"icon":"❤️","title":"手少阴心经","text":"起于心中，出属心系，下膈络小肠；其支者从心系上挟咽系目系；其直者复从心系却上肺，下出腋下，沿上臂内侧后缘行至手少阴、厥阴经之后，下肘内、循前臂内侧后缘至掌后锐骨之端，入掌内后廉。","bullets":["循行方向：手（阴经）","所属脏腑：心；联络脏腑：小肠","表里经：与手太阳小肠经相表里","体表部位：腋、上臂内侧后缘、前臂内侧后缘、掌后（小指侧）","主治要点：心痛、心悸、怔忡、失眠、多梦、健忘、咽干口燥、掌中热痛、癫狂痫"]},{"icon":"☀️","title":"手太阳小肠经","text":"起于小指外侧端，沿手背尺侧上腕、出尺骨小头，直上沿上臂后缘至肩，绕肩胛交肩上入缺盆，络心、循咽下膈抵胃属小肠；其支者从缺盆循颈上颊至目锐眦，却入耳中；另一支别颊上䪼，抵鼻，至目内眦斜络于颧。","bullets":["循行方向：手（阳经）","所属脏腑：小肠；联络脏腑：心","表里经：与手少阴心经相表里","体表部位：小指外侧、手背尺侧、上臂后缘、肩胛、颈、面颊、耳前目外眦","主治要点：头痛项强、肩背痛、耳鸣耳聋、目赤肿痛、咽喉痛、小指麻木、癫狂痫"]},{"icon":"💧","title":"足太阳膀胱经","text":"起于目内眦，上额，交巅；其支者从巅至耳上角；直者从巅入络脑，还出别下项，循肩髆内挟脊抵腰中，入循膂络肾属膀胱；其支者从腰中下挟脊贯臀入腘中；另一支从髀枢下循胫外廉下抵足外廉，出外踝之后入足小趾外侧。","bullets":["循行方向：足（阳经）","所属脏腑：膀胱；联络脏腑：肾","表里经：与足少阴肾经相表里","体表部位：头项、背腰、臀部、下肢后侧、足外侧、小趾","主治要点：头痛项强、腰背痛、下肢痿痹、癫狂痫、疟疾、小便不利、遗尿、痔疾"]},{"icon":"🌊","title":"足少阴肾经","text":"起于足小趾之下，斜走足心，出于舟骨粗隆之下，沿内踝后上行于足内侧，上行小腿内侧、膝窝内，上股内侧后缘，贯脊属肾络膀胱；其支者从肾出，络肺、注胸中。","bullets":["循行方向：足（阴经）","所属脏腑：肾；联络脏腑：膀胱","表里经：与足太阳膀胱经相表里","体表部位：足心、足内侧、内踝后、小腿内侧、股内侧后缘、脊、胸部","主治要点：遗精、阳痿、月经不调、带下、遗尿、癃闭、腰痛、膝痛、喘咳、盗汗、齿痛、耳鸣耳聋"]},{"icon":"🛡️","title":"手厥阴心包经","text":"起于胸中，出属心包络，下膈历络三焦；其支者循胸出胁，上抵腋下，沿上臂内侧行于手太阴、手少阴之间，入肘中、下前臂两筋之间，入掌中循中指出其端；另一支从掌中分出，循无名指出其端。","bullets":["循行方向：手（阴经）","所属脏腑：心包（代心受邪）；联络脏腑：三焦","表里经：与手少阳三焦经相表里","体表部位：胸胁、腋、上臂内侧、前臂内侧两筋之间、掌中、无名指","主治要点：心痛、心悸、胸胁胀痛、癫狂痫、昏厥、腋肿、掌中热痛"]},{"icon":"🔥","title":"手少阳三焦经","text":"起于无名指末端，沿手背第四、五掌骨间上行至腕，出前臂两骨之间，上贯肘、循上臂外侧上肩，交出足少阳之后，入缺盆布膻中，散络心包，下膈属三焦；其支者从膻中上出缺盆上项，系耳后，直上出耳上角，屈下颊至䪼；另一支从耳后入耳中出走耳前过客主人前交颊至目锐眦。","bullets":["循行方向：手（阳经）","所属脏腑：三焦；联络脏腑：心包","表里经：与手厥阴心包经相表里","体表部位：无名指、手背、腕、前臂外侧两骨之间、上臂外侧、肩、颈、耳周、面颊","主治要点：头痛、耳鸣耳聋、目赤肿痛、咽喉肿痛、热病、胸胁支满、上肢痹痛、癫狂痫"]},{"icon":"🌙","title":"足少阳胆经","text":"起于目锐眦，上抵头角，下耳后循颈行手少阳之前，至肩上却交出手少阳之后，入缺盆；其支者从耳后入耳中出走耳前，至目锐眦后；另一支别锐眦，下大迎，合于手少阳，抵于䪼，下加颊车，下颈合缺盆以下胸中，贯膈，络肝，属胆，循胁里出气街，绕毛际，横入髀厌中；直者循伐谷至髀关节外侧，下循胸外后廉，下至腘中，下出外踝之前，循足背出内踝，止于第四趾外侧。","bullets":["循行方向：足（阳经）","所属脏腑：胆；联络脏腑：肝","表里经：与足厥阴肝经相表里","体表部位：头侧、耳前后、目外眦、颈、胁肋、髋、股外侧、小腿外侧、足背","主治要点：偏头痛、目眩、耳鸣耳聋、胁肋痛、半身不遂、下肢痿痹、瘰疬、黄疸、口苦、呕吐"]},{"icon":"🌿","title":"足厥阴肝经","text":"起于大趾丛毛之际，沿足背上行至内踝前一寸，复上踝上八寸交出足太阴之后，上行膝内侧，循股阴入毛中，过阴器，抵小腹，挟胃属肝络胆，上膈，循喉咽，目入巅；其支者从目系下颊里，环唇内；另一支复从肝别贯膈上注肺。","bullets":["循行方向：足（阴经）","所属脏腑：肝；联络脏腑：胆","表里经：与足少阳胆经相表里","体表部位：足大趾、足背、内踝前、膝内侧、股阴部、外阴、小腹、胁肋、咽喉、目系、巅顶","主治要点：胁肋胀痛、疝气痛、睾丸偏坠、头痛眩晕、目赤肿痛、癫狂痫、月经不调、乳痈、口苦、郁证"]}]},{"type":"heading","level":3,"text":"二、十二经脉对照表"},{"type":"table","caption":"十二经脉循行体表与常见病候对照表","head":["经脉名称","所属脏腑","循行体表部位","常见病候"],"rows":[["手太阴肺经","肺（络大肠）","胸肩→上臂内侧前缘→前臂内侧前缘→拇指","咳嗽、气喘、咯血、咽痛、胸痛、缺盆中痛、掌中热痛"],["手阳明大肠经","大肠（络肺）","食指桡侧→前臂桡侧→上臂外侧前缘→肩→颈→面部","齿痛、口㾦、咽痛、颈肿、腹痛、肠鸣泄泻、便血、痔疾"],["足阳明胃经","胃（络脾）","面（鼻齿颊）→颈→膺乳→腹→股前→胫前→足背","胃痛、呕吐、呃逆、腹胀、肠鸣、便秘、癫狂、痹证、半身不遂"],["足太阴脾经","脾（络胃）","足大趾→足内侧→胫内侧→膝内侧→腹→胸","腹胀、泄泻、呕吐、便秘、便血、纳呆、倦怠、月经不调、带下、脏躁"],["手少阴心经","心（络小肠）","腋→上臂内侧后缘→前臂内侧后缘→掌后小指侧","心痛、心悸、怔忡、失眠、多梦、健忘、咽干、掌中热痛、癫狂痫"],["手太阳小肠经","小肠（络心）","小指外侧→手背尺侧→上臂后缘→肩胛→颈→面颊→耳前目外眦","头痛项强、肩背痛、耳鸣耳聋、目赤肿痛、咽喉痛、癫狂痫"],["足太阳膀胱经","膀胱（络肾）","目内眦→头项→背腰→臀→下肢后侧→足外侧→小趾","头痛项强、腰背痛、下肢痿痹、癫狂痫、疟疾、小便不利、遗尿、痔疾"],["足少阴肾经","肾（络膀胱）","足心→足内侧→内踝后→小腿内侧→股内侧后缘→脊→胸","遗精、阳痿、月经不调、遗尿、癃闭、腰痛、喘咳、盗汗、齿痛、耳鸣"],["手厥阴心包经","心包（络三焦）","胸胁→腋→上臂内侧→前臂两筋之间→掌中→无名指","心痛、心悸、胸胁胀痛、癫狂痫、昏厥、腋肿、掌中热痛"],["手少阳三焦经","三焦（络心包）","无名指→手背→前臂外侧→上臂外侧→肩→颈→耳周→面颊","头痛、耳鸣耳聋、目赤肿痛、咽喉肿痛、热病、胸胁支满、癫狂痫"],["足少阳胆经","胆（络肝）","目外眦→头侧耳前后→颈→胁肋→髋→股外侧→小腿外侧→足背","偏头痛、目眩、耳鸣耳聋、胁痛、半身不遂、瘰疬、黄疸、口苦、呕吐"],["足厥阴肝经","肝（络胆）","足大趾→足背→内踝前→膝内侧→外阴→小腹→胁肋→巅顶","胁痛、疝痛、睾丸偏坠、头痛眩晕、目赤、癫狂痫、月经不调、乳痈、口苦"]]},{"type":"paragraph","text":"十二经脉的表里配属与交接流注具有严格规律。手三阴经从胸走手，手三阳经从手走头，足三阳经从头走足，足三阴经从足走腹（胸），如此首尾相贯，如环无端，构成「流注次序」。相表里的阴经与阳经在四肢内外相对位置上交接，如手太阴肺经与手阳明大肠经在食指端交接，足阳明胃经与足太阴脾经在足大趾交接，足太阴脾经与足厥阴肝经在足背交接。手足同名阳经在头面部交接，足三阴经与手三阴经在胸部交接。把握这一规律，是理解经络气血运行、理解腧穴主治「经脉所过，主治所及」的关键。"},{"type":"callout","variant":"info","title":"循经取穴与络脉应用","text":"十二经脉病候是循经取穴的直接依据。如咳喘取肺经太渊、鱼际；颈项强痛取太阳经后溪、申脉；胁痛取胆经阳陵泉、肝经太冲；胃脘痛取胃经足三里；腰痛取膀胱经委中、肾经太溪。表里经可互相为用，如肺经虚可配大肠经，合谷补而尺泽泻。络脉十五别络各有其主治，如手太阴络脉列缺可治胸背与头项病，脾之大络大包可治周身疼痛。"},{"type":"quote","text":"十二经脉者，人之所以生，血之所以通调也。","source":"《灵枢·经别》"},{"type":"keypoints","title":"掌握要点","items":["流注次序：肺→大肠→胃→脾→心→小肠→膀胱→肾→心包→三焦→胆→肝→复注肺","四肢分布：阴经内侧、阳经外侧；头面：阳明面、太阳颊后、少阳头侧","同名阳经在头面交接，足三阴经与手三阴经在胸腹部交接","循经取穴依据「经脉所过，主治所及」，表里经可同用","十二经病候有「是动」与「所生」两类，当细辨虚实"]}]},{"id":"extraordinary-vessels","title":"奇经八脉","subtitle":"循行、功能、主治与八脉交会穴","icon":"🌀","summary":"奇经八脉别络十二经，调节气血蓄溢，督脉总督阳经、任脉总任阴经、冲脉为血海、带脉约束纵行诸脉。","badge":"重点","blocks":[{"type":"paragraph","text":"奇经八脉是十二经脉之外的八条经脉，包括督脉、任脉、冲脉、带脉、阴跷脉、阳跷脉、阴维脉、阳维脉。它们不与五脏六腑直接相属，亦无表里配属关系，但别络于十二经脉，与正经相互沟通，故有「奇经」之称。《难经·二十八难》说「奇经者，别于十二经也」，指出奇经具有调节正经气血盛衰的作用：正经气血有余时，奇经可蓄之；不足时，奇经可输之，正所谓「蓄溢十二经气血」。"},{"type":"paragraph","text":"八脉之中，督脉行于背正中，总督一身之阳经，故称「阳脉之海」；任脉行于腹正中，总任一身之阴经，为「阴脉之海」，并与妊娠有关；冲脉为「血海」，与月经、胎产密切相關；带脉横行约束诸经；跷脉主司下肢运动与眼睑开合；维脉维系一身阴经阳经。八脉虽各有特点，但在临床上常相须为用，如督脉、任脉相配调阴阳，任脉、冲脉相合为「血海」，带脉合于冲任而主妇科。"},{"type":"table","caption":"奇经八脉循行、功能与主治对照表","head":["经脉","循行路线","生理功能","主治要点"],"rows":[["督脉","起于小腹内，下出会阴，向后行于脊柱内部，上达项后风府，入脑内，再下出项部，循行至头正中；支脉从少腹下出会阴，与任脉、冲脉合于关元；另支起于目内眦，下额至人中","总督一身之阳经，总阳脉之海，调节阳经气血","脊柱强痛、角弓反张、疟疾、癫狂痫、热病、阳痿、遗精、虚劳羸瘦、泄泻、便血"],["任脉","起于小腹内，下出会阴，向前上行于阴毛部，沿腹部正中线上行，至咽喉，上行至下颌部，环绕口唇，沿面颊上至目眶下；分支从目系下至颔部，散于舌本","总任一身之阴经，为阴脉之海，主胞胎、调理冲任","生殖系统疾患、月经不调、带下、遗精、阳痿、胎动不安、脘腹疼痛、呃逆、咽干、癫狂痫"],["冲脉","起于小腹内，下出会阴，与任脉、督脉同起（会于气冲），沿腹腔前壁向上至咽喉，分布于口唇；其支脉与阳明经并行，环绕口唇；另支从胸中下挟脐两旁，下至股内；交会于足阳明经于气冲","为十二经之海、血海，涵蓄调节全身气血","月经不调、痛经、崩漏、闭经、胎动不安、恶露不绝、气逆喘咳、脘腹胀痛、癫狂痫"],["带脉","起于季胁（肋下），斜向下行至腰，横行环绕腰腹一周，交会于足少阳经之章门穴，如束带约束诸脉","约束纵行诸经，固摄下元，主司腰腹纵行诸脉之约束","腰以下各种病证：腰胁痛、腹痛、疝气、经闭、带下、崩漏、阴挺、肠鸣、泄泻"],["阴跷脉","起于足内踝下照海穴，上行于内踝后直上，沿小腿内侧上行过膝，经大腿内侧上行至会阴，再上行于胸腹，至咽喉，交会于睛明穴，与阳跷脉相会","主司下肢内侧运动，调节眼睑开合，司眼睑开合与下肢内侧肌肉活动","阴盛阳衰之嗜睡、癫狂痫、失眠、多梦、半身不遂、下肢痿痹、痛经、月经不调"],["阳跷脉","起于足外踝下申脉穴，上行外踝后，沿小腿外侧上行过膝，经大腿外侧上行至会阴，再上行于胸腹，至肩颈，至头项，至口角，至目内眦，与阴跷脉相会","主司下肢外侧运动，调节眼睑开合，司眼睑开合与下肢外侧肌肉活动","阳盛阴衰之失眠、癫狂痫、头痛、眩晕、肢体麻木、半身不遂、腰痛、下肢痿痹"],["阴维脉","起于足内踝下筑宾穴，上行于小腿内侧，经膝内侧上行至大腿内侧，循股阴而上，交会于腹部，与任脉会于脐上；其支者上挟咽，与手少阴经交于胸中","维络诸阴，主一身之里，维护阴经气血运行","心悸、怔忡、失眠、胸胁痛、癫狂痫、呕吐、泄泻、腹痛、胎动不安、癔病"],["阳维脉","起于足外踝下金门穴，上行于外踝后，沿小腿外侧上行过膝，经大腿外侧上行至胁部，交会于肩部，与手少阳经交；其支者上行于头项，至耳后，至肩上，至巅顶，与督脉会于风府","维络诸阳，主一身之表，维护阳经气血运行","外感表证、头痛项强、腰痛、腿痛、疟疾、寒热、耳鸣耳聋、胁肋痛、痹证"]]},{"type":"heading","level":3,"text":"八脉交会穴"},{"type":"paragraph","text":"八脉交会穴是奇经八脉与十二经脉在四肢腕踝部相通的八个腧穴，分别为公孙、内关、后溪、申脉、足临泣、外关、列缺、照海。八穴分属四组配对，每组两穴相配，再与相应奇经相联，主治范围相当明确。此即《针灸大成》所载「公孙冲脉胃心胸，内关阴维下总同，列缺任脉行头项，肩颈胸膈关维方，后溪督脉目内眦，颈项耳肩俱可详，申脉阳跷络亦通，耳颡肩背内关脏，臨泣胆经连带脉，阳维目锐外关逢」的歌诀。"},{"type":"table","caption":"八脉交会穴配对主治表","head":["八脉交会穴","所属经脉","相配奇经","主治病证"],"rows":[["公孙（足太阴脾经）","脾经，通冲脉","内关（手厥阴心包经）通阴维","心、胸、胃疾患，如胃痛、呕吐、胸胁胀痛、心悸、癫狂痫"],["内关（手厥阴心包经）","心包经，通阴维脉","公孙通冲脉","心、胸、胃疾患，如心痛、心悸、胸闷、呕吐、呃逆"],["足临泣（足少阳胆经）","胆经，通带脉","外关（手少阳三焦经）通阳维","目外眦、耳后、肩颈、耳颡、颊、项、胁肋等少阳部疾患"],["外关（手少阳三焦经）","三焦经，通阳维脉","足临泣通带脉","偏头痛、耳鸣耳聋、目赤肿痛、胁肋痛、落枕、上肢痹痛"],["后溪（手太阳小肠经）","小肠经，通督脉","申脉（足太阳膀胱经）通阳跷","目内眦、颈项、耳、肩、膊、腰痛、腿痛，及癫狂痫、疟疾"],["申脉（足太阳膀胱经）","膀胱经，通阳跷脉","后溪通督脉","目内眦、颈项、耳、肩背、腰痛、腿痛、失眠、癫狂痫"],["列缺（手太阴肺经）","肺经，通任脉","照海（足少阴肾经）通阴跷","头项、胸部、咽喉、肺系疾患，如头痛项强、咳嗽、咽干、癫狂痫"],["照海（足少阴肾经）","肾经，通阴跷脉","列缺通任脉","咽喉、口舌、失眠、嗜睡、小便不利、疝气、癔病、月经不调"]]},{"type":"callout","variant":"info","title":"奇经辨证与临床运用","text":"奇经病候的辨识，多从「病在奇经」与「正经自病」两方面考虑。如督脉病多见脊强反折、角弓反张；任脉病多见妇人妊娠、月经、带下诸疾；冲脉病多见气逆、血崩、胎动；带脉病多见腰腹纵行诸症；跷脉病多见肢体痿躄、失眠嗜睡；维脉病多见胸胁、脘腹、癫狂痫。治疗上常取本经募穴、背俞穴与八脉交会穴配合，如督脉虚寒取命门、关元、脊中；冲任虚寒取关元、气海、三阴交。"},{"type":"quote","text":"奇经者，别于十二经也，其十二经脉之气不能独行者也。","source":"《难经·二十八难》"},{"type":"keypoints","title":"掌握要点","items":["奇经八脉别络十二经，不与脏腑直接相属，主调节蓄溢气血","督脉为阳脉之海、任脉为阴脉之海、冲脉为血海、带脉约束诸脉","跷脉主下肢运动与眼睑开合，维脉维络阴阳，主内外协调","八脉交会穴：公孙、内关、后溪、申脉、足临泣、外关、列缺、照海","配对法：公孙配内关、后溪配申脉、足临泣配外关、列缺配照海"]}]},{"id":"acupoints","title":"腧穴总论","subtitle":"腧穴分类、五输穴与特定穴主治规律","icon":"📍","summary":"腧穴分十四经穴、经外奇穴与阿是穴；特定穴中五输穴按木火土金水规律主治，原络郄俞募会下交各有侧重，为临床配穴之枢机。","badge":"核心","blocks":[{"type":"paragraph","text":"腧穴是人体经络上气血所注的部位，是针灸等刺激的直接作用点。《针灸甲乙经》载经穴三百六十五穴，分属十二经与任督二脉，为后世所宗；后世又陆续发现经外奇穴，并补充了大量新穴。腧穴大致可分为十四经穴、经外奇穴与阿是穴三类，三者互相补充，共同构成临床选穴的完整体系。"},{"type":"table","caption":"腧穴分类对照表","head":["类别","含义","代表举例","临床意义"],"rows":[["十四经穴","归属于十二经脉及任督二脉的腧穴，共 361 个（现行教材数）","手太阴肺经 11 穴（云门、天府、侠白、尺泽、孔最、列缺、经渠、太渊、鱼际、少商）","经脉所过，主治所及，是循经取穴与辨证取穴的基础"],["经外奇穴","有明确位置与主治、但未归入十四经者","太阳穴、印堂、鱼际（虽属肺经实为奇穴）、定喘、阑尾、膝眼、肘尖、夹脊","补充正经之不足，多有专病专穴之效，如阑尾穴治急性阑尾炎"],["阿是穴","以压痛点或病痛反应点临时定位的腧穴，又称天应穴、阿是穴","颈项强痛处压痛点、腰痛局部压痛点","直达病所，多用于痛证与局部病变，取以痛为腧"]]},{"type":"paragraph","text":"腧穴的功能可概括为「近治」与「远治」两类。近治作用指腧穴对本经循行所过部位的局部病变具有主治作用，如肘中治肘部痛、悬钟治外踝痛，临床常取阿是穴与局部腧穴；远治作用指腧穴对远隔部位、脏腑的病证具有主治作用，如合谷治牙痛、足三里治胃脘痛、四关穴治头面病与上肢病。远治作用以经络学说为基础，具有整体性的特点。"},{"type":"heading","level":3,"text":"一、五输穴"},{"type":"paragraph","text":"五输穴指每经的五类特定腧穴，即井、荥、输、经、合，共十二经六穴六十穴，是经脉气血由浅入深、由四肢末端向躯干流注的五个阶段。《难经·六十八难》说「井所始，荥所流，输所注， 经所过， 合所会」，正是描述气血在经脉中的流注次序。"},{"type":"table","caption":"五输穴（井荥输经合）主治规律表","head":["五输穴","名称含义","所在部位","主治特点","举例"],"rows":[["井穴","所出为井，气血初生，如井泉之源","四肢末端（趾、指端）","主心下满（胸腹胀满）、神志病、癫狂痫、昏迷急救","少商（肺）、商阳（大肠）、厉兑（胃）、隐白（脾）、少冲（心）、少泽（小肠）、至阴（膀胱）、涌泉（肾）、中冲（心包）、关冲（三焦）、窍阴（胆）、大敦（肝）"],["荥穴","所溜为荥，气血初盛，如流人之泉","掌指（趾）关节附近","主身热（发热、口舌生疮、咽喉肿痛等）","鱼际（肺）、二间（大肠）、内庭（胃）、大都（脾）、少府（心）、前谷（小肠）、足通谷（膀胱）、然谷（肾）、劳宫（心包）、液门（三焦）、侠溪（胆）、行间（肝）"],["输穴","所注为输，气血渐盛，如注灌之流","腕（踝）关节附近","主体重节痛（关节疼痛、麻木、沉重）","太渊（肺）、合谷（大肠）、陷谷（胃）、太白（脾）、神门（心）、后溪（小肠）、束骨（膀胱）、太溪（肾）、大陵（心包）、阳池（三焦）、足临泣（胆）、太冲（肝）"],["经穴","所行为经，气血通畅流行，如经脉之径","前臂或小腿中部","主肺喘咳嗽、咽喉病及经脉循行所过诸病","经渠（肺）、阳溪（大肠）、解溪（胃）、商丘（脾）、灵道（心）、养老（小肠）、昆仑（膀胱）、复溜（肾）、间使（心包）、支沟（三焦）、阳辅（胆）、中封（肝）"],["合穴","所入为合，气血汇合，如江河入海","肘膝关节附近","主逆气、泄泻、呕吐等六腑病及局部关节病","尺泽（肺）、曲池（大肠）、足三里（胃）、阴陵泉（脾）、少海（心）、小海（小肠）、委中（膀胱）、阴谷（肾）、曲泽（心包）、天井（三焦）、阳陵泉（胆）、曲泉（肝）"]]},{"type":"callout","variant":"info","title":"五输穴临床应用要诀","text":"《难经·六十八难》归纳为「井主心下满，荥主身热，输主体重节痛，经主肺喘咳嗽，合主逆气而泄」。临床可据病性选穴：热病取荥穴，如肺热取鱼际、心火取少府；关节肿痛取输穴，如肘痹取太渊、膝痹取太溪；六腑病取合穴，如胃痛取足三里、肠鸣泄泻取阴陵泉；急救取井穴，如昏厥点刺少商、涌泉放血。亦有「以母补子」「以子泻母」之用法，须依五行生克与虚实而定，由医师权衡。"},{"type":"heading","level":3,"text":"二、常用特定穴"},{"type":"table","caption":"特定穴分类与主治规律详表","head":["特定穴类别","定义","分布特点","主治规律","举例"],"rows":[["原穴","十二经脉在四肢腕踝附近各有一个腧穴，为本经气血所注所过","多在腕踝关节附近","主治本经原脏腑疾病，可补虚泻实、调和本经气血","肺经太渊、大肠合谷、胃冲阳、脾太白、心神门、小肠阳谷、膀胱京骨、肾太溪、心包大陵、三焦阳池、胆丘墟、肝太冲"],["络穴","十二经脉各有一络穴，另加任督二络与脾之大络，共十五络","多在四肢肘膝以下，亦有位于躯干者（如长强、尾闾）","主治本经络脉循行部位的病证及表里两经之疾","肺列缺、大肠偏历、胃丰隆、脾公孙、心通里、小肠支正、膀胱飞扬、肾大钟、心包内关、三焦外关、胆光明、肝蠡沟"],["郄穴","十二经脉在四肢肘膝以下各有一个经气深聚之穴，共十二郄穴","均在肘膝以下，病情较急较重者多用","主治本经及所属脏腑的急性病、痛证、血证","肺孔最、大肠温溜、胃梁门、脾地机、心阴郄、小肠养老、膀胱金门、肾水泉、心包郄门、三焦会宗、胆外丘、肝中都"],["背俞穴","位于足太阳膀胱经第一侧线的十二个腧穴，为脏腑之气输注于背腰部的腧穴","第一胸椎至第四腰椎平面，旁开 1.5 寸","主治相应脏腑病证，并可治疗相应脏腑所主的五官、九窍、五体、五志疾病","肺俞、膏肓、心俞、督俞、肝俞、胆俞、脾俞、胃俞、三焦俞、肾俞、气海俞、大肠俞"],["募穴","脏腑之气汇聚于胸腹部的腧穴，称「脏腑募穴」，共 十二募穴","均位于胸腹部，且位置邻近所属脏腑","主治本脏腑病证；「俞募配穴」为经典配伍法；募穴多治腑病","肺中府、大肠天枢、胃中脘、脾章门、心巨阙、小肠关元、膀胱中极、肾京门、心包膻中、三焦石门、胆日月、肝期门"],["八会穴","脏腑、气、血、筋、脉、骨、髓的功能汇聚之处，共八穴","分布于躯干部四个区域","主治其所会功能相关的病证，如筋会阳陵泉治筋病、血会膈俞治血证","腑会中脘、脏会章门、气会膻中、血会膈俞、筋会阳陵泉、脉会太渊、骨会大杼、髓会绝骨"],["八脉交会穴","奇经八脉与十二经脉在四肢相通的八个腧穴","腕、踝关节附近","主治本经、本奇经及相关经脉病证，常两穴相配使用","公孙、内关、后溪、申脉、足临泣、外关、列缺、照海"],["下合穴","六腑在足三阳经脉上各有一个合穴，称六腑下合穴","均在膝关节以下","主治相应腑病，急性腑病多取下合穴，泻实作用强","大肠下合上巨虚、胃下合足三里、小肠下合下巨虚、膀胱下合委中、三焦下合委阳、胆下合阳陵泉"],["四总穴","临床常用、疗效确切、流传极广的四个腧穴","分别在腹部、腰部、肘膝部","主治范围广，为处方之核心穴","肚脐（神阙）治腹痛、泻泄；腰阳关治腰骶痛；膝眼、委中治膝痛与腰背痛；合谷治面口病"]]},{"type":"callout","variant":"info","title":"特定穴组合配伍举例","text":"临床常将特定穴成对使用，如「俞募配穴」治脏腑病：肺病取肺俞配中府、肾病取肾俞配京门；「原络配穴」（主客配穴）治表里经同病：肺经有病取肺经原穴太渊配大肠经络穴偏历；「八会配穴」治相应病证：筋病取阳陵泉、脉病取太渊；「郄穴」治急症：急性吐泻取胃郄梁门、急性心悸取心郄阴郄；下合穴治腑实：便秘取上巨虚、胆囊炎取阳陵泉。"},{"type":"quote","text":"井所始，荥所流，输所注，经所过，合所会。","source":"《难经·六十八难》"},{"type":"keypoints","title":"掌握要点","items":["腧穴分十四经穴（361 穴）、经外奇穴与阿是穴三类","腧穴作用含近治作用与远治作用，以经络学说为远治作用基础","五输穴：井主心下满，荥主身热，输主体重节痛，经主肺喘咳嗽，合主逆气而泄","特定穴：原穴主本脏腑、络穴主表里两经、郄穴主急症、背俞募穴主脏腑","八会穴：腑会中脘、脏会章门、气会膻中、血会膈俞、筋会阳陵泉、脉会太渊、骨会大杼、髓会绝骨","下合穴主治六腑病，急性腑实者多取；八脉交会穴常两两相配"]}]},{"id":"needling","title":"刺法灸法","subtitle":"毫针刺法、得气候气、异常处理与灸法要领","icon":"🪡","summary":"毫针刺法重在进针角度方向深度、行针手法与候气；灸法以艾炷、艾条为主，二者皆须守禁忌、明深浅、察反应。","badge":"操作","blocks":[{"type":"paragraph","text":"刺法是使用针具刺入人体腧穴以调畅气血、防治疾病的方法；灸法是借艾绒燃烧产生的温热刺激作用于腧穴以温通经络、扶正祛邪的方法。二者常合用为「针灸」。针刺操作的基本环节包括：针前准备（体位、消毒、器械检查）、进针、行针、留针、出针，以及各环节的异常处理与预防。临床疗效不仅取决于取穴，更取决于操作是否得当，故《灵枢·官能》强调「刺之要，气至而有效」。"},{"type":"heading","level":3,"text":"一、毫针刺法"},{"type":"paragraph","text":"毫针构造为针柄、针身、针尖三部分，针身多由不锈钢或钨丝制成，长短粗细规格不同，一般针身直径 0.25～0.35mm，长度 15～150mm 不等。针刺前应检查针体有无锈蚀、弯折，针尖有无钩毛，以无菌镊或无菌棉签逐支检查，并须一人一针一用一废弃，不得重复使用。"},{"type":"list","ordered":false,"items":["进针方法：持针式以拇、食、中三指夹持针柄；进针法有指切进针法（适合短针）、夹持进针法（适合长针）、舒张进针法（适合皮肤松弛处如腹部）、提捏进针法（适合皮肉浅薄处如印堂）","针刺角度：直刺（约 90°）、斜刺（约 45°）、平刺（约 15°～30°）；一般腧穴直刺，肌层较薄处斜刺或平刺，如头面部、胸腹部多平刺或斜刺","针刺方向：依据腧穴所在经脉循行、经络交会与局部解剖而定，如合谷向虎口方向斜刺、列缺向腕部斜刺","针刺深度：以得气为度，遵循「刺中脏腑者，慎针之」之戒；一般四肢躯干部 0.5～1.5 寸，胸背腰部 0.5～1 寸，头面颈部 0.3～0.5 寸，胖瘦老幼宜浅，肌肉丰厚者可深","行针基本手法：提插法、捻转法、循法、弹刮法、飞法、震颤法、捣法；辅助手法有循、弹、刮、摇、盘、捣、飞、颤等，并可配合爪切、押手、按揉、循摄等辅助","留针与出针：一般留针 15～30 分钟，体寒、体弱、痛经者酌加时间；出针时先摇大针孔再缓慢退出，随即按压针孔止血，并检查有无断针残留","得气与候气：得气表现为酸、麻、胀、重、凉、热感沿经传导；候气包括留针候气、循经候气、提插候气、间歇留针候气与守气等法"]},{"type":"paragraph","text":"得气是针刺取得疗效的关键环节，临床常以「酸麻胀重」为度，并有循经传导的感应。得气快、感应强者多疗效佳；不得气或感应微弱者，或因体虚正气不足，或因手法失当，须察因处置，如加强针感、延长候气时间、调整深度与角度，或配合补泻手法（捻转补泻、开阖补泻、徐疾补泻、迎随补泻）。此外，针刺感应与患者精神状态、体位、室温、医者手法均有关系，须综合判断，不可强求。"},{"type":"table","caption":"针刺常见异常情况处理表","head":["异常","临床表现","原因","处理方法"],"rows":[["晕针","突然头晕、面色苍白、心慌、恶心、出冷汗，甚至意识障碍、血压下降","精神紧张、体质虚弱、饥饿疲劳、手法过重、留针时患者体位不当","立即停针，取平卧或头低足高位，饮温开水或糖水，重者可灸百会、关元、气海；若不省人事掐人中、内关、足三里，必要时现代医学急救"],["滞针","针体在穴内捻转提插均感涩滞、不能运针","单向连续捻转致肌纤维缠绕，或患者精神紧张局部肌肉强直","放松患者，延长留针时间；在滞针穴位周围行循、弹、刮等辅助手法；单向捻转者须反向退针待针体松动后起针"],["弯针","针柄改变了进针时的方向角度，提插捻转与出针困难","手法不当、压迫或碰撞针体、患者体位改变","停止行针，缓慢退针；因体位改变者先恢复原体位再退针；不可强行拔出，以免断针"],["断针","针身折断，残端留于体内","针具质量不佳、针根部剥损、强力提插捻转、弯针后强行拔出、患者突然大幅度移动","保持镇定，安抚患者，勿移动体位；若残端露出皮肤可镊子夹出或用左手拇食指下压针孔周围使残端露出再夹出；深部残端须外科手术取出"],["血肿","针刺部位局部肿胀疼痛，继而皮肤青紫","刺破血管、针尖弯曲致伤、压迫不当、留针时患者体位移动","微出血者局部按压 3～5 分钟即可；青紫者可加压并按揉活血，必要时外敷或热敷；肿块增大、剧痛者须排除出血较多并就医"],["神经损伤","局部麻木、疼痛、无力，甚至肌肉萎缩","针刺深度过直、方向不当、反复刺激同一神经","立即停止针刺在该神经走行处继续操作，予营养神经与康复治疗，多数可逐渐恢复；症状持续或加重须神经科诊治"],["烫伤（艾灸）","灸处皮肤红肿、疼痛、起水疱","艾条太热、艾炷距皮肤过近、灸时未移动、艾灰或艾炷坠落","小疱可自行吸收，勿挑破；大疱应消毒后无菌抽液并敷以无菌纱布，保持清洁干燥，忌搔抓；面部及关节处尤须注意"],["感染","针孔周围红肿热痛、渗液、发热","消毒不严、针具污染、针孔被污染或患者自行触摸","局部清创消毒，必要时口服或外用抗菌药物，并须报告与处理；一经确诊应按医疗机构感染管理流程处置"]]},{"type":"heading","level":3,"text":"二、灸法"},{"type":"paragraph","text":"灸法以艾绒为主要原料。《本草纲目》谓「艾能通十二经，走三阴，调气血，暖脾胃」，故艾为灸治之要品。临床常用者有艾炷灸、艾条灸、温针灸、温灸器灸等，另有灯火灸、天灸（非艾类灸法）。灸法的功效在于温通经络、行气活血、祛寒逐冷、回阳固脱，并可与针法配合以增强温补之力。"},{"type":"table","caption":"常用灸法操作要点表","head":["灸法","器械与材料","操作要点","适应范围"],"rows":[["艾炷灸","艾绒搓成圆锥或圆柱形小炷","直接灸（化脓灸、非化脓灸）将艾炷直接置穴上点燃；间接灸（隔姜、隔蒜、隔盐、隔附子饼、隔麦麸）于穴上置垫物再放艾炷；灸 3～5 壮，小儿宜 2～3 壮","虚寒证、阳虚证、瘰疬、疣、哮喘、疮疡久不收口"],["艾条灸","艾绒制成长条（艾条、艾卷）","悬起灸（距离皮肤 2～3cm，回旋灸、雀啄灸、温和灸）与实按灸（穴位上垫布后按压）两大类；每次 10～15 分钟，以局部温热不灼为度","各类虚寒证、痛证、肌肉劳损、关节冷痛、养生保健"],["温针灸","毫针 + 艾绒或艾条","针刺得气后，将艾绒搓团紧裹针柄或置艾条于针柄上点燃，针下垫纸板隔热；每穴通常 1～2 壮，注意防止艾灰烫伤","寒湿痹痛、关节冷痛、阳虚寒证，如肩周炎、网球肘、腰腿痛"],["温灸器灸","温灸器（金属盒、塑料温灸器、灸疗罐等）","将艾绒或艾条装入器具，固定于腧穴上方或嵌入器具内灸 20～30 分钟；须防漏灰烫伤","大面积慢性病证、虚寒证、养生保健，如慢性腹泻、虚劳、畏寒"],["灯火灸","灯草蘸麻油点燃","以灯草蘸油点燃，迅速点灸穴位，局部可发出「啪」声；操作须迅速，注意烫伤防护","小儿疳积、痄腮等传统用法，现临床少用"],["天灸","斑蝥、白芥子、蒜泥等发泡药物","将发泡药敷贴于腧穴，使局部发泡以激发经气；须注意皮损范围与感染防控","哮喘、过敏性鼻炎、关节冷痛等传统敷贴疗法"]]},{"type":"callout","variant":"info","title":"刺灸法的现代拓展与临床配合","text":"现代针具发展出电针（以脉冲电流替代或加强手法刺激）、激光针、穴位埋线、穴位注射、浮针、针刀等；灸法发展出温针、隔物灸、扶阳灸、艾灸仪等。临床常针药并用，如面瘫急性期针刺配牵正散与西药激素、B 族维生素；痛证取阿是穴配中药离子导入。须强调：现代技术拓展不能背离经络腧穴理论，处方配穴与操作安全仍是根本，器械与药物的替代应用须由具备资质的医师评估实施。"},{"type":"callout","variant":"warning","title":"刺灸禁忌与安全要点","text":"凡属重要脏器所在部位，如胸腔、腹腔、脊髓、眼球、纵隔、大血管、神经干及大关节处，禁直刺或须极浅、极慎，防止刺入脏器；孕妇腰骶部、小腹部及合谷、三阴交、至阴等穴禁针；婴幼儿囟门部禁针；酒醉、饱食、疲劳、饥饿、精神过度紧张者不宜针刺。皮肤感染、溃疡、瘢痕、肿瘤处禁针；有出血倾向、正在使用抗凝药物者慎针。灸法禁忌：颜面五官、大血管处、孕妇腰骶腹部禁灸；实热证、阴虚火旺、高热、抽搐、精神狂躁者慎用灸法；糖尿病、周围感觉障碍者须防烫伤。"},{"type":"quote","text":"刺之要，气至而有效。","source":"《灵枢·九针十二原》"},{"type":"keypoints","title":"掌握要点","items":["毫针操作流程：进针—行针—留针—出针，每环节均须察反应","进针四法：指切、夹持、舒张、提捏；角度分直刺、斜刺、平刺","深度以得气为度，头面胸背宜浅，四肢躯干可深，胖瘦老幼须权衡","基本手法：提插、捻转、循、弹刮、飞、震颤；辅助手法有循摄、爪切、押手等","异常处理核心：晕针立即停针平卧；滞针勿强拔；弯针缓退；断针保持体位并外科处理","灸法有艾炷灸、艾条灸、温针灸、温灸器灸等；孕妇腰骶腹部禁灸"]}]},{"id":"clinical-selection","title":"配穴处方","subtitle":"取穴原则、经典配穴与临床处方思路","icon":"🧩","summary":"取穴有近部、远部、辨证、对症四途，处方当以经络辨证为纲、主穴为君、辅穴为臣，经典配伍如四关穴、八脉交会穴配伍。","badge":"实用","blocks":[{"type":"paragraph","text":"配穴处方是在辨证立法之后，确定腧穴配伍组合的过程，是针灸治疗的关键步骤。处方的构成一般分为主穴、辅穴、配穴：主穴针对主要病机，是处方的主体；辅穴协助主穴加强疗效；配穴针对兼症或起到特殊作用。处方必须遵循「主次分明、标本兼顾、远近配合、上下呼应」的原则，一般每次用穴 4～8 个为宜，贵在精练而不在多。"},{"type":"table","caption":"四种取穴方法对照表","head":["取穴方法","含义与理论依据","常用腧穴举例","适用情形"],"rows":[["近部取穴","在病变所在经络循行的局部及其邻近部位取穴，依据腧穴的近治作用","颈项病取风池、天柱；肩痛取肩髃、肩髎、肩贞；腰痛取肾俞、大肠俞、委中","局部疼痛、痹证、局部软组织损伤、脏器所在体表投影区病变"],["远部取穴","在病变部位以外的经脉循行线上取穴，依据经脉所过、主治所及与远治作用","头痛取合谷、太冲；目疾取合谷、光明；胃痛取足三里、内关；牙痛取合谷、内庭","脏腑病、头面五官病、急性痛证、「四总穴」及八脉交会穴等远治要穴"],["辨证取穴","依据八纲、脏腑、气血津液辨证结果选取针对性腧穴","气虚取气海、关元、足三里；血虚取血海、三阴交；阴虚取太溪、三阴交、照海；阳虚取神阙、命门、关元","慢性虚证、复杂证候、脏腑功能失调、以补益调和为主的治疗"],["对症取穴","针对某一具体症状选取有专长主治的腧穴，症状解除即去之","发热加大椎、太阳；呕吐加内关、公孙；便秘加上巨虚、天枢；失眠加神门、安眠；水肿加阴陵泉、水分","症状突出、病情较单纯、兼症较多者，须随证加减"]]},{"type":"heading","level":3,"text":"经典配穴组合"},{"type":"cards","columns":3,"items":[{"icon":"✋","title":"四关穴","text":"合谷配太冲，两手两足各一穴，共四穴，称四关穴。合谷属手阳明大肠经，太冲属足厥阴肝经，一升一降、一阴一阳，气血同调、上下相应。","bullets":["主治：头面五官疾患、半身不遂、癫痫、癫狂痫","可用于中风先兆、痛经、闭经、情志病","针刺得气后配合守气，效佳"]},{"icon":"🔗","title":"八脉交会穴配伍","text":"公孙配内关、后溪配申脉、足临泣配外关、列缺配照海，每组两穴同用，通过奇经与正经的交通而扩大主治范围。","bullets":["公孙—内关：心、胸、胃疾","后溪—申脉：目内眦、颈项、耳、肩背、腰腿","足临泣—外关：目外眦、耳后、颊、项、胁肋","列缺—照海：头项、胸部、咽喉、肺系"]},{"icon":"🎯","title":"俞募配穴","text":"背俞穴与募穴相配，背俞穴在腰背属阳，募穴在胸腹属阴，阴阳相配、脏腑同调，是脏腑病最常用的经典配伍。","bullets":["肺病：肺俞配中府","胃病：胃俞配中脘","肝胆病：肝俞配期门、胆俞配日月","肾与膀胱：肾俞配京门、膀胱俞配中极"]},{"icon":"🌀","title":"原络配穴（主客配穴）","text":"本经原穴为主，表里经络穴为客，主客相配以疏调表里两经气血，适用于表里同病或主病在经、客病在络者。","bullets":["肺经为病：太渊配偏历","大肠为病：合谷配列缺","胃为病：冲阳配公孙","心为病：神门配通里","肝为病：太冲配蠡沟"]},{"icon":"🦴","title":"八会穴配伍","text":"以八会穴针对相应功能失调的病证，如筋病取筋会阳陵泉，血病取血会膈俞，脉病取脉会太渊，腑病取腑会中脘。","bullets":["气病：气会膻中","血病：血会膈俞","筋病：筋会阳陵泉","骨病：骨会大杼","髓病：髓会绝骨"]},{"icon":"🌉","title":"上下配穴与同名经配穴","text":"上病下取、下病上取，如头痛取太冲、头晕取百会；同名阳经上下相配，如合谷配足临泣、阳陵泉配外关，以疏调同名经气血、恢复经气平衡。","bullets":["上病下取：面痛取合谷、巅顶痛取太冲","下病上取：足踝痛取陷谷、脱肛取百会","同名经配：合谷—足临泣通阳维","表里经配：肺经—大肠经"]}]},{"type":"paragraph","text":"临床处方的思路可概括为三步：第一步依据病位定经，选出本经腧穴；第二步依据病性配穴，寒者加灸，热者加泄，虚者用补法与背俞、募穴，实者用泻法与郄穴、络穴；第三步依据主要症状加用对症专穴。全过程以经络辨证为主线，脏腑辨证为参照，即所谓「脏腑经络并重」。处方加减亦须动态：邪实宜重泻取效，中病即止；正虚宜轻补缓图，培补先天与后天。"},{"type":"table","caption":"常用局部与远部配穴组合举例","head":["病证","主穴","配穴","操作要点"],"rows":[["头风头痛","百会、风池、太阳、合谷","肝阳上亢加太冲、太溪；血虚加三阴交、足三里","风池向鼻尖方向斜刺 0.8～1.2 寸，太冲用泻法，余用平补平泻"],["面瘫（面神经炎）","攒竹、鱼腰、阳白、四白、颧髎、颊车、地仓、合谷","风寒加风池、列缺；恢复期加足三里、阳陵泉","急性期浅刺、久留针，不宜强刺激；注意面部表情肌保护"],["不寐","神门、内关、百会、安眠","肝火加行间、侠溪；心脾两虚加脾俞、足三里；痰热加丰隆、阴陵泉","睡前 1 小时施针，留针 20～30 分钟，灸百安眠可增效"],["胃脘痛","中脘、足三里、内关、公孙","寒邪加胃俞、脾俞；肝气加太冲、阳陵泉；食积加内庭；虚寒加神阙、气海","中脘可灸；急性剧痛者先取内关、公孙、郄穴"],["痹证（风湿痹痛）","阿是穴、局部经穴（肩髃、曲池、环跳、阳陵泉）","行痹加膈俞、血海；痛痹加肾俞、命门；着痹加阴陵泉、丰隆","寒痹可配灸法；病程久者加刺络放血"],["眩晕","百会、风池、太冲","肝阳加太溪、侠溪；气血亏虚加足三里、气海；痰湿加丰隆、阴陵泉","风池深刺可引风阳下行；虚证宜灸百会、气海"],["便秘","天枢、支沟、大肠俞、上巨虚","热秘加合谷、内庭；气秘加太冲；气虚加足三里、脾俞；冷秘加神阙、关元","腹部腧穴宜平刺或斜刺；老年虚秘可用温灸"]]},{"type":"callout","variant":"info","title":"处方加减与疗效判断","text":"常用加减思路：发热加大椎、曲池；咳嗽加肺俞、尺泽；呕吐加内关、公孙、足三里；腹泻加天枢、上巨虚；便秘加支沟、天枢；失眠加神门、安眠；尿频加肾俞、膀胱俞；痛经加三阴交、关元、气海；崩漏加隐白、血海。疗效判断应结合症状、体征与功能指标，一般以「症状缓解、功能改善、复诊时病程缩短」为标准，不可仅凭一次针后感觉下定论。"},{"type":"quote","text":"气之至也，如鱼吞钩饵之沉浮；气未至也，如闲处幽堂之深邃。","source":"《标幽赋》"},{"type":"keypoints","title":"掌握要点","items":["四种取穴：近部（局部）、远部（循经）、辨证（八纲脏腑）、对症（专长）","处方结构：主穴针对病机，辅穴助主穴，配穴顾兼症","经典配伍：四关穴、俞募配穴、原络配穴、八会穴、八脉交会穴配对、上下配穴","取穴宜精练，一般 4～8 穴，动态加减","先辨经络之病位，再辨脏腑之虚实，最后加对症之专穴"]}]},{"id":"common-diseases","title":"针灸常见病主治","subtitle":"常见病证主穴、配穴与操作要点","icon":"📋","summary":"汇集感冒、头痛、失眠、胃痛、腹泻、腰痛、痹证、面瘫等常见病证的针灸主穴、配穴与操作要点，供临床参考。","badge":"临床","blocks":[{"type":"paragraph","text":"针灸的临床应用以「经络辨证与脏腑辨证相结合」为核心。下表所列主穴与配穴，依据现行针灸学教材的常规处方整理，配合各病证的操作要点，供学习参考。需强调：疾病诊断与证型判定必须由医师完成，处方须随证加减；凡急性危重症、进行性病变、原因不明者，应先行现代医学检查与专科处理，针灸只作辅助或协同治疗。"},{"type":"heading","level":3,"text":"一、处方通则"},{"type":"list","ordered":false,"items":["主穴宜少而精，每方 4～8 穴，先取本经与病所局部腧穴，再按证加减","急性病多每日 1～2 次、以泻法为主，取效即止；慢性病隔日或每周 2～3 次、补法与灸法并用","疗程一般 10～15 次为一疗程，疗程之间休息 3～5 日，疗程结束须重新辨证立方","虚实夹杂者多平补平泻或先泻后补；寒证加灸，热证可点刺放血","全程记录疗效与不良反应，必要时调整处方或转诊"]},{"type":"table","caption":"常见病针灸主治处方表","head":["病名","主穴","配穴","操作要点"],"rows":[["感冒","列缺、合谷、大椎、太阳、风池","风寒加肺俞、风门；风热加大椎、曲池；暑湿加阴陵泉、足三里；体虚加足三里、气海","风寒宜用灸法，风热宜用泻法；大椎可点刺放血；每日 1～2 次，留针 20～30 分钟"],["头痛","百会、太阳、风池、合谷、率谷、头维","肝阳上亢加太冲、太溪；血虚加三阴交、足三里；痰浊加丰隆、阴陵泉；瘀血加血海、膈俞","百会可灸；风池向鼻尖方向斜刺 0.8～1.2 寸；急性剧烈头痛先查病因"],["失眠","神门、内关、百会、安眠、照海、申脉","肝火扰心加行间、侠溪；痰热扰心加丰隆、阴陵泉；心脾两虚加脾俞、足三里；心肾不交加太溪、心俞","睡前 1 小时施针，留针 20～30 分钟；虚证可灸百安眠、安眠穴；调摄情志与作息为要"],["胃痛","中脘、足三里、内关、公孙、脾俞、胃俞","寒邪加胃俞、命门；肝气犯胃加太冲、阳陵泉；食滞加内庭、梁门；瘀血加膈俞、血海；胃阴亏虚加太溪、三阴交","急性胃痛先排除急腹症；虚寒证中脘、气海宜灸；每日 1 次，10 次为一疗程"],["腹泻","天枢、上巨虚、阴陵泉、大肠俞、足三里","寒湿加神阙、关元；湿热加内庭、曲池；脾虚加脾俞、章门；五更泻加肾俞、命门","急性腹泻宜灸神阙；慢性泄泻以补法并灸；注意补液与电解质，危重者须就医"],["便秘","天枢、支沟、大肠俞、上巨虚、阳陵泉","热秘加合谷、内庭；气秘加太冲、支沟；气虚加足三里、脾俞；冷秘加神阙、关元","腹部穴宜平刺或斜刺；老年虚秘可温灸神阙；须配合饮食与排便习惯训练"],["腰痛","肾俞、大肠俞、委中、阿是穴、命门","寒湿加腰阳关、命门；瘀血加膈俞、次髎；肾虚加太溪、志室；督脉病加后溪、悬钟","委中可点刺放血；腰部宜平直刺 0.8～1.5 寸；急性腰痛排除椎间盘突出、骨折等"],["痹证（风湿痹痛）","阿是穴、局部经穴（肩髃、曲池、外关、环跳、阳陵泉、悬钟）","行痹加膈俞、血海；痛痹加肾俞、命门、关元；着痹加阴陵泉、丰隆；热痹加曲池、大椎","寒湿痹痛可加灸法；病久者酌用刺络放血；注意关节保暖，避免诱发因素"],["面瘫（面神经炎）","攒竹、鱼腰、阳白、四白、颧髎、颊车、地仓、合谷、翳风","风寒加风池、列缺；肝阳上亢加太冲；久病加足三里、阳陵泉；伴耳痛加听宫、听会","急性期浅刺、不宜强刺激，配合面部按摩与被动训练；恢复期可适当加强刺激；注意护眼、避免面部受凉"],["咳嗽","肺俞、中府、列缺、太渊、尺泽","外感加合谷、风门；痰湿加丰隆、阴陵泉；燥邪加太溪、三阴交；肺阴虚加膏肓、照海","咳嗽急性期可加拔罐；久咳者可灸膏肓；须注意排除肺部器质性病变"],["哮喘","定喘、膻中、天突、孔最、尺泽、足三里","寒哮加风门、肺俞；热哮加鱼际、曲池；虚哮加肺俞、肾俞、膏肓；发作期加定喘、璇玑","发作期以平喘为先，缓解期补肺脾肾；天突先直刺 0.2 寸再沿胸骨柄后缘向下平刺；禁深刺"],["高血压病","曲池、太冲、足三里、涌泉、百会、风池","肝阳上亢加行间、侠溪；阴虚阳亢加太溪、照海；气虚加气海、脾俞；痰湿加丰隆、阴陵泉","百会、风池可灸；每日 1 次，10～15 次一疗程；须配合低盐饮食、监测血压，不可自行停用降压药"],["眩晕","百会、风池、太冲、颈夹脊","肝阳上亢加太溪、侠溪；气血亏虚加足三里、气海；痰湿中阻加丰隆、阴陵泉；肾精不足加肾俞、太溪","风池深刺 1～1.5 寸可引风阳下行；虚证宜灸百会、气海；发作时卧床、避免强光刺激"],["脱发","百会、风池、膈俞、肝俞、肾俞、足三里","血虚加三阴交、血海；肝郁加太冲、章门；湿热加阴陵泉、丰隆","平补平泻，留针 20～30 分钟；可配合梅花针叩刺头部与中药外洗"],["肥胖","中脘、丰隆、阴陵泉、足三里、天枢、脾俞","胃热加内庭；肝郁加太冲；脾虚加气海；便秘加上巨虚","以泻法为主，丰隆、阴陵泉为要穴；须配合饮食控制与运动，单纯针刺疗效有限，须长期坚持"],["月经不调","关元、气海、三阴交、血海、地机","月经先期加太冲、行间；后期加肾俞、足三里；经量多加隐白、脾俞；痛经加阿是穴、次髎、十七椎","经前 3～5 日开始治疗，痛经者可在经前加灸关元、气海；须排除器质性病变"],["痛经","三阴交、中极、次髎、关元、地机","寒凝加艾灸关元、气海；气滞加太冲、膈俞；血瘀加血海、次髎；实证可用泻法","经前一周开始治疗，连治 3 个月经周期；经期注意保暖、忌生冷；继发性痛经须妇科评估"],["遗尿","关元、中极、膀胱俞、三阴交、阴陵泉","肾气不足加肾俞、太溪；肝经郁热加行间、内庭；下元虚寒加命门、灸关元","睡前 2 小时施针并留针，另配合膀胱功能训练；小儿须家长配合排尿训练"],["耳鸣耳聋","听宫、听会、翳风、侠溪、足临泣、太冲","肝胆火盛加太冲、丘墟；肾虚加太溪、肾俞；痰火加丰隆、劳宫","耳周穴平刺 0.3～0.5 寸；配合鼓膜按摩与音频刺激；突发性耳聋须 48 小时内积极治疗"],["牙痛","合谷、颊车、下关、内庭、二间","风火牙痛加外关、风池；胃火牙痛加内庭、厉兑；虚火牙痛加太溪、行间","合谷向第二掌骨方向斜刺；上牙痛取下关、内庭，下牙痛取颊车、二间；须同时治疗牙病本身"]]},{"type":"paragraph","text":"临床应用时还需注意三个层面。其一，疗程与时机：急性病多每日 1～2 次、以泻法为主，1～3 日可见效；慢性病宜隔日 1 次或每周 2～3 次、以补法为主，10～15 次为一疗程，疗程之间宜休息 3～5 日。其二，手法的虚实与时相：多补少泻或平补平泻适用于虚实夹杂、慢性病；泻法适用于实邪炽盛之急性痛证；虚证、久病宜灸法与补法，灸量宜先少后多。其三，医患配合：针刺的疗效与患者的情志、饮食、劳逸、体质密切相关，情志病尤其需要配合心理疏导与生活方式调整。"},{"type":"cards","columns":3,"items":[{"icon":"⏱️","title":"急性病","text":"以祛邪为主，取穴精少、针感强，多用泻法，每日 1～2 次。","bullets":["如急性扭伤、落枕、急性腹泻","可配合放血、拔罐","中病即止"]},{"icon":"🕰️","title":"慢性病","text":"以扶正为主，取穴稍多，补法或平补平泻，灸法并用，疗程较长。","bullets":["如慢性胃痛、失眠、痹证","酌加背俞、募穴","10～15 次一疗程"]},{"icon":"🩺","title":"疑难病","text":"重视整体与标本，讲究配伍层次，配合中药与功能康复。","bullets":["如中风后遗症、顽固性头痛","多法合用","定期评估并调整方案"]}]},{"type":"callout","variant":"info","title":"现代研究提示","text":"现代研究认为，针刺可能通过调节自主神经功能、影响中枢神经递质与脑网络、改善局部微循环与炎症反应、调控免疫等多种途径起效；这些认识可作为理解针刺效应的参考，但并不能替代经络辨证这一临床处方原则。临床仍须以辨证取穴、补泻手法与得气为核心，并把患者整体状况与疾病规律纳入考量。"},{"type":"quote","text":"若要安，先三里；常要三里不瘢，急按三里合谷。","source":"《卫生宝鉴》（针灸歌赋）"},{"type":"keypoints","title":"掌握要点","items":["处方三步：辨经络病位 → 辨脏腑虚实 → 加对症专穴","急性病取穴精少、每日 1～2 次、泻法为主；慢性病补法为主、可加灸","常用疗程 10～15 次，疗程间休息 3～5 日","针刺只能协同治疗，器质性病变与急危重症须先做现代医学处理","疾病诊断与证型判定必须由医师完成，不可自行针刺"]}]},{"id":"precautions","title":"针灸禁忌与注意事项","subtitle":"禁针宜忌、晕针防范、深度安全与感染防控","icon":"⚠️","summary":"针灸安全须守部位之禁、体质之禁、时机之禁与操作之规，兼防晕针、烫伤与感染，灸法与针法各有禁忌。","badge":"安全","blocks":[{"type":"paragraph","text":"针灸虽属外治之术，但因需刺入皮肤、破坏组织并施加物理与化学刺激，仍属有创或有热的医疗行为，必须遵循无菌操作与安全规范。安全性贯穿三个环节：诊察阶段须明辨禁忌，避开重要脏器、血管、神经与特殊生理状态；操作阶段须掌握深度、方向与手法，避免刺伤脏器、折针、烫伤与感染；善后阶段须观察反应、及时处理异常，并向患者交代注意事项。"},{"type":"heading","level":3,"text":"一、禁针与慎针"},{"type":"table","caption":"禁针穴与慎针部位一览","head":["类别","具体部位与腧穴","原因","替代方案"],"rows":[["孕妇禁针穴","合谷、三阴交、至阴、昆仑、上下巨俞、关元、气海、命门、阴陵泉等；腰骶部、小腹部腧穴","通经活络、兴奋子宫平滑肌，可能致胎动或流产","若确需治疗须由专科医师评估，取穴宜少、宜浅、禁强刺激，妊娠 3 个月内慎用"],["四肢末端禁刺","指（趾）端、掌心、跖心等处","末端神经血管丰富、易生剧痛与感染，末梢循环差者更易坏死","取相应井穴时用三棱针点刺挤血，且须严格消毒、深度极浅"],["颜面五官慎针","睛明、承泣、球后、瞳子髎、风池、翳明等；眼眶周围、眼球、扁桃体部","邻近眼球、视神经、动脉，易致出血、感染或损伤；风池深刺可伤及椎动脉、枕神经","风池针 0.8～1.2 寸，针尖向鼻尖方向并严格掌握深度；面部宜浅刺平刺"],["胸腹腰背慎针","膻中、鸠尾、巨阙、期门、章门、天枢、气海、关元；背俞穴、督脉腧穴、脊中、脾俞附近","胸腔、腹腔、纵隔、心肺、肝脾、脊管所在，刺深可致气胸、内脏损伤、脊髓损伤","背俞穴平刺或斜刺 0.5～0.8 寸，向内斜入；胸腹部腧穴多平刺，深度不超过 0.5～0.8 寸"],["大血管与神经干处慎针","动脉搏动明显处、神经干走行处（臂丛、腓总神经、坐骨神经等）","刺伤血管可致大出血，刺伤神经可致麻木、瘫痪","避开血管神经，必要时沿神经走行方向平刺，并配合影像与解剖定位"],["特殊状态禁针","高热、惊厥、精神狂躁、酒醉、饱食、疲劳、饥饿、大汗、大泻后体虚；空腹","易诱发晕针、滞针或加重病情","待病情平稳、体力恢复、进食适量后再行针刺"],["局部病变禁针","皮肤感染、化脓、溃疡、瘢痕、肿瘤、皮肤感觉障碍处","感染扩散、愈合不良、感觉障碍者易致不可察觉的烫伤与损伤","改选邻近正常部位腧穴，或先处理局部病变"]]},{"type":"heading","level":3,"text":"二、晕针的预防与处理"},{"type":"list","ordered":true,"items":["首次针刺者应充分解释针感与可能反应，消除恐惧心理，取得信任与配合","初诊、体弱、精神紧张者宜取卧位，避免坐位针刺；体位以舒适、放松、能持久为度","诊室内保持空气流通、温度适宜，避免闷热、嘈杂与强光刺激","不宜空腹、过饱、疲劳、大汗、大泻、饮酒后施针；餐前餐后宜间隔适当时间","首次施针宜少穴、轻刺激、短留针，不宜首次即用强刺激或久留针","施针过程中应全程观察面色、神志、呼吸与出针情况，医师不得离开诊室","出现头晕、眼花、心慌、恶心、出冷汗时立即停针，取平卧或头低足高位，饮温开水或糖水，静卧休息多可恢复"]},{"type":"heading","level":3,"text":"三、针刺深度与手法安全"},{"type":"paragraph","text":"针刺深度的总原则是「以得气为度，以安全为要」，并遵循「刺中脏腑者，慎针之」的告诫。实际操作中须结合腧穴所在解剖层次、局部肌肉厚度、体型胖瘦、年龄老幼、疾病性质与个体反应综合判断：一般四肢躯干部肌肉丰厚处可直刺 0.5～1.5 寸；头面、颈项、胸腹、腰背宜浅刺 0.3～1 寸，多采用斜刺或平刺；手足末端宜极浅。补泻手法宜轻巧柔和，勿施暴力捻转；孕妇、老弱者、儿童及初次针刺者，手法强度应相应减弱。此外，针刺与艾灸操作中，医师应始终体现「手如持钩、气如营卫」的规范与专注，避免在患者体位移动、情绪不稳时行针。"},{"type":"heading","level":3,"text":"四、灸法禁忌"},{"type":"list","ordered":false,"items":["颜面五官、大血管处、孕妇腰骶部与腹部禁灸；热病、阴虚火旺、实热证、高热、抽搐、狂躁者慎用","糖尿病、周围神经病变、感觉障碍、循环障碍者易致烫伤，须严格控制温度与时间并全程看护","灸疮未愈、皮肤感染、溃疡处不宜施灸；出血倾向、严重心血管疾病患者慎用","艾炷大小与壮数宜循序渐进，先少后多；直接化脓灸须在专业医疗机构由有资质人员操作"]},{"type":"heading","level":3,"text":"五、感染防控"},{"type":"paragraph","text":"针刺属有创操作，感染防控是最基本的要求。应做到：一人一针一用一废弃，一次性无菌针具，使用前逐支检查针体有无锈蚀、弯折与钩毛，针刺前用 75% 酒精或碘伏消毒针刺部位皮肤，待干后进针；针刺过程中避免手指接触针体与针尖；起针后以无菌干棉球按压针孔止血，观察有无出血与血肿；针具不得与他人混用，不得带回家庭自行使用。施针人员应按规定接种疫苗、进行手卫生，工作环境应做到针具、棉球、消毒用品的规范处置与医疗废物分类收集与无害化处理。若出现针孔红肿热痛、渗液、发热等感染征象，须及时处置并按医疗机构感染管理流程报告处理。"},{"type":"callout","variant":"warning","title":"必须立即就医的情形","text":"凡遇下列情况应停止自行处理并立即就医：针刺后出现剧烈头痛、喷射性呕吐、意识障碍、瞳孔变化、肢体无力（警惕颅内出血与气胸）；胸痛、呼吸困难、突发心悸（警惕气胸与心律失常）；剧烈腹痛、腹部拒按（警惕脏器损伤）；断针残端滞留体内；局部剧痛伴皮肤苍白发凉（提示血管损伤或骨筋膜室综合征）；针孔红肿化脓伴发热（感染）；烫伤面积较大或水疱破溃。"},{"type":"callout","variant":"info","title":"患者自我管理建议","text":"针刺后宜休息 10～20 分钟，观察有无异常再离院；针孔局部保持清洁干燥，24 小时内避免沾水与用力搓揉，当日避免针刺部位沾水与洗澡盆浴，避免针刺部位受凉、淋雨与剧烈运动；刺后 2 小时内不宜饮酒、饱餐、过劳与热水泡澡，饮食宜清淡，避免辛辣刺激；针灸期间按时服药，不擅自停用原有西药；保持规律作息与情绪稳定，适当运动与锻炼。"},{"type":"quote","text":"刺虚则实之，刺实则虚之。","source":"《灵枢·官能》"},{"type":"keypoints","title":"掌握要点","items":["禁针：孕妇腰骶腹部与合谷三阴交等、四肢末端、重要脏器与大血管处","慎针：颜面五官、眼眶周围、胸腹腰背督脉腧穴、神经干走行处","晕针预防：解释沟通、卧位、空气流通、不空腹过饱、首次轻刺激、全程观察","深度原则：以得气为度、宁浅勿深，头面胸背宜浅，手法轻柔","灸法禁忌：孕妇腰骶腹部禁灸，阴虚火旺与糖尿病感觉障碍者慎用","感染防控：一人一针一废弃、无菌操作、针孔按压、废物规范处置"]}]}]}},"diet":{"page":{"key":"diet","title":"养生食疗","subtitle":"药膳方 · 体质食养 · 季节食养","description":"按药膳方、体质食养与季节食养分类整理的中医食疗方剂，每方含食材组成、用量、功效解析、制作方法与禁忌人群，全部内容依据《食疗本草》《饮膳正要》《黄帝内经》等经典文献整理，供日常膳食调理参考。","lead":"食疗是中医养生中最为平缓的一环。《饮膳正要》开篇即言「食饮有节，起居有常，不妄作劳，故能而寿」，强调调养当从日常饮食与作息入手。本页收录三十六道食疗方，分属药膳方、体质食养与季节食养三类：药膳方重在补虚纠偏，体质食养依九种体质辨证施膳，季节食养则顺应二十四节气与四时之气调摄。每方均标出食材用量、功效解析与禁忌人群，并注明药材是否列入国家食药物质目录。凡属疾病诊治者，仍须辨证由医师完成，食疗不能替代药物治疗。","type":"collection","icon":"fa fa-mortar-pestle","items":[{"id":"shiquan-dabutang","title":"十全大补汤","subtitle":"温补气血，健脾益肾","category":"药膳方","tags":["气血双补","八珍汤化裁","虚劳调养","冬令进补"],"meta":[{"label":"适用人群","value":"气血两虚、面色㿠白或萎黄、神疲乏力、少气懒言、食少便溏、畏寒肢冷者；产后、术后、病后恢复期气血亏虚者尤宜。四季皆可，冬令与立冬、小雪时节食用最佳。"},{"label":"主要功效","value":"益气健脾、养血补肝、温阳益肾，气血双补、扶正培元。用于气短懒言、面色无华、头晕心悸、失眠健忘等虚劳诸症。"},{"label":"食材组成","value":"党参 10 g，黄芪 15 g，白术 10 g，茯苓 12 g，炙甘草 6 g，熟地黄 12 g，当归 10 g，白芍 10 g，川芎 6 g，桂圆肉 8 枚，瘦猪肉 250 g，生姜 3 片，盐少许"},{"label":"制作方法","value":"药材清水快速冲洗后冷水浸泡 30 分钟；黄芪、党参、白术、茯苓、炙甘草用纱布包扎，与瘦肉、姜片同入砂锅，一次加足水约 1500 mL，大火煮沸后撇去浮沫，转小火慢炖 90 分钟，至肉酥汤浓，取出药包，加盐调味，饮汤食肉。"},{"label":"食用注意","value":"人参、白术、熟地黄、白芍、川芎均不在国家《既是食品又是药品的物品名单》之内，当归仅获准作香辛料与调味品使用，作食疗用药须经中医师辨证指导，具体剂量须遵医嘱；甘草反甘遂、大戟、海藻、芫花，人参反藜芦，不可与之同用；服药期间不宜与萝卜同食。"}],"image":"","imageHint":"十全","summary":"十全大补汤由八珍汤加黄芪、肉桂衍化而来，是气血双补的经典药膳。全方以四君子、四物为底，配黄芪补气升阳、桂圆肉养血安神，脾旺则生化有源，肝肾并调则气血自充。汤剂药力平和而持久，适合长期体虚、劳倦伤神者作日常调养之膳；冬令阳气内藏，饮此汤最合时宜。然全方温补之中亦有川芎、当归之活血，湿热壅盛、阴虚火旺者不宜，服用期间亦当忌食萝卜与寒凉之物。","blocks":[{"type":"table","caption":"十全大补汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["党参","10 g","补中益气、健脾养血，代替人参力缓而持久"],["黄芪","15 g","补气升阳、固表止汗，兼利水消肿"],["白术","10 g","健脾益气、燥湿利水，为后天之本"],["茯苓","12 g","利水渗湿、健脾宁心，性平不燥"],["炙甘草","6 g","补脾益气、调和诸药"],["熟地黄","12 g","养血滋阴、补精益髓"],["当归","10 g","补血活血、调经止痛，兼润肠"],["白芍","10 g","养血敛阴、柔肝止痛"],["川芎","6 g","活血行气、祛风止痛，使补而不滞"],["桂圆肉","8 枚","补益心脾、养血安神"],["瘦猪肉","250 g","补中益气、润燥，提供高蛋白与铁"],["生姜","3 片","温中止呕、调和表里，制熟地之滞腻"]]},{"type":"paragraph","text":"制作要点在「浸泡、装包、火候」三处。药材先用冷水浸泡约半小时，令有效成分充分溶出；党参、黄芪、白术等味厚者以纱布包扎，可使汤液澄清不致过苦。加水务必一次足量，中途不再添冷水，方能保持滋补浓度。开锅后转小火，保持微沸不急滚，汤面只冒虾眼泡而不翻大浪，炖足九十分钟，肉块酥而不烂、汤色棕红微稠为度。若用瓦罐隔水汽炖，火势更缓，补力更和平；若用蒸锅上汽蒸制，适宜久病胃弱者，可免油腻之弊。出锅前撒少许盐即可，切忌再加味精、浓茶与烈酒同食。"},{"type":"paragraph","text":"方义上，白术、茯苓、炙甘草、党参四味为四君子汤，健脾益气以资生化之源；熟地黄、当归、白芍、川芎四味为四物汤，滋养营血而调肝；黄芪增益卫气而固表，桂圆肉补心脾而安神。脾为后天之本、气血生化之源，肾为先天之本、主藏精，脾肾同调则气血生化有源而不竭，故名「十全」——十味俱备，气血双补。血肉有情之品与药食同源之味相合，使补力留而不行滞。惟全方偏于温养，运行之力略弱，故配川芎行气以防壅滞，又以生姜一味醒脾和中，兼顾脾虚便溏者可能的不适。"},{"type":"paragraph","text":"食用时机宜在早餐或午餐时温热服食，每次一碗（约 200 mL 汤与两三块肉），每周二至三次即可，不宜每日连续久服；体虚较重者可先连服十日为一疗程，症状改善后改为每周两次以巩固。汤中药物味厚，若初次食用觉口苦，可加大生姜用量或添数片瘦肉同炖以增鲜。服用期间宜少食生冷油腻与萝卜，忌浓茶、烈酒；餐后宜缓行散步二十分钟以助运化，忌即刻躺卧。若服后出现口干、苔黄、便干等燥热之象，应停服并请医师复核证型。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"孕妇禁用：方中当归、川芎有活血走窜之力，熟地黄滋腻碍胎，非所宜；备孕及哺乳期妇女须经医师评估。阴虚火旺者忌服，症见口干咽燥、五心烦热、潮热盗汗、舌红少苔者，温补如火上浇油。感冒发热、外感未解、疮疡初起或皮肤过敏时暂停服用，恐闭门留寇。脾胃虚弱、纳呆便溏者宜减量三分之一，或先服健脾方后再进。高血压、糖尿病、肿瘤放化疗期间若正服西药，须告知医师，避免与利尿剂、抗凝药叠加。凡对党参、黄芪、蜂蜜等过敏者禁食。配伍禁忌：甘草反甘遂、大戟、海藻、芫花，人参反藜芦，服药期间不得同用；本方不可与萝卜同食，恐解药性。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["气血两虚是使用前提，纯实热或纯阴虚者均不适用","党参替人参更平和，适合久服；人参须医师辨证定量","一次加足水、小火慢炖九十分钟，忌中途添冷水","汤药同食，每周二至三次，服后缓行助运化","食疗调养需数月之功，不能替代药物治疗"]},{"type":"quote","text":"五穀为食，五果为助，五肉为益，五菜为充，氣味合和而食之，則補精益氣。","source":"《饮膳正要·卷二·五味偏走》"}]},{"id":"siwu-jitang","title":"四物鸡汤","subtitle":"养血调经，温和不燥","category":"药膳方","tags":["养血","补虚","四物汤","药膳"],"meta":[{"label":"适用人群","value":"血虚见面色萎黄或苍白、唇甲色淡、头晕目眩、心悸失眠、肢体麻木、月经量少色淡、经期延后者；久病、失血、产后血亏者尤宜。平素体质偏寒、畏寒肢冷者更合。"},{"label":"主要功效","value":"补血养肝、益气和中，调经止痛。用于营血亏虚、冲任不足之面色无华、头晕心悸、月经不调。"},{"label":"食材组成","value":"当归 10 g，川芎 6 g，白芍 12 g，熟地黄 12 g，鸡肉 300 g（宜乌骨鸡或三黄鸡），生姜 3 片，红枣 5 枚，盐少许"},{"label":"制作方法","value":"四物药材洗净冷水浸 30 分钟，装入纱布袋；鸡肉切块焯水去血沫，与药包、姜片、红枣同入砂锅，加水约 1400 mL，大火煮沸转小火炖 70 分钟，取出药包，加盐调味，饮汤食肉。"},{"label":"食用注意","value":"熟地黄、白芍、当归、川芎均非国家《既是食品又是药品的物品名单》内物品，当归仅获准作香辛料与调味品使用，作食疗用药须经中医师辨证指导；感冒发热期停服；月经过多、崩漏者不宜，恐活血动血。"}],"image":"","imageHint":"四物","summary":"四物鸡汤是四物汤与鸡肉同煮的经典药膳。四物汤出自《太平惠民和剂局方》，为补血调经之基础方：当归补血和血，川芎活血行气，白芍养血敛阴，熟地黄滋阴养血，四药合用，补而不滞、行而不燥。伍以鸡肉，温中益气、补精填髓，使行血之品得气药之护、滋腻之品得血肉之助。全方药性平和，最适合气血不足而偏寒的女性及久病体虚者长日常服。惟熟地黄滋腻碍胃，脾虚便溏者当减量或加陈皮、生姜同煮；月经过多者不宜久服。","blocks":[{"type":"table","caption":"四物鸡汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["当归","10 g","补血活血、调经止痛，为补血要药"],["川芎","6 g","活血行气、祛风止痛，使血中有行"],["白芍","12 g","养血敛阴、柔肝止痛，制川芎之辛"],["熟地黄","12 g","滋阴养血、补精益髓，为滋补之要品"],["鸡肉","300 g","温中益气、补精填髓，兼含血红素"],["生姜","3 片","温中醒脾，制熟地之滞"],["红枣","5 枚","补中益气、养血安神"]]},{"type":"paragraph","text":"四物鸡汤的关键在于「先焯后炖、先包后煮」。鸡肉应先冷水下锅，水沸后撇净血沫，捞出用温水冲洗，这一步去除了腥味与血水中的杂质，汤色才清而不浊。四物四味装入纱布袋，可免药渣入口，取汁去渣而药力不散。加水一次到位，约淹没鸡肉一寸，先用大火煮沸，改用小火慢炖七十分钟，务使鸡皮酥软、骨肉可离。炖好取出药包，加盐调味即可，切勿先放盐再炖，盐早放会使鸡肉纤维收紧、汤味不厚。亦可用瓦罐隔水炖二小时，适合没有明火与看护时间的上班族。"},{"type":"paragraph","text":"四物汤的配伍严谨而富于层次：当归甘温，走血分而补血，为君；熟地黄甘寒，滋肾水而养血，为臣；白芍酸苦微寒，敛阴和营，川芎辛温，活血行气，二者为佐，一敛一散，使补血而不滞血、行血而不伤血；四味合用，补中有行、行中有敛，故为妇科调经的基础方。加入鸡肉之后，药膳的思路由「治病」转向「调养」：鸡肉甘温，入脾胃肾经，能温中益气、补精填髓，与血肉有情之品同煮，可助四物滋腻之品化为无形；姜枣为使，一温一补，醒脾和中，调和诸药。对于血虚而兼气虚者，一味药汤常力有不逮，加鸡同煮正是取其气药以护血药之意。"},{"type":"paragraph","text":"食用建议：每周二至三次，午餐或晚餐时连汤带肉食用，汤约 150 mL、肉三四块为宜；连续服用一个月为一疗程，经期前后各服一周为佳。若仅作日常保健，每月服用两三次即可，不必每日不断。食用时间宜在饭后一小时左右温服，避免空腹饮用浓汤以防胃部不适。服药期间宜多饮温水，饮食以温软易消化为主，忌生冷寒凉、浓茶与烈酒。若出现口干、便干、苔黄等燥象，可减熟地黄用量并加麦冬少许（须医师指导）。汤中药物味厚，鸡肉之鲜足以掩药气，一般人群均可接受。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"孕妇慎用：熟地黄滋腻、当归川芎活血，妊娠期非医师指导不可服用。阴虚火旺、潮热盗汗、口干咽燥者不宜，因熟地黄、当归偏温润，恐助热。感冒发热、外感未解期间停服，恐留邪。月经量多、崩漏淋漓者不宜，川芎、当归有行血之动，易加重出血；孕期、产后恶露未净者亦忌。脾虚便溏、纳呆腹胀者宜减熟地黄至 6 g 并加陈皮 6 g、生姜三片同煮，或先服健脾之品。荨麻疹、湿疹等过敏体质者若对禽类或当归过敏，禁食。服药期间忌与萝卜同食，勿用浓茶送服。本方所含熟地黄、白芍、当归、川芎不在国家食药物质目录内，用量与疗程须遵医嘱。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["四物为君臣佐使之配，补血而不滞是关键","鸡肉焯水去沫、药材装包，汤清而力存","先大火烧开转小火慢炖七十分钟，一次加足水","每周二至三次，经期前后各服一周为宜","月经过多、脾虚便溏者须减量调整并请医师把关"]},{"type":"quote","text":"大棗 味甘、無毒。主心腹邪氣，安中養脾，助經脉，生津液。","source":"《饮膳正要·卷三·果品》"}]},{"id":"danggui-jiangyang-mutton-tang","title":"当归生姜羊肉汤","subtitle":"温中补虚，散寒止痛","category":"药膳方","tags":["温阳散寒","补虚","仲景名方","冬季进补"],"meta":[{"label":"适用人群","value":"阳虚畏寒、肢体冷痛、脘腹冷痛、喜温喜按、面色㿠白、虚劳羸瘦者；冬季易冷、妇女产后或流产后畏寒腹痛者尤宜。实热、阴虚内热者忌服。"},{"label":"主要功效","value":"温中补虚、祛寒止痛。用于血虚有寒之腹中冷痛、痛经、产后腹痛、四肢厥冷。"},{"label":"食材组成","value":"当归 15 g，生姜 25 g，羊肉 500 g（带骨更佳），黄芪 10 g（可加），料酒适量，盐少许"},{"label":"制作方法","value":"羊肉切块冷水浸泡出血水后焯水；当归、生姜（拍碎）另包；与羊肉同入砂锅，加水没过食材约 1500 mL，大火煮沸后加料酒，转小火慢炖 90 分钟，取出药包，加盐调味。"},{"label":"食用注意","value":"当归仅获准作香辛料与调味品使用，作食疗用药须经中医师辨证指导；羊肉忌与韭菜、荞麦同食，忌与鱼膾、酪同食；本方温热，阴虚火旺者及 summer 湿热重者禁用。"}],"image":"","imageHint":"姜羊","summary":"当归生姜羊肉汤出自《金匮要略》，为仲景名方，被誉为「温阳补虚第一方」。方中羊肉甘温大热，暖中补虚、益气生肌；生姜辛温，温中散寒、化饮止呕；当归补血和血、活血止痛。三味相合，血虚有寒者服之最效，腹中冷痛、痛经、产后虚寒者咸宜。立冬、小雪、大雪至冬至期间为最佳食用时节。注意本方温燥力强，阴虚火旺、湿热内蕴、外感发热者均当忌服；孕妇服之宜谨慎，恐当归活血动胎。","blocks":[{"type":"table","caption":"当归生姜羊肉汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["羊肉","500 g","甘温大热，温中补虚、益气生肌"],["生姜","25 g","辛温，温中散寒、化饮止呕，量宜重"],["当归","15 g","补血和血、活血止痛，引血归经"],["黄芪（可加）","10 g","补气升阳、固表，与当归为气血相配"],["料酒","适量","行气散寒、矫味去腥"],["盐","少许","调味而不助湿"]]},{"type":"paragraph","text":"此汤最讲究三处细节。其一，羊肉须选带骨或带筋的部位，瘦肉过多则温补之力不足；切块后冷水浸泡至少一小时，中途换水两次，逼出血水，腥味可去大半。其二，焯水时冷水下锅、慢火升温，血沫浮起即捞出，汤色才能清亮。其三，生姜用量不可减至寻常炒菜之量，本方用姜重在温散，取其「辛温行散」之性，与羊肉相合方能达于肌表；拍碎入锅，不可切片，否则辛散力弱。加水一次足量约一千五百毫升，大火煮沸后转最小火，保持汤面微沸不翻滚，慢炖九十分钟，羊骨酥而不脱、肉软而不柴方可。起锅前加盐调味即可，忌加生姜过量辛辣而夺汤味。"},{"type":"paragraph","text":"方义简明：羊肉甘温，为血肉有情之品，温中补虚而不燥不腻；生姜辛温而散，通经脉、逐寒气，主「温」；当归甘温而润，补血活血、止痛，主「补」。三味合用，补中有散、温而不燥，故《金匮要略》用以治血虚有寒之「腹中痛」「胁痛里急」，妇人产后亦多取此。若加黄芪，则成气血双补之配，阳气虚而自汗、乏力者更为合宜。需要注意，中医讲「虚则补之，寒则温之」，本方所治是「血虚有寒」，若仅是怕冷而无血虚之象，则不必重用当归；若兼见口干、舌红少苔，则须另作辨治，不可机械套用。"},{"type":"paragraph","text":"食用时机宜在秋冬至早春，尤以立冬后至冬至前为当令。服用方法为每周一至两次，每次连汤带肉约小半碗至一碗，暖身效果以服后微汗、身轻为佳；体虚者可连服十日至半月为度，汗出即止，不必久服。食用当餐以温软为主，忌生冷瓜果、冰饮与寒凉海鲜。若食后觉口干咽燥、上火烦躁，说明温补太过，应停服数日并请医师调整方向。服药期间忌酒，烈酒助热更甚。汤中油脂较多，晚餐宜略食蔬菜与主食以助运化；餐后宜缓行一刻钟，勿即刻就卧。体质发热、感冒期间一律停用。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"孕妇慎用或忌用：当归有活血之功，可能动胎，妊娠期须经医师明确许可方可食用；产后恶露未净者亦当避之。阴虚火旺者禁服，症见口干咽燥、潮热盗汗、五心烦热、舌红少苔者，服此温燥之汤如添薪助火。湿热内蕴、舌苔黄厚、脘腹痞满者不宜，恐助湿壅滞。外感发热、咽喉肿痛、皮肤疮疡期间停服，恐闭门留寇。痛风、高尿酸血症者注意肉汤嘌呤偏高，不宜多饮。高血压、心力衰竭、水肿患者应少盐少汤，量宜减半。凡对羊肉、生姜过敏者禁食。配伍禁忌：羊肉忌与韭菜、荞麦同食，亦忌与鱼膾、酪同食；半夏、菖蒲服药期间忌食羊肉。本方温热力强，非药食同源之当归仅获准作香辛料与调味品使用，用量须遵医嘱。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["本方主治血虚有寒，非单纯怕冷者皆宜","生姜用量宜重（25 g），拍碎入锅方见辛散之功","羊肉焯水去沫，小火慢炖九十分钟，一次加足水","立冬至冬至为当令，每周至多两次，服后微汗为度","阴虚火旺、湿热、孕妇、外感发热者禁用或慎用"]},{"type":"quote","text":"羊肉 味甘、大熱、無毒。主暖中，頭風，大風，汗出，虛勞，寒冷，補中益氣。","source":"《饮膳正要·卷三·兽品》"}]},{"id":"baihe-lianzi-zhou","title":"百合莲子粥","subtitle":"养阴润肺，宁心安神","category":"药膳方","tags":["养阴","润肺","安神","药膳粥"],"meta":[{"label":"适用人群","value":"肺阴不足见干咳少痰、咽干咽痛、声音嘶哑者；心神不宁见心烦失眠、多梦易醒者；亦适合病后体虚、脾胃尚弱者作平补之膳。风寒咳嗽、痰湿咳嗽者不宜。"},{"label":"主要功效","value":"养阴润肺、清心安神、健脾止泻。用于肺燥咳嗽、心烦失眠、健忘等。"},{"label":"食材组成","value":"鲜百合 30 g（或干百合 10 g），莲子 20 g（去心），粳米 60 g，枸杞 8 g，冰糖少许（糖尿病者去糖）"},{"label":"制作方法","value":"莲子去心、百合洗净，与粳米同入锅，加水约 900 mL，大火煮沸转小火煮 35 分钟至粥稠，加入枸杞再煮 3 分钟，按口味加少许冰糖。"},{"label":"食用注意","value":"莲子心味苦，去心可减苦味并防其寒凉碍胃；风寒咳嗽、脾虚寒湿泄泻者慎用；食少便溏者莲子用量不宜过大，莲子心与莲子相反。"}],"image":"","imageHint":"百合","summary":"百合莲子粥以粳米为底，合鲜百合、莲子与枸杞，是清而不寒、润而不腻的经典养阴安神药膳。百合甘寒入心肺经，养阴润肺、清心安神，《食疗本草》称其蒸过蜜和食之主心急黄；莲子甘平入脾肾经，补脾止泻、养心安神、去心则无苦寒之弊；粳米甘平，益气止烦、和胃长肌肉。三者相配，最宜心肺阴虚而脾胃不健者长期食用。本方药性平和，作夜宵亦宜，但风寒咳嗽与脾虚泄泻者当慎；莲子心苦寒，与莲子相反，使用时须去心。","blocks":[{"type":"table","caption":"百合莲子粥食材配伍与作用","head":["食材","用量","作用"],"rows":[["鲜百合","30 g","甘寒入心肺，养阴润肺、清心安神"],["莲子（去心）","20 g","甘平入脾肾，补脾止泻、养心安神"],["粳米","60 g","甘平，益气止烦、和胃气、长肌肉"],["枸杞","8 g","滋补肝肾、益精明目"],["冰糖","少许","润肺生津调味，糖尿病者去之"]]},{"type":"paragraph","text":"熬此粥贵在「文火慢稠」。粳米先用清水淘洗两遍，冷水浸泡二十至三十分钟，令米粒吸饱水而开花较匀；莲子须去心，去心之法可用竹签穿过莲子中心，剔除绿色莲心，既去苦味又避免其苦寒碍胃。鲜百合掰瓣洗净即可，若用干百合须提前泡发。所有材料入锅后加水约九百毫升，先大火煮沸，随即转最小火，盖盖留缝隙出汽，慢煮三十五分钟，中途搅拌两三次以防糊底，直煮到米粒开花、汤汁挂勺、粥面泛起细密粥油为度。枸杞最易久煮失效，须关火前五分钟投入；冰糖亦宜最后加，久煮则焦苦。若用破壁机或电饭煲煲粥，须选「粥」档并留意搅翻底防焦。"},{"type":"paragraph","text":"百合、莲子、粳米三味，是中医食养中「以脏补脏、平补兼养」的典型组合。百合甘寒质润，入心经以清心除烦，入肺经以润肺止咳，《饮膳正要·菜品》另以「山丹根」一名百合入药，谓其主邪气腹胀、除诸疮肿；莲子甘平而涩，入脾经能补脾止泻、入肾经能固精止带、养心安神，最宜「心脾两虚」之失眠健忘；粳米为五谷之一，《饮膳正要·米谷品》称其「主益气，止烦，止泄，和胃气，长肌肉」，是全方最温和的载体，使滋而不腻、补而不寒。加枸杞一味，取其滋补肝肾、明目，兼顾用眼久者之需。全方寒温相济、阴阳并调，尤宜体质偏燥而脾胃尚弱者。"},{"type":"paragraph","text":"食用建议：可作早餐或晚餐主食，亦可作睡前一小时的小碗安神粥。量以一小碗约 150 mL 为宜，每周三至五次，长期食用更为受宜。服用最佳时机是秋分之后至次年惊蛰之间，此际天气干燥、夜卧渐长，肺阴易耗而心火易浮，正需此方润之安之。若作治疗性调养，可连服一月为度；若仅为日常保养，则两三日一次即可。食用时忌与辛辣煎炸之品同餐，忌浓茶与咖啡，以免苦燥伤阴。鲜品当次用完，剩粥须冷藏并在两小时内吃完，反复加热则失其甘润之性。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"风寒咳嗽、痰多清稀者忌服，百合甘寒、莲子性涩，寒邪未解而先敛肺，反致咳嗽加重。脾虚寒湿、大便溏泄清稀者慎用，莲子虽有止泻之功，然其甘涩滋腻，脾阳虚者服之易生脘腹胀满。孕妇无特殊禁忌，但须注意鲜百合与莲子均不宜过量。糖尿病患者须去冰糖，或以少量木糖醇代之，且须计入每日碳水总量。对百合、莲子过敏者禁食。配伍禁忌：莲子心与莲子相反，用时必须去心；服药期间忌与萝卜同食。鲜百合与莲子均非药品，故无十八反十九畏之虑，但若同时服用中西药物，仍宜先咨询医师。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["莲子必须去心，去心兼去其苦寒之弊","小火慢煮三十五分钟，以米开花、粥挂勺为度","枸杞与冰糖均后放，久煮则失甘润","秋分至惊蛰间食用最合时宜","风寒咳嗽与脾虚泄泻者不宜，孕妇与糖尿病者调整用法"]},{"type":"quote","text":"百合〈平〉主心急黃，（以百合）蒸過，蜜和食之。作粉尤佳。紅花者名山丹，不堪食。","source":"《食疗本草·卷上》"}]},{"id":"fuling-yiyiren-zhou","title":"茯苓薏苡仁粥","subtitle":"健脾利湿，宁心安神","category":"药膳方","tags":["健脾祛湿","利水消肿","药膳粥","祛湿"],"meta":[{"label":"适用人群","value":"脾虚湿盛见身体困重、肢体困倦、面色萎黄、便溏不爽、下肢轻度浮肿、食欲不振者；亦适合思虑过度、心神不宁兼见失眠者。夏秋湿重之时最宜。"},{"label":"主要功效","value":"健脾渗湿、利水消肿、宁心安神。用于脾虚湿困之食少便溏、肢体困重、水肿及心悸失眠。"},{"label":"食材组成","value":"茯苓 15 g，薏苡仁 30 g（炒制或生用），粳米 60 g，莲子 15 g（去心），红枣 4 枚"},{"label":"制作方法","value":"茯苓打碎与薏苡仁同入纱布袋，与粳米、莲子、红枣同煮，加水约 900 mL，大火煮沸后小火煮 40 分钟成稠粥，捞去药包即可食用。"},{"label":"食用注意","value":"《饮膳正要·服药食忌》载「有茯苓勿食醋」，服食此粥期间及前后不宜食醋及醋制品；薏苡仁性偏凉，脾胃虚寒、大便溏泄者宜炒用并减量，孕妇慎用。"}],"image":"","imageHint":"茯苓","summary":"茯苓薏苡仁粥是健脾祛湿的代表药膳，源自《饮膳正要》食疗诸病与后世流传的健脾渗湿方。茯苓甘淡性平，利水渗湿而健脾宁心，最宜脾虚湿盛；薏苡仁甘淡微寒，健脾渗湿、利水消肿，《食疗本草》称其可去干湿香港脚；莲子补脾止泻、养心安神，红枣补中益气，粳米和胃长肌肉。四药相合，祛湿而不伤正、健脾而不壅滞。本方最宜长夏与夏秋之交湿气最盛之时，脾胃虚寒者应炒用薏苡仁并减量，且服食期间忌醋。","blocks":[{"type":"table","caption":"茯苓薏苡仁粥食材配伍与作用","head":["食材","用量","作用"],"rows":[["茯苓","15 g","甘淡平，利水渗湿、健脾宁心"],["薏苡仁","30 g","甘淡微寒，健脾渗湿、利水消肿"],["莲子（去心）","15 g","补脾止泻、养心安神"],["红枣","4 枚","补中益气、养血，缓和渗利"],["粳米","60 g","益气止烦、和胃气，载药下行"],["陈皮（可加）","3 g","理气燥湿，防滋腻碍胃"]]},{"type":"paragraph","text":"此粥的火候与取药有讲究。茯苓为菌核类药材，质地疏松，捣碎或用料理机打粗粒即可，若整块投入则有效成分难以煎出，与薏苡仁一同装入纱布袋可免渣入粥。薏苡仁生者偏凉，须干锅小火慢炒至微黄透香，此即「炒薏苡仁」，既增健脾之力，又减其寒性；炒制时须不停翻动，不可焦糊。粳米淘净后与莲子、红枣同煮，先大火煮沸转小火四十分钟，中途搅拌两次防黏底。若追求更佳口感，可用破壁机将薏苡仁与茯苓先打细浆再与米同煮，但火力过猛则易糊锅。成粥后应稠而不见米粒分明之状，此时药力方能充分融入。"},{"type":"paragraph","text":"从方义看，茯苓、薏苡仁同为淡渗之品，淡能渗湿，故能利水而不伤阴；又同入脾经，故能健脾而不燥烈，这正是「利湿不伤正」的关键。薏苡仁偏于下渗，擅消肿排脓；茯苓偏于淡渗，兼宁心安神，故水肿而心悸失眠者用之尤宜。莲子补脾止泻、养心，与二味相配则渗中有补，湿去而脾气不伤；红枣甘温，补中益气，既助运化，又制薏苡仁之凉；粳米为谷，本经云其「主益气，止烦，止泄，和胃气，长肌肉」，为全方最稳的载体。若腹胀纳呆明显，可加陈皮三克理气燥湿，使补而不滞。全方偏于渗利，故虚证而无湿者不宜久服，恐伤津耗气。"},{"type":"paragraph","text":"食用时机以大暑至白露之间湿气最盛之时为最佳，亦适合梅雨及久雨之季。服法：每日早餐一碗或午餐一碗，连服十日至一月为度；体质改善后可减为每周三次。若为单纯祛湿保健，以每周三至四次、每次一小碗为宜，不必每日不断。可与新鲜蔬菜、豆制品同餐，忌久坐不动与暴饮暴食。服药期间饮食宜清淡少油，忌肥甘厚味、甜腻糕点与冰饮，痰湿与水肿者更须少盐。薏苡仁性微寒，脾胃虚寒者宜改炒用并酌减剂量，可加生姜两片同煮以温中。若出现口干咽干、心烦失眠加重，为渗利伤津之象，应减量或停服。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"孕妇慎用：薏苡仁有滑利之性，《食疗本草》虽言其可去湿，但妊娠期用量宜减，并由医师评估。阴虚津亏、大便干结者不宜，渗利之品易伤阴。泌尿系统感染、肾炎水肿者须在医师指导下使用，不宜自行长期服用。脾胃虚寒、畏寒便溏者，薏苡仁须炒用且减量，或加生姜、陈皮同煮。糖尿病患者须注意粳米计入主食总量，红枣四枚亦须计入。对薏苡仁、茯苓过敏者禁食。配伍禁忌：《饮膳正要·服药食忌》明载「有茯苓勿食醋」，故服食此粥期间及前后一二日，忌食醋、米醋、老陈醋、醋溜菜品与含醋饮料；薏苡仁与养血之品同用时不宜过量，恐其滑利碍血。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["薏苡仁炒用可减寒性、增健脾之功","茯苓须打碎装包，否则药力煎不出","渗利之品易伤阴，虚证无湿者不宜久服","大暑至白露湿盛之时最宜食用","服食期间及前后忌醋，为《饮膳正要》所载明文"]},{"type":"quote","text":"有茯苓勿食醋。","source":"《饮膳正要·卷二·服药食忌》"}]},{"id":"shanyao-paigu-tang","title":"山药排骨汤","subtitle":"健脾益胃，补肾养虚","category":"药膳方","tags":["健脾","补肾","家常汤","小儿食养"],"meta":[{"label":"适用人群","value":"脾胃虚弱、食少便溏、面色萎黄、倦怠乏力者；肾虚腰痛、遗尿、发育缓慢之小儿及老年人；亦适合病后、产后调养。实热、痰湿壅盛者不宜。"},{"label":"主要功效","value":"健脾益胃、补肾填精、益气养血。用于脾肾两虚之食少便溏、腰膝酸软、神疲乏力。"},{"label":"食材组成","value":"铁棍山药 300 g（干山药 50 g），猪排骨 500 g，玉米 1 段（约 200 g），生姜 4 片，料酒 15 mL，盐 2 g"},{"label":"制作方法","value":"排骨冷水浸泡去血水后焯水；山药去皮切段泡水防氧化；与姜片、玉米、料酒同炖 70 分钟，后下山药再炖 20 分钟，加盐调味。"},{"label":"食用注意","value":"山药生者黏液易致过敏，接触皮肤发痒者宜戴手套处理；感冒发热期停服；湿盛腹胀、大便黏滞者少食；高尿酸者注意肉汤与玉米搭配适量。"}],"image":"","imageHint":"山药","summary":"山药排骨汤是家常易做而功效明白的健脾药膳。山药味甘、性温，《饮膳正要·菜品》称其「补中益气，治风眩，止腰痛，壮筋骨」，《食疗本草》则谓薯蓣「治头疼，利丈夫，助阴力」，兼益脾肺与肾三经；猪排骨以血肉有情之品补中益气、益髓养骨；玉米与生姜则行气和中、醒脾开胃。全方甘温平补，最宜脾胃虚弱、肾气不足者平日常食，小儿与老人尤宜。惟山药多黏腻，湿盛腹胀者宜少食；感冒发热期间停服为宜。","blocks":[{"type":"table","caption":"山药排骨汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["铁棍山药","300 g","甘温，补中益气、健脾养肺、补肾填精"],["猪排骨","500 g","甘平，补中益气、益髓养骨，富含蛋白与钙"],["玉米","1 段","甘平，健脾开胃、益气养血"],["生姜","4 片","温中散寒、醒脾，矫肉腥"],["料酒","15 mL","行气散寒、矫味去腥"],["盐","2 g","调味；水肿、高血压者宜再减"]]},{"type":"paragraph","text":"此汤家常易做，但细节决定效果。第一步处理排骨：切块后以清水浸泡四十分钟，中途换水两次，使血水析出；冷水下锅焯烫，水沸后撇净浮沫，捞出用温水冲净，这样汤色清亮而不油。第二步处理山药：戴一次性手套削皮切段，随即泡入清水中，防止多酚氧化发黑；亦可先蒸后切，则更易入口。第三步是下料次序：排骨、姜片、玉米先炖七十分钟，待排骨酥软、山药之粉糯尽释，再下山药续炖二十分钟，若山药与排骨同炖则易煮化，汤不成形。盐必待起锅前再放，早放会使肉质收紧、蛋白凝固而汤味不融。全程小火，汤面只浮细泡。"},{"type":"paragraph","text":"此方的配伍逻辑在「谷肉相配、脾肾同调」。山药为薯蓣科植物，味甘性温，《饮膳正要·菜品》明载其「补中益气，治风眩，止腰痛，壮筋骨」，既入脾而助运化，又入肺而补气津，更入肾而固精，故能三脏并调；且其质黏稠，入汤后能吸附油脂，令汤羹自然稠滑，不必另加淀粉。排骨以骨为髓，肾主骨、生髓，故补中益气之外，尤长于益髓壮骨，兼顾小儿囟门未合、老人骨疏松之需。玉米甘平，《饮膳正要·米谷品》称稷类可「益气补中」，与山药同为谷物，是脾虚者的日常所需。生姜与料酒则辛散行气，防山药之滞、矫排骨之腥，并助谷气外达。"},{"type":"paragraph","text":"食用建议：作为家庭日常汤品，每周二次为宜；若作调养之用，可每日晚餐一碗，连服一月为度，儿童与老人可每三日一次。每次饮汤约 200 mL 并食排骨两三块、山药一段，饭前食用可增食欲，饭后食用则宜先休息片刻再活动。搭配上宜配清炒时蔬与米饭，不宜与生冷瓜果、浓茶同餐。食疗期间不宜暴饮暴食，也不宜以汤代饭，谷肉相配方能全面。感冒发热、咽喉肿痛期间停服，恐甘温壅滞碍邪外出；服后若见腹胀纳呆，应减量或停用并调整配伍。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"感冒发热、外感未解、咽喉肿痛者停服，甘温补益恐闭门留寇。湿热壅盛、舌苔黄厚、大便黏滞不爽者少食或停用，山药黏腻助湿，常见腹胀纳呆。糖尿病患者须注意山药与玉米皆含淀粉较多，须计入主食总量并相应减少米饭。肾功能不全、高血压、水肿者须限制盐量与汤量，盐减至 1 g 以下并遵医嘱。胆囊疾病、胰腺炎急性期忌食油腻浓汤。对山药过敏者（生山药黏液接触皮肤可致瘙痒、接触黏膜可致口唇麻木）禁食，处理时宜戴手套。痛风、高尿酸血症者肉汤与玉米同食须适量，勿饮浓汤。高脂血症者以去浮油为要。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["排骨先浸血水再焯水，汤色清亮不油","山药戴手套削皮并泡水，防氧化也防过敏","排骨与玉米先炖，山药后下，方能糯而不化","盐最后放，早放则肉紧汤不香","糖尿病与水肿者须分别控制淀粉与盐量"]},{"type":"quote","text":"山藥 味甘、溫、無毒。補中益氣，治風眩，止腰痛，壮筋骨。","source":"《饮膳正要·卷三·菜品》"}]},{"id":"gouqi-juhua-cha","title":"枸杞菊花茶","subtitle":"清肝明目，滋补肝肾","category":"药膳方","tags":["清肝明目","滋补肝肾","代茶饮","久视疲劳"],"meta":[{"label":"适用人群","value":"肝肾阴虚见目干涩、视物昏花、头晕耳鸣者；长期用眼、熬夜后眼干眼痛者；亦适合肝阳偏亢之头胀头痛、面红目赤者。脾胃虚寒者不宜多饮。"},{"label":"主要功效","value":"滋补肝肾、清肝明目。用于肝肾不足之目昏不明、头晕耳鸣，兼清虚热。"},{"label":"食材组成","value":"枸杞子 12 g，杭白菊 6 g（干菊），沸水 500 mL"},{"label":"制作方法","value":"枸杞与菊花以沸水冲泡，加盖焖 5 分钟即可饮用；可反复冲泡二至三次，至味淡为止。亦可同煮 3 分钟取汁。"},{"label":"食用注意","value":"菊花为甘苦微寒之品，脾胃虚寒、便溏者不宜；枸杞含糖，糖尿病者须限量；孕妇、哺乳期及外感发热时慎用。"}],"image":"","imageHint":"杞菊","summary":"枸杞菊花茶是流传最广的清肝明目代茶饮。枸杞子甘平入肝肾经，滋补肝肾、益精明目，《食疗本草》称其「叶及子：并坚筋能老，除风，补益筋骨，能益人，去虚劳」；杭白菊甘苦微寒，入肺肝经，疏散风热、平肝明目，《食疗本草》记甘菊「并主头风目眩、泪出，去烦热，利五脏」。二者一补一散、一温一凉，合为平补肝肾而不燥、清肝明目而不寒的经典配伍，最宜用眼过度的现代人常饮。然脾胃虚寒者与糖尿病者当慎。","blocks":[{"type":"table","caption":"枸杞菊花茶食材配伍与作用","head":["食材","用量","作用"],"rows":[["枸杞子","12 g","甘平入肝肾，滋补肝肾、益精明目"],["杭白菊","6 g","甘苦微寒，疏散风热、平肝明目"],["沸水","500 mL","取其清轻之气，不加辛温"]]},{"type":"paragraph","text":"冲泡此茶讲究水温和次序。宜用刚沸腾的水，一次注入约五百毫升，随即加盖焖五分钟，使菊花有效成分充分析出而不过度氧化；先倒出茶汤再续水，可使第一泡浓淡均匀。枸杞质地柔润，久泡易烂，第二次冲泡时可连同枸杞一同短时煮沸三十秒即可，不必久煮；若一次投入过多枸杞，糖分溶出偏多而味过于甜。器具以玻璃杯或盖碗为佳，便于观其色泽；忌用铁质或铝质容器，以免茶汤变色并影响口感。代茶可续泡二至三次，枸杞在第三泡时可连果食用，此时其味甘甜而气已尽，与嚼服杞子有别。"},{"type":"paragraph","text":"此茶之妙，全在寒温并调、补散相济。枸杞子甘平，色赤入心、肝经，《食疗本草》谓其能「坚筋能老，除风，补益筋骨，能益人，去虚劳」，是补肝肾、益精血之上品，性平不寒，故可久服；杭白菊苦寒而气清，《食疗本草》记甘菊「主头风目眩、泪出，去烦热，利五脏」，善清上焦风热、平抑肝阳。一补一清，枸杞补下焦肝肾之阴，菊花清上焦风热之标，故对「肝肾阴虚而兼有虚火上炎」之目昏、头胀最为合宜。若只觉眼干疲劳而无肝热，菊花可减至三克；若面红目赤、头胀口苦而肝火偏旺，则可增量至九克并加决明子五克（须医师指导）。"},{"type":"paragraph","text":"饮用建议：作为日常代茶，每日一至两杯，办公室与书房皆宜；上午与下午各一杯为佳，夜间不宜多饮，以免利尿影响睡眠。若作治疗性调养，可连服两至三月为度，症状改善后改为每日一杯维持。建议在电脑前每用眼四十分钟，远眺绿处一至两分钟，并配合闭目转睛、双手热敷眼部，则茶饮与劳逸相合，效果更佳。饮食上宜清淡，忌辛辣煎炸、烈酒与浓咖啡；晚餐不宜过饱，睡前可用温水送服杞子数粒助眠。服药期间若有正在服用的西药，如降压药、镇静药，应告知医师后再饮用。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒便溏、舌淡苔白者不宜多饮，菊花甘苦微寒，久饮易致胃脘不适与腹泻，宜减量或改用枸杞单独泡饮。孕妇与哺乳期妇女慎用，虽为药食同源之品，但菊花有活血通经之说，须遵医师指导。糖尿病患者须注意枸杞子含糖较多，每日不宜超过十克，并计入每日总糖量，且须与医生共同调整用药。外感发热、咽喉肿痛、头痛鼻塞期间停饮，恐助邪。肝肾功能不全者须遵医嘱。对菊花、枸杞过敏者禁食，过敏体质者初次饮用宜少量试之。低血压者慎用，菊花有降压作用，若出现头晕心慌应停饮。菊花与薏苡仁、藿香类同用无碍，但与滋腻大补之品同用宜间隔服用。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["一补一清，寒温并调是本方核心","沸水冲泡加盖焖五分钟，可续泡二至三次","脾胃虚寒者减菊花量或单用枸杞","每日一至两杯，夜间不宜多饮","用眼配合远眺与闭目转睛，效果更佳"]},{"type":"quote","text":"其葉，正月采，可作羹；莖，五月五日采；花，九月九日采。並主頭風目眩、淚出，去煩熱，利五臟。野生苦菊不堪用。","source":"《食疗本草·卷上·甘菊》"}]},{"id":"duzhong-yaohua-tang","title":"杜仲腰花汤","subtitle":"补肾强腰，接骨续筋","category":"药膳方","tags":["补肾强腰","腰膝酸软","药膳","平补肝肾"],"meta":[{"label":"适用人群","value":"肝肾不足见腰膝酸痛、腰痛乏力、久立则甚、腿软脚弱、头晕耳鸣者；亦可用于骨折、筋骨损伤恢复期及骨质疏松者的辅助调养。湿热痹痛、阴虚火旺者不宜。"},{"label":"主要功效","value":"补肝肾、强筋骨、益精血，兼能安胎。用于肝肾不足之腰膝酸软、筋骨无力。"},{"label":"食材组成","value":"杜仲 12 g，猪腰 2 只（约 250 g），生姜 4 片，料酒 15 mL，盐 2 g，枸杞 6 g（可加）"},{"label":"制作方法","value":"杜仲撕碎或切片，与姜片同水煎 20 分钟取汁；猪腰去筋膜切片，用料酒抓洗去腥后入汤，加枸杞煮 5 分钟，加盐调味。"},{"label":"食用注意","value":"杜仲叶已于 2023 年列入食药物质目录，而杜仲（杜仲皮）本身未列入普通食品目录，作食疗用药须经医师指导；猪腰为动物内脏，高尿酸、高血脂者宜少食。"}],"image":"","imageHint":"杜仲","summary":"杜仲腰花汤以杜仲为主、猪腰为辅，是补肝肾、强筋骨的传统药膳。杜仲甘温，归肝肾经，补肝肾、强筋骨、安胎，《本草纲目》谓其「补中，益精气，治腰痛、胎动不安」；猪腰味咸性温，取其「以脏补脏」之意补肾益精；生姜与料酒矫腥醒脾，枸杞兼滋肾养肝。杜仲须先煎取汁再与猪腰同煮，方能使有效成分充分溶出且不使猪腰老硬。本方为平补之品，宜长期缓图，不宜一次大补；湿热痹阻与阴虚火旺者当忌。","blocks":[{"type":"table","caption":"杜仲腰花汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["杜仲","12 g","甘温入肝肾，补肝肾、强筋骨、益精气"],["猪腰","2 只","咸温，以脏补脏，补肾益精"],["生姜","4 片","温中散寒、醒脾矫腥"],["料酒","15 mL","行气散寒、矫味去腥"],["枸杞","6 g","滋补肝肾、益精明目"],["盐","2 g","调味，量宜轻"]]},{"type":"paragraph","text":"此汤的次序不可颠倒。第一步是杜仲先煎：杜仲为树皮类，质地坚韧，有效成分不易析出，须撕成小块或薄片，冷水浸泡十分钟后加水约六百毫升，先大火煮沸转小火煎二十五分钟，滤取药汁弃渣——此为「先煎」之要领，可使药力尽出而汤不苦涩。第二步是猪腰处理：撕去表面筋膜与中间白色脂膜，对半剖开去净腰臊（若不去净则腥臊难入口），再切片，以料酒少许抓匀腌十分钟冲净。第三步才是合煮：将药汁倒入锅中，加姜片煮沸，下腰片快速汆熟，见其变白卷曲即关火，加枸杞焖五分钟，加盐调味。腰片汆煮务必短，久了则质地变老、腥味复出；用筷子拨散可防粘连。"},{"type":"paragraph","text":"肾者，「主骨、生髓」，腰为肾之外府，肝主筋、肾主骨，肝肾同源则筋骨相养。杜仲甘温而润，入肝肾二经，既补肾精又强筋骨，《本草纲目》称其「补中，益精气」，是治腰痛要药；其「补而能行、温而不燥」之性，尤宜久病腰膝无力者缓图之。猪腰取「以脏补脏」之义，咸温入肾，助杜仲补肾填精；然其胆固醇与嘌呤皆高，故不宜过量，姜与料酒既矫其腥，亦助药力运行。枸杞为佐，滋补肝肾、益精明目，与杜仲相配，肝肾并补。全方偏温补而不峻，适合作为腰膝酸软、久立乏力者的日常药膳调理。"},{"type":"paragraph","text":"食用建议：每周二次，每次饮汤约 200 mL 并食腰片两三片，连服一月为一疗程；若为骨折或骨质疏松的辅助调养，宜长期少量频服，且必须以正规医疗措施为主，不可因食疗而延误接骨、钙剂与抗骨质疏松治疗。最佳食用时间为晚餐后一小时至睡前，服后宜以温水漱口并稍作缓行。配合上应加做八段锦之「摇头摆尾去心火」与「两手攀足固肾腰」两式，配合腰背肌力训练，效果远胜单纯进食。饮食宜淡盐少油，忌久坐久站、忌搬重物、忌熬夜耗伤肾精。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"阴虚火旺者慎用，症见潮热盗汗、五心烦热、遗精、舌红少苔者，杜仲温补助热，不宜。湿热痹阻、腰痛而见口苦苔黄、肢体关节红肿热痛者禁服，应先清湿热。感冒发热期间停服。孕妇如需安胎，须经中医师辨证处方，不可自行按此方食用；本方猪腰为动物内脏，孕期妇女食用前宜咨询医师。肝肾功能不全、高尿酸血症、高脂血症、痛风患者须慎食猪腰，量宜减半并避免饮浓汤。对杜仲、猪腰过敏者禁食。须注意：杜仲叶已列入国家食药物质目录，而杜仲（杜仲皮）未列入普通食品可作药膳的目录，作食疗用药必须经中医师辨证指导，剂量与疗程遵医嘱；本方不宜与寒凉药、滋腻药同服，亦不宜久服过量。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["杜仲必须先煎取汁，药力方能尽出","猪腰须去筋膜腰臊并以料酒抓洗，否则腥臊","腰片汆煮要快，久了则老且腥","补肾需配合腰背肌力训练与正规诊疗","杜仲皮未列普通食品目录，用量须遵医嘱"]},{"type":"quote","text":"腎病禁食甘，宜食黄黍、雞肉、桃、葱之類。","source":"《饮膳正要·卷二·五味偏走》"}]},{"id":"huangqi-qiguoji","title":"黄芪汽锅鸡","subtitle":"益气健脾，固表止汗","category":"药膳方","tags":["补气","固表","云南名馔","药膳"],"meta":[{"label":"适用人群","value":"气虚见倦怠乏力、少气懒言、动则汗出、面色㿠白、易感冒者；亦适合病后、产后、术后恢复期及中老年人日常调养。阴虚阳亢、外感发热者不宜。"},{"label":"主要功效","value":"补气健脾、益卫固表、养血。用于气虚乏力、表虚自汗、易感风邪者。"},{"label":"食材组成","value":"黄芪 20 g，嫩母鸡 1 只（约 750 g），生姜 5 片，葱段 2 根，料酒 20 mL，精盐 2 g"},{"label":"制作方法","value":"黄芪冷水浸泡 30 分钟；鸡身抹盐腌 20 分钟，入汽锅加黄芪、姜葱、清水约 800 mL，用汽锅蒸制约 90 分钟，取出原汁调味即成。"},{"label":"食用注意","value":"黄芪虽已列入食药物质目录，作食疗仍须遵医嘱；感冒发热、咽喉肿痛期间停服；阴虚火旺、血压偏高者慎用，务必遵医嘱。"}],"image":"","imageHint":"汽锅","summary":"黄芪汽锅鸡是云南名馔与中医药膳的经典结合。汽锅为陶制器皿，蒸制时蒸汽在锅顶凝成汤汁滴入锅内，全程不加油、不加水过多，故汤清味醇、原汁原味。黄芪甘微温，入脾肺经，补气升阳、固表止汗、利水消肿，与嫩母鸡同蒸，取血肉有情之品补中益气之力，合黄芪补气固表之功，最宜气虚乏力、易汗、易感冒者。名曰「汽锅」，实为「气足」之喻——气虚者食之最当。惟外感发热与阴虚火旺者当忌。","blocks":[{"type":"table","caption":"黄芪汽锅鸡食材配伍与作用","head":["食材","用量","作用"],"rows":[["黄芪","20 g","甘微温入脾肺，补气升阳、固表止汗、利水消肿"],["嫩母鸡","1 只","甘温，补中益气、补精填髓"],["生姜","5 片","温中散寒、醒脾，助黄芪运行"],["葱段","2 根","通阳气、和五脏，矫腥"],["料酒","20 mL","行气散寒、矫味"],["精盐","2 g","调味"],["汽锅","1 只","凝汤为汁，使原汁原味、不加油盐"]]},{"type":"paragraph","text":"汽锅鸡的关键全在器与火。第一，锅须用带凸起汽嘴的陶制汽锅，若无汽锅亦可用砂锅代替，但须文火隔水蒸以模拟凝汁之效。第二，汽锅使用前以温水洗净，首次使用宜先煮一次去土腥气。第三，蒸汽须自锅顶汽嘴进入，遇冷凝结成汤滴落锅内，全程不加一滴油，方得清鲜；锅内清水约加至鸡身三分之一处即可，过多则汤味被冲淡。第四，黄芪须先以冷水浸泡三十分钟，使纤维舒展；第五，母鸡抹盐腌二十分钟再入锅，可令肉质紧实、汤有咸味。蒸制约九十分钟，关火后不开盖再焖十分钟，鸡肉极嫩而骨可脱。"},{"type":"paragraph","text":"此膳之精妙，在于补法与烹饪法的高度契合。《素问·阴阳应象大论》言「阴阳四时者，万物之根本也」，而气虚者最忌峻补与蛮力；汽锅蒸制属「文火虚炖」，热力温和渐进，最不伤正。黄芪甘微温，为补气升阳、固表止汗之要药，《本草纲目》谓其「补脾肺之气，升补中气」，用于脾虚食少、肺虚喘咳、表虚自汗；嫩母鸡甘温，益中补气、填精益髓，是血肉有情之品，善补而不见燥，二者相合，气血同补而补力绵长。生姜、葱、料酒三味辛散行气，使补药不滞，且引黄芪之性达于肌表，故表虚易汗、反复感冒者服之最合。汤中不加油，全靠鸡与黄芪本味，最合「淡食」养生之旨。"},{"type":"paragraph","text":"食用建议：每周一至两次，作为家庭汤品或病后调养之膳，每次饮汤约 150 至 200 mL 并食肉适量，以晚餐为宜，服后不宜立即剧烈活动。若以固表为目的，可连服八至十周为度，待汗止、体力增后改为每周一次维持。服用期间忌生冷瓜果、忌苦寒之品（苦寒易伤脾阳而致汗更出），忌浓茶与烈酒。日常可配八段锦中的「双手托天理三焦」「调理脾胃须单举」两式以助气机升降；亦可用黄芪 fifteen 克与红枣三枚泡水作日常代茶，晨起温服。若配合艾灸足三里、气海穴则固表之力更著。服药期间如需减重或控制血脂者，应说明本膳以汤为主，不额外加糖。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"感冒发热、咽喉肿痛、外感未解者停服，恐闭门留寇、留邪为患。阴虚阳亢、虚火上炎者慎用，症见潮热盗汗、口干咽燥、五心烦热、舌红少苔者，黄芪甘温，服之助热。实热证、痰热壅盛而见咳黄痰、胸闷者不宜。血压偏高、病情不稳定者服用前须告知医师并遵医嘱，服后若见血压波动、头晕应停服。疮疡初起、红肿热痛期间停用，恐助其势。孕妇慎用，须经医师评估。对鸡肉、黄芪过敏者禁食，高尿酸血症者注意汤中嘌呤与油脂，量宜减并去浮油。黄芪虽已列入国家食药物质目录，但作为食疗用药仍须辨证，须注意：甘草与之相须为用，若同时服用须由医师掌握比例；服药期间忌与萝卜同食，勿用薄荷、槟榔等耗气之品同用。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["汽锅凝汁、全程不加油，是本菜的关键","黄芪先泡三十分钟，母鸡先腌二十分钟","文火蒸九十分钟，关火焖十分钟最嫩","气虚易汗者连服八至十周为度","外感发热与阴虚火旺者一律停服"]},{"type":"quote","text":"春氣溫，宜食麥，以涼之，不可一於溫也。禁溫飲食及熱衣服。","source":"《饮膳正要·卷二·四时所宜》"}]},{"id":"heisan-heizhi-heimi-tang","title":"黑三养发汤","subtitle":"补肾益精，黑发乌须","category":"药膳方","tags":["补肾","养发","乌须","药膳汤"],"meta":[{"label":"适用人群","value":"肝肾不足、精血亏虚见须发早白、脱发枯燥、发质枯槁、腰膝酸软、头晕耳鸣者；亦适合久病体虚、产后血虚或化疗后脱发者作辅助调养。湿热内蕴、脾虚泄泻者不宜。"},{"label":"主要功效","value":"补肾益精、养血润燥。用于精血亏虚之须发早白、脱发、腰膝酸软。"},{"label":"食材组成","value":"黑豆 30 g，黑米 50 g，黑芝麻 15 g，熟地黄 10 g（可用，目录外），何首乌 10 g（目录外，须医师指导），猪骨或鸡爪 4 只，姜 3 片"},{"label":"制作方法","value":"黑豆、黑米提前浸泡 4 小时；与鸡爪、姜片同炖 90 分钟，后下黑芝麻再煮 10 分钟，加少许盐与蜂蜜调味。"},{"label":"食用注意","value":"何首乌、熟地黄不在国家食药物质目录内，须医师指导；黑芝麻润滑通便，便溏者减量；黑豆嘌呤较高，尿酸高者少食。"}],"image":"","imageHint":"三黑","summary":"黑三养发汤以黑豆、黑米、黑芝麻三味黑色食材为主，配以血肉有情之品，循「肾其华在发」「发为血之余」之理而设。黑豆甘平，补肾健脾、养血润燥；黑米甘温，益气养血、补脾强身；黑芝麻甘平，滋补肝肾、益精养血，《食疗本草》称胡麻「久服长肌肉，健人」，其油又能润肠通便。三黑相合，平和不燥，最宜须发枯白、脱发稀疏者长期调食。若配何首乌、熟地黄，则补肾之力更专，但二者不在食药物质目录内，须经医师指导。","blocks":[{"type":"table","caption":"黑三养发汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["黑豆","30 g","甘平，补肾健脾、养血润燥"],["黑米","50 g","甘温，益气养血、补脾强身"],["黑芝麻","15 g","甘平，滋补肝肾、益精养血、润肠"],["熟地黄","10 g","滋阴养血、补精益髓（目录外，须医师指导）"],["何首乌","10 g","补肝肾、益精血、乌须发（目录外，须医师指导）"],["鸡爪或猪骨","4 只","血肉有情，补中益气、填精益髓"],["生姜","3 片","温中散寒、醒脾，矫豆腥"]]},{"type":"paragraph","text":"此汤最要紧的是「泡、炖、后下」三关。黑豆与黑米质地坚硬，须提前用冷水浸泡四小时以上，令其吸水膨胀，炖煮时方能内里酥透而不夹生；黑芝麻则绝不可久煮，其有效成分多在表层与油脂之中，须待汤将成时最后投入，滚沸十秒即关火，久煮则香气挥发殆尽且油脂氧化生苦。鸡爪或猪骨先行焯水去血沫，与姜片同入砂锅，一次加足水约一千五百毫升，大火煮沸转小火慢炖九十分钟，使鸡爪中的胶原蛋白完全溶入汤中；加入黑豆黑米后续炖三十分钟，最后下黑芝麻与盐，淋少许蜂蜜以增甘润。火候宜小火长时，切忌大火滚煮，否则豆类外皮破裂而汤浑浊失形。"},{"type":"paragraph","text":"中医认为「肾其华在发」「发为血之余」，故须发枯白早落者，多从肝肾精血论治。黑豆入肾与脾经，《本草纲目》谓其补肾健脾、益精强骨，又入血分而能养血润燥，最宜发枯而兼血虚者；黑米古称「粳米之色黑者」，甘温而质润，益气养血、补脾强身，《饮膳正要·米谷品》论粳类「主益气，止烦，止泄，和胃气，长肌肉」，其色黑者更为滋补；黑芝麻甘平，《食疗本草》称胡麻「除一切痼疾，久服长肌肉，健人」，入肝肾二经滋补精血，兼润肠通便，为须发枯燥者之要品。配以鸡爪血肉有情之品填精益髓，助三黑补而不滞；熟地黄滋阴养血，何首乌补肝肾益精血，二者加强补肾乌须之力，然非食药物质目录之物，须经医师指导。"},{"type":"paragraph","text":"食用建议：每周二至三次，作为晚餐汤品，每次饮汤约二百毫升并食豆类五十克左右，连服二至三月为一疗程，须发转黑与新发生长皆需时日，不能速效。食用期间宜同时保持充足睡眠、少用染发剂与吹风机高温，并注意头部血供，每日以指腹轻柔按摩头皮百会、太阳、风池诸穴各一分钟，以助养血生发。饮食宜多食黑色与黑色食品之外亦须均衡，不偏食；忌浓茶、咖啡因过量与高糖高脂之品。若有明显甲状腺功能异常、贫血或脱发突然加剧，当及时就医检查，不可以食疗掩盖器质性病变。黑芝麻含油脂多，若大便溏泄明显者可减至十克或改用黑豆黑米为主。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"何首乌、熟地黄均不在国家《既是食品又是药品的物品名单》内，属目录外药材，非药食同源，用作食疗必须经中医师辨证指导，剂量与疗程遵医嘱，不得自行长期大量服用；何首乌有肝损伤报告，用药期间若见乏力、食欲减退、尿色加深应立即停用并就医。大便溏泄、脾胃虚弱者慎用，黑芝麻与黑豆皆滋腻滑肠；黑芝麻润肠，便秘者正宜，然若兼腹胀纳呆者当减量。痰湿壅盛、舌苔厚腻者不宜，恐滋腻助湿。糖尿病患者须注意黑米与蜂蜜之糖分，蜂蜜宜省去。痛风、高尿酸血症者黑豆嘌呤偏高，须减量并多饮汤，肾病患者须遵医嘱。孕妇与哺乳期妇女慎用，何首乌有兴奋子宫作用。凡对豆类、芝麻、骨汤过敏者禁食。服药期间忌与萝卜同食，勿与浓茶同服。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["黑豆黑米浸泡四小时以上方能炖酥","黑芝麻最后下锅，滚沸十秒即止，久煮则苦","鸡爪焯水后小火长炖九十分钟，取其胶质","以二至三月为疗程，须配合充足睡眠与头皮按摩","何首乌、熟地黄为目录外药材，须遵医嘱"]},{"type":"quote","text":"胡麻 味甘、微寒。除一切痼疾，久服長肌肉，健人。","source":"《食疗本草·卷上》"}]},{"id":"heizhima-hetao-hu","title":"黑芝麻核桃糊","subtitle":"补肾益脑，润肠通便","category":"药膳方","tags":["补肾","健脑","润肠","早餐"],"meta":[{"label":"适用人群","value":"肾虚精亏见腰膝酸软、健忘失眠、头晕耳鸣、发枯早白者；亦适合久坐用脑过度、肠燥便秘者作早餐之膳。大便溏泄、痰湿者不宜。"},{"label":"主要功效","value":"补肾填精、健脑益智、润肠通便。用于精血不足之健忘、失眠与肠燥便秘。"},{"label":"食材组成","value":"黑芝麻 20 g，核桃仁 15 g，黑豆粉 30 g，糯米粉 20 g，蜂蜜 15 g（糖尿病者省）"},{"label":"制作方法","value":"黑芝麻小火炒香，与核桃仁、黑豆粉同炒至微香，研成细粉；每次取 30 g 以沸水调成糊，拌入蜂蜜即成，早餐食用。"},{"label":"食用注意","value":"芝麻、核桃皆油脂丰富，脾虚便溏者宜减量；本方能量较高，肥胖者宜减粉量并配无糖豆浆；腹泻、便溏者暂不食用。"}],"image":"","imageHint":"黑芝","summary":"黑芝麻核桃糊是南北通行之早餐糊食，制备简便而滋补明确。黑芝麻甘平，滋补肝肾、益精养血、润肠通便，《食疗本草》称胡麻久服「长肌肉，健人」，其炒香研粉后香气更胜；核桃仁甘温，补肾温肺、润肠通便，《饮膳正要·果品》谓其「食之令人肥健，润肌黑发」；黑豆粉补肾健脾养血，糯米粉补中益气。全方以甘润之品养精血，兼以润肠通便之效，尤宜用脑过度兼便秘者作为每日早餐。惟其性滋腻滑利，脾虚便溏者当减量。","blocks":[{"type":"table","caption":"黑芝麻核桃糊食材配伍与作用","head":["食材","用量","作用"],"rows":[["黑芝麻","20 g","甘平，滋补肝肾、益精养血、润肠通便"],["核桃仁","15 g","甘温，补肾温肺、润肠通便"],["黑豆粉","30 g","甘平，补肾健脾、养血润燥"],["糯米粉","20 g","甘温，补中益气、暖脾胃"],["蜂蜜","15 g","甘平，润燥缓下、调味（糖尿病者省）"]]},{"type":"paragraph","text":"此糊之妙，全在「炒香、研细、调糊」三个环节。黑芝麻与核桃仁须先用小火干炒，炒至微微出香、略带焦气即可离火——火不可大，时间不可长，芝麻一焦即苦，核桃一焦即涩，其香气与不饱和脂肪酸亦随之破坏。炒好放凉至不烫手，再与炒熟的黑豆粉、糯米粉一同放入料理机或石臼中打成极细之粉，过筛一遍去掉粗渣，成品即成极细的香粉。每次取三十克置碗中，先以少量凉开水调成稀糊，再以九十度以上沸水一次冲入，边冲边搅，即刻凝成细腻之糊；沸水须一次冲足，中途再补则易夹生结块。蜂蜜待稍凉（六十度以下）再拌入，高温则蜜性尽失且生酸。"},{"type":"paragraph","text":"中医以「髓之充则脑健」「肾藏精，精生髓」立论，故健脑之源在补肾填精。黑芝麻与胡桃同属脂溶性滋补之品，富含油脂与蛋白质，《食疗本草》谓胡麻「除一切痼疾，久服长肌肉，健人」，《饮膳正要·果品》亦称胡桃「食之令人肥健，润肌黑发」，二者相合，最能滋补肝肾、益精养血、润肠通便，一味主补，一味兼润；黑豆粉补肾健脾而性平和，兼能养血，脾肾同调以增后天生化之源；糯米粉补中益气、暖脾胃，使滋腻之品不伤中焦。四味炒香研粉，则气香而味厚，服之不仅得补，且开胃悦口，是「药食同源」最切于日常的一例。"},{"type":"paragraph","text":"食用建议：作为早餐主食之伴侣，每日一至二次，每次三十克粉调成一碗（约二百五十毫升），宜趁热食，冷后则稠度改变而口感变差。可与水煮蛋、牛奶或无糖豆浆同餐，不宜与过甜之品相配。若以润肠通便为主要目的，宜空腹温水送服，并配合每日饮温水二千毫升与适量膳食纤维；单靠此糊不可替代饮水与纤维。服用期间少吃辛辣燥热与煎炸之品，忌酒；大便通畅后，粉量可减至每日一次。若以健脑益智为长期目标，尚须配合充足睡眠、适度运动与持续用脑训练，方能相得益彰。儿童与老人食用时粉量宜减，糖尿病者去蜂蜜并计入主食碳水总量。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"大便溏泄、脾胃虚弱者不宜，因芝麻、核桃、糯米三者皆滋腻滑肠，服之易加腹胀便泻；腹胀纳呆者当减量或停用。痰湿壅盛、舌苔厚腻者慎用，恐助湿。胆囊炎、胆石症患者须慎用大量油脂，可能诱发胆绞痛，须从少量试起。肥胖、高脂血症者不宜过量，本方每三十克约合二百千卡以上，属高能量食品。糖尿病患者须去蜂蜜，且黑豆粉、糯米粉、黑芝麻均含碳水，须计入每日主食总量并相应减少米饭。婴幼儿与吞咽功能弱者不宜，以免黏稠误吸。芝麻、核桃为常见致敏原，过敏体质者禁食。对以上食材过敏者不得食用。本方各味皆为药食同源之品，不涉十八反十九畏，但若同时服用其他中西药物，仍应先咨询医师；服药期间忌与萝卜同食，勿用浓茶送服。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["小火炒香即可，不可焦糊","打粉过筛，成品才细腻不糙口","先凉水调糊再冲沸水，一次冲足不夹生","蜂蜜待稍凉再拌，高温则失其性","便溏者宜减量，通便不可单靠此糊"]},{"type":"quote","text":"胡桃 味甘、無毒。食之令人肥健，潤肌黑髮，多食動風。","source":"《饮膳正要·卷三·果品》"}]},{"id":"sangshen-gao","title":"桑葚膏","subtitle":"滋阴补血，生津润燥","category":"药膳方","tags":["滋阴","补血","生津","膏方"],"meta":[{"label":"适用人群","value":"肝肾阴虚、血分不足见须发早白、眩晕耳鸣、失眠健忘、口干口渴、肠燥便秘者；亦适合更年期诸症及病后津液亏耗者。脾胃虚寒、便溏者忌多食。"},{"label":"主要功效","value":"滋阴补血、生津润燥。用于肝肾阴虚之须发早白、眩晕耳鸣、口干、便秘。"},{"label":"食材组成","value":"鲜桑葚 500 g，枸杞 30 g，菊花 15 g，蜂蜜 150 g（或冰糖 80 g）"},{"label":"制作方法","value":"桑葚洗净去蒂捣汁，与枸杞、菊花同煎取汁，滤渣后小火浓缩至稠膏，降至四十度以下再拌入蜂蜜，瓶装冷藏。"},{"label":"食用注意","value":"桑葚性寒，脾胃虚寒、大便溏泄者慎用；蜂蜜宜在浓缩后温度降低时拌入，高温则失效；糖尿病者用糖量须减并计入总量。"}],"image":"","imageHint":"桑膏","summary":"桑葚膏是江南传统的时令滋补膏方，以鲜桑葚捣汁熬膏，配枸杞、菊花与蜂蜜而成。桑葚甘酸微寒，归心肝肾经，滋阴补血、生津润燥，《食疗本草》称「桑椹：性微寒。食之补五脏，耳目聪明，利关节，和经脉，通血气，益精神」；枸杞滋补肝肾、益精明目；菊花清肝明目，一补一清；蜂蜜则补中润燥、缓下通便。四味相合，成膏后服用便捷，最宜须发早白、津伤口渴、肠燥便秘者长服。然桑葚性寒，脾胃虚寒者当慎用。","blocks":[{"type":"table","caption":"桑葚膏食材配伍与作用","head":["食材","用量","作用"],"rows":[["鲜桑葚","500 g","甘酸微寒，滋阴补血、生津润燥、入心肝肾"],["枸杞","30 g","甘平，滋补肝肾、益精明目"],["菊花","15 g","甘苦微寒，清肝明目、去烦热"],["蜂蜜","150 g","甘平，补中润燥、缓下解毒、矫味"]]},{"type":"paragraph","text":"熬膏的关键在「取汁、浓缩、后蜜、勿高温」。第一步择鲜桑葚须选成熟发黑者，去蒂洗净后用纱布滤去碎渣与虫砂，再捣成浆，用纱布或细筛滤取纯汁，汁液呈紫红而清亮为佳。第二步将桑葚汁与洗净的枸杞、菊花同入砂锅，先大火煮沸转小火煎煮二十分钟，滤去药渣，得清膏。第三步是最要紧的浓缩：须以最小火持续搅拌，防止糊底焦化，熬至膏体挂勺、滴入冷水可凝成半固体（约需一至两小时，视汁量而定）。第四步离火，待膏温降至四十摄氏度以下再拌入蜂蜜——高温之下蜂蜜既失其润燥之性，又易发酵变质。第五步装入洗净干燥的玻璃瓶，密封冷藏，可存一至三个月。"},{"type":"paragraph","text":"桑葚为桑树所结之聚精果实，《食疗本草》谓其「性微寒。食之补五脏，耳目聪明，利关节，和经脉，通血气，益精神」，是药食同源中滋阴兼养血之妙品，尤善「以形治形」，取其果实之色以入肝肾；枸杞与之相配，一为平补肝肾、益精明目，一为清泄肝热，肝肾得补而虚火不炽，故本方标本兼顾；蜂蜜甘平，补中益气、润燥缓下，既矫桑葚之酸涩、枸杞之滋腻，又助其润肠通便之功，是为膏剂不可少之使。熬膏之所以能久存不坏、服之省力，正赖其性甘而润、得蜜则缓而不燥。"},{"type":"paragraph","text":"食用建议：每次取一至二汤匙（约十至十五克），以温开水或淡茶调服，每日一至二次，宜在两餐之间空腹或餐后一小时服用；亦可将其涂于馒头、面包佐餐。开启后须用洁净干燥的勺取用，忌沾染生水与唾液污染罐口，取后随即旋紧冷藏。服用期间饮食宜清淡而富于津液，多食梨、百合、银耳等以助润燥，忌辛辣煎炸、烧烤与烈酒；咖啡浓茶亦宜少饮，其燥性易耗伤津液。若以治疗口干、便秘为目标，可连服一至三月为度；若作日常保健，每周三四次已足。夏日桑葚上市时节熬膏最合时令，此时价格最贱而风味最足；若用干桑葚替代，则须先以温水泡发再熬，量减半。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒便溏、大腹胀满者忌多食，桑葚甘寒滋腻，服之易加腹泻与胃脘不适；此类人若欲食，须配生姜同用或改用枸杞单泡。痰湿壅盛、舌苔白腻者慎用，恐助湿碍中。糖尿病患者禁用蜂蜜，改以冰糖或元贞糖替代并大幅减量，且桑葚本身含糖较多，须计入每日总量并监测血糖；服后若血糖升高应立即停用。腹泻、肠易激综合征发作期停服，蜂蜜与桑葚皆有缓下作用。婴幼儿、痰湿壅盛之小儿不宜。服药期间忌与萝卜同食。蜂蜜在加热六十度以上即失去部分酶活性，故必须待膏温降至四十度以下再拌；如以高温浓缩代替后加，则蜂蜜作用全失，不可取。对桑葚、枸杞、菊花的过敏体质者禁食，其中对菊花粉过敏者较常见，首次少量试服。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["桑葚须择熟黑者，捣后过筛取纯汁","小火浓缩并不断搅拌，防糊底","膏温降至四十度以下再拌蜂蜜","每次十至十五克，每日一至二次","脾胃虚寒者忌多食，糖尿病者须改糖并计入总量"]},{"type":"quote","text":"桑椹∶性微寒。食之補五臟，耳目聰明，利關節，和經脉，通血氣，益精神。","source":"《食疗本草·卷上·桑》"}]},{"id":"chenpi-fuling-yin","title":"陈皮茯苓饮","subtitle":"理气化痰，健脾渗湿","category":"药膳方","tags":["理气","化痰","健脾","代茶饮"],"meta":[{"label":"适用人群","value":"脾虚湿盛、痰气交阻见胸脘痞闷、纳呆腹胀、恶心欲呕、痰多色白、倦怠乏力、大便溏而不爽者；尤宜夏秋湿重之时及肥甘饮食之后。阴虚津亏者不宜。"},{"label":"主要功效","value":"理气健脾、燥湿化痰、渗湿和中。用于脾虚痰湿之脘痞纳呆、呕恶便溏。"},{"label":"食材组成","value":"陈皮 6 g，茯苓 12 g，荷叶 6 g，炒麦芽 10 g，冰糖少许（糖尿病者省）"},{"label":"制作方法","value":"陈皮、茯苓、荷叶、炒麦芽洗净后加冷水 600 mL 浸泡 30 分钟，煎煮 20 分钟滤汁，加冰糖调匀，分次温饮。"},{"label":"食用注意","value":"陈皮、茯苓、荷叶、麦芽皆为食药物质目录内之品，可长期作代茶饮；《饮膳正要·服药食忌》载「有茯苓勿食醋」，服饮期间忌醋。孕妇慎用麦芽。"}],"image":"","imageHint":"陈茯","summary":"陈皮茯苓饮是化痰祛湿最平和的一张代茶方。陈皮即橘皮，辛苦温、理气健脾、燥湿化痰，《饮膳正要·料物》称其「止消渴，开胃气，下痰，破冷积」；茯苓甘淡平，健脾渗湿、宁心安神；荷叶苦涩平，升清降浊、化湿和中；炒麦芽甘平，消食健胃。四味相合，辛开苦降、淡渗分利，共奏理气化痰、健脾渗湿之效，是梅雨与长夏湿重之时的当家之饮。惟阴虚津亏者不宜。","blocks":[{"type":"table","caption":"陈皮茯苓饮食材配伍与作用","head":["食材","用量","作用"],"rows":[["陈皮（橘皮）","6 g","辛苦温，理气健脾、燥湿化痰"],["茯苓","12 g","甘淡平，健脾渗湿、宁心安神"],["荷叶","6 g","苦涩平，升清降浊、化湿和中"],["炒麦芽","10 g","甘平，消食健胃、除胀"],["冰糖","少许","调味，糖尿病者省去"]]},{"type":"paragraph","text":"此饮以「煮」代「泡」，功效更胜。四味药皆为饮片或干品，须先以冷水浸泡三十分钟，令干燥者吸饱水分，其中陈皮与荷叶中的挥发油与黄酮类成分方能于后续煎煮中缓缓释出。加水约六百毫升，大火煮沸后转小火煎煮二十分钟，去滓滤汁，得澄澈药液约三百五十毫升。取汁后若需加冰糖调味，须待温度降至六十度以下方加，糖在高温中易焦化发苦，且会破坏部分有效成分。陈皮宜用陈年者，即「陈皮」，其性温而燥烈减、化湿力存；取时须刮去内瓤白色部分（橘络除外，另可入药），因内瓤性滞而碍气。此饮宜温饮，趁热缓饮，一日可分二至三次，不宜放冷久置。"},{"type":"paragraph","text":"脾为生痰之源，肺为贮痰之器；故治痰湿之要，不在专事化痰，而在健脾以绝生痰之源，陈皮、茯苓正取此意。陈皮辛苦而温，《饮膳正要·料物》谓其「止消渴，开胃气，下痰，破冷积」，长于理气健脾、燥湿化痰，其「陈久者良」之性，尤为入汤泡饮所重；茯苓甘淡而平，淡能渗湿，故能利水以泄浊、健脾以复运，二者相配，一燥一渗，湿去而脾运自复。荷叶升清降浊，助清阳上升、浊阴下行，令中焦之气机得运；炒麦芽甘平，消食除胀，饬食积停滞之弊。四味合用，辛开苦降、淡渗分利，湿浊自去而脾气不伤，是治痰湿之标本兼顾之法。"},{"type":"paragraph","text":"食用建议：作为日常代茶，每日一剂，分二至三次温饮；夏秋湿重或饮食油腻之后可日饮一剂，连服一至二月为度，俟脘腹舒展、苔苔转薄再改为每周二至三次。服药期间饮食宜清淡，三餐定时定量，晚餐不过饱，忌肥甘厚味、生冷瓜果、甜腻糕点与冰饮；每日宜饮温水二千毫升以上，并配合快走、太极拳、八段锦等以助运化，饮后不宜即刻就卧，可缓行一刻钟。若同时有痰多色白、胸闷，可加陈皮至九克；脘腹胀满为主者加炒莱菔子六克（须医师指导）；纳差食积者加焦山楂九克。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"阴虚津亏者忌用，症见口干咽燥、五心烦热、潮热盗汗、舌红少苔者，陈皮燥烈、荷叶升散，久服更伤阴液。孕妇慎用，炒麦芽有回乳之力，哺乳期妇女亦不宜；孕妇如需调理须先咨询医师。胃酸过多、胃及十二指肠溃疡活动期者慎用，芳香燥烈之品可能刺激胃酸分泌而加重胃痛。阴虚火旺、血热妄行者不宜。婴幼儿、孕妇及体质敏感者慎用。白术、苍术类燥湿健脾药与之相合，但本方不宜与温燥之附子、肉桂同用，亦不宜久服耗气之品。服药食忌：依《饮膳正要·服药食忌》所载「有茯苓勿食醋」，服饮此茶期间及前后一二日，忌食醋、米醋、老陈醋及醋溜菜品、含醋饮料。对陈皮、茯苓、荷叶、麦芽过敏者禁食，柑橘类过敏者尤须注意。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["陈皮须刮去内瓤，用陈年者为佳","先浸三十分钟再煎二十分钟，药力方足","冰糖待降温至六十度以下再加","温饮，一日可分二至三次","服饮期间忌醋，为《饮膳正要》明文记载"]},{"type":"quote","text":"陳皮 味甘、平、無毒。止消渴，開胃氣，下痰，破冷積。","source":"《饮膳正要·卷三·料物》"}]},{"id":"lianzi-qianshi-tang","title":"莲子芡实汤","subtitle":"固肾止遗，健脾止泻","category":"药膳方","tags":["固肾","止遗","健脾","收敛固涩"],"meta":[{"label":"适用人群","value":"肾虚不固、脾肾两虚见久泻久痢、遗精滑精、带下清稀、遗尿频数、小儿脾虚泄泻者；亦适合老年人夜尿频多与病后调养。实热泄泻、湿热蕴结者忌服。"},{"label":"主要功效","value":"补脾益肾、固精止遗、止泻。用于脾肾两虚之久泻、遗精、带下、遗尿。"},{"label":"食材组成","value":"莲子 20 g（去心），芡实 20 g，茯苓 15 g，淮山药 20 g，莲子心 1 g（可加），猪骨或排骨 300 g"},{"label":"制作方法","value":"莲子去心、芡实与茯苓洗净，与排骨同炖 80 分钟，后加山药续炖 20 分钟，加盐调味，莲子心最后撒入。"},{"label":"食用注意","value":"莲子、芡实、茯苓、山药皆为食药物质，可作长期调养；惟本方收敛力强，大便秘结者忌服，感冒发热期停服，忌与萝卜同食。"}],"image":"","imageHint":"莲芡","summary":"莲子芡实汤是《饮膳正要·果品》所载莲子「补中养神，益气，除百疾，轻身不老」与鸡头（芡实）补中益精之义的合方，为脾肾两虚、固摄失职者的经典药膳。莲子甘平，补脾止泻、养心安神、益肾固精；芡实甘涩平，益肾固精、补脾止泻、除湿止带；茯苓健脾渗湿；山药补脾养胃、生津益肺。四味相合，收中有补、补而不滞，最宜久泻久痢、遗精滑精、带下清稀、小儿脾虚泄泻者长期调食。惟本方收敛力强，实热与湿热者当忌。","blocks":[{"type":"table","caption":"莲子芡实汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["莲子（去心）","20 g","甘平，补脾止泻、养心安神、益肾固精"],["芡实","20 g","甘涩平，益肾固精、补脾止泻、除湿止带"],["茯苓","15 g","甘淡平，健脾渗湿、宁心安神"],["淮山药","20 g","甘平，补脾养胃、生津益肺、补肾涩精"],["排骨","300 g","补中益气，助运化"],["莲子心","1 g","清心降火，制莲子之温（少量）"],["盐","少许","调味"]]},{"type":"paragraph","text":"此汤以「去心、分层下料、文火长炖」为要。莲子须逐一剖开剔除绿色莲心，莲心苦寒，清心除热而偏泄，与本方收敛之旨相左，故当去之，量多者可用小刀剖开后以清水冲洗去心，勿使莲肉破碎。芡实为芡实科植物的种子，种皮坚硬，须提前浸泡二小时以上方能炖酥，若时间不足则外硬内粉而无效；亦可先干锅微炒至微裂，泡水后更易出粉。排骨焯水去血沫，与莲子、芡实、茯苓同炖，水一次加足约一千二百毫升，大火煮沸转小火慢炖八十分钟；山药于起锅前二十分钟削皮切段下锅（宜戴手套，避免黏液致皮肤瘙痒），续炖二十分钟，令其粉糯入汤。莲子心研极细末于出锅前撒入，只取一分苦香而不失其清心之功。全程忌大火猛滚。"},{"type":"paragraph","text":"此方以「脾肾同治、固摄并施」立论。脾主运化而升清，肾主封藏而固精，二者一升一藏，共司水谷精微之输布与封藏。莲子甘平而涩，入脾经能补脾止泻、入肾经能益肾固精、又能养心安神，《饮膳正要·果品》谓其「补中养神，益气，除百疾，轻身不老」，最宜久泻与心神不宁并见者；芡实甘涩而平，《饮膳正要》以「鸡头」名之，谓其「主湿痹，腰膝痛，补中，除疾，益精气」，专入脾肾，既补又涩，为止泻止遗止带之要药，与莲子相配，涩中有补，补而不留邪；茯苓健脾渗湿，寓「补而不滞」之义，防二味收敛而碍脾；山药补脾养胃、生津益肺，补肾涩精，兼固大便。四味合用，收中有散、补中有渗，最宜久病虚损者缓图。"},{"type":"paragraph","text":"食用建议：每日或隔日一剂，作晚餐汤品，每次饮汤约二百毫升并食莲子、芡实、山药各十至二十克，连服一至三月为度；小儿与老人可减为每周三至四次。服药期间饮食宜清淡而富有营养，宜以山药、莲子、小米之类易化之物为主，忌生冷油腻、辛辣刺激与粗硬难化之品；晚餐宜七分饱，餐后不宜即卧。配合上，可每日以艾条温灸足三里、关元、气海诸穴各十五分钟，以助脾肾阳气；小儿可配合捏脊与摩腹，能增健运之效。若见大便渐成形、精神好转，当逐渐减量，不宜久用收敛之品而致恋邪。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"大便秘结、实热泄泻、湿热痢疾者禁用，本方收敛力强，误用恐闭门留寇、恋邪不化；腹胀纳呆、嗳气而大便不畅者亦不宜。感冒发热、咳嗽痰多期间停服。痰湿壅盛、舌苔厚腻者慎用。婴幼儿不宜单以汤药喂养，乳食为主；小儿脾虚泄泻须儿科医师评估后方可用药食调理。糖尿病患者须注意莲子、芡实、山药含淀粉较多，须计入主食总量。莲子、芡实、茯苓、山药四味皆在国家食药物质目录之内，可作日常调养，但「有茯苓勿食醋」，服药期间忌醋及醋制品。服药期间忌与萝卜同食，忌与石膏、芒硝类寒下之品同用。对莲子、芡实过敏者禁食，壳类过敏者亦须注意。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["莲子必须去心，芡实须提前泡两小时以上","收敛之品配茯苓、山药，补而不滞","山药后下二十分钟，戴手套处理防痒","莲子心研末最后撒，只取一分清心之功","实热泄泻、便秘者禁服，服期间忌醋忌萝卜"]},{"type":"quote","text":"雞頭 味甘、平、無毒。主濕痹，腰膝痛，補中，除疾，益精氣。","source":"《饮膳正要·卷三·果品》"}]},{"id":"guiyuan-hongzao-cha","title":"桂圆红枣茶","subtitle":"补益心脾，养血安神","category":"药膳方","tags":["补益心脾","养血安神","气血不足","代茶饮"],"meta":[{"label":"适用人群","value":"气血不足、心脾两虚见面色萎黄、头晕心悸、失眠多梦、健忘、食少体倦者；亦适合产后血虚与中老年日常调养。痰湿壅盛、阴虚火旺者不宜。"},{"label":"主要功效","value":"补益心脾、养血安神。用于气血亏虚之面色无华、心悸失眠、健忘乏力。"},{"label":"食材组成","value":"桂圆肉 8 枚，红枣 5 枚，枸杞 8 g，生姜 2 片，红糖少许（糖尿病者省）"},{"label":"制作方法","value":"桂圆剥壳去核，红枣去核撕开，与姜片同入杯，沸水冲泡加盖焖 10 分钟；也可加红枣、桂圆先煮 8 分钟再放枸杞。"},{"label":"食用注意","value":"桂圆肉、红枣、枸杞皆在国家食药物质目录之内，可作日常代茶；然本方甘温助热，阴虚火旺、痰湿者不宜多饮，成人每日桂圆以八至十枚为度。"}],"image":"","imageHint":"桂圆","summary":"桂圆红枣茶是最为人所熟知的养血安神代茶饮。桂圆肉即龙眼肉，甘温入心脾经，补益心脾、养血安神，《饮膳正要·果品》谓其「主五脏邪气，安志，厌食，除虫，去毒」；红枣甘温，补中益气、养血安神，《饮膳正要》称其「主心腹邪气，安中养脾，助经脉，生津液」；枸杞滋补肝肾、益精明目；三者相合，益气与养血并行，最宜气血不足、心悸失眠者。惟其甘甜滋腻，痰湿壅盛与阴虚火旺者当少饮，糖尿病者须减糖。","blocks":[{"type":"table","caption":"桂圆红枣茶食材配伍与作用","head":["食材","用量","作用"],"rows":[["桂圆肉","8 枚","甘温入心脾，补益心脾、养血安神"],["红枣","5 枚","甘温，补中益气、养血安神、生津"],["枸杞","8 g","甘平，滋补肝肾、益精明目"],["生姜","2 片","辛温，温中醒脾，调和甘腻"],["红糖","少许","温中调味（糖尿病者省去）"]]},{"type":"paragraph","text":"此茶宜「煮」与「泡」两法并行，随取随饮。整粒红枣须先用小刀剖开去核撕成两瓣，这样有效成分易于释出，也避免整核在杯中久泡致苦；桂圆剥壳去核，果肉肥厚者一切两半即可。制作时可先将桂圆肉、红枣、姜片入小锅加水约四百毫升，煮沸后小火八分钟，令气味转浓；再投入枸杞，用余温焖五分钟，枸杞久煮则失其清润。亦可用保温杯直接冲泡：沸水注入后加盖焖十分钟，饮至一半再续水，第二泡味更醇。取饮时用勺连果肉同食，不宜只饮其水。若是气血亏损较重者，可将红枣增至八枚并加黄芪三小片同煮（须医师指导）。温饮最佳，每日一壶，可分二至三次饮尽。"},{"type":"paragraph","text":"心主血、脾为气血生化之源，故血虚者多见心神失养而眠不安梦，治当心脾同调。桂圆肉甘温而润，《饮膳正要·果品》谓其「主五脏邪气，安志，厌食」，正取其安神之功；其与红枣相配，一为补心脾之血，一为补脾胃之气，气血相生而生化有源，是典型的「气能生血」配伍；枸杞滋补肝肾，肝藏血，肾藏精，精血同源则血有所化，枸杞于大队甘温之中兼调肝肾，使全方不偏不燥；生姜一味看似多余，实为要着——大队甘温滋腻之品最易碍脾，姜辛温行散，既醒脾助运，又制其腻。观全方，补而不滞、温而不燥，是日常气血双补之佳品。"},{"type":"paragraph","text":"食用建议：每日一壶，上午与下午各饮一次，冬季与经期后连饮十日至一月为度；若有明确失眠困扰，可在睡前二小时饮一杯，忌临睡前大量饮汤以免夜尿。若为日常保健，间断饮用即可，不必每日不断。饮用期间饮食宜清淡而富营养，宜多食瘦肉、肝脏、深色蔬菜与豆制品，忌生冷寒凉、咖啡浓茶与烈酒；可配合适度散步与八段锦「双手托天理三焦」「调理脾胃须单举」以助气血运行。若经期量多者，可饮淡一些并忌用活血之品。服食期间注意口腔清洁，睡前刷牙并饮温水一杯，以减甜腻之弊。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"阴虚火旺、潮热盗汗、五心烦热、舌红少苔者不宜，症见口干咽燥、失眠心烦、便干溲赤者，甘温助热，饮之如火上浇油。痰湿壅盛、脘腹胀满、苔厚腻者慎用，本方甘腻助湿，饮后腹胀更甚。糖尿病患者须减红糖或去之，桂圆与红枣含糖较高，每日桂圆不宜超过八枚，并须计入每日总糖量，血糖控制不佳者暂停饮用。感冒发热、外感未解、咳嗽痰多期间停饮。儿童不宜多饮，糖分较多且易养成嗜甜之习；孕妇可饮，但须注意红枣桂圆之甘温，血糖偏高者须限食。凡对核果类（桃、杏、栗等）过敏者，因与桂圆同科，过敏体质者须谨慎试用。服用此茶期间若同时服抗凝药，须告知医师；服药期间忌与萝卜同食，勿用浓茶送服。食疗不能替代药物治疗，具体用量须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["红枣剖开去核，桂圆去核，成分方易释出","枸杞最后投，久煮则失清润","姜片一味不可省，醒脾而制其腻","每日一壶分二三次，睡眠不佳者睡前二小时饮","阴虚火旺、痰湿、糖尿病者须减量或停饮"]},{"type":"quote","text":"龍眼 味甘、平、無毒。主五臟邪氣，安志，厭食，除虫，去毒。","source":"《饮膳正要·卷三·果品》"}]},{"id":"hetao-heizhima-hu-qi","title":"核桃黑芝麻糊（滋肾强腰款）","subtitle":"滋肾强腰，益精养血","category":"药膳方","tags":["滋肾强腰","益精","药膳糊","中年久坐"],"meta":[{"label":"适用人群","value":"肾精不足、腰膝酸软、久立乏力、头晕耳鸣、健忘脱发者；亦适合中年久坐、熬夜耗伤肾精者作日常滋补。痰湿壅盛、便溏者不宜。"},{"label":"主要功效","value":"滋补肾精、强健腰膝、益养气血。用于肾精亏虚之腰膝无力、健忘脱发。"},{"label":"食材组成","value":"核桃仁 20 g，黑芝麻 15 g，淮山药粉 20 g，芡实粉 10 g，炒黑豆粉 10 g，盐少许"},{"label":"制作方法","value":"核桃仁与黑芝麻小火炒香，与炒黑豆同研极细末；每次取黑芝麻核桃粉 20 g、山药芡实粉 15 g，以沸水调匀成微咸糊，晨起温食。"},{"label":"食用注意","value":"胡桃未列入国家食药物质目录，作为药材调补须遵医嘱；本方偏温润，脾胃虚寒、便溏者宜减量并加姜汁同调；痰湿者禁服。"}],"image":"","imageHint":"核芝","summary":"核桃黑芝麻糊是黑芝麻核桃糊的「滋肾强腰」变方，去蜂蜜之甘润而加山药、芡实、黑豆健脾固肾之品，尤宜中年肾精渐亏者。核桃仁甘温，补肾温肺、润肠，《饮膳正要·果品》称其「食之令人肥健，润肌黑发」；黑芝麻甘平，滋补肝肾、益精养血；山药补脾养胃、补肾涩精；芡实益肾固精、补脾止泻；炒黑豆补肾健脾养血。全方温润而兼收涩，以脾健运为基，适合长期缓食。惟胡桃未列食药物质目录，用作药材调补须遵医嘱。","blocks":[{"type":"table","caption":"核桃黑芝麻糊食材配伍与作用","head":["食材","用量","作用"],"rows":[["核桃仁","20 g","甘温，补肾温肺、益精、润肠"],["黑芝麻","15 g","甘平，滋补肝肾、益精养血"],["淮山药粉","20 g","甘平，补脾养胃、补肾涩精"],["芡实粉","10 g","甘涩平，益肾固精、补脾止泻"],["炒黑豆粉","10 g","甘平，补肾健脾、养血润燥"],["盐","少许","微咸引肾，微量即可"]]},{"type":"paragraph","text":"此糊为「温肾固精、微咸为宜」之制，与甜食方不同。核桃仁与黑芝麻先以小火干炒至出香而未焦，随即放凉，与炒黑豆一并打成极细之粉，过筛去渣，装瓶密封防潮防哈，取用时以干燥汤匙舀取。食用时先以少量凉开水调成糊浆，再冲入沸水，边冲边搅使其凝稠，冲水须一次足量，中途补冲则易结块。此糊以咸味调和，故不必加糖；若嫌过淡，可用少许盐与两滴香油提味，或加数粒红枣同煮增加甜润，但糖尿病者仍须避免。为增温运之力，脾胃虚寒者可用三片生姜煮水代白水调糊，服后胃中温暖而更易运化。晨起温食为佳，午后加餐亦可，每次一至两碗，连服两至三月。"},{"type":"paragraph","text":"肾主骨生髓，腰为肾之府；中年以后肾精渐亏，腰膝失养而酸软乏力，遂需以食补肾。中医讲「髓之充则骨强」，补肾即所以强骨；又讲「精血同源」，精足则血生，发得其所养而不早白。核桃仁甘温而润，入肾经补精填髓，《饮膳正要·果品》称「食之令人肥健，润肌黑发」，正取其温润兼养发之功；黑芝麻甘平，滋补肝肾、益精养血，与核桃相配，一温一平，肝肾并补；淮山药补脾养胃、生津益肺，更能补肾涩精，且其健脾之力使补而不滞；芡实益肾固精、补脾止泻，与山药相配，收涩之中寓补益，为久服打基础；炒黑豆补肾健脾、养血润燥，调和全方。相较甜食方，此方去蜂蜜之缓下，加山药芡实之收涩，故更适合大便正常或偏溏、兼见夜尿频多者。"},{"type":"paragraph","text":"食用建议：每日晨起一碗（约二百五十毫升），或作为午后加餐，每日至多二次，连服二至三月为度。服用期间宜配合腰背肌力锻炼，如八段锦「摇头摆尾去心火」「两手攀足固肾腰」二式与仰卧起坐、平板支撑，每日十五至三十分钟；劳力所伤之肾精，非食补所能独任，须动静相济。饮食上宜少酒少辛辣，多食黑色食材与优质蛋白，忌久坐不动、熬夜与过度用脑耗神。若出现夜尿明显减少、膝软有力，为肾气充盈之佳象；若大便偏干或腹胀，则减芡实、加少许生姜或改用黑豆粥。少女、少年处于生长发育期不宜过食温补之品，儿童减半。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、大便溏泄清稀者宜减量并加生姜同调，本方滋润滑肠，脾阳虚者单用易致腹泻加重。痰湿壅盛、舌苔白厚腻者禁服，恐滋腻助湿、碍脾运化。阴虚火旺而大便干结者，本方收涩之品不宜过量，宜减芡实、增黑芝麻与蜂蜜另制。感冒发热期间停服。胆囊炎、胆石症、胰腺炎患者慎用大量油脂，胡桃与黑芝麻油脂丰富，服时须从少量试起。肥胖与高脂血症者注意每份约合二百千卡以上，脂类食物总量须纳入全天计算。孕妇与哺乳期妇女可作少量调养，然胡桃、芝麻油脂多，不宜过量。凡对坚果、芝麻、豆类过敏者禁食。须特别说明：胡桃未列入国家《既是食品又是药品的物品名单》，作为药材调补必须经中医师辨证指导，剂量与疗程遵医嘱；服药期间忌与萝卜同食，勿与石膏、芒硝等寒下药同用。食疗不能替代药物治疗。"},{"type":"keypoints","title":"掌握要点","items":["本方为咸口微补之制，与甜食方不同","坚果与芝麻小火炒香即可，不可焦","打粉过筛、密封防潮，方能久存","须配合腰背肌力训练，不可仅赖食补","胡桃未列食药物质目录，用量须遵医嘱"]},{"type":"quote","text":"除去風，潤脂肉，令人能食。……通經絡氣，潤血脈，黑人鬢發。","source":"《食疗本草·卷上·胡桃》"}]},{"id":"banli-paigu-zhou","title":"板栗排骨粥","subtitle":"补肾强腰，健脾养胃","category":"药膳方","tags":["补肾","健脾","粥品","家常食养"],"meta":[{"label":"适用人群","value":"脾肾不足、肾气不充见腰膝酸软、乏力健忘、食少便溏、小儿发育迟缓者；亦适合中老年日常补益与病后调养。实热、痰湿壅盛者不宜。"},{"label":"主要功效","value":"补肾强腰、健脾养胃、益气养血。用于脾肾两虚之腰膝无力、食少便溏、气血不足。"},{"label":"食材组成","value":"鲜板栗 150 g，猪排骨 200 g，粳米 60 g，红枣 4 枚，姜 3 片，盐 1 g"},{"label":"制作方法","value":"排骨焯水去沫；板栗去壳去衣，与粳米、红枣、姜片同入锅加水约 1000 mL，大火煮沸转小火煮 45 分钟成稠粥，加盐调味。"},{"label":"食用注意","value":"栗子炒食壅人氣，生食过多易腹胀便秘，故须煮熟适量；糖尿病患者须注意板栗与粳米之淀粉总量；高尿酸者排骨限量。"}],"image":"","imageHint":"栗粥","summary":"板栗排骨粥以板栗为主、粳米为底，配排骨与红枣，是脾肾同补的家常药粥。板栗即栗，《饮膳正要·果品》称其「味咸、温、无毒。主益气，厚肠胃，补肾虚」，入脾肾二经而补肾为先，为「肾虚栗要」之说所本；粳米益气止烦、和胃气、长肌肉；排骨补中益气、益髓养骨；红枣补中养脾、益气生津；姜片温中醒脾。全方补而不滞、温而不燥，作早餐或晚餐皆宜，尤宜小儿发育与中老年腰膝无力者长期食用。惟板栗壅气、易饱腹，须煮熟适量。","blocks":[{"type":"table","caption":"板栗排骨粥食材配伍与作用","head":["食材","用量","作用"],"rows":[["鲜板栗","150 g","甘温，补肾强腰、益气厚肠胃"],["猪排骨","200 g","甘平，补中益气、益髓养骨"],["粳米","60 g","甘平，益气止烦、和胃气、长肌肉"],["红枣","4 枚","甘温，补中养脾、益气生津"],["生姜","3 片","辛温，温中醒脾，矫肉腥"]]},{"type":"paragraph","text":"此粥之要，首在处理板栗。鲜板栗以质坚者为佳，用十字刀在壳面划开深纹，入沸水煮三分钟，剥壳时壳与衣即随热水一搓而落，露出完整栗肉，此法比生剥省力得多。剥好的栗肉仍有一层黄衣者，富含单宁而涩口，宜一并搓去；若脾胃虚弱者嫌其涩而不化，可保留薄衣煮粥，只是味略涩。排骨先焯水去血沫，粳米淘净后与栗肉、排骨、红枣、姜片同入锅，一次加足水约一千毫升；大火煮沸转小火慢煮四十五分钟，中间搅拌两次以防粘底，直煮到米粒开花、粥面起稠、栗肉酥而不散为度。盐于起锅前放入，量宜轻，一克足矣。栗粥颗粒粗、饱腹力强，忌再配他物过量。"},{"type":"paragraph","text":"「肾虚栗要」是中医食养之通说，其理在于栗性甘温而质润，入脾肾二经：补肾气以强腰膝，益脾气以厚肠胃，故《饮膳正要·果品》言其「主益气，厚肠胃，补肾虚」。然单食栗则「炒食，壅人气」，易致脘腹胀闷、便涩，故本方以粳米为载体，取其「主益气，止烦，止泄，和胃气，长肌肉」之功，令栗之补赖谷气而化，不至于滞胃；排骨血肉有情，益髓养骨，与栗共助其补肾强腰之效；红枣补中养脾、益气生津，使脾气得充而生化有源，兼调和栗之生涩；姜片辛温醒脾，既助运化，又矫排骨之腥。四味合参，脾肾同补而以肾为著，气血兼顾而不壅滞，是老少咸宜的家常补益粥。"},{"type":"paragraph","text":"食用建议：作早餐或晚餐主食，每次一碗（约二百五十毫升），连食两至三月为度；中老年与恢复期者每日一次为佳，小儿可三日一次，食量减半。食用时宜配清炒时蔬一小碟以助运化，忌与生冷瓜果同餐。服用期间饮食宜定时定量，晚餐不宜过饱以免栗之壅气加重腹胀；可配合每日摩腹三百圈、揉足三里与悬灸关元各十分钟，以助脾肾运化。若见食后腹胀、嗳气明显，为栗量偏多或脾胃尚弱，应减量并加陈皮三克同煮；若见大便干涩，可加火麻仁十克（须医师指导）或增饮温水。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚弱、食少便溏者初食宜减量，栗壅气滞胃，多食则脘腹胀满、大便干涩。《饮膳正要·菓品》明载栗「炒食，壅人气」，故本方必以水煮为法，忌干炒即食，亦忌与牛肉同食。痰湿壅盛、舌苔厚腻者不宜，恐助湿。糖尿病患者须注意板栗与粳米皆为淀粉类，须计入主食总量并相应减米，血糖控制不佳者少食。高尿酸血症、痛风者排骨汤与粥嘌呤偏高，量宜减并多饮汤。高脂血症者注意排骨肥瘦，选用纯瘦部位。胆囊疾病患者慎用油腻之汤。婴幼儿与消化功能弱者不宜多食。孕妇可食，但须注意板栗之壅气，不宜过量。凡对栗子、猪肉过敏者禁食。服用期间若同时服用中药，须告知医师并遵医嘱，忌与萝卜同食。食疗不能替代药物治疗，顽固腰膝疼痛须经骨科与中医科联合评估。"},{"type":"keypoints","title":"掌握要点","items":["板栗划十字煮后剥壳搓衣，省力且不伤手","以粳米为载体，令栗之补不致壅滞","小火慢煮四十五分钟，忌大火猛滚","食后腹胀者减量并加陈皮同煮","必以水煮为法，忌炒食，忌与牛肉同食"]},{"type":"quote","text":"栗 味鹹、溫、無毒。主益氣，厚腸胃，補腎虛，炒食，壅人氣。","source":"《饮膳正要·卷三·果品》"}]},{"id":"qizao-zhugan-tang","title":"芪枣猪肝汤","subtitle":"益气养血，补肝明目","category":"药膳方","tags":["益气养血","补肝","明目","药膳汤"],"meta":[{"label":"适用人群","value":"气血不足、肝血亏虚见视物昏花、眼睛干涩、面色萎黄、头晕心悸、爪甲不荣者；亦适合贫血倾向、化疗后或长期用眼过度者作辅助调养。肝火旺、阴虚火旺者不宜。"},{"label":"主要功效","value":"益气健脾、养血补肝、明目。用于气血亏虚、肝血不足之目昏、眩晕、面色萎黄。"},{"label":"食材组成","value":"黄芪 15 g，红枣 6 枚，猪肝 100 g，枸杞 10 g，生姜 3 片，料酒 10 mL，盐 1 g"},{"label":"制作方法","value":"黄芪、红枣先煮 20 分钟取汁；猪肝切薄片以料酒抓洗去腥，沸水汆烫变色即捞出；合药汁煮 5 分钟，加枸杞、盐调味。"},{"label":"食用注意","value":"猪肝为动物内脏，含胆固醇与嘌呤较高，高脂血症、痛风者慎食；肝硬化、严重肝肾功能不全者须遵医嘱；每两周一次为度，不宜常食。"}],"image":"","imageHint":"猪肝","summary":"芪枣猪肝汤以黄芪、红枣益气生血，配猪肝以脏补脏，专为气血不足兼肝血亏虚者而设。黄芪甘微温，补气升阳、固表，资气血生化之源；红枣甘温，补中益气、养血安神；猪肝味甘性平，《食疗本草》谓猪肚可「主暴痢虚弱」，猪肝则补肝明目、养血，为「以脏补脏」之典范；枸杞滋补肝肾、益精明目，与猪肝相配，明目之力愈强。全方益气与养血并重，最宜视物昏花、面色萎黄者。惟猪肝胆固醇与嘌呤皆高，不宜常食。","blocks":[{"type":"table","caption":"芪枣猪肝汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["黄芪","15 g","甘微温，补气升阳、固表止汗，资生化之源"],["红枣","6 枚","甘温，补中益气、养血安神"],["猪肝","100 g","甘平，以脏补脏，补肝明目、养血"],["枸杞","10 g","甘平，滋补肝肾、益精明目"],["生姜","3 片","温中散寒、醒脾，矫肝腥"],["料酒","10 mL","行气散寒、矫味去腥"]]},{"type":"paragraph","text":"此汤最讲究「肝要汆、不要煮」。黄芪与红枣先入锅加水约六百毫升，大火煮沸转小火煮二十分钟，滤取药汁，此为「先煮取汁」之法，令气药先行而药性清灵。猪肝处理是成败关键：取新鲜猪肝约一百克，用流水冲洗干净，切成薄片（不宜过薄，否则汆煮即碎），加料酒与少许姜汁抓匀腌十分钟，再用清水冲净血水。锅中水烧至微沸（九成热、边缘起小泡为度），下猪肝片汆三十至四十秒，见其全部转为灰褐、卷曲即迅速捞出，沥干置入汤碗——切不可在沸汤中久煮，久煮则肝质变老、腥气尽出且营养流失。最后将滚烫的药汁冲入碗中，稍停一分钟使猪肝熟透，再加枸杞与盐调味。猪肝每两周食一次即可，不宜频食。"},{"type":"paragraph","text":"肝藏血而主明目，肝血充足则目得所养而视物清晰；然血之生化在脾，气之推动在阳，故单纯补血之品难以速效，须益气以生血，气血同补方为正法。黄芪甘微温，为补气升阳、固表之要药，气充则血有所生，正合「气能生血」之理；红枣甘温，补中益气、养血安神，助黄芪补气之力并养血；猪肝乃血肉有情之品，取其「以脏补脏」之义，直入肝经而补肝血、养眼目，《食疗本草·卷上·豬》条目下「肚：主暴痢虚弱」，本经家亦以猪肝为补肝明目之要品；枸杞甘平，滋补肝肾、益精明目，与猪肝相伍，肝肾同补而明目之功愈验；生姜、料酒行散助运并矫其腥。全方气能生血、肝肾同调，是「肝血不足目不明」者的对证之膳。"},{"type":"paragraph","text":"食用建议：每两周一次为宜，作为调补而非日常菜蔬；每次饮汤约二百毫升，食猪肝三十至五十克，连服三至四次为一疗程。若以明目为主要诉求，可每两周一次连服三月，并配合每日闭目转睛、远眺绿处与按揉睛明、攒竹、风池诸穴；日常用眼须每四十分钟休息十分钟，切忌久视伤血。饮食上宜多食动物肝脏、瘦肉、绿叶蔬菜与黑芝麻、红枣；忌熬夜（肝藏血，久卧伤血亦耗肝血），忌酗酒与辛辣煎炸。若面色转为红润、视物较前清晰，为气血渐充之象；若出现口干、苔黄、胁肋胀痛等症，当停服并请医师重新辨证。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"肝火旺、目赤肿痛、口苦胁痛者禁服，肝经实热者不宜温补滋腻；阴虚火旺、潮热盗汗、舌红少苔者亦不宜。感冒发热、咽喉肿痛、食欲不振期间停服。胆囊炎、胆石症、胰腺炎、严重高脂血症与高尿酸血症者慎食猪肝，其胆固醇与嘌呤均高，服量宜减并去浮油。肝硬化、严重肝肾功能不全者，须经医师评估后方可用本品。痛风急性期禁食。过敏体质者须注意猪肝为易致敏食物，首次少量试食。对猪肝、枸杞过敏者禁食。孕妇可食但须控制次数与用量。服用期间忌与萝卜同食；若同时服用抗凝药或降糖药，须告知医师。本方为食疗调补，不替代贫血、甲状腺或眼病的正规诊疗，具体用量须遵医嘱。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["黄芪红枣先煮取汁，气药先行","猪肝切薄片、汆烫变色即捞，忌久煮","每两周一次为度，不可常食","配合闭目转睛与充足睡眠方能见效","高脂、痛风、肝病者须慎用并遵医嘱"]},{"type":"quote","text":"棗 味甘、無毒。主心腹邪氣，安中養脾，助經脉，生津液。","source":"《饮膳正要·卷三·果品》"}]},{"id":"maidong-yuzhu-zhou","title":"麦冬玉竹粥","subtitle":"养阴润肺，生津止渴","category":"药膳方","tags":["养阴","润肺","生津","药膳粥"],"meta":[{"label":"适用人群","value":"肺胃阴虚见干咳少痰、咽干口渴、劳嗽痰血、胃阴不足之饥不欲食、大便干结者；亦适合秋燥或久病后津液亏耗者。痰湿壅盛、脾胃虚寒、便溏者不宜。"},{"label":"主要功效","value":"养阴润肺、生津止渴、益胃和中。用于肺胃阴虚之燥咳、口渴、干呕、便秘。"},{"label":"食材组成","value":"麦冬 8 g（目录外，须医师指导），玉竹 10 g，淮山药 20 g，粳米 60 g，南沙参 6 g（目录外），冰糖少许"},{"label":"制作方法","value":"麦冬、玉竹、沙参与山药同煮 25 分钟取汁，滤去药渣，滤液加粳米小火煮 30 分钟成粥，按口味加冰糖。"},{"label":"食用注意","value":"麦冬、沙参均为目录外药材，用作食疗须经中医师指导；本方甘寒滋润，脾胃虚寒、痰湿、便溏者禁服；畏寒肢冷、外感风寒者停用。"}],"image":"","imageHint":"麦冬","summary":"麦冬玉竹粥是润养肺胃阴分的经典药粥，取沙参麦冬汤之意而化裁为食疗。麦冬甘微苦微寒，养阴生津、润肺清心，《食疗本草》于天门冬条下记其「补虚劳，治肺劳，止渴，去热风」；玉竹甘微寒，养阴润燥、生津止渴，长于养胃阴；南沙参养阴清肺、益胃生津；淮山药补脾养胃，制寒凉而助运；粳米益气止烦、和胃长肌肉，为诸阴药之载体。全方甘寒滋润而不伤胃，最宜秋燥干咳与胃阴不足者长期调食，然脾胃虚寒者当忌。","blocks":[{"type":"table","caption":"麦冬玉竹粥食材配伍与作用","head":["食材","用量","作用"],"rows":[["麦冬","8 g","甘微苦微寒，养阴生津、润肺清心（目录外，须医师指导）"],["玉竹","10 g","甘微寒，养阴润燥、生津止渴"],["南沙参","6 g","甘微寒，养阴清肺、益胃生津（目录外）"],["淮山药","20 g","甘平，补脾养胃、生津，制寒凉"],["粳米","60 g","甘平，益气止烦、和胃气，载药下行"],["冰糖","少许","润肺生津调味（糖尿病者省）"]]},{"type":"paragraph","text":"此粥须「先煎取汁，后煮成粥」，两步不可颠倒。第一步：麦冬、玉竹、南沙参、淮山药（切块）同入砂锅，加水约七百毫升，大火煮沸转小火煎煮二十五分钟，用滤网滤去药渣，得清亮药汁约四百五十毫升。第二步：将药汁重新倒入锅中，加淘净的粳米，小火慢煮三十分钟至米粒开花、粥汁黏稠。冰糖须待粥温降至六十度以下再加入，糖在高温中易焦化，且会破坏部分养阴之性。若为赶时间，可用破壁机将药材与粳米同打成细浆再煮沸五分钟，但须注意控制火力以免糊底。成品为半流质，色微白而清亮，口感微甘。以温食为宜，早餐或午后加餐皆可，每次一碗。"},{"type":"paragraph","text":"肺为娇脏，喜润恶燥；胃为水谷之海，其阴亦须濡养。燥热伤津则肺失濡润而干咳少痰，胃失津养则饥不欲食、口渴干呕、大便燥结。麦冬甘微苦而微寒，入肺胃心经，养阴生津、润肺清心，为润养肺胃之要药，《食疗本草·卷上·天门冬》条下称天门冬「补虚劳，治肺劳，止渴，去热风」，麦冬与之功类而更清润；玉竹甘微寒，长于养阴润燥、生津止渴而益胃，是「养胃阴」之妙品；南沙参甘微寒，养阴清肺而兼益胃，与麦冬、玉竹同为清养肺胃之配；淮山药甘平，补脾养胃、生津益肺，于大队寒凉滋润之中，培土以固本，并制其寒；粳米为谷，《饮膳正要·米谷品》称其「主益气，止烦，止泄，和胃气，长肌肉」，以甘缓之性载药下行、调和中焦，是本方能使寒凉药不伤胃的关键。"},{"type":"paragraph","text":"食用建议：每日或隔日一剂，作早餐或午后加餐，每次一碗（约二百五十毫升），秋分至立冬之间为最合时令，宜连服一至二月为度。若以燥咳为主，可加百合十克同煮；若以胃阴不足、食少干呕为主，可加石斛六克（须医师指导）；若大便干结明显，可加火麻仁十克（须医师指导）。食用期间饮食宜多汁多润，梨、百合、银耳、鸭肉、牛奶之类为宜，忌辛辣煎炸、烧烤、火锅与烈酒；每日饮水不少于二千毫升，且宜小口频饮。配合上可每日以指腹按揉太溪、照海、三阴交各一分钟，并早睡以养阴；工作久坐空调环境中者，尤须定时起身活动与补水。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒肢冷、大便溏泄清稀者禁服，麦冬、玉竹、沙参性寒滋润，寒凝伤脾而便溏者服之必加腹泻。痰湿壅盛、舌苔厚腻者不宜，恐滋腻助湿。风寒感冒、外感未解之咳嗽发热者停服，忌闭门留寇。孕妇慎用，须经医师评估；哺乳期妇女可食但不宜过量。凡对沙参、麦冬、玉竹过敏者禁食。糖尿病患者须去冰糖，并将粳米计入主食总量。脾虚痰湿之小儿不宜久服。服药期间忌与萝卜同食；本方所含麦冬、沙参均不在国家《既是食品又是药品的物品名单》之内，属目录外药材，用作食疗必须经中医师辨证指导，剂量与疗程遵医嘱；亦不宜与藜芦同用（十八反：藜芦反诸参），服药期间须避免与含藜芦的成药同服。食疗不能替代药物治疗，持久咳嗽须行胸片与专科检查。"},{"type":"keypoints","title":"掌握要点","items":["先煎取汁，后煮成粥，两步不可颠倒","粳米为载药之谷，是寒凉药不伤胃的关键","冰糖待降温至六十度以下再加","秋分至立冬之间食用最合时令","麦冬、沙参为目录外药材，须遵医嘱且忌与藜芦同用"]},{"type":"quote","text":"肺病禁食苦，宜食小麥、羊肉、杏、薤之類。","source":"《饮膳正要·卷二·五味偏走》"}]},{"id":"yiner-xueli-geng","title":"银耳雪梨羹","subtitle":"润肺止咳，生津润燥","category":"药膳方","tags":["润肺","止咳","润燥","甜羹"],"meta":[{"label":"适用人群","value":"秋燥伤肺、燥热伤津见干咳少痰、咽干咽痛、声音嘶哑、口干口渴、鼻腔干燥、皮肤干涩者；亦适合久病体虚、放疗后津液亏损者作日常滋阴之膳。痰湿、脾胃虚寒者不宜。"},{"label":"主要功效","value":"养阴润肺、生津止咳、润燥利咽。用于燥热伤肺之干咳、咽痛、口渴。"},{"label":"食材组成","value":"银耳 15 g，雪梨 1 个（约 300 g），百合 10 g，枸杞 8 g，冰糖 20 g（糖尿病者减半）"},{"label":"制作方法","value":"银耳冷水泡发两小时，撕小朵去黄蒂；梨去皮切块保留梨核同煮；加水 800 mL 大火煮沸转小火炖 60 分钟至出胶，加百合枸杞再煮 10 分钟。"},{"label":"食用注意","value":"银耳须充分泡发并撕小朵，未泡发透易致消化不良；脾胃虚寒、痰湿者忌食，冰糖亦宜减量；梨核不可食，须去之。"}],"image":"","imageHint":"银耳","summary":"银耳雪梨羹是最经典的润燥止咳甜羹，以银耳、雪梨为主料，配百合、枸杞与冰糖。银耳甘淡平，润肺生津、益气养阴，《食疗本草·卷上·木耳》谓木耳「利五脏，宣肠胃气拥」，其胶质能润燥；雪梨甘寒，《饮膳正要·果品》称其「主热嗽，止渴，疏风，利小便」，清热润肺、止咳生津；百合甘微寒，养阴润肺、清心安神；枸杞滋补肝肾、益精明目；冰糖润肺生津。全方甘凉清润，最宜秋燥干咳与咽干口渴者。惟性寒凉，脾胃虚寒与痰湿者当忌。","blocks":[{"type":"table","caption":"银耳雪梨羹食材配伍与作用","head":["食材","用量","作用"],"rows":[["银耳","15 g","甘淡平，润肺生津、益气养阴"],["雪梨","1 个","甘寒，清热润肺、止咳生津"],["百合","10 g","甘微寒，养阴润肺、清心安神"],["枸杞","8 g","甘平，滋补肝肾、益精明目"],["冰糖","20 g","甘平，润肺生津、调味（糖尿病者减半）"]]},{"type":"paragraph","text":"熬此羹的关键在「泡、撕、久炖、留核」。银耳须用冷水泡发二至三小时，中途换水两次，泡至耳片完全舒展、呈半透明淡黄色为止；泡发后须剪去黄色蒂根，并撕成指甲盖大小的小朵——撕得碎，胶质才能充分释出，羹才够稠；整片下锅则久煮不出胶。雪梨削皮切块，梨核切下另置，因梨核性凉而力专，煎汤时同煮能增润肺止咳之效，但成羹后必须取出弃去，切勿误食。配料入锅后一次加足水约八百毫升，大火煮沸转最小火，保持微沸不翻滚，炖足六十分钟，中途不可加冷水；至银耳出胶、汤汁稠如乳即可。百合与枸杞于起锅前十分钟投入，枸杞久煮即烂而味酸。"},{"type":"paragraph","text":"秋燥为病，自外而入，先伤肺津；肺失宣降则干咳少痰、咽干而痒、声音嘶哑。银耳甘淡而平，色白入肺，润肺生津、益气养阴，其所含胶质在煮制后释放，黏稠护于咽喉，是燥润之妙品；雪梨甘寒多汁，《饮膳正要·果品》谓其「主热嗽，止渴，疏风，利小便」，清热润肺、生津止渴，二者相合，一润一清，标本兼顾；百合甘微寒，养阴润肺而清心安神，兼解秋燥之烦躁；枸杞滋补肝肾、益精明目，肝肾阴充则肺阴有源，且久服眼干亦得缓解；冰糖甘平，润肺生津，兼为调味之使。全方甘凉轻润，最宜秋分后至小雪间燥气当令之时。"},{"type":"paragraph","text":"食用建议：每日或隔日一碗，作早餐、午后点心或晚餐后甜品皆可，每次约二百五十毫升，温食为佳。秋分至立秋之间连服两至三周为度；若咽干口燥明显而无咳嗽者，可去冰糖；若痰多而稀、咳嗽而胸闷者，本方不宜单独使用，须先化痰。食用期间宜多饮温水，忌辛辣烧烤、火锅、煎炸与烈酒，忌冷饮；饮食宜以蒸、煮、炖为法，减少油炸燥烈之品。日常可配合每日按摩迎香穴与搓鼻翼两侧各一分钟，鼻腔干燥者可用生理盐水喷雾。儿童与老人可减冰糖，糖尿病者去冰糖并注意梨与枸杞之糖分，血糖控制不佳者以银耳百合羹替代为宜。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒便溏、大便清稀者禁服，本方甘寒滋润，寒凝伤脾而便溏者服之必加重。痰湿壅盛、舌苔白厚腻、咳嗽痰多者不宜，恐助湿恋邪。风寒咳嗽、痰白清稀而畏寒者停服，忌闭门留寇。糖尿病患者须减冰糖或去之，梨与枸杞含糖较多，每日宜一小碗并计入总糖量，血糖控制不佳者暂不食用。孕妇可食，量宜适中。过敏体质者须注意银耳为真菌类蛋白，可能引起过敏；银耳变质后易滋生细菌而中毒，变质者（发黏、有异味）必须丢弃，绝不可食用。对梨、百合、枸杞过敏者禁食。忌与萝卜同食，忌浓茶同服。本方为食养之法，不能替代对慢性咳嗽、哮喘、肺结核等疾病的诊断与治疗，持久干咳、咯血者当及时就医。食疗调养需数月之功，不能替代药物治疗，剂量与疗程须遵医嘱。"},{"type":"keypoints","title":"掌握要点","items":["银耳泡透撕小朵，方能出胶","梨可留核煎汤，但成羹后必须取出弃去","小火微沸炖足六十分钟，中途不添冷水","秋分至立秋燥气当令时最宜食用","脾胃虚寒与痰湿者禁服，变质银耳必丢弃"]},{"type":"quote","text":"木耳〈寒〉無毒。利五臟，宣腸胃氣擁、毒瓦斯，不可多食。熱發，和蔥豉作羹。","source":"《食疗本草·卷上》"}]},{"id":"shanyao-xiaomi-zhou","title":"山药小米粥","subtitle":"健脾益气，和胃安神","category":"体质食养","tags":["气虚质","健脾益气","粥品","平和"],"meta":[{"label":"适用人群","value":"气虚质见神疲乏力、少气懒言、面色㿠白、语声低微、易出汗、易感冒、饮食偏少、大便溏薄者；亦适合病后、产后恢复期与儿童脾胃虚弱者。"},{"label":"主要功效","value":"健脾益气、和胃和中、固表止汗。用于脾气虚弱的食少、便溏、倦怠乏力与表虚自汗。"},{"label":"食材组成","value":"铁棍山药 100 g，小米 60 g，红枣 4 枚，枸杞 8 g（可加），生姜 1 片（可加）"},{"label":"制作方法","value":"小米淘洗后浸泡 20 分钟；山药去皮切小丁（戴手套），红枣去核撕开；同加水约 900 mL 大火煮沸转小火煮 30 分钟成稠粥，关火前加枸杞即可。"},{"label":"食用注意","value":"山药、小米、大枣、枸杞均在食药物质目录或日常食材范围内，可长期食用；惟脾胃实热、痰湿壅盛、腹胀便秘者宜减量，感冒发热期停服。"}],"image":"","imageHint":"小米","summary":"山药小米粥是调理气虚质最平和、最易坚持的一碗粥。山药甘平，《饮膳正要·菜品》称其「补中益气，治风眩，止腰痛，壮筋骨」，入脾肺肾而补脾为先；小米甘咸微寒，《饮膳正要·米谷品》谓粟米「主养肾气，去脾胃中热，益气」，养胃气而益脾气；红枣补中益气、养血安神，枸杞滋补肝肾。四味皆在食药物质目录之内或为日常谷物，性味平和，适合气虚质者长期日常食用，亦是儿童与病后调理之稳妥之选。惟腹胀便秘、舌苔厚腻者不宜多食。","blocks":[{"type":"table","caption":"山药小米粥食材配伍与作用","head":["食材","用量","作用"],"rows":[["铁棍山药","100 g","甘平，补中益气、健脾养胃、补肾涩精"],["小米","60 g","甘咸微寒，养胃气、益脾气、去脾胃中热"],["红枣","4 枚","甘温，补中益气、养血安神、生津"],["枸杞","8 g","甘平，滋补肝肾、益精明目"],["生姜","1 片","辛温，温中醒脾，制小米之凉"]]},{"type":"paragraph","text":"熬这碗粥看似简单，实有三处讲究。第一，小米须用清水淘洗两遍后浸泡约二十分钟，令米粒吸水而开锅更早、粥更绵；切忌用力搓揉太过，搓过度则米糠尽失、气味全无。第二，山药去皮时戴一次性手套，既防其黏液致皮肤瘙痒，又避免氧化发黑；切小丁而非大块，小丁易煮至酥糯而与米汤融为一体，若用大块则口感粗硬。第三，红枣去核撕开，皮、核同煮则汤味发苦发涩，撕开仅留果肉，甜香方能透出。加水一次约九百毫升，大火煮沸后转小火慢煮三十分钟，中途搅拌两次防糊底，直煮到米油浮面、粥面挂勺为度。枸杞于关火前两分钟投入，久煮则色暗味酸。姜片可依个人寒热取舍，畏寒者留，胃热者去。"},{"type":"paragraph","text":"气虚质之病机，在于元气不足、脏腑功能低下。《灵枢·寿夭刚柔》所谓「形与气相任则寿」，形气俱足方能健康。山药甘平而质润，《饮膳正要·菜品》明载其「补中益气，治风眩，止腰痛，壮筋骨」，既入脾经补脾气以资生化之源，又入肺经补肺气以固卫表，入肾经益肾气而固先天，三脏并调而以补脾为重；小米甘咸微寒，《饮膳正要·米谷品》称粟米「主养肾气，去脾胃中热，益气」，其性甘淡而能养胃气，恰补山药之不足、与之相成；红枣甘温，补中益气、养血安神，为气血生化之资；枸杞甘平，滋补肝肾、益精明目，肝肾得补则元气有根。合而观之，本方不温不燥、不寒不热，以「和」取胜，正合《素问·四气调神大论》「春夏养阳，秋冬养阴」随时调养之旨。"},{"type":"paragraph","text":"食用建议：每日或隔日一餐，以早餐为佳，每次一碗约二百五十毫升，连服一至三月为度；气虚较重者可每日一次早餐食用，且宜长期坚持方见其效。若以改善自汗、易感冒为主，可每周加服玉屏风散类药膳（须医师指导），并配合「避风寒、勤起居、适运动」三事：晨起后以双手搓热敷面、缓行散步二十分钟以助阳气升发；每逢气候变化即时添衣，汗出后不可当风；每周三次快走或八段锦「五劳七伤式」以壮体魄。饮食上宜少食生冷瓜果、冰淇淋与浓茶，晚餐宜七分饱，餐后缓行百步。服用期间如出现口干舌燥、苔黄而干，说明补而碍运，当减量并加少量麦冬同煮。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃实热、脘腹胀满、大便干结、舌苔黄厚者不宜多食，本方甘润滋腻，助滞恋邪。痰湿壅盛、形体肥胖、苔厚腻者减量，山药与小米皆能生湿。风寒感冒发热、外感未解期间停服，恐闭门留寇。糖尿病患者须注意小米与山药皆含淀粉较多，须计入主食总量，血糖控制不佳者减量或改以糙米、燕麦替代，枸杞亦须限食。胃溃疡活动期者慎用山药之涩，胃酸过多者可少放红枣。婴幼儿可作辅食但须捣细去渣，不宜过量。凡对谷物、枸杞过敏者禁食。此方所用药食同源之品皆在国家目录之内，可作长期日常调养；但须重申：食疗不能替代药物治疗，气虚之证当经中医师辨证，气短乏力甚或伴明显消瘦、持续低热者，须及时就医查明病因，勿以食疗延误。"},{"type":"keypoints","title":"掌握要点","items":["小米浸泡二十分钟，山药戴手套切小丁","红枣去核撕开，只留果肉以免汤涩","小火慢煮三十分钟，以米油浮面为度","长期坚持并配合散步、八段锦方能见效","气虚质调理当先辨证，食疗不替代治疗"]},{"type":"quote","text":"粟米 味鹹、微寒、無毒。主養腎氣，去脾胃中熱，益氣。","source":"《饮膳正要·卷三·米谷品》"}]},{"id":"danggui-jitang-wenyang","title":"当归生姜羊肉汤（温阳款）","subtitle":"温阳散寒，益气养血","category":"体质食养","tags":["阳虚质","温阳散寒","补虚","冬令"],"meta":[{"label":"适用人群","value":"阳虚质见畏寒怕冷、手足不温、脘腹冷痛、喜温喜按、精神不振、腰膝酸软、性欲减退、宫寒痛经者；尤宜冬季畏寒明显者及中老年人阳气渐衰者。"},{"label":"主要功效","value":"温阳散寒、补中益气、养血止痛。用于阳虚寒凝之畏寒肢冷、腹中冷痛、痛经。"},{"label":"食材组成","value":"当归 12 g，生姜 20 g，羊肉 500 g，党参 15 g，黄芪 10 g，料酒适量，盐少许"},{"label":"制作方法","value":"羊肉浸泡去血水后焯水；当归、生姜（拍碎）、党参、黄芪装入药包，与羊肉同炖，水没过约 1500 mL，大火煮沸转小火炖 90 分钟，加盐调味。"},{"label":"食用注意","value":"当归仅获准作香辛料与调味品使用，作食疗用药须经中医师辨证指导；本方温热，阴虚火旺、湿热内蕴者禁服；孕妇忌用，忌与韭菜、荞麦同食。"}],"image":"","imageHint":"温阳","summary":"当归生姜羊肉汤（温阳款）是《金匮要略》原方加党参、黄芪而成，专为阳虚质而设。羊肉甘温大热，暖中补虚、益气生肌；生姜辛温，温中散寒、化饮止呕；当归补血活血、止痛；党参补中益气、健脾养血；黄芪补气升阳、固表止汗。加参芪之后，补气之力倍于原方，最宜阳虚兼气虚、畏寒自汗、精神疲乏者。每周食一至两次，立冬至春分间为当令。惟本方温燥力强，阴虚火旺与湿热者禁服，孕妇当忌。","blocks":[{"type":"table","caption":"当归生姜羊肉汤（温阳款）食材配伍与作用","head":["食材","用量","作用"],"rows":[["羊肉","500 g","甘大热，温中补虚、益气生肌"],["生姜","20 g","辛温，温中散寒、化饮止呕"],["当归","12 g","补血活血、止痛，调经"],["党参","15 g","甘平，补中益气、健脾养血"],["黄芪","10 g","甘微温，补气升阳、固表止汗"],["料酒","适量","行气散寒、矫味去腥"],["盐","少许","调味"]]},{"type":"paragraph","text":"此汤为温阳之剂，火候与用量都较寻常食疗为重。羊肉选带骨带筋之处，瘦肉过多则温补不足；切块后冷水浸一小时并换水两次以逼出血水，腥味可去大半；冷水下锅焯烫，撇净浮沫后捞出温水冲净，务使汤清而不浊。当归、生姜拍碎，党参、黄芪与其同装纱布包，可免药渣黏喉；生姜用量二十克，量重方见辛散温通之力，不可减至炒菜之量。加水一次足量约一千五百毫升，大火煮沸加料酒，转小火保持微沸不翻滚，慢炖九十分钟，至骨酥肉烂、汤色棕红微稠为度。出锅取出药包，加盐调味。忌加蒜与辣酱，恐辛散太过反耗气动血。服后若微汗、身轻、暖意持久，则剂量适当；若觉口干烦热，则为温补过度，须停服。"},{"type":"paragraph","text":"阳虚质者，元阳不足、阴寒内盛，故《素问·生气通天论》谓阳气者「一日而主外」，阳不达表则畏寒自汗，阳不温中则脘腹冷痛。羊肉甘而大热，入脾胃肾经，温中补虚而不燥不滞，《饮膳正要·兽品》称其「主暖中，头风，大风，汗出，虚劳，寒冷，补中益气」，是最合阳虚之血肉有情之品；生姜辛温，其「辛能散、温能通」之性，最能温通经脉、逐寒外出，且制羊肉之膻；当归补血活血，为「血虚有寒」而设；党参甘平，补中益气、健脾养血，力缓而持久；黄芪甘微温，补气升阳、固表止汗，令气充则表固而汗自止。合观全方，气血阴阳并顾而以温阳散寒为主轴，正合阳虚质「温补」之大法，较原方更切于气虚兼阳虚之Reality。"},{"type":"paragraph","text":"食用建议：每周一至两次，以立冬至春分为当令；每次连汤带肉约小半碗至一碗，服后微汗为度。若以畏寒为主，可连服十日为一疗程；若以痛经为主，宜于经前七至十日连服四至五次，经期可续服，经后即止。若以自汗乏力为主，宜晨起空腹温服，并在服后避风半个时辰。服药期间忌生冷瓜果、冰饮、寒凉海鲜与冷菜，忌酒，烈酒助热更甚；日常宜温食热饮，每餐不宜过饱，餐后宜缓行。配合上，每日可用艾条温灸足三里、关元、气海各十五分钟，或以双手搓热揉按腰眼与涌泉各百遍；并宜适度进行八段锦「摇头摆尾去心火」「两手攀足固肾腰」二式以助阳气内生。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"阴虚火旺者禁服，症见五心烦热、潮热盗汗、口干咽燥、舌红少苔、遗精者，温补助火。湿热内蕴、舌苔黄厚、脘腹痞满、口苦纳呆者不宜，恐助湿壅滞。实热证、痰热壅盛而咳黄痰者禁服。外感发热、咽喉肿痛、疮疡初起期间停服，忌闭门留寇。孕妇禁用，当归、川芎类活血走窜之品有动胎之虞，且温补恐助热动血；产后恶露未净者亦当避之。痛风、高尿酸血症者注意浓肉汤嘌呤偏高，不宜多饮。高血压、心衰、水肿者宜少盐少汤并遵医嘱。儿童不宜，体质偏热者亦当慎。对羊肉、生姜、党参过敏者禁食。配伍禁忌：羊肉忌与韭菜、荞麦同食，亦忌与鱼膾、酪同食；半夏、菖蒲服药期间忌食羊肉；本方含当归，仅获准作香辛料与调味品使用，作食疗用药须经中医师辨证指导，剂量与疗程遵医嘱。食疗不能替代药物治疗，阳虚之证当经辨证。"},{"type":"keypoints","title":"掌握要点","items":["加党参黄芪，补气之力倍于仲景原方","生姜用量宜重，羊肉必焯水去沫","小火长炖九十分钟，服后微汗为度","立冬至春分为当令，每周至多两次","阴虚火旺、湿热、孕妇禁服，忌与韭菜荞麦同食"]},{"type":"quote","text":"羊肉∶溫。主風眩瘦病，小兒驚癇，丈夫五勞七傷，臟氣虛寒。","source":"《食疗本草·卷上·羊》"}]},{"id":"yiner-baihe-geng","title":"银耳百合羹","subtitle":"养阴润肺，清心安神","category":"体质食养","tags":["阴虚质","养阴润肺","安神","甜羹"],"meta":[{"label":"适用人群","value":"阴虚质见面色潮红、手足心热、口燥咽干、干咳少痰、盗汗、失眠多梦、腰膝酸软、大便干结者；亦适合秋燥伤肺与用嗓过度者长期调养。"},{"label":"主要功效","value":"滋阴润肺、清心安神、生津润燥。用于肺阴不足之燥咳咽干与心阴不足之失眠多梦。"},{"label":"食材组成","value":"银耳 15 g，百合 15 g，莲子 15 g（去心），枸杞 8 g，冰糖 15 g（糖尿病者减半）"},{"label":"制作方法","value":"银耳冷水泡发两小时撕小朵去黄蒂；与莲子同炖 50 分钟，后下百合续煮 15 分钟，加枸杞与冰糖再煮 3 分钟即成。"},{"label":"食用注意","value":"银耳为食用菌类食材，不在国家食药物质目录内，作日常食材无碍，若用于治疗须遵医嘱；脾胃虚寒、痰湿者忌，冰糖亦须减量。"}],"image":"","imageHint":"百合","summary":"银耳百合羹以银耳、百合、莲子三味养阴之品相配，专为阴虚质而设。银耳甘淡平，润肺生津、益气养阴，其胶质黏润咽喉，为燥证之妙品；百合甘微寒，入心肺经养阴润肺、清心安神，《食疗本草·卷上》谓其「蒸过，蜜和食之。作粉尤佳」；莲子去心，补脾止泻、养心安神、益肾固精；枸杞滋补肝肾、益精明目；冰糖润燥调味。全方上润肺、中养心、下滋肾，兼以莲子护脾，最宜阴虚质长期调食。惟其性寒凉，脾胃虚寒与痰湿者当忌。","blocks":[{"type":"table","caption":"银耳百合羹食材配伍与作用","head":["食材","用量","作用"],"rows":[["银耳","15 g","甘淡平，润肺生津、益气养阴"],["百合","15 g","甘微寒，养阴润肺、清心安神"],["莲子（去心）","15 g","甘平，补脾止泻、养心安神、益肾固精"],["枸杞","8 g","甘平，滋补肝肾、益精明目"],["冰糖","15 g","润肺生津、调味（糖尿病者减半）"]]},{"type":"paragraph","text":"熬羹之要，首在银耳。干银耳须以冷水泡发二至三小时，中途换水两次，泡至耳片完全舒展、手感柔软不硬刺，剪去黄色蒂根并撕成米粒大小的小朵——撕得越碎，胶质释出越快，羹才够稠；整片入锅则煮两小时亦不出胶。其次是下料次序：银耳与莲子同入锅，因二者皆须久煮方出味，加水约一千毫升，大火煮沸转最小火炖五十分钟；百合质地较脆，久煮则烂而发苦，故于起锅前十五分钟下锅；枸杞更须最后三分钟投入，久煮则色暗味酸。冰糖待羹温降至六十度以下再加，方不焦苦且不损其润。成品以羹体黏稠、晶亮挂勺为度，每次一小碗（约二百五十毫升），温食为佳。"},{"type":"paragraph","text":"阴虚质之要，在于阴液不足、虚热内生。《素问·生气通天论》以阳气论之，《素问·阴阳应象大论》则言「阴虚则热」，其治当壮水之主、以制阳光。银耳甘淡而平，入肺胃经，润肺生津、益气养阴，其胶质黏护咽喉，是燥热伤肺后生津之妙品；百合甘微寒，入心肺经，养阴润肺而清心安神，《食疗本草·卷上》记其「主心急黄……蒸过，蜜和食之，作粉尤佳」，可见其甘润之性；莲子去心后甘平，补脾止泻、养心安神、益肾固精，于大队滋腻之中独任「运」字，既护中焦又助安神；枸杞甘平，滋补肝肾、益精明目，肝肾阴充则肺阴有源，母能及子；冰糖甘平，润肺生津，兼为调味之使。全方三焦并养、标本兼顾，最宜阴虚质之干咳、盗汗、失眠与便干。"},{"type":"paragraph","text":"食用建议：每日或隔日一碗，以晚餐后或睡前一时为佳（安神之效得于夜静），连服一至三月为度。日常还须配合根本调理：每日睡足子时之前入眠，睡眠是养阴第一要务；饮食宜多汁多润，梨、百合、银耳、鸭肉、牛奶、黑芝麻为佳，忌辛辣烧烤、煎炸与烈酒；每日饮水不少于二千毫升，小口频饮，不等口渴方饮。若出现口干咽干而无咳嗽者，可去冰糖；若大便干结明显，宜加火麻仁十克（须医师指导）；若失眠较重，可加酸枣仁十克（须医师指导）以宁心安神。配合导引，每日午后按揉太溪、三阴交、照海各一分钟，并以两掌搓热敷腰骶部百遍，可助阴精内充。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒肢冷、大便溏泄清稀者禁服，百合、银耳、莲子皆寒凉滋润，服之必加腹泻与脘腹不适。痰湿壅盛、舌苔白厚腻、纳呆脘痞者不宜，恐滋腻助湿。风寒咳嗽、痰白清稀而畏寒者停服，忌闭门留寇。糖尿病患者须减冰糖或去之，莲子、银耳、百合皆含糖，须计入总量；血糖控制不佳者宜改为银耳羹不加百合莲子糖。孕妇可食，量宜适中。银耳为真菌类蛋白，可能引起过敏，变质者（发黏、异味、色变）必须丢弃绝不可食；对银耳、百合、莲子过敏者禁食。服药期间忌与萝卜同食，忌浓茶同服。须说明：银耳与百合、莲子、枸杞虽多在食药物质目录之内（银耳为食用菌类食材，不在目录之内），作日常食材食用无碍，但若作治疗性调补，仍须经中医师辨证指导，剂量与疗程遵医嘱；食疗不能替代药物治疗，持久盗汗、长期失眠、慢性干咳者当及时就医排查器质性病因。"},{"type":"keypoints","title":"掌握要点","items":["银耳泡透撕小朵，方能出胶","莲子先炖、百合后下、枸杞最后、冰糖降温加","阴虚之要在于睡眠，务必子时前入眠","大便干结可加火麻仁，失眠重可加酸枣仁（须医师指导）","脾胃虚寒与痰湿者禁服，变质银耳必丢弃"]},{"type":"quote","text":"山丹根 味甘、平、無毒。主邪氣腹脹，除諸瘡腫。（一名百合。）","source":"《饮膳正要·卷三·菜品》"}]},{"id":"yiyi-chixiaodou-zhou","title":"薏苡赤小豆粥","subtitle":"健脾利湿，利水消肿","category":"体质食养","tags":["痰湿质","利湿","消肿","粥品"],"meta":[{"label":"适用人群","value":"痰湿质见体形肥胖、腹部松软、面色晦黄、头身困重、嗜睡懒言、胸闷脘痞、痰多色白、大便溏而不爽、下肢浮肿者；尤宜夏秋湿重之时。"},{"label":"主要功效","value":"健脾渗湿、利水消肿、清热排脓。用于脾虚湿盛之肢体困重、痰饮、浮肿与疮疡。"},{"label":"食材组成","value":"炒薏苡仁 40 g，赤小豆 30 g，粳米 50 g，芡实 10 g，陈皮 3 g（可加）"},{"label":"制作方法","value":"赤小豆与薏苡仁提前浸泡 2 小时；与粳米、芡实同加水 1000 mL，大火煮沸转小火煮 45 分钟成粥，起锅前加陈皮丝与盐。"},{"label":"食用注意","value":"薏苡仁性微寒，脾胃虚寒、便溏者须炒用并减量，孕妇慎用；「有茯苓勿食醋」，服食期间忌醋；勿与尿素类利尿药同用。"}],"image":"","imageHint":"赤豆","summary":"薏苡赤小豆粥为痰湿质专设，是《饮膳正要》米谷品所载赤小豆「下水、排脓血、去热肿」之功与薏苡仁「健脾渗湿」之用的合方。赤小豆甘酸平，健脾利水、排脓消肿；炒薏苡仁甘淡微寒，健脾渗湿、利水消肿；芡实益肾固精、补脾止泻，扶正而不留邪；陈皮理气燥湿，防渗利之品壅遏；粳米益气和胃，为载药之谷。全方淡渗分利而不伤正，最宜夏秋湿盛、体形偏胖而困重乏力者长期调食。惟其性偏凉，脾胃虚寒者须炒用减量。","blocks":[{"type":"table","caption":"薏苡赤小豆粥食材配伍与作用","head":["食材","用量","作用"],"rows":[["炒薏苡仁","40 g","甘淡微寒，健脾渗湿、利水消肿"],["赤小豆","30 g","甘酸平，下水排脓、去热肿、止泻痢"],["粳米","50 g","甘平，益气止烦、和胃气、长肌肉"],["芡实","10 g","甘涩平，益肾固精、补脾止泻"],["陈皮","3 g","辛苦温，理气燥湿、开胃化滞"],["盐","少许","调味"]]},{"type":"paragraph","text":"此粥用料皆须预先处理，否则无效。赤小豆颗粒紧实，须冷水浸泡二小时以上，泡至皮色稍深、手捻即碎为佳；浸泡之水倒弃不用，因其中含淀粉与杂质。薏苡仁则须先干锅小火炒至微黄透香——此即炒薏苡仁，炒后寒性减而健脾之性增，是「痰湿质可用而脾胃不伤」的关键，不可直接用生薏苡仁。煮时将赤小豆、炒薏苡仁、粳米、芡实同入锅，一次加水约一千毫升，大火煮沸转小火慢煮四十五分钟，中途搅拌两次防黏底，直煮至豆子酥烂、米粒开花、粥汁黏稠为度。陈皮于起锅前切细丝撒入，略煮一分钟即可，久煮则苦。盐宜少，痰湿者本就水湿偏盛，重盐不利。"},{"type":"paragraph","text":"痰湿质之成，因脾失健运而津液不布，聚湿为痰；《素问·至真要大论》云「诸湿肿满，皆属于脾」，故治痰湿必先健脾。薏苡仁甘淡微寒，淡能渗湿，故能利水而不伤阴；又入脾经，故能健脾而不燥烈，此正是「利湿不伤正」之关键，《食疗本草·卷上·薏苡仁》称其「去干湿香港脚」，正取其渗湿之能。赤小豆甘酸平，《饮膳正要·米谷品》谓其「主下水，排脓血，去热肿，止泻痢，通小便」，其利水之力较薏苡仁为峻，故与之相配，一缓一急，一健脾一利水。粳米为谷，《饮膳正要》称其「主益气，止烦，止泄，和胃气，长肌肉」，益气以运脾而助渗利；芡实甘涩，益肾固精、补脾止泻，为久病体虚者扶正，兼防渗利太过；陈皮辛苦温，理气燥湿，使气行则水行，防大队淡渗之品壅遏气机。"},{"type":"paragraph","text":"食用建议：大暑至白露之间为最合时令，可每日或隔日一餐，以午餐为佳，每次一碗约二百五十毫升，连服一至三月为度。若为下肢浮肿明显者，可连服十日为一疗程，并须同时限盐（每日不超过五克）、少饮水于夜间、抬高下肢。服药期间饮食宜清淡少油，戒肥甘厚味、甜腻糕点、奶茶与冰饮，忌酒；每餐宜七分饱，晚餐尤宜清淡，餐后宜缓行二十分钟以助运化。运动是痰湿质调理的关键一环，宜每周四次、每次四十分钟以上的快走、慢跑或游泳，出汗至微热而无大汗为度，出汗后及时擦干更衣，忌当风受凉。若服后见口干、便秘，为渗利伤津之象，应减量并加少许粳米与山药同煮以复其阴。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒便溏、大便清稀者须炒用薏苡仁并减量三分之一，或加生姜三片同煮，忌纯用生薏苡仁。阴虚津亏、大便干结者不宜，淡渗利湿易伤阴，症见口干咽燥、五心烦热者当停用。孕妇慎用，薏苡仁有滑利之性，妊娠期用量宜减并经医师评估；哺乳期妇女亦不宜过量。泌尿系统感染、肾炎、水肿须在医师指导下使用，不可自行长期服用。痛风、高尿酸血症者须注意，薏苡仁与赤小豆均非高嘌呤而可适量，然须多饮水以利排泄。糖尿病患者须计入粳米与芡实之淀粉总量。婴幼儿不宜。对薏苡仁、赤小豆、芡实过敏者禁食。服药食忌：《饮膳正要·服药食忌》明载「有茯苓勿食醋」，本方芡实与之同源，故服食期间及前后一二日忌醋及醋制品、含醋饮料；亦忌与萝卜同食。利尿药使用者须避免与本方同服，以防电解质紊乱。食疗不能替代药物治疗，明显水肿、肥胖者当经中医辨证与相关检查。"},{"type":"keypoints","title":"掌握要点","items":["薏苡仁必须炒用，以减寒性增健脾","赤小豆浸泡二小时以上，方能煮酥","陈皮起锅前撒入，略煮即止，久煮则苦","限盐、控糖、多运动，三者缺一不可","服食期间忌醋、忌萝卜，孕妇慎用"]},{"type":"quote","text":"赤小豆 味甘、酸、平、無毒。主下水，排膿血，去熱腫，止瀉痢，通小便。","source":"《饮膳正要·卷三·米谷品》"}]},{"id":"lvdou-baihe-zhou-shi-re","title":"绿豆百合粥（湿热款）","subtitle":"清热解毒，养阴润燥","category":"体质食养","tags":["湿热质","清热","解毒","粥品"],"meta":[{"label":"适用人群","value":"湿热质见面目垢秽、口苦口干、脘腹痞闷、肢体困重、午后身热、大便黏滞不爽、小便短黄者；亦适合夏暑湿热并见与痤疮、口舌生疮者。"},{"label":"主要功效","value":"清热解毒、养阴润燥、利湿和中。用于湿热内蕴之口苦烦热、脘痞身重、疮疡。"},{"label":"食材组成","value":"绿豆 40 g，百合 15 g，薏苡仁 15 g，粳米 40 g，莲子心 1 g（可加）"},{"label":"制作方法","value":"绿豆、薏苡仁浸泡 2 小时后与粳米同加水 900 mL，大火煮沸转小火煮 35 分钟至豆烂，下百合续煮 12 分钟，加冰糖少许调味。"},{"label":"食用注意","value":"绿豆不在国家食药物质目录内，作普通食材煮食无碍，若入药须遵医嘱；脾胃虚寒、便溏者忌，冰糖宜省；勿与解药类西药同服。"}],"image":"","imageHint":"绿豆","summary":"绿豆百合粥（湿热款）是湿热质专用的清利之剂。绿豆甘寒，《饮膳正要·米谷品》称其「主丹毒，烦热，和五脏，行经脉」，清热解毒、消暑利湿；百合甘微寒，养阴润肺、清心安神；薏苡仁淡渗健脾利湿，使湿浊从小便而去；粳米益气和胃以护中；莲子心极少量以清心火。合观之，本方清热而不伤阴，利湿而不伤脾，是「湿热质」调理的核心思路——清热与养阴并行、祛湿与健脾兼顾。惟其性寒凉，脾胃虚寒者当忌，服之易伤中阳。","blocks":[{"type":"table","caption":"绿豆百合粥（湿热款）食材配伍与作用","head":["食材","用量","作用"],"rows":[["绿豆","40 g","甘寒，清热解毒、消暑利湿、和五脏"],["百合","15 g","甘微寒，养阴润肺、清心安神"],["薏苡仁","15 g","甘淡微寒，健脾渗湿、利水消肿"],["粳米","40 g","甘平，益气止烦、和胃气"],["莲子心","1 g","苦寒，清心除烦、去暑（量宜极小）"],["冰糖","少许","调味（糖尿病者省，湿热者尤宜省）"]]},{"type":"paragraph","text":"此粥以「清而不伤中」为原则，火候与下料次序均有讲究。绿豆与薏苡仁须冷水浸泡二小时，泡至豆粒发胀、绿豆外皮略松，否则煮之不烂；浸泡水须倒弃。粳米淘净后与绿豆、薏苡仁同入锅，一次加水约九百毫升，大火煮沸后转小火煮三十五分钟，至绿豆开花、豆沙初成；百合质地柔而味清，须在此后十二分钟下锅，久煮则气味散失且质烂；莲子心只取一分，研极细末于起锅前撒入，切不可多，多则苦寒伤胃。冰糖于关火后加或不加——湿热质本不喜甘甜，通常以淡食为佳，若胃中不适可加少许。成粥后放温至不烫口再食，食后以温水漱口。湿热质宜清淡，此粥当配白灼菜蔬，不可佐以油腻荤食。"},{"type":"paragraph","text":"湿热质之因，在于脾失健运而湿浊内生，郁久化热；或嗜食辛辣肥甘、酒酪厚味，湿热相搏，熏蒸肝胆。湿热之邪最易困阻中焦，故调理之法不可一味苦寒直折，须清热与养阴并行、利湿与健脾兼顾。绿豆甘寒，《饮膳正要·米谷品》明载其「主丹毒，烦热，和五脏，行经脉」，清热解毒之力专而能和中，诚为湿热质食疗之佳品；百合甘微寒，《食疗本草·卷上》记其甘平而可「蒸过，蜜和食之」，入心肺经养阴润肺、清心安神，湿热郁蒸最易耗伤阴液，百合正所以养其阴而防苦寒伤津；薏苡仁淡渗，健脾渗湿，使湿浊从小便而去，与绿豆相配，一清热一利湿，分消其邪；粳米益气止烦、和胃长肌肉，为大队寒凉之品护中；莲子心一分，清心除烦、去暑而不伤正。全方寒凉而不伐胃，清利而不伤阴，最合湿热质「清化」之治。"},{"type":"paragraph","text":"食用建议：每日或隔日一餐，以午餐为佳，每次一碗约二百五十毫升，连服一至二月为度；暑热最盛之小暑、大暑、处暑三节气可适当加密至每日一次。服药期间饮食宜清淡而多蔬果，忌辛辣煎炸、烧烤、油腻肥甘、烈酒与啤酒，尤忌火锅与烧烤；每日饮水二千毫升以上，可用淡竹叶、菊花、荷叶泡水代茶（须医师指导者除外），以助清热利尿。起居方面宜晚睡早起，避开正午高温时段外出，避免汗出当风与久居空调之室。若见面垢油腻、痤疮、口舌生疮明显，可加金银花 5 g、连翘 6 g 同煮（须医师指导）；若湿热下注而小便短赤、带下黄稠，可加车前子 10 g（须医师指导）。配合上，每日以掌心搓热揉按曲池、阴陵泉、三阴交各一分钟，可助湿热外达。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒肢冷、大便溏泄者禁服，绿豆、百合、薏苡仁性皆寒凉，服之必伤中阳而加腹泻、脘痛。痰湿壅盛而无热象者不宜，恐寒凉凝滞。阴虚而无湿热者少食，宜去薏苡仁。孕妇慎用，薏苡仁滑利、绿豆性寒，须经医师评估；哺乳期妇女亦宜少食。风寒感冒、脾胃虚寒之腹泻期停服。糖尿病患者须去冰糖并将粳米计入主食总量，血糖控制不佳者宜减少绿豆量、增粳米与山药。低血压、心肾功能不全者须遵医嘱。婴幼儿与儿童不宜多食。莲子心苦寒，量须极小，脾胃虚寒与孕妇尤当忌之。对豆类过敏者禁食，荨麻疹体质者慎试。服药期间忌与萝卜同食，忌浓茶；绿豆含皂苷等成分，与解药类、解热镇痛类西药不宜同服，服西药者须错开时间并咨询医师。须说明：绿豆不在国家《既是食品又是药品的物品名单》之内，作为普通食材煮粥食用无碍，若欲入药调理须经中医师辨证指导，剂量与疗程遵医嘱；食疗不能替代药物治疗，湿热证明显者当经辨证论治。"},{"type":"keypoints","title":"掌握要点","items":["绿豆薏苡仁浸泡二小时，浸泡水倒弃","百合后下十二分钟，莲子心仅用一分","清热与养阴并行，利湿与健脾兼顾","饮食清淡为要，忌辛辣油腻与酒","绿豆非目录内药材，入药须遵医嘱"]},{"type":"quote","text":"綠豆 味甘、寒、無毒。主丹毒，煩熱，和五臟，行經脉。","source":"《饮膳正要·卷三·米谷品》"}]},{"id":"shanzha-meigui-cha","title":"山楂玫瑰茶","subtitle":"活血化瘀，疏肝理气","category":"体质食养","tags":["血瘀质","活血化瘀","疏肝","代茶饮"],"meta":[{"label":"适用人群","value":"血瘀质见面色晦暗、肌肤甲错、易有瘀斑或血丝、痛经、经血色暗夹块、面部色斑、唇甲青紫者；亦适合情志不畅兼见胸胁胀闷者作日常疏调。"},{"label":"主要功效","value":"活血化瘀、疏肝理气、消食化积。用于气滞血瘀之痛经、面色晦暗、胸胁胀闷。"},{"label":"食材组成","value":"山楂 12 g，玫瑰花 5 g，陈皮 3 g，红枣 3 枚"},{"label":"制作方法","value":"山楂去核切片，与玫瑰花、陈皮、红枣一同沸水冲泡加盖焖 10 分钟，可反复冲泡二至三次；亦可加水煮 8 分钟取汁。"},{"label":"食用注意","value":"山楂性微温，胃酸过多、胃溃疡者慎食；玫瑰花与红枣为普通食品，若作活血调经之用须遵医嘱；孕妇、月经过多者忌服。"}],"image":"","imageHint":"山楂","summary":"山楂玫瑰茶以山楂活血化瘀、玫瑰花疏肝行气为核心，配陈皮理气燥湿、红枣补中和脾，为血瘀质兼气郁者而设。山楂味酸甘微温，《食疗本草·卷上·楂子》谓其「唯治霍乱转筋，煮汁饮之」，后世以其消食化积、活血化瘀为用；玫瑰花味甘微苦温，理气解郁、和血散瘀；陈皮理气燥湿，使气行则血行；红枣补中养脾，防山楂之酸伐胃。全方「气血同调」，最宜痛经、面色晦暗、胸胁胀闷者长期代饮。惟山楂酸伐，胃酸过多者慎，孕妇忌服。","blocks":[{"type":"table","caption":"山楂玫瑰茶食材配伍与作用","head":["食材","用量","作用"],"rows":[["山楂","12 g","酸甘微温，消食化积、活血化瘀"],["玫瑰花","5 g","甘微苦温，理气解郁、和血散瘀"],["陈皮","3 g","辛苦温，理气燥湿、开胃化滞"],["红枣","3 枚","甘温，补中养脾、益气生津"],["沸水","500 mL","取其清轻，勿久煎"]]},{"type":"paragraph","text":"此茶宜用「短煎」或「焖泡」，皆不宜久沸久煎。制法有二：其一为焖泡，山楂去核切片（去核可减其酸涩之弊且省量），与玫瑰花、陈皮、红枣同入玻璃杯或盖碗，注沸水五百毫升，加盖焖十分钟，饮至半量再续水一次，可得二泡；其二为短煎，取上料加水六百毫升，煮沸后小火八分钟，滤取药汁，趁温分饮，此法取力较宏而香气稍失。玫瑰花为轻质花类，久煮则香气挥发、色泽变褐，故无论何种做法皆不宜超过十分钟。饮时可闻其馨香，观其微红，取饮之外亦有怡神之效。山楂片不宜研粉冲服，因其鞣质易与铁剂及其他药物结合。若以痛经为主要目的，宜在经前七至十日连续饮用；若作日常疏调，则每周三至四次即可。"},{"type":"paragraph","text":"血瘀质之成，或因气滞，或因寒凝，或因气血不足而无以推陈；《素问·生气通天论》言「血凝于肤者为瘀，凝于脉者为泣」，瘀血既成则血行不畅，而气为血之帅，故治瘀必兼理气。山楂味酸甘微温，入脾肝经，《食疗本草·卷上·楂子》载其「唯治霍乱转筋，煮汁饮之」，后世取其化积行滞、活血散瘀之能，为果品中最善化瘀者，正合血瘀质之需；玫瑰花甘微苦温，香气浓烈，能行气解郁、和血散瘀，所谓「气行则血行」，与山楂相配，一化瘀一行气，一血一气，相得益彰；陈皮辛苦温，理气燥湿、开胃化滞，助山楂消食而不伤正，且防其酸滞碍中；红枣甘温，补中养脾、益气生津，既护胃气，又助血行，且能调和花茶之香苦。合观全方，气血同调、寒温并用，最宜血瘀兼气郁者。"},{"type":"paragraph","text":"食用建议：每周三至五次，每次一壶约三百毫升，分二至三次温饮；如为痛经调经，宜经前十日连服，经期可续服至经净，若经量过多则经期停服。经期饮食宜温通，忌生冷；日常可配黑木耳、桃仁、山药与适量醋制食材以助化瘀。服药期间忌食肥甘厚味与酒，忌久坐不动，宜每周三至五次快走或太极等有氧运动以助血行；情绪调畅尤为关键，可每日以两手交替按揉膻中、期门、太冲各一分钟，并作腹式深呼吸十分钟。若见面部色斑明显，可长期饮用并配合外用玉容散类中医外治（须医师指导）；若痛经剧烈或经色紫黑夹大血块，须先作妇科检查排除器质性病变。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"孕妇禁用，山楂有活血化瘀、兴奋子宫之虞，服之恐动胎；哺乳期妇女亦宜少饮。月经过多、崩漏淋漓、产后恶露未净者禁服，恐加重出血。胃酸过多、胃及十二指肠溃疡活动期、反流性食管炎者慎用，山楂酸涩，服之加重胃痛；胃酸缺乏者亦不宜空腹饮用。消化道溃疡出血期禁服。低血压、正在服抗凝药（如华法林）者须告知医师并遵医嘱，血瘀重者用之尤须谨慎。糖尿病患者须注意红枣之糖分，山楂与玫瑰花本身亦含少量糖，血糖控制不佳者减量。对山楂、玫瑰、陈皮过敏者禁食。服用期间忌与萝卜同食，忌用浓茶送服；山楂含鞣质，与铁剂、碱性药物不宜同服，须错开时间。须说明：山楂在国家食药物质目录之内，可作日常食材；玫瑰花、红枣作普通食品饮用无碍，若作活血调经治疗之用则须经中医师辨证指导，剂量与疗程遵医嘱；食疗不能替代药物治疗。"},{"type":"keypoints","title":"掌握要点","items":["山楂去核切片，减酸涩亦省量","玫瑰花久煮则香散色变，不宜超过十分钟","痛经者经前十日连服，经量多者经期停服","气行则血行，须配合运动与情志调畅","孕妇、月经过多者禁服，胃酸过多者慎用"]},{"type":"quote","text":"楂子〈平〉上多食損齒及損筋。唯治霍亂轉筋，煮汁飲之。與木瓜功相似，而小者不如也。","source":"《食疗本草·卷上·楂子》"}]},{"id":"foshou-chenpi-yin","title":"佛手陈皮饮","subtitle":"疏肝理气，燥湿化痰","category":"体质食养","tags":["气郁质","疏肝解郁","理气","代茶饮"],"meta":[{"label":"适用人群","value":"气郁质见神情抑郁、胸胁胀闷、善太息、脘腹胀满、嗳气频作、咽中如有物梗阻、情绪波动而症状随之起伏者；亦适合压力性脘腹不适与经前乳胀者。"},{"label":"主要功效","value":"疏肝理气、和胃止痛、燥湿化痰。用于肝郁气滞之胸胁胀闷、脘痞嗳气、咽中梗阻。"},{"label":"食材组成","value":"佛手 6 g，陈皮 5 g，玫瑰花 3 g，合欢花 3 g（可加）"},{"label":"制作方法","value":"佛手与陈皮切细丝，与玫瑰花、合欢花同入杯，沸水冲泡加盖焖 12 分钟，温饮；或加水煮 8 分钟滤汁分饮。"},{"label":"食用注意","value":"佛手、橘皮均在国家食药物质目录之内，可作日常代茶；惟气郁而正气虚者当配补气之品，孕妇慎用，胃酸过多者少饮。"}],"image":"","imageHint":"佛手","summary":"佛手陈皮饮是气郁质的疏肝第一方。佛手味辛苦酸温，疏肝理气、和胃止痛、燥湿化痰，为疏肝之良品；陈皮即橘皮，辛苦温，理气健脾、燥湿化痰，《饮膳正要·料物》称其「止消渴，开胃气，下痰，破冷积」；玫瑰花理气解郁、和血散瘀；合欢花解郁安神、活血。本方香气流动，以「气行则郁解」为法，最宜胸胁胀闷、嗳气、咽中梗阻与情绪相关症状；重在理气而不专事辛散，故久服不伤正。惟气郁兼气虚者当配黄芪、党参同用（须医师指导）。","blocks":[{"type":"table","caption":"佛手陈皮饮食材配伍与作用","head":["食材","用量","作用"],"rows":[["佛手","6 g","辛苦酸温，疏肝理气、和胃止痛、燥湿化痰"],["陈皮","5 g","辛苦温，理气健脾、燥湿化痰、下痰破积"],["玫瑰花","3 g","甘微苦温，理气解郁、和血散瘀"],["合欢花","3 g","甘平，解郁安神、活血止痛"],["沸水","500 mL","取其清轻芳香之气"]]},{"type":"paragraph","text":"此饮重在香气与浸润，宜焖泡而忌久煎。佛手为干燥果实切片，须择色金黄、香气浓郁者，用前以清水快速冲一下即可，不宜浸泡过久以免香气流失；陈皮须刮去内瓤（内瓤性滞而碍气），切细丝；玫瑰花与合欢花以轻质花类，投量宜少。三味药与陈皮同置玻璃杯或保温杯中，注沸水五百毫升，加盖焖十二分钟，其间香气自升；饮至半量续热水一次，第二泡味淡而力缓。亦可入小锅加水煮沸八分钟滤汁，趁温分二三次饮完。若以脘腹胀满为主，可加苏梗 6 g；若以咽中梗阻为主，可加桔梗 5 g（均须医师指导）。代茶可一日一壶，分次温饮；服后宜静坐片刻，缓行而勿即行 strenuous 劳作，俾气机得畅。"},{"type":"paragraph","text":"气郁质之病机，在于肝失疏泄、气机郁滞；《素问·举痛论》云「怒则气上，喜则气缓，悲则气消，恐则气下，惊则气乱」，情志不遂则气机升降出入失常，气滞则津液不布而痰随气生，气滞又使血行不畅而成瘀。佛手辛苦酸温，疏肝解郁而兼和胃止痛、燥湿化痰，《本草纲目》谓其「主治肝胃气痛，肺痞咳嗽」，其用不在破气而在条达，是气郁而不虚者之要品；陈皮辛苦温，理气健脾、燥湿化痰，《饮膳正要·料物》明载其「止消渴，开胃气，下痰，破冷积」，既助佛手理气，又运脾化痰，绝其生痰之源；玫瑰花与合欢花同为花类，一行气解郁、一解郁安神，使气郁兼心神不宁者得其所归。全方以芳香流动之品疏其郁、开其结，作用温和而持久，不伤正气，最宜作为气郁质长期日常之饮。"},{"type":"paragraph","text":"食用建议：每日一壶，分二至三次温饮，连服一至三月为度；若气郁明显而症状随情绪波动，可在情志不畅时即饮一壶，疗效较定时服用为佳。服药期间宜保持情绪舒畅，戒忧思恼怒，忌过度思虑；每日宜户外散步三十分钟，日光与自然环境有助肝气条达。运动可选八段锦「左右开弓似射雕」「托天按地如拔山」以舒展胸胁，或以两臂平展、缓慢转体各三十次以开胸理气。饮食宜清淡而多纤维，忌过度辛辣与浓茶咖啡，晚餐勿过饱。若兼见乏力自汗、少气懒言之气虚征象，则不宜单投本方，宜加黄芪 10 g、党参 12 g 同煮（须医师指导）以补气行气；若兼见口苦咽干、心烦易怒之肝火，须先清肝，忌以理气之法治火郁。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"气郁而正气虚者不宜单用本方，若见面色㿠白、少气懒言、自汗、舌淡胖，须配补气药使用（须医师指导）。孕妇慎用，玫瑰花与合欢花有活血之性，妊娠期须经医师许可；哺乳期妇女亦宜少饮。阴虚火旺、潮热盗汗、口干咽燥、舌红少苔者不宜，芳香辛温之品易耗气助热。胃酸过多、胃溃疡活动期者少饮，陈皮与佛手辛香走窜，可能刺激胃酸分泌而加重胃痛；胃寒而呕者不宜。痰热壅盛、面赤便秘者忌服。对柑橘类（橘、橙、柚、柠檬）过敏者禁食，因佛手与陈皮同属芸香科，过敏体质者须谨慎试用。婴幼儿不宜。服药期间忌与萝卜同食；本方所含佛手、橘皮均在国家《既是食品又是药品的物品名单》之内，可作日常代茶饮品，然作治疗性调养仍须经中医师辨证指导，剂量与疗程遵医嘱；食疗不能替代药物治疗，郁证而见情绪障碍、失眠、厌食者当及时就医。"},{"type":"keypoints","title":"掌握要点","items":["佛手、陈皮、玫瑰、合欢皆芳香，焖泡为上","陈皮须刮去内瓤，方不滞气","气郁兼气虚者须配补气药，忌单投","配合疏胸导引与情绪调畅，疗效更显","孕妇、柑橘过敏者、胃酸过多者慎用"]},{"type":"quote","text":"橘 皮∶主胸中瘕熱逆氣。","source":"《食疗本草·卷上·橘》"}]},{"id":"gubiao-wumei-yin","title":"固表乌梅饮","subtitle":"敛肺止咳，固表止汗","category":"体质食养","tags":["特禀质","固表","敛肺","代茶饮"],"meta":[{"label":"适用人群","value":"特禀质（过敏体质）见反复发作的过敏性鼻炎、哮喘、荨麻疹、湿疹，伴喷嚏连连、遇风或遇冷即发、平时易汗、脉浮虚者；亦适合表虚自汗、易感冒者的平时调养。"},{"label":"主要功效","value":"敛肺止咳、固表止汗、缓急和中。用于肺气不固之久咳、虚喘、自汗与过敏性发作。"},{"label":"食材组成","value":"乌梅 10 g，防风 6 g（目录外，须医师指导），黄芪 10 g，甘草 3 g，大枣 3 枚"},{"label":"制作方法","value":"乌梅略拍碎，与其余药材同入锅，加水 600 mL 煎 20 分钟滤汁，分早晚温饮，可加冰糖少许调味。"},{"label":"食用注意","value":"甘草反甘遂、大戟、海藻、芫花，服药期间严禁同用；防风为目录外药材，须医师指导；表虚自汗而外感发热者停服。"}],"image":"","imageHint":"乌梅","summary":"固表乌梅饮为特禀质（过敏体质）平素调养而设，出自玉屏风散合乌梅丸之意。乌梅酸涩平，入肺肝脾经，敛肺止咳、涩肠止泻，《食疗本草·卷上·梅实》谓其「食之除闷，安神」；黄芪甘微温，补气升阳、固表止汗，为玉屏风之主药；防风辛甘微温，祛风解表，与黄芪相配，一补一散，固表而不留邪；甘草补脾益气、调和诸药。本方扶正固表、祛风御邪，最宜过敏性鼻炎与哮喘者平素调养。惟甘草有十八反之忌，须严防与之同用之药。","blocks":[{"type":"table","caption":"固表乌梅饮食材配伍与作用","head":["食材","用量","作用"],"rows":[["乌梅","10 g","酸涩平，敛肺止咳、涩肠止泻、生津安神"],["黄芪","10 g","甘微温，补气升阳、固表止汗、托邪外出"],["防风","6 g","辛甘微温，祛风解表、胜湿止痛（目录外，须医师指导）"],["甘草","3 g","甘平，补脾益气、调和诸药、解毒"],["大枣","3 枚","甘温，补中养血、益气安神"]]},{"type":"paragraph","text":"此饮以「温煎取汁、分次温饮」为法，不宜久泡。乌梅用干品，须先以清水快速冲洗后略拍碎，使有效成分易于煎出，但不宜捣成细末，否则汤色浑浊而气浮；与防风、黄芪、甘草、大枣同入砂锅，加水约六百毫升，大火煮沸后转小火煎煮二十分钟，滤取药汁约三百五十毫升，弃滓。药汁宜温饮，分早晚两次，每次约一百五十至一百七十五毫升；小儿可分三至四次少量频服。甘草味甘而厚，若觉其味过甜可减至二克，大枣亦可减至两枚；或加少许冰糖调味，但外感期间不加。若为预防性调养，可在症状未发之时即作日常代茶；若为发作期，则仍应以正规治疗为主，不可仅赖此饮。全方煎剂性质，不可久置，须当日饮尽。"},{"type":"paragraph","text":"特禀质者，多因禀赋不耐，腠理疏松、卫外不固，故遇风遇寒即发瘾疹、鼻塞、喷嚏、咳喘。《素问·评热病论》言「邪之所凑，其气必虚」，正气不足是发病之内因，风邪外袭是触发之条件。玉屏风散以黄芪、防风、白术三味立论：黄芪甘微温，补气升阳、固表止汗，能扶正气而托邪外出；防风辛甘微温，祛风解表、胜湿止痛，助黄芪以固表而祛除外风；甘草与大枣益气和中、调和诸药。本方于此更合乌梅一味：乌梅酸涩平，敛肺止咳、生津安神，其酸收之性可敛肺气、固腠理，与黄芪之甘温补固相配，一散一收，疏风而不过散、固表而不留邪。合观之，本方实为固表御风、平素调养之良剂，寓「屏风」之义于日常茶饮之中。"},{"type":"paragraph","text":"食用建议：作为平素调养，每日一剂，分早晚温饮，连服一至三月为度；已明确过敏原者，须严格回避接触。服药期间起居有要：晨起后以两手搓热敷面、洗鼻各数十遍；居室宜常通风，床褥被套须定期烫洗除螨，尘螨、花粉、霉菌、宠物皮屑皆为常见诱因；花粉季节外出戴口罩与眼镜，回屋即洗面洗鼻更换外衣。运动宜温和渐进，如散步、太极、游泳，避免剧烈运动诱发；不宜汗出当风。饮食宜清淡而少发物，忌腥膻发物（如虾蟹、无鳞鱼、鹅肉、公鸡）、忌酒与辛辣浓茶；已知食物过敏者绝对回避。情志调畅亦重要，每日可按揉肺俞、风门、足三里各一分钟以助卫气；反复发作或伴呼吸困难者须及时就医，不可延误。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"外感发热、咽喉肿痛、感冒期间停服，恐闭门留寇；表虚自汗而伴外邪者尤忌。实热证、阴虚火旺者不宜，乌梅酸涩收敛，易敛邪留热。高血压、糖尿病者须注意糖尿病患者慎用大枣与冰糖，血糖控制不佳者去之。孕妇慎用，须经医师评估。婴幼儿用量须减半并由儿科医师指导。对乌梅、甘草、黄芪、防风过敏者禁食；甘草长期大量服用可致水钠潴留、血压升高，高血压、心衰、水肿、低钾血症者须慎用并监测。重要配伍禁忌：甘草反甘遂、大戟、海藻、芫花，服药期间严禁与上述四药同用，亦不可与含上述成分的中成药同用；服药期间忌与萝卜同食。须特别说明：防风不在国家《既是食品又是药品的物品名单》之内，作为药材使用必须经中医师辨证指导，剂量与疗程遵医嘱。食疗不能替代药物治疗，过敏性哮喘、严重荨麻疹者须规范使用抗过敏或吸入制剂，不可单凭此饮自行停药。"},{"type":"keypoints","title":"掌握要点","items":["玉屏风加乌梅，一散一收，固表御风","温煎二十分钟滤汁，当日饮尽","甘草十八反：反甘遂、大戟、海藻、芫花，严禁同用","回避过敏原与发物，起居环境同等重要","不可替代抗过敏规范治疗，勿自行停药"]},{"type":"quote","text":"梅實 食之除悶，安神。烏梅多食損齒。","source":"《食疗本草·卷上·梅實》"}]},{"id":"qincai-chao-xianggan","title":"芹菜炒香干","subtitle":"平肝清热，健胃利湿","category":"季节食养","tags":["春季食养","平肝清热","家常小炒","高纤维"],"meta":[{"label":"适用人群","value":"春季肝气升发而肝郁气滞、血压偏高、头胀目赤、烦躁易怒者；亦适合春困乏力、纳呆腹胀、肠燥便秘者。高血压与高血脂者可作日常佐餐。"},{"label":"主要功效","value":"平肝清热、健胃消食、润肠通便。用于肝阳偏亢之头胀目赤与胃肠积滞。"},{"label":"食材组成","value":"鲜芹菜 300 g，香干 150 g，干辣椒 3 g，蒜末 5 g，盐 2 g，植物油 10 g"},{"label":"制作方法","value":"芹菜去叶切段洗净沥干，沸水焯 20 秒；香干切条；热锅凉油爆香蒜末与干辣椒，下香干炒香，再下芹菜大火快炒 1 分钟，加盐出锅。"},{"label":"食用注意","value":"芹菜性凉，脾胃虚寒、便溏者宜少食；香干为豆制品，嘌呤较高，痛风与肾功能不全者须限量；晚餐不宜多食以免腹胀。"}],"image":"","imageHint":"芹菜","summary":"芹菜炒香干是应春令时蔬的家常小炒，以芹菜为主料，香干为辅。芹菜味辛甘微凉，入肝肺经，平肝清热、健胃消湿，《饮膳正要·菜品》载水芹「主养神益气，令人肥健，杀药毒」，可作春令平肝之日常佐餐；香干为大豆制品，《饮膳正要·米谷品》称大豆「主益气，补不足」，兼以健脾之功。二者一清一补，配以蒜末、干辣椒之辛香，最宜春三月肝气升发之时，既疏泄肝郁又顾护脾胃。惟芹菜性凉，脾胃虚寒者宜少食。","blocks":[{"type":"table","caption":"芹菜炒香干食材配伍与作用","head":["食材","用量","作用"],"rows":[["鲜芹菜","300 g","辛甘微凉，平肝清热、健胃消湿"],["香干","150 g","甘平，益气健脾、补充植物蛋白"],["干辣椒","3 g","辛温，助肝气升发、增香醒脾"],["蒜末","5 g","辛温，行气解毒、杀菌"],["植物油","10 g","介质，宜用菜籽油或茶油"],["盐","2 g","调味，高血压者宜减半"]]},{"type":"paragraph","text":"此菜以「快」为要，火候稍慢即失其脆。芹菜摘取嫩茎与叶（叶亦可食，勿尽弃），去老筋与空心部分，洗净后切约五厘米长段，沥干水分；若茎较粗，可用刀背轻拍裂而不断开，盐分与味更易入。焯水必不可少：水沸后下芹菜二十秒即捞出过凉水，既杀生又保色，捞后沥干，下锅时若带水则成汤、味道变淡。香干切成长条或斜片，先以干锅微烘或蒸五分钟使其干香。烹调时热锅凉油，先爆香蒜末与剪开的干辣椒，随即下香干中火炒至边缘微焦并起香，再转大火下芹菜，快速翻炒六十至九十秒，加盐与几滴香醋提味，立即出锅。全程不超过两分钟，芹菜方能翠绿爽脆；久炒则出水、出味俱败。"},{"type":"paragraph","text":"春三月，天地气升，《素问·四气调神大论》云「春三月，此谓发陈。天地俱生，万物以荣……夜卧早起，广步于庭，被发缓形，以使志生」，是万物生发之候，亦是肝气升发之令。肝主疏泄而藏血，其性喜条达而恶抑郁，春日肝气易郁而横逆，故春季养生首重疏肝理气、不过度耗伤。芹菜辛甘微凉，《饮膳正要·菜品》记水芹「主养神益气，令人肥健，杀药毒，疗女人赤沃」，其辛散之性可疏泄气机、甘凉之质可清利头目，故《本草纲目》谓其「压热、杀鱼、肉毒」，为春令平肝清热之应时之菜；香干甘平，益气健脾，以脾土之健运制约芹菜之凉并助其化滞；干辣椒与蒜末辛温，助肝气之升发、醒脾开胃，使全方清而不寒、疏而不泄。四物相配，正合春季「生而勿杀，予而勿夺」之养。"},{"type":"paragraph","text":"食用建议：作为春季家常佐餐，每日或隔日一次，每次约一百五十克菜配一餐饭量，连食一至二月为度；亦可隔日用于晚餐小菜以助运化。食用时宜配糙米饭或杂粮饭、清蒸鱼、豆制品等，以补足蛋白；忌与生冷寒凉、肥甘厚味同餐。春季宜多食时令蔬果，本菜之外可轮换菠菜、荠菜、韭菜、豌豆苗、椿芽等，以应「生发」之令。调养上宜夜卧早起、每日舒展身体、缓行散步二十分钟以助肝气条达；每日子时前入眠，肝藏血，久卧伤血亦耗阴血。情绪宜舒展，勿郁怒伤肝。若肝阳偏亢而血压偏高者，可每日以菊花、决明子泡水代茶（须医师指导）配合本菜，内外合治。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒便溏、大便清稀者少食，芹菜性凉，多食易腹痛腹泻；妊娠期大量食用可能影响胎儿，孕妇不宜多食。高血压患者宜用低钠盐并将用量减半，钠盐过多不利血压控制。高尿酸血症、痛风及肾功能不全者须限量，香干与干辣椒之钠含量亦高，痛风者尤须避免过量。胆囊炎、胆石症、胰腺炎患者不宜。芹菜含呋喃香豆素，光敏体质、皮肤易过敏者食用后须避免日晒；芹菜过敏者禁食。服用抗凝药华法林者慎用大量芹菜，因其含维生素 K 拮抗作用，须告知医师并保持摄入量稳定。感冒发热、咳嗽痰多期间不宜多食。不锈钢锅忌久煮芹菜以免铬析出，宜用陶瓷或玻璃器皿。食疗不能替代药物治疗，春季高血压病情波动者当遵医嘱用药。"},{"type":"keypoints","title":"掌握要点","items":["焯水二十秒、快炒九十秒，脆嫩为要","热锅凉油爆香蒜末，先炒香干再下芹菜","芹菜须择嫩茎老筋去尽，勿尽弃其叶","配杂粮饭与清蒸鱼，忌生冷油腻同餐","高血压者减盐，高尿酸者限量香干"]},{"type":"quote","text":"水芹 味甘、平、無毒。主養神益氣，令人肥健，殺藥毒。","source":"《饮膳正要·卷三·菜品》"}]},{"id":"chunri-suanrong-tang","title":"春笋老鸭汤","subtitle":"清热润燥，滋阴开胃","category":"季节食养","tags":["春季食养","滋阴","清热","汤品"],"meta":[{"label":"适用人群","value":"春季肝胆湿热或燥热伤津见口苦口干、食欲不振、脘腹胀满、大便干结、皮肤瘙痒者；亦适合春困乏力、阴虚内热者作时令调补。脾胃虚寒者宜少食。"},{"label":"主要功效","value":"滋阴清热、和胃开胃、润燥通便。用于春燥伤津、肝胃不和之纳呆口苦。"},{"label":"食材组成","value":"春笋 250 g，鸭肉 400 g，姜 4 片，料酒 15 mL，盐 2 g，白胡椒粉少许"},{"label":"制作方法","value":"春笋切滚刀块，焯水去涩；鸭肉焯水去沫；同姜片、料酒入砂锅加水 1500 mL，大火煮沸转小火炖 80 分钟，加盐调味。"},{"label":"食用注意","value":"竹笋性寒，脾胃虚寒者忌；《饮膳正要》载「竹笋不可共鲫鱼食之」；春笋须焯水去草酸与涩味，草酸可与钙结合。"}],"image":"","imageHint":"春笋","summary":"春笋老鸭汤是江南春令家常名汤，以春笋与鸭肉相配而得。春笋味甘微寒，入肺胃经，清热润燥、和胃开胃，《饮膳正要·菜品》载竹笋「主消渴，利水道，益气。多食发病」，《食疗本草·卷上·竹》亦言其「主逆气，除烦热」；鸭肉甘咸微凉，滋阴补虚、养胃生津，与笋一清一润，正合春燥；姜片温中醒脾，制笋之寒并矫鸭腥；料酒行气散寒。全方清润而不寒滞，最宜春三月湿热内蕴而口苦纳呆者。惟笋性寒，脾胃虚寒者当忌。","blocks":[{"type":"table","caption":"春笋老鸭汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["春笋","250 g","甘微寒，清热润燥、和胃开胃、利水道"],["鸭肉","400 g","甘咸微凉，滋阴补虚、养胃生津"],["生姜","4 片","辛温，温中醒脾，制笋寒、矫鸭腥"],["料酒","15 mL","行气散寒、矫味去腥"],["盐","2 g","调味，水肿者宜减"],["白胡椒粉","少许","辛温，行气助消化，量宜小"]]},{"type":"paragraph","text":"此汤成败全在笋的预处理与火候。春笋切滚刀块后必须焯水：水烧开加少许盐，下笋块煮三至五分钟，捞出以清水冲净——此步可去其草酸与涩味，避免与钙结合而影响吸收，且能大幅减轻笋的生冷之性。焯好后再用清水浸泡十分钟更佳。鸭肉选带骨带皮者以增胶质与油润，冷水下锅焯烫，撇净浮沫后温水冲净，务必使汤清澈不浑。合入砂锅，一次加水约一千五百毫升，加姜片与料酒，大火煮沸转最小火保持微沸，慢炖八十分钟；若用高压锅则二十分钟即可，但火候温和者为上。盐于起锅前加入，白胡椒粉极少许点缀即可，多则辛辣夺味。汤成后宜撇去表面浮油，静置五分钟再饮。"},{"type":"paragraph","text":"春三月阳气升发而肝气独胜，《素问·四气调神大论》谓「此春气之应，养生之道也」，然春多风雨、气候乍暖还寒，人体阳气始升而津液易伤，遂见口干、脘痞、纳呆、皮肤瘙痒诸症，此即「春燥」。春笋甘微寒而质脆，《饮膳正要·菜品》载其「主消渴，利水道，益气」，清热而不燥津，开胃而不碍运，《食疗本草·卷上·竹》更言其「主逆气，除烦热」，正合春令郁热与胃气上逆；鸭肉甘咸微凉，滋阴补虚、养胃生津，为血肉有情之品而不燥不热，与笋一清一润、相反相成；生姜辛温，醒脾温中，制笋之寒、矫鸭之腥，更助肝气之升发；料酒与白胡椒行气散寒，助药力行达。合观之，本方清润相济、升降相因，是春令养肝护胃之应时之膳。"},{"type":"paragraph","text":"食用建议：每周一至两次，作午餐或晚餐汤品，每次饮汤约二百毫升并食笋与鸭肉适量，春分至清明间为最合时令。若以纳呆口苦为主，可加陈皮三克、砂仁三克（须医师指导）；若以皮肤瘙痒为主，可加苦瓜丝同煮或以防风煎水代茶（须医师指导）。服药期间宜多饮温水，忌辛辣煎炸、烧烤、火锅与烈酒，忌冰饮与生冷海鲜；饮食宜多时令蔬果如菠菜、荠菜、豌豆苗、香椿。起居上宜夜卧早起，多舒展、缓行、少劳神；每日子时前入眠，肝血得藏则春不困。若食后胃脘不适或大便溏泄，说明脾虚受寒，宜减笋量、加姜并停食数日。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒便溏者忌食，竹笋性寒，脾阳虚者服之易致腹痛腹泻；同理，阳虚型痛经、宫寒者不宜多饮。竹笋含草酸较多，忌与含钙丰富的食物（如豆腐、牛奶）同食，恐影响钙吸收；且草酸可刺激胃黏膜，故胃溃疡、胃酸过多、活动期胃炎者慎食。笋类亦可能致过敏，有笋过敏史者禁食。《饮膳正要·卷二·食物相反》明载「竹笋不可共鲫鱼食之，使笋不消成癥病，不能行步」，故本汤忌与鲫鱼同食；又载「竹笋不可与糖同食」，忌与糖同烹。痛风、高尿酸血症者注意汤中嘌呤与鸭皮油脂，量宜减并去浮油；高脂血症者宜选瘦鸭肉。孕妇可食，量宜适中；对鸭肉或笋类过敏者禁食。食疗不能替代药物治疗，春季见持续纳呆、黄疸、胁痛者当及时就医检查肝胆系统。"},{"type":"keypoints","title":"掌握要点","items":["春笋必须焯水三至五分钟，去涩去草酸","鸭肉焯净血沫，汤色方清","小火微沸八十分钟，撇去浮油","春分至清明间最合时令，纳呆者加陈皮砂仁","忌与鲫鱼、糖同食，脾胃虚寒者禁食"]},{"type":"quote","text":"竹筍 味甘、無毒。主消渴，利水道，益氣。多食發病。","source":"《饮膳正要·卷三·菜品》"}]},{"id":"lvdou-lianzi-tang","title":"绿豆莲子汤","subtitle":"清暑利湿，养心安神","category":"季节食养","tags":["夏季食养","清暑","利湿","安神"],"meta":[{"label":"适用人群","value":"夏季暑湿内蕴见心烦口渴、头晕目眩、身重困倦、小便短赤、寐差多梦者；亦适合暑热伤津而口干心烦者作清暑之饮。脾胃虚寒者宜少食。"},{"label":"主要功效","value":"清热解暑、利湿和中、养心安神。用于暑湿内阻之心烦口渴、身重困倦、失眠多梦。"},{"label":"食材组成","value":"绿豆 60 g，莲子 20 g（去心），百合 15 g，薏苡仁 15 g，冰糖 20 g（糖尿病者减）"},{"label":"制作方法","value":"绿豆、薏苡仁浸泡 2 小时后与莲子同加水 1200 mL，大火煮沸转小火煮 40 分钟至豆烂，下百合续煮 15 分钟，加冰糖与枸杞 8 g 再煮 3 分钟。"},{"label":"食用注意","value":"绿豆与莲子心苦寒，脾胃虚寒、便溏者忌；莲子须去心；冰糖宜少，暑热而湿盛者尤忌甘腻；勿与解药类西药同服。"}],"image":"","imageHint":"绿豆","summary":"绿豆莲子汤是夏令清暑安神之饮。绿豆甘寒，《饮膳正要·米谷品》称其「主丹毒，烦热，和五脏，行经脉」，清热解毒、消暑利湿，为解暑之要品；莲子去心后甘平，补脾止泻、养心安神、益肾固精；百合甘微寒，养阴润肺、清心安神；薏苡仁淡渗，健脾利湿，使暑湿从小便而去；冰糖生津润燥。合观之，本方清热与养阴并行、消暑与健脾兼顾，最宜暑热伤津、心烦口渴、寐差身重者夏月常饮。惟其性寒凉，脾胃虚寒者当忌，且莲子心须去。","blocks":[{"type":"table","caption":"绿豆莲子汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["绿豆","60 g","甘寒，清热解毒、消暑利湿、和五脏"],["莲子（去心）","20 g","甘平，补脾止泻、养心安神、益肾固精"],["百合","15 g","甘微寒，养阴润肺、清心安神"],["薏苡仁","15 g","甘淡微寒，健脾渗湿、利水消肿"],["枸杞","8 g","甘平，滋补肝肾、益精明目"],["冰糖","20 g","甘平，生津润燥调味（糖尿病者减）"]]},{"type":"paragraph","text":"此汤以「取其清、勿取其腻」为原则。绿豆与薏苡仁须冷水浸泡二小时，泡至豆粒发胀、绿豆皮色转深，浸泡水倒弃不用。莲子去心之法与小圆刀划开莲子中心剔除绿心，既去苦寒又减涩。加水约一千二百毫升于砂锅，大火煮沸转小火煮四十分钟，至绿豆开花、豆沙初成；此阶段绿豆之清热解暑之力最盛，宜饮其汤。百合于起锅前十五分钟下锅，久煮则气味散失；枸杞与冰糖最后三分钟投入，枸杞久煮色暗味酸，冰糖高温易焦。冰糖须依体质增减：暑热而口干者加至三十克，湿盛困倦或痰湿者则减至十克或不加。成汤后放至温热时饮，若夏季冷藏后饮，胃肠更觉舒适，但须注意勿过冰。隔夜汤不宜留饮，当日饮尽为佳。"},{"type":"paragraph","text":"夏三月，天地气交而万物华实，《素问·四气调神大论》云「夏三月，此谓蕃秀……使志无怒，使华英成秀，使气得泄，若所爱在外，此夏气之应，养长之道也」。然夏令暑气当令，暑为阳邪，其性炎热升散，最易耗气伤津；暑多夹湿，湿与热相搏，则身重困倦、胸闷脘痞、苔腻。故夏令食养之要，在于清热而兼化湿、祛暑而兼养阴生津。绿豆甘寒，《饮膳正要·米谷品》载其「主丹毒，烦热，和五脏，行经脉」，清热解毒、消暑利湿而不伤正，是暑热烦渴之第一要品；薏苡仁淡渗，健脾渗湿，使暑湿从小便而去，与绿豆相配，分消其邪；莲子去心甘平，补脾止泻、养心安神，于大队寒凉中顾护中焦并宁心安神；百合甘微寒，养阴润肺、清心安神，与莲子同为安神之用，暑热扰心而寐差者最宜；枸杞滋补肝肾，明目解暑热之目昏；冰糖甘平，生津润燥，为暑热伤津之要药。"},{"type":"paragraph","text":"食用建议：夏至至大暑之间最合时令，可每日或隔日一剂，作午后点心或晚餐后甜汤，每次约二百五十毫升，温饮或微凉饮皆宜；连服一至二月为度。若以解暑为急务，可加鲜荷叶一张（须洗净、剪破）同煮以增清利；若以心烦寐差为主，可加酸枣仁 10 g（须医师指导）或莲子心 1 g（极少量）；若见汗多伤津、口干甚者，可加乌梅 6 g（须医师指导）以生津止渴。服药期间宜多饮温水，忌贪凉饮冰、忌生冷海鲜与生果，忌酒与辛辣烧烤；饮食宜清淡，以时令瓜果蔬菜为佳。起居上宜晚睡早起、午间小憩片刻以养心，忌正午暴晒汗出当风；每日宜缓行或游泳以消暑，但忌大汗淋漓后即刻吹空调。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒便溏、大便清稀者忌食，绿豆、薏苡仁、百合皆寒凉，服之必伤中阳而加腹泻。痰湿壅盛、舌苔厚腻者不宜，恐滋腻助湿；暑湿而无热象者亦当少饮。孕妇慎用，薏苡仁滑利，须经医师评估；哺乳期妇女可食，量宜适中。风寒感冒、发热期间停服。低血压、脾胃虚寒之人大量饮绿豆汤易致头晕，须少量频饮。糖尿病患者须减冰糖，莲子与百合含糖，血糖控制不佳者宜去之并减少莲子用量。肾功能不全者须遵医嘱，勿大量饮汤。对豆类、莲子、百合过敏者禁食。服药食忌：莲子心与莲子相反，用时必须去心；本方所含绿豆不在国家《既是食品又是药品的物品名单》之内，作普通食材煮汤食用无碍，若欲入药须经中医师辨证指导，剂量与疗程遵医嘱；绿豆含皂苷等成分，与解药类、解热镇痛类西药不宜同服，服西药者须错开时间并咨询医师。食疗不能替代药物治疗。"},{"type":"keypoints","title":"掌握要点","items":["莲子必须去心，苦寒且与莲子相反","绿豆薏苡仁浸泡二小时，百合后下十五分钟","冰糖按体质增减，湿盛者宜省","夏至至大暑间最宜，可加鲜荷叶同煮","脾胃虚寒者忌，冰糖与西药须错开"]},{"type":"quote","text":"蓮子 味甘、平、無毒。補中養神，益氣，除百疾，輕身不老。","source":"《饮膳正要·卷三·果品》"}]},{"id":"lianzi-houtong-tang","title":"莲子核桃汤","subtitle":"固肾健脾，安神益智","category":"季节食养","tags":["夏季食养","固肾","安神","甜汤"],"meta":[{"label":"适用人群","value":"夏季心脾两虚、肾气不固见心悸失眠、健忘多梦、腰膝酸软、乏力神疲、久泻便溏者；亦适合中老年平素调补与学生考试期用脑过度者。"},{"label":"主要功效","value":"补脾益肾、固精止遗、养心安神。用于脾肾不足之心悸失眠、健忘乏力。"},{"label":"食材组成","value":"莲子 20 g（去心），核桃仁 15 g，芡实 15 g，茯苓 12 g，百合 15 g，冰糖 20 g"},{"label":"制作方法","value":"莲子、芡实、茯苓先煮 30 分钟，再下百合与核桃仁续煮 20 分钟，加冰糖调味，温服。"},{"label":"食用注意","value":"茯苓忌醋（依《饮膳正要》），莲子须去心；核桃油脂多，脾虚便溏者减量；痰湿、便秘者慎用，糖尿病者减冰糖。"}],"image":"","imageHint":"莲桃","summary":"莲子核桃汤是夏令安神益智之甜汤。莲子去心甘平，补脾止泻、养心安神、益肾固精，《饮膳正要·果品》称其「补中养神，益气，除百疾，轻身不老」；核桃仁甘温，补肾温肺、益精养脑，《食疗本草·卷上·胡桃》谓其「通经络气，润血脉，黑人鬓发」；芡实益肾固精、补脾止泻；茯苓健脾渗湿、宁心安神；百合养阴润肺、清心安神。本方心脾肾三脏并补，最宜夏季心烦寐差、健忘乏力与腰膝酸软者。全方甘润滋腻，痰湿壅盛者当减量。","blocks":[{"type":"table","caption":"莲子核桃汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["莲子（去心）","20 g","甘平，补脾止泻、养心安神、益肾固精"],["核桃仁","15 g","甘温，补肾温肺、益精养脑、润肠"],["芡实","15 g","甘涩平，益肾固精、补脾止泻"],["茯苓","12 g","甘淡平，健脾渗湿、宁心安神"],["百合","15 g","甘微寒，养阴润肺、清心安神"],["冰糖","20 g","生津润燥调味（糖尿病者减）"]]},{"type":"paragraph","text":"此汤宜「先煮实药、后下 delicate 之品」。莲子去心、芡实与茯苓三者皆须久煮方出味，先入砂锅加水约一千二百毫升，大火煮沸转小火煮三十分钟；至莲子酥软、芡实粉糯，再下百合续煮十分钟，最后加核桃仁——核桃含油脂丰富，久煮则香气尽失且油脂氧化生苦，故最后五分钟投入即可，另可留少许于饮时撒入。冰糖于关火前加，糖尿病者以少量木糖醇代之或不加。全程小火微沸，忌大火猛滚。莲子心须逐一剖开剔除，其苦寒之性易伤脾胃，且与莲子相反，绝不可混入。汤成后温饮最佳，若为消暑可稍凉后饮，但不宜冰镇；每服约二百五十毫升，当日饮尽。"},{"type":"paragraph","text":"夏三月，《素问·四气调神大论》云「使志无怒，使华英成秀，使气得泄，若所爱在外，此夏气之应，养长之道也」，夏当养长，人亦当舒展情志以助阳气外达。然暑热伤心、耗气伤津，心脾两虚者则心悸失眠、健忘多梦；肾者藏精生髓，髓充则脑健，若肾气不足则健忘、腰膝酸软。本方正取「心脾同治、脾肾相资」之义：莲子去心后甘平，补脾止泻而养心安神，《饮膳正要·果品》称「补中养神，益气，除百疾，轻身不老」，为全方之主；茯苓甘淡，健脾渗湿而宁心安神，与莲子相合则脾健心安；芡实甘涩，益肾固精、补脾止泻，为莲子之肾 counterpart；核桃仁甘温，补肾温肺、益精养脑，《食疗本草·卷上·胡桃》称其「通经络气，润血脉，黑人鬓发」，以髓生脑，为健脑益智之要品；百合甘微寒，养阴清心，防温补之燥。合观之，心脾肾三脏并补而以脾为枢纽，最宜夏令养心安神。"},{"type":"paragraph","text":"食用建议：每日或隔日一剂，作晚餐后甜汤，每次约二百五十毫升，连服一至三月为度；用脑过度、备考或失眠明显者可每日一次。以安神助眠为用者，宜于睡前一时温饮，配合「卧时垂眼、勿看屏幕、听缓音」之法；宜早睡，夏季亦当于子时前入眠。若以健脾止泻为用，则宜于早餐后食用，并配合腹部按摩（以掌心搓热揉腹一百圈）与艾灸足三里。若以补肾益脑为用，可加黑芝麻 10 g 与炒黑豆粉 15 g 同煮，制成糊饮更佳。服药期间饮食宜清淡而富于蛋白，忌浓茶、咖啡与烈酒，忌睡前饮大量汤水以免夜尿；配合上宜每日散步三十分钟与八段锦「五劳七伤式」以助气血运行。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"痰湿壅盛、舌苔厚腻、形体肥胖者不宜，本方甘温滋腻，助湿增滞。脾虚便溏、大便清稀者须减量，核桃仁与冰糖皆润，服之易加腹泻；核桃仁油脂多，胆囊炎、胆石症者须从少量试起。大便秘结者少服，防其润肠致滑；大便干结而心烦者可去冰糖、加少许火麻仁（须医师指导）。阴虚火旺、潮热盗汗、舌红少苔者减量，恐温补助热；感冒发热期间停服。孕妇可食，量宜适中；婴幼儿不宜多饮。糖尿病患者须减冰糖，莲子、芡实、百合皆含糖，须计入总量。须注意核桃为常见致敏原，过敏体质者禁食；胡桃未列入国家食药物质目录，作药材调补须遵医嘱。服药食忌：《饮膳正要·服药食忌》载「有茯苓勿食醋」，故本方服食期间及前后一二日忌食醋及醋制品、含醋饮料；莲子心与莲子相反，用时必须去心。食疗不能替代药物治疗，长期失眠、多梦者当经辨证论治。"},{"type":"keypoints","title":"掌握要点","items":["莲子、芡实、茯苓先煮，核桃最后投","莲子必须去心，苦寒且与莲子相反","茯苓忌醋，服食前后一二日忌醋制品","安神者睡前一时温饮，宜配合早睡","痰湿、便溏、痰热者减量，胡桃过敏者忌"]},{"type":"quote","text":"胡桃 味甘、無毒。食之令人肥健，潤肌黑髮，多食動風。","source":"《饮膳正要·卷三·果品》"}]},{"id":"qiufen-danggui-tang","title":"秋分百合莲子粥","subtitle":"润肺养阴，健脾宁心","category":"季节食养","tags":["秋季食养","润肺","养阴","粥品"],"meta":[{"label":"适用人群","value":"秋分后燥气当令、见干咳少痰、咽干咽痒、鼻腔干燥、皮肤干涩、心烦失眠、大便干结者；亦适合老年人与儿童秋燥调养。痰湿、脾胃虚寒者不宜。"},{"label":"主要功效","value":"养阴润肺、健脾宁心、生津利咽。用于秋燥伤肺之干咳咽干与心烦失眠。"},{"label":"食材组成","value":"鲜百合 30 g，莲子 20 g（去心），粳米 60 g，枸杞 8 g，梨 1/4 个（可加），冰糖少许"},{"label":"制作方法","value":"莲子去心、百合洗净与粳米同加水 900 mL，小火煮 35 分钟成稠粥，起锅前加枸杞与梨丁再煮 5 分钟，按口味加冰糖。"},{"label":"食用注意","value":"百合、莲子性平微寒，脾胃虚寒、便溏者宜减量；冰糖宜少，痰湿者省去；梨性寒，脾胃虚寒者可去之。"}],"image":"","imageHint":"秋粥","summary":"秋分百合莲子粥是应秋燥之时的经典粥方。百合甘微寒，养阴润肺、清心安神，《食疗本草·卷上》谓其「蒸过，蜜和食之。作粉尤佳」；莲子去心甘平，补脾止泻、养心安神、益肾固精；粳米甘平，益气止烦、和胃长肌肉；枸杞滋补肝肾；冰糖生津润燥；梨甘寒，润肺生津、清热化痰。本方以粳米为底、以百合为主，专润秋燥伤肺之干咳咽干，又以莲子护脾宁心，最宜秋分至霜降间燥气当令之时。惟其性偏凉，脾胃虚寒与痰湿者当减量。","blocks":[{"type":"table","caption":"秋分百合莲子粥食材配伍与作用","head":["食材","用量","作用"],"rows":[["鲜百合","30 g","甘微寒，养阴润肺、清心安神"],["莲子（去心）","20 g","甘平，补脾止泻、养心安神、益肾固精"],["粳米","60 g","甘平，益气止烦、和胃气、长肌肉"],["枸杞","8 g","甘平，滋补肝肾、益精明目"],["梨","1/4 个","甘寒，润肺生津、清热化痰"],["冰糖","少许","生津润燥调味（糖尿病者省）"]]},{"type":"paragraph","text":"此粥取「甘缓」之性，火候宜文不宜急。粳米淘净后冷水浸泡二十分钟；鲜百合掰瓣洗净、以清水浸片刻以去其土涩；莲子须剖开去心，绿色莲心苦寒且与莲子相反，绝不可残留。百合与莲子、粳米同入锅，一次加水约九百毫升，大火煮沸转最小火，加盖留缝出汽，慢煮三十五分钟，中途搅动两三次，直煮到米粒开花、粥面泛细密粥油为度。梨去皮切小丁，于起锅前五分钟下锅，略煮即软而清香犹存，久煮则甘香尽失。枸杞与冰糖于关火前投入，枸杞久煮色暗，糖高温焦苦。若为儿童食用，可将百合、梨丁切得更碎以利吞咽；若为老年便干者，可加黑芝麻 10 g 同煮。成粥温食为佳，秋夜尤宜作夜宵。"},{"type":"paragraph","text":"秋分者，阴阳相半、昼夜均而寒暑平，然自此而后退入仲秋，《素问·至真要大论》谓「燥胜则干」，燥邪伤津最易从口鼻而入，首先犯肺。肺为娇脏、喜润恶燥，燥气干之，则肺失宣降而见干咳少痰、咽干咽痒、鼻窍干燥；燥伤津液而见口渴、皮肤干涩、大便干结；秋气内应于情志而见情绪低落、寐差。故秋令食养之要，首在养阴润燥、兼以养心宁神。百合甘微寒，入心肺经，养阴润肺而清心安神，《食疗本草·卷上》记其蒸熟蜜食之法，正取其甘润；莲子去心甘平，补脾止泻、养心安神、益肾固精，于大队滋阴中顾护中焦并宁心安神；粳米为谷，《饮膳正要·米谷品》称其「主益气，止烦，止泄，和胃气，长肌肉」，是使寒凉药不伤胃的关键；枸杞滋补肝肾，肝肾阴充则肺阴有源；梨甘寒多汁，润肺生津、清热化痰，为秋燥之应季果；冰糖生津润燥、调味。"},{"type":"paragraph","text":"食用建议：自秋分至霜降之间，每日或隔日一餐，以早餐或晚餐后为佳，每次一碗约二百五十毫升，连服一至三月为度。若干咳明显，可加川贝母 3 g 同炖（须医师指导）；若咽干痒甚，可加麦冬 8 g（须医师指导）；若大便干结，可加火麻仁 10 g（须医师指导）。服药期间宜多饮温水，每日二千毫升以上，忌辛辣烧烤、油炸炙烤、火锅与烈酒，尤忌干燥零食与夜宵；宜多食梨、百合、银耳、白萝卜、芝麻、蜂蜜之类。起居上宜「早卧早起，与鸡俱兴」，与《素问·四气调神大论》秋三月之法相合，并每日午间小憩以养心；忌久处燥热环境，可用加湿器或室内洒水以增湿度；情绪上宜恬淡，可每日按揉太溪、三阴交、照海各一分钟。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒便溏、大便清稀者宜减量或去梨，百合、莲子、梨性皆偏寒，服之易加腹泻；本方受凉即减，不可机械食用。痰湿壅盛、舌苔厚腻、咳嗽痰多色白者不宜，恐滋腻助湿。风寒咳嗽、痰白清稀而畏寒者停服，忌闭门留寇。孕妇可食，量宜适中；对百合、莲子、梨过敏者禁食。糖尿病患者须去冰糖，莲子、百合、枸杞皆含糖，须计入主食与加餐总量，血糖控制不佳者以粳米山药粥替代。婴幼儿与儿童宜少食，注意梨丁切碎以防噎。服药期间忌与萝卜同食；百合、莲子虽在食药物质目录之内，但作治疗性调补仍须经中医师辨证指导，剂量与疗程遵医嘱。食疗不能替代药物治疗，持续干咳、咯血、胸痛者须及时就医排除肺系器质性病变，秋季亦为慢性咳嗽与哮喘高发之季，不可延误。"},{"type":"keypoints","title":"掌握要点","items":["小火文煮三十五分钟，米油浮面为度","莲子去心、梨丁后下、枸杞冰糖最后","秋分至霜降之间最宜，忌辛辣燥物","宜早卧早起、午间小憩、居室加湿","持续干咳咯血者须就医，勿以食疗延误"]},{"type":"quote","text":"秋氣燥，宜食麻，以潤其燥。禁寒飲食，寒衣服。","source":"《饮膳正要·卷二·四时所宜》"}]},{"id":"qiufen-danggui-tang-2","title":"秋分润燥银耳羹","subtitle":"滋阴润燥，益气生津","category":"季节食养","tags":["秋季食养","滋阴","润燥","甜羹"],"meta":[{"label":"适用人群","value":"秋燥伤津见口鼻干燥、咽干口渴、干咳少痰、皮肤干涩、头发枯焦、大便干结者；亦适合秋日进补前先润其燥者，以及用嗓过度之教师、播音者。"},{"label":"主要功效","value":"滋阴润燥、益气生津、养阴润肤。用于秋燥伤津之干咳、咽干、皮肤干涩。"},{"label":"食材组成","value":"银耳 15 g，南北杏各 10 g（甜杏仁可，南杏须少），雪梨 1 个，枸杞 8 g，冰糖 20 g"},{"label":"制作方法","value":"银耳泡发两小时撕小朵去黄蒂，与梨块同炖 60 分钟出胶，后下杏仁、枸杞再煮 10 分钟，加冰糖调味。"},{"label":"食用注意","value":"南北杏含苦杏仁苷，过量有中毒风险，务必用量极小且煮透；银耳泡发不过夜，变质者必丢弃；脾胃虚寒者少食，糖尿病者减冰糖。"}],"image":"","imageHint":"润燥","summary":"秋分润燥银耳羹为秋燥津伤而设，以银耳、雪梨为主料，配少量南北杏、枸杞与冰糖。银耳甘淡平，润肺生津、益气养阴，其胶质黏护咽喉，《食疗本草·卷上·木耳》谓木耳「利五脏，宣肠胃气拥」，而银耳色白入肺，为秋燥之妙品；雪梨甘寒，《饮膳正要·果品》称其「主热嗽，止渴，疏风，利小便」，清热润肺、生津止渴；南北杏一润肺止咳、一降气润肠；枸杞滋补肝肾。全方甘润清凉，最宜秋分后燥气当令之时。惟南北杏用量须小、须煮透。","blocks":[{"type":"table","caption":"秋分润燥银耳羹食材配伍与作用","head":["食材","用量","作用"],"rows":[["银耳","15 g","甘淡平，润肺生津、益气养阴"],["甜杏仁","10 g","甘平，润肺止咳、润肠通便"],["南杏仁","10 g（宜减半）","苦微温，降气止咳、润肠，须煮透"],["雪梨","1 个","甘寒，润肺生津、清热化痰"],["枸杞","8 g","甘平，滋补肝肾、益精明目"],["冰糖","20 g","生津润燥调味（糖尿病者减）"]]},{"type":"paragraph","text":"此羹以「出胶、煮透」为两大关键。银耳须冷水泡发二至三小时，中途换水两次，泡至耳片完全舒展、呈半透明淡黄，剪去黄色蒂根并撕成米粒大小的小朵；撕得碎方能出胶，整片则煮两小时亦不稠。泡发水必须倒弃，且不可隔夜久泡，若闻有异味或手感发黏即为变质，必须丢弃，不可勉强食用。南、北杏仁须提前用温水浸三十分钟去皮去苦，且须煮足二十分钟以上以破坏其苦杏仁苷，切不可大量生食；用量务必按表中小量而行，儿童尤须减半。雪梨去皮切块，梨核另置煮汤后取出弃去。加水约一千毫升，大火煮沸转最小火微沸，炖六十分钟至银耳出胶、汤色微稠；枸杞与冰糖最后十分钟投入。全程忌大火猛滚，忌加冷水。"},{"type":"paragraph","text":"燥之为病，伤人津液，秋令尤甚。《素问·阴阳应象大论》云「燥胜则干」，燥气与秋天俱，故仲秋之后口鼻干燥、干咳、皮肤干涩、便结诸症叠出。银耳甘淡而平，入肺经，润肺生津、益气养阴，其胶质于煮制后释放，黏润护于咽喉与胃肠黏膜，是燥证不可无之品；《食疗本草·卷上·木耳》谓木耳「利五脏，宣肠胃气拥」，可见其本有宣畅之能。雪梨甘寒多汁，《饮膳正要·果品》载其「主热嗽，止渴，疏风，利小便」，清热润肺、生津止渴、化痰，与银耳一润一清；甜杏仁甘平，润肺止咳、润肠通便，一润肺一通便，兼顾咳与秘；南杏仁微苦温，降气止咳，助肺气下纳；枸杞滋补肝肾、益精明目，肝肾阴充则肺阴有源；冰糖甘平，生津润燥、调味，并缓和杏仁之微苦。合观之，本方润肺、生津、止咳、通便四效兼收，为秋燥津伤之应季良方。"},{"type":"paragraph","text":"食用建议：秋分至立冬之间，每日或隔日一碗，以晚餐后或睡前一时为佳（夜卧则津不布而燥愈甚），每次约二百五十毫升，温食。连服一至二月为度。若咳甚咽痒，可加川贝 3 g（须医师指导）；若干咳无痰而气逆，可加苏梗 5 g（须医师指导）；若手足心热、盗汗等阴虚内热明显，可加麦冬 8 g、地黄 10 g（均须医师指导）。服药期间宜多饮温水，忌辛辣烧烤、油炸、火锅与烈酒，忌过咸之品（咸伤津）；每日可食梨一至二个、蜂蜜一匙温水调服。起居上宜早卧早起，居室保持湿度，忌久处空调房与烟燥环境；每日按揉太溪、三阴交、涌泉各一分钟，并做扩胸与深呼吸以利肺气宣降。若见大便溏泄或腹痛，说明润腻碍脾，应减冰糖与银耳用量并加生姜同煮。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"脾胃虚寒、畏寒便溏、大便清稀者慎食，本方甘润清滑，服之易碍脾；痰湿壅盛、舌苔厚腻、咳嗽痰多者不宜。风寒咳嗽、痰白清稀而畏寒者停服，忌闭门留cousin。孕妇可食，量宜适中，杏仁用量尤须谨慎；婴幼儿与儿童不宜，杏仁含苦杏仁苷，儿童尤须减量或不用；对坚果、杏仁、银耳过敏者禁食。重要提示：南北杏所含苦杏仁苷经加热可部分分解，但过量或食用不当仍有中毒风险（可致头晕、呕吐、呼吸困难），故用量必须严格控制在每日南杏不超过十克、甜杏仁不超过十五克，且必须煮透二十分钟以上；出现不适须立即就医。糖尿病患者须减冰糖并计入加餐总量。银耳须现泡现食，泡发过久或发黏变质者一律丢弃，忌食变质银耳。服药期间忌与萝卜同食，忌浓茶同服。食疗不能替代药物治疗，持续干咳、咯血、喘促者须及时就医。"},{"type":"keypoints","title":"掌握要点","items":["银耳现泡现食，撕小朵方能出胶","南北杏须温水去皮、煮足二十分钟，用量极小","梨核煮汤后必须取出弃去","秋分至立冬最宜，睡前一时食之尤佳","脾胃虚寒、痰湿者忌，变质银耳必丢弃"]},{"type":"quote","text":"早卧早起，與雞俱興，使志安寧，以緩秋刑，收斂神氣，使秋氣平，無外其志，使肺氣清。","source":"《黄帝内经·素问·四气调神大论》"}]},{"id":"dongzhi-danggui-yangrou-tang","title":"冬至当归羊肉汤","subtitle":"温阳补虚，益气养血","category":"季节食养","tags":["冬季食养","温阳","进补","汤品"],"meta":[{"label":"适用人群","value":"冬至至大寒期间阳气内藏、畏寒肢冷、精神疲乏、气短懒言、食少便溏、面色㿠白者；尤宜中老年人、产后血虚者与冬季易感冒者。"},{"label":"主要功效","value":"温阳补虚、散寒止痛、益气养血。用于阳虚内寒之畏寒肢冷、腹中冷痛、虚劳羸瘦。"},{"label":"食材组成","value":"当归 12 g，生姜 20 g，羊肉 500 g，党参 15 g，黄芪 10 g，桂圆 6 枚，盐少许"},{"label":"制作方法","value":"羊肉焯水去沫；药材与姜片装药包，同炖加水 1500 mL，小火 90 分钟；出锅加盐调味，连汤带肉食用。"},{"label":"食用注意","value":"本方温热力强，阴虚火旺、湿热者禁服；孕妇忌用；羊肉忌与韭菜、荞麦、鱼膦同食；服用期间忌萝卜与生冷。"}],"image":"","imageHint":"冬至","summary":"冬至当归羊肉汤为冬令进补之代表，用《金匮要略》当归生姜羊肉汤加党参、黄芪、桂圆而成，是「冬至一阳生」时节的应时温补之膳。羊肉甘温大热，温中补虚、益气生肌；生姜辛温，温中散寒；党参补中益气、健脾养血；黄芪补气升阳、固表止汗；桂圆补益心脾、养血安神；当归补血活血止痛。合观之，气血阴阳并补而以温阳为先，最宜冬至至小寒间阳气内藏之时的畏寒乏力、气短自汗者。惟本方温燥，阴虚火旺与湿热者禁服，孕妇当忌。","blocks":[{"type":"table","caption":"冬至当归羊肉汤食材配伍与作用","head":["食材","用量","作用"],"rows":[["羊肉","500 g","甘大热，温中补虚、益气生肌"],["生姜","20 g","辛温，温中散寒、化饮止呕"],["当归","12 g","补血活血、止痛，调经润肠"],["党参","15 g","甘平，补中益气、健脾养血"],["黄芪","10 g","甘微温，补气升阳、固表止汗"],["桂圆","6 枚","甘温，补益心脾、养血安神"],["盐","少许","调味"]]},{"type":"paragraph","text":"此为冬令第一温补汤，火候与时机皆关紧要。羊肉选带骨连皮带筋者，瘦肉多则温力不足；切块后冷水浸一小时、换水两次以逼出血水，冷水下锅焯烫撇净浮沫后温水冲净，务使汤清不浊。药材与拍碎的生姜同装纱布袋，与羊肉共入砂锅，一次加足水约一千五百毫升，大火煮沸转最小火，保持微沸不翻滚，慢炖九十分钟；至骨酥肉烂、汤色棕红微稠为度。出锅取出药包，加盐调味。桂圆于炖汤末十分钟加入即可，久煮则味过甘而腻。若炖好后味淡，可加数片生姜同煮一刻钟；若过于油腻，可用勺撇去表面浮油。冬令宜温食热饮，服后宜避风寒、缓行片刻，不可即刻受寒风或即行大汗之运动。"},{"type":"paragraph","text":"冬三月，《素问·四气调神大论》云「冬三月，此谓闭藏。水冰地坼，无扰乎阳，早卧晚起，必待日光……去寒就温，无泄皮肤，使气亟夺，此冬气之应，养藏之道也」。冬主闭藏，阳气内藏而外泄于皮毛，故最宜温补以助阳气内聚。羊肉甘而大热，入脾胃肾经，《食疗本草·卷上·羊》谓其「主风眩瘦病，小儿惊痫，丈夫五劳七伤，脏气虚寒」，是温补虚寒之最直接者；生姜辛温，温中散寒、通经脉、逐寒外出，且制羊肉之膻；当归补血活血、止痛，为血虚有寒而设；党参甘平，补中益气、健脾养血，力缓而持久；黄芪甘微温，补气升阳、固表止汗，令卫气外固则不易感寒；桂圆甘温，补益心脾、养血安神，与当归、党参相合则气血生化有源。合观全方，以温阳散寒为主轴，气血同调、脾肾并顾，最合冬至「一阳初生」之时扶阳固本之旨。"},{"type":"paragraph","text":"食用建议：自冬至至立春之间，每周至多两次，以每周一至二次为宜；每次连汤带肉约小半碗至一碗，服后身暖微汗为度，不宜大汗淋漓。体虚较重者可连服十日为一疗程，症状改善后改为每周一次维持。服药期间忌一切生冷瓜果、冰饮、寒凉海鲜与冷菜，忌酒；晚餐宜七分饱，食后宜缓行百步。日常可每日以双手搓热揉按腰眼、命门、涌泉各百遍，并温灸足三里、关元、气海各十五分钟；早卧晚起，必待日光而后行。进补期间饮食宜温润而不过腻，配以山药、栗、核桃、红枣之类为佐，忌大补峻剂与浓烈参茸同进。若服后出现口干咽燥、烦躁失眠、苔黄而干，为温补太过，应即停服并请医师改方。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"阴虚火旺者禁服，症见口干咽燥、五心烦热、潮热盗汗、舌红少苔者，温补助火。湿热内蕴、舌苔黄厚、脘腹痞满者不宜，恐助湿壅滞。实热证、痰热壅盛而咳黄痰者禁服；感冒发热、咽喉肿痛、疮疡初起期间停服。孕妇禁用，当归有活血之功恐动胎，且温补恐助热动血；产后恶露未净者亦忌。痛风、高尿酸血症者注意浓肉汤嘌呤偏高，不宜多饮；高脂血症者以去浮油为要，量宜减；高血压、心衰、水肿者宜少盐少汤。儿童不宜，体质偏热者慎用。对羊肉、生姜、党参、桂圆过敏者禁食。配伍禁忌：羊肉忌与韭菜、荞麦同食，亦忌与鱼膦、酪同食；半夏、菖蒲服药期间忌食羊肉；本方含当归，当归仅获准作香辛料与调味品使用，作食疗用药须经中医师辨证指导，剂量与疗程遵医嘱；服药期间忌与萝卜同食，勿用浓茶送服。食疗不能替代药物治疗，阳虚之证当经辨证，阴虚火旺者误服可致诸症加重。"},{"type":"keypoints","title":"掌握要点","items":["当归生姜羊肉汤加参芪桂圆，为冬令温补主方","羊肉焯净血沫，小火微沸九十分钟","服后微汗、身暖为度，不可大汗","冬至至立春为当令，每周至多两次","阴虚火旺、湿热、孕妇禁服，忌韭菜荞麦"]},{"type":"quote","text":"冬氣寒，宜食黍，以熱性治其寒。禁熱飲食，溫炙衣服。","source":"《饮膳正要·卷二·四时所宜》"}]},{"id":"dongzhi-shanyao-geng","title":"冬至山药羊肉羹","subtitle":"温中健脾，益气填精","category":"季节食养","tags":["冬季食养","健脾","温中","羹品"],"meta":[{"label":"适用人群","value":"冬季脾胃虚寒见畏寒喜温、胃脘隐痛、食少便溏、倦怠乏力、腰膝酸软者；亦适合儿童与老年人冬季进补。平素痰湿壅盛者不宜。"},{"label":"主要功效","value":"温中健脾、益气填精、补虚润燥。用于脾肾阳虚之食少便溏、畏寒乏力。"},{"label":"食材组成","value":"山药 200 g，羊肉 300 g，当归 8 g，陈皮 3 g，生姜 4 片，盐 1.5 g"},{"label":"制作方法","value":"山药去皮切丁，羊肉切块焯水；药材与姜片先煮 20 分钟取汁，下羊肉与山药同煮 40 分钟成羹，加盐调味。"},{"label":"食用注意","value":"本方温补，痰湿、阴虚火旺者不宜；山药须煮透，黏液多者戴手套；羊肉忌与韭菜、荞麦同食；糖尿病者须计入淀粉总量。"}],"image":"","imageHint":"山药","summary":"冬至山药羊肉羹以山药与羊肉相配，是「以脏补脏」而兼顾脾肾的冬令温补羹。羊肉甘温大热，温中补虚、益气生肌；山药甘平，《饮膳正要·菜品》称其「补中益气，治风眩，止腰痛，壮筋骨」，补脾养胃、补肾涩精，且其胶质能使羹自然稠滑；当归补血和血；陈皮理气醒脾，使补而不滞；生姜温中散寒、矫腥。合观之，本方温中而不燥、补脾而能固，最宜冬季脾胃虚寒而食少便溏、畏寒乏力者。惟痰湿壅盛与阴虚火旺者当忌。","blocks":[{"type":"table","caption":"冬至山药羊肉羹食材配伍与作用","head":["食材","用量","作用"],"rows":[["山药","200 g","甘平，补中益气、健脾养胃、补肾涩精"],["羊肉","300 g","甘大热，温中补虚、益气生肌"],["当归","8 g","补血活血、止痛，兼润肠"],["陈皮","3 g","辛苦温，理气醒脾、燥湿化滞"],["生姜","4 片","辛温，温中散寒、醒脾矫腥"],["盐","1.5 g","调味，水肿者宜减"]]},{"type":"paragraph","text":"此羹以「药汁先行、山药后下、文火收稠」为要。羊肉切块焯水去血沫，捞出冲净；当归、陈皮与拍碎的姜片先入锅加水约七百毫升，小火煮二十分钟，滤取药汁弃滓——如此则药力尽出而汤不苦。将药汁倒入砂锅，下羊肉煮二十分钟，再下山药丁续煮二十分钟。山药须去皮切小丁，处理时戴一次性手套，既防其黏液致皮肤瘙痒，亦防氧化发黑；山药须煮至用筷子可轻松夹断、汤汁自然黏稠为度，不加淀粉亦不须额外勾芡，因山药淀粉遇热即糊。全程小火微沸，忌大火以防汤干。最后加盐调味，撇去浮油；因羹质稠，咸味渗透较慢，务必尝味后再定盐量。秋冬作晚餐温食最佳，每次一碗约二百五十毫升。"},{"type":"paragraph","text":"冬令闭藏，最宜「补」而不宜「泄」。《素问·四气调神大论》云「水冰地坼，无扰乎阳……去寒就温，无泄皮肤，使气亟夺」，冬三月阳气内藏，饮食当以温补脾肾为务。羊肉甘大热，温中补虚、益气生肌，为温补虚寒之第一血肉有情之品；山药甘平而润，《饮膳正要·菜品》明载其「补中益气，治风眩，止腰痛，壮筋骨」，入脾肺肾三经而以补脾为先，既补脾气以资后天生化，又补肾精以固先天，且其胶质黏滑，能护胃肠黏膜、为汤羹增稠，一举两得；当归补血和血、止痛润肠，与羊肉相伍，气血同补；陈皮辛苦温，理气醒脾、燥湿化滞，制大队温补滋腻之品碍胃之弊，使补而不滞；生姜辛温，温中散寒、醒脾开胃，兼矫羊肉之膻。合观之，本方温中健脾、益气填精，是冬季「以脾为先」之平补温养之膳。"},{"type":"paragraph","text":"食用建议：每周一至两次，以冬至至立春之间为当令；每次一碗约二百五十毫升，连汤带羹温食。若以畏寒为主，可加生姜至六片并加少许料酒同煮；若以食少便溏为主，可加白扁豆 15 g（须医师指导）；若以腰膝酸软为主，可加枸杞 10 g。服药期间忌生冷瓜果、冰饮与寒凉海鲜，忌酒与浓茶；饮食宜温软易化，以山药、小米、南瓜、红枣为佐。起居上宜早卧晚起、必待日光，日间适度散步，忌大汗淋漓之运动；每晚睡前以艾条温灸足三里与神阙各十五分钟，或以掌搓热揉摩中脘与脐周各百遍。若食后腹胀或口干上火，为温补或滋腻太过，应减量并加陈皮、砂仁（须医师指导）以运脾。"},{"type":"callout","variant":"warning","title":"禁忌人群与配伍禁忌","text":"阴虚火旺、潮热盗汗、五心烦热、舌红少苔者禁服，羊肉大热，最易助火。痰湿壅盛、形体肥胖、舌苔厚腻者不宜，羹质稠腻，恐助湿碍中。实热证与外感发热、咽喉肿痛、皮肤疮疡期间停服。孕妇禁食，当归有活血之功，且羊肉温补助热动血；产后恶露未净者亦忌。高血压、心衰、水肿、肾功能不全者宜少盐少量并遵医嘱。痛风与高尿酸血症者注意羊肉汤嘌呤与油脂，量宜减、去浮油；高脂血症者宜选瘦羊肉。糖尿病患者须注意山药与羊肉汤中淀粉及调味料，须计入主食与加餐总量并监测血糖。儿童与痰湿之小儿不宜多食；对羊肉、山药、当归过敏者禁食。配伍禁忌：羊肉忌与韭菜、荞麦同食，亦忌与鱼膦、酪同食；半夏、菖蒲服药期间忌羊肉；当归仅获准作香辛料与调味品使用，作食疗用药须经中医师辨证指导，剂量与疗程遵医嘱；服药期间忌与萝卜同食。食疗不能替代药物治疗。"},{"type":"keypoints","title":"掌握要点","items":["药汁先煮二十分钟，山药后下煮透","山药自然出胶，无需勾芡，戴手套处理","陈皮一味不可省，补而不滞","每周一至两次，冬至至立春最宜","阴虚火旺、痰湿、孕妇禁服，忌韭菜荞麦"]},{"type":"quote","text":"山藥 味甘、溫、無毒。補中益氣，治風眩，止腰痛，壮筋骨。","source":"《饮膳正要·卷三·菜品》"}]}]}},"solar":{"page":{"key":"solar","title":"节气养生","subtitle":"二十四节气 · 顺时而养","description":"按二十四节气顺序整理的中医起居、饮食、情志与导引养生要点，每一节气详述气候物候、阳气消长、饮食宜忌、穴位保健与该节气易发疾病，经典条文均标注出处，供顺时调养参考。","lead":"《素问·四气调神大论》曰：「阴阳四时者，万物之根本也。所以圣人春夏养阳，秋冬养阴，以从其根。」节气是中国人观察太阳周年运动而形成的时令划分，二十四节气交替反映气候、物候与人体阳气的盛衰节律。顺应这一节律起居、饮食、情志与运动，是中医养生「因时制宜」的核心。本页按节气先后详述各节气候特点与人体生理变化，给出饮食宜忌表、导引与穴位保健方法、易发疾病与预防要点，并附经典原文与谚语，助您在四时流转中未病先防。文中所载导引与按揉方法仅供日常保健参考，患病者仍须辨证由医师诊治，食疗与导引均不能替代药物治疗。","type":"section","icon":"fa fa-sun","sections":[{"id":"lichun","title":"立春","subtitle":"2月3日—5日 · 春季","summary":"东风解冻，蛰虫始振，阳气始生而未盛。立春为四时之始，人体阳气由闭藏渐转升发，当顺生发之势调畅气机、舒展情志，忌过食生冷。","blocks":[{"type":"paragraph","text":"立春是二十四节气之首，此时太阳黄经为345度，斗指寅，时在丑正与寅初之间。气候上，冬去春来，气温由严寒缓慢回升，但「春有倒春寒」，昼暖夜凉、大风降温频繁，冷暖空气交替往往带来数日的急剧波动。就物候而言，古人观察到「东风解冻，蛰虫始振，鱼陟负冰」：东风徐来，冰雪开始消融，蛰居之虫微微苏醒，河冰渐薄、鱼类上浮近于薄冰，正是天地间阳气萌动而生机始萌之象。对人体而言，此时腠理始开、汗孔渐泄，肝气由冬令之藏转为春令之升，肝主疏泄，条达则气机和畅，郁则胁胀、情志不遂、女子月经不调；同时脾胃之气尚弱，饮食稍不谨慎即易困倦、泄泻。立春之后的二十余日，风气渐盛而人体正气未充，故养生之要在于「顺生发、避风寒、缓起居」。"},{"type":"paragraph","text":"起居上宜「夜卧早起，广步于庭」，顺应阳气升发，每日晨起后到户外缓行三十分钟，舒展筋骨而助肝气条达；夜间当于子时前入眠，以养肝血。衣着宜「捂春」，因春寒料峭、人体腠理初开，不可骤减衣物，尤其须护住头颈、背部与足下，晨起、睡前尤忌受寒。情志上宜舒展乐观、忌怒忌郁，可多做户外与社交活动，疏泄肝气。运动宜柔缓渐进，如八段锦、太极拳、慢走，切忌大汗淋漓、骤然剧烈运动。按摩上可每日按揉肝俞、期门、足三里各一分钟，睡前以两手搓热揉擦腰眼与涌泉各百遍，以助阳气内敛归根。饮食宜省酸增甘、节食生冷，春时阳气升发而肝气偏旺，过食酸味则肝气更亢，过食生冷则伤脾阳而生湿。"},{"type":"table","caption":"立春饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","甘平之品：山药、红枣、小米、粳米、粳粟、蜂蜜","甘能补脾缓肝，助气血生化、养肝血而制肝亢"],["宜食","辛散之蔬：韭菜、荠菜、香菜、菠菜、芹菜","辛以疏肝理气，应春气升发，但辛散太过亦耗气"],["忌食","酸寒收敛之物：乌梅、石榴、南瓜、话梅、酸奶（过量）","春肝气当升，过酸则肝气郁遏不舒，滞气机"],["忌食","生冷寒凉：冰饮、生鱼片、螃蟹、苦瓜（过量）、冷拌菜","脾胃阳气未振，生冷直伤脾阳，易生腹胀腹泻"],["推荐食材","春饼、韭菜饺子、荠菜春卷、山药小米粥、枸杞菊花茶","以时令之菜配甘缓之谷，顺应立春升发之气"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"晨起后取两脚分开与肩同宽，双手抱于丹田部位，缓慢下蹲至大腿与地面约成四十五度，膝不过脚尖、腰背挺直，心中默数呼吸三十六息，共行九次。此式出自传统导引，能伸展全身筋脉、振奋阳气、疏通肝经，是立春最宜的站式导引。穴位按揉取三处：一为肝俞，位于背部第九胸椎棘突下、旁开一寸半，以拇指垂直按揉一分钟，以酸胀为度，能疏肝理气；二为期门，位于乳头直下第六肋间隙，是肝之募穴，以掌根轻揉一分钟，可疏肝利胆；三为足三里，位于外膝眼下三寸、胫骨前嵴外一横指，以拇指按揉一分半钟，健脾益气、扶助正气。另有简易搓腰法：两手握拳、以腰部为轴左右缓慢转动三十六次，同时以掌心搓热覆于腰眼，能温补肾阳、预防腰部受寒。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"立春之后气温乍暖还寒、呼吸系统疾病高发，最常见为感冒、急性咽炎、支气管炎与过敏性鼻炎反复发作；亦易出现「春困」嗜睡、头昏脑胀、情绪低落，以及胃肠道功能紊乱所致腹泻、纳差、急性胃肠炎。预防要点：其一，警惕「倒春寒」，寒潮来临时减少外出、及时添衣加帽，尤其注意头颈、腹部与足部保暖，忌汗出当风；其二，起居有常，睡前不熬夜，子时前入睡，晨起后接受日照十五至二十分钟以助阳气与褪黑素节律建立；其三，居室宜通风，每日开窗一至两小时，但避免直吹风口；其四，饮食清淡有节，忌生冷油腻与暴饮暴食，饭不过量以留脾运余地；其五，情绪宜舒展，抑郁焦虑者应及时疏导，必要时寻求专业心理与医疗帮助；其六，有慢性疾病与过敏体质者，按原有医嘱规律用药，不可自行停减。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"立春养生要点","items":["夜卧早起，晨起户外缓行三十分钟以助阳升发","春宜捂，护住头颈、背部与足下，忌汗出当风","饮食省酸增甘、节食生冷，甘缓以养脾养肝血","按揉肝俞、期门、足三里各一分钟，配搓腰固肾","警惕倒春寒与呼吸系统疾病、过敏复发及春困"]},{"type":"quote","text":"春三月，此谓发陈。天地俱生，万物以荣，夜卧早起，广步于庭，被发缓形，以使志生，生而勿杀，予而勿夺，赏而勿罚，此春气之应，养生之道也。","source":"《黄帝内经·素问·四气调神大论》"}]},{"id":"yushui","title":"雨水","subtitle":"2月18日—20日 · 春季","summary":"降雨渐增，气温回升，寒气渐退而湿气渐盛。雨水节气宜健脾祛湿、慎避湿寒，忌久居湿地与过食生冷，以防困倦、泄泻与风湿痹痛。","blocks":[{"type":"paragraph","text":"雨水是二十四节气中第二个节气，太阳黄经为330度，斗指壬，时在寅正与卯初之间。此期降水开始明显增多，气温由立春时的低位稳步回升，回暖的节奏比常年往往偏快，但雨水多、日照少，地面水分蒸发加上空气湿度上升，使得「湿」成为这一时段的主要气候特点。物候上，《礼记·月令》所载此时「獭祭鱼，鹰乃祭鸟」，古人见水獭捕鱼陈列岸边、鹰击飞鸟陈列以祭，遂以为物候之验，实际正是水域生态活跃、鸟类迁徙觅食之象。对人体而言，湿邪与春寒相合，最易困遏脾阳：脾主运化而喜燥恶湿，湿盛则水谷不化，出现头身困重、四肢酸懒、精神萎靡、食欲不振、大便溏薄；湿性黏滞重浊，又易困阻气机而使肝气郁而不伸。此外春雨多寒，湿寒相搏，关节不利者每逢阴雨即感酸痛加重，呼吸道亦易受寒湿侵袭而生咳嗽、痰多。对整体而言，此时阳气升发而尚未稳固，机体处于「既怕寒、也怕湿」的两难之境。"},{"type":"paragraph","text":"起居上仍当夜卧早起，但较立春可略提早起身，宜在雨歇天晴时到户外活动，承接日照以助阳气。居处宜干燥，居室宜常开窗通风以排湿，床褥被褥须常晾晒；切忌久居湿地、涉水淋雨后立即就卧，亦忌汗出后即脱衣吹风。情志上宜平和少郁，湿浊困阻气机时更易生胸闷、烦躁，宜以散步、下棋、听乐等方式疏导。运动宜选择在晴好天气进行，以快走、慢跑、太极拳、八段锦为宜，量力而动，忌雨中勉强锻炼。按摩上宜重在健脾利湿，可每日按揉足三里、阴陵泉、脾俞各一分钟，以拇指垂直下压至酸胀；亦可用两手空拳自腰际向下捶打大腿外侧与内侧各三十次，以震动脾经而助运化。饮食上，《饮膳正要·卷二·四时所宜》谓「春气温，宜食麦，以凉之，不可一于温也」，春虽生发而湿气渐盛，故不宜一味温燥，亦不宜过于寒凉，当取甘淡渗利之品健脾祛湿。"},{"type":"table","caption":"雨水饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","甘淡渗湿：薏苡仁、赤小豆、茯苓、豇豆、冬瓜","淡能渗湿，甘能健脾，为治湿第一要义"],["宜食","健脾和胃：山药、白扁豆、南瓜、大麦、粳米","脾健则湿自化，胃和则纳谷知味"],["忌食","滋腻助湿：肥肉、奶油、糯米过多、油炸糕点、浓汤","肥甘厚味助湿生痰，壅遏脾阳"],["忌食","生冷寒凉：冰饮、刺身、冷面、苦瓜西瓜（过食）","寒凉伤脾，湿上加寒，最易腹泻"],["推荐食材","薏苡赤小豆粥、茯苓薏苡仁粥、山药小米粥、冬瓜薏米汤","以淡渗之品配健脾之谷，顺雨水湿气"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「仰卧伸展」式：仰卧于床上，双臂平展置于体侧，掌心向上，闭目静养三分钟以养神；然后屈膝并以两手抱膝，缓慢将上身卷起贴向大腿，重复九次；最后平躺舒展四肢，深呼吸三十六息。此式能舒展脊柱、牵拉督脉与膀胱经，助阳气由下而升，最宜在雨歇之时于室内进行。穴位按揉取四处：一为脾俞，位于第十一胸椎棘突下旁开一寸半，以拇指或掌根按揉一分半钟，健脾利湿；二为阴陵泉，位于胫骨内侧髁下方凹陷处，是脾经合穴，用拇指垂直重按一分钟至酸胀，渗湿消肿之力最专；三为足三里，外膝眼下三寸，胫骨前嵴外一横指，按揉一分半钟，扶正祛湿；四为三阴交，内踝尖上三寸、胫骨内侧缘后方，妇女尤宜按揉一分钟，养血调经、健脾利湿。另可每日以双手掌相对搓热后覆于腹部脐周，作顺时针摩腹一百圈，助脾胃运化。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"雨水湿气渐盛，最易出现三类病证：一是消化系统疾患，如急性胃肠炎、细菌性痢疾、肠易激综合征发作，多因饮食不节、贪凉饮冷所致，表现为腹痛腹泻、恶心呕吐；二是风湿与关节病，湿寒侵袭使原有膝关节炎、腰椎间盘突出、痛风等旧疾加重，表现为关节酸痛、肿胀、屈伸不利；三是呼吸道疾病，湿寒刺激使感冒、支气管炎、慢性咽炎复发，咳嗽痰多而黏。此外，春分前后易发「湿温」，表现为身热不扬、午后热甚、头身困重、胸闷纳呆。预防要点：其一，饮食以温热为度，粥、汤、煮、炖为宜，忌生冷冰饮；其二，注意保暖防潮，雨天避免淋雨涉水，被褥宜常晒，居室宜除湿；其三，注意饮食卫生，不食隔夜与生冷食物，瓜果洗净削皮；其四，适度运动以助气血运行，但雨中与湿滑之地不宜锻炼；其五，腹泻者及时补充水分与电解质，持续腹泻、便血、发热者须就医查因，不可仅以食疗拖延。慢性病患者须规律用药，勿因节气调养而自行停药。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"雨水养生要点","items":["雨多湿盛，居室通风除湿，被褥常晾晒","饮食以甘淡渗湿为主，忌肥甘滋腻与一切生冷","晨起天晴即出户受日照，雨天改室内导引","按揉脾俞、阴陵泉、足三里、三阴交并摩腹","重点防腹泻、关节酸痛与湿温、咳嗽复发"]},{"type":"quote","text":"春氣溫，宜食麥，以涼之，不可一於溫也。禁溫飲食及熱衣服。","source":"《饮膳正要·卷二·四时所宜》"}]},{"id":"jingzhe","title":"惊蛰","subtitle":"3月5日—7日 · 春季","summary":"春雷始鸣，蛰虫出戶。惊蛰时节阳气骤升、肝气升发最盛，最易肝火上炎与情志失衡，宜疏肝理气、清降肝火，慎用辛燥大热之品。","blocks":[{"type":"paragraph","text":"惊蛰为春季第三个节气，太阳黄经为345度之后的345度（斗指丁），时在卯正与辰初之间。此节气以「春雷响」为显著标志——气温回升至一定程度，空气中水汽与上升气流在高空冷凝而成雷声，雷动惊醒蛰伏于土中的虫豸，故曰惊蛰。物候上《礼记·月令》载此时「桃始华」，桃树初绽花萼，南方亦见仓庚鸣而鹰化为鸠，草木萌发与生物复苏同步推进。气候上，惊蛰前后是我国气温回升幅度最大的时段之一，民间有「春捂到九九」的旧法，然此时亦常出现「倒春寒」，因为冷暖空气仍频繁交汇。对人体而言，阳气由渐升转为骤升，肝气亦随之升发最旺：肝主疏泄而藏血，阳气升则肝气动，气机不畅则郁而化火，出现目赤、口苦、胁肋胀痛、烦躁易怒、失眠多梦、头胀头痛；肝木克脾土，肝气乘脾则见纳差、腹胀、泄泻。此外春升太过亦耗伤阴血，令人倦怠、眼干、皮肤干涩。此期是「春困」最为明显的阶段，亦是精神与情绪疾病易于复发的时段。"},{"type":"paragraph","text":"起居上宜「夜卧早起，广步于庭」，比之雨水可更早起身，务在顺应骤升之阳气；然惊蛰前后乍暖还寒，仍须「春捂」，不可因气温升高而骤脱厚衣，晨起、睡前尤其注意勿受寒湿。情志调摄最为关键：肝在志为怒，惊蛰肝气升发，最易动怒而致气机上逆，故宜戒躁怒、慎思虑，可借踏青、登山、放风筝、抚琴、赏花等方式疏泄肝气；郁证患者当主动寻求倾诉与专业帮助，切忌以「忍」为德。运动宜稍增量，但仍须渐进，可加入慢跑、登山、羽毛球等有氧活动至微汗为度，忌大汗淋漓与夜间强行锻炼。按摩上宜重在疏肝清肝：每日按揉太冲、行间、章门、期门各一分钟，以拇指垂直下压至明显酸胀；并以两拇指自印堂向两侧太阳穴作推按三十六次，舒展眉目以解头胀。饮食上宜「省酸增甘、疏肝清火」，忌辛辣燥烈与酒醋浓味，多食甘淡之品以养肝血。"},{"type":"table","caption":"惊蛰饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","甘平养肝血：枸杞子、桑椹、黑芝麻、百合、红枣、粳米","甘以缓肝，肝血充则肝气条达而不亢"],["宜食","清疏肝火：芹菜、菠菜、荠菜、菊花、玫瑰花、金银花（后三须辨证）","清而不苦寒，疏泄郁热，为春肝之要"],["忌食","辛燥升发：辣椒、烈酒、烧烤、羊肉、韭菜（过量）、油炸","辛散太过则肝气更亢，郁而化火生风"],["忌食","酸涩收敛：乌梅、石榴、话梅、山楂（过量）、酸奶（过量）","春肝气当升，过酸则郁遏气机，反增胀满"],["推荐食材","桑椹枸杞茶、芹菜炒香干、百合莲子粥、玫瑰花茶（须辨证）","一清一养，肝气条达而肝血得充"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「开肝式」：坐姿，两手交叠置于腹前，闭目调息，先缓慢深吸气三十六息，再缓缓呼气三十六息，呼气时意念将体内浊气由头顶徐徐呼出，共作九轮；随后起身，两脚开立，缓慢做左右转腰与上举双臂各九次。此式以呼吸升降带动肝气条达，最宜在晨起后或午后神疲气郁之时进行。穴位按揉取四处：一为太冲，位于足背第一、二跖骨结合部前凹陷，是肝经原穴，用拇指垂直按揉一分半钟至酸胀，为疏肝理气第一要穴；二为行间，位于足背第一、二趾间缝纹端，为肝经荥穴，按揉一分钟可清肝泻火；三为章门，位于侧腹部第十一肋游离端下方，为脾之募穴、肝经之穴，按揉一分钟可疏肝健脾、条达气机；四为太溪，位于内踝尖与跟骨之间凹陷，为肾经原穴，按揉一分钟可滋水涵木、防肝阳上亢。另可每日以两手拇指自眉心向两侧推按太阳穴三十六次，并闭目转睛三十六圈，以解头胀目赤。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"惊蛰阳升太过，最易引发以下病证：一是肝火上炎型头痛、眩晕、失眠、烦躁、高血压急性发作，多见目赤口苦、胁肋胀痛；二是过敏性疾病集中爆发，花粉、尘螨、真菌孢子等春季致敏原大量释放，过敏性鼻炎、哮喘、荨麻疹、湿疹患者症状常明显加重；三是「春困」与情绪障碍，表现为嗜睡、注意力涣散、抑郁焦虑，甚至出现季节性情感障碍；四是肝火犯胃所致的胃痛、泛酸、呕吐；五是带状疱疹、湿疹等皮肤病多发。预防要点：其一，有过敏体质者提前减少外出、备好抗过敏药物并遵医嘱使用；其二，保持情绪舒畅，避免生气、焦虑与熬夜，规律作息对预防季节性情绪问题尤为关键；其三，春季高发疾病应做到早发现、早诊断、早治疗，切勿自行滥用激素或抗生素；其四，饮食清淡，忌酒以免助火伤肝；其五，高血压、甲状腺疾病、肝胆疾病患者当于惊蛰前后特别复查一次相关指标，切勿因「春养」而自行停用降压药。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"惊蛰养生要点","items":["阳气骤升、肝气最旺，戒躁怒、慎思虑，宜踏青疏泄","仍须春捂，晨起与睡前尤其忌受寒湿","饮食省酸增甘、疏肝清火，忌辛辣燥烈与酒","按揉太冲、行间、章门、期门，配合转睛推按太阳穴","重点防肝火上炎、过敏爆发与春困情绪波动"]},{"type":"quote","text":"春雷响，万物长。","source":"民间农谚（惊蛰物候与农时之谚）"}]},{"id":"chunfen","title":"春分","subtitle":"3月20日—22日 · 春季","summary":"昼夜等长，阴阳各半，肝气与脾气升降相平。春分宜疏肝健脾、调和气血，起居上「早卧早起、规律三餐」，饮食上忌大热大寒，尤重养肝健脾。","blocks":[{"type":"paragraph","text":"春分是二十四节气中最重要的平衡节点，太阳黄经为0度，斗指壬，时在亥正与子初之间。此时全球昼夜几乎等长，此后北半球昼渐长、夜渐短，故有「春分秋分，日夜均而寒暑平」之说。《素问·阴阳应象大论》所谓「阴阳四时者，万物之根本也」，春分正是天地阴阳消长转换的枢机，此后阳气渐长、阴气渐消，人体亦当由「藏」转为「长」。物候上，《礼记·月令》记此时「玄鸟至，雷乃发声，始电」，燕子北归、始雷始电，是春季物候大定的标志；古人在春分日「竖蛋」之俗，亦取天地之气「相均」之义。人体方面，肝气升发与脾土运化自此进入相对平衡的阶段：肝气条达则情绪舒畅、筋骨舒展，脾运健旺则纳谷知味、精神充沛；但若肝气稍亢即可乘脾，出现腹胀、便溏、胁痛、乳胀，若脾失健运亦可致肝郁气滞，形成「木郁土壅」之局。此外春分前后气温明显回升而湿度仍高，是全年温差变化较快的时段之一，衣着失宜最易着凉。"},{"type":"paragraph","text":"起居上，《素问·四气调神大论》言春三月「夜卧早起，广步于庭」，春分之后可更进一步提早寝卧时间，但仍当以子时前入睡为度，且须保证每日睡眠七至八小时，不可因昼长而熬夜。晨起后宜到户外散步或做「广步于庭」之功，舒展全身而助气血流畅。衣着宜「洋葱式」增减，随时备一件薄外套，忌一脱到底。情志上，春分宜「志和而神静」，情绪宜平稳愉悦，最忌大起大落、大悲大喜；郁证与焦虑患者当借踏青、赏花、垂钓等户外活动养心怡神。运动宜渐增至中等强度，如快走、慢跑、太极、登山，每周不少于五次、每次三十分钟以上。按摩上宜取肝脾同调：每日按揉太冲、章门、足三里、三阴交各一分钟；并用双手掌根自胁肋向腹部作推揉三十六次，舒展肝气而助脾运。饮食上，春分寒热均半，最忌偏寒偏热，当以「甘平、淡渗、不过饥过饱」为原则。"},{"type":"table","caption":"春分饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","甘平调养：粳米、山药、百合、莲子、红枣、瘦肉、鸡蛋","不寒不热，甘缓平补，最合阴阳均平之时"],["宜食","疏肝理气：芹菜、菠菜、香菜、玫瑰花、佛手、陈皮（量宜小）","辛香疏散，条达肝气而不耗血"],["忌食","寒凉伤脾：刺身、冰饮、螃蟹、苦瓜（过量）、生冷蔬果","春分乍暖还寒，过寒则中阳受损"],["忌食","大热助火：烈酒、烧烤、羊肉、辣椒、煎炸、辛辣酱","辛辣助肝火，灼伤肝阴而升腾太过"],["推荐食材","芹菜炒香干、百合莲子粥、山药小米粥、玫瑰陈皮饮（须辨证）","疏肝与健脾并行，调和气血之枢"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「立身摩腹」式：两脚并拢直立，双手自然下垂，闭目调息三十六息，然后以左手掌根自左侧肋下缘向右下方推揉腹部九次，换右手同样推揉九次，共十八次；继而两手上举过头顶，掌心相对，脚跟提起，做九次提踵配合展体；最后缓慢下蹲与起身各九次。此式能疏通任冲带脉、调和肝脾、升发阳气，适合春分晨起后行之。穴位按揉取五处：一为膻中，两乳头连线中点，为气会，用掌根轻揉一分钟，宽胸理气、舒展情志；二为期门，乳头直下第六肋间隙，疏肝利胆一分钟；三为章门，侧腹第十一肋游离端下方，健脾疏肝一分钟；四为足三里，外膝眼下三寸，健脾益气一分半钟；五为三阴交，内踝尖上三寸、胫骨内侧缘后方，肝脾肾三经交会，养血调经一分钟。另可每日以两手拇指沿肋骨自上而下推按胸胁三十六次，舒展肝气、缓解胁胀。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"春分前后阴阳相搏，气候变化最为剧烈，病证亦最为复杂：一是旧疾复发的高峰期，高血压、糖尿病、冠心病、哮喘、胆囊炎、痛风等慢性病在此时因气温起伏与情绪波动而加重或急性发作；二是「春困」与失眠并存，昼倦夜难眠、注意力不集中，多与肝郁血虚有关；三是春季高发传染性疾病逐渐增多，如流感、流行性腮腺炎、水痘、麻疹等，儿童与青少年为高发人群；四是过敏性疾病持续高发，哮喘、过敏性鼻炎、荨麻疹、结膜炎多见；五是精神心理疾病，如抑郁症、焦虑障碍、失眠障碍呈季节性高发，女性尤甚。预防要点：其一，「春捂秋冻」不可生搬硬套于春分，此时寒热均半，关键是「随温变、慎增减」，尤其护住早晚与颈腹；其二，严格执行作息规律，尤其保证夜间睡眠，失眠与春困皆与作息紊乱密切相关；其三，慢性病用药不可自行增减，春季血压波动期尤应加强监测；其四，儿童应按时完成疫苗接种并保持居室通风；其五，持续情绪低落、兴趣丧失、失眠两周以上者当及时寻求精神心理专业帮助，切勿讳疾忌医；其六，一旦出现高热、持续咳嗽、胸痛、呼吸困难、意识改变等急症表现，须立即就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"春分养生要点","items":["昼夜等长、阴阳各半，起居宜规律而不过度耗散","衣着随温变增减，护住颈腹与早晚温差","饮食忌偏寒偏热，甘平调养、疏肝健脾并重","按揉膻中、期门、章门、足三里、三阴交并推揉胁肋","慢性病与精神心理疾病高发，用药与睡眠最关键"]},{"type":"quote","text":"故圣人春夏养阳，秋冬养阴，以从其根。故与万物沉浮于生长之门。","source":"《黄帝内经·素问·阴阳应象大论》"}]},{"id":"qingming","title":"清明","subtitle":"4月4日—6日 · 春季","summary":"气清景明，气候温和多风。清明宜祛湿浊、养肝明目，忌过食辛热与发物，慎防过敏性疾病与春困困倦、情志失调。","blocks":[{"type":"paragraph","text":"清明是二十四节气中唯一既是节气又是传统节日者，太阳黄经为15度，斗指乙，时在辰正与巳初之间。此时气温已明显回升，我国大部分地区日平均气温稳定在十至十五摄氏度之间，天朗气清、惠风和畅，「清明时节雨纷纷」的江南多雨，与北方干燥多风形成对照。物候上，《礼记·月令》载此时「桐始华，田鼠化为鴽」，桐树始发白花，鼷鼠出穴而变为鹌鹑；民间踏青扫墓、插柳植柳之俗亦取「顺时气、达阳气」之义。人体方面，此时阳气已盛而肝气偏亢，肝火上炎之目赤肿痛、口苦、头胀、烦躁仍较常见；春季多风，风性善行而数变，加之空气干燥、花粉浓度居高不下，最易诱发过敏性鼻炎、结膜炎、哮喘与皮肤瘙痒；另一方面，肝血渐耗而脾运渐旺，若饮食过于辛燥，则肝木受损而见目干、筋惕、指麻，妇女可见经量减少、周期紊乱。故清明养生当以「清」为纲——清肝火、清湿热、清肺气。"},{"type":"paragraph","text":"起居上宜夜卧早起、午间小憩，午休二十至三十分钟即可，过长则扰乱夜间睡眠而加重春困。踏青是清明最宜之事，缓行于山水之间既可舒展筋骨、疏泄肝气，又可接受柔和日光照射以调节褪黑素分泌，一举两得；但花粉浓度高者当避开花海与草地繁茂处，戴口罩与眼镜。衣着上仍宜「春捂」，但可适度减薄，戴一条薄围巾护颈背最合时宜。情志上宜舒缓淡泊，忌大悲大喜，扫墓追思若致情绪低落当主动倾诉疏解，勿使郁结内伤。运动宜户外为主，如徒步、慢跑、太极、放风筝，忌在花粉浓度极高的午后剧烈运动。按摩上宜清利头目：每日以拇指按揉太阳、印堂、风池、翳风各一分钟；以双手食指轻揉眼内外眦三十六次，再闭目转睛三十六圈；并以掌心搓热覆于腰背部，熨按命门与肾俞各一分钟。饮食宜清而不寒、淡而不寡。"},{"type":"table","caption":"清明饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","甘淡清润：粳米、薏苡仁、赤小豆、百合、莲子、冬瓜","淡渗清利，解春湿浊而不伤脾胃"],["宜食","清肝明目：桑叶、菊花、枸杞子、荠菜、菠菜、蒲公英（后二量宜小）","清肝火而明目，疏泄有余而不伤阴"],["忌食","辛热发物：羊肉、狗肉、烧烤、烈酒、辣椒、鹅肉","助肝火、动血，发物又易诱发过敏与旧疾"],["忌食","滋腻碍脾：肥肉、浓汤、糯米糕、奶油点心、蟹肥膏满","清明脾运方旺而肝火易亢，腻滞则助火碍运"],["推荐食材","桑叶菊花茶、荠菜豆腐羹、薏苡赤小豆粥、枸杞桑椹饮","清肝兼健脾，明目而不过寒"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「抱头推窗」式：两脚分开与肩同宽站立，双手十指相扣抱于后脑，闭目仰头，同时将上身向后仰，牵拉督脉与项部筋脉，保持呼吸三十六息后缓缓起身，共行九次；随后两手自然下垂，向左右侧屈腰部各九次。此式出自传统导引，能舒展颈项、缓解眼胀头痛、对治久视昏花。穴位按揉取五处：一为印堂，两眉之间，以拇指指腹轻揉一分钟，清利头目、安神定志；二为太阳，颞部眉梢与目外眦之间向后一横指凹陷，以拇指按揉一分钟至酸胀，解头胀目赤；三为风池，枕骨下胸锁乳突肌上缘凹陷，双手拇指相对按揉一分钟，疏风清头、醒脑明目；四为曲池，屈肘时横纹尽头，按揉一分钟，清热利湿、治痒抗敏；五为血海，髌骨内上缘上二寸，按揉一分钟，养血活血、缓瘾疹。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"清明时节最突出的健康风险有三：一是过敏性疾病的高峰，过敏性鼻炎、哮喘、过敏性结膜炎、荨麻疹、湿疹、过敏性紫癜患者症状常在此期明显加重，花粉与霉菌孢子是主要诱因；二是风湿类疾病多发或加重，因气候温和多风、湿度仍高，类风湿关节炎、强直性脊柱炎、痛风性关节炎患者关节肿痛频发；三是春季传染病高发，流感、水痘、猩红热、手足口病、经呼吸道传播者此期增加；四是情志障碍，包括季节性情感障碍、抑郁焦虑与「春困」性乏力；五是心脑血管意外，清明前后温差较大，加上假日作息紊乱与情绪激动，高血压、冠心病、脑卒中患者风险上升。预防要点：其一，过敏体质者应提前查明过敏原，日常避免接触，出门戴口罩、眼镜，回屋立即洗脸洗鼻并更换外衣，遵医嘱使用抗过敏药物，切勿自行长期使用激素；其二，风湿病患者注意关节保暖，忌冷水洗浴与久居湿地，遵医嘱用药；其三，儿童按时接种疫苗，居室常通风，流行期避免前往人群密集场所；其四，假日期间保持规律作息与适量运动，忌暴饮暴食与情绪激动；其五，出现胸痛、剧烈头痛、肢体麻木无力、口角歪斜、言语不清等中风或心梗征象，须立即拨打急救电话，切勿观望。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"清明养生要点","items":["气清景明，宜踏青缓行、午间小憩二十分钟","仍宜春捂但可适度减薄，围巾护颈背","饮食宜清润淡渗，忌辛热发物与滋腻碍脾","按揉印堂、太阳、风池、曲池、血海，配转睛推窗式","重点防过敏爆发、风湿关节痛、传染病与心脑血管意外"]},{"type":"quote","text":"冬傷於寒，春必溫病；春傷於風，夏生飧泄。","source":"《黄帝内经·素问·阴阳应象大论》"}]},{"id":"guyu","title":"谷雨","subtitle":"4月19日—21日 · 春季","summary":"雨生百谷，降水明显增多，湿气渐重而春季将尽。谷雨宜健脾祛湿、养肝明目，宜食健脾淡渗之品，忌过食生冷与久居湿地。","blocks":[{"type":"paragraph","text":"谷雨为春季最后一个节气，太阳黄经为30度，斗指壬，时在巳正与午初之间。此时「雨生百谷」，降水不但频而且量明显增多，农田得雨而谷物得生，故有此名。气候上，我国北方至此已明显升温，江南则进入连续阴雨的黄梅前期，湿度攀升极快，气温日较差缩小，人体出汗散热调节变难。物候上，《礼记·月令》载此时「萍始生，鸣鸠拂其羽，戴胜降于桑」，浮萍始生于水面，鸠鸟梳理羽毛，戴胜鸟出现于桑树间，是水湿渐盛、候鸟渐动的景象。对人体而言，谷雨节气最大的特点是「湿」。湿邪困脾，则纳呆、腹胀、便溏、头身困重、精神萎靡；湿性重浊黏滞，蒙蔽清窍则头昏如蒙、记忆减退，湿郁化热则生痤疮、湿疹、口舌生疮、、带下黄稠。肝气旺而脾受制，故此时既常见肝郁乘脾之胁胀便溏，也常见脾虚生湿之困倦乏力。加之春末气候多变，人体腠理开泄而卫外不固，感冒与过敏仍处高发。"},{"type":"paragraph","text":"起居上宜「夜卧早起」，但因昼长夜短，夜间更须避免熬夜，宜在子时前入眠，晨起后即使阴雨也宜在室内行舒展导引。居室宜常开通风以排湿，室内宜保持干燥，可置干燥剂或以除湿机调节湿度；被褥衣橱宜择晴日晾晒。衣着上春末已可适当减薄，但仍以「勿使大汗、勿受凉雨」为度，出汗后即换衣，淋雨后宜即换干衣并饮温水。情志上宜平和，湿浊最易阻滞气机而使情绪沉闷，故宜增加户外与社交活动，居室宜明亮，多接触阳光与绿植。运动宜选室内或雨歇时段，太极、八段锦、游泳、羽毛球皆宜，忌久坐不动。按摩上宜健脾利湿：按揉阴陵泉、足三里、脾俞、三阴交各一分钟；以拇指从足底涌泉穴向足跟方向推按三十六次，助阳气与水液运行；并以双手掌根在腹部作逆时针揉按三十六圈。饮食当以「淡渗健脾」为法，谷雨亦是宜食健脾安神、祛湿利水的当令佳品之期。"},{"type":"table","caption":"谷雨饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","淡渗健脾：薏苡仁、赤小豆、茯苓、冬瓜、白扁豆、豇豆","淡能渗湿，脾健则湿无所生"],["宜食","养肝明目：桑叶、枸杞子、黑芝麻、菊花、绿叶蔬菜","肝血充则目得所养，兼制湿热上扰"],["忌食","滋腻生湿：肥肉、浓肉汤、甜点、奶制品过量、糯米制品","滋腻助湿生痰，困阻脾阳"],["忌食","寒凉伤脾：冰饮、刺身、冰镇水果、久居空调加冷饮","外湿内寒，两寒相叠，最伤脾胃"],["推荐食材","薏苡赤小豆粥、茯苓薏苡仁粥、冬瓜薏仁汤、黑豆芡实汤","淡渗为谷雨养脾之正法"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「转腰导引」式：两脚开立与肩同宽，双手叉腰，先以腰部为轴作逆时针缓转九周，再顺时针九周，转至尽处稍作停顿；随后俯身以两手背于腰后，抬头挺胸作后仰伸展九次。此式能松动腰腹、疏通带脉、促进脾胃运化，最宜在谷雨湿重、身重困倦之时行之。穴位按揉取五处：一为阴陵泉，胫骨内侧髁下凹陷，脾经合穴，拇指垂直重按一分半钟，渗湿消肿；二为足三里，外膝眼下三寸，按揉一分半钟，健脾益气、扶正祛湿；三为脾俞，第十一胸椎棘突下旁开一寸半，按揉一分钟，健脾统血；四为三阴交，内踝尖上三寸、胫骨内侧缘后方，按揉一分钟，健脾利湿、养血调经；五为丰隆，外踝尖上八寸、胫骨前外侧两骨之间，痰湿偏盛者按揉一分钟，化痰除湿。亦可每日睡前以艾条温灸足三里与阴陵泉各十五分钟，助阳化湿。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"谷雨前后最需防范四类问题：一是消化系统疾病高发，急性胃肠炎、细菌性痢疾、急性胆囊炎、胰腺炎发作者增加，多因饮食不节、贪凉饮冷与湿热内蕴所致，表现为腹痛、腹泻、恶心、黄疸；二是风湿与代谢性疾病，湿热交蒸使痛风性关节炎急性发作人数明显增多，表现为单侧足第一跖趾关节剧痛红肿；三是皮肤与妇科炎症，湿疹、痤疮、玫瑰疹、带状疱疹、霉菌性阴道炎等在湿热季节多发；四是过敏与呼吸道疾病仍处高位，哮喘、过敏性鼻炎、感冒、支气管炎反复；五是情绪与睡眠障碍，湿浊蒙蔽清窍致头昏健忘、倦怠乏力，「春困」表现最重。预防要点：其一，饮食以温热熟透为原则，慎食生冷海鲜、凉拌菜与隔夜食物，食物须彻底加热；其二，严格控制高嘌呤、高脂肪饮食，限制饮酒，痛风患者每日饮水须在两千毫升以上并遵医嘱用药；其三，保持皮肤与会阴部清洁干爽，勤换内衣裤，湿疹与瘙痒者忌抓挠、忌热水烫洗，宜用温和无皂基洗剂；其四，雨天出行带伞避雨，淋湿后立即更换衣物、足部保持干燥，居室宜除湿；其五，适度运动以促进运化，但运动后须及时擦干换衣，忌大汗后吹空调；其六，出现持续高热、上腹剧痛、黄疸、关节红肿剧痛或呼吸困难者，须立即就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"谷雨养生要点","items":["湿气当盛，居室通风除湿、衣物被褥常晾晒","饮食淡渗健脾，忌滋腻生湿与一切生冷","转腰导引配按揉阴陵泉、足三里、脾俞、丰隆","淋雨后立即换衣，汗出后不吹空调","重点防胃肠炎、胆囊炎、痛风急性发作与湿热皮肤病"]},{"type":"quote","text":"粳米 味甘、苦、平、無毒。主益氣，止煩，止泄，和胃氣，長肌肉。","source":"《饮膳正要·卷三·米谷品》"}]},{"id":"lixia","title":"立夏","subtitle":"5月5日—7日 · 夏季","summary":"万物至此皆假大也，暑气将起而心气渐旺。立夏宜养心安神、清淡祛湿，忌燥烈辛辣与贪凉饮冷，慎防心悸、失眠与急性胃肠炎。","blocks":[{"type":"paragraph","text":"立夏是夏季的第一个节气，太阳黄经为45度，斗指巳，时在巳初与巳正之间。「立夏」之义，在于万物至此皆假大焉——《礼记·月令》记此时「蝼蝈鸣，蚯蚓出，王瓜生」，蛙声始作、蚯蚓出洞、牵牛藤蔓生发，正是暑热将起而万物竞长的征象。气候上，此期我国南北普遍进入初夏，日平均气温显著升高，长江中下游一带常出现连续阴雨的「黄梅天」，华南则已闷热多雷雨，人体汗孔开泄、腠理疏松而汗出增多，津液与阳气随之外泄。同时暑湿交蒸，湿邪困脾，常见胸脘痞闷、恶心纳呆、头身困重、大便溏薄。对人体生理而言，五脏之中心为夏脏，《素问·六节藏象论》谓心为「君主之官」，夏气通于心，心气旺则神明得养、精神振作；然心阳过亢或心火上炎，则见心烦、失眠、多梦、心悸、健忘、口舌生疮、舌尖红赤。夏季养心的要义，正在于既养其血、又清其火，更不可贪凉而伤脾。"},{"type":"paragraph","text":"起居上宜「夜卧早起，无厌于日」，但虽日照渐长，夜间仍当于子时前入睡，午间宜小憩二十至三十分钟以养心，忌睡得过久而扰乱夜间睡眠。居室宜通风而忌贪凉，空调温度不宜低于二十六度，且忌直吹人体；夜卧时宜在腹部与足部加盖薄被，护住「中焦」与「下焦」。情志上宜恬淡宁神，心为君主之官，志为心之所出，故夏宜「使志无怒，使华英成秀」，忌大喜大怒、忌多思多虑，可养花、赏荷、抄经、静坐以宁心。运动宜舒缓为主，如太极、游泳、慢走、八段锦，忌大汗淋漓与正午暴晒剧烈运动。按摩上宜养心安神：每日按揉神门、内关、心俞、印堂各一分钟；以掌根揉按胸前膻中穴一分钟，宽胸理气；并以两手拇指交替按揉两侧内关各一分钟，宁心安神、助眠。饮食上宜「淡渗祛湿、养心安神」，忌辛燥、忌油腻重味、忌冰凉。"},{"type":"table","caption":"立夏饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","养心安神：龙眼肉、百合、莲子、小米、粳米、瘦肉、鸡蛋","补心脾、益气血，为夏养心之基础"],["宜食","淡渗祛湿：薏苡仁、赤小豆、扁豆、冬瓜、丝瓜、苦瓜（适节）","湿为夏令主要病邪，淡渗则湿去"],["忌食","辛燥助火：辣椒、花椒、烈酒、烧烤、羊肉、韭菜（过量）","心火易亢，辛散太过则心烦失眠加重"],["忌食","冰冷伤脾：冰饮、冰淇淋、生鱼片、冰镇西瓜（过食）","暑热贪凉，最伤脾阳而腹泻纳呆"],["推荐食材","百合莲子粥、薏苡赤小豆粥、桂圆红枣茶、莲子心（极少量）","养心兼健脾，安神而不滋腻"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「养心式」：坐姿，两手交叠置于腹前，闭目调息，先以鼻吸三十六息，再以口缓缓呼出三十六息，呼气时意念全身气血自心经由小指、掌心、腕、臂内侧循行，舒展两臂向前推出再收，共九轮；随后睁目，以两掌互搓生热后覆于胸口轻摩三十六次。此式能宁心降火、疏通心经，安神助眠，尤宜在午后或睡前进行。穴位按揉取五处：一为神门，腕横纹尺侧、尺侧腕屈肌腱桡侧凹陷，按揉一分钟，养心安神、助眠；二为内关，腕横纹上二寸、两筋之间，按揉一分钟，宁心安神、和胃止呕、止泻；三为心俞，第五胸椎棘突下旁开一寸半，以掌根轻揉一分钟，益心气、宁心神；四为膻中，两乳头连线中点，掌根轻揉一分钟，宽胸理气、宁心；五为足三里，外膝眼下三寸，按揉一分半钟，健脾益气、扶助心脾。亦可每晚睡前以温水泡脚十五分钟，水温四十度左右，浸至踝上，助心肾相交而安眠。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"立夏之后，暑热渐盛而疾病谱随之改变：一是心脑血管疾病风险上升，高血压、冠心病、心律失常、心肌炎患者在高温高湿环境下因汗出过多、血液黏稠度升高与心脏负荷加重而易出现心悸、胸闷、胸痛乃至心梗、脑血管意外；二是急性胃肠炎与消化不良高发，多因贪食生冷、油腻或饮食不洁所致；三是「苦夏」现象，表现为持续食欲不振、乏力、消瘦、口渴而不多饮，多与胃肠功能低下及水电解质紊乱有关；四是睡眠障碍，暑热、湿热与情绪烦躁共同导致入睡困难、多梦易醒；五是皮肤与眼科问题，痤疮、湿疹、汗疹、眼部感染（俗称「红眼病」）在此时多发；六是被动物与虫类叮咬、毒蛇咬伤亦为夏季常见意外。预防要点：其一，避免高温时段外出劳作，居室通风并合理使用空调但不可贪凉；其二，饮食清淡洁净、生熟分开、隔夜食物彻底加热，忌大量生冷；其三，每日饮水一千五百至两千毫升以上，少量多次，可适量补充淡盐汤或含电解质饮品，心肾功能不全者须遵医嘱限水；其四，规律作息、午间小憩、避免情绪激动与通宵熬夜；其五，高血压与心脏病患者须加强血压与心率监测，按时服药，切勿自行停药；其六，出现胸痛、心悸、意识改变、剧烈头痛或昏厥等表现，须立即拨打急救电话。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"立夏养生要点","items":["夜卧早起、子时前入睡，午间小憩二十分钟","空调不直吹、夜卧护腹足，忌贪凉","饮食淡渗祛湿、养心安神，忌辛燥油腻冰冷","按揉神门、内关、心俞、膻中、足三里并温水泡脚","重点防心脑血管意外、急性胃肠炎、苦夏与失眠"]},{"type":"quote","text":"夏三月，此謂蕃秀。天地氣交，萬物華實，夜卧早起，無厭於日，使志無怒，使華英成秀，使氣得泄，若所愛在外，此夏氣之應，養長之道也。","source":"《黄帝内经·素问·四气调神大论》"}]},{"id":"xiaoman","title":"小满","subtitle":"5月20日—22日 · 夏季","summary":"麦粒渐满而未熟，暑热渐盛、湿气加重。小满宜健脾祛湿、和胃清热，饮食宜以淡渗为务，忌贪凉与厚味，防胃肠炎与湿疹痤疮。","blocks":[{"type":"paragraph","text":"小满为夏季第二个节气，太阳黄经为60度，斗指丙，时在午初与午正之间。《礼记·月令》载此时「苦菜秀，靡草死，麦秋至」，苦菜繁茂而柔弱之草枯死，麦子渐次成熟而进入灌浆期，「小满」之义正在于物候至此而未至于熟，是将盈未盈之态。我国南方自此进入连续阴雨的「黄梅天」，江淮之间雾气弥漫、空气湿度常在百分之九十以上；北方亦日渐炎热，昼夜温差缩小而夜间闷热不减。人体方面，小满一候湿气渐重，二候暑热渐显，三候麦类渐熟，正对应暑湿相搏的典型气候：暑为阳邪易耗气伤津，湿为阴邪易困脾遏阳，二者相合则最见身热不扬、头重如裹、胸脘痞闷、恶心纳呆、四肢酸软、大便溏薄、汗出而不畅。对心脏与心神的影响亦在此期凸显：暑湿上蒙清窍则头昏神倦、记忆减退，暑热扰心则心烦、失眠、多梦。此外湿热下注则带下黄稠、湿疹痤疮易发；暑湿困阻经脉则关节酸痛。"},{"type":"paragraph","text":"起居上宜「夜卧早起，无厌于日」，但暑湿重时更应注意夜间不可贪凉露宿，空调温度不低于二十六度且不直吹，卧时腹部与足部加盖薄被，晨起时勿因凉而骤关空调而受闷热夹寒。居室宜通风除湿，可于雨后开窗对流，潮湿衣物须烘干后再穿。情志上宜「使志无怒」，心火与暑湿相扰则易烦躁，须以静养、慢行、赏荷、闻香等怡情之法疏泄；避免长时间处于嘈杂环境与激烈争执。运动宜选清晨或傍晚凉爽时段，以散步、太极、游泳、慢跑为主，量以微汗为度，忌正午暴晒与汗后即冲凉水澡。按摩上宜健脾化湿：每日按揉足三里、丰隆、阴陵泉、脾俞各一分钟；以两掌相对搓热后以掌根揉按腹部脐周三十六圈；并以拇指从涌泉向足跟推按三十六次。饮食上宜清淡祛湿、健脾和胃，《饮膳正要·卷二·四时所宜》谓「夏气热，宜食菽，以寒之，不可一于热也」，即夏宜以寒凉之品调节，但不可贪凉过度而反伤脾胃。"},{"type":"table","caption":"小满饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","淡渗健脾：薏苡仁、赤小豆、冬瓜、丝瓜、白扁豆、绿豆（适量）","渗湿健脾，为暑湿之月的正法"],["宜食","清热生津：冬瓜、丝瓜、苦瓜、绿豆芽、荸荠、梨","清暑热而生津，但须性凉而不伤脾"],["忌食","滋腻厚味：肥肉、浓肉汤、油炸、奶油甜品、粽子（过量）","碍脾生湿，湿上加湿则困重更甚"],["忌食","冰凉过度：冰饮、冰淇淋、生腌、隔夜凉菜","外暑内寒，胃肠激惹而腹痛吐泻"],["推荐食材","冬瓜薏仁汤、丝瓜瘦肉汤、赤小豆冬瓜汤、绿豆百合粥（须辨证）","清热不伤脾，渗湿不伤阴"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·鹿戏」：两脚开立，屈膝下蹲成马步，双手虚握于腹前，鹿角戏先两臂内旋、外旋交替画圈九次，再腰部带动作环转九周。此式取鹿之矫健，功在强腰健肾、舒展筋骨，尤宜在暑湿困身、腰膝酸软之时循序练习。穴位按揉取五处：一为足三里，外膝眼下三寸，拇指按揉一分半钟，健脾和胃、扶正祛湿；二为丰隆，外踝尖上八寸、胫骨前外侧两骨之间，按揉一分钟，化痰除湿，为治痰湿要穴；三为阴陵泉，胫骨内侧髁下凹陷，按揉一分半钟，渗湿消肿；四为三阴交，内踝尖上三寸、胫骨内侧缘后方，按揉一分钟，健脾利湿、养血调经；五为内关，腕横纹上二寸两筋之间，按揉一分钟，和胃止呕、宁心安神，暑湿犯胃而呕恶者尤宜。亦可每日以手掌摩擦小腿内侧至足下，搓热后以掌心敷于涌泉一分钟，引火归元、助眠。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"小满前后「暑湿相搏」为最主要的病机特点，相关病证集中：一是消化系统疾病高发，急性胃肠炎、细菌性痢疾、急性胆囊炎、食物中毒频发，表现为腹痛、呕吐、腹泻、发热，多因贪凉饮冷与饮食不洁；二是「苦夏」与电解质紊乱，表现为持续食欲下降、口黏乏力、头晕心悸，多见于中老年与慢性病患者，因汗出过多与电解质丢失；三是皮肤疾病高发，湿疹、痤疮、痱子、接触性皮炎、真菌感染在湿热环境下明显增多；四是蚊虫叮咬、虫媒传染病（登革热、疟疾、流行性乙型脑炎）进入高风险期；五是风湿与关节病，湿寒夹杂使膝关节炎、痛风发作增加；六是心理与睡眠问题，烦躁、失眠、焦虑在长夏多见。预防要点：其一，饮食以温热熟透为原则，凉拌菜须现拌现食，剩菜彻底加热，禁食生腌与隔夜凉拌；其二，汗多者须补充水分与电解质，可饮淡盐水或含钾饮品，高血压、肾功能不全者遵医嘱；其三，皮肤保持清洁干爽，褶皱处每日擦干，湿疹忌热水烫洗与搔抓，宜用温和洗剂并遵医嘱用药；其四，居室纱窗防蚊，清理积水灭蚊虫，野外活动穿长袖长裤并使用驱蚊剂；其五，空调温度宜二十六度左右，室内外温差不超过七度，出汗后先擦干再入空调房；其六，出现持续高热不退、剧烈腹痛、频繁呕吐脱水、意识改变者须立即就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"小满养生要点","items":["黄梅天湿重，居室通风除湿、衣物须烘干","夜间不贪凉露宿，空调不直吹并护腹足","饮食清热不伤脾、渗湿不伤阴，忌厚味与冰凉","按揉足三里、丰隆、阴陵泉、三阴交、内关","重点防胃肠炎、苦夏、湿疹痤疮与蚊媒传染病"]},{"type":"quote","text":"夏氣熱，宜食菽，以寒之，不可一於熱也。禁溫飲食，飽食，濕地，濡衣服。","source":"《饮膳正要·卷二·四时所宜》"}]},{"id":"mangzhong","title":"芒种","subtitle":"6月5日—7日 · 夏季","summary":"麦类有芒可种，忙于夏收夏种。芒种暑湿交蒸而肝火易旺，宜清利湿热、疏肝解郁，饮食以淡渗清补为要，慎防中暑与胃肠疾病。","blocks":[{"type":"paragraph","text":"芒种为夏季第三个节气，太阳黄经为75度，斗指午，时在午正与未初之间。此时长江中下游进入「梅雨」盛期，江南麦收、稻种并忙，故农谚有「芒种忙忙种」之说。《礼记·月令》载此时「螳螂生，鵙始鸣，反舌无声」，螳螂初生、伯劳始鸣而反舌鸟止声，三物候相应而次第有别，是物候严谨有序之征。气候上，此时我国南北普遍进入高温高湿的盛夏，长江流域梅雨未已而华南已现高温，暑湿交蒸之势最为典型，湿气在人体内郁滞不去，腠理虽开而汗出不畅，形成「暑湿相搏」的经典格局。对人体而言，此时心火与脾湿同为病理焦点：暑热伤心则心烦、失眠、多梦、口舌生疮、小便短赤；湿困脾阳则纳呆、脘痞、恶心、身重困倦、大便溏泄、头昏如蒙；湿热下注则带下黄稠、湿疹、痤疮、疖肿。脾胃虚弱者尤易在此时出现「长夏不调」，而气阴两虚的老年人、儿童则更易中暑。"},{"type":"paragraph","text":"起居上宜「夜卧早起，无厌于日」，但夜间当严防暑湿侵袭，室温不宜低于二十六度，亦不宜过高过闷，卧时宜盖薄被护住腹部。汗出后不可即刻吹风扇、洗冷水澡或卧于阴凉之地，须先擦干汗、静坐片刻。情志上，暑热最易烦躁而心火上炎，故宜静养为先，忌争强好胜、忌大汗淋漓后暴怒；可作书写、抚琴、种花、垂钓之事以静其心。运动宜移至清晨与傍晚，避开上午十时至下午四时的强日照与高温高湿时段，以游泳、太极、慢跑、散步为宜，量以微汗为度；运动中若出现头晕、恶心、心悸、视物模糊，即为中暑先兆，应立即停止并移至阴凉处。按摩上宜清心利湿：按揉内关、神门、曲池、阴陵泉、足三里各一分钟；以掌根揉按曲池三圈，以拇指按压合谷与外关各一分钟，舒解头身；并以两手拇指自印堂推至太阳三十六次。饮食上宜淡渗清利、健脾养心，忌辛辣油腻、忌温燥、忌冰凉。"},{"type":"table","caption":"芒种饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","淡渗清暑：薏苡仁、赤小豆、冬瓜、绿豆、丝瓜、苦瓜、莲子","暑湿并盛，淡渗清利是为正法"],["宜食","清心养神：百合、莲子心（极少量）、龙眼肉、小米、粳米","养心安神而不滋腻，清心而不苦寒太过"],["忌食","温燥助火：羊肉、狗肉、烧烤、烈酒、辣椒、核桃（过量）","暑热之时温燥助心火，烦躁失眠加重"],["忌食","肥甘壅湿：肥肉、浓汤、糯米糕、奶油点心、含糖饮料","助湿生痰，困脾而增身重"],["推荐食材","冬瓜薏仁汤、绿豆百合粥（须辨证）、丝瓜瘦肉汤、莲子百合汤","清热利湿兼养心脾，暑湿两清"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·熊戏」：两脚开立成马步，双手握拳置于腹前，屈膝上提后落，模仿熊的笨拙与沉稳，共九次；继而左右转体各九次。此式取熊之厚重，功在健脾益气、舒展腰腹，最宜在暑湿困身、脾胃失健时以缓行之。穴位按揉取五处：一为曲池，屈肘时横纹尽头，以拇指按揉一分钟，清热利湿、舒筋止痛，为夏热要穴；二为合谷，手背第一、二掌骨间，约平第二掌骨中点，按揉一分钟，解表清热、醒脑开窍；三为外关，腕横纹上二寸、两骨之间，按揉一分钟，清热解表、舒筋活络；四为阴陵泉，胫骨内侧髁下凹陷，按揉一分半钟，渗湿消肿；五为内关，腕横纹上二寸两筋之间，按揉一分钟，宁心安神、和胃止呕。亦可每日以手掌拍打大腿外侧三十遍，震动胆经以助疏泄。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"芒种前后，暑热与湿邪俱盛，须重点防范六类病证：一是中暑，包括先兆中暑（头晕、乏力、多汗、口渴、恶心）与重症中暑（高热、抽搐、昏迷、日射病与热射病），老人、儿童、肥胖者、户外作业者与慢性病患者为高危；二是急性胃肠炎与细菌性痢疾，饮食不洁与贪凉所致；三是蚊媒传染病高发，登革热、疟疾、流行性乙型脑炎均在此期流行，四肢麻木、皮疹、出血、意识改变为危险征象；四是电解质紊乱与「苦夏」表现，见大量出汗后乏力、头晕、心悸、肌肉痉挛；五是痤疮、疖肿、湿疹、毛囊炎等皮肤感染明显增多；六是心血管事件，高温下汗出过多致血液浓缩，心梗、脑卒中风险上升。预防要点：其一，高温时段避免户外劳作，户外作业须戴宽檐帽、穿浅色宽松衣物、备足含盐清凉饮料，并轮换休息；其二，出现头晕恶心即停止活动、移至阴凉通风处、平卧抬高下肢并补充含盐饮品，意识不清者切忌强行喂水，应立即拨打急救电话；其三，居室空调温度宜二十六度左右，室内外温差不超过七度，汗出后先擦干；其四，饮食清淡洁净、生熟分开，隔夜菜彻底加热，禁食生冷海鲜与凉拌隔夜菜；其五，清理居室积水、纱窗防蚊，户外使用驱蚊剂；其六，高血压、糖尿病、冠心病患者在高温期须加强监测，不可自行减药或停药，出现胸痛、持续大汗、意识改变须立即就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"芒种养生要点","items":["避开十时至十六时高温高湿时段运动，微汗为度","汗后不吹风、不洗冷水澡，居室空调不直吹","饮食淡渗清暑兼养心，忌温燥与肥甘","按揉曲池、合谷、外关、阴陵泉、内关","重点防中暑、蚊媒传染病、胃肠炎与心血管事件"]},{"type":"quote","text":"夏傷於暑，秋必痎瘧。","source":"《黄帝内经·素问·阴阳应象大论》"}]},{"id":"xiazhi","title":"夏至","subtitle":"6月21日—22日 · 夏季","summary":"日长之至、影短之至，一阴初生。暑热至极而阳气亦至极，养生宜「冬病夏治」与静心养阴，忌贪凉过甚、以热制热。","blocks":[{"type":"paragraph","text":"夏至是二十四节气中最早被确定的一节气，太阳黄经为90度，斗指癸，时在未初与未正之间。此日太阳直射北回归线，北半球白昼最长、黑夜最短，古人有「日长之至，日影短之至」之称；此后太阳直射点南移，昼渐短而夜渐长，「一阴生」即由此起，此后阴气始生而阳气渐衰，中医谓之「阳极阴生」，是全年阴阳转换的枢机。物候上，《礼记·月令》载此时「鹿角解，蜩始鸣，半夏生」，鹿角开始脱落、蝉声初起、半夏等夏生药材渐次出苗，正合暑气蒸腾、草木繁盛之象。气候上，我国多地进入全年最热时段，长江流域「出梅」而伏旱初现，江南梅雨与华北酷暑交替，人体腠理大开、汗液大量外泄，津气随汗而耗，故暑伤气、暑伤津成为此期最突出的病理；而暑热方盛之时，阳气亦达于极处，贪凉过度则遏伏阳气，至秋后易生伏寒。尤须留意此期阳盛而阴伤，心肾不交、水火不济之象渐显，失眠、心烦、口干、腰膝酸软者较他时为多。"},{"type":"paragraph","text":"起居上虽曰「无厌于日」，然夏至日最长，夜间仍当早卧早起、于子时前入眠，午间小憩二十至三十分钟，忌日间长睡。居室宜通风与遮阳，帘幕宜遮西晒之窗，空调温度宜二十六度上下，切忌贪凉而使室内外温差过大、夜间裸露腹部与足部；入睡前可用温水泡脚一刻钟以助阳入阴。情志上，《素问·四气调神大论》言夏三月「使志无怒，使华英成秀，使气得泄，若所爱在外」，宜将心神向外舒展，多接触自然与亲友，忌郁怒与强行克己；心烦失眠者可作静坐、呼吸吐纳。运动宜晨昏为之，且宜柔缓，如太极、游泳、散步、导引，不宜在烈日下练功；「冬病夏治」的哮喘、慢性支气管炎、过敏性鼻炎患者，可在医师指导下于三伏前开始贴敷与艾灸。按摩上宜交通心肾：每日按揉涌泉、太溪、神门、内关各一分钟；以掌根揉按关元与气海各一分钟；并以两脚心相搓至热，覆于腹部丹田处三十六息，助水火既济。饮食上宜清淡而多汁多水，忌辛辣炙煿，忌过食冰冷。"},{"type":"table","caption":"夏至饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","养阴生津：百合、麦冬、沙参、玉竹、桑葚、鸭肉、牛奶","夏至一阴初生，宜养阴以备秋燥"],["宜食","淡渗清暑：冬瓜、丝瓜、薏苡仁、赤小豆、绿豆、苦瓜","解暑而不伤脾，为夏至祛暑之正法"],["忌食","温燥助热：羊肉、狗肉、烧烤、烈酒、辣椒、核桃（过量）","夏至阳气已极，再助热则耗气伤津"],["忌食","冰寒伤阳：冰饮、冰淇淋、生腌、冰镇西瓜（过食）","贪凉遏阳，至秋易生伏寒之疾"],["推荐食材","百合莲子粥、麦冬玉竹粥（须辨证）、冬瓜薏仁汤、桑葚饮","养阴与清暑并行，为一阴初生之宜"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·鸟戏」：两脚开立，吸气时两臂自下向前上举过头顶，抬头目视上方，呼气时两臂下落于体侧，同时上提脚跟，共九次；继而左右展开两臂作扑翼状交替扇动三十六次。此式取鸟之轻灵伸展，功在宣通肺气、舒展筋脉，最宜在夏至阳气极盛、晨间阳气初升之时行之。穴位按揉取五处：一为涌泉，足心前三分之一凹陷，为肾经井穴，睡前以拇指按揉一分半钟至酸胀，引火归元、交通心肾、安神助眠；二为太溪，内踝尖与跟骨之间凹陷，肾经原穴，按揉一分钟，滋肾阴、纳浮阳；三为神门，腕横纹尺侧凹陷，按揉一分钟，养心安神；四为关元，脐下三寸，掌根揉按一分钟，温补肾阳、培元固本；五为中脘，脐上四寸，掌根揉按一分钟，和胃降逆、化湿消胀。亦可于夜间以艾条温灸足三里、涌泉各十五分钟，为冬病夏治之常法，须遵医嘱。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"夏至为全年阳热之极，须重点防范：一是热射病与重症中暑，特点是高热、无汗、意识障碍、抽搐，死亡率极高，老人、儿童、慢性病患者、户外作业者为高危，一旦出现须立即拨打急救电话并迅速物理降温；二是心脑血管意外，暑热使汗出过多、血液黏稠度增加，心梗、脑卒中、肝硬化门脉高压出血风险上升；三是泌尿系统疾病，汗多而饮水不足、尿液浓缩，尿路结石与急性肾损伤多见；四是消化道疾病，急性胃肠炎、细菌性痢疾高发；五是「夏季热」（婴儿夏季热）与老年性中暑，多见于体弱儿童与老人；六是失眠与心烦，暑热扰心、心肾不交所致，尤在午后与夜间为甚；七是急性结膜炎与睑缘炎俗称「红眼病」，在泳池、公共场所高发。预防要点：其一，避免正午暴晒与高温劳作，备足含盐饮料，出现中暑先兆立即停歇；其二，重症中暑者应迅速移至阴凉处、脱去多余衣物、以凉水擦拭全身并扇风，同时拨打急救电话，切勿自行喂水给意识不清者；其三，晨起与睡前测量血压，高危人群遵医嘱调整用药，切勿自行减药；其四，每日饮水一千五百至二千毫升以上，可饮淡盐水、荷叶水或西瓜翠衣汤（须辨证），心肾功能不全者限水遵医嘱；其五，注意个人卫生与眼部清洁，泳池须戴泳镜、不共用毛巾；其六，居室空调与风扇配合使用，避免室内外温差过大；其七，失眠与心烦持续者宜及时就诊中医或睡眠门诊，切勿自行长期服用安眠药。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"夏至养生要点","items":["昼最长而阳气亦极，夜仍须子时前入睡","贪凉过度最易遏阳，空调不直吹、护住腹足","饮食宜养阴生津兼清暑，忌温燥亦忌过冰","按揉涌泉、太溪、神门、关元、中脘，搓足心助眠","重点防热射病、心脑血管意外与结石、失眠"]},{"type":"quote","text":"使志無怒，使華英成秀，使氣得泄，若所愛在外。","source":"《黄帝内经·素问·四气调神大论》"}]},{"id":"xiaoshu","title":"小暑","subtitle":"7月6日—8日 · 夏季","summary":"温风至而暑热渐盛，湿热交蒸始为炽。小暑宜清暑益气、养阴生津，饮食宜淡而多汤，忌贪凉暴饮，以防中暑与胃肠病。","blocks":[{"type":"paragraph","text":"小暑为夏季第四个节气，太阳黄经为105度，斗指庚，时在未正与申初之间。此时暑热渐盛而南方梅雨方殷，《礼记·月令》载此时「温风至，蟋蟀居壁，鹰始挚」，温风携热而至、蟋蟀由田野趋居墙隙、鹰开始捕猎教雏，三候皆示暑气与生机并行。气候上，长江中下游「出梅」而暑热骤升，江南多伏旱，岭南、江南与华北南部进入高温高湿的「桑拿天」；人体腠理大开而汗孔疏泄，汗出如浆，气随津脱而阳随汗泄，故暑气伤人最易耗气伤津。此期人体还面临两个特殊挑战：其一，暑湿相合使汗出不畅，湿邪留著肌表，常见身热不扬、汗黏不透、胸脘痞闷、身重如裹；其二，暑热迫津下泄而小肠与膀胱受热，「暑湿下注」则见尿频、尿急、尿痛、便溏、下肢浮肿，妇女则见带下增多、味重色黄。此外暑热耗伤心气心血，心悸、气短、失眠与「暑厥」皆与此有关。老年人、儿童与慢性病患者在此时最易出现中暑与「热射病」，须格外留意。"},{"type":"paragraph","text":"起居上宜夜卧早起，晨起后趁气温未高时作户外活动，午间务必避暑休息，不宜在正午外出办事；夜间虽热亦不可贪凉露宿、不可赤膊敞怀而卧，空调宜二十六度左右并设睡眠模式，晨起时先开窗通风片刻。居室宜遮阳、通风，必要时使用除湿与加湿设备相配合，室内宜保持干爽。情志上，暑热最耗心神，宜恬淡自守，忌急躁、忌大喜大悲、忌通宵熬夜耗伤心气；心烦者可作静坐与深呼吸，并于午间小憩养心。运动宜于清晨或日落后进行，以游泳、散步、太极、导引为佳，忌烈日下运动；运动量宜小、次数宜多，量以微微汗出为度，若出现头晕、心悸、恶心、肢麻即须立即停止。按摩上宜清暑益气：每日按揉足三里、丰隆、阴陵泉、神门、内关各一分钟；以两掌搓热后互摩腰眼各一分钟；以指尖按压大椎、风池各一分钟，解暑醒脑。饮食上宜清淡、宜多汤水、少油少盐，宜以「热者寒之」为法而不可过寒。"},{"type":"table","caption":"小暑饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","清暑益气：绿豆、冬瓜、丝瓜、苦瓜、荷叶、莲子、扁豆","清热而益气养津，为暑日之要品"],["宜食","生津养阴：绿豆百合粥（须辨证）、麦冬、玉竹、桑葚、鸭肉","暑伤津液，宜清润以复其阴"],["忌食","辛辣油腻：烧烤、火锅、肥肠、烈酒、油炸、麻辣烫","助热伤津，且油腻碍脾而生湿"],["忌食","冰寒暴饮：冰啤、冰淇淋、生腌、冰镇饮料大量饮用","骤伤脾胃阳气而吐泻腹痛"],["推荐食材","冬瓜薏仁汤、绿豆百合粥（须辨证）、荷叶粥、丝瓜蛋汤","清暑而不伤脾，为小暑之宜"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「小暑·摇扇散热式」：两脚开立，双手持轻扇（或以掌代扇），随呼吸缓慢摇扇三十六次，同时作深长呼吸；继而以两掌交搓生热，覆于脐上静坐九轮。此式以摇扇配合腹式呼吸，能加快体表散热、调理呼吸节律，为暑日最实用的消暑导引。穴位按揉取五处：一为大椎，第七颈椎棘突下凹陷，以拇指或食中二指按揉一分钟，为清热解暑之要穴；二为风池，枕骨下凹陷，按揉一分钟，祛风醒脑、缓解头昏；三为足三里，外膝眼下三寸，按揉一分半钟，健脾益气、扶正祛暑；四为丰隆，外踝尖上八寸，按揉一分钟，化痰除湿、和胃降逆；五为阴陵泉，胫骨内侧髁下凹陷，按揉一分半钟，渗湿消肿。亦可每日以掌根揉按脐上四寸处一分钟，并顺时针摩腹三十六圈，助脾胃运化而免暑湿困脾。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"小暑以后暑热正式当令，须重点防范：一、中暑与热射病，体温调节中枢功能不全的老人、婴幼儿、肥胖者、户外作业者、慢性病患者为高危，热射病出现高热、皮肤灼热而无汗、意识模糊、抽搐者，死亡率极高，须立即拨打急救电话；二、急性胃肠炎与细菌性痢疾，贪凉暴饮与饮食不洁所致；三、泌尿系感染与结石，暑热蒸腾、汗多尿少而尿液浓缩，出现尿频尿急尿痛、腰腹绞痛者须就医；四、蚊媒传染病，登革热、疟疾流行，突发高热、皮疹、肌肉关节痛、出血倾向须即就医；五、心脑血管疾病，血压波动、心肌缺血、脑血管意外多见；六、痤疮、疖肿、毛囊炎、湿疹等皮肤病高发；七、眼部与耳鼻喉疾病，急性结膜炎、化脓性中耳炎、鼻窦炎多见；八、老年人「夏季热」与婴幼儿夏季热，表现为持续发热而体温随环境波动，伴口渴、多尿、少汗。预防要点：其一，高温时段严格减少外出与劳作，备宽檐帽、遮阳伞与含盐饮料；其二，出现头晕、恶心、心悸、乏力、多汗即为中暑先兆，须立即停止活动、移至阴凉通风处并补充含盐饮品；其三，重症中暑切勿给意识不清者喂水，须迅速降温并呼救；其四，饮食清淡洁净，多食蔬菜汤羹，瓜果洗净去皮，冰饮适量而不贪；其五，居室通风遮阳，空调与风扇配合，室内外温差不超过七度；其六，糖尿病患者在高温下易发生「中暑无症状低血糖」，须定时监测血糖并随身携带糖果，出现心悸、乏力、出冷汗时立即补糖；其七，心血管疾病患者在高温期须加强监测，不可自行减药或停药。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"小暑养生要点","items":["正午避暑，晨昏活动，空调二十六度不直吹","摇扇配深呼吸散热，午间小憩养心","饮食清淡多汤水，益气养津而不贪寒","按揉大椎、风池、足三里、丰隆、阴陵泉","重点防热射病、尿路结石、蚊媒传染病与低血糖"]},{"type":"quote","text":"綠豆 味甘、寒、無毒。主丹毒，煩熱，和五臟，行經脉。","source":"《饮膳正要·卷三·米谷品》"}]},{"id":"dashu","title":"大暑","subtitle":"7月22日—24日 · 夏季","summary":"暑气至此而极盛，湿热交蒸至极。大暑宜清暑益气、健脾养阴，忌贪凉与厚味，重点防范中暑、心脑血管病与脾胃急症。","blocks":[{"type":"paragraph","text":"大暑为夏季第五个节气，亦是全年最热的节气，太阳黄经为120度，斗指丙，时在申初与申正之间。《礼记·月令》载此时「腐草为萤，土润溽暑，大雨时行」，腐草间萤火虫出、土壤潮湿闷热、大雨时作，三候皆为暑湿大盛之征。我国多地自此进入一年中最热阶段，长江流域「七下八上」主汛期，暴雨与高温交替，湿热交蒸之烈达到极处；东北、西北亦进入酷暑。人体在此时处于「暑、湿、耗、扰」四重叠加之下：暑为阳邪，其性炎热升散，迫津外泄而气随津脱，故汗出过多、气短乏力；湿为阴邪，重浊黏滞，阻遏气机与阳气，故头重如裹、胸脘痞闷、身重肢倦、汗黏不干；暑湿相搏，郁于肌肤则生痱子、湿疹、脓疱，郁于中焦则脾胃失运而纳呆呕恶，郁于下焦则尿赤、便溏、带下黄稠。此外暑热扰心则心烦、失眠、多梦；汗出过多而血容量下降，则心悸、气短，甚至诱发心绞痛与心衰；老年人与慢性病患者的耐热能力下降，中暑风险在此时最高。"},{"type":"paragraph","text":"起居上仍宜夜卧早起，但大暑之时当以「避暑」为第一要务：上午十时至下午四时尽量不外出，居室宜遮阳、通风并合理使用空调与风扇，夜间亦不可贪凉而使室温过低，尤须护住腹部与足部；汗出过多时宜及时更换衣物、补充水分与电解质，不可因口渴不甚而少饮。情志上，暑热扰心最易烦躁失眠，宜「静能生热」，减少喧闹与剧烈情绪波动，可作静坐、书写、垂钓、闻香；忌用冷水冲头、忌大汗淋漓后骤然受凉。运动宜取清晨与夜间的散步、太极、游泳，日间则宜室内导引，不宜作大强度训练。按摩上宜清暑益气：每日按揉足三里、大椎、曲池、阴陵泉、丰隆各一分钟；以掌根轻揉脐上四寸处一分钟；以双手轻叩腰部命门两侧各三十六次。饮食上宜「淡、凉、软、润」：多汤羹、多瓜果蔬菜，忌肥甘厚味与温燥，忌冰凉过度，《饮膳正要》谓「夏气热，宜食菽，以寒之，不可一于热也」，然「不可一于」者，即不可全然寒凉而伤中阳。"},{"type":"table","caption":"大暑饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","清暑益气生津：绿豆、冬瓜、丝瓜、苦瓜、黄瓜、荷叶、莲子","暑热至极，非清热不能解其标"],["宜食","健脾益气：山药、白扁豆、薏苡仁、莲子、粳米、瘦肉","暑伤气耗津，须以甘淡益气以善后"],["忌食","肥甘厚味：肥肉、烧烤、油炸、浓汤、奶油点心、甜饮","助湿生热，加重脾胃与心脉负担"],["忌食","过寒之物：冰镇饮品、大量生冷海鲜、冰西瓜连食","骤伤脾阳，吐泻腹痛，且遏阳不散"],["推荐食材","冬瓜薏仁汤、绿豆百合粥（须辨证）、荷叶扁豆粥、绿豆丝瓜汤","清暑与益气并行，标本兼顾"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「大暑·静坐散热式」：择阴凉通风处或空调室内，盘膝而坐，两手置于膝上，闭目静养，先以鼻吸缓而深、至腹满，再以口徐徐呼出，意守下腹，吸三十六息、呼三十六息，共九轮；继而睁目，两手自然下垂，缓慢做左右转腰各九次。此式重在「静」与「缓」，能减低交感神经兴奋、帮助散热安神，最宜午后暑热最盛之时于室内进行。穴位按揉取五处：一为大椎，第七颈椎棘突下凹陷，以拇指垂直按揉一分钟，为解暑清热第一要穴；二为曲池，屈肘时横纹尽头，按揉一分钟，清热利湿、舒筋；三为足三里，外膝眼下三寸，按揉一分半钟，健脾益气、扶正；三为阴陵泉，胫骨内侧髁下凹陷，按揉一分半钟，渗湿消肿；四为内关，腕横纹上二寸两筋之间，按揉一分钟，宁心降逆、和胃止呕。亦可用鲜荷叶、鲜竹叶各适量煮水代茶，频饮以清暑。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"大暑是全年急性疾病的高峰期，须重点防范：一、重症中暑与热射病，特点是高热、无汗、意识障碍与凝血异常，老年人、婴幼儿、慢性病患者、慢性肾病患者、糖尿病患者为极高危，死亡率可达百分之二十以上，一旦出现须立即拨打急救电话，切勿自行喂水给意识不清者；二、心脑血管意外，汗出过多致血液浓缩、血压波动，心绞痛、心肌梗死、脑卒中、急性左心衰在此期频发；三、急性胃肠炎、细菌性痢疾与急性胆囊炎、胰腺炎，饮食不洁与贪凉所致；四、泌尿系统疾病，尿路结石、急性肾损伤、感染性肾炎多见；五、皮肤与五官科疾病，痱子、湿疹、脓疱疖肿、化脓性中耳炎、急性结膜炎高发；六、蚊媒传染病，登革热、疟疾、流行性乙型脑炎进入高发；七、精神与神经症状，暑热烦躁、失眠、焦虑，甚至「暑厥」；八、糖尿病患者高温下低血糖事件显著增加。预防要点：其一，最高温时段绝对避免外出，家中无空调者宜前往公共纳凉场所或使用风扇与凉席加强散热；其二，居室通风遮阳，空调温度宜二十六度，室内外温差不超过七度，睡眠时注意护腹护足；其三，每日饮水一千五百至二千毫升以上，汗多者适当补充淡盐水或含电解质饮品，心肾功能不全者限水遵医嘱；其四，饮食清淡洁净，现做现食，隔夜菜彻底加热，禁食生冷与凉拌隔夜菜；其五，高血压、糖尿病、冠心病患者须加强监测与按时用药，切勿因天热自行停药；其六，糖尿病患者随身携带糖果，定时监测血糖，出现心悸、乏力、出冷汗立即测糖并补糖；其七，出现高热、意识改变、胸痛、呼吸困难、少尿者须立即就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"大暑养生要点","items":["十时至十六时绝对避暑，居室通风遮阳合理用空调","汗出即换衣补水补盐，护住腹部与足部","饮食淡凉软润、清暑兼益气，忌肥甘亦忌过寒","静坐散热配合按揉大椎、曲池、足三里、阴陵泉","重点防热射病、心脑血管意外、尿路病与低血糖"]},{"type":"quote","text":"禁溫飲食，飽食，濕地，濡衣服。","source":"《饮膳正要·卷二·四时所宜》"}]},{"id":"liqiu","title":"立秋","subtitle":"8月7日—9日 · 秋季","summary":"凉风初起、暑气未退，秋阳之下湿热犹盛。立秋宜清暑润燥、养肺健脾，忌过食生冷与辛辣，慎防秋燥、感冒与胃肠病。","blocks":[{"type":"paragraph","text":"立秋是秋季第一个节气，太阳黄经为135度，斗指酉，时在申正与酉初之间。虽曰「立秋」，然暑气并未即刻消退——我国素有「秋老虎」之称，尤其长江以南，往往持续高温至九月末方能真正转凉；华北地区则多见「秋雨」绵长。《礼记·月令》载此时「凉风至，白露降，寒蝉鸣」，凉风渐起、白露初凝、寒蝉始鸣，三候皆示暑退凉生之迹。人体方面，此时阳气由盛渐衰而阴气由生渐长，是全年第二次阴阳消长的转折点，然而暑湿之气尚未退尽，昼夜温差开始拉大：白天暑热逼人汗出伤津，夜间凉风袭体，若贪凉过度则暑湿与寒凉相合，最易出现「阴暑」——身热不扬、恶寒无汗、头重身困、胸闷纳呆。此外立秋之后肺气始旺而秋燥未至，肺为娇脏而主宣发，暑热与燥气相合则耗伤肺津，出现口鼻干燥、干咳少痰、咽干音哑；脾气渐旺而肝气渐衰，横逆之弊减而肃降之机生，然初秋仍多暑湿困脾之象。故立秋之养，重在清暑而不伤脾、润燥而不滋腻。"},{"type":"paragraph","text":"起居上宜「早卧早起，与鸡俱兴」，即比夏季提前一个时辰入睡，晨起亦不宜过早，待日光始行，方合「必待日光」之养；但仍须于子时前入睡，以养阴助阳。夜间宜覆薄被，护住腹部与足部，忌赤膊露卧、忌贪凉饮冰。晨起后宜先饮温水一杯，再行户外缓步，舒展筋骨。情志上，暑热渐退而秋气肃降，情绪宜静而不郁，可藉登高望远、赏秋色以宽心胸；勿因暑热初退而骤敛情志致郁。运动宜增加适度户外时间，以快走、慢跑、登山、太极为佳，但须避开正午高温；亦当注意「秋后算账」，即暑热耗损之体力须经适度进补方可恢复，切忌骤然大补。按摩上宜清润养肺：每日按揉肺俞、膏肓、中府、膻中各一分钟；以两手拇指自天突沿胸骨向下推按至膻中三十六次，宽胸利气；并以掌心搓热覆于胸背轻拍各三十六次，助肺气宣降。饮食上宜「辛酸甘平、润而不腻」，忌过食生冷以免秋后中寒。"},{"type":"table","caption":"立秋饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","清暑润燥：银耳、百合、梨、莲藕、蜂蜜、芝麻、桑葚","暑退而燥生，甘润以养肺阴"],["宜食","健脾益气：山药、白扁豆、南瓜、薏苡仁、大麦、小米","脾健则湿去，为秋后之根本"],["忌食","生冷瓜果（过量）：西瓜、梨（生冷）、生鱼片、冰饮","秋后阳气内收，过食生冷易伤中阳"],["忌食","辛辣发散：辣椒、烧烤、烈酒、葱姜蒜（过量）","辛散太过则耗气伤津、助燥"],["推荐食材","银耳百合羹、莲藕排骨汤（须辨证）、山药小米粥、百合莲子粥","润肺兼健脾，暑退燥升两相宜"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·虎戏」：两脚开立成马步，两手握拳成虎爪状，缓慢向前推出、回收，左右交替各九次；继而转身作虎扑之势五次，再左右转腰各九次。此式取虎之刚健沉力，功在强健筋骨、调理肺气与气机出入，最宜在暑退秋初、肺气始旺之时行之。穴位按揉取五处：一为肺俞，第三胸椎棘突下旁开一寸半，以掌根轻揉一分钟，宣肺利气、止咳平喘；二为膏肓，第四胸椎棘突下旁开三寸，按揉一分钟，滋阴润肺、健虚劳；三为中府，云门下、锁骨下窝外端连线中点，按揉一分钟，理气平喘、止咳；四为膻中，两乳头连线中点，掌根揉按一分钟，宽胸利气、宁心；五为太溪，内踝尖与跟骨之间凹陷，按揉一分钟，滋肾阴以助肺阴。亦可每日以两手拇指自锁骨下方沿任脉推至丹田三十六次，助气机升降。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"立秋前后暑热未尽而凉气渐生，须防范五类病证：一是「秋老虎」时节的暑热相关疾病，中暑、急性胃肠炎、细菌性痢疾仍处高发；二是「阴暑」，因贪凉饮冷或露卧而致，表现为恶寒发热、无汗、头身困重、胸闷纳呆、泄泻，处理宜温化而不宜过用寒凉；三是呼吸系统疾病开始抬头，感冒、急性支气管炎、哮喘、慢性咽炎反复，尤其儿童与老人；四是虫媒与肠道传染病，蚊媒传染病与手足口病、病毒性腹泻仍多发；五是精神心理问题，暑热消退而情绪随之低落，季节性情感障碍、抑郁焦虑、失眠可见；六是心脑血管意外，昼夜温差加大使血压波动更明显。预防要点：其一，仍须严防高温，暑气未退不可骤撤防暑措施；其二，早晚加衣、午间防暑，「洋葱式」穿衣，夜间护腹护足；其三，出现恶寒无汗、身重困倦等阴暑表现，宜饮姜汤、热粥并及时就医，不可因「夏病治夏寒」而一味冷敷冷饮；其四，饮食不宜过凉，可适度温饮，忌大量生冷瓜果与冰饮；其五，居室通风与空调使用须平衡，避免室内外温差过大；其六，秋燥初起即须注意保湿，居室可置加湿器或每日洒水，多饮温水并适量食用梨、百合、银耳；其七，高血压、冠心病、糖尿病患者须加强监测并按时用药，切勿自行停减。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"立秋养生要点","items":["早卧早起早安寝，夜间覆薄被护腹足","暑热未尽仍须防暑，晨起先饮温水再缓行","饮食辛酸甘平、润而不腻，忌过食生冷与辛辣","按揉肺俞、膏肓、中府、膻中、太溪并推按任脉","重点防阴暑、哮喘与感冒、虫媒病及情绪低落"]},{"type":"quote","text":"秋三月，此謂容平。天氣以急，地氣以明，早卧早起，與雞俱興，使志安寧，以緩秋刑，收斂神氣，使秋氣平，無外其志，使肺氣清。","source":"《黄帝内经·素问·四气调神大论》"}]},{"id":"chushu","title":"处暑","subtitle":"8月22日—24日 · 秋季","summary":"暑气至此而止，燥气始代。处暑宜润肺养阴、和胃健脾，饮食宜甘润宜忌辛燥，慎防秋燥、便秘与脾胃失调。","blocks":[{"type":"paragraph","text":"处暑是暑热的终点，太阳黄经为150度，斗指戊，时在酉正与戌初之间。「处」者，止也，谓暑气至此而止。《礼记·月令》载此时「鹰乃祭鸟，天地始肃，禾乃登」，鹰捕鸟陈列以祭、天地间暑气始肃而草木收敛、谷物成熟登场，三候皆是暑退秋收、天地收敛之象。此时我国南北普遍暑热渐消而秋高气爽，东北、西北已可见早晚凝霜，南方则仍有余热。人体方面，暑热之气渐退而燥气始生，肺气当旺而司呼吸，肺喜润恶燥，燥气渐侵则肺津受灼，出现口鼻咽干、干咳少痰或痰黏难咯、皮肤干涩发痒、大便干结难下；与此同时，脾胃受暑湿困扰多日而脾阳受损，加之昼热夜凉、饮食贪凉则中焦受寒，出现脘腹隐痛、喜温喜按、泄泻、纳差。故处暑之养，重在润肺而不过腻、和脾而不过寒，令刚转为柔、暑退而燥润相济。"},{"type":"paragraph","text":"起居上宜「早卧早起，与鸡俱兴」，既顺应秋气之收敛，又须于子时前入睡以养阴；夜间宜早着衣，晨起加一件薄衫，昼间热时再减，忌贪凉露卧。晨起后宜先饮温水一杯，并到户外缓行，舒展筋骨而助肺气宣发。居室宜通风，南方尚热者亦须开窗以散湿浊，干燥明显者可置加湿器。情志上，秋气肃降而人多悲秋，宜「使志安宁，以缓秋刑」，忌过度忧思悲愁，可借登高、赏菊、静养、书画以舒心气；抑郁者当主动寻求倾诉。运动宜渐增户外比重，以快走、慢跑、登山、太极拳为佳，晨起与傍晚为佳；运动后不宜立即脱衣吹风，汗出宜及时擦干。按摩上宜润肺养阴：每日按揉肺俞、膏肓、太溪、三阴交各一分钟；以两掌相搓生热，覆于胸背部轻拍三十六次；以两手拇指自天突推至膻中三十六次，助肺气宣降；并以指腹按揉鱼际、尺泽各一分钟，清肺润燥。饮食上宜甘润、宜清补、忌辛燥，《饮膳正要》谓「秋气燥，宜食麻，以润其燥」。"},{"type":"table","caption":"处暑饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","甘润养肺：银耳、百合、梨、莲藕、蜂蜜、黑芝麻、麦冬（须辨证）","甘能润肺，润而不腻为秋燥首选"],["宜食","健脾和胃：山药、白扁豆、南瓜、莲子、薏苡仁、小米","脾健则津液得布，肺胃并养"],["忌食","辛燥伤津：辣椒、花椒、烧烤、羊肉、韭菜（过量）、炸物","辛燥耗肺津，使干咳、便秘加重"],["忌食","寒凉损阳：冰饮、刺身、螃蟹、生冷瓜果（过量）","处暑已见秋凉，过寒则中阳受损而泄泻"],["推荐食材","银耳百合羹、百合莲子粥、莲藕排骨汤（须辨证）、黑芝麻核桃糊","润肺与健脾并行，处暑之宜"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·猿戏」：两脚开立，屈膝下蹲成马步，两手握拳置于胸前，模仿猿之灵活上举、左右攀援、左右顾盼，各九次；继而以两臂作攀物状上下移动三十六次。此式取猿之灵活柔韧，功在舒展肺经、开胸理气、畅达情志，最宜秋日晨起后行之。穴位按揉取五处：一为肺俞，第三胸椎棘突下旁开一寸半，掌根轻揉一分钟，宣肺止咳；二为鱼际，掌骨桡侧中点赤白肉际处，拇指按揉一分钟，清肺利咽、治干咳；三为尺泽，肘横纹桡侧端凹陷，按揉一分钟，清肺降逆、止咳；四为太溪，内踝尖与跟骨之间凹陷，按揉一分钟，滋肾阴、纳浮阳；五为三阴交，内踝尖上三寸、胫骨内侧缘后方，按揉一分钟，健脾养血、调经。亦可每日以两手拇指沿胸骨正中自上而下推按三十次，并配合做三次深长深呼吸以助肺气肃降。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"处暑之后暑湿渐退而燥气渐显，须重点防范：一、呼吸系统疾病，感冒、急性支气管炎、哮喘、慢性咽炎进入高发期，秋季为慢阻肺与哮喘的稳定期，须规范治疗；二、秋燥相关疾病，干燥综合征、干燥性鼻炎、结膜炎、皮肤瘙痒症、老年瘙痒症多见，表现为口眼鼻干、皮肤干痒、起疹脱屑；三、便秘与消化功能紊乱，燥结伤津而大便干结，老年人与久坐者尤甚，亦可见功能性腹泻与肠易激综合征；四、胃肠型感冒与急性胃肠炎，昼夜温差加大而饮食失节所致；五、情绪障碍，季节性情感障碍、抑郁与焦虑在秋季高发，「秋悲」即其表现；六、心脑血管疾病，晨起血压高峰与温差刺激使脑卒中、心肌梗死风险升高，尤其清晨为高发时段；七、眼部与皮肤的真菌感染，汗渍与潮湿使足癣、体股癣多发。预防要点：其一，饮食清淡滋润，多食汤羹与新鲜蔬果，适量食用梨、百合、银耳、芝麻、蜂蜜，每周摄取数次；其二，每日饮水不少于一千五百毫升，宜小口频饮，晨起与睡前各饮温水一杯；其三，居室保持适宜湿度，干燥者使用加湿器并每日通风，避免长时间处于空调房；其四，皮肤干燥者忌用热水烫洗与碱性皂类，宜用温水与温和润肤剂，瘙痒难忍者勿搔抓；其五，保持适度运动与规律作息，晨起勿骤起、动作宜缓，晨练后注意保暖；其六，情绪低落者当主动求助，切勿认为「秋悲」必然而消极等待；其七，晨起血压高峰时避免剧烈运动与情绪激动，高血压患者按时服药并监测血压；其八，持续咳嗽、消瘦、咯血、大便带血或长期便秘者须及时就医查因。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"立秋养生要点","items":["早卧早起、晨起加衣，昼间热时再减","晨起温水一杯，居室通风并保持适度湿度","饮食甘润清补、健脾和胃，忌辛燥亦忌过寒","按揉肺俞、鱼际、尺泽、太溪、三阴交并推按胸骨","重点防秋燥干咳、便秘、晨起血压高峰与秋悲"]},{"type":"quote","text":"秋氣燥，宜食麻，以潤其燥。禁寒飲食，寒衣服。","source":"《饮膳正要·卷二·四时所宜》"}]},{"id":"bailu","title":"白露","subtitle":"9月7日—9日 · 秋季","summary":"露凝而白，昼夜温差显著增大。白露宜润肺养阴、防燥防寒，饮食宜温润平和，忌过早贪凉，慎防秋燥、哮喘与胃肠病。","blocks":[{"type":"paragraph","text":"白露是秋季第三个节气，太阳黄经为165度，斗指庚，时在戌初与戌正之间。「白露」之义，在于夜间水汽遇冷凝结而成露，且露色已白。物候上，《礼记·月令》载此时「鸿雁来，玄鸟归，鸟群羞」，鸿雁自北方南来、燕子归去、众鸟因气候转凉而储备脂羽以御寒，三候皆为迁候与收敛之象。气候上，此时暑气已尽、秋风渐紧，我国南北普遍进入「秋高气爽」之季：北方早晚已有霜感，昼夜温差常达十度以上；南方暑热方退而秋燥渐显，昼夜温差同样拉大。人体方面，肺气当旺而司呼吸与皮毛，肺喜温润而恶寒燥，骤然受凉则腠理闭密、卫气郁滞，肺气失宣而咳嗽、气喘、鼻塞、咽痒、恶寒无汗；与此同时，昼夜温差使人频繁调节而阳气消耗，免疫力下降，感冒、哮喘、慢支、过敏性鼻炎进入高发期，皮肤与呼吸道过敏亦见增多。此时亦是「秋燥」逐渐明显的时期，燥邪伤津耗液，口鼻咽干、干咳少痰、皮肤干涩、大便干结、情绪烦躁诸症渐起。故白露之养，重在润肺以抗燥、护阳以防凉。"},{"type":"paragraph","text":"起居上宜「早卧早起，与鸡俱兴」，即比盛夏提前一个时辰寝卧，晨起亦不宜过早；同时强调「必待日光」，待到日光始行再作户外活动。衣着须应「洋葱式」增减，晨起与夜间加衣，护住头颈、背部与足下，切忌因「秋高气爽」而单衣贪凉、露腹露足；夜间尤其不宜赤膊而卧。居室宜通风以排湿浊，干燥明显者可用加湿器，并注意室内湿度不宜过高以免生湿。情志上宜静养收敛，可借秋高气爽之景登高望远、赏菊听雨以宽心；忌过度悲忧与耗神。运动宜量力而行，宜渐增而忌骤加剧烈，晨起运动前须充分热身；晨练宜在日出后进行，避免空腹与逆风而行，雾霾天不宜户外锻炼。按摩上宜温润养肺：每日按揉肺俞、膏肓、大椎、天突、膻中各一分钟；以两手拇指自天突向下推至膻中三十六次；以掌心搓热覆于肺俞、膏肓处轻按各一分钟。饮食上宜甘润温平、宜脾肺双补，忌过食寒凉，亦忌辛燥太过。"},{"type":"table","caption":"白露饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","温润养肺：银耳、百合、梨、莲藕、山药、白扁豆、蜂蜜","甘润而性平，润肺而不伤脾"],["宜食","健脾益气：山药、薏苡仁、莲子、大麦、南瓜、小米","脾健则津液充足，肺得濡养"],["忌食","过寒伤阳：冰饮、刺身、螃蟹、生拌、冷西瓜（大量）","秋凉已显，贪凉最易伤脾胃"],["忌食","辛燥耗津：辣椒、烧烤、油炸、羊肉、韭菜（过量）、烈酒","燥邪当令，再助其燥则肺津更伤"],["推荐食材","山药排骨汤（须辨证）、百合莲子粥、莲藕排骨汤、银耳百合羹","脾肺同调，温润平和最合白露"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·鹿戏」：两脚开立，屈膝下蹲成马步，两手虚握于腹前，先以两臂内旋、外旋交替画圆九次，再以腰部为轴带动上身左右环转九周，继而后仰伸展九次。此式取鹿之矫健灵活，功在强健腰肾、舒展胸胁、调理肺气，最宜秋日晨起后行之。穴位按揉取五处：一为肺俞，第三胸椎棘突下旁开一寸半，以掌根温揉一分钟，宣肺止咳、散寒；二为膏肓，第四胸椎棘突下旁开三寸，温揉一分钟，滋阴润肺、健虚劳；三为大椎，第七颈椎棘突下凹陷，以拇指按揉一分半钟，祛风散寒、解表；四为天突，锁骨中线胸骨上窝正中，以食、中二指按揉一分钟，宣肺利咽、止咳；五为足三里，外膝眼下三寸，按揉一分半钟，健脾益气、扶助正气。亦可每日以两手互搓生热后覆于双肩肺俞区轻拍三十六次，助肺气宣发。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"白露以后昼凉夜凉、温差骤增，须重点防范：一、呼吸道疾病进入高发，感冒、急性支气管炎、哮喘急性发作、慢阻肺急性加重、儿童哮喘与过敏性鼻炎均多见；二、过敏性疾病，花粉浓度虽较春季为低，但霉菌、尘螨、皮屑与冷空气刺激仍可诱发哮喘、荨麻疹、湿疹与过敏性结膜炎；三、秋季腹泻与急性胃肠炎，昼夜温差与饮食生冷所致，尤须留意「秋后算账」式的脾胃受寒；四、心脑血管意外，晨起血压高峰与温差刺激使脑卒中与心肌梗死风险升高，清晨为一天中发病最集中的时段；五、干燥综合征与秋冬皮肤瘙痒，老年人与糖尿病患者尤为突出；六、类风湿关节炎与骨关节炎患者症状加重，晨僵明显；七、情绪与睡眠障碍，抑郁、焦虑与入睡困难在秋凉后增多；八、眼部与口腔干燥性病变。预防要点：其一，晨起与夜间加衣，护住头颈、背部与足部，切忌「秋冻」过度；其二，晨起不宜骤起，起身动作宜缓，防止体位性低血压与血压骤变，晨练前充分热身且在日出后进行；其三，饮食以温热为主，忌生冷冰饮，宜常饮温水，多食梨、百合、银耳、芝麻、蜂蜜；其四，居室保持适宜湿度，干燥时用加湿器，注意通风除湿；其五，哮喘与慢阻肺患者须按医嘱规范使用吸入制剂，切勿因「天凉了忍忍就好」而停药，秋冬季正是急性发作高峰；其六，过敏体质者提前备抗过敏药物，回屋后洗脸洗鼻更换外衣；其七，持续咳嗽、喘息、胸痛、气促、肢体麻木者须及时就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"白露养生要点","items":["早卧早起、日出后活动，晨起加衣护足","昼夜温差大，忌露腹露足、忌单衣贪凉","饮食温润甘平、脾肺双补，忌过寒与辛燥","按揉肺俞、膏肓、大椎、天突、足三里并搓肩助肺","重点防哮喘与慢阻肺急性发作、晨起血压高峰与秋燥"]},{"type":"quote","text":"桑葉∶炙，煎飲之止渴，一如茶法。","source":"《食疗本草·卷上·桑》"}]},{"id":"qiufen","title":"秋分","subtitle":"9月22日—24日 · 秋季","summary":"昼夜等长，阴阳再平而秋气始盛。秋分宜润肺平喘、补益肝肾，起居「早卧早起」、饮食「甘润平补」，防秋燥与呼吸系统疾病。","blocks":[{"type":"paragraph","text":"秋分是二十四节气中第二个昼夜等长的节气，太阳黄经为180度，斗指癸，时在戌正与亥初之间。此后太阳直射点南移，北半球昼渐短而夜渐长，与春分恰成上下对应，故《素问·阴阳应象大论》所谓「圣人春夏养阳，秋冬养阴，以从其根」于此最为切合——春分之后阳长阴消，当养阳以顺其生；秋分之后阴长阳消，当养阴以顺其藏。物候上，《礼记·月令》载此时「雷始收声，蛰虫坯户，水始涸」，雷声始收、蛰虫筑户而藏、水量渐减，三候皆为收敛收藏之象，与春分「玄鸟至，雷乃发声，始电」的生长发动恰成对照。人体方面，此时肺气当旺而司呼吸，肺为华盖而朝百脉，肺气旺则全身气机升降有序；但肺属金而与秋相应，肺气过敛则气机不畅而胸闷、气促；金旺则克木，肝气受制而疏散不利，遂见情绪抑郁、胸胁胀痛；又肺与大肠相表里，肺失宣降则大肠传导失常而便秘。燥气于此时最盛，津液渐亏而不及濡润，出现口鼻干、咽干、皮肤干、便干、眼干与关节不利。故秋分之养，最宜润肺与疏肝并施、养阴与平喘同取。"},{"type":"paragraph","text":"起居上，《素问·四气调神大论》明示秋三月「早卧早起，与鸡俱兴」，此时当严格遵行——比白露再早一个时辰入睡，且必须于子时前入眠，晨起亦不宜过早，须待日光初升。夜间宜覆被保暖，晨起加衣，出门前先饮温水一杯。居室宜通风，南方尚温者开窗对流以散余热与湿浊，北方干燥者用加湿器，湿度宜在百分之五十至六十之间。情志上，秋分正是「悲秋」情绪高发之时，宜主动调摄：多参与登高、赏菊、丰收、团聚等活动，借自然与社交之力宽心解郁；抑郁焦虑者当尽早求助，切勿以「季节性」而放任。运动宜「广步于庭」，晨间或傍晚作快走、慢跑、太极、登山，唯须避风寒与雾霾，晨练宜待日出，忌空腹。按摩上宜润肺疏肝：每日按揉肺俞、膏肓、太溪、太冲、三阴交各一分钟；以两掌搓热后摩腹三十六圈，健脾助津；并作「嘘」字诀六次以舒肺气。饮食上宜甘润平补，忌大补亦忌大寒。"},{"type":"table","caption":"秋分饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","甘润滋阴：银耳、百合、梨、莲藕、蜂蜜、黑芝麻、桑葚","甘润以养肺阴、滋肝肾阴"],["宜食","平补脾肺：山药、白扁豆、莲子、薏苡仁、粳米、瘦肉","补而不燥，为秋分平补之正法"],["宜食","疏肝理气：佛手、陈皮、玫瑰花、荞麦（须辨证）","秋金克木，疏肝以助肺气宣降"],["忌食","辛燥劫阴：辣椒、烧烤、油炸、烈酒、羊肉、韭菜（过量）","秋燥当令，辛燥更耗津液"],["忌食","寒凉伤阳：冰饮、刺身、生冷瓜果（过量）","阳气内藏之时，过寒则伤中"],["推荐食材","山药小米粥、百合莲子粥、银耳百合羹、莲藕排骨汤（须辨证）","脾肺肾同调，甘润平和"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·鹤戏」：两脚并立，双手交叠于腹前，闭目调息，先深吸三十六息，再徐徐呼出三十六息；继而两臂自下向前缓缓上举至头顶并抬头，目光上视，缓缓放下，共九轮；最后单足站立各一分钟，两侧交换，以培固下元。此式取鹤之舒展轻灵、动静相兼，功在开阔胸廓、调理气机、培固肾气，最宜秋分日傍晚在开阔处行之。穴位按揉取五处：一为肺俞，第三胸椎棘突下旁开一寸半，掌根温揉一分钟，宣肺平喘；二为太溪，内踝尖与跟骨之间凹陷，按揉一分钟，滋肾阴、纳浮阳；三为太冲，足背第一、二跖骨结合部前凹陷，按揉一分钟，疏肝理气、降压；四为三阴交，内踝尖上三寸、胫骨内侧缘后方，按揉一分钟，健脾养血、调经安神；五为膻中，两乳头连线中点，掌根揉按一分钟，宽胸理气。亦可每日以两足心相搓至热，覆于腰眼与涌泉各一分钟，助水火既济。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"秋分之后阴气渐盛而阳气内藏，须重点防范：一、燥邪为患最盛，秋季感冒、支气管炎、哮喘、过敏性鼻炎与咽炎高发；二、慢阻肺与心肺疾病进入急性加重高峰，老慢支、肺心病、冠心病患者症状多在此期加重，须加强监测与规范治疗；三、秋季腹泻与胃病，脾胃受凉而肠易激综合征、慢性胃炎急性发作；四、干燥综合征、干燥性皮肤瘙痒、老年瘙痒症与皲裂性湿疹高发；五、抑郁与焦虑等情绪障碍进入年度高峰，「秋悲」甚者可见悲观厌世倾向；六、心脑血管意外，早晨血压高峰与温差是重要诱因，脑卒中与心梗多发；七、抑郁与骨质疏松并存，雌激素下降与钙吸收减少使老年女性骨折风险升高；八、皮肤与五官科疾病，痤疮、银屑病、脂溢性皮炎、口腔溃疡多发。预防要点：其一，严格「秋冬养阴」，夜卧早眠、子时前入睡，切忌熬夜耗阴；其二，饮食温润滋阴，忌辛辣燥烈，注意补充水分；其三，居室维持适宜湿度并注意通风，避免长期处于干燥空调房；其四，适度运动但须避风寒，晨练待日出、衣要穿足；其五，慢性肺病与心脏病患者须在医师指导下提前准备抗感染与急救药物，坚持按医嘱用药，切勿擅自停用吸入制剂；其六，情绪抑郁持续两周以上者须及时至精神心理科或中医门诊就诊，切勿自行滥用药物；其七，老年人宜检测骨密度并适量补充钙与维生素D，谨防跌倒；其八，出现胸痛、呼吸困难、剧烈头痛、意识改变、持续黑便者须立即就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"秋分养生要点","items":["早卧早起、子时前入睡，晨起加衣待日光","秋冬养阴，居室湿度五十至六十并注意通风","饮食甘润平补、脾肺肾同调，忌辛燥与过寒","按揉肺俞、太溪、太冲、三阴交、膻中并搓足心","重点防慢阻肺急性加重、秋季腹泻、情绪抑郁与骨折"]},{"type":"quote","text":"所以聖人春夏養陽，秋冬養陰，以從其根。故與萬物沉浮於生長之門。","source":"《黄帝内经·素问·阴阳应象大论》"}]},{"id":"hanlu","title":"寒露","subtitle":"10月8日—9日 · 秋季","summary":"露气寒冷将凝，燥气转寒。寒露宜温润肺胃、健脾化湿，忌寒凉生冷，重点防秋燥转寒凉、哮喘与胃痛复发。","blocks":[{"type":"paragraph","text":"寒露是秋季第五个节气，太阳黄经为195度，斗指戊，时在亥初与亥正之间。「寒露」之义，在于露水将凝而未凝，尚带寒意，故称寒露，较白露更深一层寒气。物候上，《礼记·月令》载此时「鸿雁来宾，雀入大水为蛤，菊有黄华」，鸿雁自北方南来为宾、雀入大水化为蛤蛤、菊花开出黄华，三候皆示深秋物候与气候之变。此时我国南北普遍进入深秋：北方已可见霜冻，白天仍觉温暖而早晚寒气逼人，昼夜温差可达十五度以上；南方亦由凉转寒，秋意明显。人体方面，燥邪渐退而寒气渐生，暑湿已尽而寒湿之邪始侵。《素问·阴阳应象大论》云「秋伤于湿，冬必咳嗽」，深秋之湿与寒相合最易留滞于肺，肺气失宣而咳嗽、痰多、气喘；寒湿困脾则脘腹胀痛、纳差、泄泻；寒邪束表则恶寒、无汗、头身疼痛；又肺气虚寒则卫外不固，感冒频发。此外，秋冬之交是胃病与心脑血管病的高发期，脾胃虚寒者尤为敏感。此期养生的要点在于「温」与「润」并行——既散寒而不燥，又润燥而不腻。"},{"type":"paragraph","text":"起居上宜「早卧早起，与鸡俱兴」，并进一步强调保暖，夜间须加厚被褥，晨起即着衣，忌「秋冻」过度而受寒露之气；「寒露不摘棉，霜打莫怨天」正言其理。洗澡宜用温水，忌冷水洗浴，睡前可用温水泡脚十五分钟以助阳气内达。居室宜通风，因湿气渐重，房屋宜保持干燥，必要时使用除湿设备，被褥衣橱宜择晴日晾晒。情志上宜「使志安宁」，忌悲忧、忌恣意耗神，宜安神定志、适度静养，可借秋色与丰收之景调畅心怀。运动宜渐入冬前的耐寒锻炼，以八段锦、太极、慢跑、登山为宜，忌大汗淋漓；晨练宜在日出后并待身体温暖后再行，忌空腹与迎风疾行。按摩上宜温肺散寒：每日按揉肺俞、脾俞、足三里、大椎、风门各一分钟；以两掌搓热后摩腹三十六圈；以拇指按揉迎香穴一分钟以通鼻窍、宣肺气。饮食上宜温润为宜，《饮膳正要·卷二·四时所宜》谓「秋气燥，宜食麻，以润其燥；禁寒饮食，寒衣服」，当忌一切寒凉生冷。"},{"type":"table","caption":"寒露饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","温润养肺：银耳、百合、梨、莲藕、蜂蜜、芝麻、栗（须辨证）","温而润，润肺而不生寒"],["宜食","健脾温运：山药、白扁豆、南瓜、薏苡仁、生姜、大枣","脾健则湿化，寒湿得散"],["宜食","温补肺肾：栗、核桃、黑芝麻（须辨证，胡桃非目录内）","深秋进补以润肺肾，为燥季所宜"],["忌食","寒凉生冷：螃蟹、刺身、冰饮、生冷瓜果、凉拌苦瓜","寒露已至，过寒直伤脾胃"],["忌食","辛辣燥烈：辣椒、烧烤、烈酒、油炸、羊肉（过量）","既助燥又发散，耗伤肺津"],["推荐食材","山药排骨汤（须辨证）、板栗粥、百合莲子粥、桂花陈皮饮（须辨证）","温润并进，脾肺同调"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·虎戏」：两脚开立成马步，双手成虎爪状向前推出、回收，左右交替各九次；继而转身作虎扑势五次，转身回视各九次。此式取虎之刚健与俯冲之势，功在强筋健骨、宣通肺气与激发阳气，最宜深秋晨起、日光方升之时行之。穴位按揉取五处：一为肺俞，第三胸椎棘突下旁开一寸半，以掌根温揉一分半钟，宣肺止咳、散寒；二为风门，第二胸椎棘突下旁开一寸半，按揉一分钟，祛风散寒、预防感冒；三为大椎，第七颈椎棘突下凹陷，按揉一分半钟，振奋阳气、解表散寒；四为脾俞，第十一胸椎棘突下旁开一寸半，按揉一分钟，健脾化湿；五为足三里，外膝眼下三寸，以拇指按揉一分半钟，健脾益气、扶正固表。亦可用艾条温灸足三里、脾俞、命门各十五分钟，须遵医嘱并注意防烫伤。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"寒露前后是秋冬疾病的高发起点，须重点防范：一、呼吸系统疾病，感冒、急性支气管炎、哮喘急性发作、慢性阻塞性肺疾病急性加重、肺炎均多见，尤以老年人、儿童为重；二、秋季腹泻与胃痛急性发作，脾胃虚寒者受寒即痛即泻；三、心脑血管疾病，晨起血压高峰与寒凉刺激使脑卒中、心肌梗死风险上升，是秋冬心梗的第一个高峰；四、慢性病恶化，高血压、糖尿病、慢阻肺、心衰患者在季节交替时易失代偿；五、类风湿与骨关节炎症状加重，晨僵、关节肿痛明显；六、皮肤干燥性皮肤病与瘙痒症，湿疹、老年瘙痒症、干皮症高发；七、失眠与情绪障碍，秋冬是失眠与抑郁的高发期；八、带状疱疹与水痘在秋冬季好发，与免疫力下降相关。预防要点：其一，「寒露不摘棉」，及时增减衣物，夜间尤其保暖，忌「秋冻」过度；其二，晨起与夜间避免赤膊露腹、避免洗冷水澡，睡前温水泡脚；其三，饮食温热为主，忌一切生冷寒凉，宜多食温润之品并常饮温水；其四，居室通风与除湿并重，被褥常晾晒，保持干燥温暖；其五，慢性肺病患者须在医师指导下提前准备药物，坚持使用吸入制剂，不可因「天冷懒得动」而停药；其六，高血压患者加强晨起血压监测，冬季调整用药须经医师评估，切勿自行加量；其七，糖尿病患者注意保暖，天冷时血糖易波动，须加强监测并备好糖果；其八，出现持续高热、气促、胸痛、意识改变或剧烈腹痛者须立即就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"寒露养生要点","items":["寒露不摘棉，晨起加衣、夜间加被，忌秋冻过度","温水洗浴、睡前泡脚，居室通风与除湿并重","饮食温润健脾，忌一切寒凉生冷与过食辛辣","按揉肺俞、风门、大椎、脾俞、足三里并可温灸","重点防哮喘与慢阻肺加重、晨起血压高峰与胃肠病"]},{"type":"quote","text":"秋傷於濕，冬必咳嗽。","source":"《黄帝内经·素问·阴阳应象大论》"}]},{"id":"shuangjiang","title":"霜降","subtitle":"10月23日—24日 · 秋季","summary":"气肃霜降，秋冬之交而阳气始降。霜降宜温补脾肾、养阴润燥并重，饮食宜温补而不燥，慎防心脑血管病与呼吸道疾病。","blocks":[{"type":"paragraph","text":"霜降是秋季最后一个节气，太阳黄经为210度，斗指亥，时在亥正与子初之间。「霜降」之义，在于气肃而凝露为霜，天气已由凉转为寒。物候上，《礼记·月令》载此时「豺乃祭兽，草木黄落，蛰虫咸俯」，豺捕获猎物陈列以祭，草木枯黄凋落，蛰虫皆俯伏蛰藏，三候皆为天地收敛闭藏之象，至此而秋气已尽，冬气将临。对人体而言，此时是全年阳气由升转降、由显转藏的转折点：阳气开始潜藏于体内，体表腠理逐渐密固，抗御外邪的能力由强转弱，故《素问·生气通天论》言「故阳气者，一日而主外，平旦人气生，日中而阳气隆，日西而阳气已虚，气门乃闭」；腠理始闭而汗出渐少，若此时仍贪凉露宿，最易寒邪直中脏腑；与此同时，燥气未消而寒气渐生，肺胃既受燥伤又受寒侵，出现干咳少痰、咽干、口唇干裂、鼻腔出血、皮肤干燥皲裂、脘腹冷痛与泄泻并存之象。秋冬之交亦是心脑血管疾病的第一高发期，晨起血压高峰叠加寒凉刺激，使脑卒中与心肌梗死风险显著上升。脾胃虚寒者尤须注意，此期若过食生冷，极易诱发胃痛、呕吐与急性胃肠炎。"},{"type":"paragraph","text":"起居上宜「早卧晚起，必待日光」，此时当严格遵行——比秋分再早一个时辰入睡，晨起须待日光始行方可活动，晨练宜安排在上午九时之后；夜间宜早寝暖睡，特别注意头颈、背部与足部的保暖，忌夜间「蹬被」与赤足而眠。居处宜温暖，居室宜保持干燥温暖，被褥宜加厚并常晾晒；洗澡宜用温水，忌冷水洗浴，睡前可温水泡脚。情志上宜「使志若伏若匿，若有私意，若已有得」，此即收敛内藏、涵养心神之意，忌外放恣意、忌过度思虑与悲忧，宜静养、读书、静坐、早睡。运动宜以柔缓为度，太极、八段锦、散步为宜，忌大汗淋漓；不宜再作大强度耐寒锻炼，冬练宜渐收。按摩上宜温补脾肾：每日按揉足三里、脾俞、肾俞、命门、涌泉各一分钟；以两掌搓热后按揉腰眼一分半钟；以拇指按揉阴陵泉一分半钟以化寒湿。饮食上宜温补、宜平补、忌大热亦忌大寒，谓「秋冬养阴」，故不宜过用温燥之品耗伤津液。"},{"type":"table","caption":"霜降饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","温补脾肾：栗、羊肉（适量）、核桃、枸杞、生姜、大枣","温补以助阳气内藏，惟不可过燥"],["宜食","滋阴润燥：银耳、百合、梨、蜂蜜、黑芝麻、麦冬（须辨证）","秋冬养阴，润燥而不碍脾"],["宜食","健脾化湿：山药、白扁豆、薏苡仁、茯苓、南瓜","脾健湿去，秋冬之本"],["忌食","寒凉生冷：冰饮、螃蟹、刺身、凉拌菜、生冷瓜果（过量）","霜降已至，寒邪直中脏腑"],["忌食","过食生冷或过用温燥：大量冰啤、辣椒、烧烤、烈酒","一伤脾阳，一耗肺津，两败俱伤"],["推荐食材","板栗粥、山药小米粥、百合莲子粥、枸杞羊肉汤（须辨证）","温补与滋阴并重，脾胃为枢纽"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·猿戏」：两脚开立，屈膝下蹲成马步，两手握拳置于胸前，模仿猿之攀援举物，左右各九次；继而两臂上下攀动三十六次，再左右顾盼各九次。此式取猿之柔韧灵活，功在疏通全身经络、舒展筋骨、安宁心神，最宜深秋傍晚于室内行之。穴位按揉取五处：一为足三里，外膝眼下三寸，以拇指按揉一分半钟，健脾益气、扶正固表；二为脾俞，第十一胸椎棘突下旁开一寸半，掌根揉按一分钟，健脾化湿、统血；三为肾俞，第二腰椎棘突下旁开一寸半，温揉一分半钟，补肾助阳、纳气平喘；四为命门，第十四腰椎下凹陷，掌根温揉一分半钟，温补肾阳、固本培元；五为涌泉，足心前三分之一凹陷，睡前按揉一分半钟至酸胀，引火归元、助眠。亦可每日以艾条温灸关元、气海、足三里各十五分钟，须遵医嘱；女性经期与孕期不宜温灸。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"霜降为秋冬疾病的第一波高峰，须重点防范：一、心脑血管意外，晨起血压高峰与寒凉刺激使脑卒中、心肌梗死、主动脉夹层风险明显上升，是秋冬第一个发病高峰；二、呼吸系统疾病，感冒、流感、支气管炎、哮喘与慢阻肺急性发作高发，流感在此时进入流行高峰；三、秋冬腹泻与急性胃肠炎，脾胃虚寒者受寒即发，老年人与婴幼儿尤甚；四、慢性病管理与失代偿，高血压、糖尿病、冠心病、慢阻肺、心衰患者在气温骤降时易出现血压波动、血糖波动与心功能不全；五、类风湿关节炎、骨关节炎与腰腿痛复发加重；六、皮肤与黏膜干燥性疾病，皲裂、口唇炎、口腔溃疡、眼干燥、老年瘙痒症多见；七、失眠与情绪障碍，秋冬发作型失眠与季节性抑郁增多；八、老年人跌倒与骨质疏松性骨折，入冬后骨折高发。预防要点：其一，及时添衣加被，护住头颈、背部、腰腹与足部，忌「秋冻」过度与睡前赤足；其二，晨起动作宜缓，先在床上活动片刻再起身，晨练安排在日出后并做好热身，忌空腹与逆风快跑；其三，饮食温热有营养，多食汤羹，忌生冷寒凉，适量进补但忌膏方擅自乱用；其四，居室保温与通风兼顾，洗澡用温水并及时擦干，睡前泡脚；其五，高血压患者晨起测量血压并规律服药，冬季调整方案须经医师评估，切勿自行加药；其六，糖尿病患者加强血糖监测，注意保暖并随身携带糖果，防止低血糖与糖尿病酮症酸中毒；其七，老年人注意防跌倒，居室地面防滑、起夜开灯、穿合脚防滑鞋，必要时使用手杖；其八，流行季前接种流感与肺炎疫苗（依医嘱），出现高热不退、呼吸困难、胸痛、意识改变或剧烈腹痛者须立即就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"霜降养生要点","items":["早卧晚起、必待日光，晨起先活动片刻再起身","及时添衣加被，护头颈腰腹与足部，忌秋冻过度","饮食温补与滋阴并重，忌生冷亦忌过燥","按揉足三里、脾俞、肾俞、命门、涌泉并可温灸","重点防心脑血管意外、流感与慢阻肺加重、跌倒骨折"]},{"type":"quote","text":"羊肉 味甘、大熱、無毒。主暖中，頭風，大風，汗出，虛勞，寒冷，補中益氣。","source":"《饮膳正要·卷三·兽品》"}]},{"id":"lidong","title":"立冬","subtitle":"11月7日—8日 · 冬季","summary":"万物收藏，动而至于静。立冬宜养藏、温补脾肾、藏精蓄锐，忌过早大补，宜静养少劳，慎防心脑血管病与呼吸系统疾病。","blocks":[{"type":"paragraph","text":"立冬是冬季的第一个节气，太阳黄经为225度，斗指亥，时在子初与子正之间。「立冬」之义，在于万物至此收藏。《礼记·月令》载此时「水始冰，地始冻，雉入大水为蜃」，水始结冰、地始冻结，野鸡少有而复有蜃蛤之声，皆言阴气渐盛而阳气内藏。气候上，我国绝大部分地区已入冬：北方气温降至零度上下并开始出现初霜与降雪，江南则寒潮频至、昼夜温差骤大，岭南亦渐生凉意。此时地表湿度迅速下降而空气干燥，加之气温下降，人体腠理致密、汗孔闭合，散热减少而卫气不能外达，遂见畏寒怕冷、四肢不温、精神萎靡、嗜睡赖床；同时人体对热量的需求增加而脾胃运化相对迟缓，加之夏秋饮食积滞未清，极易出现脘腹胀满、食欲不振、恶心泄泻的「肠积」。冬主闭藏，《素问·四气调神大论》谓「冬三月，此谓闭藏……无泄皮肤，使气亟夺」，强调冬季当减少耗散、蓄养精气，尤其是肾精与阳气的封藏，为来年之基。此外冬季是心脑血管疾病与呼吸系统疾病的高发期，晨起血压高峰叠加寒冷刺激，前者尤须警惕。"},{"type":"paragraph","text":"起居上宜「早卧晚起，必待日光」，这是冬季最紧要的一条——必须比秋季再提前一个时辰入睡，且晨起须待到日光初升方起身活动，晨练宜安排在上午九时之后，忌天未亮即出门。夜间宜早寝暖睡，被褥加厚，护住头颈、背部、腰腹与足部，忌夜间蹬被、赤足而眠与「秋冻」延续。洗澡宜用温水，忌冷水洗浴，睡前温水泡脚十五分钟，以助阳气内达。居处宜温暖，居室宜保持干燥温暖，被褥衣橱宜择晴日晾晒，通风与保暖兼顾。情志上宜「使志若伏若匿，若有私意，若已有得」，即内敛含蓄、勿使心绪外泄，忌大喜大悲与耗神，宜静养、读书、早睡、适度日光浴。运动宜柔缓持久，如太极、八段锦、慢跑、散步，忌大汗淋漓与骤然大强度锻炼；「冬练勿过劳」，忌晨练过度。按摩上宜温补脾肾：每日按揉足三里、脾俞、肾俞、命门、涌泉各一分钟；以两掌搓热后按揉腰眼一分半钟。饮食上宜温补、宜平和，《饮膳正要·卷二·四时所宜》谓「冬气寒，宜食黍，以热性治其寒」，然进补须有节、有序、辨证而行，切忌骤然大补。"},{"type":"table","caption":"立冬饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","温补脾肾：羊肉、牛肉、当归生姜羊肉汤、栗、核桃、生姜","温阳散寒以应闭藏之势"],["宜食","黑色养肾：黑豆、黑米、黑芝麻（须辨证）","五色入肾，为黑色系食材所宜"],["宜食","平补气血：山药、桂圆、大枣、当归、枸杞（须辨证）","补而不峻，为冬令平补之本"],["忌食","寒凉生冷：螃蟹、刺身、冰饮、生冷瓜果、绿豆汤（过量）","冬令闭藏，过寒伤阳"],["忌食","过食肥甘厚味与烈酒","酿生痰湿，困脾碍运，且助火动血"],["推荐食材","当归生姜羊肉汤、山药排骨汤（须辨证）、板栗粥、黑豆核桃粥（须辨证）","温补与平补相济，脾胃为化源"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·鹿戏」：两脚开立，屈膝下蹲成马步，两手虚握于腹前，先以两臂内旋、外旋交替画圆九次，再以腰部为轴带动上身左右环转九周，继而后仰伸展九次。此式取鹿之矫健与蓄势，功在强健腰肾、凝聚阳气、舒展筋脉，最宜冬季日光明亮时于室内或向阳处行之。穴位按揉取五处：一为足三里，外膝眼下三寸，以拇指按揉一分半钟，健脾益气、扶正固表，为「长寿穴」；二为脾俞，第十一胸椎棘突下旁开一寸半，掌根温揉一分钟，健脾化湿；三为肾俞，第二腰椎棘突下旁开一寸半，温揉一分半钟，补肾助阳、纳气平喘；四为命门，第十四腰椎下凹陷，掌根温揉一分半钟，温补肾阳、固本培元；五为涌泉，足心前三分之一凹陷，睡前以拇指按揉一分半钟至酸胀，引火归元、助眠。亦可每日以艾条温灸关元、气海、足三里各十五分钟，须遵医嘱并防烫伤。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"立冬以后气候急剧转冷，须重点防范：一、心脑血管疾病进入高发，脑卒中、心肌梗死、主动脉夹层与心源性猝死风险显著上升，晨起血压高峰与寒冷刺激是重要诱因；二、呼吸系统疾病，感冒、流感、支气管炎、哮喘与慢阻肺急性发作增加，流感在冬春进入流行高峰；三、老年人「肠积」与营养不良，脾胃运化减弱而食欲不佳，加之天冷活动减少，易致体重下降、肌肉萎缩与营养不良，进而免疫力更弱形成恶性循环；四、冬季腹泻与急性胃肠炎，受寒与饮食不洁所致；五、慢病管理与失代偿，糖尿病患者天冷时血糖升高、胰岛素需求增加，血压亦因血管收缩而波动；六、抑郁与失眠，冬季日照减少与活动量下降使季节性情感障碍高发；七、冻疮、雷诺现象与低体温，外周循环不良者多见；八、跌倒与骨折，路面结冰与天冷活动减少使老年人跌倒风险升高。预防要点：其一，及时添衣加被并注意「洋葱式」增减，护住头颈、腰腹与足部，忌「春捂秋冻」在冬日延续；其二，晨起动作宜缓，先在被中活动、坐起静坐一分钟再下床，晨练安排在日出后并充分热身；其三，高血压患者每日监测晨起血压并规律服药，冬季调整剂量须经医师评估，切勿自行加药；其四，糖尿病患者加强血糖监测，注意保暖并备好糖果，天冷时增加活动量与降糖药调整均须遵医嘱；其五，进补须循序渐进，先调脾胃后进血肉之品，忌骤然大补或自行服用膏方；其六，老年人注意营养均衡，摄入足量优质蛋白与蔬菜，必要时请营养师评估；其七，保持每日日照与适度室内活动，情绪低落者及时求助；其八，路面结冰时减少外出，外出穿防滑鞋、拄手杖，室内加装扶手与夜灯；其九，流行季可接种流感与肺炎疫苗（依医嘱），出现胸痛、呼吸困难、意识改变或剧烈腹痛者须立即就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"立冬养生要点","items":["早卧晚起、必待日光，晨练安排在九时之后","被褥加厚，护住头颈腰腹与足部，忌冷水洗浴","进补有节有序，先调脾胃后进血肉，忌骤然大补","按揉足三里、脾俞、肾俞、命门、涌泉并可温灸","重点防心脑血管意外、流感、老年肠积与营养不良"]},{"type":"quote","text":"冬三月，此謂閉藏。水冰地坼，無擾乎陽，早卧晚起，必待日光，使志若伏若匿，若有私意，若已有得，去寒就溫，無泄皮膚，使氣亟奪，此冬氣之應，養藏之道也。","source":"《黄帝内经·素问·四气调神大论》"}]},{"id":"xiaoxue","title":"小雪","subtitle":"11月22日—23日 · 冬季","summary":"天气上升地气下降，闭塞而成冬。小雪宜温肾助阳、养阴润燥，饮食宜温补而不燥，忌过食生冷，慎防寒邪束表与心肺疾病。","blocks":[{"type":"paragraph","text":"小雪是冬季第二个节气，太阳黄经为240度，斗指戌，时在子正与丑初之间。物候上，《礼记·月令》载此时「虹藏不见，天气上升地气下降，闭塞成冬」，虹不再现于天，而天气上升、地气下降，天地之气不相交而闭塞成冬，是全年阳气闭藏趋势的明确标志。我国北方已值初雪，南方虽仍无雪而寒意渐深，昼短夜长、晨昏极冷。人体方面，阳气闭藏而卫外不固，最易为寒邪所乘：寒邪束表则恶寒发热、无汗、头身疼痛、鼻塞流清涕；寒邪直中则脘腹冷痛、呕吐泄泻、肢冷蜷卧；寒性凝滞、主痛，故寒证疼痛剧烈而得温则减。与此同时，秋燥之害尚未完全消退，燥与寒合则津液更亏，表现为干咳少痰、鼻腔干燥、唇裂、皮肤皲裂、便秘。此外，冬季闭藏而人体气血运行不畅，加之室外活动减少、居室通风不足，室内空气污浊而呼吸道疾病高发；心脉亦因寒凝而气血不畅，成为心绞痛与心肌梗死的重要诱因。故小雪之养，重在「温」与「润」双管齐下——温以散寒，润以养阴。"},{"type":"paragraph","text":"起居上宜「早卧晚起，必待日光」，冬季作息当严格遵行，宜在戌时前后（晚八至九时）入睡，早晨待日光升起后再起，晨练安排在九时之后，忌天未明或雪后路滑时勉强出行。衣着宜保暖分层，内层排汗、中层保暖、外层防风，护住头颈、背部、腰腹与足下，忌「春捂秋冻」延续至冬而受寒；夜间宜加被护腹，晨起先在被中活动再起身。居室宜保持温暖而适度通风，每日开窗一至两次以避免二氧化碳与浊气蓄积，室内可置加湿器以防干燥。洗澡宜温水不宜冷水，睡前温水泡脚一刻钟。情志上宜内敛安静，忌过度思虑与悲忧，宜静养、阅读、早睡、适度日照。运动宜太极、八段锦、慢跑、散步，忌大汗淋漓、忌雪后路滑与严寒中锻炼。按摩上宜温阳散寒：每日按揉足三里、命门、肾俞、大椎各一分钟；以两掌搓热后覆于腰腹一分钟；并以拇指按揉迎香、风门各一分钟，通鼻窍、散风寒。饮食上宜温补而兼润燥，忌一切寒凉。"},{"type":"table","caption":"小雪饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","温补脾肾：羊肉、牛肉、当归生姜羊肉汤、栗、核桃","温阳散寒，补火之源以消阴翳"],["宜食","温润滋燥：银耳、百合、梨、蜂蜜、黑芝麻、当归","温而润，润燥而不助燥"],["宜食","健脾助运：山药、白扁豆、南瓜、大枣、茯苓","脾健则气血生化有源，标本兼顾"],["忌食","寒凉生冷：冰饮、螃蟹、刺身、生腌、凉拌苦瓜","寒邪直中，腠理闭而凝滞"],["忌食","过燥伤津：辣椒、烧烤、油炸、烈酒（过量）","燥与寒合则津伤更甚"],["推荐食材","当归生姜羊肉汤、山药排骨汤（须辨证）、百合莲子粥、桂圆红枣茶","温补不燥，温润并重"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「五禽戏·猿戏」：两脚开立，屈膝下蹲成马步，两手握拳置于胸前，模仿猿之攀援举物，左右各九次；继而两臂作攀物状上下移动三十六次，再左右顾盼各九次。此式取猿之灵活柔韧，功在舒展筋骨、疏通经络、安宁心神，最宜冬季日短之时于向阳室内进行。穴位按揉取五处：一为命门，第十四腰椎下凹陷，以掌根温揉一分半钟，温补肾阳、固本培元；二为肾俞，第二腰椎棘突下旁开一寸半，温揉一分半钟，补肾助阳、纳气平喘；三为足三里，外膝眼下三寸，按揉一分半钟，健脾益气、扶正固表；四为大椎，第七颈椎棘突下凹陷，按揉一分半钟，振奋阳气、解表散寒，感冒时尤宜；五为风门，第二胸椎棘突下旁开一寸半，按揉一分钟，祛风散寒。亦可每晚以艾条温灸大椎、命门、足三里各十五分钟，助阳散寒而御风，须遵医嘱并防烫伤。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"小雪以后寒邪当令，疾病以「寒」为特征，须重点防范：一、呼吸道疾病大爆发，感冒、流感、急性支气管炎、肺炎、哮喘与慢阻肺急性发作在此时达到高峰，流感与呼吸道合胞病毒感染以婴幼儿与老年人为重；二、心血管疾病，寒冷刺激使血管收缩、血压升高、心肌耗氧增加，脑卒中、心肌梗死、心绞痛与心衰失代偿显著增多，冬季是心梗第二个高峰；三、寒性胃肠病，急性胃肠炎、胃痛、呕吐、腹泻因受寒生冷而多发，婴幼儿轮状病毒腹泻亦高发；四、冻疮、雷诺现象、寒冷性荨麻疹与低体温；五、皮肤与黏膜干燥综合征，皲裂、口唇炎、结膜炎、眼干与便秘加重；六、骨与关节病，骨质疏松性骨折、腰腿痛、类风湿关节炎在寒潮时加重；七、老年人的「肠积」与营养不良、肌肉萎缩与跌倒风险；八、情绪与睡眠障碍，冬季日照减少与活动不足使抑郁、焦虑与失眠加重。预防要点：其一，按「洋葱式」穿衣并护住头颈、腰腹与足部，忌「春捂秋冻」延续；其二，晨起晚出，晨练待日光，动作宜缓、忌空腹与路滑时锻炼；其三，饮食温热为主，忌生冷，适量温补而不燥，进补宜辨证；其四，居室温暖且每日定时通风，可加装扶手与夜灯；其五，高血压与心脏病患者加强血压监测并规律服药，不可自行加减药量，冬季方案调整须经医师评估；其六，糖尿病患者加强血糖监测，注意保暖并备糖果，以防低血糖与酮症；其七，心肺疾病患者按医嘱在入冬前完成药物与器材准备，坚持使用吸入制剂；其八，老年人保证足量蛋白与蔬菜摄入，必要时评估营养状况，注意防跌倒；其九，儿童与老人按时接种流感与肺炎疫苗（依医嘱）；其十，出现持续高热、气促、胸痛、大汗、意识改变、剧烈腹痛或腹泻脱水者须立即就医。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"小雪养生要点","items":["早卧晚起必待日光，晨练待九时后并注意路面","洋葱式穿衣，护头颈腰腹与足下，忌冬日秋冻延续","饮食温补兼润燥，忌生冷亦忌过燥","按揉命门、肾俞、足三里、大椎、风门并可温灸","重点防流感与肺炎、心梗、冻疮、胃肠病与老年跌倒"]},{"type":"quote","text":"冬氣寒，宜食黍，以熱性治其寒。禁熱飲食，溫炙衣服。","source":"《饮膳正要·卷二·四时所宜》"}]},{"id":"daxue","title":"大雪","subtitle":"12月6日—8日 · 冬季","summary":"至此而雪盛，仲冬之盛阴。大雪宜温肾助阳、养血润燥，饮食宜温补有节，忌过食温燥与生冷，慎防寒凝血瘀与心脑血管病。","blocks":[{"type":"paragraph","text":"大雪为冬季第三个节气，太阳黄经为255度，斗指亥，时在丑初与丑正之间。此时降雪量渐增、积雪渐深，《礼记·月令》载此时「鹖鴠不鸣，虎始交，荔挺出」，寒号之鸟不再鸣叫、虎开始交配，荔挺之草芽初生，三候皆示深冬阴盛而生机潜藏之象。我国北方已是大雪封地、万里冰封，南方亦湿冷明显，气温降至全年低位。人体方面，阳气闭藏日深而卫外最弱，寒邪成为最主要的致病因素：寒性凝滞收引，故气血运行不畅而痛证多见，且痛有定处、得温则减；寒性伤阳，故畏寒肢冷、脘腹冷痛、痰饮聚而不化；寒与血相搏则血瘀，而血瘀又使痛证更重。此外冬季为心脑血管疾病的高发期，《素问·生气通天论》言「故阳气者，一日而主外……日西而阳气已虚，气门乃闭」，夜间与清晨阳气最弱而血压波动最著，脑卒中与心梗多在此时发生；又冬主闭藏而气机不舒，情志抑郁、气机郁滞亦常见。燥邪虽退而津液常因室内暖气而暗耗，干咳、便秘、皮肤干裂仍多见。故大雪之养，宜温肾助阳以御寒，兼养血润燥以护津，并格外重视「防寒护心」。"},{"type":"paragraph","text":"起居上仍宜「早卧晚起，必待日光」，大雪时节白昼最短，宜在戌亥之交（约晚九时前）入睡，早晨待日光充分后再起，晨练宜在九时之后并选择日照较好之时。衣着须进一步加厚，护住头颈、颈肩、背部、腰腹与足下，室内宜使用「洋葱式」多层衣物，忌单层紧身而泄阳；夜卧宜加被护腹，晨起宜先在被中活动手足再起身，忌骤起。室外活动须防寒防滑，雪后路滑不宜外出锻炼。居室宜温暖，室内暖气与通风须平衡，每日定时开窗以防空气污浊与干燥。洗澡宜温水，睡前温水泡脚一刻钟以助阳气内达。情志上宜「使志若伏若匿」，内敛静养，忌过度思虑与忧愁，宜早睡、阅读、静坐，并争取每日日照。运动宜室内为主，如太极、八段锦、健身操，忌大汗淋漓。按摩上宜温通经络：每日按揉足三里、命门、肾俞、大椎、涌泉各一分钟；以两掌搓热后摩腰眼一分钟；以两臂从肩至手相互搓擦三十六次以通上肢阳经。"},{"type":"table","caption":"大雪饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","温补脾肾：羊肉、牛肉、当归生姜羊肉汤、栗、核桃","温阳以御寒，助阳气内藏"],["宜食","养血润燥：当归、桂圆、大枣、枸杞（须辨证）、黑芝麻、蜂蜜","血得温则行，津得润则不燥"],["宜食","健脾益气：山药、白扁豆、南瓜、粳米、莲子","脾为后天之本，脾健则气血充"],["忌食","生冷寒凉：螃蟹、刺身、冰饮、生冷蔬果（过量）","寒凝血脉，见于四肢与腹部"],["忌食","过食温燥与烈酒：辣椒、烧烤、油炸、烈酒（过量）","助火伤津、动血，与养阴相悖"],["推荐食材","当归生姜羊肉汤、桂圆红枣茶、山药小米粥、黑豆核桃粥（须辨证）","温补与养血润燥并举"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「八段锦·背后七颠」与「两手上托」二式配合：先以两脚跟提起、放下，反复七次以震动督脉与肾经；再两手上托如擎天状，向上撑举并拉伸腰背九次，同时仰头目视上方。此二式出自八段锦，能振奋阳气、拉伸督脉、牵伸脊背，最宜大雪之日在向阳处缓行之。穴位按揉取五处：一为命门，第十四腰椎下凹陷，掌根温揉一分半钟，温补肾阳；二为肾俞，第二腰椎棘突下旁开一寸半，温揉一分半钟，补肾助阳、纳气平喘；三为足三里，外膝眼下三寸，按揉一分半钟，健脾益气、扶正固表；四为大椎，第七颈椎棘突下凹陷，按揉一分半钟，解表散寒、振奋阳气；五为涌泉，足心前三分之一凹陷，睡前按揉一分半钟至酸胀，引火归元、助眠。亦可用手握空拳轻捶腰骶部三十六次，或以双手掌搓热覆于肾俞处一分钟，助肾阳温煦。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"大雪是一年中最冷的时节之一，须重点防范：一、严寒相关疾病，冻伤、冻疮、低体温、寒冷性荨麻疹、雷诺现象与冷性哮喘增多；二、心脑血管意外进入最高风险期，脑卒中、心肌梗死、心绞痛、主动脉夹层与心源性猝死多在清晨与夜间发生，寒冷与晨起血压高峰是核心诱因；三、呼吸道疾病高发，流感、肺炎、急性支气管炎、慢性阻塞性肺疾病急性加重、哮喘急性发作，老幼与慢病患者为重；四、冬季腹泻与急性胃肠炎，受寒与轮状病毒、诺如病毒感染并存，婴幼儿与老人易出现脱水与电解质紊乱；五、肌肉关节疾病，腰痛、颈椎病、类风湿关节炎与骨关节炎因寒凝血瘀而加重，冬季是颈腰痛高发期；六、皮肤与黏膜干燥病，皲裂、口唇炎、眼干、便秘、老年瘙痒症高发；七、精神心理疾病，季节性情感障碍、失眠与焦虑加重，冬季为自杀风险相对较高时期，须重视；八、老年人跌倒与骨折，路面冰雪与天寒行动不便使风险升高。预防要点：其一，「大雪封河」之际尽量减少非必要外出，尤其避免清晨独自外出与独居老人独自活动；其二，穿衣务必护住头颈、背部、腰腹与足部，帽子与手套不可省，鞋子须防滑保温，衣袖宽松不致束血；其三，室温宜控制在适宜范围，过低则冷凝血管，过高而干燥则耗津，宜用加湿器并每日通风；其四，饮食温热、适量进补，忌生冷与暴饮暴食，每日饮水充足而宜温；其五，晨起与夜间动作宜缓，起夜时开灯、动作放慢，防止体位性低血压与跌倒；其六，高血压、糖尿病、冠心病患者坚持规律用药与监测，冬季方案调整须经医师评估，切勿自行停药或加量；其七，心肺疾病患者须按医嘱使用药物与吸入制剂，切勿因畏寒而自行减量或停用；其八，跌倒高危老人家中加装扶手、防滑垫与夜灯，穿合脚防滑鞋，必要时使用助行器；其九，情绪明显低落者及时向家人与专业人员求助，切勿独处；其十，出现持续高热不退、呼吸困难、剧烈胸痛、意识模糊、言语不清或肢体无力者须立即拨打急救电话。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"大雪养生要点","items":["白昼最短，早卧晚起必待日光，晨练九时后并防路滑","加厚衣着护住头颈腰腹与足部，帽子手套不可省","室温适宜并加湿通风，饮食温热适量进补","行背后七颠与两手上托，按揉命门、肾俞、足三里、涌泉","重点防心脑血管意外、严寒伤害、呼吸道病与跌倒骨折"]},{"type":"quote","text":"去寒就溫，無泄皮膚，使氣亟奪，此冬氣之應，養藏之道也。","source":"《黄帝内经·素问·四气调神大论》"}]},{"id":"dongzhi","title":"冬至","subtitle":"12月21日—23日 · 冬季","summary":"一阳初生，日最短而阳气始萌。冬至宜静养藏精、温补有节、忌大补，饮食宜温润平和，慎防寒邪内侵与心脑血管病。","blocks":[{"type":"paragraph","text":"冬至是二十四节气中最早被确定的一个节气，太阳黄经为270度，斗指子，时在丑正与寅初之间。此日太阳直射南回归线，北半球白昼最短、黑夜最长，故称「日短之至、日影长之至」；此后太阳直射点北移，昼渐长而夜渐短，古称「一阳生」，《易·复卦》以「一阳来复」喻之，谓一阳生于下而复生于上。物候上，《礼记·月令》载此时「蚯蚓结，麋角解，水泉动」，蚯蚓蜷结深藏、麋鹿解角、水泉萌动，三候皆寓阴极阳生、蛰伏生机始动之义。对人体而言，此时阳气处于全年最低点而生机潜藏待发，最宜静养、藏精、蓄锐；《素问·四气调神大论》言「冬三月，此谓闭藏……使志若伏若匿，若有私意，若已有得」，即主张心神内敛、体气潜藏。生理上，冬季血液黏稠度升高、血压晨峰显著，凝血与血栓风险上升，脑卒中、心肌梗死是发病最高的时段之一；又寒邪直中易致阳虚内寒，脾胃虚寒者的脘腹冷痛、晨泻在此季最明显。体质上，素体阳虚、畏寒肢冷者当借此时温养，而素体阴虚火旺者则当静养而忌温燥太过。"},{"type":"paragraph","text":"起居上宜「早卧晚起，必待日光」，冬至为全年阴气最盛之时，宜在戌时（晚八至九时）前入睡，早晨待日光升起后再起身，晨练宜在九时之后，或改于午后向阳处进行。衣着须充分保暖，护住头颈、颈肩、背部、腰腹与足下，帽子、围巾、手套与保暖鞋袜皆不可省，寝时宜加被护腹并注意夜间「蹬被」；忌「春捂秋冻」延续而受大寒。居室宜温暖，室内须每日定时通风并使用加湿器，忌长期紧闭门窗。洗澡宜温水，睡前温水泡脚一刻钟。情志上宜「使志若伏若匿」，内敛含蓄，忌大喜大悲、忌强行振奋与耗神，宜静养、读书、早睡、晒太阳。运动宜柔缓持久，忌大汗淋漓与严寒中大强度锻炼。按摩上宜温补脾肾、滋水涵木：每日按揉足三里、命门、肾俞、太溪各一分钟；以两掌搓热后按揉腰眼一分钟；以拇指按揉涌泉与太冲各一分钟。饮食上宜温润平和、补中有静，《饮膳正要·卷二·四时所宜》谓「冬气寒，宜食黍，以热性治其寒」，然冬至阳气初萌，最忌骤然大补致虚不受补，当取「温润、缓补、平补」之法。"},{"type":"table","caption":"冬至饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","温润平补：当归生姜羊肉汤、山药、桂圆、大枣、莲子、粳米","一阳初生，补而不峻为要"],["宜食","温阳散寒：羊肉、生姜、核桃、栗、枸杞（须辨证）","温助初萌之阳气"],["宜食","温润养血：当归、黑芝麻、蜂蜜、百合、银耳","血得温则行，津得润则安"],["忌食","寒凉生冷：螃蟹、刺身、冰饮、生冷蔬果（过量）","阴盛之际，寒上加寒"],["忌食","大补峻剂与温燥：膏方骤进、辣椒、烧烤、烈酒（过量）","虚不受补则上火，津伤则生燥"],["推荐食材","当归生姜羊肉汤、桂圆红枣茶、山药小米粥、百合莲子粥","温润平补，脾胃为枢纽"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「冬至·一阳来复式」：两脚开立，两手交叠于腹前，闭目静养，先以鼻吸三十六息，气沉丹田，再徐徐呼出三十六息；继而两手上举，掌心相对如托天状，缓缓上撑并吸气，共九次；再缓缓放下并呼气九次。此式取「一阳生于下、复归于上」之义，能助阳气升发而不耗散，最宜冬至日在向阳处静坐行之。穴位按揉取五处：一为关元，脐下三寸，以掌根温揉一分半钟，温补肾阳、培元固本，为虚寒要穴；二为气海，脐下一寸半，温揉一分钟，益气固脱、培补元气；三为足三里，外膝眼下三寸，按揉一分半钟，健脾益气、扶正固表；四为太溪，内踝尖与跟骨之间凹陷，按揉一分钟，滋肾阴、纳浮阳；五为涌泉，足心前三分之一凹陷，睡前按揉一分半钟至酸胀，引火归元、助眠。另可于冬至前后用艾条温灸足三里、关元各十五分钟，须遵医嘱并防烫伤。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"冬至是全年疾病谱中最需警惕的时段之一：一、心脑血管疾病达到全年最高峰，脑卒中、心肌梗死、心绞痛、主动脉夹层、心源性猝死多在清晨与夜间发生，「晨峰高血压」与血液黏稠度升高叠加寒凉刺激是核心机制；二、呼吸道疾病高发，感冒、流感、肺炎、支气管炎、哮喘与慢阻肺急性发作进入高峰，老幼与慢病患者为重；三、脾胃虚寒者最易出现脘腹冷痛、呕吐、晨泻、完谷不化，老年人与婴幼儿尤甚；四、冬季腰腿痛与关节病加剧，颈腰椎间盘突出、坐骨神经痛、骨关节炎、类风湿关节炎发作，寒冷与血瘀互为因果；五、冻疮、雷诺现象、冷性荨麻疹与低体温体温过低；六、老年人跌倒与骨折，为冬季致死致残的重要原因；七、抑郁、焦虑、失眠与「季节性情感障碍」高发，冬季自杀风险相对升高，须高度重视心理照护；八、老年人营养不良与「肠积」，食欲下降与活动减少形成恶性循环，肌肉流失与免疫力下降互相促进。预防要点：其一，冬季外出尽量避开清晨与深夜，独居老人避免独行独处，家庭成员宜多问候；其二，穿戴须充分保暖，护住头颈、腰腹与足部，衣宽松不束血；其三，晨起动作宜缓，先在被中活动再起身，起夜时开灯并缓慢，路面结冰时减少外出；其四，居室温度适宜、每日通风、加湿使用，人群密集处佩戴口罩以减少呼吸道感染；其五，高血压、糖尿病、冠心病患者坚持规律用药与血压血糖监测，冬季调整方案须经医师评估，切勿自行停药或加量；其六，冬季进补须辨证、循序渐进，先健脾后补肾，忌骤然大补与盲目服用膏方，阴虚火旺者尤当忌温燥；其七，保证每日优质蛋白（鱼、蛋、奶、瘦肉、豆制品）与足量蔬菜，主食粗细搭配，食欲差者少量多餐；其八，保持适度室内运动与每日日照，情绪低落、失眠明显或有自伤念头者当立即求助家人与专业人员；其九，出现持续高热、呼吸困难、剧烈胸痛、大汗淋漓、意识模糊、言语不清、单侧肢体无力或剧烈腹痛者须立即拨打急救电话。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"冬至养生要点","items":["阴极阳生，宜早卧晚起、必待日光，晨练九时后","穿戴充分保暖护头颈腰腹与足部，忌冬日秋冻延续","进补宜温润平补、循序渐进，忌骤然大补与膏方乱用","行一阳来复式，按揉关元、气海、足三里、太溪、涌泉","重点防心脑血管意外、呼吸道感染、脾胃虚寒与情绪低落"]},{"type":"quote","text":"使志若伏若匿，若有私意，若已有得，去寒就温，无泄皮肤，使气亟夺。","source":"《黄帝内经·素问·四气调神大论》"}]},{"id":"xiaohan","title":"小寒","subtitle":"1月5日—7日 · 冬季","summary":"冷气积久而寒甚，冰天雪地。小寒宜温肾助阳、固护脾肾，饮食宜温补有节不燥烈，慎防严寒冻伤、心脑血管病与呼吸道病。","blocks":[{"type":"paragraph","text":"小寒是冬季第四个节气，太阳黄经为285度，斗指丑，时在寅初与寅正之间。此时已入深冬，《礼记·月令》载此时「雁北乡，鹊始巢，雉始雊」，鸿雁开始北归、喜鹊开始筑巢、野鸡开始鸣叫，三候皆为岁末冬深、阳气将萌之象。我国北方冰封雪锁、气温常在零下十度以下，江南亦寒气逼人，日照时间短而寒湿并存。人体方面，阳气闭藏至极而阴寒之盛臻于顶点：寒邪束表则恶寒、发热、无汗、头身疼痛；寒邪直中脏腑则脘腹剧痛、呕吐、泄泻、手足厥冷；寒凝血瘀则痛证加剧，关节、腰背、心脉皆受其害；寒性伤阳，脾肾阳虚者的晨泻、畏寒、精神萎靡在此季最为明显。此时亦是心脑血管疾病与呼吸道疾病的高峰，晨起与夜间气温最低、血压波动最大，脑卒中与心梗多发；而「冬不藏精，春不病温」，冬季过度耗泄会削弱来年的抵抗力。此外，居室暖气与室外严寒造成的巨大温差，使呼吸道感染率显著上升，老幼与慢病患者首当其冲。故小寒之养，重在「固肾护阳、慎起居、防寒保暖」，并尤须注意保护头部、足部与腰腹三处。"},{"type":"paragraph","text":"起居上宜「早卧晚起，必待日光」，小寒为全年最冷之候，宜在戌时（晚八时前后）即行安寝，早晨须待日光升起、气温回升后再起，晨练宜移至九时之后或改在午后向阳处；凡遇寒潮、降雪、大风天气，宜完全取消户外锻炼，改在室内行导引。衣着宜「洋葱式」三层加厚，务必戴帽、围巾与手套，穿高帮保暖鞋，护住头部、腰腹与足踝；室内外温差宜控制在十度以内，进出屋子时宜在门厅稍作停留以适应温差；忌「春捂秋冻」在寒冬延续。睡前可用温水泡脚一刻钟，洗澡宜水温略高、时间不宜过久。情志上宜内敛安静，忌过用脑力与情绪激动，宜早睡、静养、晒太阳；年节将近更须避免熬夜与劳心。运动宜八段锦、太极、室内健身操为主，忌大汗淋漓。按摩上宜温阳固肾：每日按揉足三里、命门、肾俞、大椎、涌泉各一分钟；以两手握拳互相捶击腰骶各三十六次；以掌心搓热覆于小腹一分钟。饮食上宜温补有节、忌过燥烈，宜在温补之中佐以滋阴之品，使温而不燥。"},{"type":"table","caption":"小寒饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","温补脾肾：羊肉、牛肉、当归生姜羊肉汤、栗、核桃","温阳散寒，助阳气封藏"],["宜食","温补兼滋阴：枸杞（须辨证）、当归、百合、麦冬（须辨证）、黑芝麻","温而不燥，防温补伤津"],["宜食","健脾养胃：山药、白扁豆、南瓜、粳米、茯苓、莲子","脾健则生化有源，为进补之基"],["忌食","寒凉生冷：螃蟹、刺身、冰饮、生腌、生冷蔬果（过量）","大寒之时，寒邪直中"],["忌食","过燥烈与酒：辣椒、烧烤、烈酒、油炸（过量）","助火动血，灼伤肺津"],["推荐食材","当归生姜羊肉汤、桂圆红枣茶、山药排骨汤（须辨证）、黑豆核桃粥（须辨证）","温补有节，温润并重"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「八段锦·五劳七伤」与「攒拳怒目增气力」二式：先以两臂后屈、掌心向内，缓慢转身拗腰，左右各九次，以活动腰腹；再握拳攒于腰际，怒目瞪视，一拳向前缓缓冲出，左右各九次，以振奋阳气。此二式出自八段锦，能强健腰腹、振奋精神，最宜小寒之日在室内向阳处行之。穴位按揉取五处：一为命门，第十四腰椎下凹陷，掌根温揉一分半钟，温补肾阳、固本培元；二为肾俞，第二腰椎棘突下旁开一寸半，温揉一分半钟，补肾助阳、纳气平喘；三为足三里，外膝眼下三寸，按揉一分半钟，健脾益气、扶正固表；四为大椎，第七颈椎棘突下凹陷，以拇指按揉一分半钟，振奋阳气、解表散寒；五为涌泉，足心前三分之一凹陷，睡前按揉一分半钟至酸胀，引火归元、助眠。亦可每日以艾条温灸足三里、命门、气海各十五分钟，须遵医嘱并注意防烫伤。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"小寒为全年最严寒之候，须重点防范：一、严寒相关急症，冻伤、冻疮、低体温症、寒冷性荨麻疹、雷诺现象与冷性哮喘增多，老人与婴幼儿尤须留意体温与肢端血运；二、心脑血管疾病处于全年高峰，脑卒中、心肌梗死、心绞痛与心源性猝死多在清晨、夜间与寒潮时发生，血压晨峰与血液黏稠度增高为核心诱因；三、呼吸道疾病，感冒、流感、支原体肺炎、病毒性肺炎、慢性阻塞性肺疾病急性加重与哮喘发作高发，老幼、慢病患者与免疫低下者最重；四、冬季腹泻与胃肠病，脾胃虚寒者晨泻、完谷不化，婴幼儿轮状病毒与诺如病毒感染易致脱水；五、肌肉骨骼疾病，颈肩腰痛、坐骨神经痛、类风湿关节炎与骨质疏松性骨折在严寒时多发；六、干燥综合征，室内暖气造成湿度过低而致口眼干、皮肤干裂与便秘，老年人与绝经后女性尤甚；七、冬季精神心理危机，季节性情感障碍、失眠、焦虑与孤独感加剧，独居老人为高危群体，须加强家庭与社区照护；八、老年人营养不良与肌肉衰减；九、用火与取暖安全，冬季取暖致一氧化碳中毒与火灾风险上升。预防要点：其一，寒潮与降雪日尽量不外出，尤其避免清晨与夜间独行；其二，戴帽子围巾手套、穿保暖鞋袜，保护头颈腰腹与足踝，室内外温差控制在十度以内，进出屋子在门厅缓留片刻；其三，起居遵「早卧晚起，必待日光」，晨练推迟，忌空腹与路滑时锻炼；其四，高血压、糖尿病、冠心病患者规律监测与用药，切勿自行停药，冬季调整须经医师评估；其五，冬季进补须辨证、宜温润平补，忌大补峻剂与烈酒助兴，年节饮食尤须节制，糖尿病患者尤须防血糖波动与酮症；其六，注意营养均衡，保证蛋白与蔬菜，主食粗细搭配，食欲差者少量多餐；其七，独居老人与慢性病老人宜有固定探视安排，家中备应急联络方式；其八，使用取暖设备须保持通风、远离易燃物，安装一氧化碳报警器，出现头痛头晕恶心即开窗并撤离并呼救；其九，居室每日定时通风并使用加湿器；其十，出现持续高热、呼吸困难、剧烈胸痛、意识模糊、言语不清、单侧肢体无力、严重冻伤或持续腹泻脱水者须立即就医或拨打急救电话。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"小寒养生要点","items":["早卧晚起必待日光，寒潮日取消户外锻炼","帽围巾手套与保暖鞋不可省，室内外温差宜小于十度","进补温润有节，忌大补峻剂与酒，年节饮食尤须节制","行五劳七伤与攒拳怒目式，按揉命门、肾俞、足三里、涌泉","重点防心脑血管意外、呼吸道病、冻伤、抑郁与取暖安全"]},{"type":"quote","text":"早卧晚起，必待日光，使志若伏若匿，若有私意，若已有得。","source":"《黄帝内经·素问·四气调神大论》"}]},{"id":"dahan","title":"大寒","subtitle":"1月20日—21日 · 冬季","summary":"寒气之逆极，一阳将生。大寒宜温补肾阳、蓄势养神，饮食宜温润平衡、忌过补过燥，为春生做好准备，慎防寒极生热与心脑血管病。","blocks":[{"type":"paragraph","text":"大寒是二十四节气中的最后一个节气，也是三九天中最冷的一候，太阳黄经为300度，斗指癸，时在丑正与寅初之间。《礼记·月令》载此时「鸡始乳，征鸟厉疾，水泽腹坚」，母鸡开始孵卵，鹰隼等猛禽在高寒中振翅迅疾，积水结冰坚硬至此，冰冻三尺而人畜绝迹，为一年中最酷寒之候。此时寒气之盛已至极点，然物极必反——阳气已潜藏一冬而生机始动，太阳黄经每日递增，一阳来复之势已蓄而未发，古人于此际最重「藏」，《素问·四气调神大论》所谓「使气亟夺」之义正在于把阳气牢牢封藏于内，以待来春之生。人体方面，寒极则阳气郁闭于内而外达不足，畏寒肢冷、精神沉郁、脾胃阳气亏虚之象最为明显；然亦有素体阳热或久服温燥者，至此反见口干咽痛、烦躁失眠、便干尿赤，即所谓「寒极生热」，不可一概温补。此外，年度大寒时节亦是全年疾病谱的收尾期：心脑血管疾病与呼吸系统疾病仍处高峰，且年末应酬、饮食不节、熬夜劳累与情绪波动叠加，最易诱发急性胃肠炎、急性胰腺炎、酒精性肝病、痛风急性发作与心脑血管意外。精神方面，岁末焦虑、抑郁与睡眠障碍亦见多发。"},{"type":"paragraph","text":"起居上仍当遵「早卧晚起，必待日光」，大寒为全年最冷之候，宜在戌时（晚八时前后）入睡，早晨待日光充分、气温回升后再起身，晨练宜在九时之后或改于室内，绝不勉强外出。衣着须最充分保暖，戴帽围手套、穿保暖鞋袜，护住头部、颈肩、腰腹与足踝；室内外温差宜小于十度，进出屋子于门厅稍停；室温宜适宜而不过高，并每日定时通风，忌紧闭门窗致空气污浊。睡前温水泡脚一刻钟，洗澡水温宜略高、时间不宜过长。情志上宜「使志若伏若匿」，年末事务繁杂，尤须节劳少思、避免熬夜与情绪激动，忌以纵情声色或过劳透支为「年节仪式」，宜早睡、静养、适度日照。运动宜八段锦、太极与室内健身操，忌大汗淋漓与大强度锻炼。按摩上宜温补脾肾、蓄养阳气：每日按揉足三里、命门、肾俞、涌泉、太溪各一分钟；以两掌搓热覆于腰腹一分钟；以两足心相搓至热覆于小腹一分钟。饮食上宜温补有节、平调阴阳，《饮膳正要·卷二·四时所宜》谓「冬气寒，宜食黍，以热性治其寒」，然大寒已近春临，进补宜逐渐减量并转以平补滋养，为来春脾胃生生之气蓄力。"},{"type":"table","caption":"大寒饮食宜忌","head":["类别","内容","说明"],"rows":[["宜食","温补有节：羊肉、牛肉、当归生姜羊肉汤、栗、核桃","阳气内藏而渐萌，温补不宜过量"],["宜食","平补滋养：山药、桂圆、大枣、莲子、百合、黑芝麻、粳米","为来春脾胃生生之气蓄力"],["宜食","温润而不燥：枸杞（须辨证）、当归、蜂蜜、麦冬（须辨证）","寒极生热者可用以润其燥"],["忌食","过补过燥：膏方骤进、羊肉（过量）、辣椒、烈酒","恐助热动血，耗伤津液"],["忌食","年节无度：肥甘厚味、暴饮暴食、隔夜菜、腌腊生食","应酬之食最易伤脾胃、酿痰湿"],["推荐食材","山药小米粥、桂圆红枣茶、当归生姜羊肉汤、百合莲子粥","进补渐减，转为平补以迎春"]]},{"type":"callout","variant":"info","title":"导引与穴位保健","text":"导引宜取「八段锦·摇头摆尾去心火」与「背后七颠」二式配合：先以马步站定，双手叉腰，头摇尾摆、左右转动各九次，转至尽处稍停以牵伸腰脊；继而两脚跟提起放下，反复七次以震动督脉、肾经。此二式出自八段锦，能强健腰肾、疏解腰背僵硬，最宜大寒之日在室内或向阳处缓行之。穴位按揉取五处：一为关元，脐下三寸，掌根温揉一分半钟，温补肾阳、培元固本；二为命门，第十四腰椎下凹陷，掌根温揉一分半钟，温补肾阳、固本培元；三为足三里，外膝眼下三寸，按揉一分半钟，健脾益气、扶正固表；四为太溪，内踝尖与跟骨之间凹陷，按揉一分钟，滋肾阴、纳浮阳，为阴阳双补之要穴；五为涌泉，足心前三分之一凹陷，睡前按揉一分半钟至酸胀，引火归元、助眠。亦可每日以艾条温灸足三里、关元各十五分钟，至立春前逐渐减量，须遵医嘱。"},{"type":"callout","variant":"warning","title":"该节气易发疾病与预防","text":"大寒为年度收尾之期，各系统疾病仍处高发，须重点防范：一、心脑血管疾病，脑卒中、心肌梗死、心绞痛、主动脉夹层与心源性猝死全年最高峰，寒潮、晨峰高血压与年节劳累共同致病；二、呼吸道疾病，流感、肺炎、慢阻肺急性加重与哮喘发作高发，兼有节日聚餐导致的交叉感染；三、急性消化系统疾病，暴饮暴食与酒精相关，急性胰腺炎、急性胆囊炎、急性胃肠炎、消化性溃疡穿孔、肝损伤与高血压脑病均见增加，其中高血压合并饮酒所致脑病尤为凶险；四、痛风与代谢病急性发作，节日高嘌呤、高酒精饮食使痛风性关节炎急性发作、血尿酸升高与糖尿病失控频见；五、严寒相关疾病，冻伤、冻疮与低体温；六、老年人的营养不良与「肠积」，天冷食欲差而活动少，肌肉衰减加速；七、精神心理疾病，年末焦虑、抑郁、失眠与酒精依赖风险升高，节假日期间情绪危机与自伤风险不容忽视；八、用火取暖安全与交通出行安全，冬季一氧化碳中毒、火灾与冰雪路面交通事故高发。预防要点：其一，年节期间仍须规律作息，切勿通宵达旦与暴饮暴食，饮酒务必适量，服药期间严禁饮酒；其二，高血压、糖尿病、冠心病患者绝不可因过节而停药或漏服，须照常监测血压与血糖；其三，胰腺炎与胆囊疾病高发，节庆饮食宜少油少酒、细嚼慢咽，避免暴食与一次性大量进食高脂高蛋白食物；其四，痛风患者严格限制高嘌呤食物、严禁啤酒与动物内脏，每日饮水二千毫升以上并遵医嘱用药；其五，寒潮期间减少外出，注意头颈腰腹与足部保暖，路面结冰时不出行或谨慎慢行；其六，独居老人与慢病老人节日期间应有家人探视与照护，备好常用药、急救药与紧急联络方式；其七，取暖须通风并使用一氧化碳报警器，睡前检查取暖设备；其八，注意居室通风与加湿，饮食均衡、保证蛋白与蔬菜；其九，情绪低落、失眠严重或有自伤念头者当立即向家人与专业人员求助；其十，出现持续高热、呼吸困难、剧烈或持续胸痛、大汗、意识模糊、言语不清、单侧肢体无力、剧烈上腹痛、呕吐不止者须立即拨打急救电话。本节所述导引、穴位按揉与饮食调养均不能替代药物治疗，患病者须辨证由医师诊治，用药调整须遵医嘱。"},{"type":"keypoints","title":"大寒养生要点","items":["早卧晚起必待日光，寒潮日绝不作户外锻炼","穿戴最充分保暖，室内外温差宜小于十度","进补渐减转平补，为来春脾胃蓄力；年节饮食有节","行摇头摆尾与背后七颠式，按揉关元、命门、足三里、太溪、涌泉","重点防心脑血管意外、胰腺炎、痛风发作与取暖安全"]},{"type":"quote","text":"逆四時之氣，雖有強壯之形，從之則病生，故病不可治。","source":"《黄帝内经·素问·四气调神大论》"}]}]}},"constitution":{"page":{"key":"constitution","title":"中医体质辨识","subtitle":"九种体质分型·形态特征·辨证要点·调养指南","description":"以王琦九种体质分型为纲，系统介绍平和质、气虚质、阳虚质、阴虚质、痰湿质、湿热质、血瘀质、气郁质、特禀质的形态特征、心理倾向、常见表现、辨证要点、易患倾向与调养方案，是开展中医治未病与个体化调理的入门读本。","lead":"体质是先天禀赋与后天获得共同塑造的相对稳定特征，既反映个体在形态结构、生理功能与心理状态上的差异，也决定对病邪的易感性、疾病传变的趋向与治疗反应的强弱。中医体质学以九种基本体质为框架，把「因人养生、因人施治」落实为可辨识、可分类、可调摄的具体方案。本页逐一体质的形态、面色、性格、适应能力、辨证要点、饮食宜忌与起居情志运动调摄之法，并附体质与病因病机、辨证治疗关系之总论，供体质辨识与健康调养参考。","type":"section","icon":"fa fa-id-card","sections":[{"id":"overview","title":"体质学说总论","subtitle":"源流、概念、构成、分类与体病关系","icon":"☯","summary":"体质学说的形成源流与基本内涵，体质由形态结构、生理功能、心理状态三方面构成，九种基本体质分类框架，以及体质与病因、病机、辨证、治疗、养生的内在联系。","badge":"总论","blocks":[{"type":"paragraph","text":"体质学说的思想萌芽于《黄帝内经》。《灵枢·天年》以「以母为基，以父为楼」说明个体禀赋的先天来源，《素问·上古天真论》提出「形与神俱，而尽其终始」，为体质学说奠定了先天禀赋与身心一体的理论根基；《素问·生气通天论》所谓「阴平阳秘，精神乃治」，则从阴阳协调的高度揭示了个体体质差异的实质。历代医家又在临证中不断丰富这一学说：《诸病源候论》强调「人各有其气性」，指出体质具有个体特异性；金元时期朱丹溪《格致余论》提出「阳常有余，阴常不足」，从阴阳偏頇角度描述人群体质倾向；明·张景岳《景岳全书》详论禀赋强弱与病因的关系，奠定了「因人制宜」的思想基础。二十世纪七十年代以来，王琦等学者在系统整理历代文献并结合临床观察的基础上，提出以形态结构、生理功能和心理状态为差异依据的体质分型新思路，继而明确了各体质的形态特征、生理特点、心理倾向与常见表现。一九九五年，王琦等公开提出平和质、气虚质、阳虚质、阴虚质、痰湿质、湿热质、血瘀质、气郁质、特禀质九种基本体质分型；二零零九年《中医体质分类与判定》经中华中医药学会发布为行业标准，九种体质各设单一体质与兼夹体质两类判定条目，使体质辨识由经验描述走向规范化、可量化、可重复，为「治未病」与个体化诊疗提供了可操作的工具，也使「因人养生、因人施治」不再停留于抽象口号。"},{"type":"table","caption":"中医体质学说的源流与学术进展","head":["时期","代表文献或人物","学术贡献"],"rows":[["《黄帝内经》时期","《灵枢·天年》《素问·上古天真论》","提出先天禀赋与形神一体的体质思想，奠定体质学说理论基础"],["隋·唐","《诸病源候论》","强调「人各有其气性」，指出体质具有个体特异性"],["金·元时期","朱丹溪《格致余论》","提出「阳常有余，阴常不足」，从阴阳偏頇角度描述体质倾向"],["明·清时期","张景岳《景岳全书》等","详论禀赋强弱与病因关系，确立「因人制宜」的辨治原则"],["二十世纪七十年代","王琦等学者","提出以形态结构、生理功能、心理状态为差异依据的体质分型新思路"],["一九九五年","王琦等体质分型研究","确立九种基本体质分型，明确各型的形态、生理、心理特征与判定要点"],["二零零九年","《中医体质分类与判定》行业标准","规范九种体质的分类条目与判定方法，形成可操作的量化工具"]]},{"type":"heading","level":3,"text":"一、体质的概念与构成"},{"type":"paragraph","text":"体质是指人体在先天禀赋和后天获得的基础上所形成的形态结构、生理功能和心理状态方面综合的、相对稳定的固有特质。体质强调三个要点：一是整体性，体质是形态结构、生理功能与心理特征的综合表现，不能仅以某一脏腑或某一体征概括；二是相对稳定性，体质形成后具有不易改变的一面，这是「同病异治」与「异病同治」得以成立的前提；三是动态可变性，体质可随年龄、季节、生活环境、饮食起居、情志劳逸与疾病的影响而发生程度不等的偏移，青年时期渐定，年老渐衰，疾病期可出现体质偏移。故体质既非固定不变的「天生标签」，也非可以随意改变的临时状态，而是在一定条件下稳定而又可调的中间变量。"},{"type":"table","caption":"体质构成的三个方面","head":["构成要素","具体内涵","临床辨识意义"],"rows":[["形态结构","外部形态（体型、胖瘦、体态、面色、肤色、肌肉骨骼、五官）与内部形态（脏腑、经络、气血津液、形体结构）","体质差异的物质基础，「有诸内必形诸外」的外在依据"],["生理功能","脏腑经络功能及精气血津液的生成、运行、输布与化生，体现为代谢、汗出、饮食、二便、耐受性等","决定机体对外邪的应答方式与疾病传变趋势"],["心理状态","性格、气质、意志、情感及对情志刺激的应答方式","影响情志致病倾向与治疗依从性，为「形神合一」的具体落实"]]},{"type":"heading","level":3,"text":"二、体质的分类：九种基本体质"},{"type":"paragraph","text":"依据形态结构、生理功能与心理特征的综合性差异，王琦等将人体体质分为九种基本类型。平和质是阴阳气血调和、脏腑功能协调的相对理想状态，是人群的主体；其余八种为偏颇体质，分别由气、阳、阴、津液、血、气机与先天禀赋等某一方面的偏盛偏衰所主导。偏颇体质之间可以兼夹，如「气虚质兼痰湿质」「阳虚质兼气郁质」，临床须以主要矛盾为主、兼夹为辅。分类的价值在于：其一，提示发病倾向——不同体质对不同病邪的易感性不同；其二，提示病机演变——体质影响疾病传变与转归；其三，指明干预方向——调养与治疗可针对体质偏颇之处进行修正，从而降低疾病发生的可能性。"},{"type":"table","caption":"九种基本体质分类总表","head":["体质","形态特征","心理特征","对外适应能力","易患倾向"],"rows":[["平和质","体形匀称健壮，肤色润泽，须发稠密有光泽","性格随和开朗，思维敏捷，情志调畅","适应能力强，耐寒耐热，饮食睡眠规律，不易患病","患病少，康复快"],["气虚质","形体偏瘦或虚胖，肌肉松软不实，面色萎黄少华","内向安静，缺少活力，易疲劳，注意力不易集中","卫外不固，腠理疏松，耐受寒湿暑热与劳倦能力差","感冒、咳嗽、哮喘、自汗、疲劳、便秘、腹泻"],["阳虚质","形体偏胖或中等，肌肉松软，畏寒肢冷，面色㿠白","沉静内向，多喜安静，意志较薄弱，易感疲惫","耐寒不耐热，易受寒邪，代谢率低，产热不足","感冒、咳喘、腹泻、痹证、水肿、阳虚型失眠"],["阴虚质","形体偏瘦，手足心热，口燥咽干，肤色偏红","外向好动，急躁易怒，睡眠少而多梦","不耐暑热与燥邪，需津液滋润，易出现干燥与内热","咳嗽、咽痛、便秘、眩晕、更年期综合征、盗汗"],["痰湿质","体形肥胖，腹部肥满松软，面部皮肤油脂较多","性格偏温和敦厚，善忍让，反应迟钝，多善思考","耐受寒湿较佳但湿邪易困，代谢迟缓，关节易受湿邪","肥胖、痰饮、咳嗽、哮喘、高血压、糖尿病、眩晕"],["湿热质","形体中等或偏瘦，面垢油光，易生痤疮，口苦","多急躁易怒，思维敏捷，好动少眠","不耐湿热，对夏秋暑湿之邪敏感，湿热蕴结易化火","痤疮、湿疹、痢疾、黄疸、口疮、淋证、痛风"],["血瘀质","形体偏瘦或消瘦，肤色晦暗，色素沉着或有瘀斑","性格易烦，健忘，喜静恶动，情感不易表露","血行不畅，易痛，瘀血内阻，女子经血多不畅","痛证、癥瘕、冠心病、痛经、痹证、肌肤甲错"],["气郁质","形体偏瘦，神情抑郁，胸胁胀闷，常叹气","内向不稳定，易烦闷，多愁善感，敏感多虑","适应能力较差，遇事易消极，情绪波动明显","脏躁、梅核气、百合病、抑郁状态、失眠、乳腺增生"],["特禀质","先天禀赋特殊，可有畸形、胎记、过敏体征，肤色不匀","反应敏感，多疑善虑，或特殊嗜好，体质稳定性差","对季节、气候、药物、食物反应强烈，易出现过敏与特异反应","过敏性疾病、哮喘、荨麻疹、遗传性疾病、某些自身免疫病"]]},{"type":"heading","level":3,"text":"三、体质与病因、病机、辨证、治疗及养生的关系"},{"type":"paragraph","text":"体质与病因：体质决定对某些病邪的易感性。《素问·评热病论》说「邪之所凑，其气必虚」，《素问·刺法论》说「正气存内，邪不可干」，正说明体质的偏颇决定发病与否与发病的病邪性质。阳虚者畏寒而易感寒邪，阴虚者喜凉而易感燥热之邪，痰湿质者易受湿邪，气郁质者易因情志拂郁而发病。体质与病机：体质影响病机从化与传变，同为外感发热，阳虚质易从寒化、阴虚质易从热化、痰湿质易夹湿、湿热质易化火伤阴；素体气虚者邪易入里而不易解，素体气郁者易气滞血瘀而病程缠绵。体质与辨证：证是疾病过程中某一阶段病理状态的概括，体质则是疾病发生前后的内在背景，辨证不能脱离体质而孤立进行。体质与治疗：体质决定治则的取向与方药的取舍，也决定同一病种在不同体质者身上的加减差异，所谓「因人施治」即以辨体为前提。体质与养生：养生应「因人养生」，先辨体质之偏颇，再以食疗、起居、运动、情志调摄与导引之法进行纠偏，寓「治未病」之旨于日常。"},{"type":"quote","text":"邪之所凑，其气必虚。","source":"《黄帝内经·素问·评热病论》"},{"type":"heading","level":3,"text":"四、辨体、辨病、辨证三者结合与体质的可调性"},{"type":"paragraph","text":"辨病、辨证、辨体三者各有侧重而须相互结合。辨病是辨明疾病的病种与基本病机，如感冒、哮病、消渴、淋证，抓住疾病的本质特征与主线；辨证是辨清当前阶段邪正盛衰、脏腑气血阴阳的错杂状态，如风寒、风热、痰湿、瘀血、气虚、阴虚等，是决定治法方药的关键；辨体是辨明个体的体质类型，阐明其发病倾向、传变规律与预后顺逆。临床的正确路径是以辨病把握全貌与基本病机，以辨证确定当下的证候并立法处方，再以辨体修正方案、权衡攻补、预判转归。例如同为咳嗽，气虚质者须扶正以祛邪，阴虚质者须养阴而不腻碍，痰湿质者须健脾燥湿而不伤津。只辨证不辨体，易只见当前之邪而伤其本；只辨体不辨证，则易以体质代替病理诊断而误治。"},{"type":"paragraph","text":"体质具有可调性，这是体质学说最具实践价值的部分。体质的偏颇一旦形成，虽难以在短期内根本改变，却可通过调养与干预向平和方向移动，量的积累足以带来质的变化。调养的主要途径包括：食养宜忌——按体质选配饮食，避免加重偏颇的「所嗜」与「所忌」；起居调摄——顺应四时起居有常，避风寒湿燥；运动导引——选择与体质相宜的功法；情志调摄——针对易激、易郁、易怒者分别施以疏肝、养心、柔肝之法；药物干预——在医师辨证指导下以膏方、汤剂等长期调理；非药物干预——针灸、推拿、艾灸、拔罐等经穴调理。老年、产后、病后体质的调养尤须重视，因其偏颇程度深、恢复能力弱，更宜徐徐图功、循序渐进，切忌峻补峻攻。可见体质虽禀赋于先天，其偏颇却可由后天加以调治，此即「体病相关」而「体病可同治」之义。"},{"type":"keypoints","title":"体质学说掌握要点","items":["体质是先天禀赋与后天获得共同作用形成的形态结构、生理功能与心理状态综合特征，具有相对稳定性与动态可变性","九种基本体质为平和质、气虚质、阳虚质、阴虚质、痰湿质、湿热质、血瘀质、气郁质、特禀质，兼夹体质以「某某夹某某」表述","体质决定发病倾向与病机从化，同病异治、异病同治的理论依据即在于此","辨病、辨证、辨体三者结合：以辨病把握本质，以辨证立法处方，以辨体权衡攻补、预判转归","体质偏颇可经食养、起居、运动、情志、针灸导引与药物长期调养而向平和转化，是治未病的关键抓手"]},{"type":"callout","variant":"info","title":"使用说明","text":"本页体质判定条目依据《中医体质分类与判定》相关标准整理，仅供体质辨识与健康管理参考，不等同于疾病诊断。体质判定需结合形体特征、生理表现与心理倾向综合观察，且须排除疾病状态下的暂时性改变（如发热、疼痛、服药、劳累等可影响面色、汗出、脉象与饮食）。具体体质判定、中药处方与剂量、针灸推拿操作均应由执业医师依据四诊合参后确定。涉及孕产、哺乳、未成年人、老年人及慢性病用药者，请务必在医师指导下进行。"}]},{"id":"qixue-yangxu","title":"气虚质","subtitle":"元气不足，卫外不固","icon":"🌬","summary":"以疲乏、气短、自汗为主要特征，形体多偏瘦或虚胖、肌肉松软不实，脾肺气虚、卫外不固，宜补气健脾、益气固表。","badge":"八种偏颇体质","blocks":[{"type":"paragraph","text":"气虚质是因元气不足，以疲乏、气短、自汗等为主要特征的体质类型。形态上多见形体偏瘦，或因脾虚失运而虚胖（胖而松软、肌肉不实），骨骼不粗壮，面色偏黄或萎黄少华、缺乏光泽，毛发稀疏不华、枯黄易脱。生理方面，脾肺两脏之气不足：脾失健运则水谷精微化生不足，故食欲减退、脘腹胀软、便溏；肺气虚则呼吸气短、语声低微、动则汗出；卫气不固、腠理疏松则易感受外邪，反复感冒且病程迁延；气虚推动无力，气血运行迟缓，故可有面色晦滞、头晕目眩、心悸乏力。心理方面多见性格内向、安静沉稳、缺少活力与进取心、不喜冒险、易疲劳、注意力不易集中、情绪偏低、常有自卑或不自信感。对外适应能力方面，因卫表不固、正气不足，对寒、湿、暑邪及时行疫疠之气的抵抗力明显下降，耐受温差、饥饿、劳累的能力均较差，劳累后恢复缓慢，且同一种外感疾病常反复发作、缠绵难愈。"},{"type":"table","caption":"气虚质常见表现","head":["表现项目","典型特征"],"rows":[["总体特征","疲乏无力，气短懒言，精神不振，语音低微，动则加重"],["形态体态","形体偏瘦，或虚胖而肌肉松软不实，骨骼不粗壮"],["面色肤色","面色偏黄或萎黄少华，缺乏光泽，毛发不华"],["舌象","舌质淡，舌体胖嫩，边有齿痕，苔薄白"],["脉象","脉虚缓、虚数或细弱无力"],["情志表现","性格内向，喜静恶动，缺少活力，易疲劳，注意力涣散"],["饮食二便","食少纳呆，口淡无味，大便溏薄或矢气频转"],["汗出与适应","自汗，动则尤甚；易感外邪，耐寒暑与劳倦能力差"]]},{"type":"cards","columns":2,"items":[{"icon":"🫁","title":"呼吸系统疾病","text":"感冒、反复上呼吸道感染、咳嗽、支气管炎、哮喘缓解期","bullets":["卫气不固，外邪乘虚而入","肺气不足，宣降失司，痰饮内停","反复感冒，病程迁延不愈"]},{"icon":"🍚","title":"消化系统疾病","text":"消化不良、功能性腹胀、慢性腹泻、便秘","bullets":["脾失健运，水谷不化","中气不足，运化无力，腹胀便溏","气虚推动无力，肠道传导迟滞"]},{"icon":"💤","title":"疲劳与虚劳诸证","text":"慢性疲劳综合征、贫血、头晕心悸、失眠健忘","bullets":["气血生化乏源，清窍失养则头晕","心血不足，心神失养则心悸失眠","劳倦内伤，恢复缓慢"]},{"icon":"💦","title":"汗证与免疫低下","text":"自汗、盗汗、反复感染、术后或产后体虚","bullets":["腠理疏松，卫外失固","营卫不和，汗液外泄","正气亏虚，卫表不固易感"]}]},{"type":"table","caption":"气虚质辨证要点与舌脉","head":["观察要点","典型表现"],"rows":[["舌象","舌质淡，胖嫩，边有齿痕，苔薄白而润"],["脉象","脉虚缓，或细弱无力，关部尤弱"],["面色","面色萎黄少华，或㿠白无华"],["汗出","自汗为主，动则益甚，汗后身凉易疲"],["语声","语声低微，气短不足以息，说话无力"],["饮食口味","纳少便溏，口淡无味，不喜生冷油腻"],["病势特点","起病较缓，病程较长，反复发作，劳累后加重"]]},{"type":"paragraph","text":"气虚质的调养总则是扶正益气、健脾益肺，以培补元气为纲，兼顾脾肺两脏。脾为后天之本、气血生化之源，故健脾为先，脾健则气自充；肺主气、主皮毛、司呼吸，卫外不固者当补肺固表，益气御邪。调治须掌握三条原则：一是补而不滞，益气药多易助湿恋邪，脾虚湿盛者宜配伍行气渗湿之品，使补而可行；二是忌峻攻伐，气虚之体承受不住苦寒攻下、破气逐瘀与峻烈发汗，误用则气随津脱、变生他证；三是缓补为上，非实证不宜骤补骤攻，宜丸散膏方长期调理，缓缓图功。兼夹证应分层处理：兼阳虚者温阳益气，兼痰湿者健脾燥湿兼益气，兼血虚者气血双补，兼阴虚者益气养阴并施。药食调养以甘温、甘平之品健脾益气为要，忌苦寒伐阳、忌辛燥耗气、忌滋腻壅滞。运动宜柔缓绵长，以八段锦、太极拳、五禽戏、散步、慢跑、登山等有氧运动为主，忌大汗淋漓、忌过度气力训练。"},{"type":"table","caption":"气虚质饮食宜忌","head":["类别","食物举例","说明"],"rows":[["宜食·补气健脾","山药、莲子、薏苡仁、白扁豆、大枣、粳米、小米、南瓜","健脾益气，渗湿止泻，为日常主食之选"],["宜食·益气固表","黄芪、党参、白术、防风（可食为黄芪粥、黄芪炖鸡）","补肺固表，用于易感冒、汗多者"],["宜食·气血同补","鸡肉、瘦猪肉、牛肉、鹌鹑、桂圆、大枣茶","补益气血，兼治气血两虚之面色萎黄"],["常用食疗","山药粥、黄芪炖鸡、莲子百合粥、栗子粥、牛肉汤","每日或隔日一次，量宜适中，忌油腻厚味"],["忌食·生冷寒凉","生冷海鲜、冰饮、瓜果生冷、凉拌菜、苦寒药物久服","损伤脾阳，腹泻腹痛加重"],["忌食·峻烈耗气","过辣过燥之品、浓茶、过量咖啡、烈酒","耗气伤津，助火动血"],["忌食·油腻黏滞","肥肉、动物内脏、糯米过多、油炸食品、奶油制品","碍脾助湿，壅滞气机"]]},{"type":"table","caption":"气虚质起居·运动·情志·四季调摄","head":["调摄维度","具体方法"],"rows":[["起居","起居有常，睡眠充足，避风避寒，注意保暖，尤其护住背部、颈部与足部；午后宜小憩片刻，不宜过劳与熬夜"],["运动","选择柔缓持久项目：太极拳、八段锦、五禽戏、散步、慢跑、登山；运动量以微微汗出为度，忌大汗与憋气发力"],["情志","多参加集体活动与文娱活动以升发气机；避免思虑过度、忧愁恐惧，气虚者多易郁而无力，宜温和鼓励、循序渐进"],["四季调养","春宜舒展肝气、升发阳气，夏避暑热、不可贪凉饮冷，秋宜平补、忌过燥，冬宜温补、避寒就温，早卧晚起"],["四季调养","换季与流感流行期注意防护，勤洗手、常通风，可用玉屏风散等在医师指导下预防；节食减肥当慎，因气虚者不宜过耗"]]},{"type":"callout","variant":"warning","title":"注意事项与禁忌","text":"药物禁忌：气虚者忌用峻下之剂（如大黄、芒硝、番泻叶久服），忌破气逐瘀之品（如枳实、青皮、莪术、三棱），忌强发汗（麻黄、桂枝大剂久用），忌苦寒直折（如黄连、黄柏长期大量），忌重镇有毒之品（如朱砂、雄黄）；人参、黄芪、附子等补益温阳药须在医师辨证指导下使用，不可自行长期大剂量服用。食物禁忌：忌生冷、冰饮、肥甘厚腻与过辣过燥之物，忌饥饱无常与过度节食减重。灸法注意：气虚者多可耐受艾灸与温灸，但皮肤破损、疮疡未愈处、发热期及对艾烟过敏者不宜施灸；糖尿病、周围感觉减退者施灸须防烫伤，宜由专业人员操作并缩短时间。就医情形：出现反复或持续发热、咳嗽超过两周、气促胸闷明显、明显消瘦、体重骤降、黑便或便血、心悸不能平卧、头晕晕厥、讲话或行走无力加重等情况，应及时就医检查，不可仅以「体虚」自了。注意与结核病、肿瘤、贫血、甲状腺疾病、慢性肺病的鉴别，需完善相关检查。"},{"type":"keypoints","title":"气虚质要点","items":["核心病机：元气不足，脾肺两虚，卫外不固","四诊抓手：舌淡胖有齿痕、脉虚弱、面色少华、自汗、气短懒言","易患倾向：反复感冒与呼吸道感染、慢性腹泻、功能性消化不良、疲劳综合征、自汗","治则大法：健脾益气、补肺固表，补而不滞，忌峻攻","调养要点：忌生冷油腻，宜山药黄芪之属；避风寒、慎过劳；运动宜柔缓，忌大汗"]},{"type":"quote","text":"邪之所凑，其气必虚。","source":"《黄帝内经·素问·评热病论》"},{"type":"divider","text":"==APPEND=="}]},{"id":"yangxu","title":"阳虚质","subtitle":"阳气不足，温煦与推动无力","icon":"🔥","summary":"以畏寒怕冷、肢端不温为主要特征，形体偏胖或中等、肌肉松软，脾肾阳虚、产热不足，宜温补脾肾、扶阳抑阴。","badge":"八种偏颇体质","blocks":[{"type":"paragraph","text":"阳虚质是因阳气不足，以畏寒怕冷、肢端不温为主要特征的体质类型。形态上多见形体偏胖或中等，肌肉松软不实、骨骼偏瘦，常呈向心性肥胖，腰腹肥满而下肢偏瘦，面色㿠白或晦滞缺少光泽，眼睑或下肢轻度浮肿，目光偏钝、唇色偏淡，毛发易早白易脱落。生理方面，脾肾阳气不足：脾阳虚则运化无力，故食欲减退、脘腹冷痛、喜温喜按、大便溏薄或五更泄泻；肾阳虚则气化失司，故腰膝酸冷、尿清而长、夜尿多、畏寒肢冷；阳虚则水湿不化，痰饮、水肿常随之而来。心理方面多见性格沉静内向、喜安静少言、意志较薄弱、易感疲惫、缺少动力、遇事退缩，对外界刺激反应迟缓，易产生畏难与消极情绪。对外适应能力方面，耐寒不耐热、畏寒怕冷是突出特征，不耐暑热与辛辣温热之品，冬季易患感冒、咳喘、关节冷痛，夏季贪凉饮冷反使症状加重，且因阳虚推动无力，代谢率偏低，畏寒与怕冷症状常年存在。"},{"type":"table","caption":"阳虚质常见表现","head":["表现项目","典型特征"],"rows":[["总体特征","畏寒怕冷，手足不温，全身发冷，冬季尤甚，夏季亦感冷"],["形态体态","形体偏胖或中等，肌肉松软不实，骨骼偏瘦，腰腹肥满"],["面色肤色","面色㿠白或晦滞，唇色淡，毛发易早白易落"],["舌象","舌质淡胖，色淡，舌边有齿痕，苔白滑或白润"],["脉象","脉沉迟无力，或沉细，或尺脉沉弱"],["情志表现","性格沉静内向，喜静少言，意志较薄弱，易感疲惫，缺少动力"],["饮食二便","纳少腹胀，腹痛喜温喜按，大便溏薄或五更泄泻，小便清长夜尿多"],["汗出与适应","多不渴或喜热饮；耐寒不耐热，易受寒邪，易生痰饮水肿"]]},{"type":"cards","columns":2,"items":[{"icon":"❄️","title":"寒湿痹痛与关节疾患","text":"风湿性关节炎、腰痛、颈肩痛、膝关节冷痛","bullets":["阳虚寒盛，寒湿留着于经络","气血运行不畅，不通则痛","遇寒加重，得温则减"]},{"icon":"🌬","title":"寒饮咳喘","text":"哮喘、慢支咳嗽、反复感冒、过敏性鼻炎","bullets":["阳不化气，津液不布，聚而为痰","寒痰清稀，咳喘遇寒即发","卫阳不固，反复感邪"]},{"icon":"💧","title":"脾肾阳虚诸证","text":"慢性腹泻、五更泻、消化不良、水肿、畏寒肢冷","bullets":["脾失温运，纳呆便溏","肾阳不足，气化失司","水液停聚而为痰饮水肿"]},{"icon":"🌙","title":"胞宫与生殖诸疾","text":"宫寒不孕、月经后期、痛经、阳痿早泄","bullets":["阳虚胞宫失于温煦","寒凝血瘀，冲任不利","下元虚寒，元阳不足"]}]},{"type":"table","caption":"阳虚质辨证要点与舌脉","head":["观察要点","典型表现"],"rows":[["舌象","舌质淡胖、淡暗，舌边齿痕明显，苔白滑或白润而厚"],["脉象","脉沉迟无力，或沉细弱，关尺尤弱，尺脉沉微"],["面色","面色㿠白或晦滞无华，眼睑浮肿，唇色偏淡"],["寒热","畏寒肢冷，关节冷痛，得温则舒、遇寒加重，不渴或喜热饮"],["语声","语声低微，气短乏力，咳嗽声低，痰多清稀色白"],["二便","大便溏薄或五更泄泻，小便清长，夜尿频数"],["病势特点","病程缠绵，起病较缓，反复发作，得温则减、得寒则剧"]]},{"type":"paragraph","text":"阳虚质的调养总则是温补脾肾、扶阳抑阴，以温阳散寒为纲，兼顾脾肾两脏，脾阳得运则水谷化生有源，肾阳得充则气化有司。施治须把握三条要点：一是温而不燥，补阳多以温润平和之品为主，忌峻用附子、肉桂等大辛大热，恐助火伤阴、迫血妄行；二是补而不滞，阳虚者常兼水湿痰饮，滋补过度易碍脾助湿，故温补之中宜配伍利水渗湿与行气之品；三是重视脾肾同治，命门火衰者当以温肾为主，脾虚为主者当以健脾为先。中病即止，不可久服峻补。兼夹方面，兼气虚者益气温阳并用，兼痰湿者温阳兼燥湿化痰，兼血瘀者温通兼活血化瘀，兼寒湿痹痛者温经散寒兼通络。药食调养宜温热忌寒凉，宜血肉有情之品配伍温性草木，忌食生冷瓜果、冰饮苦寒、肥甘厚腻。运动宜温通不宜大汗，以八段锦、太极拳、五禽戏、慢跑、散步、登山、晒太阳为佳，忌大汗淋漓、忌久泳受寒、忌夜间户外锻炼受凉。"},{"type":"table","caption":"阳虚质饮食宜忌","head":["类别","食物举例","说明"],"rows":[["宜食·温阳补肾","羊肉、牛肉、鸡肉、鹿肉、核桃、栗子、枸杞、杜仲、肉桂","温补脾肾，暖腰膝，强筋骨"],["宜食·温中散寒","生姜、干姜、红枣、龙眼肉、韭菜、茴香、葱白","温中焦、散寒凝，冬季尤宜"],["宜食·化痰利水","生姜、陈皮、茯苓、山药、白术、薏苡仁、生姜汁","温化痰饮，健脾渗湿"],["常用食疗","当归生姜羊肉汤、生姜红枣茶、桂圆红枣枸杞饮、核桃黑芝麻粥、羊肉萝卜汤","秋冬进补，量宜适度，感冒发热期间停服"],["忌食·生冷寒凉","生冷海鲜、冰镇饮料、刺身、螃蟹、梨生冷、西瓜、火龙果、冰淇淋","损伤脾阳，加重畏寒、便溏与痛经"],["忌食·苦寒攻伐","苦寒药物久服、浓绿茶、过量苦瓜、绿茶空腹饮、啤酒冷饮","苦寒伐阳，遏阳气生化之机"],["忌食·生冷不洁","隔夜生冷菜、路边生食冰镇瓜果、大量生食","胃肠虚寒者易致腹泻与食积"]]},{"type":"table","caption":"阳虚质起居·运动·情志·四季调摄","head":["调摄维度","具体方法"],"rows":[["起居","注意保暖，尤其护住腰腹、下肢与足部；睡前温水泡脚；宜早睡早起、昼长夜短；避免久居阴冷潮湿之处，忌夜间户外受寒"],["运动","宜温通有氧：太极拳、八段锦、五禽戏、慢跑、登山、晒背；运动以微微汗出为度，忌大汗淋漓，忌长时间游泳与冷水浴"],["情志","宜多与人交往、参与文娱活动振奋心神；避免思虑过度与长期独处；保持乐观，勿因畏寒乏力而自弃，阳虚者多易郁而气滞"],["四季调养","春宜温阳健脾、舒展肝气；夏勿贪凉饮冷、忌空调直吹；长夏宜健脾化湿；秋宜温润平补、早卧早起；冬宜藏精养阳、避寒就温"],["其他调养","可用艾灸、隔姜灸、督脉灸、膀胱经捏脊等温阳手法；睡眠、饮食、房事均宜有节，忌过度耗损"]]},{"type":"callout","variant":"warning","title":"注意事项与禁忌","text":"药物禁忌：阳虚质忌用大苦大寒之品，如石膏、知母、大黄、芒硝、番泻叶、黄连、黄柏、龙胆草等久服，以免损伤脾肾阳气；附子、肉桂、吴茱萸、细辛等大热有毒或走窜之品必须由医师辨证定量使用，不可自行服用；忌用峻烈发汗与攻下之法，以防亡阳；滋腻助湿之品如熟地黄滋腻碍脾，脾虚痰湿者当慎用。食物禁忌：忌一切生冷寒凉、冰饮冷酒，忌蟹、梨、柿、葡萄等偏寒之品大量食用，忌苦寒药物与苦寒凉茶长期饮用。就医情形：出现明显水肿、晨起眼睑浮肿、腹痛剧烈呕吐、久泻不止、五更泻加重、畏寒极甚伴意识迟钝、突发胸痛心悸、肢体麻木疼痛、或出现阳萎不育、月经长期闭经等情况，应立即就医，明确病因并排查甲减、贫血、垂体病变等器质性疾病。特殊人群：孕妇、哺乳期妇女、年老体弱者使用温补药须格外谨慎；皮肤感觉减退者洗浴水温不宜过高，防烫伤；阳虚质者不宜盲目加大运动量与减重速度。"},{"type":"keypoints","title":"阳虚质要点","items":["核心病机：脾肾阳虚，温煦与推动无力，水湿不化","四诊抓手：舌淡胖有齿痕、苔白滑、脉沉迟无力、畏寒肢冷、喜热饮","易患倾向：寒湿痹痛、寒饮咳喘、五更泻、水肿、宫寒不孕","治则大法：温补脾肾、扶阳抑阴，温而不燥、补而不滞","调养要点：忌生冷寒凉，宜温热之属；注意保暖、晒太阳；运动宜温通，忌大汗与受寒"]},{"type":"quote","text":"阳气者，若天与日，失其所则折寿而不彰。","source":"《黄帝内经·素问·生气通天论》"}]},{"id":"yinxu","title":"阴虚质","subtitle":"阴液亏少，虚热内生","icon":"🌙","summary":"以手足心热、口燥咽干、潮热盗汗为主要特征，形体偏瘦、皮肤偏干，脏腑失养而虚热内生，宜滋阴清热、壮水制火。","badge":"八种偏颇体质","blocks":[{"type":"paragraph","text":"阴虚质是因阴液亏少，以手足心热、口燥咽干、潮热盗汗等为主要特征的体质类型。形态上多见形体偏瘦，骨骼显露，肌肉消瘦而缺乏弹性，面色偏红或颧红，五官轮廓分明、口唇偏干微红，皮肤偏干、易生细纹、毛发枯槁易脆、易脱发。生理方面，津血不足、脏腑失养：肺阴不足则干咳少痰、咽干咽痛；胃阴不足则饥不欲食、口干欲饮而胃脘灼热、大便干结；肾阴不足则腰膝酸软、遗精、潮热盗汗、五心烦热；肝阴不足则目干涩、视物昏花、筋惕肉跳。虚热内生，故手足心热、午后及夜间潮热明显，颧红唇赤，睡眠不安而多梦易醒。心理方面多见外向好动、急躁易怒、思维敏捷、能言善辩、情绪起伏较大，睡眠需求较少而难眠。对外适应能力方面，耐冬不耐夏，最不耐暑热与燥邪，夏季易出现心烦、口干、汗出过多与耗伤，秋季燥邪当令时症状加重，需津液濡润方能安适。"},{"type":"table","caption":"阴虚质常见表现","head":["表现项目","典型特征"],"rows":[["总体特征","手足心热，口燥咽干，午后潮热，夜间盗汗，口干而欲饮水"],["形态体态","形体偏瘦，肌肉消瘦，骨骼显露，皮下脂肪少，体表偏热"],["面色肤色","面色偏红或颧红，唇红微干，皮肤偏干易生纹"],["舌象","舌质红而少津，舌体偏瘦，舌面少苔或无苔，或见裂纹"],["脉象","脉细数，或细而弦数"],["情志表现","外向好动，急躁易怒，思维敏捷，多言多动，情绪起伏明显"],["饮食二便","喜食凉润之物，口干喜饮，胃脘灼热，大便干结，小便短少色黄"],["睡眠与适应","失眠多梦，易醒；耐冬不耐夏，不耐暑热与燥邪，秋季症状加重"]]},{"type":"cards","columns":2,"items":[{"icon":"🌡","title":"阴虚内热与更年期诸证","text":"更年期综合征、烘热汗出、盗汗、虚劳","bullets":["阴液耗损，虚火内扰","肾阴不足，天癸渐亏","潮热自汗，心烦不宁"]},{"icon":"🗣","title":"肺胃阴伤诸证","text":"慢性咽炎、干燥综合征、久咳干咳、胃阴不足","bullets":["肺失濡润，燥邪犯肺","咽干咽痛，咳而无痰","胃阴不足，饥不欲食"]},{"icon":"💩","title":"肠燥津亏","text":"习惯性便秘、老年便秘、痔疮出血","bullets":["津血亏少，肠道失润","传导无力，大便干结难下","努挣伤络，易致出血"]},{"icon":"🍯","title":"消渴与虚火上炎","text":"糖尿病、口腔溃疡、牙龈肿痛、目赤肿痛","bullets":["阴虚燥热，津液亏耗","虚火上炎，口舌生疮","肝肾阴亏，目干昏花"]}]},{"type":"table","caption":"阴虚质辨证要点与舌脉","head":["观察要点","典型表现"],"rows":[["舌象","舌质红而少津，偏瘦，舌面少苔或无苔，干燥或有裂纹，少津"],["脉象","脉细数，或细而弦数，尺脉尤细"],["面色","面色偏红或颧红，面部烘热，唇红干"],["寒热","手足心热，午后及夜间潮热，骨蒸感，五心烦热，盗汗"],["津液","口干咽燥，咽干痛，胃脘灼热，喜饮水而量不多，鼻干唇燥"],["二便","大便干结如羊屎，小便短少色黄"],["病势特点","起病较缓，病程较长，反复迁延；秋燥与夏热时症状明显加重"]]},{"type":"paragraph","text":"阴虚质的调养总则是滋养阴液、养阴清热、壮水制火，以甘寒滋润、酸甘化阴为基本思路，重在养阴而不恋邪、滋而不腻滞。施治须把握四条要点：一是辨明阴虚所在之处，肺阴虚重在润肺，胃阴虚重在养胃，肾阴虚重在滋肾填精，肝阴虚重在柔肝潜阳；二是养阴必先健脾，滋腻之品最易碍胃，若脾运不健者当佐以砂仁、陈皮、茯苓等醒脾运中之品，使滋而不腻；三是清热当以甘寒养阴为主，不可苦寒直折，苦寒易化燥伤阴，致虚火更炽；四是忌用汗、下、燥烈之攻伐之法，重阴之体最忌津液再伤。兼夹方面，兼气虚者气阴双补，兼阳虚者阴阳双调而温阳不燥，兼血虚者滋阴养血，兼痰湿者滋阴兼化痰而不伤阴。药食调养宜甘凉滋润，忌辛辣煎炸燥烈，忌温补助火。运动宜柔缓舒缓，以太极、瑜伽、游泳、散步、书法静坐为佳，忌大汗耗津、忌高温桑拿汗蒸、忌长时间烈日暴晒。"},{"type":"table","caption":"阴虚质饮食宜忌","head":["类别","食物举例","说明"],"rows":[["宜食·甘凉滋润","银耳、百合、梨、蜂蜜、桑葚、黑芝麻、核桃、莲子、荸荠","滋阴润燥，缓补不腻"],["宜食·养阴生津","枸杞、麦冬、沙参、玉竹、石斛、鸭肉、甲鱼、桑椹","养阴清热，生津止渴"],["宜食·清热","绿豆、苦瓜（熟食）、冬瓜、丝瓜、芹菜、马蹄","清解内热，须配伍养阴之品"],["常用食疗","银耳百合羹、百合莲子粥、桑葚膏、五汁饮（梨汁藕汁甘蔗汁）、麦冬粥","每日或隔日一次；脾虚便溏者减量"],["忌食·辛辣燥烈","辣椒、花椒、麻辣烫、烧烤、煎炸、羊肉、狗肉、韭菜、蒜苗、烈酒","耗伤阴液、助火动血"],["忌食·温补助火","鹿茸、淫羊藿、巴戟天、附子、人参大剂量久服、当归生姜羊肉汤","温燥太过，反增内热"],["忌食·香燥煎炸","炒货、膨化食品、油炸糕点、浓茶、浓咖啡","香燥伤津，烘助虚火"]]},{"type":"table","caption":"阴虚质起居·运动·情志·四季调摄","head":["调摄维度","具体方法"],"rows":[["起居","子时养阴，宜早睡早起、保证充足睡眠；忌熬夜，熬夜最伤阴液；适当午休；居室宜湿润，忌燥热；房事有节，忌过度消耗"],["运动","宜柔缓静态：太极拳、瑜伽、慢走、游泳、八段锦；运动以微热不出汗为度，忌大汗淋漓、忌高温桑拿汗蒸、忌暴晒运动"],["情志","养心为要，宜静心宁神、读书、书法、冥想；节制急躁愤怒，防相火妄动；阴虚者心烦易怒，宜以动养与静养结合，规律作息最为重要"],["四季调养","春宜养肝疏泄、少怒；夏避暑热、忌汗过多；长夏健脾以助生津；秋宜润燥、滋阴为重；冬宜藏精、早卧晚起、忌过早进补"],["其他调养","可在医师指导下选用六味地黄丸、杞菊地黄丸等滋阴类中成药；可用涌泉、太冲、三阴交等穴位的按揉与艾灸以引火归元、滋阴降火"]]},{"type":"callout","variant":"warning","title":"注意事项与禁忌","text":"药物禁忌：阴虚质忌用温燥壮阳之品，如附子、肉桂、鹿茸、淫羊藿、巴戟天、鹿鞭、菟丝子等长期大量使用；忌用大剂滋腻碍胃之品，如熟地黄、阿胶、龟甲胶长期单独服用而无健脾配伍，恐致脘腹胀满便溏；忌用峻烈发汗药（麻黄、桂枝大剂）与苦寒泻下药长期使用，恐重灼津液；苦寒药亦须中病即止，不可久服。食物禁忌：忌辛辣、煎炸、烧烤、燥烈之品，忌烈酒与浓茶浓咖啡，忌温补汤锅与药膳久服。就医情形：出现持续低热不退、夜间盗汗、五心烦热明显、体重骤降或消瘦、反复口腔溃疡、长期咳嗽干咳或咯血、吞咽困难、颈部肿块、异常阴道出血、视力急剧下降等情况，应尽快就医，排查感染性疾病、结核、甲状腺疾病、血液系统疾病与自身免疫病等。特殊人群：孕妇、哺乳期妇女使用滋阴药须谨慎；儿童与青少年不宜擅自服用滋补类中成药；正在服用抗凝药、降糖药者，服用滋阴类中成药前须告知医师；糖尿病患者食疗须计入每日能量。"},{"type":"keypoints","title":"阴虚质要点","items":["核心病机：阴液亏少，脏腑失养，虚热内生","四诊抓手：舌红少苔少津、脉细数、颧红、手足心热、盗汗、大便干","易患倾向：更年期综合征、慢性咽炎、干燥综合征、便秘、消渴、口疮","治则大法：滋养阴液、养阴清热、壮水制火，滋而不腻","调养要点：忌辛辣燥烈与熬夜，宜甘凉滋润；运动宜静缓，忌大汗与桑拿；秋冬注意润燥"]},{"type":"quote","text":"阴者，藏精而起亟也；阳者，卫外而为固也。","source":"《黄帝内经·素问·生气通天论》"}]},{"id":"tanshi","title":"痰湿质","subtitle":"痰湿凝聚，脾失健运","icon":"💧","summary":"以体形肥胖、腹部肥满、口黏苔腻为主要特征，脾失健运、湿聚痰生，宜健脾燥湿、化痰利水。","badge":"八种偏颇体质","blocks":[{"type":"paragraph","text":"痰湿质是因体内水湿停聚、痰浊内生，以体形肥胖、腹部肥满、口黏苔腻为主要特征的体质类型。形态上多见体形肥胖，腹部肥满松软，按之柔软无痛，皮下脂肪丰厚，肌肉松软，形体臃肿；面色多见㿠白或萎黄，或面部晦暗夹有油腻感，眼胞微浮；毛发易脱落，出汗多而黏滞不爽。生理方面，脾失健运是根本：脾为生痰之源，脾虚则水湿不化，津液输布失常，聚湿成痰，故见食欲不振、脘腹胀满、口黏不渴或渴不多饮、胸闷、恶心、痰多、大便黏滞不爽或溏泄；湿性趋下，故下部腰以下沉重酸楚，肢体困重。心理方面多见性格温和敦厚、宽厚仁善、好交往、能忍耐、反应迟钝、多善思考而不善言辞、情绪稳定而缺乏主动性。对外适应能力方面，因内湿既困脾胃又易招外湿，对梅雨季节及潮湿环境适应能力差，表现为头重如裹、身体困重、关节酸重；耐受寒湿的能力较强故不易出现剧烈疼痛，但易患痰饮、肥胖、水肿等代谢相关疾病，且病程缠绵、反复难愈。"},{"type":"table","caption":"痰湿质常见表现","head":["表现项目","典型特征"],"rows":[["总体特征","体形肥胖，腹部肥满松软，痰多，口黏，胸闷，脘腹胀满"],["形态体态","形体臃肿，腹部肥满按之柔软，肌肉松软，脂肪丰厚"],["面色肤色","面部㿠白或萎黄而垢浊油腻，或晦暗无华"],["舌象","舌体胖大，舌质淡或淡胖，苔白腻或白滑"],["脉象","脉滑，或濡滑、缓滑"],["情志表现","性格温和敦厚，宽厚仁善，好交往，反应迟钝，多善思考，情绪稳定"],["饮食二便","不渴或渴不多饮，纳呆不化，口黏，胸闷恶心，大便黏滞不爽或溏泄"],["头部与肢体","头重如裹，肢体困重，关节酸重，腰以下沉重，女性可带下量多"]]},{"type":"cards","columns":2,"items":[{"icon":"🫁","title":"痰饮咳喘","text":"支气管炎、哮喘、慢阻肺、反复咳嗽痰多","bullets":["脾虚生痰，痰湿阻肺","肺失宣降，咳嗽痰多色白","痰随气升，喘息胸闷"]},{"icon":"⚖️","title":"代谢与内分泌病","text":"单纯性肥胖、高脂血症、2型糖尿病、脂肪肝","bullets":["湿浊内聚，形体日丰","脾失健运，糖脂代谢失常","肝失疏泄，痰湿蕴结肝体"]},{"icon":"💧","title":"水肿与泌尿系病","text":"特发性水肿、肾病综合征、泌尿系感染","bullets":["气化不利，水湿停聚","湿热下注，膀胱气化不利","水湿泛溢肌肤而浮肿"]},{"icon":"🩺","title":"消化与妇科杂病","text":"功能性消化不良、便秘、眩晕、带下病、肥胖相关不孕","bullets":["痰湿中阻，纳运失司","痰浊上蒙清窍而眩晕","湿浊下注，带下量多"]}]},{"type":"table","caption":"痰湿质辨证要点与舌脉","head":["观察要点","典型表现"],"rows":[["舌象","舌体胖大，舌质淡胖或有齿痕，苔白腻、白滑或厚腻"],["脉象","脉滑，或濡滑、缓滑，尺部偏沉"],["面色","面部㿠白或萎黄而垢浊，眼胞微浮，色晦不华"],["痰涎","痰多色白质黏或稀，咯之不爽，胸闷脘痞，恶心"],["饮食口味","口黏不渴或渴不多饮，纳呆不化，脘腹胀满"],["二便","大便黏滞不爽或溏泄，小便色黄或混浊"],["病势特点","起病缓慢，病程缠绵，症状随饮食与气候波动，梅雨季节加重"]]},{"type":"paragraph","text":"痰湿质的调养总则是健脾燥湿、化痰利水，以杜绝生痰之源为根本，兼顾运脾与化浊。脾为生痰之源、肺为贮痰之器，故健脾化痰当为第一要义，同时宣降肺气以化贮痰之器。施治须把握三条要点：一是标本兼治，健脾燥湿治本，化痰利水治标，不可单纯利水而伤津、不可单纯滋补而助湿；二是因势利导，湿性黏滞，遇寒则凝、遇热则蒸，故用药宜温运而不宜过寒，宜淡渗而不宜峻利；三是顾护脾胃，痰湿质者脾胃本虚，化痰之品多辛燥行气，过用则更伤中气，须配伍陈皮、砂仁、白术、茯苓之类健脾行气之品以助运化。兼夹方面，兼气虚者益气化痰，兼阳虚者温阳化饮，兼湿热者清热化湿，兼血瘀者化痰兼活血，气郁明显者理气解郁化痰。药食调养宜清淡渗利之品，忌肥甘厚味、甜腻黏滑与暴饮暴食。运动是痰湿质最有效的干预手段，宜大运动量、有氧、持久以耗化痰湿，忌久坐少动，忌以节食为主要手段的快速减重。"},{"type":"table","caption":"痰湿质饮食宜忌","head":["类别","食物举例","说明"],"rows":[["宜食·健脾渗湿","薏苡仁、山药、白扁豆、茯苓、白术、芡实、莲子、玉米、冬瓜","健脾利湿，杜绝生痰之源"],["宜食·化痰理气","陈皮、萝卜、白萝卜、荸荠、海藻、昆布、紫苏、砂仁","理气化痰，消食导滞"],["宜食·清淡养胃","粳米、小米、绿豆、芹菜、菠菜、冬瓜、丝瓜、瘦肉、鱼类","低脂高纤，减轻脾胃负担"],["常用食疗","薏苡仁赤小豆粥、山药陈皮粥、冬瓜薏仁汤、白扁豆粥、荷叶陈皮茶","每日或隔日一次；久服注意健脾与补益配伍"],["忌食·肥甘厚味","肥肉、猪油、动物内脏、奶油、黄油、蛋糕、巧克力、甜饮料","助湿生痰，加重肥胖与胸闷"],["忌食·黏腻难化","糯米、油炸食品、黏米年糕、浓汤、肥肉羹、阿胶膏方久服","碍脾运化，湿浊更难去"],["忌食·寒凉伤脾","冰饮、生冷刺身、大量苦寒药物、极低热量减肥餐","脾阳受损，湿聚更甚"]]},{"type":"table","caption":"痰湿质起居·运动·情志·四季调摄","head":["调摄维度","具体方法"],"rows":[["起居","起居有常，忌久坐久卧；居室宜干燥通风，忌潮湿；睡前不饱食、不饮酒；多饮温水，忌冰饮；衣著宽松，忌紧束腰腹"],["运动","宜大运动量有氧以化痰湿：慢跑、快走、游泳、爬山、跳绳、骑车、球类；每周累计中等强度运动三十分钟以上，出汗后及时更衣"],["情志","宜多参加运动与集体活动以行气化湿；避免久坐寡动与情绪郁结；气郁易助痰湿生成，须保持心情舒畅、意志积极"],["四季调养","春宜疏肝理气以助脾运；夏宜祛暑化湿、忌贪凉饮冷；长夏为祛湿黄金期，宜健脾化湿；秋宜润燥兼化痰；冬忌进补滋腻，宜温运脾阳"],["其他调养","可用中脘、丰隆、足三里、阴陵泉等穴位的按揉、艾灸与拔罐；可配合化痰祛湿的中成药长期调理，须遵医嘱"]]},{"type":"callout","variant":"warning","title":"注意事项与禁忌","text":"药物禁忌：痰湿质忌滋腻补益之品长期独用，如阿胶、鹿角胶、熟地黄、龟甲膏等，以免助湿壅滞；忌用峻烈泻下之剂（如番泻叶、大黄、芒硝长期服用）以免伤脾致虚；半夏、南星、白附子等化痰燥湿药性偏燥烈，兼阴虚血燥者慎用；利尿剂与抗生素亦不宜长期滥用。食物禁忌：忌肥甘厚味、甜腻、黏滑、油炸与暴饮暴食，忌夜宵与不定时加餐，忌酗酒，忌冰镇饮料；梅雨季与潮湿季节尤须注意饮食清淡。就医情形：出现体重在短期内明显上升或下降、严重腹胀、腹水、下肢凹陷性水肿、咳嗽痰多气促不能平卧、反复肺部感染、尿常规异常、明显嗜睡或意识改变等情况，应及时就医，排查心、肝、肾、胰等脏器疾病与内分泌代谢异常。特殊人群：孕妇不宜过多使用利水化痰之品以免伤胎；严重肥胖者合并高血压、糖尿病、冠心病的，须在专科医师指导下进行减重方案；合并阻塞性睡眠呼吸暂停者应及时就诊。"},{"type":"keypoints","title":"痰湿质要点","items":["核心病机：脾失健运，湿聚为痰，痰湿互结，阻滞气机","四诊抓手：形体肥胖腹满、舌胖大苔白腻、脉滑、口黏不渴、头重身困","易患倾向：痰饮咳喘、单纯性肥胖、脂肪肝、糖尿病、眩晕、带下病","治则大法：健脾燥湿、化痰利水，标本兼顾，顾护脾胃","调养要点：忌肥甘甜腻与久坐，宜有氧大运动量；长夏与梅雨季加强祛湿"]},{"type":"quote","text":"脾为生痰之源，肺为贮痰之器。","source":"《医宗必读·痰饮》"}]},{"id":"shire","title":"湿热质","subtitle":"湿热内蕴，郁而化火","icon":"🔥","summary":"以面垢油光、口苦口黏、大便黏滞不爽为主要特征，湿热蕴结于内外，宜清热利湿、分消湿热。","badge":"八种偏颇体质","blocks":[{"type":"paragraph","text":"湿热质是因湿热内蕴，以面垢油光、口苦口黏、大便黏滞不爽为主要特征的体质类型。形态上多见形体中等或偏瘦，肌肉结实或有轻微臃肿之象；面色垢滞泛黄或油光满面，易生痤疮、酒糟鼻，眼胞微浮，口唇红润而少津；毛发易生屑、出油多。生理方面，湿热熏蒸：热在肌表则易生疮疡、湿疹、疖肿；湿热上蒸则头重昏蒙、口苦口黏、口气重、恶心纳呆；湿热下注则小便短赤涩痛、大便黏滞不爽或下痢脓血、妇女带下黄臭量多；湿热郁于肌肤则皮肤油腻、易生疖疮与斑疹。心理方面多见性格急躁易怒、急于求成、易冲动，遇事不耐煩；或表现为心胸狭隘、多疑多虑，且湿热熏蒸最易扰动心神，故失眠多梦、心烦易怒。适应能力方面，对暑湿、湿热气候及湿重环境适应能力差，梅雨或盛夏时症状明显加重；耐受热邪而不耐寒湿，遇寒则湿郁而化热，湿热更易蕴结；饮食方面嗜食辛辣油腻厚味与酒类，越食越热，因「膏粱厚味」易化湿生热。"},{"type":"table","caption":"湿热质常见表现","head":["表现项目","典型特征"],"rows":[["总体特征","面垢油光，口苦口黏，口臭，纳呆，身重困倦，大便黏滞不爽"],["形态体态","形体中等或偏瘦，肌肉结实，或有轻微壅肿之象"],["面色肤色","面部垢黄油光，易生痤疮、酒糟鼻、毛孔粗大"],["舌象","舌质偏红，舌苔黄腻或黄厚，苔质黏腻"],["脉象","脉滑数，或濡数"],["情志表现","性格急躁易怒，容易冲动，心烦，失眠多梦，多疑多虑"],["饮食口味","口苦口黏，喜食辛辣肥甘与酒类，纳呆，恶心，身热不扬"],["二便与分泌物","小便短赤涩痛，大便黏滞不爽或下痢，带下黄臭量多"]]},{"type":"cards","columns":2,"items":[{"icon":"🧴","title":"皮肤病与疔疮","text":"痤疮、湿疹、疖肿、丹毒、脂溢性皮炎","bullets":["湿热蕴肤，腠理闭塞","热毒郁蒸，发为疮疡","气血壅滞而成痈肿"]},{"icon":"🍺","title":"肝胆湿热","text":"急慢性肝炎、胆囊炎、胰腺炎、口苦胁痛","bullets":["湿热熏蒸肝胆，疏泄失常","胆汁外溢面目发黄","中焦湿热，纳呆恶心"]},{"icon":"🔥","title":"泌尿系与肠道湿热","text":"尿路感染、急性痢疾、盆腔炎、痛风","bullets":["湿热下注，膀胱气化不利","湿热蕴结大肠，传导失常","湿热壅滞下焦，气血不运"]},{"icon":"🍚","title":"热证相关内伤杂病","text":"口疮、牙龈肿痛、失眠、汗臭、便秘","bullets":["火热上炎，熏蒸口舌","湿热扰心，神不安宁","热结肠道，腑气不通"]}]},{"type":"table","caption":"湿热质辨证要点与舌脉","head":["观察要点","典型表现"],"rows":[["舌象","舌质偏红，苔黄腻或黄厚而黏腻，舌面湿黏"],["脉象","脉滑数，或濡数，尺部偏数"],["面色","面部垢黄油光，易生疮疹，唇红"],["寒热","身热不扬，午后热甚，或有低热，汗出不畅"],["口苦与气味","口苦口黏、口臭，口气重，纳呆恶心，喜饮而量不多"],["二便","小便短赤涩痛，大便黏滞不爽、臭秽或下痢，带下黄臭量多"],["病势特点","起病较急，缠绵反复，湿热交蒸则病程延长，急性期湿热偏盛、缓解期脾虚湿困"]]},{"type":"paragraph","text":"湿热质的调养总则是清热利湿、分消湿热，以清利下焦与清化中焦为基本路径。湿与热相合最难速化，故施治须把握四条要点：一是清热而不苦寒伤胃，苦寒直折易化燥生热而湿留不去，宜用甘淡渗利与清化之品，使湿去热孤；二是利湿而不伤阴，渗利太过则津液受损而虚热内生，须顾护阴液；三是分消上下，湿热弥漫三焦者当上清肺气、中化脾湿、下利小便，使湿邪有出路；四是重视脾运，湿热之体多兼脾虚，湿去之后须健脾固护，否则极易复生。兼夹方面，兼气虚者益气清热化湿，兼阴虚者养阴清热利湿，兼血瘀者清热兼活血化瘀，兼气郁者疏肝清热。药食调养宜清淡，忌辛辣煎炸、肥甘酒类与浓茶。运动宜大强度有氧以出汗排湿，但须避免汗出过度而伤津，忌大汗淋漓与桑拿，忌熬夜与情志郁结化火。"},{"type":"table","caption":"湿热质饮食宜忌","head":["类别","食物举例","说明"],"rows":[["宜食·清热利湿","绿豆、薏苡仁、赤小豆、冬瓜、丝瓜、芹菜、荸荠、马齿苋、苦瓜","清热解毒、淡渗利湿，为日常主选"],["宜食·凉润养阴","绿豆汤、荷叶、菊花、金银花、鲜西瓜（少量）、甘蔗","清解暑热，防利湿伤阴"],["宜食·健运护脾","山药、白扁豆、莲子、薏苡仁、陈皮、茯苓、大米","湿热渐清后健脾以防复发"],["常用食疗","绿豆百合汤、薏仁赤小豆粥、荷叶决明茶、丝瓜络饮、土茯苓汤","每日或隔日；脾胃虚寒者不宜多服"],["忌食·辛辣炙烤","辣椒、花椒、麻辣烫、火锅、烧烤、烈酒、白酒","助热生火，灼伤津液"],["忌食·肥甘厚味","肥肉、动物内脏、油炸、奶油制品、浓汤、火锅汤底","酿生湿浊，助火生痰"],["忌食·甜腻与酒","糖果、蛋糕、含糖饮料、啤酒、米酒","湿热内蕴之人的主要助长之品"]]},{"type":"table","caption":"湿热质起居·运动·情志·四季调摄","head":["调摄维度","具体方法"],"rows":[["起居","居室宜通风干燥，忌潮湿；衣物被褥常晒常洗；保持皮肤与会阴清洁干爽；忌久坐不动；睡眠充足，忌熬夜熬夜生火；忌穿紧身不透气衣物"],["运动","宜大强度有氧以出汗祛湿：跑步、球类、游泳、爬山、跳绳；运动后及时沐浴更衣，忌汗后即吹冷风、忌汗蒸桑拿过度"],["情志","宜心情舒畅、情绪稳定，避免急躁焦虑与生气；肝郁化火与湿热相搏，故平肝潜阳、清利肝胆湿热有助调理；规律作息为要"],["四季调养","春宜清肝利湿、防肝火上炎；夏为湿热最盛之季，宜避暑热、忌贪凉饮冷、宜清淡；长夏宜化湿健脾；秋宜清润兼清肺；冬忌温补燥热"],["其他调养","可用曲池、阴陵泉、内庭、丰隆、委中等穴位的按揉与刺络拔罐；可在医师指导下选用甘露消毒丹、茵陈蒿汤等方加减内服"]]},{"type":"callout","variant":"warning","title":"注意事项与禁忌","text":"药物禁忌：湿热质忌用温燥药与滋补品，如附子、肉桂、鹿茸、淫羊藿、红参、黄芪、人参久服、当归生姜羊肉汤等，恐助热恋邪；苦寒药如黄连、黄柏、栀子、大黄、芒硝不可久服或过量，以免损伤脾胃阳气而湿邪更困；清热解毒药如金银花、连翘、板蓝根等亦不宜长期代茶饮；抗生素不可自行服用，须由医师依病原与药敏结果选用。食物禁忌：忌酒类（含药酒、醪糟）、辛辣、油炸、烧烤、甜腻与高糖饮料；忌大量进食海鲜发物与浓汤。就医情形：出现高热不退、皮肤红肿热痛迅速扩散、脓疱成簇、口腔与咽喉肿痛影响进食、右上腹疼痛伴发热呕吐、腰痛伴尿血尿痛、便血腹泻严重、外阴瘙痒分泌物大量增多等情况，应及时就医；黄疸、尿黄加深、腹水、肝功能异常者须尽快排查肝胆系统疾病。特殊人群：孕妇、哺乳期妇女与儿童使用清热利湿药须严格遵医嘱；脾胃虚寒者不可盲目照搬湿热调理方案。"},{"type":"keypoints","title":"湿热质要点","items":["核心病机：湿热内蕴，熏蒸内外，气机升降失常","四诊抓手：舌红苔黄腻、脉滑数、面垢油光、口苦口黏、大便黏滞不爽、小便短赤","易患倾向：痤疮湿疹、疖肿、肝胆湿热、泌尿系感染、痢疾、口疮、痛风","治则大法：清热利湿、分消三焦，清热不苦寒、利湿不伤阴","调养要点：忌辛辣酒类与肥甘；宜清淡多纤维；宜大强度有运动汗出；情志宜平和忌怒"]},{"type":"quote","text":"湿胜则濡泻，甚则水闭胕肿；热胜则疮疡。","source":"《素问·至真要大论》"}]},{"id":"xueyu","title":"血瘀质","subtitle":"血行不畅，瘀阻脉络","icon":"🩸","summary":"以肤色晦暗、舌有瘀斑、痛处固定为主要特征，气滞血瘀而经络不畅，宜活血化瘀、疏经通络。","badge":"八种偏颇体质","blocks":[{"type":"paragraph","text":"血瘀质是因血行不畅、气滞血瘀而不能通畅，以肤色晦暗、舌有瘀斑、痛处固定为主要特征的体质类型。形态上多见形体偏瘦或消瘦，肌肉不丰，肤色晦暗无华、粗糙缺乏光泽，面颊与眼周色素沉着明显，或有斑痣、肌肤甲错、皮肤干燥脱屑；面色晦暗或黧黑，或面色青紫；口唇色暗、唇甲紫暗；头发易脱落，爪甲脆薄、变形。生理方面，血行不畅是核心：血行迟滞则肌肤失养而色暗粗糙，血行瘀滞则不通则痛，且痛有定处、刺痛、拒按、夜间加重；瘀血阻滞冲任则妇女月经不调、经色紫暗夹血块、痛经、经前乳胀；瘀阻心脉则胸闷胸痛、心悸，瘀阻脉络则肢体麻木、半身不遂；瘀血内阻则面色晦暗、口唇紫暗、肌肤甲错、舌质紫暗或有瘀点瘀斑、舌下络脉迂曲怒张。心理方面多见性格易烦、易激惹而不轻易表露情感，健忘，注意力不集中，多愁善感而情绪易低落，内心常有不平与委屈感。对外适应能力方面，对寒邪、湿邪、情志刺激的耐受性差，血脉运行不畅则手足冰凉、痛经明显；因血行迟缓，康复与恢复速度较慢，损伤后瘀血留滞难消。"},{"type":"table","caption":"血瘀质常见表现","head":["表现项目","典型特征"],"rows":[["总体特征","肤色晦暗，色素沉着，痛处固定而刺痛，夜间尤甚，女性月经色紫暗有块"],["形态体态","形体偏瘦或消瘦，肌肉不丰，肌肤粗糙缺乏弹性"],["面色肤色","面色晦暗、黧黑或青紫，眼周与面颊色素沉着，肌肤甲错"],["舌象","舌质紫暗或暗红，或有瘀点、瘀斑，舌下络脉迂曲怒张，苔薄白"],["脉象","脉涩，或沉涩，或结代"],["情志表现","性格易烦，健忘，注意力不集中，多愁善感，情感不易表露"],["疼痛特征","痛有定处，固定不移，刺痛拒按，夜间加重，劳累后加重"],["二便与经血","大便色黑或秘结，妇女经色紫暗夹血块，经行不畅，痛经拒按"]]},{"type":"cards","columns":2,"items":[{"icon":"💗","title":"心脉瘀阻诸证","text":"冠心病心绞痛、心律失常、心悸失眠","bullets":["心脉痹阻，血行不畅","不通则痛，痛引肩背内侧","瘀久化热，心神失养"]},{"icon":"🩺","title":"痛证与痹证","text":"偏头痛、颈肩痛、腰痛、痛经、术后痛","bullets":["瘀血阻络，不通则痛","痛处固定，拒按","夜间或经期加重"]},{"icon":"🧬","title":"癥瘕积聚","text":"子宫肌瘤、肝硬化、脾大、腹部肿块","bullets":["气滞血瘀，瘀久成积","瘀血内结，癥瘕不消","久瘀损伤正气"]},{"icon":"🧠","title":"肢体与神志异常","text":"中风后遗症、肢体麻木、失眠、抑郁、痴呆","bullets":["瘀阻脑络，肢体不利","瘀血蒙蔽心神，神志异常","久病入络，络脉瘀阻"]}]},{"type":"table","caption":"血瘀质辨证要点与舌脉","head":["观察要点","典型表现"],"rows":[["舌象","舌质紫暗、青紫或暗红，舌面有瘀点瘀斑，舌下络脉迂曲怒张，舌面瘀筋显露"],["脉象","脉涩，或沉涩无力，或细涩，或结代"],["面色","面色晦暗、黧黑、青紫，眼眶暗黑，面颊色素沉着，唇甲紫暗"],["皮肤","肌肤粗糙干燥，肌肤甲错，色素沉着，脱屑，或有斑痣、瘢痕"],["疼痛","痛处固定不移，刺痛或钝痛，拒按，夜间加重，得温则减"],["出血","血色紫暗夹血块，出血后色紫，妇女经血紫暗有块，痛经拒按"],["兼夹征象","常兼气滞（胀痛窜痛）、痰湿（苔腻）、血虚（面唇色淡）之象"]]},{"type":"paragraph","text":"血瘀质的调养总则是活血化瘀、疏经通络，兼以理气、行滞、温经，并重视扶正与化瘀并用。瘀血为有形之邪，非行气活血不能化除，故施治须把握四条要点：一是活血而不伤正，纯用破血逐瘀之品易耗气伤阴，故当佐以益气养血之品以扶正，寓「瘀去新生」之意；二是行气以活血，气行则血行，故活血方中必配理气之品，如川芎、郁金、香附、枳壳之类；三是注意病位与寒热，瘀在胸者宣通胸阳，瘀在腹者通腑化瘀，瘀在经络者通络止痛，瘀久化热者当清热凉血，瘀在胞宫者温经暖宫；四是久瘀入络，须用虫类药搜剔通络，但须注意其破血之力与毒性。兼夹方面，兼气虚者益气活血，兼血虚者养血活血，兼寒者温经活血，兼痰湿者化痰祛瘀，气滞明显者疏肝理气。药食调养宜活血化瘀之品，忌过食寒凉与肥腻，宜适度运动以助血行，但须避免大强度对抗性运动与外伤。"},{"type":"table","caption":"血瘀质饮食宜忌","head":["类别","食物举例","说明"],"rows":[["宜食·活血化瘀","山楂、玫瑰花、桃仁、藏红花（少量）、黑木耳、洋葱、醋、蒜、韭菜、芹菜","活血通络，凉血散瘀"],["宜食·行气止痛","佛手、陈皮、青皮、玫瑰花、香橼、萝卜","气行则血行，助化瘀滞"],["宜食·温通血脉","生姜、桂圆、红糖、黄酒（少量）、羊肉、桂圆红枣茶","温经散寒，寒凝血瘀者尤宜"],["常用食疗","山楂玫瑰饮、桃仁红花粥、黑木耳山楂汤、醋泡黑木耳、当归生姜羊肉汤","每日或隔日；孕妇忌用活血之品"],["忌食·寒凉凝滞","冰饮、生冷海鲜、刺身、极低脂节食、长期生冷蔬果","寒凝血涩，瘀滞更甚"],["忌食·滋腻碍行","肥肉、动物内脏、过量甜食、油炸、糯米黏滞之品","助湿生痰，痰瘀互结"],["忌食·伤血动血","过量辛辣燥烈、烈酒、大量活血破血药自行服用","耗血动血，易致出血倾向"]]},{"type":"table","caption":"血瘀质起居·运动·情志·四季调摄","head":["调摄维度","具体方法"],"rows":[["起居","起居有常，睡眠充足，忌久坐久站不动；注意保暖，忌受寒受凉，忌冷水浴；避免外伤与过度用力屏气；衣着宽松，勿过紧束缚"],["运动","宜有氧与伸展类运动以促进血行：跑步、快走、瑜伽、太极、八段锦、五禽戏；避免长时间静坐与剧烈对抗性运动，运动后不宜立即冷水浴"],["情志","宜疏肝理气、保持心情舒畅，避免长期忧郁与压抑；血瘀者多易烦而郁，情绪不畅则气滞血瘀更甚，宜培养兴趣爱好与社交活动"],["四季调养","春宜疏肝理气以助血行；夏忌贪凉、忌空调冷风直吹以防寒凝；秋宜润燥兼活血；冬重保暖，温经通脉，忌大寒大凉饮食"],["其他调养","可用血海、膈俞、肝俞、委中、阿是穴等穴位按揉、刺络放血与艾灸；可在医师指导下选用血府逐瘀汤、桃红四物汤等方"]]},{"type":"callout","variant":"warning","title":"注意事项与禁忌","text":"药物禁忌：血瘀质忌用峻猛破血之品自服，如水蛭、生三棱、生莪术、斑蝥、马钱子等；红花、桃仁、益母草、丹参等活血药孕妇禁用，月经过多者、备孕者、出血倾向者慎用；抗凝药（如华法林、利伐沙班、阿司匹林）服用者不可自行合用活血化瘀药或大量活血食物，以防出血；手术前两周须停用活血药物并告知医师。食物禁忌：忌大量生冷与寒凉，忌烈酒与暴饮暴食，忌过多肥甘厚味。就医情形：出现突发剧烈头痛、喷射性呕吐、意识障碍、肢体一侧麻木无力或言语不清、胸口压榨性疼痛持续不缓解、咯血、呕血、黑便、便血、月经量骤增或淋漓不止、腹部包块迅速增大、皮肤出现大片瘀斑或出血点等情况，须立即急诊就医，排查脑出血、急性冠脉综合征、消化道出血与凝血功能障碍。特殊人群：孕妇、产后、手术前后、肿瘤放化疗期间及严重贫血者，调理方案必须由医师个体化制定，禁用活血破瘀之品。"},{"type":"keypoints","title":"血瘀质要点","items":["核心病机：气血运行不畅，瘀血内阻，血行迟滞","四诊抓手：舌紫暗有瘀斑、脉涩、面色晦暗、肌肤甲错、痛处固定刺痛","易患倾向：冠心病、痛经与月经不调、偏头痛、痹证、癥瘕积聚、中风后遗症","治则大法：活血化瘀、疏经通络，兼理气，扶正与化瘀并用","调养要点：忌寒凉与外伤，宜适度运动助血行；活血药与抗凝药同用须遵医嘱"]},{"type":"quote","text":"血行不畅，瘀血内阻者，则为痛；痛则不通，通则不痛。","source":"《医林改错》"}]},{"id":"qiyu","title":"气郁质","subtitle":"气机郁滞，情志不舒","icon":"🌿","summary":"以神情抑郁、胸部胀闷、善太息为主要特征，肝失疏泄、气机郁滞，宜疏肝理气、条达气机。","badge":"八种偏颇体质","blocks":[{"type":"paragraph","text":"气郁质是因气机郁滞、情志不舒，以神情抑郁、胸部胀闷、善太息为主要特征的体质类型。形态上多见形体偏瘦，体型不胖不瘦，动作缓慢，常有低头敛肩之态；面色偏暗或面色少华，神情抑郁，眉宇间常有愁绪，眼圈偏暗；毛发不甚光泽。生理方面，肝主疏泄、调畅气机，气郁则一身气机不畅，故胸胁胀满、善太息、嗳气、脘腹胀痛、窜痛不定，妇女可见乳房胀痛、月经不调、经前乳胀与痛经；气郁日久可生痰、成瘀、化火，故可兼见咽中如有物梗阻（梅核气）、失眠、焦虑，或口苦咽干、烦躁易怒等郁而化火之象；肝脾不调则纳差、腹胀、便溏或便结。心理方面多见性格内向不稳定、多愁善感、容易烦躁发怒、敏感多虑、优柔寡断、缺乏动力、易感到委屈与不平，遇事常闷在心里而不愿倾诉，情绪波动明显。对外适应能力方面，对外界刺激的适应能力较差，家庭与工作环境中的矛盾、压力易导致情绪抑郁而发病；症状随情志变化而增减，冬季与阴雨季节情绪低落更为明显，且长期情志抑郁者易患郁证、脏躁、梅核气、乳腺增生与失眠。"},{"type":"table","caption":"气郁质常见表现","head":["表现项目","典型特征"],"rows":[["总体特征","神情抑郁，胸部满闷，胁肋胀痛，善太息，脘腹胀满，症状随情志变化"],["形态体态","形体偏瘦，体型不胖不瘦，动作缓慢，常低头敛肩"],["面色肤色","面色偏暗或少华，眼圈偏暗，眉宇间常有愁绪"],["舌象","舌质淡红或暗，苔薄白，或薄腻；气郁化火时舌红苔薄黄"],["脉象","脉弦，或弦涩"],["情志表现","内向不稳定，多愁善感，敏感多虑，优柔寡断，易烦躁发怒，情绪波动明显"],["消化与呼吸","嗳气频作，纳差，脘腹胀满，大便不调，咽中如有物梗阻"],["妇科表现","经前乳胀痛，胸胁胀满，月经先后不定，痛经，经血紫暗夹块"]]},{"type":"cards","columns":2,"items":[{"icon":"😔","title":"郁证与情志病","text":"抑郁状态、焦虑症、郁证、脏躁、百合病","bullets":["肝失疏泄，气机郁结","情志不遂，郁而化火","心神失养，故失眠多梦"]},{"icon":"🗣️","title":"梅核气与咽部异物感","text":"癔球症、咽中异物感、慢性咽炎","bullets":["气郁痰凝，阻于咽喉","咯之不出、咽之不下","情志波动时症状加重"]},{"icon":"🎗️","title":"乳腺与妇科杂病","text":"乳腺增生、乳癖、月经不调、痛经、更年期诸证","bullets":["肝郁气滞，乳络不畅","冲任失调，气血紊乱","经前加重，乳房胀痛"]},{"icon":"🫄","title":"功能性胃肠病与疼痛","text":"功能性消化不良、肠易激综合征、偏头痛、胁痛","bullets":["肝气乘脾，脾胃失运","气滞腑胀，腹痛即泻","气行不畅则痛，窜痛"]}]},{"type":"table","caption":"气郁质辨证要点与舌脉","head":["观察要点","典型表现"],"rows":[["舌象","舌质淡红或暗，苔薄白；气郁化火者舌红、苔薄黄而干；兼痰湿者苔薄腻"],["脉象","脉弦，或弦涩，或弦而细"],["面色","面色偏暗或少华，眼圈偏暗，神情抑郁，眉宇愁锁"],["胸胁","胸部满闷，胁肋胀痛或窜痛，善太息，嗳气频作，矢气则舒"],["咽喉","咽中如有物梗阻，咯之不出、咽之不下，咽干而痒"],["情志","情绪抑郁，善太息，多愁善感，易激惹，兴趣减退，失眠多梦"],["病势特点","症状随情志变化而增减，反复发作，妇女常与月经周期相关"]]},{"type":"paragraph","text":"气郁质的调养总则是疏肝理气、条达气机、怡情易性，以「解郁为先」为纲，同时兼顾脾土与心神。理气之品多辛香走窜，易耗气伤阴，故施治须把握四条要点：一是疏肝而不伤阴，辛散太过则肝体失养而郁火更炽，须配伍养血柔肝之品如当归、白芍，寓「养肝以达郁」之意；二是理气兼健脾，肝木克土是气郁之人的常见病理，肝郁乘脾则纳差便溏，故宜佐以健脾助运之品；三是治郁先治气，气顺则郁解，兼火者清其郁火、兼痰者化其痰凝、兼瘀者化其瘀血，忌一味重镇安神而遏其气机；四是重视情志调摄，情志因素既是致病之因，也是调理之要，「移情易性」常胜于药物。兼夹方面，兼血瘀者理气活血，兼痰湿者理气化痰，兼血虚者疏肝养血，兼脾虚者疏肝健脾，兼阴虚者疏肝养阴。药食调养宜芳香理气之品，忌收敛酸涩与滋腻碍气。运动宜舒展疏导，快走、慢跑、太极、八段锦、游泳、瑜伽与各种球类皆宜，尤其宜户外与集体运动，忌长期闭居独处。"},{"type":"table","caption":"气郁质饮食宜忌","head":["类别","食物举例","说明"],"rows":[["宜食·疏肝理气","佛手、陈皮、青皮、玫瑰花、菊花、金桔、香橼、萝卜、紫苏","芳香辛散，条达气机"],["宜食·养血柔肝","当归、枸杞、大枣、桑葚、桂圆、蜂蜜、瘦肉、菠菜","养肝血以柔肝体，防辛散伤阴"],["宜食·健脾助运","山药、茯苓、白扁豆、莲子、小米、粳米","实脾土以防木克土，助气血生化"],["常用食疗","玫瑰花茶、佛手陈皮茶、玫瑰山药粥、金桔陈皮饮、百合莲子粥","每日或隔日；孕妇慎用芳香走窜之品"],["忌食·收敛酸涩","乌梅、石榴、南瓜籽、过量醋、过浓茶汤","收敛气机，郁滞不散"],["忌食·滋腻碍气","肥肉、奶油、油炸、糯米、浓汤、阿胶膏方久服","壅滞气机，加重胸闷腹胀"],["忌食·刺激兴奋","浓咖啡、烈酒、能量饮料、过量巧克力","加重烦躁、失眠与心悸"]]},{"type":"table","caption":"气郁质起居·运动·情志·四季调摄","head":["调摄维度","具体方法"],"rows":[["起居","起居有常，睡眠充足，忌熬夜；居室宜明亮通风，忌幽闭昏暗；养成规律作息，睡前避免思虑与刷屏；宜每日定时户外活动"],["运动","宜疏泄条达之运动：快走、慢跑、太极、八段锦、广播操、游泳、爬山、瑜伽、球类与团队运动；运动宜结伴而行，忌长期独处静坐"],["情志","为调养之首，宜多倾诉、社交、参观展馆、参与团体活动；练习深呼吸、冥想、书法与音乐疗法；遇不快之事及时疏导，忌反刍思虑、忌自我封闭"],["四季调养","春宜疏肝理气、踏青舒展，是气郁质最佳调养时节；夏宜清心宁神、忌贪凉；长夏宜健脾化湿以防肝郁乘脾；秋宜收敛适中、忌过悲；冬宜温阳藏精、防气机郁闭"],["其他调养","可用太冲、期门、膻中、内关、合谷、太冲等穴位的按揉与刺络；可用玫瑰花、合欢花、佛手等代茶饮；症状明显者宜尽早接受心理与专科诊疗"]]},{"type":"callout","variant":"warning","title":"注意事项与禁忌","text":"药物禁忌：气郁质忌用峻烈攻伐之品，如大黄、芒硝、巴豆、番泻叶久服，恐攻下伤气，加重气虚气郁；芳香理气药如木香、枳实、厚朴、青皮等不宜久服过量，以免耗气伤阴；长期服用抗抑郁药、镇静药者不可擅自停药或加用活血类中成药，须由精神科或专科医师评估调整；孕妇不宜大量使用芳香走窜与行气破气之品。就医情形：出现持续情绪低落超过两周、兴趣丧失、明显失眠或早醒、食欲体重明显下降、自责自罪感、无价值感、出现自伤或自杀念头与行为、严重焦虑心悸惊恐发作、躁狂表现（少眠多言、冲动易怒、思维奔逸）、以及胸痛、心悸气促、吞咽困难、颈部肿块与体重骤降等情况，须立即就医。特殊人群：孕妇、哺乳期妇女、青少年与老年人出现明显情绪障碍者应及时求助专业心理与精神卫生机构，切勿自行用药或依赖保健品替代治疗。"},{"type":"keypoints","title":"气郁质要点","items":["核心病机：肝失疏泄，气机郁滞，情志不遂","四诊抓手：脉弦、舌淡红苔薄白、神情抑郁、善太息、胸胁胀满、症状随情志波动","易患倾向：郁证与焦虑状态、梅核气、失眠、乳腺增生、功能性胃肠病、偏头痛","治则大法：疏肝理气、条达气机，兼健脾养血，治郁先治气","调养要点：情志调摄为先，宜结伴运动与社交；忌浓茶咖啡烈酒与滋腻收敛之品"]},{"type":"quote","text":"木郁达之。","source":"《素问·六元正纪大论》"}]},{"id":"tebing","title":"特禀质","subtitle":"先天禀赋特殊，反应异于常人","icon":"⭐","summary":"以先天禀赋特殊、对某些因素反应剧烈为主要特征，多见过敏体质与畸形、遗传性特征，宜益气固表、养血消风。","badge":"八种偏颇体质","blocks":[{"type":"paragraph","text":"特禀质是因先天禀赋特殊、遗传因素或生理特征明显异于常人，以对某些外界因素反应剧烈为主要特征的体质类型。其表现有两类：一为禀赋性特殊生理特征，如先天畸形（扁平足、脊柱侧弯、缺唇、腭裂、多指趾）、遗传性疾病（家族性高胆固醇血症、地中海贫血、蚕豆病、遗传性耳聋）、特殊生理状态（生理性无排卵、隐睾、胎记与色素痣）；二为过敏性体质，多见先天禀赋特异，对某些食物、药物、花粉、尘螨、动物皮毛、气候变化、气味、射线等刺激反应剧烈，出现皮肤瘙痒、风团、湿疹、荨麻疹、哮喘、过敏性鼻炎、过敏性结膜炎等。形态上多见皮肤易见划痕（皮肤划痕征阳性）、对温度与触碰反应敏感，可见面部或躯干有胎记、咖啡斑、痣与色素沉着，或有特殊畸形体征；一般无特定形态偏颇，可兼见形瘦或虚胖。生理方面，禀赋特殊者脏腑功能与常人有异，对外界的适应能力呈现明显的「过度反应」或「不足反应」两种倾向：过敏者反应过度，稍受刺激即发病；禀赋不足者则反应迟钝、适应能力低下。心理方面，多见体质敏感、聪慧而易受外界影响，或性格独特、孤僻，亦有性情急躁者；对环境、饮食、气候的改变适应较慢，换季或迁居时症状明显加重。由于禀赋难改，此类体质调养重在避其诱发因素、固表御邪、长期调护，以减少发病次数与程度。"},{"type":"table","caption":"特禀质常见表现","head":["表现项目","典型特征"],"rows":[["总体特征","先天禀赋特殊，或对某些食物、药物、花粉、尘螨、气候反应剧烈，起病急而反复"],["形态体态","可有先天畸形、胎记与色素痣、特殊生理结构；一般无特定胖瘦偏颇"],["面色肤色","可见咖啡斑、蒙古斑、胎记、色素沉着，或面色因过敏而红斑"],["舌象","多与兼夹体质相关；过敏发作期可见舌红苔薄黄或苔腻"],["脉象","浮数或浮紧（发作期），平素随兼夹体质而异"],["情志表现","敏感聪慧，易紧张多虑，对环境变化适应较慢；亦有性情急躁者"],["过敏表现","皮肤瘙痒、风团、划痕征、湿疹、丘疹，或喷嚏、鼻塞、喘息"],["病史特点","多有家族过敏史或遗传病史，反复发作，发作与接触史相关"]]},{"type":"cards","columns":2,"items":[{"icon":"🌾","title":"过敏性疾病","text":"过敏性鼻炎、哮喘、荨麻疹、湿疹、过敏性结膜炎","bullets":["禀赋特异，接触诱因即发","风邪夹湿客于肌肤腠理","肺卫不固，宣降失常"]},{"icon":"💊","title":"药物与食物过敏","text":"药物性皮炎、食物过敏、过敏性休克倾向","bullets":["禀赋不耐，接触即应","脾失健运，内生湿热","重者可累及心肺，须急救"]},{"icon":"🧬","title":"遗传性疾病倾向","text":"家族性高胆固醇血症、遗传性贫血、遗传性耳聋、畸形与残障","bullets":["禀赋异常，非后天可得","病位固定，治疗以调养为主","宜早筛早诊，评估家系"]},{"icon":"🫧","title":"自身免疫倾向","text":"类风湿关节炎、甲状腺自身免疫病、溃疡性结肠炎倾向","bullets":["禀赋失衡，免疫紊乱","正气不足，邪毒内侵","需专科长期随访管理"]}]},{"type":"table","caption":"特禀质辨证要点与舌脉","head":["观察要点","典型表现"],"rows":[["禀赋病史","出生即有的畸形、胎记、色素痣；家族中有过敏、遗传病或自身免疫病病史"],["过敏史","对特定食物、药物、花粉、尘螨、动物皮毛、冷热刺激、化妆品反应剧烈且可重复"],["舌象","平素随兼夹体质而异；发作期舌质淡红或红，苔薄白、薄黄或薄腻"],["脉象","发作期多见浮数、浮紧或细数，缓解期随兼夹体质而异"],["皮肤反应","划痕征阳性、皮肤瘙痒、风团、湿疹样皮疹、抓痕、渗出，或干燥脱屑"],["呼吸与五官","阵发喷嚏、鼻塞流清涕、嗅觉减退、喘息、胸闷、结膜红痒"],["病势特点","发作急骤、来得快去得快，反复发作；季节交替、气候骤变、接触诱因时明显加重"]]},{"type":"paragraph","text":"特禀质的调养总则是益气固表、养血消风、扶正御邪，以「避、固、调、养」四字为纲。避，即明确并规避已知过敏原，衣被饮食居室环境皆须留心，有条件者可作过敏原检测以明确靶点；固，即固护卫表、益气固表，腠理疏松者以玉屏风散类方培补肺卫；调，即调畅气血、养血消风，血虚风燥者养血润燥祛风，血瘀者活血通络；养，即长期调养，纠正兼夹的偏颇体质以减少敏感状态。施治须把握四点：一是辨清标本，禀赋之体多兼夹气虚、血虚、湿热等，标本兼顾，祛邪不伤正；二是过敏发作期以祛邪为先、止痒为要，缓解期以扶正固本为主；三是慎用峻猛之品，虫类药破血搜风虽效速，但体虚者易伤正，须在医师指导下短期使用；四是避免过度忌口，忌口过度可致营养不良、影响发育，须由医师与营养师评估后给出合理的忌口清单。药食调养宜固表祛风、养血润燥，忌辛辣发物与含常见致敏成分的食物。运动宜循序渐进，先低强度适应后再增量，避免高强度出汗后受风与花粉浓度高的时段。"},{"type":"table","caption":"特禀质饮食宜忌","head":["类别","食物举例","说明"],"rows":[["宜食·固表益气","黄芪、党参、白术、防风、山药、大枣、粳米、香菇","补肺固表，御风御邪"],["宜食·养血祛风","当归、熟地、白芍、何首乌、鸡血藤、桑葚、黑芝麻","养血润燥，血虚风燥者尤宜"],["宜食·清热利湿","薏苡仁、土茯苓、马齿苋、绿豆、冬瓜","湿热发疹者可用"],["常用食疗","玉屏风粥、黄芪红枣茶、当归乌鸡汤、薏仁赤小豆粥","按兼夹体质选用；明确致敏食物须严格回避"],["忌食·常见致敏","海鲜鱼虾、蟹、蜂产品、坚果、花生、牛奶蛋白、鸡蛋清、酒酿","已知致敏者严格回避；可疑者逐一排查"],["忌食·发物辛辣","竹笋、香菇（大量）、韭菜、鹅肉、辣酱、酒、烧烤","易助热动风，诱发皮疹瘙痒"],["忌食·寒凉黏腻","冰饮、生冷海鲜、肥甘厚味、浓汤","脾虚生湿，湿盛则痒甚"]]},{"type":"table","caption":"特禀质起居·运动·情志·四季调摄","head":["调摄维度","具体方法"],"rows":[["起居","床被枕巾宜常洗常晒，防尘螨；居室宜通风除尘，避免绒毛、毛绒玩具与宠物同室；花粉季节关窗减少外出；作息规律，忌熬夜耗伤正气"],["运动","宜循序渐进，从散步、太极、八段锦等低强度开始，适应后逐步增加；避开花粉高峰与高温高湿时段；运动后及时沐浴更衣，避免汗后受风；有过敏性哮喘者随身携带缓解药物"],["情志","保持心情平和，避免过度紧张与情绪波动诱发过敏；慢性皮肤病致情绪低落者尤需心理支持与家庭支持；避免反复搔抓与刺激"],["四季调养","春花季花粉多，宜戴口罩、减少户外活动、居室净风；夏避免汗后受凉与日晒后骤冷；秋宜固表润燥、防秋燥诱发干痒；冬宜温养、护住皮肤、避免过热水洗浴"],["其他调养","可在医师指导下选用玉屏风散、过敏煎、防风通圣散、养血祛风类方；耳穴贴压、督脉灸、穴位按摩可辅助调理，须避开皮损与发疹部位"]]},{"type":"callout","variant":"warning","title":"注意事项与禁忌","text":"药物禁忌：有过敏体质者就医时必须主动告知医师全部过敏史，所有用药前须核对成分，避免使用已知致敏药物及同类结构药物（如青霉素类、头孢类、磺胺类、含麻黄碱或某些中药注射剂的外用制剂）；含已知致敏原的中成药、外用膏剂、贴剂使用前须核对说明书；过敏发作期忌自行使用含激素、抗生素的复方外用药膏于面部与皱褶部位，长期使用可致皮肤变薄与依赖；虫类药如全蝎、蜈蚣、蜂房破风止痒力强，但有毒且破血，须医师指导短期使用，不可自行服用。就医情形：出现过敏性休克征象（全身风团、血管性水肿、喉头紧缩感或声音嘶哑、胸闷憋气、呼吸困难、面色苍白、大汗、意识模糊、血压下降）须立即拨打急救电话并使用肾上腺素自动注射装置（若备有）；出现全身风团伴呼吸困难、眼睑口唇明显肿胀、发热伴皮疹、皮肤大片脱皮或水疱、关节肿痛、异常口渴多尿、体重骤降等情况须尽快就医。特殊人群：孕妇、哺乳期妇女、儿童及过敏体质者，须在专科医师指导下管理，不可自行使用抗过敏药或外用激素制剂；儿童与老年人应随身备好急救药物与过敏信息卡。"},{"type":"keypoints","title":"特禀质要点","items":["核心病机：先天禀赋特殊，肺卫不固，腠理疏松，对外邪反应剧烈","四诊抓手：过敏史与家族史、划痕征阳性、发作性风团与痒疹、时作时止、遇诱因即发","易患倾向：过敏性鼻炎与哮喘、荨麻疹湿疹、药物与食物过敏、自身免疫性疾病倾向","治则大法：益气固表、养血消风，避其诱因，发作期祛邪、缓解期扶正","调养要点：严格避忌致敏物、居室防尘螨、花粉季减少外出；运动循序渐进，忌过度忌口与盲目忌药"]},{"type":"quote","text":"正气存内，邪不可干；邪之所凑，其气必虚。","source":"《黄帝内经·素问·刺法论》"}]},{"id":"pinghe","title":"平和质","subtitle":"阴阳气血调和，脏腑功能协调","icon":"☘","summary":"体形匀称健壮、面色红润、性格随和、适应能力强，是九种体质中的理想状态，宜守中致和、勿妄攻补。","badge":"八种偏颇体质","blocks":[{"type":"paragraph","text":"平和质是阴阳气血调和、脏腑功能协调、形体与心理和谐统一的体质类型，也是人群中占比最高的基本体质。形态上多见体形匀称健壮，体型不过肥不过瘦，肌肉结实有弹性，骨骼发育正常；面色红润有光泽，须发稠密有光泽，目光明亮，唇色红润；皮肤润泽有弹性，不粗不燥。生理方面，脏腑功能协调：脾胃运化健旺，纳谷正常、二便规律，不饥不胀；肺气宣降如常，呼吸均匀、声音洪亮、皮肤润泽无汗出不畅；心主血脉，心率适中、面色红润、睡眠安稳、精神饱满；肾精充盛，骨骼强健、发齿坚固、听力正常、男女第二性征发育正常；肝疏泄调畅，情绪稳定、情志舒畅、眠寐安宁。整个机体对外界环境变化有良好的适应能力，耐受寒暑冷热，饮食有节而不偏嗜，作息规律而少熬夜，患病后恢复迅速、预后良好，不易受外界病邪侵袭。心理方面表现为性格随和开朗、思维清晰敏捷、能与人融洽相处、乐观自信、情绪稳定、意志坚定、适应力强、少患得患失，介于过度兴奋与过度抑制之间。对外适应能力方面是最主要标志：对气候、地域、饮食、作息的变化均能良好适应，劳累后休息即可恢复，不易出现持续疲劳与明显不适，疾病发生率低、患病后自愈能力强。"},{"type":"table","caption":"平和质常见表现","head":["表现项目","典型特征"],"rows":[["总体特征","体形匀称健壮，面色红润有光泽，精力充沛，睡眠安稳，饮食、二便正常"],["形态体态","体型不胖不瘦，肌肉结实有弹性，骨骼发育正常"],["面色肤色","面色红润有光泽，唇色红润，皮肤润泽有弹性，须发稠密有光泽"],["舌象","舌质淡红，舌体适中，苔薄白而润"],["脉象","脉和缓有力，或从容平稳，节律规整"],["情志表现","性格随和开朗，思维清晰，乐观自信，情绪稳定，适应力强"],["饮食二便","纳谷正常，饥饱适度，不偏嗜；二便规律成形，晨起排便"],["适应能力","耐受寒暑冷热，作息规律少熬夜，患病后恢复迅速，不易反复"]]},{"type":"cards","columns":2,"items":[{"icon":"🛡","title":"抗病能力强","text":"外感不易侵袭，患病少且自愈快","bullets":["卫外固密，正气充足","邪不易入，传入亦浅","恢复迅速，预后良好"]},{"icon":"🌿","title":"脏腑功能协调","text":"消化、呼吸、循环、泌尿各系统功能正常","bullets":["脾胃健运，纳化有常","肺气宣降，呼吸调匀","肾精充盛，水道通畅"]},{"icon":"😌","title":"情志和谐","text":"情绪稳定乐观，睡眠安稳，社交良好","bullets":["肝气疏泄有度","心神安定，眠寐安稳","应变能力强，不易内伤"]},{"icon":"🌱","title":"养生策略：守中致和","text":"以维持而非矫正为原则，顺时而养、节欲保精","bullets":["饮食有节，不过饥过饱","起居有常，忌熬夜过劳","以动养形，以静养神"]}]},{"type":"table","caption":"平和质辨证要点与舌脉","head":["观察要点","典型表现"],"rows":[["舌象","舌质淡红，舌体大小适中，苔薄白而润，舌面无裂纹无瘀点"],["脉象","脉和缓有力，从容平稳，节律规整，无明显异常偏盛偏衰"],["面色","面色红润有光泽，唇色红润，目光明亮"],["形态","体型匀称，肌肉结实有弹性，骨骼发育正常"],["精神","精力充沛，反应敏捷，语言清晰，注意力集中"],["饮食睡眠","纳谷正常，二便规律，睡眠安稳，醒后精神饱满"],["病势特点","患病概率低，即使患病亦病程短、恢复快、少传变"]]},{"type":"paragraph","text":"平和质的调养原则为守中致和、勿妄攻补，即以维护现有平衡为要，不妄加补益、不滥用攻伐。平和质本身无须辨证用药，所谓「不治之治」即为最好的调养。养生要点有四：一是饮食有节、不过饥过饱，谨守「五味调和、荤素搭配、寒温适中」之则，忌偏嗜寒凉或辛辣燥热；二是起居有常，顺应四时阴阳消长，晨起适度活动、夜间早卧少熬夜，保证充足睡眠；三是动静相济、形神共养，以适度运动养形，以静坐、书画、冥想养神；四是情志平和、不过喜过怒，保持适度情绪波动有益气血运行，但须避免长期情绪激越与长期压抑。药物调养原则上不予常规使用，若确需进补亦宜平补、缓缓图功，切忌峻补、妄攻，尤忌以「养生」之名长期服用温燥或苦寒之品。定期体检、关注情志与睡眠，是平和质维持平衡的重要保障。"},{"type":"table","caption":"平和质饮食宜忌","head":["类别","食物举例","说明"],"rows":[["宜食·五味调和","五谷为养（粳米、小米、燕麦、荞麦、玉米）、五果为助（苹果、桃、梨、枣、橙）","谷气充盛则气血生化有源"],["宜食·荤素搭配","瘦肉、鱼、禽、蛋、豆腐、豆浆、菠菜、芹菜、菌菇、藻类","优质蛋白与膳食纤维并重"],["宜食·四时之果","春樱桃与草莓、夏西瓜与桃、秋梨与柿、冬枣与桂圆","应季而食，顺应自然之气"],["常用食疗","八宝粥、山药排骨汤、莲子百合粥、核桃黑芝麻糊、当归生姜羊肉汤","平补为度，四季皆宜，量宜适中"],["忌食·偏嗜","长期偏食寒凉（冰饮生冷）或燥热（辛辣烧烤烈酒）","破坏中焦，阴阳失调，易生偏颇"],["忌食·过食","暴饮暴食、过量宵夜、久饱、快餐与浓油赤酱","损伤脾胃，酿生痰湿湿热"],["忌食·不洁","霉变食品、隔夜生冷菜、来源不明之野味","损伤脾胃，诱发胃肠与过敏疾病"]]},{"type":"table","caption":"平和质起居·运动·情志·四季调摄","head":["调摄维度","具体方法"],"rows":[["起居","起居有常，晨起不赖床，睡前不贪玩；子时前入睡，卯时起身；劳逸适度，忌久坐久卧与熬夜；四季衣被厚薄随气候调整"],["运动","动静结合、量力而行：每周中等强度有氧运动三至五次，每次三十分钟左右，兼以八段锦、太极拳、拉伸等柔韧训练；运动后微汗即止，不宜大汗淋漓"],["情志","保持平和乐观，兴趣广泛，家庭与同事关系融洽；遇事宜从容面对，不过大喜大悲；闲暇时读书、抚琴、赏景、静坐，以养心神"],["四季调养","春养肝气舒展、踏青缓行；夏养心神清静、避暑热而不过食生冷；秋养肺气润燥、早卧早起；冬养肾气藏精、早卧晚起、避寒就温"],["其他调养","每年定期体检，监测血压、血糖、血脂与体重指数；保持兴趣与社交；可于四季交替时做体质复评，早期识别偏颇倾向"]]},{"type":"callout","variant":"warning","title":"注意事项与禁忌","text":"药物禁忌：平和质无适应证者不应长期服药，忌以养生为名长期服用补益药（如人参、鹿茸、阿胶、燕窝、膏方）或服用苦寒攻伐之品（如大黄、番泻叶、苦寒凉茶长期代饮），前者易致阴阳失调、碍胃生痰，后者易伤脾胃；服用保健食品与中成药前须阅读成分与禁忌；确需用药者应遵医嘱，出现不适及时停药反馈。就医情形：虽体质平和，仍在出现持续发热、咳嗽咯血、胸痛、明显消瘦、便血、晕厥、持续头痛与视力改变、异常出血与肿块等情况时及时就医；女性出现月经骤停或异常出血、孕期异常症状亦须尽早就诊。特殊人群：孕产期、哺乳期、婴幼儿与老年人均应遵循专科医嘱，不适用一般性养生建议；各类筛查（血压、血糖、血脂、肿瘤筛查、眼底与口腔检查）建议按年龄与风险因素定期进行。"},{"type":"keypoints","title":"平和质要点","items":["核心特征：阴阳气血调和、脏腑功能协调、形体与心理和谐统一","四诊抓手：体形匀称健壮、面色红润、舌淡红苔薄白、脉和缓有力、纳便正常、眠安","养生策略：守中致和，不妄攻补，以维护既有平衡为原则","调养要点：饮食有节、起居有常、动静相济、情志平和，顺四时而养","风险提示：平和质亦会因饮食失节、劳倦、情志失调、久病而向偏颇体质转化，宜定期复评"]},{"type":"quote","text":"阴平阳秘，精神乃治；阴阳离决，精气乃绝。","source":"《黄帝内经·素问·生气通天论》"}]}]}},"diseases":{"page":{"key":"diseases","title":"疾病调理","subtitle":"28 个常见病种·辨证分型·外治法·调养与就医提示","description":"收录内科、妇科、儿科、外科皮肤、五官科等八大类二十八个中医常见病种，逐病给出中医病名与证型概要、病因病机、辨证分型与论治（代表方与加减）、针灸推拿艾灸等外治法取穴操作、饮食调养、起居运动与预防、就医提示与禁忌。","lead":"本页按科室整理二十八个临床常见病种，每病均依中医内科学、妇科学、儿科学、外科学与五官科学教材的辨证框架撰写：先述病因病机，再列证型与代表方药，继以针灸、推拿、艾灸等外治法作为辅助手段，最后给出饮食调养、起居运动与预防建议，并明确标注何时必须就医的红旗征象与用药禁忌。方剂与剂量均须由执业医师依据四诊合参后决定，本页内容仅供学习参考，不构成诊疗建议。","type":"collection","icon":"fa fa-heartbeat","items":[{"id":"ganmao","title":"感冒","subtitle":"感冒｜普通感冒、流行性感冒","category":"内科","tags":["外感","六淫","肺卫","时行疫气","解表"],"meta":[{"label":"中医病名/证型概要","value":"感冒。分为风寒束表、风热犯表、暑湿伤表、气虚感冒、阴虚感冒五型，多属表证"},{"label":"主要症状","value":"恶寒发热、头痛身痛、鼻塞流涕、喷嚏咳嗽、咽痛咽干，或有汗出与口渴"},{"label":"舌脉要点","value":"风寒舌苔薄白、脉浮紧；风热舌边尖红苔薄黄、脉浮数；暑湿苔薄黄腻、脉濡数；气虚舌淡苔白、脉浮无力"},{"label":"治则","value":"解表达邪为主。风寒辛温解表、风热辛凉解表、暑湿清暑祛湿解表、气虚益气解表、阴虚滋阴解表"}],"image":"","imageHint":"感冒","summary":"感冒由六淫之邪乘虚侵袭肺卫所致，以发热恶寒、头身疼痛、鼻塞流涕、咳嗽咽痛为主要表现。风为六淫之首，常夹寒夹热夹暑夹湿伤人，故有风寒、风热、暑湿之分；素体气虚、阴虚者则易反复感冒而形成虚证感冒。病位主要在肺卫，病机为外邪束表、肺卫失宣、营卫不和。病程多为五至七天，普通感冒多可自愈，流行性感冒则传染性强、症状重，须重视防护与及时就医。","blocks":[{"type":"paragraph","text":"感冒的病因是六淫之邪与时行疫气。六淫之中风邪居首，常兼夹寒、热、暑、湿；时行疫气则具有强烈传染性与流行性，与气候反常、环境骤变、人群聚集而正气不足有关。其发病必须具备两个条件：一是外邪侵袭，二是正气不足。《素问·评热病论》所言「邪之所凑，其气必虚」，正说明素体亏虚是发病的内在基础。病位主要在肺卫，病机为外邪束表，肺卫失宣，卫气被遏，营卫失和；邪在卫表故见发热恶寒、头身疼痛、无汗或汗出不畅，肺气失宣故见鼻塞流涕、咳嗽咽痒。若素体阳气不足，则邪易从寒化而入里，形成风寒证；素体阴血亏虚、燥热内蕴，则邪易从热化、燥化，形成风热证；夏月暑湿当令，或恣饮生冷、居处湿热，则暑湿束表，卫阳被遏而身热不扬、头重身困；素体气虚、卫外不固者，邪虽入而正不支，肺卫无力驱邪外出，故咳嗽迁延、反复感冒；素体阴虚者，汗源不足、卫外失固，又兼燥热伤津，故干咳少痰、咽干而病程缠绵。病程一般五至七天，若治疗不当或正气不足，可迁延两三周，或由表入里转为咳嗽、哮病、肺炎等。"},{"type":"table","caption":"感冒辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["风寒束表证","恶寒重、发热轻、无汗、头痛身痛、鼻塞声重、喷嚏、流清涕、咳嗽、痰稀色白、不渴、苔薄白、脉浮紧","辛温解表，宣肺散寒","荆防达表汤（或荆防败毒散）","恶寒甚加麻黄、桂枝；咳嗽痰多加杏仁、前胡；项背强加葛根；体虚加黄芪"],["风热犯表证","发热重、恶风、有汗不畅、头胀痛、咽痛、口渴、鼻塞流浊涕、咳嗽痰黄稠、舌尖红苔薄黄、脉浮数","辛凉解表，宣肺清热","银翘散","咽痛甚加马勃、玄参；痰黄加黄芩、瓜蒌；口渴甚加天花粉；项肿加板蓝根"],["暑湿伤表证","身热、微恶风、汗少、头重如裹、肢体酸重、咳嗽痰黏、鼻流浊涕、心烦口渴或口中黏腻、胸闷脘痞、泛恶、便溏、苔薄黄腻、脉濡数","清暑祛湿，解表和中","新加香薷饮","胸闷脘痞加藿香、佩兰、苍术；咳嗽痰多加杏仁、浙贝；便溏加薏苡仁、白扁豆"],["气虚感冒","恶寒较甚、发热、无汗、头痛身楚、咳嗽痰白、气短懒言、倦怠乏力、反复易感、舌淡苔白、脉浮无力","益气解表，调和营卫","参苏饮（合玉屏风散）","气虚甚加黄芪、白术；表虚汗多加浮小麦、麻黄根；咳嗽加前胡、桔梗"],["阴虚感冒","身热、微恶寒、少汗、头昏心烦、口干、干咳少痰、手足心热、舌红少苔、脉细数","滋阴解表","加减葳蕤汤","咳甚加川贝、枇杷叶；心烦加竹叶、栀子；咽干加玄参、麦冬"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴列缺、合谷、大椎、太阳、风池；风寒加风门、肺俞，风热加大椎、曲池、印堂，暑湿加中脘、丰隆，气虚加足三里、气海，阴虚加太溪、三阴交","bullets":["毫针刺法，以泻法为主，虚证改用补法","感冒发热者可在大椎、少商点刺放血","留针二十至三十分钟，每日或隔日一次"]},{"icon":"🤲","title":"推拿按摩","text":"以推、拿、揉、摩、擦、捏法为主，先揉风池、太阳、印堂、攒竹，再按揉肺俞、风门、大椎，最后推拿背部膀胱经与四肢外侧","bullets":["以发热、头痛、鼻塞为治疗重点","颈项强硬者重点拿揉风池、肩井","推拿后饮温开水，取微汗为度"]},{"icon":"🔥","title":"艾灸与拔罐","text":"艾灸取足三里、气海、关元、大椎、太阳，每穴灸十五至二十分钟；闪罐或走罐沿督脉、膀胱经反复走罐至皮肤潮红","bullets":["风寒型最宜施灸，注意防止烫伤","风热、暑湿型宜灸量减半或改用刺络拔罐","面部与孕妇腰腹部不宜施灸与拔罐"]}]},{"type":"paragraph","text":"感冒的饮食调养，首重顾护津液与助汗透邪。风寒感冒宜温热辛香，忌生冷瓜果与冰饮，可食生姜红枣茶、葱白粥、荆芥防风粥以助阳解表；风热感冒宜清淡多水，忌辛辣煎炸、烧烤与酒类，宜饮金银花菊花茶、桑菊饮，并食绿豆汤、荸荠汁、白萝卜汁以清热生津；暑湿感冒宜清暑利湿，忌肥甘厚味与油腻甜品，宜饮藿香佩兰茶、薏仁赤小豆粥、冬瓜薏仁汤；气虚感冒宜益气易消化，忌生冷与过饥，可食山药粥、黄芪粥、莲子百合粥；阴虚感冒宜滋阴润燥，忌辛辣燥烈，可用银耳雪梨、百合麦冬、桑葚膏。饮食宜清淡易消化、少量多餐，忌浓茶浓咖啡以免伤津耗气；发热期间忌高糖高脂饮食，以免助热恋邪。康复期不宜过早进补甜腻之品，宜逐步恢复正常饮食。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：感冒期间应卧床休息，多饮温水，保暖避风，尤其避免汗出当风与洗浴受凉；居室保持通风但避免直吹冷风，湿度宜在百分之五十至六十；鼻塞时可用生理盐水滴鼻或蒸气吸入。运动：急性期绝对卧床，不宜勉强运动与出行；恢复期宜循序渐进，先室内散步、后户外慢走与八段锦，微微汗出即止，避免大汗与晨跑受寒。预防：顺应四时气候变化及时增减衣物，春季「春捂」，冬季「早卧晚起，必待日光」；流行感冒季节避免前往人群密集场所，出入公共场所戴口罩，勤洗手、常通风；易感人群可在医师指导下服用玉屏风散等预防；保证睡眠、饮食有节、适度运动以扶助正气；已患感冒者宜在家休息，避免传染他人。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：高热持续三天以上不退、热度超过三十九度五、畏寒伴寒战；咳嗽加重、咳痰变黄稠或带血、胸痛、明显气促、唇甲发绀；剧烈头痛、颈项强直、意识模糊、嗜睡或烦躁谵语；心悸、胸闷、心前区压榨性疼痛；鼻翼煽动、呼吸每分钟超过三十次；老年人、孕妇、儿童、婴幼儿及慢性心肺疾病、糖尿病、免疫功能低下者出现感冒症状应尽早就诊。用药禁忌：解表药多辛温发汗，风热、阴虚、暑热者忌用麻黄、桂枝、羌活等辛温峻剂；孕妇禁用峻猛发汗与攻下；肝肾功能不全者慎用含马来酸氯苯那敏的复方感冒药与解热镇痛药；抗生素不能用于普通感冒，除非医师判断存在细菌感染；不宜同时服用多种复方感冒药以免成分重复过量；体温超过三十八度五且持续不退时，不宜单纯依赖物理降温而延误治疗；老年人与儿童用药须遵医嘱与体重剂量。"},{"type":"keypoints","title":"感冒要点","items":["辨证关键：风寒以恶寒重、无汗、清涕、苔薄白、脉浮紧为要；风热以发热重、咽痛、黄涕、脉浮数为要","暑湿感冒多见身热不扬、头重身困、胸闷泛恶、苔黄腻，切勿误作风热而用辛凉重剂","体虚者多反复感冒，须辨气虚、阴虚分别益气解表与滋阴解表，不可一概辛温发散","普通感冒多可自愈，但高热不退、咳血、气促、心悸、意识改变必须立即就医","抗生素对病毒性感冒无效，滥用可致耐药与菌群失调"]}]},{"id":"kesou","title":"咳嗽","subtitle":"咳嗽｜急慢性支气管炎、咳嗽变异性哮喘","category":"内科","tags":["肺系病证","外感内伤","肺失宣降","痰","止咳"],"meta":[{"label":"中医病名/证型概要","value":"咳嗽。分外感咳嗽（风寒袭肺、风热犯肺、风燥伤肺）与内伤咳嗽（痰湿蕴肺、痰热郁肺、肝火犯肺、肺阴亏耗）"},{"label":"主要症状","value":"咳嗽有声，或有痰咯，或干咳无痰，兼见胸闷、咽痒、气逆、咯血等"},{"label":"舌脉要点","value":"风寒苔薄白脉浮紧；风热舌边尖红苔薄黄脉浮数；痰湿苔白腻脉濡滑；痰热舌红苔黄腻脉滑数；肺阴亏耗舌红少苔脉细数"},{"label":"治则","value":"外感者宣肺祛邪，内伤者祛痰养肺；标本兼顾，忌见咳止咳、忌苦寒败肺"}],"image":"","imageHint":"咳嗽","summary":"咳嗽由肺失宣降、肺气上逆所致，是肺系病证中最常见者。外感六淫与内伤脏腑功能失调均可致咳，外感多起病急、病程短、兼表证；内伤多病程长、反复发作，兼脏腑失调表现。临床辨证首辨外感内伤，再辨寒热虚实与痰之有无。治疗以宣通肺气为基本原则，外感宜宣散，内伤宜祛痰养肺，切忌见咳即用收涩敛肺之品，以免闭门留寇。 反复久咳者当注意排除器质性病变。","blocks":[{"type":"paragraph","text":"咳嗽的病位在肺，与肝、脾、肾密切相关。肺主气、司呼吸，主宣发肃降，通调水道；肺气肃降有权则气机下行、咳嗽自止。外感六淫从口鼻而入，或从皮毛而入，首犯肺卫，肺气失宣则咳嗽；风寒束表、卫气被遏，肺气不宣而咳声重浊、痰白清稀；风热犯肺、燥热灼津，肺失清肃而咳声频剧、痰黄黏稠；风燥伤肺、津液受灼而干咳少痰、咽干而痒。内伤咳嗽多由脏腑功能失调所致：脾失健运，水湿不化，聚为痰湿，痰湿上贮于肺，则咳嗽反复、痰多色白而黏，胸闷脘痞；痰湿郁久化热，痰热互结，肺失清肃，则咳声粗重、痰黄稠黏、发热面赤；肝主疏泄，肝气郁而化火，肝火上逆犯肺，则咳嗽阵作、咳引胸胁痛、咽干口苦；肺阴亏耗、虚火内炎，则干咳少痰或痰中带血、午后潮热、盗汗消瘦。此外，久病及肾，肾虚不能纳气，也可导致咳喘。病理因素以痰为主，痰随气升降，故咳嗽病机总属肺失宣降、痰气上逆；初起多实，久则由实转虚，或虚实夹杂，外感咳嗽误治或失治常可迁延转为内伤咳嗽。"},{"type":"table","caption":"咳嗽辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["风寒束肺证","咳声重浊紧闷，痰白清稀，鼻塞流清涕，恶寒无汗，头身痛，苔薄白，脉浮紧","疏风散寒，宣肺止咳","三拗汤合止嗽散","恶寒甚加麻黄、桂枝；痰多加半夏、陈皮；咽痒加蝉蜕、僵蚕"],["风热犯肺证","咳频剧，痰黏稠或黄，咽痛，发热恶风，鼻流黄涕，口渴，舌边尖红苔薄黄，脉浮数","疏风清热，宣肺止咳","桑菊饮","痰黄黏加黄芩、瓜蒌、浙贝；咽痛加牛蒡子、射干；热甚加黄连、石膏"],["风燥伤肺证","干咳无痰或痰少难咯，鼻咽干燥，咽干喉痒，舌红少津，苔薄白而干，脉浮数","疏风清肺，润燥止咳","桑杏汤","干咳甚加沙参、麦冬；痰黏难咯加川贝、瓜蒌；鼻衄加白茅根、藕节"],["痰湿蕴肺、痰热郁肺证","痰湿者咳嗽反复、痰多白黏、脘痞食少、苔白腻、脉濡滑；痰热者咳嗽气粗、痰黄稠或腥臭、面赤口渴、舌红苔黄腻、脉滑数","痰湿者燥湿化痰、理气止咳，痰热者清热化痰、宣肺止咳","痰湿用二陈汤合三子养亲汤，痰热用清金化痰汤","胸闷加枳壳、瓜蒌皮；食少加白术、莱菔子；热甚加黄芩、栀子；痰腥加鱼腥草、薏苡仁"],["肝火犯肺、肺阴亏耗证","肝火者咳逆阵作、痰少而黏、咳引胸胁痛、咽干口苦、舌红苔薄黄、脉弦数；肺阴亏者干咳少痰或痰中带血、午后潮热、盗汗消瘦、舌红少苔、脉细数","肝火者清肝泻火、肃肺止咳，肺阴亏者养阴润肺、清咳止血","肝火用黛蛤散合加减泻白散，肺阴亏用沙参麦冬汤","火盛加黄芩、栀子；胁痛加川楝子、郁金；痰中带血加仙鹤草、白及；潮热加地骨皮、青蒿"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴肺俞、中府、列缺、太渊；外感加合谷、大椎、风门，痰湿加丰隆、阴陵泉，痰热加曲池、内关，肝火加太冲、行间，肺阴亏加膏肓、太溪、三阴交","bullets":["实证用泻法，虚证用补法或平补平泻","急性咳嗽可加耳针肺、气管、支气管区","留针二十至三十分钟，每日一次"]},{"icon":"🤲","title":"推拿按摩","text":"胸腹部推拿以膻中、期门、章门、鸠尾为主；背部按揉肺俞、风门、膏肓、大杼、肾俞；配合揉风池、拿肩井、推桥弓","bullets":["痰多者加揉丰隆、摩腹以化痰","干咳者加揉太溪、三阴交滋阴","手法宜轻柔缓和，以透热为度"]},{"icon":"🔥","title":"艾灸与拔罐","text":"虚寒咳嗽宜灸肺俞、膏肓、足三里、命门，每穴十五分钟；实证咳嗽可用闪罐、刺络拔罐，取大椎、肺俞、膈俞","bullets":["肺阴亏者灸量宜小，可配太溪滋阴","咳嗽急性期伴发热者先针刺，灸法宜缓","皮肤破损、咯血倾向者慎用拔罐"]}]},{"type":"paragraph","text":"咳嗽的饮食调养应以养肺护津、化痰止咳为原则。外感风寒宜辛温宣散，忌冰饮生冷与寒凉瓜果，可食姜糖水、葱白粥、烤梨配川贝；外感风热与燥邪宜辛凉甘润，忌辛辣煎炸、烧烤与酒类，宜用雪梨川贝炖盅、百合粥、银耳雪梨膏、桑菊饮代茶；痰湿壅盛者宜健脾化痰，忌肥肉、甜腻、糯米黏滞、油炸与浓汤，可食山药陈皮粥、薏仁赤小豆粥、萝卜陈皮汤、白扁豆粥；痰热咳嗽者宜清热化痰，忌温燥羊肉、韭菜、辣椒与药膳汤锅，宜用荸荠汁、丝瓜络煎液、雪梨、百合；肺阴亏耗者宜滋阴润肺，忌辛辣燥烈、煎炸烧烤与温补之品，可食银耳百合羹、百合莲子粥、燕窝、雪梨、蜂蜜（幼儿不宜）、黑芝麻。饮食宜清淡易消化、少量多餐，忌过咸与过辣，咳痰多者每日宜饮足温水以稀释痰液、便于咯出；夜间咳嗽加重者睡前勿进食油腻。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：居室保持空气流通与适宜湿度，避免烟尘、油烟、粉尘与冷风刺激；被褥常晒常洗，枕头宜高些以利气道；咳嗽期间注意休息，保证睡眠，避免熬夜与情绪激动；戒烟并避免二手烟，痰多者每日多饮温水，勤漱口、保持口腔清洁。运动：急性咳嗽伴发热者卧床休息；病情稳定后可逐步进行八段锦、太极拳、散步、慢走与呼吸操，练习腹式呼吸与缩唇呼吸以改善肺功能； COPD 及其他慢性肺病患者可做缩唇呼吸、丹田呼吸与六字诀，切忌在寒冷户外剧烈运动。预防：积极戒烟，远离油烟与粉尘；四时气候变化及时增减衣物，冬季注意护住颈项与背部；避免过食辛辣燥烈与生冷；加强营养与适度锻炼以扶正；反复咳嗽迁延不愈者应查明病因，排除慢性支气管炎、支气管扩张、哮喘、心源性咳嗽与肺部器质性病变。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：咳嗽持续超过三周或超过八周（慢性咳嗽）不见缓解；咯血或痰中带血，量多或反复；高热持续不退、痰呈黄绿脓性或有腥臭；剧烈胸痛、呼吸困难、口唇发绀；显著气促、夜间不能平卧、下肢水肿；阵发性喘息、喉中哮鸣；消瘦、盗汗、乏力、食欲显著下降；婴幼儿呛咳后气促、喂养困难、口唇青紫。用药禁忌：成瘾性镇咳药（如可待因、右美沙芬等）不宜长期自行服用，痰多者更忌单用强力镇咳药以免痰液滞留窒息；含可待因的复方制剂孕妇、哺乳期妇女及儿童禁用；抗组胺药引起嗜睡，驾驶与高空作业者慎用；抗生素须由医师判断存在细菌感染时使用，不可自行滥用；肺结核、支气管扩张咯血者忌用温燥、活血破血之品以免加重出血；孕妇哺乳期与儿童用药须遵医嘱；中成药止咳颗粒、枇杷膏等亦须辨证选用，风寒与风热相反，误用可加重病情。"},{"type":"keypoints","title":"咳嗽要点","items":["辨证首辨外感内伤：外感起病急兼表证，内伤病程长兼脏腑失调","风寒咳声重痰稀白，风热咳频痰黄稠，风燥干咳咽干痒，三者鉴别要点明确","内伤咳嗽以痰为关键，痰湿白腻宜燥化，痰热黄稠宜清化，肝火咳引胁痛宜清肝","见咳止咳为大忌，痰多者不可一味收涩敛肺，以免留邪闭肺","咳嗽超过八周、咯血、气促、消瘦者必须就医排查器质性病变"]}]},{"id":"xiaochuan","title":"哮喘","subtitle":"哮喘｜支气管哮喘、喘息性支气管炎","category":"内科","tags":["肺系病证","哮病","发作期缓解期","痰","息痰"],"meta":[{"label":"中医病名/证型概要","value":"哮病（哮喘）。发作期分冷哮、热哮、寒包热哮、风痰哮；缓解期分肺脾气虚、肺肾两虚"},{"label":"主要症状","value":"发作时喉中哮鸣有声，呼吸急促困难，甚则喘息不能平卧，缓解后如常人或动则气短"},{"label":"舌脉要点","value":"冷哮苔白滑脉浮紧；热哮舌红苔黄腻脉滑数；寒包热哮苔白滑脉滑紧；肺肾两虚舌淡苔白脉沉细"},{"label":"治则","value":"发作期攻邪治标，祛痰利气、宣肺平喘；缓解期扶正固本，补肺脾肾、化痰降气"}],"image":"","imageHint":"哮喘","summary":"哮病以喉中哮鸣有声、呼吸急促困难，甚则喘息不能平卧为主要表现，反复发作，发作，缓解后如常人。其病理基础为宿痰内伏于肺，因外邪、饮食、情志、劳倦等诱因引触，以致痰阻气道、肺气上逆。辨证当分发作期与缓解期：发作期以邪实为主，辨冷、热、寒包热、风痰；缓解期以正虚为主，辨肺脾气虚与肺肾两虚。治疗强调「急则治标、缓则治本」，发作期重在祛痰利气，缓解期重在扶正固表、防止复发。","blocks":[{"type":"paragraph","text":"哮病的发生与发展，与宿痰内伏、外邪引动、脏腑虚损三者密切相关。痰为病理产物，又是致病之因：脾失健运则津液不化聚而成痰，肾阳不足则水泛为痰，肺失宣降则津液不布亦可为痰，痰伏于肺则成为发病的「夙根」。发作时因外感风寒、风热，饮食生冷肥甘鱼腥蟹虾、酒精，接触花粉尘螨油烟等过敏原，或情志拂逆、劳倦体虚，引动伏痰，痰随气升壅塞气道，肺气上逆，痰气交阻，气道狭窄，故见喉中哮鸣如水鸡声、呼气延长、吸气困难、端坐呼吸、不能平卧、大汗淋漓、面色苍白或青紫。辨证方面，痰白清稀而口不渴、畏寒肢冷、苔白滑、脉浮紧者为寒痰，治宜温肺化饮；痰黄稠而烦热口渴、面赤、苔黄腻、脉滑数者为热痰，治宜清热化痰；寒痰与热痰并见、痰黏色黄而兼恶寒无汗、舌红苔白滑者为寒包热，治宜解表散寒、清化痰热；痰浊壅盛、喉中作痒、反复发作无常、苔白腻而脉弦滑者为风痰，治宜祛风化痰。缓解期痰伏未动，肺气耗伤则气短声低、自汗易感，脾虚则纳少便溏、倦怠乏力，肾虚则呼多吸少、动则喘甚、腰膝酸软、畏寒肢冷。病理性质总属本虚标实，发作期以标实为主，缓解期以本虚为主，久病则虚实夹杂。"},{"type":"table","caption":"哮喘辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["冷哮证（发作期）","喉中哮鸣如水鸡声，呼吸急促，喘憋胸闷，咯痰稀白清亮，形寒肢冷，口不渴或喜热饮，苔白滑，脉浮紧","宣肺散寒，化痰平喘","射干麻黄汤","哮甚加葶苈子、白芥子；寒甚加干姜、细辛；痰多加半夏、款冬花"],["热哮证（发作期）","喉中痰鸣如吼，喘而气粗息涌，胸高胁胀，咳呛阵作，痰黄或白黏难咯，烦热口渴，汗出面赤，舌红苔黄腻，脉滑数","清热化痰，宣肺平喘","定喘汤","热甚加石膏、鱼腥草；痰黄稠加瓜蒌、浙贝、鱼腥草；气急加葶苈子"],["寒包热哮证","喉中鸣息有声，胸膈烦闷，呼吸急促，喘咳气逆，咯痰不爽，痰黏色黄，烦躁发热，恶寒无汗，口干，舌红苔白滑，脉滑紧","解表散寒，清化痰热","小青龙加石膏汤","表寒重加桂枝、麻黄；痰热重加黄芩、瓜蒌皮；喘甚加杏仁、葶苈子"],["风痰哮证","喉中作痒，哮鸣如吼，咳嗽痰多，痰黏难咯，发作无明显规律，诱发因素多样，苔白腻，脉弦滑","祛风化痰，降气平喘","射干麻黄汤合三子养亲汤","风盛加防风、地龙；痰多加莱菔子、白芥子；喘甚加葶苈子"],["缓解期肺脾气虚、肺肾两虚证","肺脾气虚者短气息低、动则加剧、自汗怕风、纳少便溏、舌淡苔白、脉弱；肺肾两虚者短气息促、吸气不利、咯痰质黏起沫、耳鸣腰酸、舌淡苔白、脉沉细","肺脾气虚者健脾益气、补肺固卫，肺肾两虚者补肺益肾、纳气平喘","肺脾气虚用六君子汤合玉屏风散，肺肾两虚用生脉地黄汤合金水六君煎","气虚甚加党参、黄芪；自汗加浮小麦、麻黄根；肾阳虚加附子、补骨脂；痰多加苏子"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"发作期主穴定喘、膻中、肺俞、尺泽、天突；冷哮加风门、列缺，热哮加曲池、鱼际，寒包热加大椎、曲池；缓解期加膏肓、足三里、太溪、肾俞","bullets":["发作期宜泻法，缓解期宜补法或平补平泻","哮喘急性发作可即刻针刺以缓急","留针二十至三十分钟，每日或隔日一次"]},{"icon":"🤲","title":"推拿按摩","text":"以推、揉、按、拿、搓法为主，重点按揉定喘、天突、膻中、肺俞、丰隆，揉拿风池、肩井、涌泉以助阳气升发","bullets":["胸背部横擦、搓法以温肺化痰","小儿推拿可揉板门、补脾经、清肺经","手法宜轻柔，以不诱发喘息为度"]},{"icon":"🔥","title":"艾灸与穴位贴敷","text":"缓解期艾灸肺俞、膏肓、足三里、命门、关元，每穴十五至二十分钟；寒哮可用温化寒痰膏或白芥子、细辛、干姜、肉桂等研末姜汁调敷于肺俞、膻中穴区","bullets":["哮喘发作期不宜大剂量艾灸","贴敷后局部发红灼痛应立即揭除","皮肤破损、瘢痕体质、孕妇腰腹部慎用"]}]},{"type":"paragraph","text":"哮喘的饮食调养以清淡、忌诱发、顾护脾胃为要。发作期痰多气促，宜清淡流质或半流质，忌过咸（盐可助痰生水）、过甜（甘可生痰）、过腻（可碍气道）；寒哮者忌一切生冷、寒饮、冰饮、刺身与冰镇饮料，可食生姜红枣茶、葱白粥、桂圆红枣炖鸡等温中之品；热哮者忌辛辣煎炸、烧烤、烈酒与温补汤锅，宜用雪梨、川贝、百合、荸荠、丝瓜、枇杷等清润之品；缓解期以健脾益气、补肾纳气为调养方向，宜山药粥、莲子百合粥、黄芪粥、核桃、黑芝麻、栗子、瘦猪肉、鸽子、鹌鹑等，并注意补充优质蛋白与铁质。日常须严格辨认并回避个人过敏食物，如海鲜鱼虾、蟹、鸡蛋、牛奶、花生坚果、酒精等；戒烟并避免油烟、尘螨、花粉、宠物毛屑；忌食过冷饮品，尤其在寒冷季节与清晨夜间；缓解期不可认为病愈而暴饮暴食，忌生冷瓜果与冰镇饮料。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：保持居所空气清洁，禁烟并避免油烟、粉尘、装修异味与刺激性气味；被褥枕巾常洗晒，保持室内湿度适宜；发作期宜取端坐或半卧位、避免平卧；随身携带缓解药物并定期检查有效期；记录发作日记，识别并回避诱因；季节交替时注意防寒保暖、预防呼吸道感染。运动：急性发作期绝对休息，缓解期在医师指导下进行呼吸康复训练（缩唇呼吸、腹式呼吸、丹田呼吸）与适度的八段锦、太极拳、步行；运动宜在温暖通风处进行，先吸后呼、吸呼比约一比三，避免在寒冷与雾霾天户外剧烈运动；逐步增强肺功能与免疫耐受，切忌勉强。预防：规范使用控制药物、不可自行停减吸入或口服激素；过敏体质者可行过敏原检测与针对性脱敏；接种流感与肺炎疫苗（须遵医嘱）；注意营养与睡眠，避免过劳与情绪激动；儿童哮喘家长应学会识别发作征象与正确使用缓解装置。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须立即就医：呼吸困难持续不缓解、说话不能成句、不能平卧、口唇甲床青紫；哮鸣音突然减弱或消失而气促加重（警惕气道痰栓与呼吸衰竭）；剧烈咳嗽后胸痛、咯血；大汗淋漓、意识模糊、烦躁不安或嗜睡（提示二氧化碳潴留）；心率极快或极慢、血压下降；使用缓解药物后仍不能控制；首次发作或症状明显加重。用药禁忌：β受体激动剂吸入剂过量可致心悸、手抖、烦躁，须按医嘱使用并记录频次；口服或吸入糖皮质激素不可突然停用，需逐渐减量否则可致反跳与肾上腺危象；含麻黄碱的复方感冒药、含可待因的镇咳药可诱发或加重心悸与喘息，哮喘患者应避免；β受体阻滞剂（心得安等）与部分降压药可诱发支气管痉挛，禁用；孕妇、哺乳期妇女、儿童用药须严格遵医嘱；茶碱类药物须监测血药浓度与肝肾功能，不可自行加量；发作期切忌平卧睡眠与强行运动。"},{"type":"keypoints","title":"哮喘要点","items":["辨证核心是分清发作期与缓解期：发作期标实（冷哮、热哮、寒包热哮、风痰哮），缓解期本虚（肺脾气虚、肺肾两虚）","冷哮以痰稀色白、畏寒、苔白滑、脉浮紧为要，热哮以痰黄稠、烦渴、苔黄腻、脉滑数为要","寒包热哮特征为痰黏色黄而舌红苔白滑，治宜解表散寒兼清化痰热，切不可单纯清热","缓解期重在扶正固本，补肺脾肾、化痰降气，是减少复发的关键","气促加重而哮鸣音突然消失、不能平卧、口唇青紫为危重征象，须立即急诊"]}]},{"id":"gaoxueya","title":"高血压","subtitle":"高血压｜原发性高血压","category":"内科","tags":["肝阳上亢","风痰上扰","气血亏虚","肾阴不足","瘀血阻窍"],"meta":[{"label":"中医病名/证型概要","value":"眩晕、头痛、中风先兆。证型分肝阳上亢、痰湿中阻、气血亏虚、肾阴亏虚、瘀血阻窍"},{"label":"主要症状","value":"头晕头胀、头痛、耳鸣、面红目赤、急躁易怒、心悸失眠，或眩晕乏力、腰膝酸软"},{"label":"舌脉要点","value":"肝阳上亢舌红苔黄脉弦数；痰湿舌苔白腻脉濡滑；气血亏虚舌淡脉细弱；肾阴亏虚舌红少苔脉细数"},{"label":"治则","value":"平肝潜阳、化痰祛湿、补益气血、滋补肝肾、活血通窍，随证立法"}],"image":"","imageHint":"血压","summary":"高血压以头晕、头痛、耳鸣、面红目赤、烦躁易怒为主要表现，中医多归属「眩晕」「头痛」范畴，病变脏腑主要在肝，兼及脾肾。其本在肝肾阴虚，其标为肝阳上亢、风痰上扰、瘀血阻窍。情志不遂、饮食膏粱厚味、劳倦内伤、年老体衰为其主要病因。治疗须标本兼顾，平肝与滋肾同施，化痰与活血兼顾，并强调调畅情志、节制饮食、规律起居。","blocks":[{"type":"paragraph","text":"高血压的基本病机是阴虚为本、阳亢为标，肝肾为病变中心，脾为生化之源，兼及冲任与心。病因以情志不遂、饮食不节、劳倦内伤、年老体衰、禀赋不足为主。情志失调，肝失疏泄，气郁化火，阳亢于上，则发为头胀头痛、面红目赤；恣食肥甘厚味、嗜酒，损伤脾胃，运化失健，聚湿生痰，痰浊中阻，清阳不升，浊阴不降，则眩晕头重如蒙、恶心呕吐；劳倦内伤，耗伤气血阴阳，气血亏虚，清窍失养，则头晕眼花、心悸失眠；年高肾亏，肾阴不足，水不涵木，肝阳偏亢，或肾阳衰微、髓海失充，则腰膝酸软、耳鸣、眩晕；久病入络，气滞血瘀，阻滞心脉脑络，则胸痛、头痛固定、肢体麻木。此外，肝火上炎可灼伤阴血，痰湿久蕴可化热，气虚运迟亦可成瘀，形成虚实夹杂、痰瘀互结的复杂病机。因此临证须辨清标本虚实，审察脏腑阴阳，不可一概苦寒清降。"},{"type":"table","caption":"高血压辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["肝阳上亢证","眩晕耳鸣，头目胀痛，面红目赤，急躁易怒，失眠多梦，口苦，舌红苔黄，脉弦数","平肝潜阳，清热息风","天麻钩藤饮","肝火盛加龙胆草、夏枯草；眩晕甚加菊花、白蒺藜；失眠加酸枣仁、夜交藤"],["痰湿中阻证","眩晕头重如蒙，胸闷恶心，呕吐痰涎，头目昏蒙，肢体困重，舌苔白腻，脉濡滑","燥湿化痰，降逆止眩","半夏白术天麻汤","胸闷加枳壳、瓜蒌皮；呕恶加生姜、代赭石；痰多加苍术、莱菔子"],["气血亏虚证","眩晕动则加剧，劳累即发，面色㿠白，神疲乏力，倦怠懒言，唇甲不华，心悸少寐，纳少，舌淡苔薄白，脉细弱","益气养血，健脾宁心","归脾汤","气虚甚加黄芪、党参；血虚加熟地、白芍、阿胶；失眠加夜交藤、合欢皮"],["肾阴亏虚证","眩晕耳鸣，腰膝酸软，五心烦热，失眠健忘，颧红口干，舌红少苔，脉细数","滋补肾阴，潜阳息风","六味地黄丸加味","阳亢加天麻、钩藤、石决明；耳鸣加磁石、柴胡；潮热加知母、地骨皮"],["瘀血阻窍证","头痛如刺，固定不移，眩晕心悸，失眠健忘，面唇晦暗，舌质紫暗有瘀斑，脉涩","活血化瘀，通窍止痛","通窍活血汤","头痛甚加白芷、川芎、藁本；久瘀加地龙、水蛭；兼气虚加黄芪"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴风池、百会、太冲、曲池、合谷、阳陵泉、三阴交；肝阳上亢加太溪、行间，痰湿加丰隆、阴陵泉，气血亏虚加气海、足三里，肾阴亏虚加肾俞、太溪","bullets":["肝阳上亢以泻法为主，取泻肝潜阳之效","虚证用补法或平补平泻，得气为度","留针二十至三十分钟，每日一次，十次为一疗程"]},{"icon":"🤲","title":"推拿按摩","text":"头面部推拿取印堂、攒竹、鱼际、头维、太阳、风池；颈项部揉拿风池、肩井、风府；背部按揉肝俞、肾俞、脾俞；足底涌泉按揉引火归元","bullets":["重点缓解头胀头痛与颈项僵紧","涌泉穴按揉每侧三至五分钟","手法宜柔和，避免过重刺激头部"]},{"icon":"🔥","title":"耳穴与艾灸","text":"耳穴贴压取神门、肝、肾、心、枕、太阳、皮质下，每次单耳贴压三至五日，双耳交替；虚证可灸足三里、气海、关元、命门以培补元气","bullets":["耳穴贴压期间避免水浸与频繁牵拉","每日自行按压数次，每次一至两分钟","实热证不宜大剂量艾灸"]}]},{"type":"paragraph","text":"高血压的饮食调养以清淡、限盐、控脂为基本原则，兼辨证施膳。肝阳上亢者宜平肝潜阳，忌辛辣燥烈、煎炸烧烤、烈酒与浓茶，可饮菊花决明茶、山楂决明茶、桑叶菊花饮，食芹菜、菠菜、荸荠、海带、紫菜；痰湿中阻者宜化痰祛湿，忌肥肉、甜腻、油炸、糯米与酒，可食薏仁赤小豆粥、山药陈皮粥、冬瓜薏仁汤、荷叶陈皮饮；气血亏虚者宜益气养血，忌生冷寒凉与过饥，可食山药粥、黄芪粥、莲子百合粥、桂圆红枣茶、黑芝麻；肾阴亏虚者宜滋阴补肾，忌辛辣温燥、煎炸烧烤与温补助火之品，可食银耳百合羹、桑葚膏、芝麻核桃、百合莲子粥、黑芝麻。日常须严格限盐（每日食盐一般不超过五克），慎用酱油、咸菜、腌制品与酱料；控制总热量与油脂，忌动物内脏、肥肉、蛋黄过量；戒烟限酒，忌浓茶与咖啡因饮品；多食新鲜蔬菜、水果与优质蛋白（鱼、瘦肉、豆制品）；若合并糖尿病、肾病，须同时按相应疾病医嘱调整蛋白与钾、磷摄入。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：作息规律，早睡早起，避免熬夜与长期过劳，保证每日七至八小时睡眠；保持居室安静通风、避免噪音与强光刺激；情绪稳定，避免大喜大怒、忧思恼怒与精神紧张；冬季注意保暖、夏季注意防暑，洗澡水温宜温不宜热、时间不宜过久，浴后及时擦干；避免屏气用力动作与剧烈快速起身，防止体位性低血压与脑卒中的诱发。运动：以中低强度有氧运动为主，如快走、慢跑、游泳、太极拳、八段锦、骑自行车，每次三十分钟左右、每周五至七次，强度以运动时能交谈、微微出汗为度；避免屏气用力和大强度器械运动；运动前后测量血压，血压显著升高或波动过大时暂停运动。预防：定期测量血压并记录，40 岁以上、有家族史者应每年至少测量一至两次；控制体重、限盐、戒烟限酒、坚持运动、保证睡眠，是延缓进展与减少心脑血管事件的关键；已确诊者须遵医嘱规律服药，不可自行减量、停药或改用「降压保健品」替代。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须立即就医：血压急剧升高伴剧烈头痛、喷射性呕吐、意识障碍、抽搐、肢体瘫痪（脑出血）；突发胸痛、压榨感持续不缓解、心悸大汗、心电图异常（急性冠脉综合征）；呼吸困难、夜间不能平卧、下肢水肿；剧烈头痛伴发热、颈项强直；血压突然显著降低伴头晕冷汗、面色苍白；血压波动明显、常规药物控制不佳。用药禁忌：不可自行加倍或停用降压药，也不可因血压降至正常便擅自停药，否则易致反跳与心脑血管事件；忌用含麻黄碱的复方感冒药、部分感冒止咳药与减肥药、浓茶咖啡因产品以免升高血压；吲哚美辛等非甾体止痛药、含甘草的制剂、糖皮质激素类可能升高血压；利尿剂与降压药需监测血钾与肾功能；孕妇、哺乳期妇女、儿童用药必须遵医嘱，禁用ACEI与ARB类；服利尿剂者不宜自行补钾或限钾；中成药如天麻钩藤饮、松龄血脉康等亦须辨证使用，不可当作降压西药替代。"},{"type":"keypoints","title":"高血压要点","items":["病机核心：阴虚为本、阳亢为标，肝肾为主，兼脾、痰、瘀","肝阳上亢以天麻钩藤饮平肝潜阳，最为常见；痰湿中阻以半夏白术天麻汤燥湿化痰","用药须标本兼顾：平肝潜阳同时不忘滋肾，痰瘀互结者化痰与活血同施","非药物干预是基石：限盐、控重、戒烟限酒、规律运动、保证睡眠、调畅情志","血压骤升伴剧烈头痛呕吐、意识障碍、胸痛气促为危急征象，须立即急诊"]}]},{"id":"tangniaobing","title":"糖尿病","subtitle":"糖尿病｜2 型糖尿病、胰岛素抵抗","category":"内科","tags":["消渴","三多一少","阴虚燥热","气阴两虚","脉络瘀阻"],"meta":[{"label":"中医病名/证型概要","value":"消渴。分上消肺热津伤、中消胃热炽盛、下消肾阴亏虚与阴阳两虚，常兼气阴两虚、脉络瘀阻"},{"label":"主要症状","value":"多饮、多食、多尿、体重下降，或口渴多饮而乏力气短，视物模糊，肢体麻木疼痛"},{"label":"舌脉要点","value":"肺热津伤舌红少津脉数；胃热炽盛舌红苔黄脉滑实；肾阴亏虚舌红少苔脉细数；气阴两虚舌淡红少苔脉细弱"},{"label":"治则","value":"清热润燥、养阴生津为基本法，兼益气、活血化瘀，标本缓急并顾"}],"image":"","imageHint":"糖尿","summary":"糖尿病属中医「消渴」范畴，以多饮、多食、多尿、体重减轻为主要表现。其基本病机为阴津亏损、燥热偏胜，病位主要在肺、胃、肾，以肾为关键，三者互相影响：肺燥津伤则口渴多饮，胃热过盛则消谷善饥，肾阴亏虚则尿多而甜。病久则阴损及阳、气阴两虚，并因阴虚燥热、脉络瘀阻而出现多种并发症。治疗以清热润燥、养阴生津为纲，随证益气、滋阴、温阳、活血，并须严格控制饮食、规律运动、规范监测血糖。","blocks":[{"type":"paragraph","text":"消渴的基本病机是阴津亏损、燥热偏胜，以阴虚为本、燥热为标。病因为禀赋不足、饮食不节、情志失调、劳欲过度与药毒损伤。禀赋不足者先天肾阴亏虚，燥热内生；饮食不节，过食肥甘厚味，损伤脾胃，运化失健，积热内蕴，燥热伤津；情志失调，肝气郁结，郁久化火，火灼津液；劳欲过度，房劳伤肾，肾阴亏耗，虚火内扰。病位虽在肺胃肾，关键在肾：肺主治节，输布津液，肺燥则津液不能输布而口渴多饮；胃主受纳腐熟，胃热炽盛则消谷善饥；肾主水，司开阖，肾阴亏虚则固摄失职、 水谷精微随尿而泄，故尿多而甜、尿频量多。肺胃燥热日久，耗伤肾阴，形成上消、中消并见，进而下消；病久阴损及阳，可见气阴两虚甚至阴阳两虚，气虚运化无力则水谷不能化生气血，血糖更行失控。燥热灼伤脉络、煎熬血液，血行不畅而致瘀阻，瘀血阻络则见视物模糊、肢体麻木疼痛、胸痹、中风等并发症。故消渴病机可概括为阴虚为本、燥热为标，兼气虚、阳虚与瘀血，久病多虚实夹杂。"},{"type":"table","caption":"糖尿病辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["肺热津伤证（上消）","口渴多饮，口舌干燥，尿频量多，舌边尖红苔薄黄而干，脉数","清热润肺，生津止渴","消渴方","口干甚加天花粉、麦冬；烦热加黄连、知母；尿多加天冬、覆盆子"],["胃热炽盛证（中消）","多食易饥，口渴，尿多，形体消瘦，大便秘结，苔黄，脉滑实有力","清胃泻火，养阴增液","玉女煎","饥甚加黄连、石膏；便秘加大黄、玄参；消瘦加黄精、葛根"],["肾阴亏虚证（下消）","尿频量多，混浊如膏或尿甜，腰膝酸软，头晕耳鸣，五心烦热，舌红少苔，脉细数","滋阴固肾","六味地黄丸","遗精加金樱子、覆盆子；尿浊加萆薢、车前子；潮热加知母、黄柏"],["阴阳两虚、气阴两虚证","阴阳两虚者小便频数如膏、面容憔悴、形瘦、腰膝酸软、畏寒肢冷、舌淡苔白而干、脉沉细无力；气阴两虚者口渴引饮而便溏或食少、神疲乏力、体瘦、舌淡红少苔、脉细弱","阴阳两虚者滋阴温阳、补肾固涩，气阴两虚者益气养阴","阴阳两虚用金匮肾气丸，气阴两虚用七味白术散合生脉散","畏寒加附子、桂枝；尿频加益智仁、桑螵蛸；乏力加黄芪、党参；便溏加山药、莲子"],["脉络瘀阻证","视物模糊或昏花，肢体麻木疼痛，肌肤甲错，或胸痛，舌质紫暗有瘀斑，脉涩","活血化瘀，疏通脉络","血府逐瘀汤","视物模糊加枸杞、菊花、青葙子；肢麻加全蝎、蜈蚣、鸡血藤"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴肺俞、胃俞、肾俞、三阴交、太溪；上消加太渊、中府，中消加内庭、中脘，下消加太溪、涌泉，气阴两虚加气海、足三里，脉络瘀阻加血海、膈俞","bullets":["实证用泻法、虚证用补法，留针三十分钟","艾灸虚证取关元、气海、足三里","每次选穴不宜过多，十至十二穴为宜"]},{"icon":"🤲","title":"推拿按摩","text":"腹部顺时针绕脐按摩三至五分钟，配合按揉中脘、天枢、气海、关元；背部按揉胰俞、脾俞、胃俞、肾俞；下肢按揉足三里、三阴交、太溪、涌泉","bullets":["腹部手法宜轻柔缓慢，餐后两小时内不宜操作","足三里与涌泉每侧三至五分钟","坚持自我按摩有助改善胰岛功能与末梢循环"]},{"icon":"🩸","title":"耳穴与自我监测","text":"耳穴贴压取内分泌、胰胆、肾、皮质下、饥点，每次贴单耳三至五日；配合每日规律测血糖并记录，空腹与餐后两小时监测，糖化血红蛋白定期复查","bullets":["记录饮食、用药、运动与血糖变化","出现低血糖先补糖再复盘原因","足部感觉减退者测血糖须用指血，勿用足血"]}]},{"type":"paragraph","text":"消渴的饮食调养以控制总能量、均衡膳食、定量定时为要，兼辨证配餐。上消肺热津伤者宜清淡润燥，忌辛辣煎炸、酒类与油炸，可饮天花粉麦冬茶、雪梨、百合、银耳；中消胃热炽盛者宜清胃凉润，忌肥甘厚味、甜食、浓汤与酒，可食黄瓜、苦瓜、冬瓜、绿豆、荞麦；下消肾阴亏虚者宜滋阴固肾，忌温燥壮阳之品，可食黑芝麻、桑葚、山药、莲子、芡实、覆盆子；气阴两虚者宜益气养阴，忌生冷寒凉与过饥过饱，可食山药粥、黄芪粥、莲子百合粥、桂圆红枣；脉络瘀阻者宜活血通络，忌过食寒凉与肥腻，可食黑木耳、桃仁、山楂、玫瑰花茶。日常须严格定时定量、少量多餐，主食以粗杂粮与全谷物为主，优选燕麦、荞麦、糙米、玉米与豆类；限制精制糖、糕点、含糖饮料、油炸与肥肉；每日保证足量蔬菜与适量低糖水果（血糖控制稳定者）；食盐摄入亦须限制；戒烟限酒；不随意食用「无糖食品」，其碳水化合物仍可升糖；服用降糖药或胰岛素者必须与进餐时间严格配合，防止低血糖。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：起居规律，保证每日七小时左右睡眠，避免熬夜与长期过劳；戒烟限酒；注意个人卫生与足部皮肤护理，每日温水洗足并仔细检查趾间有无破损、水疱、变色、溃疡，真菌感染及时处理；不赤脚行走，不自行处理鸡眼胼胝，趾甲不宜剪得过深；冬天取暖不用热水袋直接接触皮肤，忌用取暖器烘烤足部；注意口腔卫生，早晚刷牙、定期洁牙；保持情绪稳定，避免长期紧张焦虑与情绪波动，因情绪可直接影响血糖水平。运动：规律有氧运动是控制血糖的关键，如快走、慢跑、游泳、太极、八段锦、骑车，每次三十分钟、每周至少五天，强度以微微出汗、心率不超过每分钟一百一十次为宜；抗阻训练宜每周两次并注意保护关节；运动前后监测血糖，随身携带糖果以防低血糖；避免空腹剧烈运动与饭后立即运动；足部有病变者改为上肢与坐位运动，避免负重与冲击。预防：控制体重、合理膳食、规律运动是预防2型糖尿病的一级措施；家族史者、高体重者、有妊娠糖尿病史者应定期筛查空腹血糖与糖化血红蛋白；确诊者须规范治疗与随访，监测糖化血红蛋白、血脂、尿微量白蛋白与视网膜情况，积极防治心脑血管、肾脏、视网膜与神经病变。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须立即就医：血糖极高伴恶心呕吐、腹痛、呼吸深快、呼气有烂苹果味（糖尿病酮症酸中毒，为急症）；严重高血糖伴意识模糊、嗜睡或昏迷（高渗高血糖状态）；血糖过低伴意识障碍、抽搐、不能进食（低血糖昏迷）；足部溃疡并发黑、恶臭、周围红肿疼痛发热（糖尿病足感染）；突发视物模糊、视野缺损、眼前黑影（视网膜出血或脱落）；突发胸痛、憋气、大汗、左侧肩背放射痛（心梗）；突发一侧肢体无力麻木、口角歪斜、言语不清（中风）；腰痛伴肉眼血尿（肾病变）、水肿与少尿。用药禁忌：磺脲类与格列奈类可致低血糖，须按时进餐；双胍类可致乳酸酸中毒，肾功能不全、严重感染、缺氧时须停用并告知医师；胰岛素使用者严禁擅自停用或改量，外出必须随身携带胰岛素与糖块并注明使用说明；噻唑烷二酮类可致体重增加、水肿与肝损伤，须监测肝功能；孕妇禁用多数口服降糖药，须改用胰岛素并由内分泌专科与产科共同管理；服用糖苷酶抑制剂者须配合碳水化合物控制；任何中成药或保健品均不可替代降糖药，且可能含糖或影响血糖。"},{"type":"keypoints","title":"糖尿病要点","items":["病机为阴虚为本、燥热为标，病位在肺胃肾而以肾为关键，久则气阴两虚兼血瘀","三多一少中尤以多尿与消瘦为辨证要点，上消主肺、中消主胃、下消主肾","上消消渴方、中消玉女煎、下消六味地黄丸，阴阳两虚用金匮肾气丸，对证方药不可张冠李戴","饮食控制与规律运动是基础治疗，与药物同等重要，切忌以「无糖食品」替代降糖药","酮症酸中毒、高渗昏迷、足溃疡感染、视网膜出血与心脑血管事件为四大危急征象，须立即就医"]}]},{"id":"shimian","title":"失眠","subtitle":"失眠｜不寐、入睡困难与睡眠维持障碍","category":"内科","tags":["不寐","心神不宁","肝郁化火","痰热扰心","心脾两虚"],"meta":[{"label":"中医病名/证型概要","value":"不寐。证型分肝火扰心、痰热扰心、心脾两虚、心肾不交、心胆气虚"},{"label":"主要症状","value":"入睡困难、睡眠浅易醒、多梦、早醒、醒后不能再入睡，伴心悸、健忘、烦躁或疲倦"},{"label":"舌脉要点","value":"肝火舌红苔黄脉弦数；痰热舌红苔黄腻脉滑数；心脾两虚舌淡脉细弱；心肾不交舌红少苔脉细数"},{"label":"治则","value":"补虚泻实、调整阴阳、安神定志，实证泻其有余、虚证补其不足，兼治其因"}],"image":"","imageHint":"失眠","summary":"不寐是以经常不能获得正常睡眠为特征的一类病证，其基本病机是心神失养或心神被扰，神不守舍。病因有情志失常、饮食不节、病后失调、年迈体虚与禀赋不足，病位主要在心，与肝、脾、肾密切相关。临床辨证首辨虚实：实证多见肝火扰心与痰热扰心，虚证多见心脾两虚、心肾不交与心胆气虚。治疗重在安神，但须标本兼治，尤其重视情志疏导与起居调摄，忌单纯依赖安眠药物。","blocks":[{"type":"paragraph","text":"不寐的病位在心，与肝脾肾密切相关。《素问·宣明五气》曰「心藏神」，心神得养则寐，得扰则不寐；心神亦需肾精化血以濡养，需肝气疏泄以调畅，需脾气运化以生化。病因方面，情志失常最为重要，郁怒伤肝、忧思伤脾、惊恐伤肾，皆可致脏腑气机失调而神不守舍：肝郁化火，上扰心神则心烦不寐、烦躁易怒；忧思伤脾，脾虚则气血生化不足，心失所养而不寐，且运化失健而生痰，痰湿与气郁相搏可成痰热扰心之实证；年迈体虚或久病之后，肾精亏耗，髓海失充，心肾不交，水火不济，则心烦、头晕耳鸣、腰酸而难入睡；素体心胆气虚者，遇事易惊、胆气不壮，决断失职，故易惊醒多梦。病理性质有虚有实：邪气郁滞、痰热、火扰者属实，多见于青壮年；阴血不足、心脾两虚、肾精亏虚者属虚，多见于久病、年老或产后；两者可相互转化，实证日久耗伤气血可转虚，虚证之人复感邪气则成虚实夹杂。此外，饮食不节，嗜食辛辣肥甘或过饱过饥，宿食停滞化热，亦可影响睡眠。病程较长者常伴心悸、健忘、焦虑抑郁，须重视情志调摄与长期管理，避免单靠药物强行入睡而忽略病因。"},{"type":"table","caption":"失眠辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["肝火扰心证","不寐多梦，急躁易怒，头晕头胀，目赤耳鸣，口干而苦，不思饮食，便秘溲赤，舌红苔黄，脉弦数","疏肝泻火，镇心安神","龙胆泻肝汤","火盛加黄连、栀子；彻夜不寐加生龙骨、生牡蛎、磁石；便秘加大黄"],["痰热扰心证","心烦不寐，胸闷脘痞，泛恶嗳气，头重目眩，口苦痰多，纳呆，舌红苔黄腻，脉滑数","清热化痰，和中安神","黄连温胆汤","痰多加瓜蒌、浙贝；胸闷加枳壳、郁金；惊悸加珍珠母、龙骨；不寐甚加夜交藤、酸枣仁"],["心脾两虚证","心悸怔忡，失眠多梦，易醒健忘，头晕目眩，面色少华，神疲乏力，纳少便溏，舌淡苔薄，脉细无力","补益心脾，养血安神","归脾汤","气虚甚加黄芪、党参；血虚加熟地、白芍、阿胶；便溏加山药、莲子、扁豆"],["心肾不交证","心烦不寐，入睡困难，心悸多梦，头晕耳鸣，腰膝酸软，潮热盗汗，五心烦热，咽干少津，男遗精，舌红少苔，脉细数","滋阴降火，交通心肾","六味地黄丸合交泰丸","心烦加黄连、肉桂；盗汗加浮小麦、五味子；遗精加金樱子、莲须"],["心胆气虚证","心悸胆怯，易惊善恐，失眠多梦，虚烦不宁，气短自汗，倦怠乏力，舌淡苔薄，脉弦细","益气镇惊，安神定志","安神定志丸","易惊加珍珠母、龙齿、琥珀；自汗加黄芪、五味子；失眠甚加夜交藤、合欢皮"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴神门、内关、百会、安眠、四神聪、印堂；肝火加行间、太冲，痰热加丰隆、内庭，心脾两虚加心俞、脾俞、足三里，心肾不交加心俞、肾俞、太溪，心胆气虚加胆俞、丘墟","bullets":["虚证用补法并可加灸，实证用泻法，留针二十至三十分钟","安眠穴与四神聪为经验要穴，睡前留针可助入睡","每日或隔日一次，十次为一疗程"]},{"icon":"🤲","title":"推拿按摩","text":"头部推拿取印堂、攒竹、太阳、头维、风池；颈项揉拿风府、肩井；胸腹分推膻中、鸠尾；背部按揉心俞、脾俞、肾俞；最后擦涌泉引火归元、按揉神门","bullets":["睡前二十分钟做放松手法，疗效优于醒后补做","涌泉穴搓揉至发热为度","配合腹式呼吸与渐进式肌肉放松训练"]},{"icon":"🌿","title":"耳穴与芳香疗法","text":"耳穴贴压取神门、心、皮质下、交感、枕、肾、脾，每次单耳贴压三至五日；可于卧房使用淡薰衣草、檀香类芳香制品辅助放松","bullets":["睡前按压耳穴一至两分钟","芳香制品须保证气味不过浓以免刺激呼吸道","严重失眠伴焦虑者宜配合心理干预"]}]},{"type":"paragraph","text":"不寐的饮食调养以宁心安神、清淡助眠为原则。肝火扰心者宜清肝降火，忌辛辣、煎炸、烧烤、烈酒、浓茶与咖啡，可饮菊花决明茶、玫瑰花茶、苦丁茶，佐餐以苦瓜、绿叶蔬菜、莲子心；痰热扰心者宜清热化痰，忌肥甘厚味、甜腻、油炸、浓汤与酒类，可食山药陈皮粥、薏仁赤小豆粥、冬瓜、萝卜、荸荠、丝瓜；心脾两虚者宜补益心脾、益气养血，忌生冷寒凉与过饥，可食山药粥、黄芪粥、莲子百合粥、桂圆红枣茶、小米粥、瘦肉；心肾不交者宜滋阴降火、交通心肾，忌温补助火与辛辣燥烈，可食银耳百合羹、桑葚膏、莲子、百合、淡菜、黑色食物；心胆气虚者宜益气镇惊，忌浓茶、咖啡、能量饮料与烈酒，可食莲子心、百合、小麦、桂圆。日常须严格节律：晚餐七分饱、睡前二小时不再进食；忌夜宵、忌饮酒助眠；每日固定作息时间，包括休息日；日间保持适度光照与活动，午睡控制在二十分钟以内且不晚于下午三点；睡前避免浓茶、咖啡、能量饮料、吸烟与饮酒，避免长时间使用手机与观看刺激性影视。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：建立固定睡眠节律，睡前保持卧室内光线柔和、空气流通、温度适宜、安静整洁；床铺只用于睡眠，避免在床上处理工作与刷手机；睡前一至两小时避免观看刺激性节目、争论与讨论工作；白天保证自然光照与规律活动，夜间避免强光与长时间加班；久卧床榻者应有计划地增加户外活动与日光照射；老年人夜间起身应放慢动作并保持夜灯照明，防止跌倒。运动：适度规律运动有助改善睡眠，建议每日三十分钟中等强度有氧（快走、慢跑、游泳、太极、八段锦），但临睡前两小时内不宜剧烈运动；可配合八段锦中的摇头摆尾势、背后七颠与摩腹叩齿等简单导引，以及腹式呼吸、渐进式肌肉放松、正念冥想等放松训练。预防：建立健康的睡眠卫生习惯，避免把「睡不着」过度关注为焦虑源；长期失眠者应尽早就诊查明病因，而非自行长期服用安眠药；抑郁、焦虑、双相情感障碍、甲状腺功能异常、睡眠呼吸暂停、不宁腿综合征等均需针对性治疗；围绝经期女性与老年人失眠应重视激素与躯体疾病因素。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：连续失眠超过三个月、每周少于三晚入睡困难或睡眠时间不足四小时；严重失眠伴情绪极度低落、有自伤或自杀念头（须立即急诊或心理危机干预）；伴明显躁狂表现如少眠多言、精力异常旺盛、冲动消费；夜间憋醒、憋气、晨起头痛、鼾声伴呼吸暂停（筛查睡眠呼吸暂停）；伴打鼾与白天嗜睡、腿部难以形容的不适感（不宁腿综合征）；长期依赖安眠药方能入睡、停药后反弹加重；出现心悸胸闷、严重焦虑发作、惊恐发作、幻觉妄想等。用药禁忌：安眠药（苯二氮䓬类）与非苯二氮䓬类（唑吡坦等）应由医师处方并短期使用，不宜自行加量、换药或长期服用，连续使用后须在医师指导下逐步减停以免反跳性失眠与戒断；服用安眠药期间严禁饮酒与驾驶；抗组胺药、甲状腺素、激素、激素类减肥药、麻黄碱类感冒药、含咖啡因制剂均可致失眠或加重失眠；中成药如酸枣仁、天王补心丹、朱砂安神丸等亦须辨证使用，朱砂类制剂不宜久服以防汞蓄积；孕妇、哺乳期妇女、儿童、老年人及肝肾功能不全者禁用或慎用镇静催眠药；饮酒、服安眠药与驾驶三禁。"},{"type":"keypoints","title":"失眠要点","items":["病位在心，与肝脾肾相关，病机为心神失养或心神被扰，神不守舍","辨证首分虚实：实证以肝火扰心、痰热扰心为主，虚证以心脾两虚、心肾不交、心胆气虚为主","肝火扰心用龙胆泻肝汤，痰热扰心用黄连温胆汤，心脾两虚用归脾汤，心肾不交用六味地黄丸合交泰丸，心胆气虚用安神定志丸","安神只是治标，须同时处理情志、饮食、作息与躯体疾病等病因","长期失眠、依赖安眠药、伴躁狂或抑郁者必须就医，不可自行长期服药"]}]},{"id":"weitong","title":"胃痛","subtitle":"胃痛｜慢性胃炎、消化性溃疡、功能性消化不良","category":"内科","tags":["脾胃病证","胃脘痛","寒热虚实","肝气犯胃","胃阴不足"],"meta":[{"label":"中医病名/证型概要","value":"胃痛（胃脘痛）。证型分寒邪客胃、饮食伤胃、肝气犯胃、湿热中阻、瘀血停胃、胃阴亏耗、脾胃虚寒"},{"label":"主要症状","value":"上腹胃脘部疼痛为主，兼见胀满、嗳气、泛酸、恶心呕吐、纳差、大便异常"},{"label":"舌脉要点","value":"寒邪舌苔白润脉弦紧；肝气舌苔薄白脉弦；胃阴亏耗舌红少苔脉细数；虚寒舌淡苔白脉迟弱"},{"label":"治则","value":"理气和胃止痛为基本原则，寒者温、热者清、虚者补、实者泻，审因论治"}],"image":"","imageHint":"胃痛","summary":"胃痛以上腹胃脘部近心窝处疼痛为主症，是脾胃病证中最常见者。病因为外感寒邪、饮食不节、情志失调、劳倦内伤与瘀血内停，病位在胃，与肝脾关系密切。基本病机是胃气郁滞、络脉失养，「不通则痛」与「不荣则痛」并见。辨证当分寒热虚实、气血阴阳，外感者多实，内伤者多虚或虚实夹杂，久病入络常成瘀。治疗以理气和胃止痛为纲，同时审因论治，忌一味辛香温燥或苦寒攻伐。","blocks":[{"type":"paragraph","text":"胃痛的病位在胃，胃为六腑之一，以通为用、以降为顺，喜润恶燥。寒邪客胃，寒主收引凝滞，得温则减、遇寒则痛；饮食不节，或过饥过饱、恣食肥甘生冷，宿食停滞，胃失和降，致胃脘胀痛拒按、嗳腐吞酸；肝气犯胃，肝主疏泄，情志不遂则横逆犯胃，气机阻滞则胃脘胀痛连胁、窜痛不定；瘀血停胃，血行不畅，瘀阻胃络则痛如针刺、痛有定处、拒按，夜间尤甚；湿热中阻，湿热蕴结，胃失和降则胃脘灼热疼痛、口苦嘈杂；胃阴亏耗，胃失濡养则隐痛绵绵、灼热、饥不欲食、口干便秘；脾胃虚寒，中阳不振，运化失职则隐痛喜温喜按、空腹痛甚、得食痛减、泛酸呕涎。病机可概括为胃气郁滞、络脉失养，不通则痛、不荣则痛。初病多实，久病多虚，虚实夹杂者临床最为常见。情志因素在胃痛的发生发展与复发中作用突出，故《素问·举痛论》有「怒则气上、喜则气缓、悲则气消、恐则气下、惊则气乱、寒则气收、炅则气泄、思则气结」之说，说明情志失调可直接影响胃之气机而致痛。"},{"type":"table","caption":"胃痛辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["寒邪客胃证","胃脘疼痛，得温痛减，遇寒加重，喜温喜按，口和不渴，苔白润，脉弦紧","温胃散寒，行气止痛","香苏散合良附丸","寒甚加吴茱萸、干姜；食滞加神曲、麦芽；痛甚加延胡索、川楝子"],["饮食伤胃证","胃脘疼痛，胀满拒按，嗳腐吞酸，呕吐不消化食物，吐后痛减，大便不爽，苔厚腻，脉滑","消食导滞，和胃止痛","保和丸","食积化热加黄连、黄芩；便秘加大黄、枳实；脾虚加白术、砂仁"],["肝气犯胃证","胃脘胀痛，痛连两胁，嗳气频作，遇情志不遂痛作，矢气则舒，大便不畅，苔薄白，脉弦","疏肝理气，和胃止痛","柴胡疏肝散","火郁加栀子、黄连；胀甚加青皮、郁金；呕恶加半夏、生姜；痛甚加川楝子、延胡索"],["湿热中阻、瘀血停胃证","湿热者胃脘疼痛急迫、灼热、得热痛减、口苦嘈杂、恶心、便溏不爽、舌红苔黄腻、脉滑数；瘀血者痛如针刺、痛有定处、拒按、舌紫暗有瘀斑、脉涩","湿热者清化湿热、理气和胃，瘀血者化瘀通络、理气和胃","湿热用清中汤，瘀血用失笑散合丹参饮","热甚加黄连、栀子；呕恶加藿香、竹茹；痛甚加白芍、延胡索、三七"],["胃阴亏耗、脾胃虚寒证","胃阴亏耗者胃脘隐痛灼热、饥不欲食、口燥咽干、大便干结、舌红少苔、脉细数；脾胃虚寒者隐痛喜温喜按、空腹痛甚、得食痛减、泛酸呕涎、便溏、舌淡苔白、脉沉迟无力","胃阴亏耗者养阴益胃、和中止痛，脾胃虚寒者温中健脾、和胃止痛","胃阴亏耗用一贯煎合芍药甘草汤，脾胃虚寒用黄芪建中汤","口干加麦冬、石斛；痛甚加白芍、甘草、延胡索；气虚甚加党参、白术；泛酸加乌贼骨、煅瓦楞子"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴中脘、足三里、内关、公孙；寒邪加神阙、关元，肝气加太冲、阳陵泉，湿热加内庭、曲池，瘀血加血海、膈俞，虚寒加脾俞、胃俞，胃阴亏加太溪、三阴交","bullets":["实证用泻法，虚证用补法并加灸，留针二十至三十分钟","急性剧痛时可先取内关、公孙、阳陵泉","配合腹部热敷与艾灸对寒证、虚寒证效果显著"]},{"icon":"🤲","title":"推拿按摩","text":"腹部推拿取中脘、建里、天枢、气海、关元，掌摩腹部五分钟；背部按揉脾俞、胃俞、肝俞、肾俞；四肢按揉足三里、内关、阳陵泉、太冲","bullets":["以揉、推、摩、按、拿为主，手法宜温和","餐后一小时内不宜手法","按压中脘与足三里时以酸胀舒适为度"]},{"icon":"🔥","title":"艾灸与穴位贴敷","text":"虚寒证与寒邪客胃证宜灸中脘、足三里、关元、气海，每穴十五分钟；可用吴茱萸、白芥子、细桂等研末姜汁调敷中脘与天枢穴区","bullets":["艾灸对虚寒证效果最好，热证不宜灸","贴敷时间一般两小时以内，皮肤发红灼痛立即揭除","孕妇腹部禁用贴敷与艾灸"]}]},{"type":"paragraph","text":"胃痛的饮食调养总以定时定量、细嚼慢咽、忌食生冷为要，并随证配餐。寒邪客胃与脾胃虚寒者宜温热，忌一切生冷、冰饮、刺身、冷拌菜与冰镇饮料，可食姜糖水、葱姜粥、小茴香炖羊肉、桂圆红枣茶；饮食伤胃者宜消食导滞，忌过饱与难消化食物，可食山楂、神曲、麦芽煎汤、莱菔子、白粥与软面条；肝气犯胃者宜疏肝理气且忌郁怒与情绪紧张，饮食宜清淡规律，可饮佛手陈皮茶、玫瑰花茶、金桔饮；湿热中阻者宜清淡忌油，忌肥肉、油炸、辛辣、酒类、浓汤与海鲜，可食冬瓜、丝瓜、绿豆、薏仁、荸荠；瘀血停胃者忌粗硬、粗糙、过烫与粗纤维过多之品，宜细软稀烂、少量多餐；胃阴亏耗者宜滋阴润燥、忌辛辣燥烈与煎炸，可食山药、石斛、麦冬、沙参、玉竹、百合、梨、藕。日常须少食或不食咖啡、浓茶、碳酸饮料、巧克力、薄荷、烟酒与过酸过辣食物；症状缓解期仍需节食量，避免暴饮暴食；服健胃消食药期间忌生冷油腻。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：起居有常，保证睡眠，避免熬夜；情志调畅是胃痛调养的关键，恼怒伤肝、忧思伤脾均可致痛，须避免长期紧张、焦虑与过度思虑，必要时学会放松与呼吸调节；注意腹部保暖，春秋季避免露腹受凉，夜间睡眠宜穿肚脐保暖衣；作息与进食时间固定，避免夜间加餐；胃痛发作时宜采取左侧卧位或俯卧位以减轻疼痛。运动：胃痛急性期宜静养，症状缓解后可行散步、慢走、太极、八段锦、腹式呼吸与揉腹功（以脐为中心顺时针轻揉），每次十五至二十分钟，运动后不宜立即进食冷饮与冷食；避免长距离跑步、跳跃等震动性运动与餐后即刻运动。预防：三餐定时定量、细嚼慢咽、七八分饱；忌烟酒与暴饮暴食；慎用 NSAIDs 等非甾体止痛药以免加重黏膜损伤；出现上腹隐痛、纳差、黑便者应及时检查；幽门螺杆菌感染者应遵医嘱完成规范根除治疗并复查；有家族胃癌史者定期胃镜筛查。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：胃部剧痛持续不缓解或呈刀割样痛并向背部放射（急性胰腺炎、穿孔）；突然剧烈上腹痛伴面色苍白、冷汗、血压下降（消化道出血或穿孔）；呕血或咖啡色呕吐物、黑便与柏油样便；腹部膨隆、叩诊浊鼓、呕吐不止、不排气不排便（幽门梗阻或肠梗阻）；上腹痛伴持续高热、皮肤黄染与肝功能异常（急性胆囊炎、胰腺炎、肝炎）；体重在短期内明显下降、贫血、吞咽困难、腹块（胃癌可能）；疼痛规律改变、夜间痛醒、进食后加重（消化性溃疡）；反复呕吐伴血不能进食。用药禁忌：严禁自行长期服用布洛芬、双氯芬酸、阿司匹林等非甾体抗炎药与激素类药物，可致溃疡、出血与穿孔；含麻黄碱、咖啡因的感冒药与止痛片可加重胃病；抑酸药（奥美拉唑等）不宜自行长期服用，掩盖病情并影响维生素B12与镁吸收；脾胃虚寒者忌用苦寒清胃之品如黄连、黄柏、蒲公英、大量番泻叶；孕妇、哺乳期妇女、儿童用药须遵医嘱；中成药（气滞胃痛颗粒、香砂养胃丸、越鞠保和丸等）亦须辨证选择，不可混用。"},{"type":"keypoints","title":"胃痛要点","items":["病机为胃气郁滞、络脉失养，不通则痛与不荣则痛并见，病位在胃而与肝脾密切相关","辨证要点：喜温喜按得食减者多虚寒，拒按得热减者多实寒，胀痛连胁者肝气，刺痛固定者血瘀，灼痛口苦者湿热，隐痛口干者胃阴亏","寒邪客胃用香苏散合良附丸，肝气犯胃用柴胡疏肝散，湿热中阻用清中汤，瘀血停胃用失笑散合丹参饮，胃阴亏耗用一贯煎合芍药甘草汤，脾胃虚寒用黄芪建中汤","情志与饮食是最重要的可控因素，调畅情志与节制饮食常胜于药物","剧痛、呕血黑便、腹胀不排气、进行性消瘦为红旗征象，须立即就医"]}]},{"id":"xuanyun","title":"眩晕","subtitle":"眩晕｜眩晕症、椎-基底动脉供血不足、内耳性眩晕","category":"内科","tags":["眩证","肝阳上亢","痰湿中阻","瘀血阻窍","清窍失养"],"meta":[{"label":"中医病名/证型概要","value":"眩证。证型分肝阳上亢、气血亏虚、痰湿中阻、肾精亏虚、瘀血阻窍"},{"label":"主要症状","value":"头晕眼花、视物旋转、站立不稳，常伴恶心呕吐、汗出肢冷、头重如蒙、耳鸣"},{"label":"舌脉要点","value":"肝阳上亢舌红苔黄脉弦数；痰湿苔白腻脉濡滑；气血亏虚舌淡脉细弱；瘀血舌紫暗脉涩"},{"label":"治则","value":"补虚泻实、调整阴阳、化痰祛瘀、滋养肝肾，使清窍得养、浊阴得降"}],"image":"","imageHint":"眩晕","summary":"眩证以头晕眼花、视物旋转、站立不稳为主要表现，轻者闭目即止，重者如坐舟车、旋转不定、不能站立，常伴恶心呕吐、汗出肢冷、头重如蒙、耳鸣等症。病位在清窍，与肝、脾、肾、痰、瘀密切相关。病机总属风、火、痰、瘀扰动清窍或精血不足、清窍失养。辨证当分虚实，实证多见肝阳上亢、痰湿中阻、瘀血阻窍，虚证多见气血亏虚、肾精亏虚。治疗须审因论治，尤重调畅情志、节饮食、起居规律与积极查找病因。","blocks":[{"type":"paragraph","text":"眩晕的病位在清窍，与肝脾肾关系最为密切。《素问·至真要大论》曰「诸风掉眩，皆属于肝」，肝为风木之脏，体阴用阳，肝气升发太过或肝阴不足不能制阳，均可致阳亢风动，上扰清窍而眩；情志不遂、恼怒过度则肝气上逆，郁而化火，肝阳上亢，发为眩晕头痛、面红目赤。脾为后天之本、主运化升清，饮食劳倦、化源不足则气血亏虚，清阳不升，头目失养而眩晕；脾失健运则水湿不化，聚湿成痰，痰湿中阻，阻遏阳气、清阳不升，浊阴不降，故眩晕头重如蒙、恶心呕吐。肾藏精、主骨生髓，脑为髓海，肾精亏损则髓海不足，脑失所养而眩晕耳鸣、腰膝酸软；肾阴不足水不涵木可致肝阳上亢，肾阳衰微则不能化水，痰浊内生。瘀血为有形之邪，阻滞脉络，清窍失养或血行不畅不能上荣于脑，故眩晕如坐舟车、痛有定处、面色晦暗。病机总括为风、火、痰、瘀上扰清窍或精血亏虚、清窍失养，实证多虚证少，而又常虚实夹杂。发作性眩晕须重视排除耳源性与脑血管性病因，不可一概按「肝阳上亢」论治。"},{"type":"table","caption":"眩晕辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["肝阳上亢证","眩晕耳鸣，头目胀痛，面红目赤，急躁易怒，失眠多梦，腰膝酸软，头重脚轻，舌红苔黄，脉弦数或弦细数","平肝潜阳，清火息风","天麻钩藤饮","火盛加龙胆草、夏枯草；眩晕甚加菊花、白蒺藜、珍珠母；阴虚加生地、白芍、女贞子"],["气血亏虚证","眩晕动则加剧，劳累即发，面色㿠白，神疲乏力，倦怠懒言，唇甲不华，心悸少寐，纳少，舌淡苔薄白，脉细弱","补益气血，健脾养心","归脾汤","气虚甚加黄芪、党参；血虚加熟地、阿胶、白芍；眩晕甚加天麻、钩藤"],["痰湿中阻证","眩晕头重如蒙，胸闷恶心，呕吐痰涎，头目昏蒙，肢体困重，纳呆多痰，舌苔白腻，脉濡滑","燥湿化痰，降逆止眩","半夏白术天麻汤","痰多加苍术、莱菔子；呕恶加生姜、代赭石；胸闷加瓜蒌皮、枳壳；眩晕甚加钩藤、石决明"],["肾精亏虚证","眩晕耳鸣，腰膝酸软，失眠健忘，目眩发焦，须发早白，偏头痛，舌淡或红，脉细弱，尺脉沉细","补益肾精，滋养肝肾","左归丸（肾阴虚）","精亏加龟板、鹿角胶、枸杞；眩晕加菟丝子、天麻；耳鸣加磁石、柴胡"],["瘀血阻窍证","眩晕日久不愈，痛如针刺，固定不移，头重如蒙，面色晦暗，唇甲紫暗，或有头部外伤史，舌质紫暗有瘀斑，脉涩","活血化瘀，通窍止眩","通窍活血汤","久瘀加地龙、水蛭；兼气虚加黄芪、党参；兼痰湿加半夏、白术"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴百会、风池、太阳、颈夹脊、太冲、内关；肝阳上亢加太溪、行间，痰湿加丰隆、阴陵泉，气血亏虚加气海、足三里，肾精亏虚加肾俞、太溪，瘀血加血海、膈俞","bullets":["实证泻法、虚证补法，虚证可加灸，留针二十至三十分钟","百会与风池为要穴，针感向头额部传导为佳","急性眩晕发作期可先针内关、百合、足三里以缓急"]},{"icon":"🤲","title":"推拿按摩","text":"头部推拿取印堂、攒竹、鱼际、太阳、头维；颈项部重点揉拿风池、风府、肩井、颈夹脊；背部按揉肝俞、脾俞、肾俞；足底涌泉按揉","bullets":["颈项手法宜轻柔缓慢，避免暴力旋转手法","每次推拿十分钟左右，可缓解颈源性眩晕","配合颈深屈肌等长等张训练以改善颈椎稳定性"]},{"icon":"🌀","title":"耳穴与眩晕操","text":"耳穴贴压取神门、肝、肾、脾、枕、内耳、额；配合自编眩晕体操：头位缓慢转动、眼球跟踪训练、平衡板站立训练，每次十分钟","bullets":["耳穴贴压后每日按压数次","前庭功能训练须循序渐进，避免诱发剧烈眩晕","眩晕急性期以休息为主，训练延后进行"]}]},{"type":"paragraph","text":"眩晕的饮食调养以清淡、均衡、避免诱发为原则，并随证配餐。肝阳上亢者宜平肝潜阳，忌辛辣燥烈、煎炸烧烤、烈酒与浓茶浓咖啡，可饮菊花决明茶、桑叶菊花饮、决明子代茶并多食芹菜、荸荠、海带、紫菜；痰湿中阻者宜化痰祛湿，忌肥肉、甜腻、油炸、糯米、浓汤与酒，可食薏仁赤小豆粥、山药陈皮粥、冬瓜薏仁汤、陈皮茯苓饮；气血亏虚者宜益气养血，忌生冷寒凉与过饥过劳，可食山药粥、黄芪粥、莲子百合粥、桂圆红枣茶、黑芝麻、瘦肉；肾精亏虚者宜补益肾精、填精益髓，忌过度耗伤与熬夜，可食黑芝麻、桑葚、核桃、栗子、枸杞、何首乌、淡菜、优质蛋白；瘀血阻窍者宜活血通络，忌寒凉与肥腻，可食黑木耳、山楂、桃仁、玫瑰花茶并注意避免外伤。日常须保证饮水与规律三餐，避免低血糖与脱水诱发眩晕；发作性眩晕发作期宜卧床休息、避免起身过猛；乘车前可少食以减少呕吐。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：起居有常，睡眠充足，避免熬夜与长期过劳；居住环境宜安静、光线柔和、空气流通，突发眩晕时先平卧闭目、避免强光刺激；动作宜缓，起床、起身、转头时放慢速度，防止跌倒；洗澡水温不宜过高、时间不宜过长，浴室宜装扶手；情绪稳定，避免恼怒与过度思虑，这是肝阳上亢与痰湿中阻型最重要的日常调摄；发作期不宜独自洗澡、外出与登高。运动：发作期以休息为主，缓解期宜适度有氧运动（快走、慢跑、太极、八段锦、游泳）以增强体质与前庭代偿；配合颈深屈肌等长训练与平衡功能训练（单腿站立、闭眼站立、太极云手），循序渐进；避免突然转头、翻滚、密闭旋转类运动；运动中出现眩晕立即停止并坐下休息。预防：积极寻找病因——颈椎病、后循环缺血、梅尼埃病、突发性耳聋、贫血、高血压、低血糖、心律失常、药物与耳毒性物质均可致眩晕，须针对性治疗；避免长期使用链霉素、庆大霉素等耳毒性药物与含汞制剂；防止头部外伤；发作频繁或有言语不清、肢体无力者须立即急诊。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须立即就医：突发眩晕伴剧烈头痛、喷射性呕吐、颈项强直、意识障碍、抽搐（脑出血或蛛网膜下腔出血）；突发眩晕伴口角歪斜、言语不清、肢体麻木无力、视物障碍、行走不稳（中风）；眩晕伴明显耳鸣听力骤降、耳痛、流脓、发热（急性中耳炎或突发性耳聋）；眩晕伴持续呕吐不能进食、明显脱水、电解质紊乱；眩晕伴心悸胸闷、晕厥、黑矇（心源性）；旋转感持续不缓解且无法站立、行走；老年人反复跌倒；新发严重眩晕伴视物旋转与眼球震颤明显。用药禁忌：眩晕发作期避免使用可致前庭毒性的药物，慎用链霉素、卡那霉素、庆大霉素、顺铂、水杨酸盐；抗组胺类与止吐药可致嗜睡与反应迟钝，服后严禁驾车与高空作业；镇静催眠药可加重共济失调；降压药与降糖药须按医嘱调整，不可自行减量以免引起体位性低血压或低血糖；孕妇禁用前庭镇静类药物并须就诊产科；TIA 属卒中预警，须住院评估，不可当作普通眩晕处理；中成药如天麻钩藤饮、半夏天麻丸、归脾丸须辨证服用，痰湿者不宜用滋腻补益之品。"},{"type":"keypoints","title":"眩晕要点","items":["病位在清窍，与肝脾肾相关；病机为风、火、痰、瘀上扰清窍，或精血亏虚清窍失养","实证以肝阳上亢（天麻钩藤饮）、痰湿中阻（半夏白术天麻汤）、瘀血阻窍（通窍活血汤）为主，虚证以气血亏虚（归脾汤）、肾精亏虚（左归丸）为主","眩晕而头重如蒙、恶心呕吐者属痰湿；眩晕而头胀痛、面红目赤者属肝阳；眩晕而耳鸣腰酸者属肾精亏；眩晕而舌紫脉涩者属瘀血","发作性眩晕必须排查耳源性与脑血管性病因，不可一概按肝阳上亢论治","眩晕伴肢体无力、言语不清、剧烈头痛呕吐、听力骤降者须立即急诊"]}]},{"id":"yuejingbudiao","title":"月经不调","subtitle":"月经不调｜月经先后无定期、月经先期、月经后期、月经过少","category":"妇科","tags":["月经病","肾虚","肝郁","脾虚","调经"],"meta":[{"label":"中医病名/证型概要","value":"月经先后无定期、月经先期、月经后期、月经过多、月经过少。证型分肾气虚、肾阴虚、肝郁、脾虚、阳盛血热、阴虚血热、气血虚、血瘀"},{"label":"主要症状","value":"月经周期先后不定，或提前、延后，量多量少，色质异常，伴腰膝酸软、胁胀、纳差、乏力"},{"label":"舌脉要点","value":"肾气虚舌淡苔薄脉沉细；肝郁舌淡红苔薄白脉弦；脾虚舌淡胖苔白脉缓弱；血热舌红苔黄脉数或细数"},{"label":"治则","value":"调经治本，补肾、疏肝、健脾、清热、养血、化瘀，随证而施，顺应月经周期"}],"image":"","imageHint":"月经","summary":"月经不调是以月经周期、量、色质异常为主要表现的妇科常见病，包含月经先后无定期、月经先期、月经后期、月经过多与月经过少。其病机为冲任失调、胞宫藏泻失常，与肾、肝、脾三脏关系最为密切。肾主生殖、为先天之本，肾气盛衰决定胞宫按时藏泻；肝主疏泄、调畅气机，肝郁则月经先后不定；脾为气血生化之源，脾虚则经血来源不足或统摄无权而量多量少。治疗以调经治本为纲，强调顺周期、分阶段调治，并须重视情志、饮食与起居调摄。","blocks":[{"type":"paragraph","text":"月经不调的病位在胞宫，与冲任、肝肾脾关系密切。《素问·上古天真论》言女子「二七而天癸至，任脉通，太冲脉盛，月事以时下」，冲任通盛、胞宫按时藏泻是月经正常的生理基础。肾藏精、主生殖，肾气充盛、天癸成熟是月经按时来潮的前提，肾气不足或肾阴亏虚则封藏失职、冲任失调而经期紊乱、量少色淡，或经间期出血；肝藏血、主疏泄，肝气郁结则冲任失调，血海蓄溢无度而经前经后无定期、量多色暗有块、乳房与胁肋胀痛，郁而化火则血热妄行而月经先期；脾为气血生化之源、主统血，饮食劳倦伤脾则化源不足而经量渐少、色淡质稀，或统摄无权而经量过多、经期延长、崩漏；阳盛血热者素体阳盛或过食辛辣炙煿，邪热迫血妄行而月经先期、量多色深红；阴虚血热者热扰冲任而先期量少、色红质稠、颧红潮热；气滞血瘀者经行不畅、色紫暗有块、痛经拒按。病机可概括为冲任失调、胞宫藏泻失度，治疗当辨虚实、辨脏腑、顺周期，在经前经后分别调治，不可一概补益或一概清利。"},{"type":"table","caption":"月经不调辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["肾气虚、肾阴虚证","肾气虚者周期提前或延后、量少色淡暗质稀、腰酸腿软、头晕耳鸣、小便频数、舌淡苔薄、脉沉细；肾阴虚者量少色红质稠、颧红潮热、手足心热、失眠盗汗、舌红少苔、脉细数","肾气虚者补肾益气、养血调经，肾阴虚者滋肾养阴、调补冲任","肾气虚用固阴煎，肾阴虚用左归丸合四物汤","肾阳虚加鹿角霜、仙茅；潮热加青蒿、地骨皮；血热加生地、丹皮；失眠加夜交藤、酸枣仁"],["肝郁证","经期先后不定，量多或量少，色暗红有块，经前乳房与胁肋胀痛，烦躁易怒，胸闷不舒，舌淡红苔薄白，脉弦","疏肝解郁，理气调经","逍遥散","郁热加丹皮、栀子；乳胀加橘核、王不留行；痛经加川楝子、延胡索"],["脾虚证","经期延后或量多，色淡质稀，纳少便溏，神疲乏力，面色萎黄，浮肿，舌淡胖苔白，脉缓弱","健脾益气，养血调经","归脾汤","气虚甚加黄芪、党参；便溏加山药、莲子、扁豆；量多加茜草、艾叶"],["阳盛血热、阴虚血热证","阳盛血热者经期提前、量多色深红质稠、心烦口渴、面赤唇红、便秘溲赤、舌红苔黄、脉数；阴虚血热者先期量少色红质稠、颧红潮热、手足心热、咽干、舌红少苔、脉细数","阳盛血热者清热凉血、调经止血，阴虚血热者养阴清热、凉血调经","阳盛血热用清经散，阴虚血热用两地汤","热甚加黄连、地榆；量多加地榆、槐花；潮热加女贞子、旱莲草；便秘加大黄"],["气血虚弱、气滞血瘀证","气血虚弱者经期延后或量少、色淡质稀、面色苍白、神疲乏力、头晕心悸、舌淡苔薄白、脉细弱；气滞血瘀者经期延后、量少色紫暗有块、经行不畅、小腹疼痛拒按、舌紫暗有瘀斑、脉弦涩","气血虚弱者益气养血、调经固冲，气滞血瘀者理气活血、化瘀调经","气血虚弱用八珍汤，气滞血瘀用血府逐瘀汤","气虚加黄芪；血虚加阿胶、鸡血藤；心悸加远志、酸枣仁；痛经加延胡索、五灵脂；块多加三棱、莪术"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴关元、气海、三阴交、中极、血海、地机；肾虚加肾俞、太溪，肝郁加太冲、曲泉，脾虚加脾俞、足三里，血热加曲池、大椎，血瘀加膈俞、次髎","bullets":["经前一周开始施治，连针三至五个周期效果较好","虚证用补法并可加灸，实证用泻法","关元、三阴交为调经要穴，针感向小腹与下腰传导为佳"]},{"icon":"🤲","title":"推拿按摩","text":"腹部推拿取关元、气海、中极、归来、子宫穴，掌摩小腹与腰骶部；腰骶部按揉肾俞、次髎、十七椎；下肢按揉三阴交、血海、足三里、太冲","bullets":["经前一周每日按摩一次，每次二十分钟","以温通为法，手法宜轻柔和缓","可配合艾灸关元、三阴交温养冲任"]},{"icon":"🔥","title":"艾灸与穴位贴敷","text":"虚寒与肾虚型艾灸关元、命门、肾俞、三阴交，每穴十五分钟；可用艾叶、干姜、肉桂等制成温经膏贴敷于关元与子宫穴区","bullets":["艾灸对寒凝血瘀型痛经效果最佳","贴敷时间两小时以内，皮肤过敏者停用","经期与孕期腹部禁用贴敷与艾灸"]}]},{"type":"paragraph","text":"月经不调的饮食调养以养血调经、顺时调补为原则，并随证配餐。肾气虚与肾阴虚者宜补肾养血、忌生冷寒凉与耗伤肾精之品，可食山药、栗子、核桃、桑葚、枸杞、淡菜、乌骨鸡、黑芝麻、阿胶（脾胃虚弱者慎用）；肝郁者宜疏肝理气、忌辛辣燥烈与情志刺激，可饮玫瑰花茶、佛手陈皮茶、金桔饮，食佛手、香橼、玫瑰花、芹菜；脾虚者宜健脾益气、忌生冷油腻与过饥，可食山药粥、莲子百合粥、黄芪粥、薏仁红枣粥、瘦肉；阳盛血热者宜清热凉血、忌辛辣煎炸、烧烤、烈酒与温补，可食生地、莲藕、马齿苋、荸荠、绿豆；阴虚血热者宜滋阴清热、忌燥烈与温补，可用银耳百合羹、桑葚膏、麦冬、枸杞；血瘀者宜活血化瘀、忌寒凉凝滞，可食黑木耳、山楂、桃仁、玫瑰花。日常须注意经期前后加强营养，保证优质蛋白、铁与维生素的摄入；经期忌生冷寒凉、浓茶咖啡、酒精与剧烈运动，宜保暖、充分休息；经量多者注意补充含铁食物并监测血红蛋白。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：保持规律作息，保证每日七至八小时睡眠，避免熬夜，长期熬夜耗伤肾精与冲任；经期与经后注意保暖，尤其腰腹与足部，避免冷水洗浴与受凉；调节情志是本病调养的关键，肝郁者尤须避免长期紧张、焦虑与生气，可练习深呼吸、瑜伽、太极与八段锦，必要时寻求心理支持；保证居室通风与睡眠环境安静；经期避免久坐与憋尿。运动：经期可作散步、瑜伽、太极、八段锦等舒缓运动，避免剧烈跑跳、负重训练、游泳与桑拿；经后血块排出、痛经缓解后，可逐步进行慢跑、健身与力量训练以改善盆底与内分泌功能；规律运动有助缓解痛经与稳定周期。预防：青春期注重初潮后的经期卫生教育；避免反复人工流产与过度宫腔操作；控制体重与血糖；长期服用激素类药物须在医师指导下调整；婚后备孕一年以上未孕、或月经严重紊乱者应尽早就诊检查，不宜自行长期服用黄体酮或调经药；绝经期妇女异常出血须排查子宫内膜病变。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：月经周期短于二十一天或长于三十五天且持续三个月以上；经量超过平常一倍或每小时湿透一片卫生巾，持续两小时以上；经期延长至十天以上或非经期异常出血、性交后出血；痛经进行性加重、疼痛剧烈不能缓解、伴发热；绝经后任何阴道出血（须警惕子宫内膜癌）；月经骤停伴小腹胀痛（须排除宫外孕）；长期月经稀发伴多毛、痤疮、体重明显增加（须排查多囊卵巢综合征与甲状腺疾病）；月经过多伴头晕心悸、面色苍白（须排查贫血与凝血障碍）；青少年初潮后即月经稀发且伴发育异常。用药禁忌：不可自行长期服用黄体酮、雌激素或各类调经中成药，可能掩盖器质性病变并致体重增加、痤疮、血栓风险；活血化瘀类中成药（益母草膏、桃红四物汤等）孕妇禁用，月经过多者慎用；经期忌服用泻下药与强刺激药物；激素治疗须严格遵医嘱，不可自行停药；凝血功能异常、严重肝肾疾病者禁用活血药；青春期少女须由儿科或妇科专科医师评估后用药。"},{"type":"keypoints","title":"月经不调要点","items":["病机为冲任失调、胞宫藏泻失常，病位在胞宫，与肾、肝、脾密切相关","肾气虚用固阴煎、肝郁用逍遥散、脾虚用归脾汤、阳盛血热用清经散、阴虚血热用两地汤、气滞血瘀用血府逐瘀汤","经前重在疏肝理气与活血通经，经后重在补肾养血与调固冲任，顺周期调治效佳","情志因素在肝郁型中最重要，调畅情志常为治疗关键","周期短于二十一天、经量骤增、痛经剧痛、绝经后出血、少女月经稀发者必须就医"]}]},{"id":"tongjing","title":"痛经","subtitle":"痛经｜原发性痛经、继发性痛经","category":"妇科","tags":["痛经","寒凝血瘀","气滞血瘀","湿热瘀阻","益气养血"],"meta":[{"label":"中医病名/证型概要","value":"痛经。证型分气滞血瘀、寒凝血瘀、湿热瘀阻、气血虚弱、肾气亏损"},{"label":"主要症状","value":"经前或经期小腹疼痛、坠胀，腰骶酸痛，疼痛可放射至大腿内侧与腰骶部，拒按或喜按，伴恶心、头痛、乏力"},{"label":"舌脉要点","value":"气滞舌暗红苔薄白脉弦；寒凝舌暗苔白润脉沉紧；湿热舌红苔黄腻脉滑数；虚弱舌淡苔薄脉细弱"},{"label":"治则","value":"经期以通为主，重在行气活血化瘀止痛；经后以补为主，重在补肾益气养血"}],"image":"","imageHint":"痛经","summary":"痛经以经前或经期小腹疼痛、坠胀为主要表现，疼痛可放射至腰骶与大腿内侧，是妇科最常见病症。原发性痛经无盆腔器质性病变，与前列腺素分泌失衡、子宫过度收缩及精神心理因素有关；继发性痛经多由子宫内膜异位症、子宫腺肌症、子宫肌瘤、盆腔炎等引起，疼痛进行性加重。辨证以「不荣则痛」与「不通则痛」为纲，气滞血瘀、寒凝血瘀、湿热瘀阻多属实，气血虚弱、肾气亏损多属虚。治疗经期重通、经后重补，并配合艾灸与暖宫疗法。","blocks":[{"type":"paragraph","text":"痛经的病位在胞宫与冲任，核心病机是气血运行不畅，不通则痛，或胞宫失养、不荣则痛。实者多因瘀血阻滞：气滞血瘀者素性抑郁、恼怒不遂，肝气郁结、气机不畅则血行受阻，经血下泄不畅而痛，特点是小腹胀痛、痛无定处、拒按，经前乳胀、胁胀，经后痛减，血块排出则痛减；寒凝血瘀者素体阳虚，或经期冒雨涉水、饮食生冷，寒邪客于胞宫，血行凝滞而痛，特点是疼痛剧烈、得温则减、遇寒加重、喜按喜暖、色暗有块；湿热瘀阻者下焦湿热蕴结，与经血相搏而痛，特点是痛处灼热、拒按、连绵不休，伴发热、口渴、便秘或黏滞、带下黄臭。虚者多因胞宫失养：气血虚弱者素体不足或失血过多，气血不能荣养胞宫，经后或经期小腹隐痛、喜按、量少色淡、面色苍白、神疲乏力；肾气亏损者房劳多产、久病伤肾，肾精不足、胞宫失于温养，冲任气血运行不畅而痛，特点为经期或经后绵绵作痛、连腰骶部、量少色淡暗、头晕耳鸣、腰膝酸软。病机演变上，实证日久可伤正转虚，虚证兼寒凝则成虚实夹杂；治疗上须把握经前经期与经后的不同阶段，方能标本兼顾、持久取效。"},{"type":"table","caption":"痛经辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["气滞血瘀证","经前或经期小腹胀痛，疼痛较剧，痛无定处，拒按，经行量少色紫暗有块，块下痛减，胸胁乳房胀痛，舌紫暗，脉弦涩","行气活血，化瘀止痛","膈下逐瘀汤","气滞甚加香附、乌药、柴胡；痛剧加延胡索、五灵脂；乳胀加橘核、王不留行"],["寒凝血瘀证","经期小腹冷痛，得热痛减，遇寒加重，喜温喜按，经量少色暗有块，畏寒肢冷，舌暗苔白，脉沉紧","温经散寒，化瘀止痛","温经汤","寒甚加吴茱萸、小茴香、艾叶；痛剧加制川乌、白芍；气滞加香附、乌药"],["湿热瘀阻证","经前或经期小腹疼痛，拒按，有灼热感，疼痛连绵，量多或少，色紫暗有块，低热起伏，口渴不欲饮，大便黏滞，小便短黄，舌红苔黄腻，脉滑数","清热除湿，活血止痛","清热调血汤","热甚加黄连、栀子、败酱草；痛甚加延胡索、蒲黄；带下黄臭加土茯苓、败酱草"],["气血虚弱证","经期或经后小腹隐痛，喜按或以手捂之，经量少色淡质稀，面色苍白，神疲乏力，头晕心悸，舌淡苔薄白，脉细弱","益气养血，调经止痛","圣愈汤","气虚加黄芪、白术；血虚加熟地、阿胶；痛甚加白芍、甘草、延胡索"],["肾气亏损证","经期或经后小腹绵绵作痛，牵引腰骶部，量少色淡暗，头晕耳鸣，腰膝酸软，畏寒肢冷，小便频数，舌淡苔薄，脉沉细","补肾益精，养血止痛","益肾调经汤","肾阳虚加菟丝子、巴戟天、鹿角霜；腰酸甚加杜仲、桑寄生；痛甚加川断、延胡索"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴三阴交、中极、次髎、地机、十七椎；气滞血瘀加太冲、膈俞，寒凝加关元、命门、湿热加阴陵泉、大赫，气血虚加足三里、气海，肾虚加肾俞、太溪","bullets":["经前一周开始针刺，连治三至五个经期为一疗程","次髎、十七椎为经验止痛要穴，虚证可加灸","实证用泻法、虚证用补法，留针二十至三十分钟"]},{"icon":"🤲","title":"推拿按摩","text":"腹部推拿取关元、中极、子宫、归来，掌摩小腹与腰骶部；腰骶部重点按揉十七椎、次髎、肾俞；下肢按揉三阴交、地机、血海、太冲","bullets":["经前每日按摩一次，每次二十分钟，手法宜渗透温热","以温通为法，配合热敷效果更佳","按摩配合缓慢深呼吸与腹式呼吸有助放松"]},{"icon":"🔥","title":"艾灸与热敷","text":"艾灸关元、命门、三阴交、气海，每穴十五至二十分钟，痛经发作期可即灸；可用粗盐或艾叶炒热装入布袋敷于小腹与腰骶部，每次二十分钟","bullets":["寒凝血瘀型艾灸效果最为显著","经期与孕期腹部施灸须谨慎，孕期禁灸","热敷温度以舒适不烫为度，防低温烫伤"]}]},{"type":"paragraph","text":"痛经的饮食调养以温通、养血、避免寒凝为原则。气滞血瘀者宜疏肝理气、活血化瘀，忌滋腻壅滞与寒凉凝滞之品，可饮玫瑰花茶、佛手陈皮茶、桃仁红花饮，食黑木耳、山楂、玫瑰花；寒凝血瘀者宜温经散寒、忌一切生冷冰饮、刺身与冷拌菜，可饮姜糖红枣茶、艾叶红糖水、当归生姜羊肉汤，食桂圆、核桃、红糖、生姜、羊肉、小茴香；湿热瘀阻者宜清热除湿、忌辛辣酒类与油腻煎炸，可食冬瓜、丝瓜、绿豆、土茯苓、薏仁、马齿苋；气血虚弱者宜益气养血、忌生冷与过饥，可食山药粥、黄芪粥、莲子百合粥、桂圆红枣、瘦肉、乌骨鸡、黑芝麻、阿胶；肾气亏损者宜补肾益精、忌过度耗伤，可食核桃、栗子、桑葚、黑芝麻、枸杞、淡菜、鹌鹑蛋、黑豆。日常须注意经期前后加强营养，保证铁与蛋白质摄入；经期忌生冷、浓茶、咖啡、酒精与剧烈运动，宜保暖、充分休息；经期不宜节食减肥；喝红糖姜茶只作辅助，不能替代对器质性病变的治疗。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：经期与经前一周注意保暖，尤其腰腹、下肢与足部，忌冷水洗浴、洗头后未干即出门、露脐与赤足；保证每日七小时以上睡眠，避免熬夜与过度劳累；经期以卧床休息为主，避免久坐与长时间站立；调节情志、避免紧张焦虑，因精神紧张会加重痛经，疼痛时可用深呼吸、缓慢腹式呼吸与放松训练；睡前一至两小时避免刺激性饮食与情绪激动。运动：经期避免剧烈运动与长时间站立，可作散步、瑜伽、太极、八段锦等舒缓活动；经痛缓解后逐步恢复慢跑、游泳、瑜伽与核心训练；规律有氧运动与核心肌力训练可改善盆腔血液循环、减轻痛经；但有明显盆器脱垂或严重痛经者须遵医嘱；继发性痛经者应在原发病治疗基础上进行适度运动。预防：避免经期受寒与游泳；规律作息与均衡饮食；青少年注意经期卫生与营养；反复严重痛经者须行妇科超声、CA125等检查排除子宫内膜异位症、腺肌症与盆腔炎；有家族遗传倾向者提前评估；经期避免不必要的宫腔操作。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：痛经程度剧烈、进行性加重、止痛药无效而影响正常学习工作生活；疼痛放射至大腿内侧或伴性交痛（同房痛）、慢性盆腔坠痛（子宫内膜异位症与腺肌症线索）；经期或非经期剧烈下腹痛伴发热、脓性带下、宫颈举痛（盆腔炎）；绝经后阴道流血伴下腹痛；痛经同时出现少尿、浮肿、血尿、腰痛（泌尿系或肾结石）；突然剧烈腹痛伴面色苍白、头晕、心悸、血压下降（须排除异位妊娠、卵巢囊肿蒂扭转）；青春期少女原发性痛经进行性加重或伴发热。 用药禁忌：非甾体抗炎药（布洛芬、双氯芬酸）于疼痛开始时提前服用效果最佳，胃溃疡、哮喘、肾功能不全、孕期者禁用；口服避孕药须由医师评估后使用，35岁以上吸烟者、高血压、血栓史者慎用；中药活血化瘀类（桃红四物汤、膈下逐瘀汤、少腹逐瘀汤等）孕妇禁用，服抗凝药者慎用，月经过多者不适用；吗啡类强效镇痛药不可自行使用；滥用止痛药可掩盖病情并致药物依赖性头痛与胃肠损伤。"},{"type":"keypoints","title":"痛经要点","items":["病机核心是不通则痛与不荣则痛，实证多瘀、虚证多虚","气滞血瘀用膈下逐瘀汤、寒凝血瘀用温经汤、湿热瘀阻用清热调血汤、气血虚弱用圣愈汤、肾气亏损用益肾调经汤","辨证抓手：胀痛拒按属气滞，剧痛得温减属寒凝，灼痛属湿热，隐痛喜按属虚，绵绵作痛牵腰属肾虚","经期重通、经后重补，针刺与艾灸宜从经前一周开始，连续三至五个周期","进行性加重的痛经、同房痛、发热与脓性带下须及时排查器质性病变"]}]},{"id":"gengnianqi","title":"更年期综合征","subtitle":"更年期综合征｜围绝经期综合征、绝经前后诸证","category":"妇科","tags":["围绝经期","肾虚","阴虚火旺","心脾两虚","潮热盗汗"],"meta":[{"label":"中医病名/证型概要","value":"绝经前后诸证。证型分肾阴虚、肾阳虚、肾阴阳俱虚、心肾不交、心脾两虚、肝郁气滞"},{"label":"主要症状","value":"月经紊乱或绝经，烘热汗出、潮热面赤、烦躁易怒、失眠心悸、腰膝酸软、情绪波动、注意力下降"},{"label":"舌脉要点","value":"肾阴虚舌红少苔脉细数；肾阳虚舌淡胖苔白脉沉细；心脾两虚舌淡苔薄脉细弱；肝郁舌淡红苔薄脉弦"},{"label":"治则","value":"补肾调阴阳为主，兼养心、疏肝、化痰、活血，交通心肾，宁心安神"}],"image":"","imageHint":"更年","summary":"围绝经期综合征指妇女绝经前后因性激素波动而出现的一系列身心症状群，典型表现为月经紊乱、烘热汗出、潮热面赤、烦躁易怒、失眠心悸、腰膝酸软、情绪波动与注意力下降。中医认为其病机为肾气渐衰、天癸渐竭、冲任失调，肾阴不足则虚热内扰，肾阳衰微则虚寒内生，肾虚累及心脾可致心肾不交、心脾两虚，兼情志不遂则肝郁气滞。治疗以补肾调阴阳为纲，标本兼治，并重视心理疏导、运动调摄与生活方式的整体干预。","blocks":[{"type":"paragraph","text":"围绝经期诸证的病位在肾，涉及肝、心、脾。妇女七七之年，肾气渐衰、天癸渐竭、冲任虚损，这是本病的生理基础。肾阴不足，虚火内扰，迫津外泄，则见烘热汗出、潮热面赤、烦躁易怒、五心烦热、失眠多梦、口干咽燥、月经先期量少或经间期出血；肾阳渐衰，命门火衰，冲任虚寒，则见畏寒肢冷、腰膝酸软、精神萎靡、面色晦暗、月经后期量少色淡质稀、夜尿频数、无汗或汗少；肾阴肾阳俱虚，则寒热往来、烘热与畏寒并见，病情复杂；肾水不足不能上济心火、心火不能下交于肾，水火不济则心肾不交，心悸失眠、心烦多梦；肾虚日久，累及心脾，脾气虚则纳少便溏、倦怠乏力，心血不足则心悸失眠、面色萎黄，心脾两虚；情志不遂、忧思恼怒则肝气郁结，肝郁与肾虚相互影响，出现情绪波动、易怒、胸胁胀满、咽中如有物梗阻。此外，痰湿内生与瘀血内阻亦常与肾虚夹杂，形成肾虚痰瘀互结的复杂证候。临床须辨清阴阳偏颇与兼夹之证，不可一概以「肾虚」概治。"},{"type":"table","caption":"围绝经期综合征辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["肾阴虚证","绝经前后，月经紊乱，量少色红质稠，烘热汗出，潮热面赤，五心烦热，头晕耳鸣，腰膝酸软，失眠多梦，口干咽燥，舌红少苔，脉细数","滋养肾阴，潜阳清热","六味地黄丸加味","潮热加青蒿、地骨皮、鳖甲；盗汗加浮小麦、五味子；失眠加夜交藤、酸枣仁；血压高加天麻、钩藤"],["肾阳虚证","绝经前后，月经紊乱，量多色淡质稀，面色晦暗，腰膝酸软，畏寒肢冷，精神萎靡，夜尿频多，纳少便溏，无汗或自汗，舌淡胖苔白，脉沉细无力","温肾扶阳，调补冲任","右归丸","寒甚加附子、肉桂、杜仲；浮肿加茯苓、泽泻；失眠加夜交藤、磁石；便溏加白术、山药"],["肾阴阳俱虚证","绝经前后诸症并见，烘热汗出与畏寒肢冷交替，月经紊乱或闭经，形体消瘦，神疲乏力，舌淡苔薄，脉沉细","阴阳双补，调和冲任","二仙汤合二至丸","潮热加浮小麦、青蒿；畏寒加仙茅、巴戟天；失眠加合欢皮、夜交藤"],["心肾不交证","绝经前后心烦不寐，入睡困难，心悸多梦，头晕耳鸣，腰膝酸软，潮热盗汗，五心烦热，咽干少津，舌红少苔，脉细数","滋阴降火，交通心肾","六味地黄丸合交泰丸","心烦加黄连、肉桂；盗汗加五味子、浮小麦；心悸加珍珠母、龙齿"],["心脾两虚、肝郁气滞证","心脾两虚者心悸怔忡、失眠健忘、面色萎黄、神疲乏力、纳少便溏、舌淡苔薄、脉细弱；肝郁气滞者情绪抑郁、烦躁易怒、胸胁胀满、乳房胀痛、咽中如有物梗阻、舌淡红苔薄白、脉弦","心脾两虚者补益心脾、养血安神，肝郁气滞者疏肝解郁、理气调中","心脾两虚用归脾汤，肝郁气滞用逍遥散","气虚加黄芪、党参；血虚加熟地、白芍；失眠加夜交藤、合欢皮；乳胀加橘核、郁金、王不留行"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴百会、关元、气海、三阴交、太溪、神门、照海；阴虚加复溜、阴谷，阳虚加命门、肾俞，心肾不交加通里、少府，肝郁加太冲、期门，失眠加安眠、四神聪","bullets":["虚证用补法，阴虚者可配太溪、三阴交滋阴而不滋腻","针刺与艾灸结合更适合围绝经期调养","每周二至三次，十次为一疗程，疗程间休息数日"]},{"icon":"🤲","title":"推拿按摩","text":"头部推拿取百会、印堂、太阳、风池以放松；颈肩揉拿风池、肩井以缓解紧张；胸腹分推膻中、期门、章门、关元；腰骶部按揉肾俞、次髎、命门；足底涌泉按揉","bullets":["每周二至三次，每次二十分钟，配合呼吸放松","腹部与腰骶部手法宜温通轻柔","配合冥想与渐进式肌肉放松效果更佳"]},{"icon":"🩺","title":"耳穴与生活方式干预","text":"耳穴贴压取内分泌、卵巢、肾、肝、心、皮质下、神门，每次单耳三至五日；配合规律有氧运动、太极、八段锦与团体活动，每周累计一百五十分钟中等强度运动","bullets":["运动对改善潮热、睡眠与情绪效果确切","减少咖啡因、酒精与辛辣饮食以缓解潮热","必要时接受激素治疗或心理专科评估"]}]},{"type":"paragraph","text":"围绝经期的饮食调养以补肾、调和气血、平淡为要，并随证配餐。肾阴虚者宜滋阴补肾、忌辛辣燥烈与煎炸烧烤温补，可食银耳百合羹、桑葚膏、黑芝麻、百合、莲子、梨、蜂蜜、淡菜；肾阳虚者宜温补肾阳、忌生冷寒凉与冰饮，可食核桃、栗子、羊肉、桂圆、当归生姜羊肉汤、黑豆、杜仲炖猪腰；肾阴阳俱虚者宜平补阴阳，宜山药、莲子、枸杞、黑芝麻、核桃、百合、瘦肉、菌菇等平补之品；心肾不交者宜交通心肾、滋阴降火，忌温燥助火，可用莲子心、百合、麦冬、桂圆、酸枣仁；心脾两虚者宜补益心脾、忌生冷与过饥，可食山药粥、黄芪粥、莲子百合粥、龙眼肉、瘦肉、大枣；肝郁气滞者宜疏肝理气、忌辛辣刺激与情绪激动，可饮玫瑰花茶、佛手陈皮茶、金桔饮，食佛手、香橼、芹菜、佛手。日常须保证每日足量蛋白质、钙与维生素D摄入（牛奶、豆制品、深绿色蔬菜、坚果），限盐限油、少糖限酒，慎用浓茶、咖啡与碳酸饮料以减轻潮热与心悸；控制体重以减慢骨量流失；不吃所谓「回春」「补肾」保健品替代规范治疗。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：规律作息，保证每日七至八小时睡眠，固定就寝与起床时间，睡眠环境宜安静、遮光、凉爽；避免睡前浓茶、咖啡与长时间刷屏；潮热明显时穿着分层、宽松、透气衣物并备凉水与湿毛巾；保持居室通风与适宜温度；心理调适极为重要，家人应给予理解支持，避免轻视「小题大做」与强行否定症状；学习围绝经期相关知识以减少焦虑；工作与家务量力而行，避免长期透支。运动：规律有氧运动是改善潮热、睡眠、情绪与骨密度的关键，建议每周一百五十分钟中等强度（快走、慢跑、游泳、太极、八段锦）并配合每周两次抗阻训练以强骨；避免长时间静坐；户外日晒每日十五至二十分钟以补钙；跳跃与负重运动量力而行；坚持一年以上者骨密度与潮热频率均明显改善。预防：35岁后关注月经周期与经量变化并记录；围绝经期每年进行常规体检与妇科筛查、乳腺检查、宫颈癌筛查、骨密度检测；补钙与维生素D须遵医嘱；戒烟限酒、控制体重、保证蛋白与钙摄入；绝经后任何阴道出血都必须就诊，不可自行当作「更年期月经不调」处理。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：绝经后任何阴道出血、绝经后出血伴下腹疼痛或性交痛（须排查子宫内膜癌、宫颈癌与卵巢病变）；异常阴道分泌物增多有臭味、盆腔疼痛、发热（盆腔炎或肿瘤）；月经周期严重紊乱、经量骤增或淋漓不止、经期延长超过十天；严重失眠伴抑郁焦虑、兴趣丧失、有自伤念头（须心理危机干预）；阵发性心悸胸闷、气促、下肢水肿、晕厥（须排查心脏疾病）；骨质疏松所致身高变矮、腰背疼痛、易骨折，或长期大量饮用咖啡与浓茶并吸烟、饮酒、缺乏运动；潮热伴高热与消瘦、甲亢表现（心悸消瘦多汗）须查甲功。用药禁忌：激素替代治疗须由妇科医师评估获益与风险后个体化处方，有乳腺癌、子宫内膜癌、卵巢癌史者、静脉血栓史者、严重肝病者禁用或慎用，不可自行服用或长期使用「雌激素」保健品；替勃龙、利维隆等有特殊禁忌；中成药如更年安、坤宝丸、荣华丸等须辨证使用，不可与激素自行叠加；抗抑郁药、镇静药可与中医调理并存但须告知医师；围绝经期骨质疏松者须在专科评估后使用抗骨质疏松药与钙剂；不建议自行长期服用大剂量钙剂或维生素D。"},{"type":"keypoints","title":"更年期综合征要点","items":["病机为肾气渐衰、天癸渐竭、冲任失调，肾阴虚用六味地黄丸、肾阳虚用右归丸、阴阳俱虚用二仙汤合二至丸","心肾不交通六味地黄丸合交泰丸，心脾两虚用归脾汤，肝郁气滞用逍遥散","烘热汗出、潮热面赤、五心烦热属阴虚；畏寒肢冷、无汗、夜尿频属阳虚；两者并见为阴阳俱虚","心理疏导与运动调摄是治疗的重要组成，规律有氧运动对潮热与睡眠改善确切","绝经后出血、严重抑郁、自伤念头、原因不明的消瘦须立即就医"]}]},{"id":"daixiabing","title":"带下病","subtitle":"带下病｜阴道炎、宫颈炎、盆腔炎","category":"妇科","tags":["带下病","脾虚湿盛","湿热下注","阴虚夹湿","带下异常"],"meta":[{"label":"中医病名/证型概要","value":"带下病。证型分脾虚、肾阳虚、阴虚夹湿、湿热下注、湿毒蕴结"},{"label":"主要症状","value":"带下量明显增多、质色气味异常，或伴外阴瘙痒、灼热、疼痛、接触性出血"},{"label":"舌脉要点","value":"脾虚舌淡胖苔白腻脉缓弱；肾阳虚舌淡苔白脉沉迟；湿热舌红苔黄腻脉滑数；阴虚舌红少苔脉细数"},{"label":"治则","value":"健脾升清除湿为主，兼温肾、清热利湿、滋阴清热，内外合治"}],"image":"","imageHint":"带下","summary":"带下病以带下量明显增多、色质气味异常，或伴外阴瘙痒灼热为主要表现。带下为阴中少量黏液津津常润，若量多质稀如水或黏稠如凝膏、气味腥臭、外阴瘙痒者，即为带下病。病位在胞宫与带脉，与肝脾肾关系密切。脾虚运化失健、湿浊下注为最常见病机；肾阳虚则封藏失职、冲任不固；湿热下注则带黄稠臭；湿毒蕴结则带如脓血、伴灼痛；阴虚夹湿则带少而黏、灼热干涩。治疗须辨清寒热虚实，局部外治与整体内调并重。","blocks":[{"type":"paragraph","text":"带下病的病位在胞宫与带脉。正常带下是胞中有津液濡润的生理表现，量少、色白或淡黄、质稀无臭。带下病的核心病机是脾虚失运、湿浊下注，或肾气不固、封藏失职而带脉失约。饮食劳倦、忧思伤脾，脾虚运化失健，水湿内停，湿浊下注胞宫，故带下量多、色白或淡黄、质稀无臭、绵绵不断，伴纳少便溏、面色萎黄、四肢乏力；素体肾阳不足，或房劳多产、年老肾亏，肾气不固、任带失约，故带下量多、质稀清冷、终日淋漓、腰酸腹冷、小便清长、夜尿频多；湿热之邪下注胞宫，与经血浊液相搏，故带下量多、色黄或黄绿、质黏稠、气味腥臭、外阴瘙痒灼热，伴口苦咽干、尿赤便秘；如湿热郁久化毒，则带下如脓或夹血、量多臭秽、外阴肿痛、发热；阴虚而夹湿者，多见于久病、绝经前后，带下量少而色黄或赤白相兼、质黏稠、外阴干涩灼热，伴面部潮红、五心烦热、舌红少苔。此外，带下日久可损伤阴血、导致腰腹疼痛与不孕，亦可因久病不治而继发宫颈与盆腔病变。故治疗须兼顾内调与外治，并及时排除感染性因素与器质性病变。"},{"type":"table","caption":"带下病辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["脾虚证","带下量多，色白或淡黄，质稀无臭，绵绵不断，面色萎黄，倦怠乏力，纳少便溏，舌淡胖苔白腻，脉缓弱","健脾益气，升阳除湿","完带汤","带多加芡实、莲子、薏苡仁；气虚加黄芪、党参；纳差加焦三仙；腰酸加杜仲、桑寄生"],["肾阳虚证","带下量多，色白质稀，清冷无臭，淋漓不断，腰酸腹冷，小便清长，夜尿频多，面色晦暗，舌淡苔白，脉沉迟","温肾培元，固涩止带","内补丸","寒甚加附子、肉桂；腰酸加菟丝子、桑寄生；带多加芡实、金樱子、乌贼骨"],["阴虚夹湿证","带下量少，色黄或赤白相兼，质黏稠，外阴干涩灼热，面部潮红，五心烦热，口咽干燥，舌红少苔，脉细数","滋阴清热，除湿止带","知柏地黄丸加味","湿重加土茯苓、薏苡仁、黄柏；灼热加苦参、土槿皮；潮热加地骨皮、青蒿"],["湿热下注证","带下量多，色黄或黄绿，质黏稠，气味腥臭，外阴瘙痒灼热，小便短赤涩痛，口苦咽干，大便黏滞，舌红苔黄腻，脉滑数","清热利湿，止带","易黄汤","热甚加黄连、栀子、败酱草；痒甚加苦参、地肤子、蛇床子；带多加土茯苓、椿根皮"],["湿毒蕴结证","带下量多如脓或夹血，色黄绿或褐，气味腥臭，外阴肿痛瘙痒，发热，小腹疼痛，口苦，舌红苔黄腻，脉滑数","清热解毒，除湿止带","五味消毒饮合完带汤","热毒盛加白花蛇舌草、蒲公英、紫花地丁；带多加椿根皮、土茯苓；腹痛加延胡索、川楝子"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴带脉、关元、中极、次髎、阴陵泉、三阴交；脾虚加脾俞、足三里，肾阳虚加肾俞、命门，湿热加行间、曲池，阴虚加太溪、然谷，湿毒加血海、膈俞","bullets":["带脉、关元、中极为调经止带要穴","实证用泻法、虚证用补法并可加灸，留针二十至三十分钟","针刺配合外阴冲洗与栓剂效果更佳"]},{"icon":"🌿","title":"外治与坐浴","text":"中药坐浴可用苦参、蛇床子、地肤子、黄柏、蒲公英、白鲜皮煎汤熏洗外阴，每次二十分钟；或用苦参栓、妇炎平栓、硝呋呋唑类阴道栓剂按说明使用","bullets":["坐浴水温不宜过高，以不烫为度，经期与孕期慎用","禁止阴道冲洗以免破坏微生态与上行感染","外用药须遵医嘱，孕期与哺乳期由医师决定"]},{"icon":"🤲","title":"推拿按摩","text":"腹部推拿取关元、中极、归来、气海，掌摩小腹与腰骶部；腰骶部按揉肾俞、次髎、十七椎；下肢按揉三阴交、阴陵泉、足三里、太溪","bullets":["每日一次，每次二十分钟，手法宜轻柔和缓","配合臀桥与骨盆倾斜训练改善盆底肌功能","治疗期间禁止盆浴与性生活"]}]},{"type":"paragraph","text":"带下病的饮食调养以健脾除湿、清热利湿为原则，并随证配餐。脾虚者宜健脾益气、忌生冷寒凉与油腻甜腻，可食山药粥、莲子粥、白扁豆粥、薏仁山药粥、茯苓、莲子、芡实、瘦肉；肾阳虚者宜温补肾阳、忌寒凉生冷，可食核桃、栗子、羊肉、桂圆、当归生姜羊肉汤、杜仲炖腰子；阴虚夹湿者宜滋阴清热兼除湿、忌辛辣燥烈与温补，可食银耳百合羹、百合莲子粥、桑羹、百合莲子粥、桑葚膏、山药、薏苡仁；湿热下注者宜清淡利湿、忌辛辣酒类、肥甘厚味与煎炸，可食冬瓜、丝瓜、绿豆、土茯苓、马齿苋、薏仁；湿毒蕴结者宜清淡解毒、忌温补与酒类，可食绿豆瓣芽、蒲公英、马齿苋、丝瓜。日常须注意治疗期间清淡饮食、少食多餐、避免生冷油腻与辛辣刺激，保证充足饮水；保持外阴清洁干燥、每日更换棉质内裤并充分晾晒；经期与产后注意会阴清洁，避免盆浴；治疗期间禁止性生活；注意营养与休息，避免过劳与熬夜。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：注意个人卫生，每日用温水清洗外阴，专人专用毛巾与脸盆，内裤与护垫每日更换并消毒晾晒；避免不洁性行为，伴侣同治；避免使用碱性洗液与沐浴露清洗外阴以免破坏微生态；避免久坐与长时间穿紧身不透气裤装，多站立走动；经期与产褥期禁止盆浴与性生活；保证充足睡眠，避免熬夜与过度劳累；注意经期与产后营养。运动：病情稳定期可进行散步、慢跑、瑜伽、太极、八段锦与凯格尔盆底肌训练（每日三次、每次十次收缩与放松），有助于改善盆底肌功能与减少带下异常复发；急性炎症期宜休息，避免性生活与盆浴；避免久坐与骑行压迫会阴。预防：定期妇科体检与宫颈癌筛查（HPV与TCT）；发现带下异常、瘙痒、异味应尽早就诊而非自行用药；避免过度阴道冲洗与滥用抗生素导致菌群失调；妊娠期与产褥期特别重视会阴护理；反复发作者须筛查糖尿病与免疫功能低下；带下病久治不愈者须排除宫颈癌、内膜癌与盆腔炎性包块。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：带下量突然显著增多、色黄绿或脓性、有明显腥臭味；伴外阴剧烈瘙痒、灼痛、肿胀或皮肤破损；伴发热、下腹压痛、拒按；绝经后出现带下增多或血性分泌物；伴性交痛、下腹坠痛与发热；治疗一周以上症状无改善或反复发作；伴外阴溃疡、白斑、增厚或色素改变（须排除外阴白斑、硬化性苔藓与恶性病变）；出现腰痛、发热、尿频尿痛（上行感染累及肾脏）。用药禁忌：擅自使用广谱抗生素可致菌群失调与真菌性阴道炎加重；禁止使用碱性洗剂、消毒液、香皂洗外阴；禁止孕期自行使用栓剂与洗液，孕期用药须遵医嘱；抗真菌药与雌激素类阴道制剂须按疗程使用，症状消失即停药易致复发；甲硝唑类可与酒精产生双硫仑样反应，用药期间及停药一周内严禁饮酒；孕妇与哺乳期禁用甲硝唑口服与某些栓剂；未绝经女性不宜长期使用雌激素类阴道制剂；中药坐浴方含有毒药物（如苦参用量过大）者须医师指导，避免黏膜灼伤。"},{"type":"keypoints","title":"带下病要点","items":["带下量多质稀色白属脾虚湿盛（完带汤），色黄稠臭属湿热下注（易黄汤），清冷稀薄属肾阳虚（内补丸），量少黏稠伴潮热属阴虚夹湿（知柏地黄丸加味）","如脓夹血伴灼痛发热者属湿毒蕴结（五味消毒饮合完带汤），须及时就医","治疗须内调与外治并重，中药坐浴配合针刺可提高疗效，但禁止阴道冲洗","带下异常须先排除滴虫性、霉菌性、细菌性阴道炎与宫颈病变，不宜盲目自行用药","反复发作者须筛查糖尿病、免疫功能异常与盆腔器质性病变"]}]},{"id":"xiaoeryanshi","title":"小儿厌食","subtitle":"小儿厌食｜小儿食欲不振、疳积初起","category":"儿科","tags":["小儿疳积","脾胃虚弱","脾失健运","喂养不当","食欲不振"],"meta":[{"label":"中医病名/证型概要","value":"厌食、疳积。证型分脾失健运、脾胃气虚、脾胃阴虚、脾虚夹积（疳积）"},{"label":"主要症状","value":"长期食欲不振或食欲减退、见面拒食、形体偏瘦、面色少华，或伴腹胀、大便不调、烦躁夜啼"},{"label":"舌脉要点","value":"脾失健运苔薄白或薄腻指纹淡；脾虚夹积苔厚腻指纹紫滞；脾胃阴虚舌红少苔指纹淡紫"},{"label":"治则","value":"运脾和胃为基本法，兼健脾益气、滋养胃阴、消积理脾，消补兼施"}],"image":"","imageHint":"厌食","summary":"小儿厌食是指小儿长期食欲不振或食欲减退为主要表现的儿科常见病，以脾胃功能失调、运化失健为基本病机，尤以学龄前与学龄期儿童多见。病因主要有喂养不当（喂养过度、滋补过甚、进食不定时、边吃边玩）、脾胃虚弱、禀赋不足与久病伤脾。辨证以脾虚为本、积滞为标，常见脾失健运、脾胃气虚、脾胃阴虚与脾虚夹积四型。治疗以运脾和胃为纲，强调调理喂养与纠正不良习惯，避免长期使用助消化药物或过度补充营养品。","blocks":[{"type":"paragraph","text":"小儿厌食的病位在脾胃，与心、肝、肾及大小肠相关。小儿脾常不足，脾为阴土、喜燥恶湿，胃为阳土、喜润恶恶降，其生理特点决定了小儿运化功能易受饮食影响而紊乱。喂养不当是首要病因：喂养过度或滥服滋补之品，使脾胃壅滞不运，纳食不香；进食不定时、饥饱失常或边吃边玩、追逐嬉戏，扰乱脾胃的正常纳运节律；嗜食肥甘厚味与生冷之品，损伤脾胃运化；喂养中态度强硬斥责、强迫进食，使小儿脾胃气机紊乱、厌恶进食。禀赋不足、久病伤脾或病后失调则脾气虚弱，运化无力而食欲不振；脾虚日久，气血生化乏源，形体消瘦、面色少华、倦怠乏力，是为脾胃气虚；恣食燥热或久病热病之后，胃阴耗伤，脾胃失润而口干多饮、不喜进食、大便干结，是为脾胃阴虚；若脾虚而乳食停滞不化，积滞内停，脾气更受损伤，则见腹胀、嗳腐酸馊、大便酸臭或夹不消化食物、烦躁夜啼，是为脾虚夹积，是本病进一步发展的阶段。严重者可发展为疳积，出现形体极度消瘦、精神萎靡、烦躁不安、影响生长发育，须及时干预。"},{"type":"table","caption":"小儿厌食辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["脾失健运证","不思进食，见食不悦或见面拒食，形体尚可或略瘦，大便溏薄夹不消化食物，舌苔薄白或薄腻，指纹淡","调和脾胃，运脾开胃","不换金正气散","脘腹胀满加木香、枳壳；食积加神曲、麦芽；呕吐加半夏、生姜"],["脾胃气虚证","食欲不振，稍食即饱，面色少华或萎黄，形体偏瘦，倦怠乏力，大便溏薄，易感冒，舌淡胖苔薄白，指纹淡红","健脾益气，助运开胃","参苓白术散","气虚甚加黄芪、党参；便溏加莲子、扁豆、薏苡仁；厌食甚加鸡内金、焦三仙"],["脾胃阴虚证","食欲不振，不喜进食，口干多饮，皮肤失润，形瘦，大便干结，烦躁，手足心热，舌红少苔，指纹淡紫","滋养胃阴，健脾开胃","养阴益胃汤","口干甚加麦冬、石斛、沙参；便干加火麻仁、郁李仁；厌食加鸡内金、麦芽"],["脾虚夹积证","不思乳食，脘腹胀满，嗳腐酸馊，大便酸臭或溏薄夹不消化食物，烦躁不安，夜啼，形体略瘦，舌苔厚腻，指纹紫滞","健脾益气，消积理中","肥儿丸","积滞化热加黄连、胡黄连、连翘；腹胀加枳实、木香；夜啼加蝉蜕、钩藤"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴中脘、足三里、脾俞、胃俞、大椎、四缝；脾失健运加内庭、公孙，脾胃气虚加百会、气海，脾虚夹积加天枢、大横、丰隆，阴虚加三阴交、太溪","bullets":["小儿针刺宜浅刺、快针、少留针，手法轻柔","四缝穴点刺挤出少量黄色黏液后以消毒棉签按压，是儿科疳积特色疗法","每周二至三次，十次为一疗程"]},{"icon":"🤲","title":"小儿推拿","text":"补脾经、揉板门、揉四横纹、捏脊、揉中脘、揉足三里、分腹阴阳、揉内庭；积滞者加推四横纹、清胃经、揉板门","bullets":["每日一次，每次十五至二十分钟，捏脊五至七遍","手法宜轻柔缓和，餐前二十分钟进行","配合摩腹与揉脐改善肠鸣腹胀"]},{"icon":"🌿","title":"穴位贴敷与捏脊","text":"可选用消积膏、鸡内金粉调敷脐部与中脘穴区，或用吴茱萸、肉桂、丁香研末醋调敷神阙；每日捏脊一次并以艾条温灸脾俞、胃俞","bullets":["贴敷时间二至四小时，皮肤过敏者停用","捏脊方向自下而上，力度以皮肤微红为度","厌食伴反复感冒者可加灸肺俞以补卫气"]}]},{"type":"paragraph","text":"小儿厌食的饮食调养以纠正喂养方式为先，药物与食疗为辅。脾失健运者宜健脾开胃、忌生冷油腻与厚腻滋补之品，可用山药粥、山楂麦芽粥、白扁豆粥、莲子粥、芡实薏米粥、少量陈皮水；脾胃气虚者宜健脾益气、忌生冷寒凉与过饥过饱，可用山药粥、黄芪粥、莲子百合粥、大枣小米粥、瘦肉、鸡肉、牛肉；脾胃阴虚者宜滋养胃阴、忌辛辣燥烈与温补，可食山药、百合、麦冬、石斛、粳米粥、莲藕、雪梨、苹果、鸭梨；脾虚夹积者宜消食导滞、忌肥甘甜腻与过量零食，可用焦山楂、神曲、麦芽煎汤、炒鸡内金、陈皮水、莱菔子粥。日常喂养要点：定时定量、每餐七八分饱，不追喂、不强迫、不以零食替代正餐；一日三餐两点心，零食选择奶类、水果、坚果少量；纠正边吃边玩、边看电视边吃饭的习惯；保证每日饮水与新鲜蔬果；避免长期服用多潘立酮、莫沙必利等促胃动力药与各类消化酶制剂；避免盲目补充锌剂、赖氨酸与保健品，缺锌须在医师指导下检测与补充。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：保证每日十至十二小时睡眠（学龄前十三小时左右），避免睡眠不足影响脾胃运化与生长激素分泌；固定三餐与作息时间，两餐间隔不少于三小时；保证每日户外活动与日晒；注意保暖，避免受凉感冒而加重食欲不振；家中不存放过多零食饮料；父母不因孩子拒食而责骂、恐吓或以食物作为奖励与惩罚，避免形成进食焦虑。运动：每日保证两小时以上活动量，以跑跳、球类、游泳、骑行车等为佳，餐前不要剧烈运动，餐后休息半小时再活动；厌食日久伴形体消瘦者，运动量宜循序渐进，避免空腹剧烈运动。预防：树立正确喂养观念，母乳喂养儿按需哺乳，添加辅食遵循由稀到稠、由细到粗、由少到多、一次一种的原则；避免长期大补或滥用保健品；小儿在发热、感冒、腹泻等疾病期间食欲下降属正常现象，不宜强行进食，宜在疾病康复后逐步恢复正常饮食；定期监测身高体重与生长曲线，发现偏离及时干预。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：厌食持续超过一个月以上、体重不增或下降、身高增长停滞；面色苍白、乏力、头晕、活动后心悸气促（须排查贫血）；反复口腔溃疡、皮下出血点、频繁感染（须排查血液系统疾病与免疫缺陷）；伴多饮多尿、体重下降明显（须排查糖尿病）；腹胀、腹痛、呕吐、大便带血或黏液、腹部包块（须排查肠道器质性疾病）；伴精神萎靡或烦躁不安、发育落后、智力发育迟缓（须排查内分泌、染色体与代谢病）；严重消瘦、精神萎靡、眼眶凹陷、皮肤弹性差伴脱水（须警惕严重营养不良与疳积重症）；长期拒食伴心悸、乏力、电解质紊乱表现。用药禁忌：不可长期使用多潘立酮、莫沙必利、西甲替丁等促胃动力与抑酸药，可能掩盖器质性病变并有不良反应；锌剂须经血清锌检测确认缺乏后按医嘱使用，过量可致铜缺乏与胃肠道刺激；不宜滥用开胃中成药与保健品；乳酶生、健胃消食片等亦须辨证短期使用；严禁给小儿服用成人剂量药物或自行使用抗生素与激素；脾胃虚寒者忌用苦寒清胃之品如黄连、栀子、大黄长期给药；拒绝服用药物时宜改用食疗与推拿，切勿强行灌药以免呛咳误吸。"},{"type":"keypoints","title":"小儿厌食要点","items":["病机为脾胃运化失健，脾虚为本、积滞为标，喂养不当是首要病因","脾失健运用不换金正气散、脾胃气虚用参苓白术散、脾胃阴虚用养阴益胃汤、脾虚夹积用肥儿丸","纠正喂养方式是治疗第一要素：定时定量、不追喂、不强迫、不以零食代正餐","厌食伴体重下降、贫血、精神萎靡、发育落后者必须就医排查器质性疾病","不可长期使用促胃动力药与补充品，锌剂须检测后使用"]}]},{"id":"xiaoerjizhi","title":"小儿积滞","subtitle":"小儿积滞｜小儿消化不良、食积、奶积","category":"儿科","tags":["乳食积滞","小儿推拿","消食导滞","胃热消积","脾虚夹积"],"meta":[{"label":"中医病名/证型概要","value":"积滞、疳积。证型分乳食内积、脾虚夹积、胃热消积（食积化热）"},{"label":"主要症状","value":"不思乳食、脘腹胀满、嗳腐酸馊、大便酸臭或不消化食物、夜啼、烦躁，可见手心发热"},{"label":"舌脉要点","value":"乳食内积苔厚腻指纹紫滞；胃热消积舌红苔黄腻指纹紫；脾虚夹积舌淡苔白腻指纹淡滞"},{"label":"治则","value":"消食导滞、理气和中为标，健脾益气为本，消补兼施、运脾和胃"}],"image":"","imageHint":"积滞","summary":"小儿积滞是乳食停积于中焦、脾胃运化失常所致的儿科常见病，以不思乳食、脘腹胀满、嗳腐酸馊、大便酸臭或夹不消化食物为主要表现。乳食不节、喂养不当、脾胃虚弱、感邪发热与虫积均可致积。病机为乳食停滞、脾胃失运，积滞日久则损伤脾胃而转为疳积，故有「积滞不化可成疳」之说。辨证分乳食内积、脾虚夹积与胃热消积三型。治疗以消食导滞为主、健脾为辅，并配合小儿推拿与纠正喂养方法。","blocks":[{"type":"paragraph","text":"小儿积滞的病位在脾胃，病机为乳食停积、运化失司。小儿脾胃娇嫩，形气未充，乳食不知自节，故积滞为儿科多发病。病因有四：一是喂养不当，喂养过量、过早添加辅食、食物种类过多、进食不节而伤于脾胃；二是脾胃虚弱，先天禀赋不足或久病体虚，运化无力，稍有乳食即成积滞；三是外感六淫或饮食不洁，邪气犯胃、肠腑传导失常，宿食停滞化热；四是虫积，肠道虫积扰乱脾胃运化而致食欲异常、腹部不适。病机演变上，初期乳食内积，气机壅滞，脘腹胀满、嗳腐酸馊、大便酸臭，多属实；若积滞不化，郁而化热，则见口渴烦躁、口臭、便秘或黏滞、舌红苔黄腻，为食积化热（胃热消积）；若脾胃素弱，积滞日久，积必伤脾，脾虚则运化更无力，形成脾虚夹积之虚实夹杂证，可见形体略瘦、面色萎黄、大便溏薄夹不消化食物、指纹淡滞。《幼科直言》谓「积滞不化，可成疳证」，故积滞须及时治疗，切勿任其发展。"},{"type":"table","caption":"小儿积滞辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["乳食内积证","不思乳食，脘腹胀满，嗳腐酸馊，大便酸臭或含不消化食物，烦躁不安，夜啼，手足心热，舌苔厚腻，指纹紫滞","消食导滞，理气和中","保和丸","食积化热加黄连、连翘；腹胀加枳实、木香、厚朴；呕吐加半夏、生姜；便臭加鸡内金、莱菔子"],["脾虚夹积证","不思乳食，形体偏瘦，面色少华，脘腹胀满，大便夹有不消化食物，倦怠乏力，纳少，舌淡胖苔白腻，指纹淡滞","健脾益气，消积理中","健脾丸","气虚甚加黄芪、党参、白术；积重加神曲、麦芽、莱菔子；便溏加山药、莲子、扁豆"],["胃热消积证","不思乳食，脘腹胀满，口渴喜饮，口臭烦躁，大便秘结或黏滞不爽，小便短赤，舌红苔黄腻，指纹紫","清热消积，导滞和中","肥儿丸","热甚加黄连、栀子、连翘；便秘加大黄、玄参；腹胀加枳实、木香"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴中脘、足三里、天枢、大横、四缝、内庭、公孙；乳食内积加神阙、璇玑，胃热加曲池、合谷，脾虚加脾俞、胃俞、章门","bullets":["小儿浅刺快针，不留针或少留针，手法轻柔","四缝穴点刺是治疗小儿积滞的特色操作","隔日一次，十次为一疗程"]},{"icon":"🤲","title":"小儿推拿","text":"揉板门、清胃经、补脾经、揉四横纹、揉中脘、分腹阴阳、揉天枢、揉足三里、捏脊、推八道","bullets":["清胃经与揉板门为消积主手法，每日二次","捏脊五至七遍以健脾助运","腹胀明显者可配合摩腹与揉脐"]},{"icon":"🔥","title":"艾灸与穴位贴敷","text":"艾灸中脘、足三里、脾俞、神阙，每穴十分钟；可用焦三仙、莱菔子、鸡内金等研末醋调或以消积膏贴敷中脘、脐部","bullets":["艾灸宜用温和悬灸，防烫伤小儿皮肤","贴敷时间二至四小时，注意观察皮肤反应","积滞化热者不宜热敷与艾灸"]}]},{"type":"paragraph","text":"小儿积滞的饮食调养以调换饮食结构、控制食量为先，积滞未消时尤忌进食。乳食内积者宜消食导滞、忌油腻厚味与甜腻零食，可用焦山楂、神曲、麦芽、莱菔子各等分煎汤代水饮用，山楂麦芽粥、鸡内金粉（每次一至二克，小儿用量宜小）、白萝卜汤；脾虚夹积者宜健脾消积、忌生冷寒凉与不消化食物，可用山药粥、莲子粥、白扁豆粥、茯苓薏米粥、瘦肉泥、蒸南瓜；胃热消积者宜清热消积、忌辛辣煎炸、炸鸡与含糖饮料，可用冬瓜、丝瓜、绿豆汤、绿豆百合粥、芦根竹蔗水、梨。日常喂养要点：发现食积立即减量，暂停零食与甜食；饮食由稀到稠、由少到多逐步恢复；不宜用开水冲调奶粉并立即喂哺，宜适当稀释；不强迫进食、不追喂、不边玩边吃；大便通畅有助于消积，可每日顺时针摩腹；食积发热者宜多饮温水，忌食生冷。切忌盲目补充益生菌、健胃消食片与大量水果泥，恐碍脾运化。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：保持充足睡眠，积滞期间让脾胃得到休息，夜间避免哭闹与饥饿过度；保证每日饮水与大便通畅；注意腹部保暖，避免受凉而加重腹泻与腹胀；居住环境与家庭氛围轻松，家长切勿因孩子不吃饭而责骂，避免形成进食焦虑与情志性厌食；发热期间记录体温与精神状态。运动：每日保证户外活动两小时，以散步、跑跳、球类为主；食积伴腹胀者可作摩腹、揉脐、揉足三里与八段锦中的调理手法，每日一至两次；积滞化热者可作八段锦摇头摆尾势以助气机通畅；不宜在餐后立即剧烈运动。预防：喂养做到量宜少、质宜软、次数宜少而定时；不给婴幼儿随意服用消食中成药与保健品；添加辅食遵循由稀到稠、由细到粗、由少到多、一次一种加至三天观察反应；母乳喂养按需哺乳，避免一哭即喂；预防接种与疾病期间食欲下降属正常，注意与积滞相鉴别；日常可作小儿推拿保健（揉板门、揉足三里、捏脊）以健脾助运。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：腹胀剧烈、持续哭闹拒按、呕吐频繁或呕吐物含胆汁或血；大便带血、呈果酱样或脓血样；高热不退、抽搐、精神萎靡或意识不清（须警惕热结旁流与严重感染）；脱水征象（眼眶凹陷、皮肤弹性差、尿量减少、口唇干燥）；腹部包块、肛门指检触及坚硬条索状物（须排查肠套叠）；腹胀不排气不排便、呕吐腹胀（须排查肠梗阻）；消瘦明显、体重不增、面色萎黄、精神萎靡（须警惕疳积）；发热伴皮疹、结膜充血、口唇皲裂（须警惕川崎病）；手足口病、疱疹性咽峡炎、轮状病毒与诺如病毒感染相关的呕吐腹泻。用药禁忌：不可自行给小儿服用泻下药（大黄、番泻叶、果导片）以免峻下伤脾、引起脱水与电解质紊乱；积滞化热者忌用温燥消导之品如干姜、附子、肉桂；长期使用多潘立酮、莫沙必利可致不良反应，须医师评估；抗生素仅在明确细菌感染时使用；服健胃消食片、保和丸等中成药须辨证且短期使用；小儿推拿与外治须在专业人员指导下进行，掐人中、拿风池等手法操作不当有风险；不擅自给小儿服用成人药物或剂量。"},{"type":"keypoints","title":"小儿积滞要点","items":["病机为乳食停积、脾胃失运，乳食内积用保和丸、胃热消积用肥儿丸、脾虚夹积用健脾丸","辨证抓手：腹胀嗳腐、大便酸臭为乳食内积；口渴口臭、便秘、舌红苔黄腻为胃热；形体略瘦、便溏、指纹淡为脾虚夹积","小儿推拿（揉板门、清胃经、揉四横纹、揉中脘、捏脊）是重要而安全的辅助疗法","积滞未消须先减量，忌盲目补充益生菌、消食片与大量水果泥","剧烈腹胀、呕吐胆汁、便血、高热抽搐、脱水、腹部包块者须立即就医"]}]},{"id":"xiaoerkesou","title":"小儿咳嗽","subtitle":"小儿咳嗽｜小儿急性支气管炎、肺炎后咳嗽","category":"儿科","tags":["小儿咳嗽","肺脾气虚","外感咳嗽","小儿推拿","痰"],"meta":[{"label":"中医病名/证型概要","value":"小儿咳嗽。证型分风寒袭肺、风热犯肺、痰热壅肺、阴虚肺热、肺脾气虚"},{"label":"主要症状","value":"咳嗽有声、痰多或少，兼见鼻塞流涕、发热、咽红、气促、纳差，或久咳少痰、面色少华、易出汗"},{"label":"舌脉要点","value":"风寒苔薄白指纹浮；风热舌红苔薄黄指纹浮紫；痰热苔黄腻指纹紫滞；肺脾气虚舌淡苔薄指纹淡"},{"label":"治则","value":"宣通肺气、化痰止咳为标，宣肺散邪与养阴健脾并重，忌苦寒、忌过用收涩"}],"image":"","imageHint":"儿咳","summary":"小儿咳嗽是儿童常见病，以咳嗽、咯痰为主要表现，可伴鼻塞、流涕、发热、咽红或气促。小儿脏腑娇嫩、形气未充，肺常不足、脾常不足，肺为娇脏不耐寒热，卫外不固，故外感六淫易从口鼻而入犯肺；肺失宣降则津液输布失常，聚液为痰，痰阻气道而咳嗽。病位在肺，常累及脾，久咳则肺脾气虚。辨证以风寒、风热、痰热、阴虚、肺脾气虚为纲。治疗以宣肺化痰为基本法，配合小儿推拿与家庭护理。","blocks":[{"type":"paragraph","text":"小儿咳嗽的病位在肺，与脾关系密切。小儿肺常不足，肺为娇脏，主气司呼吸，外合皮毛，不耐寒热，卫外不固，故六淫之邪易从口鼻而入，肺卫受邪、宣降失职而咳嗽；脾常不足，运化不健，津液不布，聚而为痰，痰阻气道，肺气上逆而咳嗽加剧，痰多而黏。病因以外感为主：风寒束肺则肺气失宣，咳嗽声重、痰稀色白、鼻塞流清涕、恶寒无汗、苔薄白、指纹浮；风热犯肺则肺失清肃，咳嗽频剧、痰黏或黄、咽红肿痛、发热、舌红苔薄黄、指纹浮紫；外感入里化热则痰热壅肺，咳嗽气粗、痰多黄稠或腥臭、胸闷、发热面赤、口渴、苔黄腻、指纹紫滞，是为痰热之证，须及时清化以防变证。若素体阴虚（如热病后期或久病体弱），肺阴耗伤而干咳少痰、咽干口燥、午后潮热、盗汗、舌红少苔、指纹细数，则为阴虚肺热，久则肺虚及脾，出现咳嗽无力、痰多清稀、气短懒言、面色㿠白、自汗、易感冒、纳少便溏、指纹淡的肺脾气虚证，此时当以扶正为主、健脾益气固表。小儿病情变化迅速，肺气闭郁可发展为喘促与心阳受损，故咳嗽若兼气促、鼻翼煽动、面色苍白或青紫、口唇发绀，属危重信号，须立即就医。"},{"type":"table","caption":"小儿咳嗽辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["风寒袭肺证","咳嗽声重，痰稀色白，鼻塞流清涕，恶寒无汗，发热较轻，舌淡红苔薄白，指纹浮","宣肺散寒，止咳化痰","三拗汤合止嗽散","寒甚加桂枝、紫苏叶；痰多加半夏、陈皮；咽痒加蝉蜕、桔梗；鼻塞加辛夷、苍耳子"],["风热犯肺证","咳嗽频剧，痰黏稠或黄，咽红肿痛，发热恶风，鼻流黄涕，口渴，舌红苔薄黄，指纹浮紫","辛凉宣肺，清热止咳","桑菊饮","热甚加黄芩、连翘；咽痛加牛蒡子、射干、玄参；痰黄加瓜蒌、浙贝；咳甚加枇杷叶、前胡"],["痰热壅肺证","咳嗽气粗，痰多黄稠或腥臭，胸闷，发热面赤，口渴烦躁，或气促鼻煽，舌红苔黄腻，指纹紫滞","清热化痰，宣肺止咳","清金化痰汤（或桑白皮汤）","热毒盛加鱼腥草、蒲公英、黄芩；痰多加葶苈子、浙贝；气促加麻黄、杏仁；便秘加大黄"],["阴虚肺热证","干咳少痰或痰黏难咯，咽干口燥，午后潮热，盗汗，颧红，舌红少苔，指纹细数","养阴清肺，润燥止咳","沙参麦冬汤","咳甚加川贝、枇杷叶；痰中带血加仙鹤草、白及；潮热加地骨皮、青蒿；咽干加玄参、麦冬"],["肺脾气虚证","咳嗽无力，痰多清稀色白，气短懒言，面色㿠白，自汗怕风，纳少便溏，易感冒，舌淡苔薄，指纹淡","健脾益气，补肺固表","六君子汤合玉屏风散","气虚甚加黄芪、党参；痰多加半夏、陈皮；自汗加浮小麦、麻黄根；食少加山药、莲子"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴肺俞、列缺、合谷、天突、膻中；风寒加风门、大椎，风热加大椎、曲池，痰热加丰隆、鱼际，阴虚加膏肓、太溪，肺脾气虚加脾俞、足三里","bullets":["小儿浅刺快针，手法轻柔，宜不留针或少留针","天突、膻中为经验止咳要穴","不宜在剧烈咳嗽或高热时强行针刺"]},{"icon":"🤲","title":"小儿推拿","text":"清肺经、推拿肺俞、揉板门、揉天突、揉膻中、分推肩胛、运内八卦、按揉足三里、捏脊；风寒加揉外门、推三关，风热加清天河水、退六腑","bullets":["清肺经与揉肺俞为主手法，每日二至三次","捏脊以培补元气，适用于久咳体虚者","手法宜轻柔，避免在胸骨上重压"]},{"icon":"🫧","title":"雾化与家庭护理","text":"遵医嘱行雾化吸入是儿童急性咳嗽与哮喘的重要局部治疗方式；配合拍背排痰、空心掌由下向上、由外向内拍背，每次五至十分钟，痰多者拍后用吸痰器","bullets":["拍背宜在餐前或餐后两小时进行","痰多而无力咯出者可作体位引流","拍背力度以不引起疼痛为度，禁在脊柱与肾区叩击"]}]},{"type":"paragraph","text":"小儿咳嗽的饮食调养以清润、易消化、少量多餐为原则，随证配餐。风寒袭肺者宜温化寒痰，忌生冷寒凉与冰饮，可饮生姜红枣水、葱白粥、蒸苹果；风热犯肺与痰热壅肺者宜清热化痰，忌辛辣煎炸、烧烤、巧克力与含糖饮料，可食雪梨川贝、百合、荸荠、丝瓜、萝卜、绿豆、蜂蜜（一岁以上）、马蹄；阴虚肺热者宜滋阴润肺，忌燥烈温燥与煎炸，可食银耳百合羹、百合莲子粥、燕窝、雪梨、桑葚、枇杷；肺脾气虚者宜健脾益气、忌生冷寒凉与过饥，可食山药粥、莲子百合粥、黄芪粥、瘦肉、鸽子、鹌鹑、大枣。日常护理要点：多饮温水以稀释痰液、便于排出；保持室内空气流通与适宜湿度（百分之五十至六十），避免烟尘、油烟、粉尘与刺激性气味；每日保证优质蛋白、锌与维生素摄入以助恢复；咳嗽期间不宜进食生冷、油腻与海鲜发物；不宜用冰糖炖梨等甜腻食疗替代规范治疗；不擅自给小儿服用止咳糖浆、含可待因制剂与抗生素。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：保证每日十至十三小时睡眠，休息充分有助正气恢复；居室通风但避免冷风直吹小儿，湿度适宜；注意保暖，避免汗出当风与受凉，注意颈部与背部保暖；发热期间多休息、少量多次饮温水；咳嗽时让小儿侧卧或坐起以利排痰，夜间床头略抬高；避免二手烟与雾霾；不随意亲吻小儿口部以免传播呼吸道感染。运动：咳嗽期间以静养为主，急性期避免剧烈活动；症状缓解后可逐步恢复户外活动与轻度跑跳，以增强体质；每次运动时间不宜过长，注意观察有无气促与面色变化；反复咳嗽的儿童可作八段锦、五禽戏等温和导引；避免在空气污染或寒冷清晨户外剧烈运动。预防：按时完成预防接种（百日咳、流感、肺炎球菌疫苗等须遵医嘱）；按时添加辅食与保证营养以增强体质；幼儿园与家庭均应注意手卫生与咳嗽礼仪（用纸巾或肘部遮挡口鼻）；避免带小儿去人多拥挤、空气污浊的场所；反复咳嗽或喘息者应查明病因（过敏性哮喘、异物吸入、胃食管反流、支气管异物等）而非长期自行用药。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须立即就医：呼吸急促、鼻翼煽动、三凹征（胸骨上窝与肋间隙凹陷）、口唇甲床青紫；喘息发作、哮鸣明显；咳嗽剧烈伴呕吐或呛咳后气促（须警惕气道异物）；高热持续三天以上不退或退热后再次升高；精神萎靡、烦躁不安、嗜睡、囫囵吞枣或意识模糊；拒食拒水、尿量明显减少、口唇干燥、皮肤弹性差（脱水）；咳嗽伴咯血或痰中带血；胸痛、咳脓痰；反复夜间阵发性剧烈咳嗽伴喘息（须排查哮喘）；消瘦、盗汗、低热持续（须排查结核）；小于三月的婴儿出现发热（须立即就医）。用药禁忌：婴幼儿禁用含可待因的镇咳制剂，四岁以下儿童不宜使用中枢性镇咳药（可致呼吸抑制）；阿片类、二甲双胍类禁用；不得给小儿服用成人止咳药或随意使用抗生素；激素类雾化仅在医师处方下短期使用，不可自行长期反复雾化；氨溴索、乙酰半胱氨酸等祛痰药须遵医嘱；口服补液盐须按规范配制以免钠负荷过重；禁止给小儿服用含马来酸氯苯那敏的复方感冒药或抗组胺药镇咳；服用中药汤剂须遵医嘱并注意量剂；不擅自使用激素、抗生素或雾化激素。"},{"type":"keypoints","title":"小儿咳嗽要点","items":["病位在肺而常累及脾，风寒用三拗汤合止嗽散、风热用桑菊饮、痰热用清金化痰汤、阴虚肺热用沙参麦冬汤、肺脾气虚用六君子汤合玉屏风散","辨证抓手：痰稀色白属风寒，痰黄稠属风热或痰热，痰多清稀兼乏力属肺脾气虚，干咳少痰兼潮热属阴虚","小儿推拿（清肺经、揉肺俞、揉天突、捏脊）是安全有效的辅助疗法，拍背排痰有助痰液排出","气促、鼻翼煽动、三凹征、口唇青紫、嗜睡拒食为危重征象，须立即就医","四岁以下禁用可待因类镇咳药，激素雾化不可自行长期使用"]}]},{"id":"shizhen","title":"湿疹","subtitle":"湿疹｜湿疹样皮炎、婴儿湿疹、脂溢性皮炎","category":"外科皮肤","tags":["湿疮","湿热浸淫","脾虚湿蕴","血虚风燥","皮肤瘙痒"],"meta":[{"label":"中医病名/证型概要","value":"湿疮（湿疹）。证型分湿热浸淫、脾虚湿蕴、血虚风燥，婴儿多见脾虚湿蕴"},{"label":"主要症状","value":"皮损多形性，红斑、丘疹、水疱、糜烂、渗出与结痂，瘙痒剧烈，搔抓后渗血或继发感染"},{"label":"舌脉要点","value":"湿热舌红苔黄腻脉滑数；脾虚湿蕴舌淡胖苔白腻脉濡缓；血虚风燥舌淡苔薄脉细"},{"label":"治则","value":"清热利湿、祛风止痒为主，脾虚者健脾除湿，血虚者养血润燥祛风，内外合治"}],"image":"","imageHint":"湿疹","summary":"湿疹中医称湿疮，以皮肤多形性损害、剧烈瘙痒为主要特征，病程长、易反复。病位在皮肤，与肺脾心肝关系密切，基本病机为风湿热邪蕴结肌肤、脾失健运、湿浊内生。辨证分湿热浸淫、脾虚湿蕴与血虚风燥三型，临床以脾虚湿蕴为基础而兼夹湿热。治疗须内外结合：内服中药调整脾湿与气血，外用清热解毒、祛风止痒之品，并重视皮肤屏障修复与生活调摄，避免搔抓与不当刺激。","blocks":[{"type":"paragraph","text":"湿疹的病位在皮肤，与肺、脾、心、肝关系密切。《素问·至真要大论》曰「诸皮毛之类，皆属于肺」，肺主皮毛，肺失宣降则腠理开合失司，风邪易袭；《素问·太阴阳明论》曰「脾主身之肌肉」，脾主运化，脾虚则水湿不化，湿浊内生，浸淫肌肤；心主血脉，血热则肌肤失养而瘙痒、烦躁；肝主疏泄，肝血不足则风燥内生，肌肤失养而干枯脱屑。基本病机可归纳为风湿热邪蕴结肌肤。临床以脾虚为本、湿热为标：饮食不节、肥甘厚味或辛辣刺激，脾失健运，湿聚成痰，湿久化热，湿热蕴结肌肤，故皮损红肿灼热、糜烂渗液、瘙痒剧烈、伴口苦便秘；或因外感风邪，风湿相搏，郁于肌肤而发；久病耗伤阴血，脾虚生风，肌肤失养，则皮损干燥粗糙、肥厚脱屑、瘙痒夜间尤剧、舌淡脉细。婴幼儿湿疹多因禀赋不足、胎毒内蕴、脾失健运，加以乳食不节、护理失宜而发，湿重于热，常表现为皮损渗出而色不甚红。搔抓是本病最重要的恶性环节，可致皮肤屏障破坏、渗出增多、继发感染并形成难治的慢性苔藓样变，故治疗中「止痒、防抓」与「健脾除湿」并重。"},{"type":"table","caption":"湿疹辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["湿热浸淫证","皮损潮红肿胀，灼热瘙痒，糜烂渗液，浸淫蔓延，渗液较稠，伴心烦口渴，身热，大便秘结，小便短赤，舌红苔黄腻，脉滑数","清热利湿，祛风止痒","龙胆泻肝汤","热甚加黄连、栀子、丹皮；痒甚加地肤子、白鲜皮、蛇床子；渗出多加土茯苓、萆薢"],["脾虚湿蕴证","皮损色淡或暗红，粗糙肥厚，瘙痒较轻，渗液不多但浸淫，伴纳呆腹胀，倦怠乏力，大便溏薄，舌淡胖苔白腻，脉濡缓","健脾除湿，祛风止痒","除湿胃苓汤","脾虚甚加白术、山药、莲子；湿盛加薏苡仁、茯苓、车前子；痒甚加白鲜皮、地肤子"],["血虚风燥证","皮损干燥脱屑，粗糙肥厚，瘙痒难忍，夜间尤甚，抓痕血痂，久病不愈，舌淡苔薄，脉细","养血润燥，祛风止痒","当归饮子","血虚甚加熟地、白芍、鸡血藤；干燥甚加麦冬、玉竹；痒甚加全蝎、蜈蚣、白蒺藜"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴曲池、血海、足三里、三阴交、阴陵泉、阿是穴；湿热加大椎、曲池、公孙，脾虚加脾俞、胃俞、足三里，血虚风燥加膈俞、脾俞、关元","bullets":["曲池、血海为止痒要穴，针刺留针二十至三十分钟","阿是穴（皮损周围）可围刺，但皮损处不宜直接针刺","实证用泻法、虚证用补法，每日或隔日一次，十次为一疗程"]},{"icon":"🧴","title":"外治法","text":"渗出明显宜用湿敷（生地榆、黄柏、马齿苋煎水湿敷），干燥脱屑宜用润肤膏剂，瘙痒剧可用中药外洗方（苦参、地肤子、白鲜皮、蛇床子）煎汤熏洗；婴儿可用婴儿保湿霜厚涂修复屏障","bullets":["湿敷面积不超过皮损范围，每次二十分钟，勿过长时间以免脱水","外洗水温不宜过高，忌用力搓洗","激素类外用药须遵医嘱短期使用，不擅自长期涂擦面部与皱褶部位"]},{"icon":"🤲","title":"推拿与耳穴","text":"推拿取曲池、血海、足三里、三阴交、风市、脾俞，以揉按为主；耳穴贴压取肺、脾、肝、肾、荥麻疹区、皮质下，双耳交替贴压三至五日","bullets":["推拿每日一次，每次十五分钟，可配合按揉内关与神门以安神助眠","耳穴贴压期间避免水浸","瘙痒剧烈影响睡眠者加揉安眠与百会"]}]},{"type":"paragraph","text":"湿疹的饮食调养以清淡、忌发物、辨证施膳为要。湿热浸淫者宜清热利湿，忌辛辣煎炸、烧烤、酒类、浓茶与海鲜发物，可食冬瓜、丝瓜、绿豆、土茯苓、薏苡仁、马齿苋、苦瓜；脾虚湿蕴者宜健脾除湿、忌生冷寒凉、肥甘甜腻与牛奶蛋类可疑致敏食物，可食山药粥、薏仁山药粥、白扁豆粥、茯苓、莲子、芡实、陈皮；血虚风燥者宜养血润燥、忌辛辣燥烈与煎炸，可食黑芝麻、桑葚、百合、莲子、桂圆、瘦肉、当归生姜羊肉汤。日常须严格避免已知致敏食物与可疑过敏原（牛奶、鸡蛋、花生坚果、鱼虾蟹、芒果等），必要时逐一排查并记录；忌酒、浓茶、咖啡与碳酸饮料；多饮温水；婴幼儿不必过度忌口而致营养不良，须由医师评估。皮肤护理要点：温水（三十七度左右）淋浴，时间不超过十分钟，忌过热热水与皂基、碱性洗剂；沐浴后三分钟内涂保湿剂封闭；穿纯棉宽松衣物，忌羊毛、化纤与粗糙摩擦；剪短指甲以防抓伤；被褥与衣物常洗常晒；居室湿度适宜、避免过热出汗加重瘙痒。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：作息规律，保证睡眠，避免熬夜（肝血不足则痒甚）；避免过度劳累、情绪紧张与热水烫洗；室内温湿度适宜，避免出汗、闷热与干燥刺激；不接触洗涤剂、溶剂、化妆品等刺激物，接触清洁剂时戴手套；精神紧张与情绪波动会加重瘙痒，宜保持心情平和。运动：病情急性期以休息为主，避免汗液刺激；缓解期可作散步、慢跑、太极、八段锦等温和运动，运动后及时沐浴并涂保湿剂；避免高强度出汗运动与桑拿；不宜在剧烈搔抓后立即运动。预防：积极寻找并回避诱因（食物、接触物、气候、精神因素、肠道寄生虫）；维持皮肤屏障完整是预防复发的核心；母亲有过敏史者孕哺期宜注意饮食回避；婴幼儿湿疹应加强保湿护理；反复发作或伴哮喘、过敏性鼻炎者须查过敏原并考虑特异性免疫治疗；避免长期依赖单一外用激素而反复自行使用，宜在专科医师指导下阶梯用药与定期复评。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：皮损大面积渗出、糜烂、结厚痂伴发热、局部红肿热痛明显（继发细菌感染）；皮损迅速扩大、出现水疱、大疱或表皮剥脱，伴口腔、眼部、外生殖器黏膜糜烂（须警惕重症药疹、剥脱性皮炎与Stevens-Johnson综合征）；眼周与面部皮损伴眼睑肿胀、视物模糊；皮损伴发热、关节痛与淋巴结肿大；剧痒影响睡眠、影响生活与工作，经规范治疗无效；婴幼儿湿疹伴发育迟缓、反复感染（须排查免疫缺陷与代谢病）；皮损呈环状、边缘隆起、中央消退并向周围扩展（须排查体癣与体癣样脓疱病）；皮损经规范治疗两周以上无改善。用药禁忌：外用糖皮质激素不可擅自长期大面积使用于面部、眼周、皱褶与外阴，易致皮肤萎缩、毛细血管扩张与激素依赖性皮炎；含激素的复方膏剂（皮炎平、复方酮康唑等）不宜自行长期使用；抗真菌药与抗生素药膏须辨证选用，误用于湿疹会加重病情；口服抗组胺药可致嗜睡，驾驶与高空作业者慎用；中药外用含硫磺、雄黄、朱砂者须医师指导；孕妇、哺乳期妇女与婴幼儿使用任何外用药前须咨询医师；禁止用酒精、醋、盐水、牙膏等自行涂擦患处；搔抓致继发感染时须由医师决定是否使用抗生素，禁自行长期口服抗生素。"},{"type":"keypoints","title":"湿疹要点","items":["病机为风湿热蕴结肌肤，脾虚为本、湿热为标，血虚风燥为久病之变","湿热浸淫用龙胆泻肝汤、脾虚湿蕴用除湿胃苓汤、血虚风燥用当归饮子","辨证抓手：红肿灼热渗出属湿热，色淡肥厚渗液少属脾虚，干燥脱屑夜痒属血虚风燥","止痒防抓与修复屏障同等重要：温水短时淋浴、沐浴后三分钟内涂保湿剂、剪短指甲、穿纯棉宽松衣物","继发感染、大面积剥脱、累及黏膜、眼周受累与规范治疗两周无效者须立即就医"]}]},{"id":"cuochuang","title":"痤疮","subtitle":"痤疮｜寻常痤疮、皮脂腺增生、青春痘","category":"外科皮肤","tags":["粉刺","肺经风热","湿热蕴结","冲任不调","痰湿瘀滞"],"meta":[{"label":"中医病名/证型概要","value":"粉刺（肺风粉刺）。证型分肺经风热、湿热蕴结、痰湿瘀滞、冲任不调"},{"label":"主要症状","value":"颜面、胸背部出现粉刺（黑头、白头）、丘疹、脓疱、结节与囊肿，皮脂分泌旺盛，轻者瘙痒微痛，重者遗留色素沉着与瘢痕"},{"label":"舌脉要点","value":"肺经风热舌红苔薄黄脉浮数；湿热舌红苔黄腻脉滑数；痰湿瘀滞舌暗苔白腻脉滑涩；冲任不调舌淡红苔薄脉弦"},{"label":"治则","value":"清肺祛风、清热利湿、化痰祛瘀、调摄冲任，内外合治，重在去除粉刺"}],"image":"","imageHint":"痤疮","summary":"痤疮中医称粉刺，以颜面胸背出现粉刺、丘疹、脓疱、结节与囊肿为主要表现，常见于青春期，与皮脂分泌增多、毛囊皮脂腺导管角化异常、痤疮丙酸杆菌感染、局部炎症与免疫反应以及雄激素水平变化相关。中医病机为肺经风热、湿热蕴结、痰湿瘀滞与冲任不调，肺主皮毛、外合大肠，肺经风热上蒸于面则生粉刺；过食辛辣肥甘、脾失健运、湿热内蕴则丘疹脓疱；久病痰瘀互结则结节囊肿、遗留瘢痕；冲任失调、肾阴不足、相火妄动则经前加重。治疗须内调脏腑、外清皮毛，并重视面部护理与生活方式干预。","blocks":[{"type":"paragraph","text":"痤疮的病位在肺与皮肤，与脾、肝、肾及冲任关系密切。《素问·刺法论》曰「肺合皮毛」，肺主宣发肃降、外合皮毛，肺经风热循经上蒸，郁于肌肤而发为粉刺，故痤疮初起多见肺经风热之证；肺与大肠相表里，肺热下移大肠，腑气不通，糟粕积滞化毒，毒邪外透肌肤，加重丘疹脓疱。饮食不节，过食辛辣炙煿、肥甘厚味与酒类，脾胃受损，运化失健，湿浊内生，郁久化热，湿热蕴结肌肤，故见红肿疼痛的丘疹、脓疱、结节，皮肤油腻，伴口苦口黏、便秘尿赤；久病入络，气滞血瘀，痰瘀互结，故结节囊肿坚硬，皮损色暗，遗留凹陷性瘢痕与色素沉着；素体肾阴不足、冲任失调，相火妄动，湿热循经上扰，故痤疮于月经前一周加重，伴月经不调、腰酸乏力。病机可概括为肺经风热为本、湿热痰瘀为标、冲任失调为重要内因，且互为因果、缠绵难愈。治疗须辨明虚实与病位，初期以清肺疏风为主，中期以清热利湿为先，日久则以化痰祛瘀、调补冲任为要。"},{"type":"table","caption":"痤疮辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["肺经风热证","颜面潮红，丘疹色红，针头大小，瘙痒或疼痛，偶有脓疱，皮肤油腻，伴口渴喜冷饮、便秘，舌红苔薄黄，脉浮数","清肺散风，清热解毒","枇杷清肺饮","热甚加黄芩、桑白皮；痒甚加白鲜皮、防风；便秘加大黄、玄参；脓疱加蒲公英、紫花地丁"],["湿热蕴结证","皮损红肿疼痛，丘疹脓疱并见，结节囊肿，口苦口黏不渴，纳呆，胸闷，皮脂分泌旺盛，大便秘结或黏滞，小便短赤，舌红苔黄腻，脉滑数","清热除湿，解毒散结","龙胆泻肝汤合二陈汤","热甚加黄连、栀子、丹皮；囊肿加夏枯草、浙贝、玄参；便秘加大黄、芒硝"],["痰湿瘀滞证","病程日久，皮损色暗，丘疹结节融合成硬结或囊肿，遗留瘢痕与色素沉着，皮脂多，舌暗红或有瘀斑，苔白腻，脉滑涩","除湿化痰，活血散结","二陈汤合桃红四物汤","痰结加夏枯草、浙贝、玄参、牡蛎；瘀重加三棱、莪术；结节硬加莪术、昆布、海藻"],["冲任不调证","痤疮于月经前加重，皮损以结节囊肿为主，伴月经不调、量少色暗有块，腰酸乏力，情绪烦躁，舌淡红苔薄，脉弦","调摄冲任，清热活血","丹栀逍遥散","月经不调加菟丝子、女贞子、旱莲草；结节加夏枯草、浙贝；腰酸加杜仲、桑寄生"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴肺俞、大椎、曲池、合谷、血海、足三里、阳陵泉；肺经风热加印堂、鱼际，湿热加阴陵泉、内庭，痰湿瘀滞加丰隆、三阴交，冲任不调加关元、太冲、三阴交","bullets":["合谷、血海、曲池为主穴，针刺泻法可清利面部湿热","实证可点刺大椎、耳尖或委中放血，每周一至两次","留针二十至三十分钟，每日或隔日一次，十次为一疗程"]},{"icon":"🧴","title":"外治与挑刺","text":"传统挑刺法（挑治肺俞穴或耳背）、中药面膜（黄连、黄芩、丹参、大黄等研末调敷）、火针与针刺放血；现代可配合维A酸类外用、过氧化苯甲酰等按医嘱使用","bullets":["挑治须由专业人员在无菌条件下操作","炎症明显处以抗炎处理为主，不宜挤压粉刺","外用维A酸类起效需四至八周，须遵医嘱使用并注意妊娠禁用"]},{"icon":"🤲","title":"推拿与耳穴","text":"面部推拿取印堂、攒竹、鱼际、颊车、四白、太阳，轻柔按揉以助面部气血运行；耳穴贴压取肺、大肠、内分泌、皮脂腺、肾上腺、皮质下，双耳交替","bullets":["面部手法宜轻，避免牵拉皮肤加重色沉","耳穴贴压期间避免水浸与摩擦","配合面部清洁与作息管理效果更佳"]}]},{"type":"paragraph","text":"痤疮的饮食调养以清淡、控油、少糖为原则，并随证配餐。肺经风热者宜清肺散风、忌辛辣煎炸、酒类与浓茶，可饮金银花菊花茶、蒲公英茶、绿豆百合粥、荸荠；湿热蕴结者宜清热除湿、忌肥甘厚味、甜腻、奶制品过量与酒类，可食冬瓜、丝瓜、苦瓜、绿豆、薏苡仁、土茯苓、马齿苋；痰湿瘀滞者宜化痰祛瘀、忌滋腻助湿之品，可食山药、薏苡仁、茯苓、桃仁、山楂、玫瑰花茶；冲任不调者宜调摄冲任、忌温燥助火，可食枸杞、女贞子、旱莲草、桑葚、山药、百合、黑芝麻。日常须严格限制高糖高脂与奶制品摄入（乳制品与痤疮的关系明确，高糖负荷与油脂摄入过量均可加重皮脂分泌与炎症）；忌酒、浓茶、咖啡因与能量饮料；每日饮水一千五百至二千毫升；避免大量食用牛奶、奶酪、巧克力、坚果、油炸食品与肥肉；补充锌与维生素A族的食物（牡蛎、瘦肉、南瓜、动物肝脏适量）。面部护理：温和洁面每日两次、忌用力擦拭与挤压、避免高浓度酒精与磨砂产品、做好防晒（物理遮挡加不致痘的防晒霜）以防色沉。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：起居规律，保证每日七至八小时睡眠，避免熬夜（肝郁化火与肺经风热皆因作息紊乱而加重）；避免长期熬夜与过度用脑；保持心情舒畅，肝气疏达则肺胃得降；避免长时间处于高温高湿环境（如厨房、桑拿房），汗液与油脂分泌增加会加重病情；注意个人物品清洁，枕巾与床单每周更换；避免用手触摸面部；不随意挤压粉刺以免继发感染与凹陷性瘢痕。运动：规律有氧运动（快走、慢跑、游泳、骑行、球类）有助代谢与情绪改善，建议每周一百五十分钟中等强度，但避免高强度出汗运动后不及时清洁与高湿环境运动；运动后及时清洁并涂保湿；避免佩戴厚重头盔与不透气装备摩擦面部。预防：痤疮有遗传与内分泌因素，无法完全避免，但及时规范治疗可减少瘢痕与色沉；坚持三个月以上规范疗程，切勿症状缓解即停药；控制甜食与乳制品、规律作息、适度运动是长期管理要点；面部已有炎症者不宜挤、抠、挑；治疗期间不宜同时叠加多种刺激性外用药；青少年痤疮严重者宜尽早就诊，避免留下永久性瘢痕影响心理健康。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：皮损以结节、囊肿为主、质地坚硬、范围较大或伴明显疼痛（须排查聚合性痤疮、皮脂腺增生与感染）；出现皮肤红肿热痛、脓液波动、发热（须排查疖肿、脓肿）；下颌与颈部出现成片丘疹结节、触之疼痛、愈后留瘢痕（须排查痤疮性下颌炎与毛囊炎）；伴多毛、明显痤疮、月经不调、体重增加（须排查多囊卵巢综合征与内分泌疾病）；长期月经紊乱、多毛（须查性激素与甲状腺功能）；结节囊肿破溃后长期不愈、边缘不整齐、易出血（须警惕皮肤恶性肿瘤）；长期用药无效或反复发作加重（须评估用药方案与诊断）；出现明显色素沉着、瘢痕或心理困扰（宜尽早皮肤科就诊）。用药禁忌：外用维A酸类（阿达帕林、维A酸乳膏）妊娠与哺乳期禁用，初期可致干燥脱皮刺痛，须建立耐受、避开眼周；过氧化苯甲酰可致干燥与衣物漂白；外用抗生素（克林霉素、夫西地酸）不可自行长期使用以免耐药；异维A酸（口服四环素类）育龄女性须严格避孕，孕期与哺乳期禁用，并监测血脂与肝功能；四环素类药物八岁以下儿童禁用、孕期禁用；含激素的复方外用药不可长期用于面部；挤压危险三角区皮损有感染扩散风险；中成药如痤疮胶囊、丹参酮胶囊等须辨证使用，孕妇慎用活血祛瘀之品。"},{"type":"keypoints","title":"痤疮要点","items":["病机为肺经风热、湿热蕴结、痰湿瘀滞与冲任不调，初期清肺、中期清热利湿、日久化痰祛瘀调冲任","肺经风热用枇杷清肺饮、湿热蕴结用龙胆泻肝汤合二陈汤、痰湿瘀滞用二陈汤合桃红四物汤、冲任不调用丹栀逍遥散","限制糖类与乳制品、避免熬夜、加强防晒是三大基础措施","严禁挤压，特别是面中部的危险三角区，以防感染扩散与凹陷性瘢痕","结节囊肿为主、伴多毛月经不调、或规范治疗无效者须及时就诊排查特殊类型"]}]},{"id":"bantu","title":"斑秃","subtitle":"斑秃｜斑片脱发、圆形脱发","category":"外科皮肤","tags":["脱发","血虚风燥","肝郁气滞","血瘀","补肾养血"],"meta":[{"label":"中医病名/证型概要","value":"油风（斑秃）。证型分血虚生风、肝郁气滞、血瘀、肾虚"},{"label":"主要症状","value":"头皮出现圆形或不规则片状脱发区，边界清楚、头皮光滑无炎症，患处毛发稀疏渐至全脱，可伴瘙痒与灼热感"},{"label":"舌脉要点","value":"血虚生风舌淡苔薄脉细弱；肝郁气滞舌淡红苔薄白脉弦；血瘀舌紫暗有瘀斑脉涩；肾虚舌淡脉沉细"},{"label":"治则","value":"养血祛风、疏肝解郁、活血化瘀、补肾生发，兼安神，内外合治"}],"image":"","imageHint":"斑秃","summary":"斑秃中医称油风，以头皮出现边界清楚的圆形或不规则片状脱发区、头皮光滑为特征，属突然发生的局限性脱发。病位在头皮，与肝、肾、血关系密切，「发为血之余」，肾其华在发。情志不遂肝郁化火耗伤血，发失所养；先天禀赋不足或劳倦过度，肾精亏虚不能生发；久病入络、气滞血瘀，络脉瘀阻发失荣养；气血亏虚则血不养发。治疗以养血生发、疏肝活血、补肾为法，并配合局部外治与心理疏导，多数患者经规范治疗可获毛发再生。","blocks":[{"type":"paragraph","text":"斑秃的病位在头部皮肤，与肝、肾、血密切关系。《素问·六节藏象论》曰「肾其华在发」，肾精充盛则发黑有光；《素问·上古天真论》曰「发为血之余」，血荣则发养。故斑秃之成，与肾精不足、血不养发密切相关。病因有四：一为先天禀赋不足，肾精亏虚，髓海失充，发失所养，多见于青少年发病者；二为情志不遂，肝气郁结，郁久化火，暗耗阴血，或肝血不足不能荣发，故常在精神刺激、重大事件、焦虑抑郁之后突然发病；三为劳倦过度、久病体弱，气血亏虚，发失所养；四为久病入络，气滞血瘀，络脉瘀阻，脱发难生。临床常见数证相兼：血虚生风者脱发区头皮光亮、瘙痒、伴面色萎黄、头晕心悸、舌淡脉细；肝郁气滞者脱发与情志密切相关，伴胸胁胀满、烦躁易怒、失眠；血瘀者病程日久、头皮紫暗、舌暗有瘀斑；肾虚者脱发量多而广、伴腰膝酸软、头晕耳鸣、牙齿松动、须发早白。病机要点在于「发失所养」与「络脉瘀阻」，治疗须辨明虚实，血虚者补血生发，气滞者疏肝理气，血瘀者活血通络，肾虚者补肾填精。"},{"type":"table","caption":"斑秃辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["血虚生风证","脱发区头皮光亮，瘙痒或灼热，毛发稀疏，伴面色萎黄，神疲乏力，头晕心悸，舌淡苔薄，脉细弱","养血祛风，健脾生发","神应养真丹","血虚甚加熟地、白芍、鸡血藤；瘙痒加白蒺藜、蝉蜕；纳差加白术、茯苓"],["肝郁气滞证","脱发与情志波动密切相关，胸胁胀满，烦躁易怒，失眠多梦，叹息，舌淡红苔薄白，脉弦","疏肝解郁，养血生发","逍遥散","郁热加丹皮、栀子；失眠加夜交藤、酸枣仁；脱发重加何首乌、鸡血藤"],["血瘀证","病程迁延数月以上，脱发区扩大或反复发作，头皮色暗或紫，舌质紫暗有瘀斑，脉涩","活血化瘀，通窍生发","通窍活血汤","久瘀加地龙、水蛭；痛经加延胡索、五灵脂；血虚加当归、熟地"],["肾虚证","脱发面积广、发色枯黄稀疏，伴腰膝酸软，头晕耳鸣，牙齿松动，须发早白，畏寒乏力，舌淡苔薄，脉沉细","补肾益精，养血生发","七宝美髯丹","肾阴虚加女贞子、旱莲草、龟板；肾阳虚加菟丝子、鹿角霜；发枯加何首乌、黑芝麻"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴百会、头维、风池、脾俞、肝俞、肾俞、足三里、三阴交；血虚加膈俞、血海，肝郁加太冲、期门，血瘀加血海、膈俞，肾虚加太溪、关元","bullets":["风池与百会为生发要穴，针刺得气为佳","实证用泻法、虚证用补法，肾虚者加灸关元、命门","留针二十至三十分钟，每日或隔日一次，十次为一疗程"]},{"icon":"🌿","title":"外治法","text":"斑秃区以鲜姜汁或侧柏叶酊涂擦，每日二至三次；中药制剂如首乌酊、桑菊首乌丸配合外搽；可用中药液洗头（侧柏叶、何首乌、旱莲草煎液）","bullets":["涂擦以微微刺激为度，皮肤破损、渗液处暂停","外用糖皮质激素与米诺地尔须遵医嘱使用","出现局部毛囊炎、毛孔粗大应停药就诊"]},{"icon":"🤲","title":"推拿按摩与耳穴","text":"头部推拿取百会、风池、头维、太阳、阿是穴，以摩、揉、叩为法；耳穴贴压取肾、肝、脾、 神门、枕、皮质下，双耳交替贴压三至五日","bullets":["头部按摩每日一次，每次十分钟，促进局部血流","配合头皮放松与心理疏导可缓解焦虑","严重焦虑失眠者宜加心理科干预"]}]},{"type":"paragraph","text":"斑秃的饮食调养以补肾养血、益精生发为原则。血虚生风者宜养血健脾，忌辛辣燥烈与生冷，可食黑芝麻、桑葚、核桃、桂圆、红枣、枸杞、龙眼肉、瘦肉、猪肝（适量）、当归生姜羊肉汤；肝郁气滞者宜疏肝理气，忌郁怒与过食辛辣，可饮玫瑰花茶、佛手陈皮茶、合欢花茶，食佛手、香橼、芹菜；血瘀者宜活血化瘀、忌寒凉凝滞，可食黑木耳、桃仁、山楂、玫瑰花；肾虚者宜补肾填精，忌生冷寒凉与过度耗伤，可食黑芝麻、桑葚、核桃、栗子、枸杞、淮山、芡实、淡菜、优质蛋白、黑色食物。日常须保证每日足量优质蛋白、铁、锌与维生素B族摄入；避免节食减肥与长期素食导致气血生化乏源；避免烫发、染发与频繁梳理；每日温水洗头并轻柔按摩头皮；注意休息、减少压力、保持心情平和；避免长期熬夜。中药内服与外用并用效果优于单一疗法，一般需坚持三至六个月以上方见新生毛发。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：作息规律，保证每日七至八小时睡眠，避免熬夜与长期精神紧张；保持头皮清洁与通风，佩戴帽子与头巾宜宽松透气；避免烫染发与使用刺激性染发剂、生发液；洗头宜温水、洗发剂温和，勿用指甲用力抓挠头皮；避免长期佩戴过紧的帽子与头绳牵拉头发（可致牵引性脱发）；头皮有皮屑或油脂过多者宜对症处理；情绪调摄极为关键，斑秃与精神因素关系密切，须给予充分解释与鼓励，避免过度关注。运动：适度有氧运动（快走、慢跑、游泳、太极、八段锦）有助气血运行与减压，每周一百五十分钟；避免高强度与长时间倒立、倒吊类运动及过度拉扯头发的运动；配合头皮按摩与颈部放松。预防：家族有脱发史者应早期干预；持续高应激状态者宜主动进行心理调适；有自身免疫疾病、甲状腺疾病、贫血者应积极治疗基础病；长期服用可能影响毛发的药物（抗凝药、维A酸类、部分抗肿瘤药、锂剂等）须告知皮肤科医师；避免反复自行使用来源不明的生发产品；发现进行性脱发、头皮红肿脱屑或伴全身症状时须尽早就诊明确病因。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：脱发呈全头脱落或发展为全身毛发稀疏脱落（须排查弥漫性脱发、甲状腺疾病、贫血、狼疮与梅毒）；脱发区头皮红肿、渗出、结痂、脱屑（须排查头癣、脂溢性皮炎与细菌感染）；脱发伴皮肤变薄、发亮、可见扩张血管与色素改变（须排查盘状红斑狼疮与萎缩性硬化性苔藓）；脱发同时出现眉毛、睫毛、胡须脱落或甲改变（须排查斑秃合并甲改变、甲状腺与结缔组织病）；头皮出现无痛性进行性增大的肿块、溃疡、反复出血（须警惕皮肤恶性肿瘤）；突然大量脱发伴高热、口腔溃疡、光过敏、关节痛（须排查系统性红斑狼疮）；脱发伴精神抑郁、焦虑、失眠或出现自伤念头（须及时进行心理干预）；规范治疗三至六个月仍无新发再生。用药禁忌：外用糖皮质激素与米诺地尔须遵医嘱使用，米诺地尔可致心悸、血压升高与多毛，孕妇与哺乳期禁用，心血管疾病者慎用；口服糖皮质激素与免疫抑制剂不可自行服用；育龄期女性使用抗雄激素治疗须严格避孕；中药首乌类制剂有肝损伤报告，须短期使用并监测肝功能，不宜与何首乌同用，肝功能异常者禁用；活血破血药（红花、三棱、莪术）孕妇禁用，服抗凝药者慎用；不可自行购买使用含重金属、激素的「速效生发液」；头皮有感染或破损处禁用刺激性外用药。"},{"type":"keypoints","title":"斑秃要点","items":["病位在头皮，病机为发失所养与络脉瘀阻，与肝、肾、血关系密切","血虚生风用神应养真丹、肝郁气滞用逍遥散、血瘀用通窍活血汤、肾虚用七宝美髯丹","辨证抓手：血虚见面色萎黄心悸、肾虚见腰酸耳鸣齿松、血瘀见舌暗有瘀斑、肝郁见情志相关","内服与外治并用，配合头皮按摩与心理疏导，一般需坚持三至六个月以上","全头脱发、头皮红肿脱屑、眉毛脱落、头皮肿块与免疫病征象者须及时就诊"]}]},{"id":"dongchuang","title":"冻疮","subtitle":"冻疮｜冷伤、冻疮（雷诺现象相关）","category":"外科皮肤","tags":["冷伤","寒凝血瘀","阳气不足","温经散寒","冻疮"],"meta":[{"label":"中医病名/证型概要","value":"冻疮（冷伤）。证型分寒凝血瘀、寒盛阳衰、气血虚弱、脾肾阳虚"},{"label":"主要症状","value":"手足、耳廓、鼻尖等末梢部位出现暗红或紫红色斑片、肿块，麻木疼痛，遇热则痒痛加剧，或见水疱、血疱与破溃"},{"label":"舌脉要点","value":"寒凝血瘀舌淡暗或有瘀斑苔白脉沉细或涩；阳虚舌淡胖苔白润脉沉迟无力；气血虚舌淡苔薄脉细弱"},{"label":"治则","value":"温经散寒、活血通络为基本法，兼温阳益气、养血荣筋，重在预防与局部保暖"}],"image":"","imageHint":"冻疮","summary":"冻疮中医称冻疮或冷伤，是冬季寒冷环境下末梢部位（手指、手背、耳廓、鼻尖、足跟）出现的局部皮肤损害，以暗红紫红色斑片、肿块、麻木疼痛、遇热奇痒为特征。病机为寒邪侵袭，血脉凝滞，血行不畅则瘀；素体阳气不足者更易发病且症状更重。辨证分寒凝血瘀、寒盛阳衰、气血虚弱与脾肾阳虚四型。治疗以温经散寒、活血通络为主，重在预防：保暖、避免骤冷骤热、适度户外锻炼与增强体质。","blocks":[{"type":"paragraph","text":"冻疮的病位在肌肤血脉，其核心病机为寒邪侵袭、血脉凝滞。寒为阴邪，主收引、主凝滞，冬季气候严寒，寒邪直中肌肤经络，血管收缩、血行不畅，肌肤失于温煦与濡养，故出现麻木、疼痛、皮色苍白或暗紫；寒凝日久，气血运行更加迟滞而成瘀，瘀阻脉络则皮色紫暗、肿块硬结、痛处固定、遇热则痒痛交作，甚则血瘀化热而出现水疱、血疱与破溃糜烂；若素体阳气不足（脾肾阳虚），阳不制寒、卫外不固，则寒邪易入、遇寒即发、反复不愈，且多见畏寒肢冷、腰膝酸软等全身表现；气血虚弱者，血不荣养肌肤、抗寒能力低下，故手足末端循环不良、易生冻疮且愈合缓慢。特点方面，冻疮好发于末梢循环较差部位，冬季高发、气温回升后多自行缓解，春夏反复发作，多见于儿童与青少年、妇女、户外工作者与雷诺现象患者。其发生与气候、湿度、风速、衣着、营养、吸烟及基础疾病密切相关。治疗须内外结合，内服温经散寒、活血通络之剂，外用活血消肿之品，并着重于「预防胜于治疗」。"},{"type":"table","caption":"冻疮辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["寒凝血瘀证","手足指趾、耳廓、鼻尖出现暗红或紫红色斑片，麻木疼痛，遇热则痒痛加剧，皮损硬结，舌淡暗或有瘀斑，苔白，脉沉细或涩","温经散寒，活血通络","当归四逆汤","寒甚加吴茱萸、细辛、干姜；瘀重加红花、桃仁、鸡血藤；痛甚加延胡索、乳香"],["寒盛阳衰证","全身畏寒，四肢厥冷，面色苍白，神疲乏力，患处皮肤苍白麻木、感觉减退，甚至出现水疱与血疱，舌淡苔白滑，脉沉微","回阳救逆，助阳通脉","四逆汤合当归四逆汤","阳衰甚加附子、干姜、桂枝；水疱加茯苓、薏苡仁；局部用温热敷"],["气血虚弱证","手足末端皮肤苍白或紫暗，麻木疼痛，畏寒肢冷，面色少华，神疲乏力，舌淡苔薄白，脉细弱","益气养血，温经通络","黄芪桂枝五物汤合当归四逆汤","气虚加党参、白术；血虚加熟地、鸡血藤、阿胶；畏寒加桂枝、细辛"],["脾肾阳虚证","冻疮反复发作，患处皮肤苍白干燥，畏寒肢冷，腰膝酸软，神疲乏力，夜尿频多，舌淡胖苔白润，脉沉迟无力","温补脾肾，益气温经","附子理中丸合金匮肾气丸","肾阳虚甚加仙茅、巴戟天、鹿角霜；脾虚加黄芪、党参、白术；冻疮处加红花、透骨草"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴阿是穴（患处周围）、大椎、足三里、三阴交；寒凝血瘀加膈俞、血海、委中，寒盛阳衰加关元、命门，气血虚加气海、脾俞，脾肾阳虚加肾俞、太溪","bullets":["阿是穴围刺与点刺放血（少量）可改善局部循环","关元、命门、足三里宜用艾灸温阳","留针二十至三十分钟，每日或隔日一次，急性期可每日一次"]},{"icon":"🔥","title":"艾灸与温热外治","text":"艾灸患处与足三里、关元，每穴十五分钟；中药外洗可用桂枝、红花、川芎、当归煎汤浸洗患处，水温三十八度左右；冻疮膏、维A酸类外用可按医嘱使用","bullets":["冻疮处施灸与温洗温度不宜过高，防低温烫伤与皮肤破溃","已出现水疱、血疱者不宜用力揉搓或穿刺","不宜用雪水或冰水直接敷患处，以免加重损伤"]},{"icon":"🤲","title":"推拿按摩","text":"患处轻柔按摩、揉搓至温热，循手足三阴三阳经推按；重点按揉阳池、外关、合谷、阳陵泉、涌泉，每穴一至两分钟；并做握拳、松指与腕关节旋转动作","bullets":["按摩宜在温暖环境下进行，手法宜轻柔","每次五至十分钟，每日二至三次","已有水疱破损处只可轻触周围，禁重按患处"]}]},{"type":"paragraph","text":"冻疮的饮食调养以温阳散寒、益气养血为原则，并按证配餐。寒凝血瘀者宜温经散寒、忌一切生冷寒凉与冰饮，可饮姜枣茶、当归生姜羊肉汤、桂枝汤类食疗，食生姜、红枣、羊肉、桂圆、桂皮、小茴香；寒盛阳衰者宜温阳散寒、忌寒凉生冷，可食核桃、栗子、羊肉、干姜炖羊肉；气血虚弱者宜益气养血、忌生冷与过饥，可食黄芪炖鸡、当归生姜羊肉汤、桂圆红枣茶、瘦猪肉、猪肝、菠菜；脾肾阳虚者宜温补脾肾、忌一切寒凉，可食核桃、栗子、黑芝麻、桑葚、枸杞、羊肉、杜仲炖腰子。日常须保证足够热量与优质蛋白摄入，注意补充铁、锌与维生素C（可食动物肝脏、瘦肉、海参、坚果、绿叶蔬菜）；忌大量生冷水果、冰饮与冷食；忌烟（尼古丁致血管收缩，加重局部缺血）；冬季适量饮用温热的姜枣茶或黄芪红枣茶；控制血糖与血脂，因糖尿病患者冻疮更易感染、溃疡与不愈。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：冬季注意全身与末梢保暖，重点护住头部、颈部、耳廓、手足与足跟，穿宽松分层的保暖衣物，内层宜吸汗棉质、外层防风；戴手套时避免过紧压迫，注意手套内层干燥；不宜在严寒中长时间静止不动，避免在寒风中久站、久骑自行车与户外作业过久；室内外冷热交替时避免骤遇高温（如进入暖气房立即用热水烫手），宜循序渐进回暖；每天温水（三十七度左右）洗手洗脚后立即擦干并涂润肤剂；不宜用炉火、暖水袋、热水直接烘烤患处，须隔一层布并控制时间以免低温烫伤；室内供暖注意通风与湿度，忌过度干燥。运动：冬季宜进行适度的户外运动（快走、慢跑、骑车、跳绳、滑雪）以促进末梢血液循环，每日不少于三十分钟；运动前充分保暖、充分热身后再暴露于冷环境；运动后及时擦干汗液、换干衣物并保暖；避免长时间静止不动的姿势；可作握拳、松指、腕踝旋转与搓手等局部热身动作。预防：预防的关键在于保暖与促进循环；每年冻疮发作前即开始预防性护理；有雷诺现象、结缔组织病、糖尿病、下肢动脉疾病、甲状腺功能减退与严重贫血者须积极治疗基础病；反复发作或溃疡不愈者须专科评估。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：冻疮处出现水疱、血疱或破溃、渗液、结黑色干痂；局部红肿热痛迅速加重、发热（须警惕蜂窝织炎与坏死性感染）；手指出现在寒环境下变白、变紫、变红三色变化伴麻木疼痛、溃烂（雷诺现象或闭塞性动脉硬化症，须查免疫指标与甲功）；溃疡长期不愈、边缘不整齐、渗血或恶臭（须排查感染与皮肤恶性肿瘤）；出现肌肉关节疼痛、皮肤苍白无汗、意识障碍、呕吐（重度冻伤伴低体温，须立即急诊复温）；出现指端坏疽、肢端冰冷无感觉、脉搏不能触及（须立即血管外科处理）；伴面部浮肿、蛋白尿（须排查肾病相关雷诺现象）；反复严重冻疮伴脱发、雷诺现象与关节痛（须排查系统性红斑狼疮）。用药禁忌：冻疮已破溃、有感染或渗液者禁用水温过高的浸泡与热敷；外用激素类药膏禁用于破溃与感染创面；口服血管扩张剂（钙通道阻滞剂、前列地尔等）可致头晕、下肢水肿，须由医师处方并监测；抗凝药与扩血管药联用须谨慎；局部麻醉剂与含辣椒素的外用制剂可刺激创面，破溃处禁用；中药外洗方含附子、川乌、草乌等有毒大热之品者，必须由医师配制指导使用，皮肤破损与感觉减退者禁用；严禁用火烤、泡热水、用力揉搓与挑破水疱等错误处理方式；糖尿病患者冻疮处理须格外谨慎，宜尽早就医。"},{"type":"keypoints","title":"冻疮要点","items":["病机核心为寒邪侵袭、血脉凝滞，血瘀与阳虚互为因果","寒凝血瘀用当归四逆汤，寒盛阳衰用四逆汤合当归四逆汤，气血虚弱用黄芪桂枝五物汤合当归四逆汤，脾肾阳虚用附子理中丸合金匮肾气丸","辨证抓手：皮色紫暗硬结属瘀，畏寒肢冷脉沉微属阳衰，面色少华脉细弱属血虚，腰膝酸软脉沉迟属脾肾阳虚","预防重于治疗：末梢保暖、避免骤冷骤热、适度冬季运动、忌烟、控制血糖血脂","出现水疱破溃、剧痛发热、指端三色变化或坏疽者须立即就医"]}]},{"id":"manxingyanyan","title":"慢性咽炎","subtitle":"慢性咽炎｜慢性喉痹、慢喉痹","category":"五官","tags":["慢喉痹","咽干痒","肺肾阴虚","痰气郁结","咽部不适"],"meta":[{"label":"中医病名/证型概要","value":"慢喉痹（喉痹）。证型分肺肾阴虚、脾气虚、痰气郁结、肝郁气滞、阴虚燥热"},{"label":"主要症状","value":"咽部干燥微痛、灼热不适、异物感或痰粘着感，频频清嗓、咽痒干咳，晨起或夜间加重，吞咽不利但无明显梗阻"},{"label":"舌脉要点","value":"肺肾阴虚舌红少苔脉细数；脾气虚舌淡苔白腻脉缓弱；痰气郁结舌淡红苔薄腻脉弦滑"},{"label":"治则","value":"养阴润燥、清利咽喉为基本法，兼健脾益气、化痰理气、疏肝解郁，忌苦寒与辛温燥烈"}],"image":"","imageHint":"咽炎","summary":"慢性咽炎中医称慢喉痹，以咽部干燥、灼热、异物感、痰粘着感与频繁清嗓为主要表现，反复发作、迁延不愈。病位在咽，与肺、脾、肾、肝关系密切。肺开窍于鼻、肾脉循咽喉、脾开窍于口，肺肾阴虚则咽喉失养而干痒灼热；脾胃虚弱则痰湿内生上阻咽喉而异物感明显；肝气郁结、情志不遂则气机不畅、津液不布而咽中如堵。本病常与用嗓过度、烟酒刺激、空气污染、鼻部与消化道慢性炎症、职业用嗓有关。治疗须重视养阴润燥与生活方式干预，慎用抗生素与激素。","blocks":[{"type":"paragraph","text":"慢性咽炎的病位在咽，涉及肺、脾、肾、肝与胃。肺主气司呼吸，其脉循咽喉上出颊咽，肺阴不足则咽喉失于濡润而干痒、灼热、微痛、痰少难咯；肾脉循喉咙上系舌本，肾阴亏虚、虚火上炎，则咽喉干燥而痛、颧红潮热、盗汗干咳，缠绵难愈；脾胃为后天之本，脾虚运化失健则水湿不化、聚湿成痰，痰湿上阻咽喉，致咽中异物感明显、痰多而黏、频作清嗓；肝主疏泄，肝气郁结则气机不畅、津液输布受阻，咽中如有物梗阻、咯之不出、咽之不下，随情志波动而增减，且胸胁胀满、善太息。病机可归纳为「阴虚为本、痰气为标」，初病多实（痰气郁结）、久病多虚（肺肾阴虚、脾气虚），亦常虚实夹杂。诱因方面，用嗓过度（教师、歌手、接线员）致气机不畅、津液耗伤；烟酒辛辣煎炸之品刺激咽部并伤津；空气污染、粉尘与化学气体长期刺激；鼻部慢性炎症分泌物倒流刺激咽部（鼻后滴漏）；胃食管反流夜间刺激咽喉；免疫功能低下与季节气候变化均可致本病反复。治疗须辨明虚实、以润为要，忌苦寒泻火、忌辛温发散。"},{"type":"table","caption":"慢性咽炎辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["肺肾阴虚证","咽部干燥，微痛，灼热感，午后或夜间加重，干咳少痰或痰黏难咯，咽中痒，颧红盗汗，口干不欲饮，舌红少苔，脉细数","滋养肺肾，清利咽喉","养阴清肺汤","咳甚加川贝、枇杷叶、百合；咽干甚加麦冬、玄参、生地；盗汗加浮小麦、五味子"],["脾气虚证","咽部不适，痰多而黏、色白易咯，脘闷纳呆，倦怠乏力，大便溏薄，面色萎黄，舌淡苔白腻，脉缓弱","健脾益气，化痰利咽","六君子汤加味","痰多加半夏、陈皮、浙贝；咽中堵加香附、郁金、桔梗；乏力加黄芪、党参"],["痰气郁结证","咽中如有物梗阻，咯之不出、咽之不下，痰黏难咯，胸闷脘痞，恶心纳呆，情志不畅时加重，舌淡红苔薄腻，脉弦滑","化痰理气，解郁利咽","半夏厚朴汤合甘麦大枣汤","气郁甚加柴胡、郁金、香附；痰热加黄芩、瓜蒌、浙贝；咽痒加蝉蜕、僵蚕"],["肝郁气滞证","咽中异物感明显，胸胁胀满，善太息，烦躁易怒，咽干而痒，症状随情绪波动，妇女可伴月经不调，舌淡红苔薄白，脉弦","疏肝解郁，理气利咽","柴胡疏肝散（或逍遥散）","郁热加丹皮、栀子；咽干加玄参、麦冬；胁胀加郁金、川楝子"],["阴虚燥热证","咽部干涩灼热而痒，频频清嗓而无痰，或痰少如白膜，咽痛隐隐，口干唇燥，夜间及饮水后稍缓，舌红少津，脉细数","养阴润燥，清咽利喉","养阴清肺汤合增液汤","干燥甚加沙参、麦冬、玄参；咽痛加桔梗、射干、山豆根；干咳加川贝"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴合谷、廉泉、扶突、天突、尺泽、少商；肺肾阴虚加太溪、三阴交，脾气虚加足三里、脾俞，痰气郁结加丰隆、太冲，肝郁加行间、期门","bullets":["合谷、廉泉为利咽要穴，针感向咽部传导为佳","少商点刺放血少量可泄热利咽，急性咽痛常用","留针二十至三十分钟，每日或隔日一次，十次为一疗程"]},{"icon":"🤲","title":"推拿按摩","text":"颈部推拿取风池、风府、廉泉、天突、喉结旁（人迎、水突）、翳风；按揉合谷、少商、尺泽、鱼际；沿任脉自上而下推按任脉、督脉","bullets":["喉部手法宜轻柔，以舒适为度，禁重压","每次十分钟，每日一至二次，配合吞咽动作","配合颈部放松与发声训练有助改善用嗓习惯"]},{"icon":"🫖","title":"雾化与咽部护理","text":"遵医嘱行雾化吸入可缓解干痒与炎症；可于饭后用淡盐水或温开水漱口、饮温水；长期用嗓者可作咽喉发声训练（哼鸣、唇颤音、气息练习）","bullets":["雾化须使用医用蒸馏水并按医嘱配药","每次雾化后漱口并洗脸，避免残留刺激","发声训练循序渐进，避免用力和喊叫"]}]},{"type":"paragraph","text":"慢性咽炎的饮食调养以养阴润喉、清淡为要，随证配餐。肺肾阴虚与阴虚燥热者宜滋阴润肺、清利咽喉，忌辛辣煎炸、烧烤、烈酒与温燥之品，可食银耳百合羹、百合莲子粥、桑葚膏、雪梨、鸭梨、枇杷、橄榄、罗汉果、麦冬、沙参、玉竹、蜂蜜（幼儿不宜）；脾气虚者宜健脾益气化痰，忌生冷寒凉与油腻黏腻，可食山药粥、薏仁山药粥、莲子粥、白扁豆粥、茯苓、瘦肉、陈皮；痰气郁结与肝郁者宜疏肝理气、化痰散结，忌收敛酸涩（乌梅、石榴、南瓜籽、过浓茶汤）与滋腻碍气之品，可饮玫瑰花茶、佛手陈皮茶、菊花茶、麦冬茶，食佛手、香橼、玫瑰花、芹菜、萝卜。日常须严格戒除烟酒、浓茶与咖啡；不吃辛辣、过烫、过咸、过干与油炸食物；进食时细嚼慢咽，避免用力吞咽与边吃边说话；每日饮水一千五百至二千毫升以润咽；避免用力清嗓、频繁咽口水与大声喊叫；居室保持空气流通与适宜湿度，避免粉尘、化学气体与油烟刺激；饭后不要立即平卧以减少胃食管反流刺激咽喉。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：保证每日七至八小时睡眠，避免熬夜（肝胆湿热与阴虚火旺皆因作息紊乱而加重）；居室保持空气清新，避免粉尘、装修污染与二手烟，干燥季节可使用加湿器但须定期清洁；注意保暖，避免冷空气与寒凉刺激直接吸入而诱发咽部不适；避免过度用嗓，教师、歌手、客服等职业者应合理安排用嗓时间，感冒期间严格休声；饭后保持直立或站立三十分钟，睡前抬高床头以减少夜间反流刺激；保持口腔卫生，早晚刷牙并定期洁牙。运动：规律有氧运动（快走、慢跑、游泳、太极、八段锦）有助改善体质与情绪，每周一百五十分钟；配合咽喉保健操（撮空、叩齿、咽津、按揉廉泉）与颈肩放松训练；避免在空气污浊、寒风凛冽或烟尘环境中长时间户外锻炼；运动后及时饮水并做温和的咽喉放松。预防：积极治疗鼻窦炎、过敏性鼻炎与胃食管反流等邻近疾病以去除持续刺激源；纠正用嗓与呼吸习惯；四季变化时注意增减衣物、饮食清淡与作息规律以减少复发；反复发作或伴吞咽障碍者须尽早专科评估。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：咽部疼痛剧烈、吞咽困难明显、进食与饮水困难（须警惕扁桃体炎、喉炎与会厌炎）；伴高热、畏寒、颌下淋巴结肿大（须排查化脓性扁桃体炎）；咽部单侧持续疼痛、异物感不减轻、咯血或回吸性血痰、声嘶持续两周以上不缓解（须警惕咽喉部恶性肿瘤）；颈部摸及肿块、肿大淋巴结；痰中带血、持续咳嗽伴消瘦、盗汗、低热（须排查肺结核与肺部肿瘤）；口干、眼干、关节痛、皮肤干燥（须排查干燥综合征与干燥综合征）；返酸、烧心、咽部酸腐感（须排查胃食管反流病）；打鼾伴夜间呛咳（须排查睡眠呼吸暂停）；突发声音嘶哑伴呼吸困难（须急诊排查喉梗阻）。用药禁忌：抗生素不适用于非细菌性咽炎，滥用可致耐药与菌群失调；含马来酸氯苯那敏的复方感冒药可致口干而加重咽部不适；不宜长期使用含激素的含片或雾化激素，须在医师指导下短期使用并逐渐减停；苦寒清咽之品（黄连、黄柏、栀子、大黄、番泻叶）不可长期服用以免损伤脾胃与津液；辛温发散类（麻黄、桂枝、细辛）在阴虚咽干者当慎用；孕妇、哺乳期妇女与儿童使用含片、喷雾与含碘消毒制剂须遵医嘱；含碘喉片与双氧水漱口液不宜长期使用；警惕中药含马钱子、雄黄等有毒成分的制剂。"},{"type":"keypoints","title":"慢性咽炎要点","items":["病机为阴虚为本、痰气为标，肺肾阴虚用养阴清肺汤、脾气虚用六君子汤、痰气郁结用半夏厚朴汤合甘麦大枣汤、肝郁用柴胡疏肝散","辨证抓手：干痒灼热属阴虚，痰多清嗓属脾虚痰湿，咽中如堵随情志加重属气郁","治疗须以养阴润燥为主，忌苦寒泻火与辛温发散，忌长期使用激素与抗生素","去除刺激源是关键：戒烟酒、治鼻部疾病、治胃食管反流、避免粉尘与过度用嗓","伴吞咽困难、咯血、颈部肿块、持续声嘶超过两周者须及时排查器质性与恶性病变"]}]},{"id":"biyan","title":"鼻炎","subtitle":"鼻炎｜过敏性鼻炎、鼻窦炎、鼻渊","category":"五官","tags":["鼻鼽","鼻渊","肺气虚寒","胆腑郁热","喷嚏流涕"],"meta":[{"label":"中医病名/证型概要","value":"鼻鼽（过敏性鼻炎）、鼻渊（鼻窦炎）。鼻鼽分肺气虚寒、脾气虚、肺经风热；鼻渊分胆腑郁热、脾经湿热、肺经风热、肺脾气虚"},{"label":"主要症状","value":"阵发性连续喷嚏、清水样鼻涕、鼻痒、鼻塞、嗅觉减退，或鼻流浊涕黄稠、头胀额痛、眉棱骨痛"},{"label":"舌脉要点","value":"肺气虚寒苔薄白脉浮无力；肺经风热苔薄黄脉浮数；胆腑郁热苔黄腻脉弦数；脾经湿热苔黄腻脉濡数"},{"label":"治则","value":"鼻鼽重在益气固表、宣肺通窍，鼻渊重在清热利湿、通窍排脓，兼扶正"}],"image":"","imageHint":"鼻炎","summary":"鼻炎包括过敏性鼻炎（鼻鼽）与鼻窦炎（鼻渊），是五官科常见病。以阵发性喷嚏、清水样鼻涕、鼻痒鼻塞为鼻鼽主症，以鼻流浊涕黄稠、鼻塞、头胀疼痛、嗅觉减退为鼻渊主症。病位在鼻，与肺、脾、胆密切相关：肺开窍于鼻，肺气虚寒则卫外不固、腠理疏松而喷嚏流清涕；风热犯肺则鼻塞流浊涕；胆经郁热上犯于鼻则鼻渊流黄浊涕；脾经湿热上蒸则鼻流稠浊。治疗须分清鼻鼽与鼻渊，分别采用益气固表与清热利湿之法，同时积极寻找过敏原与邻近病灶。","blocks":[{"type":"paragraph","text":"鼻病的病位在鼻，与肺、脾、胆、肝、肾相关。《素问·宣明五气》曰「鼻为肺之窍」，肺主气司呼吸，开窍于鼻，肺气宣畅则鼻通气畅；肺卫气虚则卫外不固、腠理疏松，风寒异气乘虚而入，内应于肺，肺气失宣，津液不布而鼻痒、喷嚏连连、清涕如注，此为鼻鼽之肺气虚寒；风热犯肺或肺经郁热，热邪灼津，涕液变稠而黄浊，鼻塞不通；肝胆湿热或胆腑郁热循经上犯，胆经上行至头侧，郁热上蒸于鼻，浊涕引流不畅而致鼻渊，症见鼻流浊涕黄稠、鼻塞、嗅觉减退、头额胀痛；脾主运化，脾虚则运化失健、卫外不固，故鼻鼽反复、迁延难愈并兼纳差便溏、倦怠乏力；脾经湿热上蒸于鼻则鼻流稠浊而黄。此外，鼻渊日久可伤脾肺，形成肺脾气虚之鼻鼽；鼻鼽兼鼻渊者临床常见且相互影响。诱因方面，接触花粉、尘螨、霉菌、动物皮屑、冷空气与刺激性气味是鼻鼽的主要诱因，鼻窦炎则多继发于感冒、上颌牙根感染、鼻腔解剖异常与鼻中隔偏曲。治疗上鼻鼽重在治本固表、兼以祛邪，鼻渊重在清热排脓通窍，急性期以祛邪为主，慢性期以扶正通窍为要。"},{"type":"table","caption":"鼻炎辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["肺气虚寒证（鼻鼽）","阵发性连续喷嚏，清水样鼻涕，鼻痒，鼻塞，嗅觉减退，遇风寒或晨起加重，自汗怕风，易感冒，舌淡苔薄白，脉浮无力","益气固表，宣肺通窍","玉屏风散合苍耳子散","自汗加浮小麦、麻黄根；鼻塞甚加辛夷、蝉蜕；喷嚏多加地龙、乌梅"],["脾气虚证（鼻鼽）","鼻塞流涕反复迁延，伴倦怠乏力，纳少便溏，面色萎黄，少气懒言，舌淡胖苔白，脉缓弱","健脾益气，升阳通窍","补中益气汤合苍耳子散","气虚甚加党参、黄芪；便溏加山药、莲子；鼻塞加辛夷、白芷"],["肺经风热证（鼻鼽或鼻渊初起）","鼻塞，鼻流黄稠涕或黄水样涕，发热恶风，头痛，咽干口渴，嗅觉减退，舌红苔薄黄，脉浮数","辛凉宣肺，通窍清热","银翘散合苍耳子散","浊涕多加黄芩、瓜蒌、鱼腥草；头痛加川芎、蔓荆子；咽痛加牛蒡子、射干"],["胆腑郁热证（鼻渊）","鼻流黄稠浊涕量多，腥臭，鼻塞，嗅觉减退，头胀额痛或眉棱骨痛，口苦咽干，急躁易怒，舌红苔黄腻，脉弦数","清胆泻热，通窍排脓","龙胆泻肝汤","浊涕多加鱼腥草、蒲公英、桔梗；头痛加川芎、柴胡；鼻塞加辛夷、苍耳子"],["脾经湿热证（鼻渊）","鼻流黄稠浊涕，鼻塞，嗅觉减退，头晕头重，脘闷纳呆，倦怠，大便黏滞，舌淡红苔黄腻，脉濡数","清热利湿，通窍化浊","茵陈蒿汤合二妙散加减","湿重加茯苓、薏苡仁、冬瓜皮；浊涕加桔梗、辛夷；头晕加菖蒲、藁本"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴迎香、印堂、攒竹、合谷、列缺、风池；肺气虚寒加肺俞、气海，脾气虚加脾俞、足三里，风热加大椎、曲池，胆腑郁热加侠溪、行间，湿热加阴陵泉、内庭","bullets":["迎香、印堂为主穴，针刺宜向鼻方向斜刺以通鼻窍","肺气虚寒者加灸肺俞、足三里以固表","留针二十至三十分钟，每日或隔日一次，十次为一疗程"]},{"icon":"🤲","title":"推拿按摩","text":"鼻部推拿取迎香、印堂、睛明、攒竹、太阳；额部与面部轮推；颈项揉拿风池、风府；配合按揉足三里与肺俞；鼻翼两侧以指腹轻揉","bullets":["鼻部手法宜轻柔，勿用力捏挤鼻翼","每次十分钟，配合鼻翼两侧按摩有助通窍","配合迎香精油按摩须确认无过敏"]},{"icon":"🌿","title":"耳穴与鼻腔护理","text":"耳穴贴压取肺、脾、胆、内鼻、咽喉、神门、过敏区，双耳交替贴压三至五日；鼻腔可用生理盐水冲洗（须用专用洗鼻壶），鼻渊者遵医嘱行鼻窦冲洗","bullets":["洗鼻须用生理盐水或专用制剂，禁用手挤压或吸鼻器猛吸","冲洗后按医嘱使用鼻用激素与减充血剂","注意鼻腔湿润，干燥季节可用生理盐水喷雾"]}]},{"type":"paragraph","text":"鼻病的饮食调养以清淡、辨证、避免诱发为要。肺气虚寒（鼻鼽）者宜益气固表、忌生冷寒凉与过食生冷瓜果，可食山药粥、黄芪粥、莲子百合粥、桂圆红枣、羊肉、生姜、葱白、粳米；脾气虚者宜健脾益气、忌油腻黏滞与过饥，可食山药、白扁豆、莲子、茯苓、薏苡仁、瘦肉、大枣；肺经风热与胆腑郁热者宜清热利胆、忌辛辣煎炸、烧烤、酒类、火锅与海鲜，可饮菊花茶、桑叶茶、菊花决明茶、绿豆汤、胖大海茶，食冬瓜、丝瓜、苦瓜、绿豆、荸荠；脾经湿热者宜清热利湿、忌肥甘厚味与甜腻，可食冬瓜、丝瓜、赤小豆、薏苡仁、土茯苓。日常须注意：有过敏性鼻炎者应严格回避已知过敏原（花粉、尘螨、霉菌、宠物皮屑、某些食物与药物），并做饮食日记以协助查找不耐受食物；忌酒与冷饮，忌辛辣刺激与过冷食物（冷饮会使鼻黏膜血管收缩而加重鼻塞）；每日保证饮水与富含维生素C、锌与优质蛋白的食物（新鲜蔬果、瘦肉、坚果、牡蛎）；咳嗽与喷嚏发作时以纸巾掩口鼻并及时更换，避免交叉感染。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：居室保持清洁通风，勤晒被褥、经常除尘以减少尘螨；避免装修污染、烟草烟雾、油漆与消毒剂等刺激物；床单被套每周用热水（五十五度以上）清洗以杀灭尘螨；花粉季节减少户外活动，出门戴口罩与眼镜，回家后洗脸、洗鼻、换外衣；花粉高峰期关窗并使用空气净化器；鼻渊患者保持鼻腔通畅与清洁，按医嘱行鼻腔冲洗；居室湿度适宜，避免过度干燥导致鼻黏膜脆弱与易出血；避免用手揉鼻、挖鼻与用力擤鼻（可致鼻前庭炎、鼻出血与鼻中隔损伤），擤鼻应一侧一侧轻擤；保证充足睡眠与适度运动以增强体质。运动：规律有氧运动（快走、慢跑、游泳、太极、八段锦、瑜伽）可减轻鼻部症状并改善免疫，每周一百五十分钟；配合迎香、印堂、攒竹的按揉与鼻翼按摩，每日二次；鼻渊患者可作低头位引流配合拍背；避免在花粉高峰、雾霾与寒冷大风天长时间户外锻炼。预防：积极治疗慢性鼻炎、鼻窦炎、腺样体肥大、扁桃体炎与胃食管反流，消除慢性刺激源；反复鼻塞伴张口呼吸、睡眠打鼾的儿童须查腺样体与过敏性鼻炎；明确过敏原者可在医师指导下行特异性免疫治疗（脱敏）；规范使用鼻用激素是控制鼻鼽的一线方案，须坚持足疗程而非症状缓解即停；避免长期使用减充血剂滴鼻液以免引起药物性鼻炎；反复鼻窦炎者由耳鼻喉科评估是否需要手术。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：鼻塞持续不缓解、单侧鼻腔完全阻塞、反复鼻出血；鼻涕带血或为脓性、有明显臭味；面部或额头胀痛、头痛、牙痛伴发热（须排查鼻窦炎与牙源性感染）；眼球突出、视力下降、眼球活动受限、复视（须警惕鼻窦炎并发眶内感染或鼻窦真菌病，须急诊）；鼻痒阵发剧烈喷嚏伴全身荨麻疹、喉头紧缩感、头晕（须警惕严重过敏反应）；幼儿鼻塞影响睡眠、进食、发育；长期嗅觉减退；反复鼻窦炎需评估鼻中隔偏曲、鼻甲肥大、腺样体肥大等结构问题。用药禁忌：鼻用减充血剂（如羟甲唑啉）连续使用不超过七天，以免发生药物性鼻炎与鼻黏膜萎缩；口服抗组胺药可致嗜睡与口干，驾驶与高空作业者慎用；鼻用激素须按疗程规范使用，症状控制后逐步减量，不可自行长期滥用；孕妇、哺乳期妇女使用鼻用激素须遵医嘱，禁用部分减充血剂；不宜自行长期服用中药「通窍」制剂（含麝香、辛夷、苍耳子等）以免肝肾损伤；苍耳子有小毒，须按医嘱使用与控制剂量，不可自行煎服过量；不宜自行使用抗生素治疗普通鼻炎；严禁用手指或其他异物抠挖鼻腔。"},{"type":"keypoints","title":"鼻炎要点","items":["鼻鼽以喷嚏、清涕、鼻痒为特征，重在益气固表（玉屏风散合苍耳子散）；鼻渊以浊涕、鼻塞、头胀痛为特征，重在清热利湿通窍（龙胆泻肝汤等）","辨证抓手：清涕清稀属虚寒，浊涕黄稠属实热，脾虚者迁延反复兼纳差乏力，胆热者兼口苦烦躁头胀痛","去除刺激源与明确过敏原是长期控制的关键：尘螨、花粉、霉菌、宠物皮屑与冷空气","鼻用激素须坚持规范疗程，不可症状缓解即停；减充血剂连续使用不超过七天","鼻涕带血、单侧完全阻塞、眼球突出与视力下降者须立即就医排查严重病变"]}]},{"id":"bizheng","title":"痹证","subtitle":"痹证｜风湿性关节炎、类风湿关节炎","category":"其他","tags":["痹证","风寒湿热","行痹痛痹着痹","关节疼痛","久痹入络"],"meta":[{"label":"中医病名/证型概要","value":"痹证（风湿痹、痛风）。证型分行痹、痛痹、着痹、热痹、痰瘀痹阻、肝肾两虚"},{"label":"主要症状","value":"肢体关节疼痛、酸楚、重着、屈伸不利，或关节红肿灼热、肿胀变形，晨僵，活动受限，疼痛常随天气变化而加剧"},{"label":"舌脉要点","value":"行痹苔薄白脉浮；痛痹苔白脉弦紧；着痹苔白腻脉濡缓；热痹舌红苔黄脉滑数；久痹舌暗脉沉细"},{"label":"治则","value":"祛邪通络、宣痹止痛为标，兼养肝肾、补气血、化痰祛瘀，后期重在扶正"}],"image":"","imageHint":"痹证","summary":"痹证是由于人体正气不足、风寒湿热等邪气侵袭经络、闭阻气血运行所致的病证，以肢体关节疼痛、酸楚、重着、屈伸不利，甚或关节肿大变形为主要表现，相当于风湿性关节炎、类风湿关节炎与痛风等。病位在肌肉关节经络，与肝、肾、脾关系密切，正虚是发病内因，风寒湿热是致病条件。辨证以风寒湿三气杂至偏胜而分行痹、痛痹、着痹，邪郁化热则为热痹，久病入络、痰瘀互结则成痰瘀痹阻，肝肾亏虚则病程迁延。治疗须重视内服与外治结合、标本兼顾与功能康复。","blocks":[{"type":"paragraph","text":"痹证的病位在肌肉、骨节、经络，与肝、肾、脾关系密切。《素问·痹论》指出痹病的成因是「风寒湿三气杂至，合而为痹」，并按邪气偏胜分为行痹（风胜）、痛痹（寒胜）、着痹（湿胜），后世称三痹；又指出痹久不去「内舍于其合」，日久可入脏腑。《素问·评热病论》「正气存内，邪不可干」揭示了正气不足是发病的内在基础，而风寒湿热之邪侵袭是外在条件，两者缺一不可。素体阳气不足、营卫不和、腠理不固，则风寒湿邪乘虚而入，闭阻经络，气血运行不畅，「不通则痛」而发病；病位上，湿邪留着于肌肉关节故重着酸楚，寒邪凝滞收引故疼痛剧烈、遇寒加重、得温则减，风邪善行数变故疼痛游走不定。若感邪热或风寒湿郁久化热，湿热相搏，壅遏经络关节，则见关节红肿灼热、疼痛拒按、发热口渴，属热痹（亦见于痛风急性期、类风湿活动期）；病久入络，气血运行不畅而瘀血内生，津液输布失常而痰浊凝聚，痰瘀互结于关节，则关节肿大变形、僵硬畸形、屈伸不利，形成痰瘀痹阻之顽痹；病久肝肾亏虚，精血不足，筋骨失养，则关节肿大变形、肌肉萎缩、腰膝酸软、畏寒乏力，为肝肾两虚。病性上，本虚标实：初期以邪实为主，久病以正虚为主，虚实夹杂者最多。"},{"type":"table","caption":"痹证辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["行痹（风痹）","肢体关节疼痛游走不定，部位不固定，恶风，关节屈伸不利，恶寒发热，苔薄白，脉浮","祛风通络，散寒除湿","防风汤","游走甚加羌活、独活、秦艽；肩痛加姜黄、桑枝；痛甚加延胡索、制川乌"],["痛痹（寒痹）","关节疼痛较剧，遇寒加剧，得温则减，关节不可屈伸，局部皮色不红、触之不热，畏寒喜暖，苔白，脉弦紧","温经散寒，祛风除湿","乌头汤","寒甚加附子、干姜、细辛；痛剧加制川乌、延胡索、桂枝；血虚加当归、鸡血藤"],["着痹（湿痹）","关节重着酸痛，痛处固定不移，肌肤麻木不仁，屈伸不利，阴雨天加重，苔白腻，脉濡缓","除湿通络，祛风散寒","薏苡仁汤","湿重加苍术、防己、蚕沙；麻木加鸡血藤、络石藤；痛甚加威灵仙、木瓜"],["热痹、痰瘀痹阻证","热痹者关节红肿灼热、疼痛拒按、触之热，伴发热口渴、便秘溲赤、舌红苔黄腻、脉滑数；痰瘀痹阻者病程日久、痛处固定刺痛、关节肿大变形僵硬、舌紫暗有瘀斑、苔白腻、脉涩","热痹者清热通络、祛风除湿，痰瘀痹阻者化痰祛瘀、搜风通络","热痹用白虎加桂枝汤，痰瘀痹阻用双合汤","热甚加忍冬藤、连翘、桑枝；肿甚加土茯苓、薏苡仁、防己；瘀重加全蝎、蜈蚣、地龙；痰结加夏枯草、浙贝、僵蚕"],["肝肾两虚证","病程迁延，关节肿大变形，屈伸不利，肌肉消瘦萎缩，腰膝酸软，畏寒乏力，或寒热错杂，舌淡苔薄，脉沉细","补益肝肾，祛风通络","独活寄生汤","肾阳虚加附子、鹿角霜；阴虚加生地、龟板；血虚加熟地、当归；痛甚加延胡索、桑寄生"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴阿是穴、局部经穴、大椎、身柱、阳陵泉、悬钟、阴陵泉；行痹加膈俞、血海，痛痹加肾俞、命门，着痹加丰隆、脾俞，热痹加大椎、曲池，久痹加膈俞、脾俞、肝俞、肾俞","bullets":["阿是穴（最痛点）与循经取穴结合，针刺得气并出现酸胀感为度","行痹与热痹用泻法，痛痹与着痹可加灸，肝肾两虚用补法","留针二十至三十分钟，每日或隔日一次，十次为一疗程"]},{"icon":"🤲","title":"推拿按摩与关节松动","text":"以推、拿、揉、搓、拔伸、摇法为主，先循经推拿再取阿是穴与局部手法，配合关节松动术、牵伸与肌力训练；急性红肿热痛期宜轻柔，忌强力扳法","bullets":["急性期以远端与轻手法为主，禁强力推拿与热敷","每次二十分钟，配合关节活动度训练","配合红外线、蜡疗等温热理疗有助晨僵缓解"]},{"icon":"🔥","title":"艾灸与药浴","text":"痛痹与着痹宜艾灸阿是穴、局部腧穴与督脉，每穴十五分钟；中药熏洗与药浴（伸筋草、透骨草、桂枝、威灵仙、川芎等）每次二十分钟，水温三十八至四十度","bullets":["热痹（红肿热痛）禁用艾灸与热敷","药浴水温不可过高，糖尿病与感觉障碍者须测温防烫伤","皮肤破损、静脉曲张处不宜药浴"]}]},{"type":"paragraph","text":"痹证的饮食调养以祛风除湿、通络止痛为原则，随证配餐。行痹者宜辛散祛风，忌生冷酸凉，可食生姜、葱、韭菜、芹菜、桑枝煎液、菊花茶；痛痹者宜温经散寒、忌一切生冷冰饮与寒凉果品，可食当归生姜羊肉汤、桂枝汤类食疗、羊肉、生姜、桂圆、红糖；着痹者宜健脾除湿、忌生冷油腻与甜腻黏滞，可食薏仁赤小豆粥、山药陈皮粥、冬瓜薏仁汤、白扁豆粥、茯苓、赤小豆、扁豆；热痹者宜清热利湿、忌辛辣煎炸、烧烤、酒类与温补，可食冬瓜、丝瓜、绿豆、土茯苓、薏苡仁、荸荠、芦根；痰瘀痹阻者宜活血化瘀、忌寒凉凝滞，可食黑木耳、桃仁、山楂、玫瑰花茶；肝肾两虚者宜补益肝肾、忌过度耗伤，可食黑芝麻、桑葚、核桃、枸杞、杜仲炖腰子、淮山、栗子。日常须注意：类风湿关节炎患者在使用糖皮质激素或免疫抑制剂期间尤其注意补充钙与维生素D、预防感染与骨质疏松，饮食宜富含优质蛋白（鱼、蛋、瘦肉、豆制品）、新鲜蔬果与含钙食物（奶制品、豆制品、小鱼干、芝麻）；痛风患者须严格限制高嘌呤食物（动物内脏、浓肉汤、火锅汤底、啤酒、含糖饮料）与果糖摄入，每日饮水两千毫升以上以促进尿酸排泄；发病期避免海鲜、啤酒与含糖饮料；不吸烟、不酗酒；注意居住环境温暖干燥，忌居处潮湿与冷水作业。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：居住与工作环境宜温暖干燥、通风，避免潮湿与寒冷刺激，注意保暖并避免汗出当风；坚持每天用温水洗浴或泡脚后擦干并保暖，忌冷水洗浴与游泳后不及时保暖；冬季注意护住关节，避免关节受凉后诱发加重；睡眠充足，保证每日七至八小时，避免熬夜；保持乐观情绪与规律作息，情绪波动会加重疼痛与晨僵。运动：急性红肿热痛期以休息为主，制动并抬高患肢，忌按摩热敷；缓解期应尽早开始规范的关节活动度训练、等长肌力训练与有氧运动（步行、游泳、骑车、太极、八段锦），每日三十分钟左右，配合温热疗法与关节松动手法；注意关节保护，使用护具、避免久跪久蹲与提重物；避免在寒冷潮湿环境锻炼，运动后及时擦干汗液并保暖；类风湿关节炎患者关节活动须在医师与康复治疗师指导下进行，勿自行强力扳动以免造成关节内损伤。预防：积极治疗咽喉与口腔感染、扁桃体炎等感染灶（部分风湿热与链球菌感染相关）；注意保暖防湿，避免久居湿地与冒雨涉水；家族有风湿病者定期筛查；类风湿关节炎一经确诊应尽早使用改善病情抗风湿药（DMARDs）以控制关节破坏，不可仅依赖止痛药与中药对症治疗；系统管理与规范随访可显著减少关节畸形与残疾。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：关节红肿热痛伴发热（须警惕化脓性关节炎与感染性关节炎，须急诊穿刺检查）；关节剧痛不能活动、局部明显肿胀发热；关节肿大变形、关节间隙明显狭窄、骨性强直（须评估手术指征）；颈项强痛伴四肢麻木无力、行走不稳、大小便障碍（须警惕类风湿颈椎病与脊髓受压）；突发关节红肿剧痛伴血尿酸升高（痛风急性发作）；长期服用糖皮质激素出现骨痛、多发骨折、血糖升高、血压升高、向心性肥胖与感染（须专科评估）；出现发热、口腔溃疡、皮疹、光过敏、关节痛与肾损害（须排查红斑狼疮等自身免疫病）；风湿热伴心悸、心前区不适（须警惕风湿性心脏病）；使用药物后出现皮疹、口腔溃疡、肝功能异常与白细胞减少。用药禁忌：非甾体抗炎药（NSAIDs）可致胃肠道出血、肾损害与心血管风险，胃溃疡、肾功能不全、心衰与高血压患者慎用或禁用；糖皮质激素不可自行减量或停用；免疫抑制剂（甲氨蝶呤、环磷酰胺等）须定期监测血常规与肝肾功能，备孕与孕期禁用；中药附子、川乌、草乌有大毒，须由医师严格掌握剂量与煎法，禁自行服用；雷公藤多苷片有生殖毒性与肝肾毒性，育龄者慎用、孕期禁用；痛风急性期不宜自行使用降尿酸药起始治疗（可诱发发作加重），须遵医嘱；抗生素类与激素类须按医嘱使用；发热与感染期须及时就医而非自行服中药掩盖症状。"},{"type":"keypoints","title":"痹证要点","items":["痹证基本病机为正气不足、风寒湿三气杂至闭阻经络；行痹用防风汤、痛痹用乌头汤、着痹用薏苡仁汤、热痹用白虎加桂枝汤、痰瘀痹阻用双合汤、肝肾两虚用独活寄生汤","辨证抓手：疼痛游走属风、剧痛遇寒加重属寒、重着酸困属湿、红肿灼热属热、固定刺痛变形属痰瘀","治疗须标本兼顾：初期祛邪通络为主，久病补益肝肾、化痰祛瘀，扶正祛邪兼顾","类风湿关节炎确诊后应尽早使用改善病情抗风湿药，中药与外治为辅，不可仅对症止痛","关节红肿热痛伴发热、颈髓压迫征象、长期激素副作用者须及时就医"]}]},{"id":"yaotong","title":"腰痛","subtitle":"腰痛｜腰肌劳损、腰椎间盘突出症、腰肌纤维炎","category":"其他","tags":["腰痛","腰肌劳损","寒湿腰痛","湿热腰痛","肾虚腰痛"],"meta":[{"label":"中医病名/证型概要","value":"腰痛。证型分寒湿腰痛、湿热腰痛、血瘀腰痛、肾阳虚腰痛、肾阴虚腰痛"},{"label":"主要症状","value":"腰部一侧或两侧疼痛、酸痛、重痛，劳累后加重、休息缓解，阴雨天与受凉后加剧，重者转侧困难、行走不便"},{"label":"舌脉要点","value":"寒湿舌淡苔白腻脉沉紧；湿热舌红苔黄腻脉濡数；血瘀舌紫暗有瘀斑脉涩；肾虚舌淡脉沉细"},{"label":"治则","value":"「腰痛治肾」为原则，寒者温之、湿者清之、瘀者行之、虚者补之，兼舒筋活络"}],"image":"","imageHint":"腰痛","summary":"腰痛是以腰部一侧或两侧疼痛为主要表现的常见症状病，可见于腰肌劳损、腰椎间盘突出症、腰肌纤维炎、强直性脊柱炎与肾脏疾病等。病位在腰部经络与肾，与肝脾相关。《素问·脉要精微论》曰「腰为肾之府」，肾主骨生髓，故腰痛与肾关系最为密切；足太阳、督脉循行腰背，故经脉痹阻亦可致痛；脾主运化，脾虚则湿邪内生。辨证以寒湿、湿热、血瘀与肾虚为纲，虚实夹杂者多见。治疗须内外并重，尤须重视姿势与负荷管理，避免久坐久站与不当用力。","blocks":[{"type":"paragraph","text":"腰痛的病位在腰部经络、筋骨与肾。病机有虚实两端：实证多因外感寒湿、湿热与跌仆外伤；虚证多因先天不足、年老体衰、劳倦过度、久病及肾。寒湿腰痛，因劳汗当风、久居湿地、冒雨涉水，寒湿之邪客于腰部经络，寒则收引凝滞、湿则重浊黏滞，气血运行不畅而痛，其特点是痛处冷重、转侧不利、阴雨天及遇寒加重、得温则减；湿热腰痛，多因嗜食辛辣肥甘、嗜酒或外感湿热，湿热下注于腰府，壅遏经脉而痛，其特点是痛处灼热、痛势急迫、遇热或雨天加重、伴口苦不渴、小便短赤；血瘀腰痛，多因跌仆外伤、久坐久站体位不当、闪挫使腰部气血壅滞，瘀血阻络而痛，其特点是痛有定处、刺痛拒按、俯仰转侧不利、昼轻夜重，舌质紫暗或有瘀斑；肾虚腰痛，《素问·脉要精微论》「腰为肾之府」，肾藏精、主骨，肾精不足则髓海失充、筋骨失养而腰酸无力，肾阳虚者畏寒肢冷、喜温喜按、劳则加重、卧则减轻，肾阴虚者心烦失眠、口燥咽干、舌红少苔。此外，肝主筋、脾主肌肉，肝血不足筋脉失养、脾气虚弱肌肉失养，亦可致腰酸。特点是腰痛常与劳作、姿势、气候密切相关，反复发作、缠绵不愈，故治疗与调摄并重，纠正不良体位与负荷习惯往往比单纯用药更为关键。"},{"type":"table","caption":"腰痛辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["寒湿腰痛","腰部冷痛重着，转侧不利，阴雨天或寒冷天气加重，得温则减，喜温喜按，舌淡苔白腻，脉沉紧或濡缓","散寒除湿，温经通络","甘姜苓术汤加减","寒甚加附子、干姜、桂枝；湿重加苍术、薏苡仁、独活；痛甚加杜仲、桑寄生、延胡索"],["湿热腰痛","腰部疼痛，痛势急迫，灼热感，痛处或痛处不发热亦喜冷，遇热或阴雨天加重，伴口苦不渴、小便短赤、大便秘结，舌红苔黄腻，脉濡数","清热利湿，舒筋通络","四妙丸合当归拈痛汤","热甚加黄柏、栀子；湿重加土茯苓、泽泻；痛甚加威灵仙、忍冬藤、防己"],["血瘀腰痛","腰痛如针刺，痛处固定，拒按，昼轻夜重，转侧俯仰困难，舌质紫暗或有瘀斑，脉弦涩","活血化瘀，行气通络","身痛逐瘀汤","痛甚加乳香、没药、全蝎；夹寒加桂枝、附子；夹虚加黄芪、当归"],["肾阳虚腰痛","腰部酸软无力，绵绵不休，喜温喜按，劳则加重、卧则减轻，腰膝酸软，畏寒肢冷，神疲乏力，舌淡苔白，脉沉细无力","温补肾阳，壮腰止痛","右归丸加减","寒甚加附子、肉桂、鹿角胶；腰痛甚加杜仲、续断、狗脊；纳差加山药、白术"],["肾阴虚腰痛","腰部酸痛，隐隐不休，腿膝酸软，头晕耳鸣，心烦失眠，口燥咽干，五心烦热，舌红少苔，脉细数","滋补肾阴，壮腰止痛","左归丸加减","阴虚甚加龟板、鳖甲、女贞子；腰痛甚加桑寄生、续断、狗脊；潮热加地骨皮、青蒿"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴肾俞、大肠俞、腰阳关、委中、阿是穴、昆仑；寒湿加命门、腰阳关、关元，湿热加阴陵泉、大椎、曲池，血瘀加膈俞、次髎，肾虚加太溪、命门、足三里","bullets":["肾俞与委中为要穴，委中可点刺放血少许以泄瘀通络","寒湿与肾虚者加灸，每穴十五分钟；湿热者只针不灸","急性剧痛期可先针后活动，留针二十至三十分钟"]},{"icon":"🤲","title":"推拿与功能训练","text":"腰部推拿取肾俞、命门、志室、腰阳关、八髎、委中与阿是穴，以滚、揉、按、弹拨、擦法为主；配合核心肌群训练（臀桥、平板支撑、小燕飞、鸟狗式）与柔韧拉伸","bullets":["推拿每日或隔日一次，每次二十分钟，手法宜稳准有力","急性剧痛期避免强力扳法与牵引，疑椎间盘突出大突出者慎用暴力手法","核心训练每日二至三次，每次十五分钟，循序渐进"]},{"icon":"🔥","title":"艾灸、拔罐与药敷","text":"寒湿与肾虚腰痛宜艾灸肾俞、命门、督脉与膀胱经循行部位；可用督脉灸、铺灸；寒湿者可用中药热敷包（艾叶、干姜、透骨草、川芎）外敷；瘀血者可拔罐留罐","bullets":["艾灸与热敷温度宜适中，防烫伤，尤其糖尿病与感觉障碍者","急性期扭伤48小时内禁用热敷与拔罐","皮肤破损处禁贴敷与拔罐；孕妇腰骶部禁灸禁罐"]}]},{"type":"paragraph","text":"腰痛的饮食调养以补肾强腰、温经散寒为原则，随证配餐。寒湿腰痛者宜温经散寒、忌一切生冷寒凉与冰饮，可饮姜枣茶、当归生姜羊肉汤、桂枝加芍药汤类食疗，食生姜、羊肉、韭菜、核桃、栗子、杜仲炖腰子；湿热腰痛者宜清热利湿、忌辛辣煎炸、酒类与肥甘厚味，可食冬瓜、丝瓜、赤小豆、薏苡仁、土茯苓、苦瓜、绿豆；血瘀腰痛者宜活血化瘀、忌寒凉凝滞，可食黑木耳、桃仁、山楂、玫瑰花茶、少量黄酒；肾阳虚腰痛者宜温补肾阳、忌生冷与过度耗伤，可食核桃、栗子、羊肉、枸杞、杜仲、巴戟天炖鸡、黑色食物；肾阴虚腰痛者宜滋补肾阴、忌辛辣燥烈与温补助火，可食黑芝麻、桑葚、百合、枸杞、栗子、山药、淡菜、黑豆。日常须注意：保证每日优质蛋白、钙与维生素D摄入（奶制品、豆制品、鱼虾、瘦肉、坚果）；避免过食寒凉生冷以免寒湿内侵；忌酒与过量甜食；控制体重以减轻腰椎负荷；保证每日饮水以防便秘（便秘可加重腰痛）；注意腰背保暖，忌汗出当风、忌冷水洗浴；久坐办公者每小时起身活动并做腰部伸展，避免长时间保持同一姿势。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：睡硬板床或中等硬度床垫，仰卧时膝下垫枕以放松腰椎；侧卧时双膝间夹枕；避免过软床垫与趴睡；坐姿保持腰部挺直、双足着地、避免跷二郎腿与长时间前倾，椅子高度使大腿与地面平行；搬提重物须屈膝下蹲、物体贴近身体、避免弯腰直搬与突然扭转；提物时避免弯腰同时旋转；注意腰部保暖，冬季不露腰、洗澡后及时擦干；控制体重；避免久坐久站、久蹲与长途驾驶，驾车时每小时下车活动。运动：缓解期宜加强核心肌群与臀部肌力训练（臀桥、平板支撑、小燕飞、鸟狗式、臀中肌训练），每次十五至二十分钟，每日一至二次；配合柔韧拉伸（腘绳肌、竖脊肌、腰方肌）；有氧可选快走、游泳（蛙泳与自由泳）、骑车与水中行走；急性发作期以相对休息为主，但不宜绝对卧床超过二天，以免肌肉萎缩；职业性腰痛者应作岗位评估与工位调整；康复训练须在医师或康复治疗师指导下循序渐进。预防：坚持核心训练与姿势管理是预防复发的核心；控制体重、戒烟限酒、规律作息；长期从事体力劳动者须注意劳逸结合与正确用腰姿势；有腰椎间盘突出史者避免久坐与提重物；反复发作或伴下肢症状者应定期复查影像，评估是否需要手术或其他治疗。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：腰痛伴下肢放射痛、麻木无力、行走困难、足下垂（须排查腰椎间盘突出压迫神经根或马尾）；腰痛伴会阴部（骑跨区）麻木、大小便失禁或尿潴留（马尾综合征，属外科急症，须立即急诊手术）；腰痛伴发热、寒战、血象升高（须排查化脓性脊柱炎与椎间隙感染）；剧烈腰痛伴外伤后不能活动、身高变矮或脊柱后凸畸形（须排查压缩性骨折与骨质疏松）；腰痛伴体重下降、持续低热、夜间痛甚、既往有肿瘤史或感染史（须排查转移瘤、结核与多发性骨髓瘤）；腰痛伴尿血、尿痛、发热（须排查泌尿系结石与感染）；伴会阴麻木的鞍区痛或双下肢进行性无力（须立即就医）；长期使用糖皮质激素者出现腰痛（须排查骨质疏松性骨折）；伴下肢静脉曲张、皮肤色素沉着、行走后肿痛（须排查下肢静脉疾病）。用药禁忌：非甾体抗炎药可致胃肠道出血与肾损害，胃溃疡、肾病、冠心病患者慎用；外用 NSAID 乳胶剂可致接触性皮炎；中药附子、川乌、草乌有大毒，须医师掌握剂量与煎法，禁自行服用；活络效灵丹、桃红四物汤等活血方孕妇禁用，月经期与出血倾向者慎用；服抗凝药者慎用活血药；止痛药不可长期依赖以掩盖病情；不主张对急性期大力按摩与暴力牵引，疑骨折、严重椎间盘突出或马尾综合征者严禁推拿；孕妇腰骶部禁用推拿、牵引、艾灸与拔罐；久坐久站者不宜盲目按摩放松代替姿势与运动干预。"},{"type":"keypoints","title":"腰痛要点","items":["病位在腰与肾，实证多寒湿、湿热、血瘀，虚证多肾阳虚与肾阴虚，临床虚实夹杂常见","寒湿腰痛用甘姜苓术汤加减，湿热腰痛用四妙丸合当归拈痛汤，血瘀腰痛用身痛逐瘀汤，肾阳虚用右归丸，肾阴虚用左归丸","辨证抓手：冷重得温减属寒湿、灼热遇热重属湿热、刺痛固定拒按属瘀、酸软乏力属肾虚","姿势管理与核心训练是长期控制的关键，急性期不宜绝对卧床超过二天","腰痛伴下肢无力、会阴麻木与大小便障碍、发热或外伤后剧痛者须立即就医"]}]},{"id":"jingzhuibing","title":"颈椎病","subtitle":"颈椎病｜项痹、颈肩综合征、颈源性头痛与眩晕","category":"其他","tags":["项痹","颈椎病","颈肩痛","肝肾亏虚","筋骨失养"],"meta":[{"label":"中医病名/证型概要","value":"项痹、颈痹、眩晕。证型分风寒湿型、气滞血瘀型、痰湿阻络型、肝肾亏虚型、气血亏虚型"},{"label":"主要症状","value":"颈项强痛、僵硬、活动不利，疼痛向肩臂或手指放射，伴上肢麻木无力、头晕、视物旋转、恶心，颈部转动时症状加重"},{"label":"舌脉要点","value":"风寒湿苔薄白脉弦紧；气滞血瘀舌暗有瘀斑脉弦涩；痰湿苔白腻脉濡滑；肝肾亏虚舌淡脉沉细"},{"label":"治则","value":"舒筋活络、调和气血为基本法，兼祛风散寒、活血化瘀、化痰通络、补益肝肾，筋骨并重"}],"image":"","imageHint":"颈椎","summary":"颈椎病是因颈椎间盘退变、关节骨与韧带病变而引起的以颈项疼痛、僵硬与上肢麻木无力为主要表现的病证，属中医「项痹」「颈痹」范畴。病位在颈项经络与筋骨，与肝肾关系密切：肾主骨生髓，肝主筋，肝肾亏虚则筋骨失养、颈项失固；风寒湿邪客于颈项、经脉痹阻则痛；久坐低头使气血运行不畅、气滞血瘀而痛；痰湿上阻清窍则眩晕。辨证以风寒湿、气滞血瘀、痰湿阻络与肝肾亏虚为纲。治疗以保守为主，须重视颈部功能锻炼与姿势管理，必要时配合牵引、推拿与药物。","blocks":[{"type":"paragraph","text":"颈椎病的病位在颈项部筋骨与经络，与肝、肾、脾关系密切。《素问·痹论》指出「痹在于骨则重，在于脉则血凝而不流」，颈为督脉与足太阳经所过之处，督脉总督一身之阳经，经气不利则颈部强痛、俯仰不利；足太阳膀胱经从巅入络脑，还出别下项，循肩膊内，络脊，故颈项病变可牵连肩背与上肢。病因为四：一是外感风寒湿邪，颈部暴露当风、久居湿地，邪气客于颈项，经脉痹阻，气血不畅而发；二是劳倦内伤与姿势因素，长期低头伏案、久坐不动、睡姿不当使颈椎长期处于前屈或旋转位，颈椎间盘与关节劳损退变；三是情志不畅与劳倦内伤致气血亏虚、肝肾不足，筋骨失养、颈项失固，痹阻更易发生；四是外伤与失治误治，颈部外伤后遗留慢性疼痛。病机演变上，初期以风寒湿与气滞血瘀为主，属邪实；久病肝肾亏虚、气血不足为本虚，兼夹痰湿。临床类型上，颈型与神经根型以颈痛与上肢放射痛麻木为主，椎动脉型以头晕、视物旋转、耳鸣、恶心为主，交感型以心悸、血压波动、视物模糊、眼干等自主神经症状为主，脊髓型以四肢无力、行走不稳、踩棉感为严重表现，须尽早手术评估。此外，颈源性头痛与颈源性眩晕在临床中常见而容易被误诊，须与颅内疾病、耳鼻科疾病与心血管疾病鉴别。"},{"type":"table","caption":"颈椎病辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["风寒湿型","颈项强痛，活动不利，遇风寒加重，得温则减，肩背沉重酸痛，头有紧束感，苔薄白，脉弦紧","祛风散寒，除湿通络","羌活胜湿汤","寒甚加桂枝、葛根；湿重加苍术、薏苡仁；颈痛甚加威灵仙、延胡索、葛根"],["气滞血瘀型","颈肩背疼痛，痛处固定，刺痛拒按，上肢麻木，转侧不利，舌质紫暗或有瘀斑，脉弦涩","活血化瘀，行气通络","身痛逐瘀汤（或补阳还五汤加减）","痛甚加全蝎、蜈蚣、延胡索；麻木加鸡血藤、络石藤、地龙；久瘀加水蛭"],["痰湿阻络型","头晕目眩，头重如裹，颈肩酸胀沉重，恶心欲呕，胸闷，失眠多梦，苔白腻，脉濡滑","燥湿化痰，通络止眩","半夏白术天麻汤合二陈汤","呕恶加生姜、代赭石；痰多加苍术、莱菔子、胆南星；眩晕甚加钩藤、天麻、石决明"],["肝肾亏虚型","颈痛隐隐，头晕耳鸣，视物模糊，腰膝酸软，四肢乏力，筋骨失养，舌淡苔薄，脉沉细","补益肝肾，强筋壮骨","独活寄生汤","肾阳虚加附子、鹿角霜、杜仲；阴虚加熟地、龟板、女贞子；眩晕加天麻、钩藤、菊花"],["气血亏虚型","颈肩麻木酸痛，头晕，面色少华，心悸气短，倦怠乏力，劳累后加重，舌淡，脉细弱","益气养血，荣筋通络","黄芪桂枝五物汤合当归补血汤","气虚甚加党参、白术；血虚加熟地、鸡血藤；麻甚加桑枝、桂枝、木瓜"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴颈夹脊、风池、天柱、大椎、后溪、肩髃、悬钟；风寒湿加风门、颈4夹脊，气滞血瘀加膈俞、血海，痰湿加丰隆、阴陵泉，肝肾亏虚加肾俞、太溪，气血亏虚加足三里、气海","bullets":["颈夹脊与后溪为要穴，针后活动颈部可增效","实证泻法、虚证补法并可加灸，留针二十至三十分钟","椎动脉型与交感型慎用重手法与大幅度扳法"]},{"icon":"🤲","title":"推拿与牵引","text":"以滚、揉、一指禅、弹拨、拔伸、扳法为主，重点处理斜方肌上束、肩胛提肌、菱形肌与枕下肌；配合颈椎间歇牵引（须在医师指导下进行）；并作颈椎等长抗阻与深层颈屈肌训练","bullets":["手法宜轻柔，急性发作期禁暴力扳法","脊髓型颈椎病与颈椎不稳者禁牵引，颈椎结核、肿瘤、严重骨质疏松禁牵引与扳法","每次二十分钟，训练每日二至三次"]},{"icon":"🔥","title":"艾灸与热敷","text":"风寒湿型与气血亏虚型宜艾灸颈夹脊、大椎、肩井与督脉，每穴十五分钟；可用中药热敷包外敷颈肩部；配合红外线、蜡疗等温热理疗","bullets":["温热疗法对寒湿型效果佳，热证与阴虚火旺者慎用","热敷温度适中，防止低温烫伤与皮肤低温损伤","急性期水肿明显时不宜热敷"]}]},{"type":"paragraph","text":"颈椎病的饮食调养以补益肝肾、益气养血、舒筋通络为原则，随证配餐。风寒湿型宜温经散寒、忌生冷寒凉，可饮姜枣茶、桂枝加芍药汤类食疗，食生姜、羊肉、韭菜、核桃；气滞血瘀型宜活血化瘀、忌寒凉凝滞与肥腻，可食黑木耳、桃仁、山楂、玫瑰花茶、黑芝麻；痰湿阻络型宜健脾化痰、忌肥甘甜腻与生冷，可食薏仁赤小豆粥、山药陈皮粥、冬瓜、萝卜、茯苓、陈皮；肝肾亏虚型宜补益肝肾、忌过度耗伤，可食黑芝麻、桑葚、核桃、枸杞、栗子、淮山、淡菜、杜仲炖腰子、黑色食物；气血亏虚型宜益气养血、忌生冷与过饥，可食黄芪粥、山药粥、莲子百合粥、桂圆红枣、瘦肉、鸡肉、黑芝麻。日常须注意：保证每日优质蛋白、钙与维生素D摄入以养骨护筋（奶制品、豆制品、鱼、瘦肉、坚果、深绿色蔬菜）；多晒太阳；控制体重以减轻颈椎负荷；忌酗酒与熬夜；饮食不宜过量；吸烟者应戒烟，因吸烟加速椎间盘退变并影响血供；不宜盲目长期服用「颈椎神药」，应在专科医师指导下使用；发作期饮食宜清淡易消化，避免过咸（加重水钠潴留与头昏）。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：睡眠使用符合颈椎生理曲度的枕头（高度以侧卧时头颈与躯干成一直线为宜，约一拳高），仰卧时枕头不宜过高，避免长时间俯睡；床铺软硬适中；避免长时间低头看手机（建议将手机抬至视线水平），连续伏案每三十至四十分钟起身活动颈肩；使用符合人体工学的椅子与显示器（屏幕上缘与视线齐平），双足着地、肘部约九十度；驾车时调整座椅使视线平直、头部后有支撑，长途行车每小时休息；避免空调直吹颈部，注意颈部保暖、不露颈睡；避免颈部剧烈甩动与自行「掰脖子响」；情绪与睡眠管理同样重要，焦虑与睡眠不足会加重颈部肌肉紧张。运动：颈部功能锻炼是核心——(1) 颈深屈肌训练（收下巴、点头动作，每组十次、每日三组）；(2) 等长抗阻训练（手掌抵额、枕、侧头对抗，等长十秒，重复十次）；(3) 肩胛骨后缩与胸椎伸展；(4) 每次十五至二十分钟、每日一至二次，配合快走、游泳与八段锦；(5) 运动幅度以不引起上肢麻木加重为度，出现放射性症状应立即停止并就诊。预防：坚持颈椎锻炼与姿势管理是预防复发与延缓退变的关键；乘车与工作场景的工效学改造最为实用；避免颈部受寒与长时间静止体位；控制体重、戒烟；睡眠充足；有上肢麻木、无力、行走不稳者应尽早就诊，明确类型与严重程度以决定保守或手术治疗。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须尽快就医（尤其警惕脊髓型颈椎病）：四肢麻木无力、握持力下降、精细动作困难；行走踩棉花感、步态不稳、易跌倒；大小便功能障碍、便秘或尿潴留（须立即急诊）；躯干与四肢感觉平面固定、躯干束带感；进行性肌力下降；突发剧烈眩晕伴猝倒、复视、构音障碍、吞咽困难、 Horner综合征（须警惕后循环缺血）；颈痛伴发热、盗汗、消瘦、既往有结核或肿瘤史（须警惕颈椎结核与转移瘤）；外伤后颈痛伴畸形、不稳定（须急诊固定并影像学检查）；头晕伴晕厥、心悸、黑矇（须排查心源性晕厥与心律失常）；颈部包块、吞咽困难、声音嘶哑（须排查器质性病变）；规范保守治疗三至六个月无效或症状进行性加重。用药禁忌：非甾体抗炎药可致胃肠道出血与肾损害，胃溃疡、肾病、心血管疾病者慎用；肌松药与镇静药可致嗜睡，服后严禁驾车；抗抑郁药与降压药可致头晕体位性低血压，须由医师处方；活血化瘀类中成药（桃红四物汤、活血止痛膏等）孕妇禁用，月经期、有出血倾向者慎用，服抗凝药者须告知医师；颈痛剧烈时自行服用含麻黄碱的止痛药或强效止痛药可掩盖病情；脊髓型颈椎病严禁自行推拿扳动与暴力牵引；颈椎结核、肿瘤、严重骨质疏松、颈动脉明显斑块者禁牵引；射频与臭氧等介入治疗须由专科医师评估后实施。"},{"type":"keypoints","title":"颈椎病要点","items":["病机为筋骨失养与经脉痹阻，风寒湿用羌活胜湿汤、气滞血瘀用身痛逐瘀汤、痰湿阻络用半夏白术天麻汤合二陈汤、肝肾亏虚用独活寄生汤、气血亏虚用黄芪桂枝五物汤合当归补血汤","辨证抓手：遇寒加重属风寒湿、刺痛固定属瘀、头晕头重属痰湿、腰膝酸软属肝肾亏、面色少华心悸属气血虚","颈深屈肌训练、等长抗阻与姿势管理是长期控制的核心，手机与伏案姿势是主要致病因素","脊髓型颈椎病是唯一明确需要手术的类型，出现四肢无力、踩棉感、大小便障碍须立即就诊","禁止自行「掰脖子」与暴力牵引，孕妇活血药与NSAIDs禁忌须严格遵守"]}]},{"id":"feipang","title":"肥胖","subtitle":"肥胖｜单纯性肥胖、代谢综合征","category":"其他","tags":["肥胖","痰湿内盛","脾虚湿阻","胃热滞脾","消脂"],"meta":[{"label":"中医病名/证型概要","value":"肥胖（膏粱之疾）。证型分脾虚湿阻、胃热滞脾、痰湿内盛、气滞血瘀、脾肾阳虚"},{"label":"主要症状","value":"形体肥胖，BMI与腰围超标，可伴乏力、气短、怕冷或烦热、食欲异常、便秘或便溏、睡眠打鼾、关节疼痛与情绪低落"},{"label":"舌脉要点","value":"脾虚湿阻舌淡胖苔白腻脉濡缓；胃热苔黄腻脉滑数；痰湿内盛舌胖苔白腻脉滑；脾肾阳虚舌淡胖有齿痕苔白润脉沉迟"},{"label":"治则","value":"健脾化痰、减重降脂为基本法，兼清热消导、活血行气、温补脾肾，标本兼治"}],"image":"","imageHint":"肥胖","summary":"肥胖是以形体过于肥胖、体脂比例过高、超过标准体重为特征的慢性代谢性疾病，属中医「膏粱之疾」「肥人多痰湿」范畴。病位在脾（胃）与经络，病机为脾失健运、水湿不化、痰浊内生与气血运行不畅。其本在脾（肾），其标为痰湿与瘀血。辨证分脾虚湿阻、胃热滞脾、痰湿内盛、气滞血瘀与脾肾阳虚五型。治疗须以饮食控制与规律运动为基础，中医药可协助改善代谢、调节胃肠功能与减少并发症，切不可依赖药物减重。","blocks":[{"type":"paragraph","text":"肥胖的病位在脾胃，涉及肝、肾与经络。《素问·通评虚实论》指出「肥者气不外散，多惰少动，著于脉，位在脾」，明确指出肥胖与脾的运化失健密切相关；《素问·奇病论》更指出「肥者令人内热」，言脾运不健则湿浊内生，郁久化热。病机核心为脾失健运：过食肥甘厚味、嗜酒、饮食失节，或久坐少动，脾运不健，水谷不化精微而反聚为湿浊；湿为阴邪，黏滞重浊，随气升降，弥漫全身则形体肥胖、头身困重、脘腹胀满；湿聚成痰，痰浊上蒙清窍则头晕目眩、困倦嗜睡，痰阻心肺则气短、心悸、睡眠呼吸暂停，痰浊下注则肢体沉重、关节疼痛；脾虚则水液代谢失常而见水肿；湿浊久留，阻滞气机，气滞则血瘀，痰瘀互结则胸闷、胁痛、皮下结节与脂肪肝；日久及肾，肾阳衰微则水湿泛滥、畏寒肢冷、便秘浮肿，肾阴不足则口干、潮热、盗汗。总体而言，肥胖属本虚标实之证，本在脾肾不足，标为痰湿与瘀血，且常兼肝郁、气虚、阴虚等。需强调的是，肥胖是代谢综合征、2型糖尿病、高血压、血脂异常、非酒精性脂肪肝、冠心病、痛风与骨关节炎的重要危险因素，治疗目标不仅是体重数字，更包括腰围、血压、血糖、血脂与生活质量的综合改善。"},{"type":"table","caption":"肥胖辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["脾虚湿阻证","形体肥胖，脘腹胀满，疲乏无力，纳少便溏，肢体困重，面色萎黄，舌淡胖有齿痕苔白腻，脉濡缓","健脾益气，渗利水湿","参苓白术散合二陈汤","气虚甚加黄芪、党参；湿重加薏苡仁、泽泻、猪苓；食少加焦三仙"],["胃热滞脾证","形体肥胖，多食易饥，口渴喜饮，口气重，面垢油光，大便秘结或黏滞，舌红苔黄腻，脉滑数有力","清胃泻火，消导化滞","保和丸合枳实导滞丸","胃热甚加黄连、石膏；便秘加大黄、玄参；食积加神曲、麦芽、山楂"],["痰湿内盛证","形体硕大，腹部肥满松软，脘腹胀满，头重如裹，嗜睡懒言，胸闷，痰多，苔白腻，脉滑","燥湿化痰，理气消痞","二陈汤合平胃散","痰多加莱菔子、芥子、胆南星；胸闷加瓜蒌皮、枳壳；头重加苍术、石菖蒲"],["气滞血瘀证","肥胖，胁肋胀满或痛，烦躁易怒，胸闷不舒，妇女月经不调、痛经、经色紫暗有块，舌暗有瘀斑，脉弦涩","疏肝理气，活血化瘀","血府逐瘀汤合逍遥散","胁痛加川楝子、延胡索、郁金；月事不调加香附、益母草；瘀重加水蛭、地龙"],["脾肾阳虚证","肥胖，畏寒肢冷，腰膝酸软，神疲乏力，浮肿，小便清长，夜尿频，大便溏薄或便秘，舌淡胖有齿痕苔白润，脉沉迟无力","温补脾肾，利水化痰","真武汤合济生肾气丸","寒甚加附子、肉桂、仙茅；浮肿加泽泻、猪苓；便秘加肉苁蓉、何首乌"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴中脘、丰隆、阴陵泉、足三里、天枢、大横、曲池；脾虚加脾俞、胃俞、章门，胃热加内庭、梁门，痰湿加丰隆、膻中，气滞血瘀加太冲、膈俞，阳虚加命门、关元","bullets":["丰隆、阴陵泉为化痰祛湿要穴，梁门、天枢可通腑减脂","实证用泻法、虚证用补法并可加灸，留针二十至三十分钟","每周三次，十次为一疗程，配合饮食运动效果更佳"]},{"icon":"🤲","title":"推拿按摩与穴位埋线","text":"腹部推拿取中脘、天枢、气海、关元、大横、带脉，掌摩腹部以助肠蠕动；配合穴位按摩与埋线（丰隆、天枢、大横、阴陵泉等）用于长期减重调理；耳穴贴压取饥点、内分泌、脾、胃、大肠","bullets":["腹部顺时针按摩每次十分钟，餐后一小时进行","埋线由专业人员在无菌条件下操作，每二至四周一次","耳穴贴压可辅助控制食欲，每日按压数次"]},{"icon":"🥗","title":"生活方式干预","text":"每日热量缺口约五百至七百千卡，保证蛋白质与膳食纤维摄入；每周至少一百五十分钟中等强度有氧运动加两次抗阻训练；保证每日七至八小时睡眠；减少含糖饮料与夜宵","bullets":["每周固定时间称重一次，记录腰围与血压","进食速度放缓，每餐二十分钟以上","睡眠不足会升高瘦素抵抗与皮质醇，妨碍减重"]}]},{"type":"paragraph","text":"肥胖的饮食调养以控制总能量、保证营养均衡、改变进食结构为原则，随证配餐。脾虚湿阻者宜健脾渗湿、忌肥甘与生冷，可食山药、薏苡仁、赤小豆、白扁豆、茯苓、冬瓜、玉米、糙米；胃热滞脾者宜清胃消导、忌辛辣煎炸、酒类与含糖饮料，可食冬瓜、丝瓜、苦瓜、绿豆、芹菜、海带、魔芋；痰湿内盛者宜化痰祛湿、忌甜腻与油炸，可食萝卜、荸荠、海藻、紫菜、陈皮、荷叶茶；气滞血瘀者宜疏肝活血、忌收敛酸涩与寒凉，可饮玫瑰花茶、菊花陈皮饮，食黑木耳、桃仁、山楂；脾肾阳虚者宜温补脾肾、忌一切生冷，可食核桃、栗子、羊肉、桂圆、生姜、杜仲炖腰子、黑豆。日常调摄要点：严格限制含糖饮料、果汁、奶茶与酒精；控制精制碳水与油脂比例；每日保证优质蛋白（鱼、虾、鸡蛋、低脂奶、豆制品）与蔬菜摄入，蔬菜体积大可增加饱腹感；进餐顺序为先汤菜、后蛋白、主食；细嚼慢咽，每餐二十分钟以上；避免暴饮暴食与夜宵；减重速度宜每周体重下降不超过体重的一至二个百分点，过快减重可致肌肉流失、代谢下降与反弹；不采用极低热量饮食与代餐替代正餐；保证饮水一千五百至二千毫升。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：规律作息，保证每日七至八小时睡眠，睡眠不足会升高皮质醇、降低瘦素敏感性而妨碍减重；避免熬夜与长期压力；久坐者每坐四十分钟起身活动；睡前不进食宵与含糖饮料；保证居室通风与适宜温度以增加日常活动量。运动：运动是减重的关键手段，建议每周累计一百五十分钟以上中等强度有氧运动（快走、慢跑、游泳、骑行、爬楼、球类）并配合每周二至三次抗阻训练（深蹲、俯卧撑、划船、平板支撑、弹力带训练）以保留肌肉量、增加基础代谢；日常增加非运动性活动消耗（站立、通勤步行、做家务）；运动应循序渐进，关节不适时改为水中运动与低冲击有氧；减重平台期可变换运动方式与强度；避免完全依赖运动而不控制饮食。预防：预防肥胖的关键是「能量平衡」，从儿童期即应控制含糖饮料与油炸食品摄入，保证户外活动与睡眠；青少年肥胖须关注生长与发育，忌极端节食与未经医师指导使用减肥药；孕妇与哺乳期妇女以合理增重为目标，不宜减重；中老年人减重速度宜更缓，须保证蛋白质与肌肉量；肥胖者若出现打鼾与日间嗜睡，须筛查阻塞性睡眠呼吸暂停；确诊肥胖者应定期监测血压、血糖、血脂、肝功能与尿酸。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：体重在短期内不明原因快速下降或极度消瘦（须排查甲亢、糖尿病、肿瘤与结核）；肥胖伴多毛、痤疮、月经稀发（须排查多囊卵巢综合征）；肥胖伴嗜睡、睡中憋醒、晨起头痛（须筛查睡眠呼吸暂停）；肥胖伴心悸、气促、下肢水肿（须排查心衰与肺心病）；突发剧烈头痛、视力障碍、视野缺损、肢体无力（须排查脑垂体瘤与颅内病变）；肥胖伴多饮多尿、体重下降（须排查糖尿病）；严重打鼾伴睡眠呼吸暂停与心律失常（须及时专科干预）；减重过程中出现心悸、失眠、焦虑、脱发、闭经（须排查过度减肥与内分泌紊乱）；肥胖合并脂肪肝、痛风性关节炎反复发作；青少年肥胖伴生长迟缓、发育异常。用药禁忌：严禁使用来源不明的「减肥药」「排毒减肥产品」与含泻药、利尿剂、甲状腺激素的产品，可致电解质紊乱、心律失常、甲状腺功能亢进与药物依赖；奥利司他等脂肪酶抑制剂有肝功能与心理副作用，须医师处方并监测；GLP-1受体激动剂等减重药物有胃肠道反应与胆囊、胰腺相关风险，须专科评估，不可自行网购使用；中药减肥方（常含大黄、番泻叶、泽泻、芒硝）可致腹泻、脱水与电解质紊乱，孕妇禁用，脾胃虚寒者慎用；任何减重药物不可与减重代餐、极低热量饮食同时自行叠加；哺乳期与备孕妇女禁用减重药物；重度肥胖合并心衰、肾衰者减重方案须在专科监护下实施；药物性肥胖（如糖皮质激素、抗精神病药）须由原发病医师调整用药而非自行停药。"},{"type":"keypoints","title":"肥胖要点","items":["病机为脾失健运、痰湿内生，本在脾肾、标为痰湿与瘀血","脾虚湿阻用参苓白术散合二陈汤、胃热滞脾用保和丸合枳实导滞丸、痰湿内盛用二陈汤合平胃散、气滞血瘀用血府逐瘀汤合逍遥散、脾肾阳虚用真武汤合济生肾气丸","饮食控制与规律运动是治疗基石，中药与针灸为辅助，不可依赖药物减重","减重目标应综合腰围、血压、血糖、血脂与生活质量，速率以每周体重的一至二个百分点为宜","严禁使用泻下、利尿与甲状腺激素类减肥产品，减重药物须专科处方与监测"]}]},{"id":"bianmi","title":"便秘","subtitle":"便秘｜功能性便秘、肠易激综合征便秘型、老年便秘","category":"其他","tags":["便秘","肠胃积热","气机郁滞","津血不足","润肠通便"],"meta":[{"label":"中医病名/证型概要","value":"便秘。证型分肠胃积热（热秘）、气机郁滞（气秘）、阴虚肠燥（虚秘）、气血亏虚（气虚秘）、阳虚寒凝（冷秘）"},{"label":"主要症状","value":"排便次数减少或次数不减而排便困难、粪便干硬或粗大难出、努挣无力或排出不尽感，伴腹胀腹痛、嗳气、烦躁或神疲"},{"label":"舌脉要点","value":"热秘舌红苔黄燥脉滑数；气秘舌淡红苔薄腻脉弦；虚秘舌红少津脉细数；气虚秘舌淡脉弱；冷秘舌淡苔白脉沉迟"},{"label":"治则","value":"润肠通便为基本法，实证泻热通便、行气导滞，虚证益气养血、滋阴温阳，忌峻下"}],"image":"","imageHint":"便秘","summary":"便秘是以排便次数减少、粪便干硬难出，或次数正常而排便艰涩、排出不尽为主要表现的病证，相当于功能性便秘与肠易激综合征便秘型。病位在大肠，与肺、脾、肾、肝相关。大肠传导失常是便秘的直接病机：肺气不降、脾失运化、肾阴不足或肾阳衰微、肝郁气滞皆可致秘。辨证以热秘、气秘、虚秘、气虚秘与冷秘为纲，实者泻之、虚者补之。治疗以润肠通便为基本法，并重视饮食、饮水、运动与排便习惯的建立，切忌滥用泻药形成依赖。","blocks":[{"type":"paragraph","text":"便秘的病位在大肠，病变关键在于大肠传导功能失常，与肺、脾、肾、肝关系密切。《素问·至真要大论》曰「大肠者，传导之官，变化出焉」，大肠接受小肠下传的食物残渣，吸收水分后形成粪便并排出，若肠腑气机不利、传导失常，则大便秘结不下。其病因有：一、热结肠胃——过食辛辣煎炸、饮酒或外感热邪传里，胃肠积热，津液被灼而肠燥便秘，属热秘；二、气机郁滞——情志不遂、恼怒抑郁，或久坐少动，肝失疏泄、大肠传导失司，腑气不通，或气滞而津液不布致秘，属气秘；三、阴血不足——久病体虚、产后失血、年老津亏，热病伤阴，肠失濡养，属阴虚肠燥之虚秘；四、气血亏虚——饮食劳倦、久病耗气，脾气不足、运化无力，大肠传导迟缓，属气虚秘；五、阳虚寒凝——年老肾阳衰微，或久病伤阳，命门火衰，肠道失于温煦推动，津液不布而结，属冷秘。临床以虚实夹杂与寒热错杂常见，如老年便秘多见气虚与阴虚并见，青年便秘多见热秘与气秘。便秘虽为小病，但长期便秘可致痔疮、肛裂、粪便嵌塞、肠梗阻，并增加心血管事件风险，须认真对待。治疗上实者以泻为主、虚者以补为主，且均须配合饮食、饮水、运动与排便习惯的调整，不可滥用泻药形成依赖。"},{"type":"table","caption":"便秘辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["肠胃积热证（热秘）","大便干结，腹胀满，口干口臭，面赤身热，小便短赤，舌红苔黄燥，脉滑数","泻热通便，润肠通腑","麻子仁丸","热甚加大黄、芒硝、枳实；口干加生地、玄参、麦冬；气滞加木香、枳壳、厚朴"],["气机郁滞证（气秘）","大便干结或不甚干结，欲便不得，或便而不爽，肠鸣矢气，腹中胀痛，嗳气频作，胸胁痞满，苔薄腻，脉弦","顺气导滞，降逆通便","六磨汤","气郁甚加柴胡、郁金、香附；腹胀加木香、枳实、莱菔子；嗳气加代赭石、旋覆花"],["阴虚肠燥证（虚秘）","大便干结如羊屎，努挣难出，口干咽燥，形体消瘦，头晕耳鸣，腰膝酸软，舌红少津，脉细数","滋阴润燥，增液通便","增液汤","津亏甚加火麻仁、郁李仁、松子仁；阴虚加麦冬、石斛、玉竹；头晕加女贞子、旱莲草"],["气血亏虚证（气虚秘）","大便不甚干结，努挣难下，排出无力，气短懒言，面白无华，神疲乏力，舌淡苔薄白，脉细弱","益气健脾，养血润肠","黄芪汤加味","气虚甚加党参、白术；血虚加熟地、当归、阿胶；气短加党参、黄芪"],["阳虚寒凝证（冷秘）","大便艰涩，排出困难，腹中冷痛，喜温喜按，畏寒肢冷，腰膝酸软，小便清长，舌淡苔白润，脉沉迟或沉细","温肾助阳，润肠通便","济川煎加味","寒甚加附子、肉桂、干姜；便秘甚加肉苁蓉、锁阳；腹痛加白芍、甘草"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴天枢、支沟、水道、大肠俞、上巨虚；热秘加合谷、曲池，气秘加太冲、中脘，阴虚加太溪、三阴交，气虚加足三里、脾俞，冷秘加神阙、命门、肾俞","bullets":["支沟为治便秘要穴，实证泻法、虚证补法","虚寒者加灸神阙与气海；老年虚秘可加灸","留针二十至三十分钟，每日或隔日一次，十次为一疗程"]},{"icon":"🤲","title":"推拿与腹部按摩","text":"腹部推拿取天枢、大横、中脘、气海、关元，以掌揉、顺时针摩腹、推腹为主；配合按揉支沟、足三里、脾俞、大肠俞；并作提肛与腹式呼吸训练","bullets":["顺时针摩腹每次十分钟，餐前一小时或晨起进行","虚秘者配合逆时针轻揉与热敷","配合每日定时排便训练（厕所有便意即去，勿久蹲）"]},{"icon":"🔥","title":"艾灸与穴位贴敷","text":"虚寒与气虚便秘可灸神阙、气海、关元、足三里，每穴十五分钟；可用吴茱萸、肉桂、丁香研末醋调贴敷神阙与足三里；亦可用中药灌肠液（须医师指导）","bullets":["实热秘不宜艾灸与热敷","贴敷时间二至四小时，观察皮肤反应","灌肠液须选生理渗透压制剂，老弱者慎用并须有人陪护"]}]},{"type":"paragraph","text":"便秘的饮食调养以增加膳食纤维、补充水分、调节肠道菌群为原则，随证配餐。热秘者宜清热通便、忌辛辣煎炸、酒类与高脂，可食菠菜、芹菜、苋菜、西葫芦、猕猴桃、火龙果、梨、绿豆；气秘者宜行气通便、忌收敛酸涩（乌梅、石榴、南瓜籽、过浓茶汤），可饮陈皮茶、佛手茶、玫瑰花茶，食佛手、香橳、萝卜、芹菜、燕麦；阴虚肠燥者宜滋阴润燥、忌辛辣燥烈，可食银耳、百合、桑葚、黑芝麻、核桃、蜂蜜（幼儿不宜）、阿胶（脾虚便溏者慎用）、梨、藕；气虚便秘者宜益气养血、忌生冷与耗气之品，可食山药粥、黄芪粥、莲子粥、燕麦、糙米、黑白芝麻、瘦肉；冷秘者宜温阳通便、忌一切生冷，可食核桃、栗子、羊肉、桂圆、当归生姜羊肉汤、桑葚。日常须每日饮水一千五百至二千毫升（心肾功能不全者遵医嘱限水），膳食纤维每日二十五至三十克，可由全谷物、豆类、蔬菜与水果提供；建立每日定时排便（晨起后或餐后半小时内），有便意勿憋、勿如厕看手机，每次不超过十分钟；避免久坐与长途旅行时活动不足；保持排便姿势时可脚下垫小凳使髋屈曲角度增大以利排便；腹部自我按摩与提肛训练每日进行；避免滥用泻药与「排毒茶」。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：养成每日定时排便习惯，起床后先饮温水一杯并如厕；如厕时双脚踩小凳、屈膝、避免久蹲与用力屏气；排便不宜看手机与读书以免久坐；保证充足睡眠，充足饮水；注意保暖，腹部受凉可加重肠道痉挛；避免长期卧床与久坐办公；调整作息与情绪，抑郁与焦虑可通过自主神经影响肠道功能。运动：规律有氧运动（快走、慢跑、游泳、骑行、椭圆机）每日三十分钟、每周一百五十分钟，可促进肠蠕动；配合核心与盆底训练（提肛训练每日三次、每次十五次，臀桥与腹式呼吸），对老年与产后便秘尤有帮助；避免长时间静坐，每小时起身活动并做提肛运动；晨起散步与饮温水相结合效果良好；运动后及时补水。预防：预防便秘重在生活方式——足量饮水、足量纤维、定时排便、规律运动、心情舒畅；老年人、长期卧床者、产后妇女与服用阿片类镇痛药者尤应重视；长期使用泻药者应在医师指导下逐步减量并改用渗透性缓泻剂；新发便秘、腹痛与消瘦者须及时就医排除器质性病变；反复便秘者建议做肛门指诊与必要的结肠镜检查。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：便秘伴便血、黑便、便条变细或排便习惯明显改变（须排查结肠癌、息肉）；便秘伴腹痛、腹胀、呕吐、停止排气（须排查肠梗阻与肠套叠）；便秘伴消瘦、贫血、低热、盗汗（须排查结核、克罗恩病与肿瘤）；突发剧烈腹痛并停止排便排气、腹部膨隆压痛（须急诊）；粪便表面带鲜血或肛门剧痛（须排查肛裂与痔疮）；长期服用泻药无效或依赖（须评估肠神经症与需用泻药）；老年患者新发便秘伴意识改变、乏力（须排除高钙血症、甲状腺功能减退与电解质紊乱）；便秘伴尿潴留、肢体麻木（须排查神经源性）；儿童便秘伴腹胀呕吐、生长发育落后（须排除先天性巨结肠与肠源性畸形）。用药禁忌：容积性泻药（欧车前、聚乙二醇）适用于长期使用但须多饮水；渗透性缓泻剂（乳果糖、聚乙二醇）相对安全；刺激性泻药（番泻叶、大黄、芦荟、决明子）不宜长期使用，可致结肠黑变病与依赖，须在医师指导下短期使用；含蒽醌类的中草药减肥茶与「排毒茶」同样不宜长期服用；强效泻药与灌肠液禁用于肠梗阻、肠套叠、急腹症与严重心血管疾病；长期使用阿片类药物、钙通道阻滞剂、抗胆碱药、抗抑郁药、钙剂、铁剂者须由医师评估并调整；孕妇、哺乳期与老年体弱者避免刺激性泻药；儿童便秘不自行使用泻药，须就医评估。"},{"type":"keypoints","title":"便秘要点","items":["病位在大肠，与肺脾肾肝相关；热秘用麻子仁丸、气秘用六磨汤、阴虚肠燥用增液汤、气血亏虚用黄芪汤、阳虚寒凝用济川煎","辨证抓手：口干口臭苔黄燥属热、嗳气腹胀苔薄腻属气滞、舌红少津脉细数属阴虚、气短乏力脉弱属气虚、腹冷喜温属阳虚","治疗的四个基础：足量饮水、足量膳食纤维、定时排便、规律运动","支沟、天枢、上巨虚为针灸要穴，实证泻法、虚证补法加灸","伴便血、消瘦、排便习惯改变或腹痛呕吐者须立即就医；刺激性泻药不可长期自行使用"]}]},{"id":"toutong","title":"头痛","subtitle":"头痛｜偏头痛、紧张性头痛、丛集性头痛、颈源性头痛","category":"其他","tags":["头痛","风邪外袭","肝阳上亢","痰浊瘀血","经络不通"],"meta":[{"label":"中医病名/证型概要","value":"头痛（内伤头痛与外感头痛）。证型分风寒头痛、风热头痛、风湿头痛、肝阳头痛、血虚头痛、痰浊头痛、瘀血头痛"},{"label":"主要症状","value":"头部疼痛，部位可为太阳、颞部、巅顶、后枕或全头，性质可为胀痛、刺痛、昏痛、紧束痛，常伴恶心呕吐、畏光畏声、眩晕"},{"label":"舌脉要点","value":"风寒苔薄白脉浮紧；风热舌红苔薄黄脉浮数；肝阳舌红苔黄脉弦数；血虚舌淡脉细；痰浊苔白腻脉濡滑；瘀血舌紫暗脉涩"},{"label":"治则","value":"外感头痛以祛邪为主，内伤头痛以补虚泻实、调整阴阳为纲，兼活血通络"}],"image":"","imageHint":"头痛","summary":"头痛是临床常见症状，可见于偏头痛、紧张性头痛、丛集性头痛、颈源性头痛、鼻窦炎头痛、丛集性血管性头痛及颅内器质性病变等。中医病机为「不通则痛」与「不荣则痛」两大类：外感六淫（风寒、风热、风湿）侵袭经络，邪滞脑络而痛；内伤则多与肝、脾、肾相关，肝阳上亢、痰浊上蒙、瘀血阻络、气血亏虚而痛。辨证当分外感内伤、寒热虚实，并结合疼痛部位、性质、诱因与兼症细辨。治疗须以辨证论治为先，同时重视生活调摄与原发病治疗，并警惕颅内器质性病变的红旗征象。","blocks":[{"type":"paragraph","text":"头痛的病位在头部经络，与肝、脾、肾关系密切。《素问·刺法论》曰「头为诸阳之会」，诸阳经皆上于头；足厥阴肝经上巅顶，足少阳胆经上额至头项，手少阳三焦经上项系耳后，足太阳经上入脑，故六经与督脉均可致头痛。病机可分外感与内伤两大类：外感者，因风为百病之長、为阳邪之冠，风寒、风热、风湿之邪侵袭头目，邪气留滞经络，气血不利而痛，起病较急、病程较短、多兼表证；内伤者，因肝主疏泄而藏血，肝失疏泄则气郁化火，阳亢风动上扰清窍而痛；脾为后天之本，运化失健则痰湿内生，痰浊上蒙清窍而痛；肾藏精生髓，肾精不足则髓海失养，或肾阴不足水不涵木而肝阳上亢，或肾阳衰微清阳不升而痛；气为血帅，血为气母，气虚则清阳不升、血虚则脑失所养而痛；久病入络，瘀血内阻脑络则头痛如刺、痛有定处、久痛不愈。此外，饮食不节、情志失调、劳倦过度、失血伤津、久病体虚、外感邪气与头部外伤，均可成为头痛的病因。临床辨证要点在于分清外感内伤、审察寒热虚实、结合部位与性质（太阳经痛连后颈、阳明经痛在额与眉棱骨、少阳经痛在头两侧、厥阴经痛在巅顶），并须特别注意排查继发性头痛。"},{"type":"table","caption":"头痛辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["风寒头痛","恶风寒，头痛连及项背，遇风寒加重，得温则减，口不渴，苔薄白，脉浮紧","疏风散寒，通络止痛","川芎茶调散","寒甚加麻黄、桂枝、细辛；项背强加葛根；鼻塞加辛夷、苍耳子"],["风热头痛","头痛而胀，发热恶风，面红目赤，口渴欲饮，咽痛，尿黄便秘，舌红苔薄黄，脉浮数","疏风清热，和络止痛","芎芷石膏汤","热甚加黄芩、连翘；便秘加大黄、玄参；咽痛加牛蒡子、桔梗"],["风湿头痛","头痛如裹，肢体困重，恶心呕吐，胸闷纳呆，苔白腻，脉濡","祛风胜湿，通窍止痛","羌活胜湿汤","湿重加苍术、藿香、佩兰；胸闷加藿香、厚朴；呕恶加半夏、生姜"],["肝阳、血虚头痛","肝阳者头胀痛、眩晕、心烦易怒、面红目赤、口苦、失眠、舌红苔黄、脉弦数；血虚者头痛隐隐、眩晕、心悸失眠、面色少华、神疲乏力、舌淡苔薄、脉细弱","肝阳者平肝潜阳、息风止痛，血虚者养血益气、柔肝止痛","肝阳用天麻钩藤饮，血虚用加味四物汤","肝火盛加龙胆草、夏枯草、栀子；眩晕加菊花、僵蚕；血虚甚加熟地、阿胶、鸡血藤；失眠加夜交藤、酸枣仁"],["痰浊、瘀血头痛","痰浊者头痛昏蒙、胸闷恶心、呕吐痰涎、纳呆头重如裹、苔白腻、脉濡滑；瘀血者头痛日久痛如锥刺、固定不移、夜间尤甚、舌紫暗有瘀斑、脉涩","痰浊者健脾化痰、降逆止痛，瘀血者活血化瘀、通窍止痛","痰浊用半夏白术天麻汤，瘀血用通窍活血汤","痰多加苍术、莱菔子；呕恶加生姜、代赭石；久瘀加水蛭、地龙；痛甚加全蝎、蜈蚣、延胡索"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴百会、太阳、风池、合谷、列缺；风寒加风门、大椎，风热加大椎、曲池，风湿加阴陵泉、丰川，肝阳加太冲、太溪，血虚加足三里、三阴交，痰浊加丰隆、阴陵泉，瘀血加血海、膈俞","bullets":["按部位配穴：前额取阳白、攒竹，头侧取率谷、太阳，巅顶取百会、四神聪，后枕取天柱、风池","实证泻法，虚证补法并加灸，留针二十至三十分钟","急性期可配合刺络放血（太阳、大椎）以泄热"]},{"icon":"🤲","title":"推拿按摩与颈项治疗","text":"头面部推拿取印堂、攒竹、鱼际、太阳、头维、风池；颈项部揉拿风池、风府、肩井、颈夹脊；颞部与枕后分推、揉搓至发热；颈源性头痛须重点处理枕下肌与上斜肌","bullets":["每次十五分钟，力度适中，以舒适为度","头痛剧烈时不宜强行重手法","配合放松训练与呼吸调息效果更佳"]},{"icon":"🧘","title":"耳穴与放松训练","text":"耳穴贴压取神门、皮质下、交感、枕、太阳、肝、肾，双耳交替贴压三至五日；配合渐进式肌肉放松、腹式呼吸与正念训练；规律睡眠、避免漏餐与脱水","bullets":["发作期安静环境休息、避光避声有助缓解","睡眠不足、进食不规律与脱水是常见诱因","记录发作日记以识别诱因与评估疗效"]}]},{"type":"paragraph","text":"头痛的饮食调养以清淡、均衡、避免诱发为原则，随证配餐。风寒头痛者宜温热、忌生冷冰饮，可饮姜枣茶、苏叶茶、桂枝汤类食疗；风热头痛者宜清凉、忌辛辣煎炸、烧烤与酒类，可饮菊花茶、金银花茶、薄荷茶、绿豆汤；风湿头痛者宜化湿、忌生冷油腻与甜腻，可饮与甜腻，可饮藿香佩兰茶、薏仁赤小豆粥、冬瓜、薏苡仁；肝阳头痛者宜平肝、忌辛辣燥烈、动物内脏与温补，可饮菊花决明茶、桑叶菊花饮、罗布麻茶，食芹菜、荸荠、海带、紫菜；血虚头痛者宜养血、忌生冷与过度耗伤，可食当归生姜羊肉汤、桂圆红枣茶、桑葚膏、黑芝麻、瘦肉、猪肝；痰浊头痛者宜化痰、忌肥甘甜腻与酒类，可食山药陈皮粥、薏仁山药粥、萝卜、冬瓜、茯苓；瘀血头痛者宜活血、忌寒凉凝滞，可食黑木耳、桃仁、山楂、玫瑰花茶、黑芝麻。日常须注意：发作期保证规律进食与饮水（脱水是常见诱因）；避免酒精、浓茶、咖啡因饮品与含糖饮料；限制含亚硝酸盐的加工肉制品（香肠、腊肉、罐装食品）与味精；避免强光、闪烁屏幕与噪音环境；保证每日七至八小时睡眠、避免熬夜与睡懒觉；三餐规律，避免长时间空腹；控制体重与血压；发作时记录头痛部位、性质、程度、持续时间与伴随症状。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：规律作息，每日定时起床与入睡（睡眠过多与过少均可诱发偏头痛），避免周末补觉过久；睡前与发作时保持安静、光线柔和的环境；限制强光与噪音暴露，减少夜间使用强光屏幕；注意保暖，冬季外出戴帽以免寒邪侵袭头部；学会放松与压力管理，长期精神紧张是常见诱因；发作期减少不必要活动、安静休息；记录发作日记（诱因、部位、性质、程度、持续时间、用药反应）以评估治疗效果。运动：规律有氧运动（快走、慢跑、游泳、骑行）每周一百五十分钟，可减少偏头痛发作频率并改善睡眠与情绪；避免剧烈运动与突然发力（如在头痛发作期进行高强度训练或长时间倒立、倒吊类动作）；配合颈深屈肌训练与肩胛稳定训练以改善颈源性头痛；运动前后充分热身与补水；发作期以轻度活动为主。预防：识别并回避个体化诱因（睡眠不足、漏餐、脱水、酒精、咖啡因、强光、气味、情绪压力、经期）；发作频繁者应接受头痛专科评估与预防性治疗，不宜仅靠止痛药；长期频繁服用止痛药者可出现药物过度使用性头痛；生活方式干预是偏头痛与紧张性头痛管理的基础；对颈源性头痛者须同时处理颈椎问题与姿势习惯。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须立即就医：突然发生的剧烈头痛（「一生中最痛」），伴发热、颈项强直、呕吐、意识障碍或皮疹（须排查蛛网膜下腔出血与脑膜炎）；头痛进行性加重、晨起加重伴喷射性呕吐与视力下降（须排查颅内占位与脑积水）；头痛伴一侧肢体无力或麻木、言语不清、口角歪斜、视物模糊（脑卒中）；头部外伤后头痛伴呕吐、意识改变、瞳孔不等大（须排查颅内出血）；妊娠期或产后出现剧烈头痛伴视物模糊、抽搐、上腹痛（须排查子痫前期与静脉窦血栓）；中老年突发剧烈头痛伴心悸、血压极高（须排查高血压急症）；头痛伴发热、鼻塞流脓、眼周与额部压痛（鼻窦炎）；头痛伴意识模糊、行为异常、癫痫发作；50岁以后新发头痛；头痛伴发热、体重下降、免疫抑制状态（须警惕隐匿性脑炎与颅内感染）；偏头痛伴一侧眼痛、视力下降与眼睑下垂（须排查丛集性头痛与巨细胞动脉炎，老年患者尤须警惕）。用 药禁忌：含咖啡因的复方止痛药长期频繁使用可致药物过度使用性头痛；非甾体抗炎药可致胃肠道出血与肾损害，胃溃疡、肾病、心血管病者慎用；曲普坦类（利扎曲普坦等）与麦角胺类可致血管收缩，冠心病、脑血管病、高血压未控者禁用，孕期禁用；含对乙酰氨基酚的复方感冒药与感冒止咳药可诱发热敏感者偏头痛；强效阿片类不可用于偏头痛；苯二氮䓬类可致依赖与嗜睡；孕哺期妇女禁用麦角胺与阿片类；预防性用药（β受体阻滞剂、托吡酯、丙戊酸、Topiramate）须由医师评估，不可自行服用或停药；避免自行使用激素与麻醉类药物反复注射以防药物过量性头痛。"},{"type":"keypoints","title":"头痛要点","items":["病机分「不通则痛」（风寒风热风湿、痰浊、瘀血）与「不荣则痛」（血虚、气虚、肾虚）两大类","风寒用川芎茶调散、风热用芎芷石膏汤、风湿用羌活胜湿汤、肝阳用天麻钩藤饮、血虚用加味四物汤、痰浊用半夏白术天麻汤、瘀血用通窍活血汤","辨证抓手：遇风加重属风寒、胀痛发热属风热、如裹属风湿、胀痛烦躁属肝阳、隐隐心悸属血虚、昏蒙呕恶属痰浊、刺痛固定属瘀血","诱因管理（睡眠、进食、饮水、酒精、咖啡因、强光、情绪）是发作预防的核心，需记录头痛日记","突发剧烈头痛伴呕吐颈强、神经系统体征、外伤后头痛、孕产期剧烈头痛者须立即急诊"]}]},{"id":"tuofa","title":"脱发","subtitle":"脱发｜斑秃、脱发、雄激素性脱发、产后脱发","category":"其他","tags":["脱发","发为血之余","肾其华在发","养血生发","补肾"],"meta":[{"label":"中医病名/证型概要","value":"脱发（发落）、斑秃（油风）、髭秃。证型分血虚生风、肝郁气滞、肾精亏虚、血瘀、脾胃虚弱、湿热蕴结"},{"label":"主要症状","value":"头发稀疏脱落、数量减少、发际线后移或头顶部变稀，或突然出现圆形片状脱发区，头皮光滑，亦可伴头皮油腻、瘙痒、头屑"},{"label":"舌脉要点","value":"血虚舌淡苔薄脉细弱；肝郁舌淡红苔薄白脉弦；肾虚舌淡脉沉细；血瘀舌紫暗有瘀斑脉涩；湿热舌红苔黄腻脉滑数"},{"label":"治则","value":"养血生发、补肾益精为基本法，兼疏肝解郁、活血化瘀、清利湿热，内外合治"}],"image":"","imageHint":"脱发","summary":"脱发以头发数量减少、稀疏、发际线后移或出现片状脱发区为主要表现，可见于雄激素性脱发、斑秃、产后脱发、休止期脱发、脂溢性脱发与头皮疾病所致脱发。中医认为「发为血之余」（血养发）、「肾其华在发」（精生发），故脱发与肝、肾、血、脾关系密切。血虚生风则发稀疏枯脆；肝郁气滞则脱发与情志相关；肾精亏虚则发早白脱落、腰膝酸软；脾虚则气血生化不足；湿热蕴结则头皮油腻、脱屑瘙痒；瘀血阻络则久治不愈。治疗须内外并重、结合病因，同时重视调畅情志与生活调摄。","blocks":[{"type":"paragraph","text":"脱发的病位在毛发与头皮，与肝、肾、脾相关。《素问·上古天真论》曰「肾气衰，发堕齿槁」，指出肾气衰亏则头发脱落、牙齿枯槁；《素问·六节藏象论》曰「肾其华在发」，肾精充盈则发黑有光泽；而《素问·上古天真论》「发为血之余」则强调血是濡养毛发之源，脾胃为气血生化之源，故发之荣枯与肾精、血液、脾胃功能密切相关。病因可归纳为：一、血虚生风——失血、久病、产后、脾胃虚弱致气血生化不足，血不养发，毛发枯脆稀疏而脱，或血虚生风、肌肤失养而瘙痒；二、肝郁气滞——情志不遂、忧思恼怒，肝郁化火耗伤阴血，或肝血不足不能荣发，脱发常与情绪波动相关，并可伴胸胁胀痛、烦躁失眠；三、肾精亏虚——先天禀赋不足、年老体衰、房劳过度、久病伤肾，肾精不能化生血液以养发，发早白、枯槁而脱，伴腰膝酸软、头晕耳鸣、牙齿松动；四、血瘀阻络——久病入络、情志气滞日久致瘀，瘀阻毛窍，脱发日久、迁延难愈、色素沉着明显；五、湿热蕴结——嗜食辛辣肥甘、头皮油脂分泌旺盛，湿热上蒸熏蒸头皮，致头皮油腻、瘙痒、脱屑、发根松动而脱发。此外，产后气血骤虚、手术、大病、剧烈减重、高热与精神打击可致休止期脱发；男性雄激素性脱发与遗传、雄激素水平、毛囊对雄激素敏感性相关；头皮感染与炎症（如头癣、脂溢性皮炎、斑秃）可直接导致脱发。临床须首先明确病因与类型，治疗上内服调补肝肾脾血、外用生发活血，配合精神调摄，方能取效。"},{"type":"table","caption":"脱发辨证分型与论治","head":["证型","主要表现","治法","代表方","加减"],"rows":[["血虚生风证","头发稀疏枯脆，脱落较多，发色枯黄，头皮瘙痒，面色萎黄，神疲乏力，头晕心悸，舌淡苔薄，脉细弱","养血祛风，健脾生发","神应养真丹","血虚甚加熟地、白芍、鸡血藤、首乌；脾虚加白术、茯苓、山药；瘙痒加白蒺藜、蝉蜕"],["肝郁气滞证","脱发与情志波动密切相关，胸胁胀满，烦躁易怒，失眠多梦，叹息，舌淡红苔薄白，脉弦","疏肝解郁，养血生发","逍遥散","郁热加丹皮、栀子；失眠加夜交藤、酸枣仁；脱发重加何首乌、鸡血藤、旱莲草"],["肾精亏虚证","脱发量多而广，发色枯白稀疏，早白，伴腰膝酸软，头晕耳鸣，牙齿松动，畏寒乏力或五心烦热，舌淡苔薄，脉沉细","补肾益精，养血生发","七宝美髯丹","肾阴虚加女贞子、旱莲草、龟板；肾阳虚加菟丝子、鹿角霜、巴戟天；发枯加黑芝麻、桑椹"],["血瘀、脾胃虚弱证","血瘀者脱发日久不愈、发际线后移或头顶稀疏、头皮色暗有色素沉着、舌紫暗有瘀斑、脉涩；脾胃虚弱者脱发日久、毛发稀疏细软、面色萎黄、纳少便溏、神疲乏力、舌淡胖苔白、脉缓弱","血瘀者活血化瘀、通窍生发，脾胃虚弱者健脾益气、养血生发","血瘀用通窍活血汤，脾胃虚弱用归脾汤","久瘀加地龙、水蛭；气虚加黄芪、党参；便溏加山药、莲子、扁豆；发枯加首乌、黑芝麻"],["湿热蕴结证","头皮油腻，瘙痒，头屑多，毛发稀疏脱落，伴口苦、胸闷、大便黏滞，舌红苔黄腻，脉滑数","清热利湿，护发养发","龙胆泻肝汤合二妙散","湿重加土茯苓、薏苡仁、泽泻；油多加侧柏叶、蒲公英；瘙痒加白鲜皮、地肤子"]]},{"type":"cards","columns":3,"items":[{"icon":"💉","title":"针灸取穴","text":"主穴百会、风池、头维、肾俞、肝俞、脾俞、足三里、三阴交；血虚加膈俞、血海，肝郁加太冲、期门，肾虚加太溪、命门，湿热加阴陵泉、丰隆","bullets":["百会、风池为生发要穴，针后配合头皮按摩增效","实证泻法、虚证补法并可加灸，肾虚者灸肾俞、关元","留针二十至三十分钟，每日或隔日一次，十次为一疗程"]},{"icon":"🌿","title":"外治法","text":"鲜姜汁、侧柏叶酊或首乌酊涂擦脱发区，每日二至三次；中药洗剂（侧柏叶、何首乌、旱莲草、桑椹煎液）洗头；斑秃可配合梅花针叩刺患处与艾灸；现代可遵医嘱使用米诺地尔与糖皮质激素外用","bullets":["涂擦以微微刺激为度，勿过度摩擦损伤毛囊","出现局部毛囊炎、毛孔粗大、灼痛应停用并就诊","米诺地尔初期可致脱 shedding 增多，须遵医嘱使用，孕妇禁用"]},{"icon":"🤲","title":"推拿按摩与耳穴","text":"头皮按摩以指腹揉搓至温热，重点百会、风池、头维与发际穴，配合十指梳发与颈部放松；耳穴贴压取肾、肝、脾、肾俞、内分泌、皮质下、神门，双耳交替","bullets":["每日一次，每次十分钟，促进头皮局部血流","配合放松训练与心理疏导改善焦虑相关脱发","梳发宜用宽齿梳，勿强拉"]}]},{"type":"paragraph","text":"脱发的饮食调养以补肾养血为原则，随证配餐。血虚生风者宜养血健脾，忌辛辣燥烈与生冷，可食黑芝麻、桑葚、核桃、桂圆、红枣、枸杞、瘦肉、猪肝、当归生姜羊肉汤；肝郁气滞者宜疏肝理气、忌郁怒与刺激性食品，可饮玫瑰花茶、佛手陈皮茶、合欢花茶，食佛手、香橳、芹菜、黑芝麻；肾精亏虚者宜补肾填精、忌过度耗伤，可食黑芝麻、桑葚、核桃、栗子、枸杞、淮山、芡实、淡菜、黑色食物、杜仲炖腰子；血瘀者宜活血、忌寒凉凝滞，可食黑木耳、桃仁、山楂、玫瑰花茶；脾胃虚弱者宜健脾益气、忌生冷油腻，可食山药粥、莲子粥、黄芪粥、茯苓、白扁豆、瘦肉；湿热蕴结者宜清淡利湿、忌辛辣酒类与肥甘厚味，可食冬瓜、丝瓜、绿豆、薏苡仁、土茯苓、苦瓜。日常须注意：保证每日足量优质蛋白（约每公斤体重一点至一点五克）、铁、锌与维生素B族（瘦肉、鱼虾、蛋、奶、豆制品、动物肝脏、坚果、全谷物）；女性与素食者尤其注意补铁，必要时查血清铁蛋白；避免过度节食与快速减重（可致休止期脱发）；避免长期高糖高脂饮食；限制酒类（可致毛囊炎与加重脂溢性脱发）；少吃甜食与精制碳水（可致糖化终末产物累积损伤毛囊）；保证睡眠充足（每日七至八小时），睡眠剥夺与压力升高皮质醇可诱发脱发；避免频繁染烫头发与长期扎紧发髻、佩戴过紧发箍。"},{"type":"callout","variant":"info","title":"起居运动与预防","text":"起居：保证每日七至八小时睡眠，避免长期熬夜；保持头皮清洁与通风，温和洗发（每周二至三次，过度洗头会加重脱发），洗发水宜中性无硫酸盐；避免用指甲抓挠头皮；避免频繁染、烫、漂发，尤其避免漂发与高温直发；避免长期扎紧马尾、佩戴过紧发带与长期戴帽压迫发际；洗头后勿用高温风吹干；注意营养与气血生化；情绪调摄极为关键，焦虑与抑郁是脱发的重要加重因素，须学会放松、必要时寻求心理支持；节食减重须缓慢。运动：规律有氧运动（快走、慢跑、游泳、骑行、太极）每周一百五十分钟，可改善代谢、循环与情绪；配合头皮按摩与颈部放松；避免长时间高强度运动导致大量出汗后不及时清洁；力量训练有助改善代谢与激素水平但须适量；作息与运动结合对雄激素性脱发的整体管理有益。预防：早期发现脱发增加、发际线后移或头皮稀疏时应尽早就诊干预，毛囊一旦长期萎缩则毛发难以再生；雄激素性脱发须规范使用抗雄激素治疗（男性可与非那雄胺等，须由医师评估，育龄男性须注意生育影响）；产后脱发多为休止期脱发，多在产后数月自行恢复，但持续不改善者须查甲功、铁蛋白与泌乳素；头皮有红肿、渗液、脱屑、剧烈瘙痒者先治头皮；避免自行长期使用含激素的「生发液」或依赖网购生发产品；出现全身性脱发、眉毛睫毛脱落、伴甲改变与皮肤症状者须尽快就诊排查系统性疾病。"},{"type":"callout","variant":"danger","title":"就医提示与禁忌","text":"出现下列情况必须及时就医：脱发突然发生、出现圆形或不规则片状脱发区（斑秃）；全头脱落或全身毛发广泛稀疏脱落（须排查弥漫性脱发、甲状腺疾病、贫血、狼疮与梅毒）；头皮红肿、渗液、结痂、剧烈瘙痒、边缘隆起的环形脱屑（须排查头癣、脂溢性皮炎与细菌感染）；头皮出现无痛性溃疡、增厚、边缘不整齐、易出血的肿块（须警惕皮肤恶性肿瘤）；脱发伴甲脆裂、皮肤干燥、雷诺现象、关节痛（须排查甲状腺疾病与结缔组织病）；伴月经紊乱、溢乳、乏力、怕冷（须排查泌乳素升高与甲减）；伴明显消瘦、乏力、心悸、食欲亢进、体重下降（须排查甲亢）；严重脱发伴月经稀少、多毛、痤疮（须排查多囊卵巢综合征）；头皮大面积烧灼、疼痛或感觉异常（须警惕感觉神经性脱发与三叉神经痛）；产后脱发持续一年以上不改善。用药禁忌：米诺地尔可致心悸、血压升高、多毛与胎儿毒性，孕妇、哺乳期禁用，心血管疾病者慎用；非那雄胺可致性欲减退、勃起障碍与胎儿致畸，育龄男性及其配偶须严格避孕，孕妇禁用；口服抗雄激素药物可致肝功能异常与情绪变化，须定期监测肝功能与血脂；糖皮质激素长期使用可致股骨头坏死与继发感染，须在医师监护下使用；中药含何首乌者有肝损伤报告，须短期使用并监测肝功能，肝功能异常者禁用；含重金属的「生发液」与「养发液」可致中毒；避免自行使用米诺地尔与激素混合制剂；孕期、哺乳期与育龄妇女使用任何生发药物前必须咨询医师。"},{"type":"keypoints","title":"脱发要点","items":["病机为发失所养与络脉瘀阻，「发为血之余」「肾其华在发」是辨治核心","血虚生风用神应养真丹、肝郁气滞用逍遥散、肾精亏虚用七宝美髯丹、血瘀用通窍活血汤、脾胃虚弱用归脾汤、湿热蕴结用龙胆泻肝汤合二妙散","辨证抓手：枯脆面黄属血虚、情志相关属肝郁、早白腰酸属肾虚、日久色暗属瘀、头皮油痒属湿热","保证蛋白、铁、锌与睡眠、避免频繁染烫与过度节食是基础措施","突发片状脱发、全身脱发、头皮感染征象、伴甲与内分泌改变者须及时就诊"]}]}]}},"about":{"page":{"key":"about","title":"关于本站","subtitle":"缘起、体例、资料来源与免责声明","description":"岐黄翰墨是一份面向传统医学学习者的开放知识库，内容以中医经典文献与公开教材为依据整理，涵盖理论、典籍、药物、方剂、针灸、食疗、节气、体质与临床调护九个板块。","lead":"「岐黄」出自《黄帝内经》对岐伯与黄帝问答的记述，后世遂以「岐黄」代指中医学与中医文献。**岐黄翰墨**取此为名，意在把散见于典籍、方书、本草、针灸与养生笔记中的中医知识，整理成一部可检索、可阅读、可再扩展的开放资料。","type":"section","icon":"fa fa-info-circle","sections":[{"id":"origin","title":"缘起与定位","subtitle":"为什么做这个站","icon":"🌱","summary":"中医文献浩如烟海，普通读者难以入门；本站试图提供一条结构清晰、术语准确、可随时查证的路径。","blocks":[{"type":"paragraph","text":"读《黄帝内经》《伤寒论》原文，是许多中医学习者的第一道门槛。原文本身并不难懂，难的是缺少上下文：读《素问·阴阳应象大论》时，不知道它与《难经》如何承接；读《本草纲目》某味药的「发明」时，不知道它与《神农本草经》的「气味主治」有何区别；读一张方子时，也不知道它对应的是哪一类证候。本站把这些背景补齐，让每一段原文、每一味药、每一张方子都能在体系中找到位置。"},{"type":"paragraph","text":"因此本站的内容组织遵循三个原则：**其一是忠实原文**，引用古籍一律标注书名与篇名，可回溯核对；**其二是结构化**，把散落的描述拆解为性味归经、功效主治、配伍宜忌、剂量用法等可比较的字段，便于横向对照；**其三是可扩展**，正文与样式彻底分离，新增内容只需编辑数据文件，无需改动任何页面代码。"},{"type":"cards","columns":3,"items":[{"icon":"📚","title":"忠实原文","text":"引文逐字比对典籍原文，标注书名与篇名，读者可自行复核。"},{"icon":"🧩","title":"结构化","text":"药物、方剂、病种均按统一字段组织，支持跨条目横向比较。"},{"icon":"🌿","title":"可扩展","text":"内容与样式彻底分离，补充新章节只需编辑 JSON 数据文件。"}]},{"type":"callout","variant":"info","title":"本站不是医疗工具","text":"岐黄翰墨是传统医学的**知识整理与文化传播**项目，不是在线诊疗平台，不提供处方、剂量计算或诊断结论。所有涉及具体治疗的内容，均以「须经医师辨证」的方式表述。"}]},{"id":"structure","title":"内容板块与体例","subtitle":"九个板块的分工","icon":"🗂️","summary":"九个板块构成从理论到临床的完整链条，彼此交叉引用，可顺序阅读也可按需检索。","blocks":[{"type":"paragraph","text":"九个板块之间存在明确的知识递进关系：**理论基础**回答「中医如何认识人体与疾病」，**经典医籍**回答「这些认识从哪来」，**本草图鉴**与**方剂大成**回答「用什么药、什么方来调整」，**针灸经络**回答「如何从体表调治脏腑」，**养生食疗**与**节气养生**回答「如何在日常生活中维护健康」，**体质辨识**回答「我的身体偏向何种类型」，**疾病调理**则把这些知识落到具体病种的辨证论治上。"},{"type":"table","caption":"各板块的内容范围与体例","head":["板块","内容范围","体例"],"rows":[["理论基础","阴阳五行、藏象、气血津液、经络、病因病机、四诊八纲、治则治法、治未病","分节论述，每节含提要、对照表、引文与要点"],["经典医籍","《黄帝内经》《难经》《伤寒论》《金匮要略》《神农本草经》《本草纲目》等十九部","逐部介绍成书背景、内容结构、文献地位与原文摘录"],["本草图鉴","六十味常用中药，按解表、清热、泻下、祛风湿等十二类归类","性味归经、功效主治、用法用量、配伍与禁忌"],["方剂大成","三十六首经典方剂，按八法归类","组成、功用主治、君臣佐使方义、加减化裁与禁忌"],["针灸经络","经络总论、十二经脉、奇经八脉、腧穴总论、刺灸法、配穴处方、常见病主治、禁忌","分节论述，含腧穴定位、操作要领与异常处理"],["养生食疗","三十六道药膳，分药膳方、体质食养、季节食养三类","食材用量、功效主治、制作方法与禁忌人群"],["节气养生","二十四节气的气候物候、起居饮食、导引保健与易发疾病","逐节论述，含宜忌表、穴位保健与预防提示"],["体质辨识","体质学说总论与九种基本体质","形神特征、常见表现、易病倾向、饮食起居调摄"],["疾病调理","二十八个常见病种，分属内、妇、儿、皮肤、五官等科室","病因病机、辨证分型论治、外治法、饮食调养与就医提示"]]},{"type":"keypoints","title":"阅读建议","items":["初次接触中医者，建议先读「理论基础」的阴阳与藏象两节，建立整体观。","学习临证者，可由「方剂大成」入手，反查「理论基础」中的治则治法以理解配伍逻辑。","关注自我调养者，先做「体质辨识」，再依体质选读「养生食疗」与「节气养生」的相关条目。","有具体健康困扰者，先看「疾病调理」中对应病种的辨证分型表，再回到「方剂大成」核对代表方。"]}]},{"id":"sources","title":"资料来源","subtitle":"典籍、教材与文献","icon":"🖋️","summary":"本站资料以公有领域中医古籍为骨干，以现行中医药教材为参照，以权威机构公开资料为补充。","blocks":[{"type":"paragraph","text":"**古典文献。** 十九部传世典籍的正文与篇目结构依据公有领域古籍整理本，引用原文均逐字比对并标注出处：《黄帝内经》分《素问》《灵枢》两部，是现存最早的医学典籍，奠定阴阳五行、藏象、经络与治未病之说；《难经》以八十一难释疑补《内经》之未备；《伤寒论》与《金匮要略》原合称《伤寒杂病论》，前者立六经辨证，后者载杂病六十余种、方二百六十二首；《神农本草经》载药三百六十五种，首立三品分类与七情和合；《本草纲目》载药一千八百九十二种、医方一万一千零九十六首、插图一千一百六十幅，是世界药学史上的里程碑。"},{"type":"paragraph","text":"**现代教材。** 药物的性味归经、功效主治与用法用量，以《中华人民共和国药典》及全国中医药行业高等中医药院校规划教材《中药学》《方剂学》《中医内科学》《针灸学》的通行表述为参照；体质分类采用中国中医科学院王琦团队提出的九种体质分类法；二十四节气的物候与养生要点参考《素问·四气调神大论》等经典论述并结合现代气候特点。"},{"type":"table","caption":"主要参考文献","head":["类别","书名 / 名称","说明"],"rows":[["基础理论","《黄帝内经》《难经》","阴阳五行、藏象、经络、诊断与治则的根本经典"],["临床方书","《伤寒论》《金匮要略》《千金要方》","辨证论治体系的奠基之作与唐代临床集成"],["本草药物","《神农本草经》《本草纲目》《药性歌括四百味》","药性理论的本源、药物学巨著与便于记诵的歌括"],["针灸推拿","《针灸大成》《奇经八脉考》《扁鹊心书》","经络腧穴的操作总结与奇经别论"],["养生食疗","《饮膳正要》《食疗本草》","元代饮食宜忌与唐代食疗专论"],["温病与急症","《温病条辨》《肘后备急方》《洗冤集录》","三焦辨证体系、急救手册与早期法医学专书"],["医论医德","《四圣心源》《医学源流论》","清代医论代表作，纵横批驳，医德医风并重"]]}]},{"id":"tech","title":"网站实现说明","subtitle":"内容与样式分离的架构","icon":"⚙️","summary":"本站是一套「静态骨架 + JSON 数据 + 客户端渲染」的极简站点，无框架、无构建依赖，可直接托管于 GitHub Pages。","blocks":[{"type":"paragraph","text":"全部页面共用同一套 HTML 骨架，正文内容来自 <code>data/</code> 目录下的九份 JSON 文件，由 <code>assets/js/app.js</code> 在浏览器端装配渲染。样式集中于 <code>assets/css/theme.css</code>（设计令牌与基础排版）与 <code>assets/css/main.css</code>（布局与组件）两份文件，页面不内联任何样式。"},{"type":"table","caption":"目录职责","head":["路径","职责","是否需要手工编辑"],"rows":[["data/*.json","内容与站点配置的唯一源文件","是（日常维护只改这里）"],["assets/data/tcm-data.js","数据预构建包，供 file:// 直接打开时使用","否，由构建脚本生成"],["assets/js/app.js","渲染引擎与交互逻辑","一般不需要"],["assets/css/theme.css","配色、字体、间距等设计令牌","改主题时编辑"],["assets/css/main.css","布局与组件样式","一般不需要"],["*.html","各页面的静态骨架","新增页面时由脚本生成"]]},{"type":"keypoints","title":"扩展成本","items":["补充一条药材或方剂：编辑对应的 JSON，追加一个对象，刷新页面即可。","新增一个章节：编辑对应 JSON 的 sections 数组，目录导航会自动出现新条目。","新增一个页面：新建 JSON、在 site.json 的 nav 中登记、运行页面生成脚本，三步完成。","更换配色：只改 theme.css 顶部的 CSS 变量，不触碰任何内容文件。"]}]},{"id":"disclaimer","title":"免责声明","subtitle":"使用本站内容前请务必阅读","icon":"⚠️","summary":"以下条款是本站内容的使用前提，请在使用任何方药、针灸、食疗方案前完整阅读。","blocks":[{"type":"callout","variant":"danger","title":"重要提示","text":"本站全部内容仅供传统医学知识学习、学术参考与文化传播之用，**不构成医疗诊断、治疗方案或用药建议**，亦不能替代执业医师的面诊与处方。任何药物剂量、针灸操作、食疗配方的具体应用，均须由具备相应执业资质的医师结合患者年龄、性别、体质、合并症与用药史辨证确定。"},{"type":"list","ordered":true,"items":["含毒性药材条目（附子、马钱子、细辛、乌头、甘遂、大戟、芫花、商陆、鸦胆子、雷公藤、洋金花等）所列用量仅为文献常用范围参考，临床须严格控量并由医师指导，不得自行购买使用。","妊娠期、哺乳期、少年儿童、老年人，以及肝肾功能不全、正在服用抗凝药、降压药、降糖药或免疫抑制剂者，禁用或慎用任何药物与食疗方案，务必先咨询医师。","「十八反」「十九畏」配伍禁忌（如甘草反甘遂、大戟、海藻、芫花；人参反藜芦；硫黄畏朴硝；巴豆畏牵牛；丁香畏郁金；川乌、草乌畏犀角；牙硝畏三棱；官桂畏赤石脂；人参畏五灵脂）已在相关条目中标注，实际配伍须经专业审核。","文中疾病调理内容仅供了解辨证思路，出现高热、意识障碍、胸痛、呼吸困难、大出血、剧烈头痛、持续呕吐腹泻等红旗征象时，请立即就医，切勿延误。","引用古籍原文时可能存在版本差异，不同版本用字略有出入，本站已在必要处注明版本与出处，读者引用时请以所据版本为准。","本站不承担因使用者自行依据本站内容诊治而产生的任何责任；内容如有疏漏，欢迎指正。"]},{"type":"callout","variant":"warning","title":"许可与来源","text":"本站引用的古籍正文均为公有领域文献；现代教材部分为版权保护内容，本站仅作要点式转述并标注出处，不作全文转载。若您为相关内容的权利人并认为本站的使用方式不妥，可通过仓库 Issue 与我们联系，我们会及时调整或下线相关内容。"}]}]}},"stats":{"generatedAt":"2026-11-06T03:10:47.785Z","totals":{"entries":237,"chars":486727},"boards":{"theory":{"count":11,"raw":11,"unit":"章","type":"section"},"classics":{"count":19,"raw":19,"unit":"部","type":"collection"},"herbs":{"count":60,"raw":60,"unit":"味","type":"collection"},"formulas":{"count":36,"raw":36,"unit":"首","type":"collection"},"acupuncture":{"count":8,"raw":8,"unit":"章","type":"section"},"diet":{"count":36,"raw":36,"unit":"道","type":"collection"},"solar":{"count":24,"raw":24,"unit":"节","type":"section"},"constitution":{"count":9,"raw":10,"unit":"种","type":"section"},"diseases":{"count":28,"raw":28,"unit":"病","type":"collection"},"about":{"count":5,"raw":5,"unit":"章","type":"section"}}}};
